Object.assign(window.__TXT,{"15000": "左。瘰疬破溃，脉至弦数，面色㿠白，大便溏薄，此系疬劳，最难图治。拟香贝养营汤以培根本。", "15001": "（案8）缪，左。疽生于项，硬如顽石，右脉细弦，色紫，时穿矣。此属气血凝滞。溃后得脓则吉，出血出水则凶。", "15002": "（案9）邹，孩。论其面色淡黄、纳食呕吐，似宜甘温补气，芳香悦脾。如论其颈上两旁瘰疬硬而无情，此由肝血枯槁。脉见细数、久热不已，又当壮水涵木以制阳光。", "15003": "（案12）龚，右。肝无血养，木火上炎，痰凝结疬，脉至细数。此属虚症，切勿攻消为事。", "15004": "（案15）唐，右。疽生于项，硬如岩石，此系郁结痰滞，肝无血养，脉所以左关独见弦滑而有时歇止也。", "15005": "（案17）顾，左。颈侧结核，木硬无情，脉至左弦带数，此肝无血养，木火上炽，挟痰凝结，非急切可愈。", "15006": "（案18）方，右。六脉细涩，面淡黄而舌白，经事愆期，纳谷甚少。先从肩上少阳之经累累结核，渐延颈项，背足俱满。初肿则按之酸痛，溃破则腐且见骨，此由营阴本亏，加以情不能畅舒，遏壅荣行之度而结痰疬。形伤及气，阴阳两阻，故蔓延上下也。用加味归脾法增损图治。", "15007": "（案19）郑，左。素有失血，脉细数，今颈侧两旁生疬不一，虽有客邪，攻消升散之剂在所宜慎。", "15008": "（案27）童，儿。喜豆后余邪未清，耳后项上发出一块，肿而不红，脉不数，舌不厚，神情清爽，乃属气不宣达，挟外邪所致。宜疏散。", "15009": "（案29）曹，左。左三部脉细如丝、右寸关弦滑；颐颔之左结块如桃，不红不肿，此属虚痰。不可专用攻坚克伐之品。用拟金水六君加理气行痰为治。非比实症可以速效，还宜休养为嘱。", "15010": "复诊胃口虽能多进薄粥，大便亦能坚固，脉亦不是前之细数无根，而颔颐之下结块已消。在不明医理者，似如日有起色，殊不知吸吸气短，乃源海无根，非比肺家实喘，往往有顷刻变生脱绝者，况无大剂人参在此急救，焉能挽回元气于无何有之乡？勉商观音梦授散合参麦散以纳在上之虚气，都气丸作汤以摄在下之脱气。倘或应手，还有可生之机。否则别无良法。", "15011": "（案30）辛，左。脉见细数，著手即空，右更无力，内热不已，肝肾阴亏，无形之火上升，有形之痰凝聚，颈侧两旁结块累累，按之无情，乃虚痰也。非实症可比可用攻消，且拟育阴制阳养营软坚一方，投后，以观效否，再酌。但体虚症重，急宜静养，课读且停，切嘱切嘱。", "15012": "复诊自投育阴制阳、养营软坚法，热势难减，胃口略起，颈侧疬块亦稍平。方非不对，惟左三部脉象仍如前细数，右三部未见有力，不特阴亏，气分当急为培补。所谓阴根于阳，阳根于阴也。且补阴，阴不能骤生；补气，则无形能生有形。但炎热之令将至，阴亏气弱之体须要极其小心调养。炎威固不可受，风寒亦不可感。至于饮食，一切腥腻生冷、面食、发物，切勿入口。因体极易受邪，为此叮咛告戒。如不遵守，往往变生。慎之慎之，原方去当归、石决明。", "15013": "（案31）杨。素质阴亏，兼之课读耗气，而颈侧结核有红仁。脉至左三部细数，寸尤甚；右三部细软。显系气分有亏，肝肾之阴不足，虚阳上炽，痰为凝结血分是也。", "15014": "（案1）虞，右。脉至左关独见弦细，左肩内侧痛，而不能屈伸如意，此肝血不荣于筋也。更兼外寒侵袭于络，法当温通活血。", "15015": "（案1）陈，左。舌苔滑白，脉至迟软，肩臂酸麻，犹有湿痰不清。", "15016": "（案4）高，左。毒发于手腕内侧，或触虫毒所致，脉有力有神。拟仙方活命饮加减。", "15017": "（案9）秦，右。指麻固是气虚，而精神脉象不见衰弱，放心可也。", "15018": "（案11）过，左。经云：掌得血而能握。今指屈而难伸，此血虚不荣于脉络。但补血血不能骤生，还当先补气。所谓无形者能生有形也。然绝欲为嘱。", "15019": "复诊坚如顽石，硬如牛领，大若覆碗，踞于中脘期门之间。脉至沉细，纳谷日减。此纯乎寒气痰积闭结，非但难消，成功不易，倘若溃脓，有性命之忧。商以回阳三建汤以冀得温则化，然亦只可希图万一。", "15020": "（案1）左。脉至左弦右弱，脐左寸许有块，硬而似痂，此处并非结痂地位，乃是肝血不足，筋不柔和，似块非块，攻散消破，断断不宜。", "15021": "（案2）右。筋无血养，气不流行，少腹结块，痛连腿膝，不能屈伸。六脉细弱如无，此宜温培气血。", "15022": "（案3）右。块大，周围径尺，不在皮肤，亦不在肉。虽不著骨而附于筋，所以痛则牵连络脉，后连腰脊，下连于腿，无处不痛。症属阴经之阴症，所以朝轻暮重，蒂固根深，消之甚难。成功亦不易，议与血气兼培之中加宣络行血，血瘀理气消坚一法。", "15023": "（案5）某。腹皮痈块大如盘，色白，板硬，脉至左三部迟滞，此寒积夹瘀所成。", "15024": "（案1）史，右。爪枯为血虚，畏风为气虚。腋下生痰，脉见左寸关滑数甚于别部。脉症合参，良由肝肾之阴亏于下。阴亏则阳浮于上，火动风生，风动痰生，此症之由来也。壮水涵木，制阳熄风，不治痰正所以治痰也。", "15025": "（案2）苏，右。腋疽溃而不敛，由来已久，脉至软弱，气血亏矣。", "15026": "（案4）左。穿胛腋疽生于右半，漫肿色白，痛连胸背。脉至浮数，左关为甚；右脉涩滞。增寒壮热，此系努力伤筋，血凝气滞，更兼重感风寒。肝郁不舒，邪袭太阳、少阳、阳明以致内外并发重症也。为日已多，难于消散，论脉论症，理当疏托兼施。受病夹杂，方亦不能简净。病势方张，素体虚弱，正多变迁，饮食起居不可不小心调养，还须耐烦。倘能根束顶高，毒聚得脓，则吉。", "15027": "又：大脓已得，六脉细弱，气血俱亏，纯乎虚象，法当气血兼顾，加重补脾醒胃之品投之。但饮食寒暖要极其小心，否则虚人多变。", "15028": "（案1）宜兴。蜂窝搭手偏于背之右半，肿而不高，束而未束，次系外症之重阴者，急宜托解以防内陷。况脉至无力，气血本不充足，极要小心，不得泛视。", "15029": "（案2）严庄。背右太少两经交会之处患疡，大小不一，色白漫肿而硬。一为少气之腑，一为少血之腑。痰注寒凝，气血因之不宣，脉亦为滞迟。法宜温通化坚、和卫养营。", "15030": "（案8）吕，右。背疽黑陷，六脉俱伏。常城内外之医俱曰不治。来质于余。余细细参之。疮而至黑，黑而至陷，陷而至于脉无。即当神不安宁，非昏即愦矣。而语言如前，气爽神倦，此非虚也，亦非陷也。及省其大便，已十余日不解；问其饮食，虽不能如未病之时，而减亦无几。及看其所服之方，用人参、附子者不少。余曰：此非虚而邪陷，乃毒闭而火结也。半由医药所致，以热济热，火上添油也。经所谓不焦而枯，所以黑也。闭结则脉络不通，所以脉伏而便闭也。法当清解透达，所谓火郁则发之。", "15031": "上方服至三剂，而口舌糜烂，可畏，六脉洪大，疮形高，黑色转红而痛矣。伊胞弟同来，见而畏之。余曰：此毒火外达，是吉兆也。从此加紧赶服清解之品可以而愈，以后芦根常用之一斤，捣汁冲服，石膏常用一两，银花常用二两，洋参常用一两，其余不过见症加减。重托清解服至四十剂，而腐脱新生。改用清补，又三十剂而收功。", "15032": "（案9）程，左。背疽偏于左半，色暗而紫，顶平根散。疮形大有尺许，头面数十孔如椒眼，无脓而流血，色暗，神情委软，六脉虚软。饮食减少，唇舌色淡，此气弱血虚、脾胃两伤，阳衰之症。非大加温补不可。", "15033": "（案14）徐，左。悒郁恚怒，气滞血凝，毒发肝肾。顶平色紫，头多如蜂窝，散漫不束，病属重险。脉至左弱右弦，正虚邪盛，调治失宜，极易变陷。此时势若燎原，急当大剂托解。十日内顶高根聚，半月后腐脱脓多，乃是佳兆。凡寒暖气恼，急宜自慎，切嘱切嘱。", "15034": "（案15）陆，左。毒发肝肾，透于太阳。色紫，顶平，根不收束脉至细弱无根。转侧不能轻便。腐而不化，按之板硬。毒盛正虚，凶多吉少。凡实症，可攻，可散，可清，可消，至于虚症，能护托于十日之前，收功者多。及其毒势散漫，虽托亦无及矣。坐视不援，固非仁者之心，然马到临崖，收缰惟恐已晚。勉方以应主人之命，自问学浅，不胜重任，还祈速请高明诊治。", "15035": "又：昨投大剂护托透解之法，色转红活，略能高耸，根亦稍聚，脉数亦稍减，舌苔亦稍净，惟胸腹满闷如前，按之中空，此气火毒邪盘踞于中。所云：实者可攻可逐，虚者只可托解。邪正本不两立：正虚则邪进，正旺则邪退。内外一理，并非臆说。昔贤云：脉虚正虚，首尾必行补法。又曰：半月之后，脓少不腐、顶不高跟不束者，乃极虚之症，治当大补，得全收敛之功，岂狂语乎？余非好奇好异，更，读古人之书不敢不遵古人之训。仍用前法。", "15036": "（案1）汪，左。中石疽，覆大如碗，顽硬如岩，脉至左关弦大而滑，此属木郁痰凝。如能化脓则吉，否则，服药不易见功。", "15037": "（案4）吴，左。腰脊两旁板硬无情，脉至沉迟，此寒痰湿浊滞于足太阳。膀胱为寒水之府，宜温通则化。", "15038": "（案2）右。月前产后恶露不清，少腹之左先攻撑作痛，今结块拒按，左足屈伸不利，身热，脉数，势欲成痈，症非轻浅。", "15039": "（案5）余，童。童儿腹中不适，似有横梗。按之不痛，脉来细弦，乃气血不和之故也。延久虑成肚痈。", "15040": "（案1）左。手麻足痛，脉至细弱，气虚血弱之故。", "15041": "（案2）秦，左。表有风寒，里有湿浊，少腹之左近阴器囊处结块，作痛连腰。发热，脉数，恐成外疡。", "15042": "又：血疝半在少腹，入阴囊通连腰。为日已多，难行消散，势在成痈。今脉至弦洪而大、右关尺更甚，舌苔黄厚，显系下注厥阴而兼肝郁气滞，瘀凝所结。商以疏托兼施。所嫌向来多病，年及五旬，气血不亏而亏，成痈出脓正多时日。非细事也。倘调理不善，变幻正多，不可不极其小心。", "15043": "（案5）右。脉至沉而有力，湿热下注肝肾。", "15044": "（案5）吴，左。湿热下注肛门，结痈成漏，半由攻伐伤气，半由湿浊不清。今脉象软弱，气血不可不补，还宜渗湿之品。但至阴之下药不易到，须耐心调养方能痊愈。", "15045": "（案7）王，左。素体薄弱，患疡不敛而成管漏。脓水交流以致气血愈伤。今神情委顿，六脉细数，饮食减少，内热不已，势非浅轻。用拟言，法以滋化源，以培根本。倘脉数减、饮食增，乃是转机，此时正在凶险，无晦理及外疡。", "15046": "（案12）王，左。尻骨之下为尾闾，患疡不敛。周身之气血，督脉一亏，无不亏矣。药不过树皮草根，焉能挽回气血，已坏之后，且用十全大补合龟鹿以固任督。如有效还可著手，否则甚难。加银花、杜仲。", "15047": "复诊腿面阳明部位结疽，色白木硬，此系寒痰。经云：先肿而后胀者，寒伤形也。脉至软弱。主以香贝温散。方失。", "15048": "（案3）高，右。痈结三阴，业已自溃，色带紫暗，此肝肾营阴不足，湿火下注，凝聚而成。脉象虽虚，幸有根有神、不弦不数。能人事小心，不难就愈。拟托解一法。", "15049": "又：大脓已得，右脉还见数大，补气血之中当佐以凉解。", "15050": "（案6）过，左。腿外侧痛而不肿，脉至左三部弦数，理宜清疏少阳湿热，即是从脉不从症之一法。若因其不红而为寒，便认错矣。", "15051": "腿痛难伸，肌肉日削，脉弱无力，气血有亏，沉寒深入，著骨附筋也。", "15052": "（案9）金，左。环跳痛而足不能伸，病在筋也。所嫌脉数，泄泻，于症不合。且先固正育阴，以观效否，再酌。", "15053": "（案14）王，左。喜按而痛，甚于夜。右腿环跳肿痛，连于内侧跨缝并及委中，屈而难伸。两尺脉来微细。午后日见寒热，舌色苔黄。此肝肾两虚，重寒深湿，著于筋骨，寒欲化火、湿欲化热而成，附骨环跳疽之重恙也。用拟大防风加减治之。", "15054": "（案18）余，左。穿肠腿痈，日久难行消散，近腿缝处隆隆而起。按之微软，内脓已成，所按色脉两虚，且为补托，俟顶起脓足，庶可用刀出脓。", "15055": "又：两膝浮肿，色白而热，脉象带数，此寒化为热、湿化为火，宜温凉并用，气血兼培。", "15056": "（案5）钱，童。温热夹风，流散肤腠，络脉注于节骱两膝。", "15057": "（案2）宣，右。温化热，热化风，遍体肌肤瘙痒，足踝赤烂浸淫。脉见左关尺数而有力。当清解下焦湿热为主，并以疏泄风邪也。", "15058": "（案3）段，左。腿肿，内侧肝经部络脉肿，结聚成块，得刺出血则松，此即血痣，血箭之属。良由血热阻位，络脉不宣。", "15059": "（案2）龚，右。诸节属肝，痛而且肿，脉致弦数，身见发热，此木郁气滞、风旋阳亢。用拟逍遥以舒其郁，加味以清其火。", "15060": "（案4）秦，左。脉至滑数，肌肤疯如血鳞，此血燥有火，宜凉血活血。", "15061": "脉至沉迟细弱，左足难伸，腰间作痛。结块色白不热不红，而疼痛拒按。由来一月，日逐增重，乃寒湿深入肝、肾、膀胱三经，气血因而凝滞，此流注中及重者，邪实正虚，治难速效，药以温通宣络，疏理气血为主。", "15062": "复诊肝主疏泄，胃司二便，筋属肝而骨属肾。今屈伸转不能自如，二便不爽，此系肝肾亏损，寒湿乘虚内袭，更兼挹郁，郁则气滞，以致营卫不行，结成外疡，脉不洪大，舌不焦干而见渴，症属水亏。疏泄消瘀之中宜兼养营育阴之品。", "15063": "（案1）周，右。疔生鼻窍，名曰白刃。唇面肿胀连及左肋，心烦呕恶，六脉洪大。业已走黄，势难挽回。见远途而来，不得不勉为图治，以翼万一也。", "15064": "此两日半共服四贴。肿消势减，顶高根束，热退脉平，已有可生之机。", "15065": "（案2）吴，左。凡痛，总要明虚实寒热，四字做主，再分脏腑经络。虽不中，不远矣。若见症治症，实症则效，虚症无不受伤。至于吾先生之恙，身体薄弱，更兼应减烦劳。所有伏毒脉症并无实象可据，扶正之中稍兼清解，缓缓图痊。", "15066": "（案3）吴，右。无论内外，轻者实者可以正治，重者虚者必须从治，此千古治病之一定方法。惜乎今世不宗，轻者实者多愈重，虚者每每不治。即以此症而论，未尝不可作实症。但脉至数而无力，面色不华，饮食减少，似当培养气血兼理脾胃，佐以化毒清解而不伤正气一法，乃可久投。药力到，血气旺。虽有毒邪，自然尽彻。", "15067": "医之有案，其来远矣。若历代明医史传之所以载其施治之法，神妙之效，皆凿凿可考。至丹溪之朱，樱宁生之滑，其传皆出于名笔，动数千言莫之既，而于病之浅深，治之缓急，功之大小，昭然明甚，思欲起其人而不可得。吾郡祁之汪石山，儒医也。于《素问》则有补注，本草则有类钞，脉诊则有论著，运气则有提纲，外科及针灸等书则又俱有纂述，盖集古今诸名家之所长而为一大成也乎！其从事于医，殆四十余载。凡病家之求治者，因脉制方，随投辄效。从游之士得于目击者，即手录之，以为成法。其邑西石墅陈桷氏，实石山高弟，以其所录者分为三卷，名曰《石山医案》，刻之梓以传。诣予终老楼属序之。夫病之见治于石山也，如饥者得食而充，渴者得饮而解，溺者得援之而登，颠危者得扶持之而安，盖医之王道也。使同生朱、滑之时，其抱负设施，与之同驱并驾，未可必其或后先也。后人视此，不亦犹法家之有断案也哉！引伸触类，延惠无穷，其为慈孝之助多矣！石山之传，撰于镜山，其未及载者，赖此以传，岂非后人之幸欤！石山名机，字省之，石山其号也。庸僭序之，以谂观者如此。", "15068": "丹溪论阳有余阴不足，乃据理论人之禀赋也。盖天之日为阳，月为阴。人禀日之阳为身之阳而日不亏，禀月之阴为身之阴而月常缺。可见人身气常有余，血常不足矣。故女人必须积养十四五年，血方足而经行，仅及三十余年，血便衰而经断，阴之不足固可验矣。丹溪揭出而特论之，无非戒人保守阴气，不可妄耗损也。以人生天地间，营营于物，役役于事，未免久行伤筋，久立伤骨，久坐伤肾，久视伤神，久思伤意。凡此数伤，皆伤阴也。以难成易亏之阴，而日犯此数伤，欲其不夭枉也难矣。此丹溪所以立论垂戒于后也，非论治阴虚之病也。若遇有病气虚则补气，血虚则补血，未尝专主阴虚而论治。且治产后的属阴虚，丹溪则曰：「右脉不足，补气药多于补血药；左脉不足，补血药多于补气药」，丹溪固不专主于血矣。何世人昧此，多以阴常不足之说横于胸中，凡百诸病，一切主于阴虚，而于甘温助阳之药一毫不敢轻用，岂理也哉？虽然，丹溪谓气病补血，虽不中亦无害也；血病补气，则血愈虚散，是谓诛罚无过。此指辛热燥烈之剂而言，亦将以戒人用药，宁可失于不及，不可失于太过。盖血药属阴而柔，气药属阳而刚，苟或认病不真，宁可药用柔和，不可过于刚烈也。《书》曰「罪疑惟轻，功疑惟重」、本草曰「与其毒也宁善，与其多也宁少」之意，正相合也。虽然，血虚补气固为有害，气虚补血亦不可谓无害。吾见胃虚气弱，不能运行，血越上窍者，多用四物汤凉血之药，反致胸腹痞闷，饮食少进，上吐下泻，气喘呕血，去死不远，岂可谓无害耶？是以医者贵乎识病真耳。", "15069": "或问：丹溪曰「人身之虚，皆阳虚也。若果阳虚，则暴绝死矣」，是阳无益于补也；又曰「气无补法，世俗之言也。气虚不补，何由而行」，是气又待于补也，何言之皆背戾耶？予曰：经云「卫气者，水谷之悍气也，慓疾不受诸邪，此则阳常有余，无益于补者也。朱子曰「天之阳气，健行不息，故阁得地在中间，一息或停，地即陷矣」，与丹溪所谓阳虚则暴绝同一意也，此固然矣。使阴气若虚，则阳亦无所依附而飞越矣。故曰天依形，地附气。丹溪曰「阴先虚，而阳暴绝」，是知阳亦赖阴而有所依附也。此丹溪所以拳拳于补阴也。经曰「营气者，水谷之精气，入于脉内，与息数呼吸应」，此即所谓阴气不能无盈虚也，不能不待于补也，分而言之，卫气为阳，营气为阴。合而言之，营阴而不禀卫之阳，莫能营昼夜利关节矣。古人于营字下加一气字，可见卫固阳也，营亦阳也。故曰血之与气，异名而同类。补阳者，补营之阳；补阴者，补营之阴。又况各经分受，有气多血少者，有血多气少者。倘或为邪所中，而无损益，则藏府不平矣。此《内经》所以作，而医道所以兴也。譬如天之日月，皆在大气之中。分而言之，日为阳，月为阴。合而言之，月虽阴，而不禀日之阳，则不能光照而运行矣。故古人于阴字下加一气字，可见阳固此气，阴亦此气也。故曰阴中有阳，阳中有阴，阴阳同一气也，周子曰「阴阳一太极」是也。然此气有亏有盈，如月有圆有缺也。圣人裁成辅相，即医家用药损益之义也。是知人参黄耆补气，亦补营之气，补营之气即补营也，补营即补阴也，可见人身之虚皆阴虚也。经曰「阴不足者，补之以味」，参耆味甘，甘能生血，非补阴而何？又曰「阳不足者，温之以气」，参耆气温，又能补阳，故仲景曰气虚血弱，以人参补之，可见参耆不惟补阳，而亦补阴。东垣曰血脱益气，仲景曰阳生阴长，义本诸此。世谓参耆补阳不补阴，特未之考耳。", "15070": "然生侍侧有日，聆诲已久，因而察其受病之源，详其致病之因，不过心过于劳而已。何则？心为血主，而血又所以养心。血属阴而主静，惟静则可以生水，故曰静则生阴是也。苟或心过于劳，则主动而属阳矣。阳则火之象也，故曰动则生阳。丹溪亦曰诸动属火。动极火炽，阳亢阴微，血愈亏损，而心失所养矣。是以睡卧不宁，夜梦纷纭，职皆由于此也。经云主闭藏者，肾也。肾主相火，上系于心。心既动劳，则相火随起，而热则流通矣。是以闭藏之肾，反暗流疏泻，而梦遗精滑之疾有所不能免矣。医书所谓情动于中，精淫于外是也。经云东方实，西方虚。心劳火动，则西方之金愈虚，而东方之木愈实。脾土得不为之伤乎？脾土既伤，是以上或为呕，下或为泻，中或为畏食之病，莫不层出而叠见矣。由是探本索元，其初固在于心，而支流余裔，不免延及它藏，而亦有所损也。又尝参之以脉。夫左寸，心脉所出也。或时而浮洪，或时而敛小，盖由心之劳逸不常，以致脉之大小无定。劳则心动而火炽，故脉为之浮洪而躁扰。逸则心安而气和，故脉为之敛小而恬静。所可喜者，肝肾二脉静而有常，久而不变，是知相火虽或有时而动，而势未致于燎原也。故今病未即瘳而终有可瘳之理，邪未即伏而终有可伏之机，尚复何虑之有？右手三部，肺、脾、命脉之所出也。亦或浮而稍洪，又或小而稍弱，良由火来侮肺，又乘于脾，遂延及命门，以致然耳。故曰火性躁扰强越，其燔灼之祸，无不著于物也。或时小而稍弱者，盖府藏之阴血阳气，未免为火暗伤而阴损。故火旺之时，脉来浮洪，而独见火象。及火静之后，则邪伏而虚见矣。脉之小而弱者，宁不基于此乎？", "15071": "生于是察其脉，切其病，反复精思，参互考证。所治之方，无出于八物汤之外也。或者专主四物滋阴，加黄柏、知母、玄参、生地之属以降火，此固一说也。未免寒伤胃气，而呕泻畏食之病莫能去矣。或者专主四君子以养阳，加温暖、消导、燥热之剂以助胃，此亦一理也。未免阳刚伤阴，而夜梦遗精之患不能除矣。求其万举万全，而无一偏之害者，还当以八物为主。一则可以养阴，而心火不致于太炽；一则可以养阳，而脾土不致于太伤。其他清金降火、安神固肾之药，又当因时月之宜，酌病之轻重，更相出入，递为佐使，庶得变通之妙。而免执中无权之诮矣。守此以治，而谓病之不痊，吾未之信也。", "15072": "此项数病，皆生于心。何则？心主血脉，心血一亏，则阳热随起，故夜卧不宁、唇舌焦燥、黑胎之病，层出而叠见矣。且舌乃心之苗。心火亢极，故舌生黑胎。静养二三日而始退者，盖静养则阴生，阴生则阳伏矣。周子所以定之以中正仁义而主静者，良以此也。降火去胎、润唇滋燥之药，恐无出于四物，再加麦门冬、五味、黄柏、知母之属。", "15073": "一人年弱冠时，房劳后忽洒洒恶寒，自汗发热，头背胃脘皆痛，唇赤、舌强、呕吐，眼胞青色。医投补中益气，午后谵语，恶热，小便长。初日脉皆细弱而数，次日脉则浮弦而数，医以手按脐下痛。议欲下之，遣书来问。", "15074": "邑人汪大尹，年几七十。形色苍白，劳倦病疟。疟止，胸膈痞闷，心恶痰多，不思饮食，懒倦，口苦头痛，夜梦纷纭，两腿时痒。予为诊之，脉皆浮濡无力，且过于缓。", "15075": "医书云，脉缓无力者，气虚也。又云，劳则气耗。又云，劳倦伤脾。脾伤不能运化精微以养心，故心神为之不安，宜仿归脾汤例治之。人参二钱，麦门冬、白术各一钱，归身、酸枣仁、茯神各八分，黄芩、陈皮各六分，枳实、甘草各五分，川芎七分，煎服二帖，夜卧颇安。但药后觉嘈，食则吞酸口淡。减去枳实，加山楂七分、吴茱萸二分服之，仍用参、术、归、芎、山栀、山楂，丸服而愈。", "15076": "一人年逾四十，形瘦色紫淡，素劳伤脾。予令常服参苓白术散获安。住药一年，复劳饮冷酒不爽，是夜头又被湿，遂致身冷不安，早起面目俱黄。医用零筋草根酒煎服之，吐泻大作。又加姜煎，则心热膈壅，不进饮食，大便秘结，疟作，胸膈痞塞，粥饮不入，食此汤则嗳此气，呕逆吐涎，意向甚恶。予诊左脉浮濡无力，肝脉颇弦，右脉肺部濡散，脾部浮微，二部脉皆似有似无，或呼吸相引，又觉应指。", "15077": "一人年逾四十，不肥不瘦，形色苍白，季秋久疟，医用丹剂一丸止之，呕吐不休，粒米不入，大便或泻，面赤，妄语，身热。予诊脉皆浮而欲绝。", "15078": "仲景云阳病得阴脉者死。今面赤、身热、妄语，其症属阳；而脉微欲绝，则阴脉矣，此一危也。经曰得谷者昌，失谷者亡。今粒米不入，此二危也。又曰泄而热不去者死。今数泄泻，而面赤、身热不除，此三危也。以理论之，法在不治。古人云治而不愈者有也，未有不治而愈者也。令用人参五钱，白术二钱，御米一钱，橘红八分，煎服四帖，渐有生意。", "15079": "一人年近三十，形瘦淡紫，八月间病疟。予诊之，左脉颇和而驶，右脉弱而无力。令用清暑益气汤加减。服之觉胸膈痞闷，遂畏人参，更医作疟治。而疟或进或退，服截药病稍增。延至十月，复邀予诊。脉皆浮小而濡带数，右则尤近不足。", "15080": "一人年逾三十，形瘦色苍，八月间病疟。或用截药，或用符水，延缠不愈，胸膈痞满，饮食少进，大肠痔血，小便短赤，疟发于夜，寒少热多，自汗。予诊左脉濡小而缓，右脉濡弱无力。", "15081": "一妇面色淡紫，年逾四十，九月病疟。夜发渴多汗，呕吐，粒食不进数日。予诊脉皆浮濡而缓，按之无力。", "15082": "遂用人参五钱，橘红八分，甘草七分，白术一钱，煎服十余帖，疟止食进，渐有生意，但大便二十日不通。再诊，右脉浮小无力，左脉沉弱无力。前方加归身一钱，火麻仁钱半，如旧煎服，病除。", "15083": "一妇年逾三十，瘦长淡紫，六月产，八月疟。疟止胸膈痞闷，才劳气喘咳血，身热脚冷。予诊左脉濡弱，右脉肺部颇洪，关尺二部亦弱。", "15084": "一人年三十，形色苍白，因劳感热，九月尽病疟。头痛，口渴，呕吐，胸膈痞塞，不进饮食，自汗倦怠，热多寒少。医用截药，病增。过饮水，吐甚。予诊脉皆浮大而濡，颇弦。", "15085": "一人年三十，久疟。医用补中益气汤，或止或作，延及半年，因解发结，劳伤咳嗽。医用前方加半夏、五味，遂致喉痛声哑，夜不能寝。邀予视之，右脉浮濡，左脉小弱。", "15086": "一人年三十余，形瘦淡紫，素劳久疟，三日一发，于夜呕吐，热多寒少，不进饮食，小便频数，气喘咳嗽，日夜打坐，不能伏枕几月矣，头身骨节皆痛。医作疟治，病甚，众皆危之。脉皆浮虚缓弱而不甚大。", "15087": "一妇形色脆白，年五十余，忧劳，六月背疮。艾灸百余壮，疮散病疟。身热，自汗，口渴，头晕，呕吐，泄泻，不进饮食，寒少热多。自用清暑益气汤，病甚。予诊左脉浮微，似有似无，右脉浮小，按之不足。", "15088": "一人于嘉靖九年因冒风病疟。热多寒少，头痛倦怠，食少自汗，已服参苏饮一帖。予适在彼，诊之，脉皆浮虚近驶。", "15089": "一妇常患咳嗽，加以疟疾，因仍左胁有块。疟止有孕，嗽尚不宁，咳干痰少，或时呕出顽痰钟许方止，夜亦如是，常觉热盛，胸膈壅满，背心亦胀，常要打摩。妊已六月。夜半如厕，身忽寒战厚覆，少顷乃愈。越二日，夜半又发，寒热如疟，肢节痛，上身微汗，口中觉吐冷气，胸喉如有物碍，心前虚肿，按之即痛，头痛气喘，坐卧不宁。医作伤寒发散，又作痰症而用二陈，不效。予往视之，脉皆濡而近滑。", "15090": "一人形瘦色脆，年几三十。正德十年四月腹痛，惟觉气转左边，五日而止。次年四月亦然。八月病疟，间日一发，寒少热多，十余日止。第三年四月八月如旧，腹痛疟作。四年五年四月八月亦然，但疟作腹痛，疟止痛止。旬余疟除，又泻痢十余日。泻止疟又作，但不腹痛，五日疟瘥。仲冬感寒，头痛发热，腹及右胁胀痛，气喘溏泻，内黑外红，日夜五六次，内热不减，饮食难进。医用三乙承气汤三帖，继用木香枳术丸，诸症稍定。午后内热愈炽，遇食愈胀，得泻略宽，头痛不减。诣予诊治，脉皆浮濡近驶。", "15091": "一人形瘦色脆，年三十余。八月因劳病疟。寒少热多，自汗体倦，头痛胸痞，略咳而渴，恶食，大便或秘或溏，发于寅申巳亥夜。医议欲从丹溪，用血药引出阳分之例治之。予诊其脉，濡弱近驶稍弦。", "15092": "曰：察形观色参脉，乃属气血两虚，疟已深入厥阴矣。专用血药，不免损胃又损肺也。淹延岁月，久疟成痨，何也？自汗嗽渴，而苍术、白芷岂宜例用？恶食胸痞，而血药岂能独理？古人用药立例，指引迷途耳。因例达变，在后人推广之也。遂以补中益气汤，加川芎、黄柏、枳实、神曲、麦门冬，倍用参、耆、术。煎服三十余帖，诸症稍除，疟犹未止。乃语之曰：今当冬气沉潜，疟气亦因之以沉潜，难使浮达，况汗孔亦因以闭塞。经曰疟以汗解。当此闭藏之时，安得违天时以汗之乎？且以参、术、枳实、陈皮、归身、黄芩丸服。胃气既壮，来年二月，疟当随其春气而发泄矣。果如期而安。", "15093": "一人年三十，形色颇实。初因舟行过劳受热，咳嗽不已，续又病疟，素有热淋。求医服药，或作或辍。回家，予为诊之。脉皆濡弱近缓，左尺略驶。", "15094": "一人年三十，六月因劳取凉，梦遗，遂觉恶寒，连日惨惨而不爽，三日后头痛躁闷。家人诊之，惊曰脉绝矣。议作阴症，欲进附子汤。未决，邀予往治。", "15095": "曰：阴症无头痛。今病如是，恐风暑乘虚入于阴分，故脉伏耳，非脉绝也。若进附子汤，是以火济火，安能复生？姑待以观其变，然后议药。次日，未末申初果病。寒少热多，头痛躁渴，痞闷呕食，自汗，大便或泻或结，脉皆濡小而驶，脾部兼弦。此非寻常驱疟燥烈劫剂所能治。遂用清暑益气汤减苍术、升麻，加柴胡、知母、厚朴、川芎，以人参加作二钱，黄耆钱半，白术、当归各一钱，煎服二十余帖而愈。", "15096": "本县二尹大人，北人，形长魁伟，年逾四十。六月，舟中受热，病疟。寒少热多，头痛躁渴汗多，医用七保饮治之，不愈。予诊其脉浮濡而驶略弦。", "15097": "侍御程公，形色清脆，年逾四十，素善饮，形色苍热。病头痛，恶食泄泻，小便短少，午后恶寒发热。医用二陈、平胃、五苓共一服，治不退，反增腰腹拘急。邀予诊视。脉皆濡弱颇弦而驶。", "15098": "一人年三十余，八月因劳病疟。诣予诊治。脉皆六至而数无力。", "15099": "曰：古人云形瘦色黑者，气实血虚也。又云脉数无力者，血虚也。间日发于午后，亦血分病也。以色脉论之，当从血治。但今汗多，乃阳虚表失所卫；消谷善饥，乃胃虚火乘其土，皆阳虚也。仲景法有凭症不凭脉者，兹当凭症作阳虚治。以参、耆各三钱，白术、白芍、麦门冬各一钱，归身、生地、甘草各七分，黄柏、知母、陈皮各五分，煎服二十余帖而安。若用寻常驱疟劫剂，宁免后难？", "15100": "予年逾六十，形质近弱。八九月酷热时，往来休歙，外有药剂之劳，内有病者之忧，内外弗宁，昼夜不静。至十月初旬，疟作三日，午后一发，寒不甚寒，热不甚热，喜热恶寒，寒去热来则爽快矣。口干微渴，临发昏倦嗜卧。左脉沉小而数，右脉浮濡无力，亦近于数，独脾部弦而颇洪，疟去则脉大小浮沉相等，惟觉缓弱而已。", "15101": "一人瘦长脆白，年三十余。久疟后盗汗自汗过多，加以伤食，吐泻大作，吐止而泻，四日不住，筋惕肉𥆧，惊悸梦遗，小便不禁。予诊脉皆缓弱，右略弦而涩。", "15102": "予曰：须不见脉见症，必是禀赋素弱，不耐饥寒，宜作饮食劳倦为主，而感冒一节，且置诸度外。夫气升胀闷触痛者，脾虚不能健运，以致气郁而然。胸膈漉漉水声，谓之留饮。乃用独参汤补养其气血，加姜以安其呕吐，黄柏以降其逆气。初服三帖，脐左痛除，吐止。将人参加作一两，吐又复作。此由补塞太过，而无行散佐使故也。人参减作七钱，附五分，炮姜七分，半夏八分，苍术七分，厚朴七分，茯苓一钱。服至二十余帖，吐止食进，余病皆减，颇喜肉味。以手揉擦其肚，尚有水声汩汩。微感寒，腹中气犹微动，或时鼻衄数点。近来忽泻，二日而自止。才住前药，又觉不爽。前方加黄耆四钱，山栀七分，减黄柏，如旧煎服。", "15103": "一人形近肥而脆，年三十余，内有宠妻。三月间，因劳感热，鼻衄。久而流涕不休，臭秽难近，渐至目昏耳重，食少体倦。医用四物凉血，或用参耆补气，罔有效者。邀予诊视，脉皆浮濡而滑，按之无力。", "15104": "一妇年逾五十，病痢半载余。医用四物凉血之剂及香连丸，愈增。胃脘腹中痛甚，里急后重，下痢频并嗳气，亦或咳嗽，遍身烦热。予为诊之，脉皆细弱而数。", "15105": "一人八月病滞下，医用调胃承气、大承气汤下之不利，邀予视之。面色萎黄，食少无味，大便不通，惟后重甚痛，脉皆细弱近滑，右脉觉弱。", "15106": "予兄年逾六十，苍古素健。九月患滞，予适出外，自用利药三帖，病减。延至十月，后重未除，滞下未止。诊之，脉皆濡散颇缓。", "15107": "予婿王琇，客扬州，病胁痛。医以为虚，用人参、羊肉补之，其痛愈甚。镇江钱医治以龙荟丸，痛减。予闻，冒雪自芜湖徒行至彼。诊之，脉皆弦濡而弱。", "15108": "越五年，腹胁复痛。彼思颇类前病，欲服龙荟丸，未决。予又冲寒陆路至彼，遂亲扶持，不成寐者数晚，诊之脉皆濡弱而缓。", "15109": "又，后十余年，来贺余寿，病滞下，腹痛后重，日夜四五十行。诊之，脉皆濡弱近驶。", "15110": "黟县丞，年逾五十，京回，两胁肋痛。医用小柴胡汤，痛止。续后复痛，前方不效，请予往治。脉皆弦细而濡，按之不足。", "15111": "一人年逾四十，春间患胀。医用胃苓汤及雄黄敷贴法，不效。邀予诊视，脉皆缓弱无力。", "15112": "曰：「此气虚中满也，曾通利否？」曰：「已下五六次矣。」予曰：「病属气虚，医反下之，下多亡阴，是谓诛罚无过也。故脉缓，知其气虚；重按则无，知其阴亡。阳虚阴亡，药难倚仗。八月水土败时，实可忧也。」乃问予曰：「今不与药，病不起耶？尝闻胀病脐突不治，肚上青筋不治，吾今无是二者。」予白：「然也。但久伤于药，故且停服。」明日遂归，如期果卒。", "15113": "一妇形瘦弱小，脉细濡近驶。又一妇身中材颇肥，脉缓弱无力。俱病鼓胀，大如箕，垂如囊，立则垂坠，遮拦两腿，有碍行步，邀予视之。", "15114": "一人年逾四十，瘦长善饮。诊之，脉皆洪滑。", "15115": "曰：可治。《脉诀》云腹胀浮大，是出厄也。但湿热大重，宜远酒色，可保终年。遂以香连丸，今日吞三次，每服七八十丸。月余良愈。", "15116": "一人年三十余，酒色不谨，腹胀如鼓。医用平胃散、广荗溃坚汤不效。予为诊之，脉皆浮濡近驶。", "15117": "一人年逾六十，形瘦苍紫。夜常身痒，搔之热，蒸皮内肉磊如豆粒，痒止热散，肉磊亦消矣。医用乌药顺气、升麻和气等不效。诣予诊之。脉皆细濡近驶。", "15118": "一人年六十逾，色紫。平素过劳好酒，病膈。食至膈不下，就化为脓痰吐出，食肉过宿，吐出尚不化也。初卧则气壅不安，稍久则定。医用五膈宽中散、丁沉透膈汤，或用四物加寒凉之剂，或用二陈加耗消之剂，罔有效者。来就余治。脉皆浮洪弦虚。", "15119": "予曰：此大虚症也。医见此脉，以为热症，而用凉药，则愈助其阴，而伤其阳。若以为痰为气，而用二陈香燥之剂，则愈耗其气，而伤其胃，是以病益甚也。况此病得之酒与劳也。酒性酷烈，耗血耗气，莫此为甚。又加以劳伤其胃，且年逾六十，血气已衰，脉见浮洪弦虚，非吉兆也。宜以人参三钱，白术、归身、麦门冬各一钱，白芍药八分，黄连三分，干姜四分，黄芩五分，陈皮七分，香附六分，煎服五帖，脉敛而膈颇宽，食亦进矣。", "15120": "一人形肥苍白，年五十余，病淋，砂石涩痛。医用五苓或琥珀八正散之类，病益加。邀余往诊。脉皆濡弱而缓近驶。", "15121": "一妇年逾四十，两眼昏昧，咳嗽头痛似鸣，而痛若过饥，恶心。医以眼科治之，病甚。予诊脉皆细弱，脾部尤近弦弱。", "15122": "一人年逾三十。季夏日午，房后多汗，晚浴又近女色，因患白浊。医用胃苓汤，加右眼作痛。用四物汤入三黄服之，睡醒口愈加苦，又加左膝肿痛。仲冬不药浊止。渐次延至背痛，不能转侧，日轻夜重。嚏则如绳束撮，腰胁痛不可忍，呵气亦应背痛。或时梦遗。次年正月请予诊治。脉皆缓弱无力，左脉缓而略滑。", "15123": "一人形长色苍瘦，年逾四十。每遇秋凉，病痰嗽，气喘不能卧，春暖即安，病此十余年矣。医用紫苏、薄荷、荆芥、麻黄等以发表，用桑白皮、石膏、滑石、半夏以疏内，暂虽轻快，不久复作。予为诊之，脉颇洪滑。", "15124": "一妇年逾五十，其形色脆弱。每遇秋冬、痰嗽气喘，自汗体倦，卧不安席，或呕恶心。诊之，脉皆浮缓而濡。", "15125": "次年秋间，滞下，腹痛后重，脉皆濡细稍滑。", "15126": "一妇产后咳嗽痰多，昼轻夜重，不能安寝，饮食无味，或时自汗。医用人参清肺汤，嗽愈甚。予为诊之，脉浮濡近驶。曰：此肺热也。令服保和汤五帖而安。", "15127": "一妇怀妊七月，嗽喘不能伏枕，两臀坐久皮皆溃烂。医用苏子降气汤、三拗汤、参苏饮，罔有效者。邀予诊之。右脉浮濡近驶，按之无力，左脉稍和。", "15128": "一童子八岁，伤寒咳嗽，痰少面赤，日夜不休。丁氏小儿科治以参苏饮，数日嗽甚。予为诊之，脉洪近驶。", "15129": "一妇瘦弱，年四十余。患走气，遍身疼痛，或背胀痛，或两胁抽痛，或一月二三发，发则呕尽所食方快，饮食不进，久伏床枕。医作气治，用流气饮；或作痰治，用丁藿二陈汤，病甚。邀余视之。脉皆细微而数，右脉尤弱。", "15130": "曰：此恐孀居忧思，伤脾而气郁也。理宜补脾散郁。以人参三钱，香附、砂仁、黄芩、甘草各五分，黄耆二钱，归身钱半，川芎八分，干姜四分。煎服十余帖，脉之数而弱者稍缓而健，诸痛亦减。仍服前方，再用人参、黄耆、川芎、香附、山栀、甘草，以神曲糊丸，服之病除。", "15131": "邑庠司训萧先生，年逾五十，形肥色紫。病气从脐下冲逆而上，睡卧不安，饮食少，精神倦。予为诊之，脉皆浮濡而缓。", "15132": "曰：气虚也。问曰：丹溪云气从脐下起者，阴火也。何谓气虚？予曰：难执定论。丹溪又云肥人气虚，脉缓亦气虚。今据形与脉，当作气虚论治。遂以参！耆为君，白术、白芍为臣，归身、熟地为佐，黄柏、甘草、陈皮为使，煎服十余帖，稍安。彼以胸膈不利，陈皮加作七分，气冲上，仍守前方，月余而愈。", "15133": "一妇或时遍身麻痹，则懵不省人事，良久乃苏。医作风治，用乌药顺气散，又用小续命汤，病益甚。邀余诊之，脉皆浮濡缓弱。", "15134": "一妇婺居改嫁，乘轿劳倦，加以忧惧，成婚之际，遂病小腹胀痛，大小便秘结不通。医以硝黄三下之，随通随闭，病增胸膈胃脘胀痛，自汗食少。予为诊之，脉皆濡细近驶，心脉颇大，右脉觉弱。", "15135": "一人年三十余，形瘦神悴，性急作劳，伤于酒色，仲冬吐血二盂盆，腹胀肠鸣，不喜食饮。医作阴虚治，不应。明年春，又作食积治。更灸中脘、章门，复吐血碗许。灸疮不溃，令食鲜鱼，愈觉不爽。下午微发寒热，不知饥饱。予诊其脉，涩细而弱，右脉尤觉弱而似弦。", "15136": "一人年二十余，形瘦色脆，病咳血。医用滋阴降火及清肺之药，延及二年不减。又一医用茯苓补心汤及参苏饮，皆去人参，服之病增。邀予诊之。脉细而数有五至余。", "15137": "曰：不可为也。或曰：《脉诀》云「四至五至，平和之则」，何谓不可为？予曰：经云「五藏已衰，六府已极，九候须调犹死」是也。且视形症，皆属死候。经曰肉脱热甚者死，嗽而加汗者死，嗽而下泄上喘者死。嗽而左不得眠，肝胀右不得眠，肺胀，俱为死症。今皆犯之，虽饮食不为肌肤，去死近矣。越五日，果卒。凡患虚劳，犯前数症，又或嗽而喉痛声哑不能药，或嗽而肛门发瘘，皆在不救，医者不可不知。", "15138": "一人年三十时，过于勤劳，呕血，彼甚忧惶。予为诊之，脉皆缓弱。", "15139": "越十余年，叫号伤气，加以过饱病膈，壅闷有痰，间或咯红噎酸，饮食难化，小便短赤，大便或溏，有时滑泄不止，睡醒口苦，梦多或梦遗。医用胃苓汤，病甚。邀予诊视。脉或前大后小，或驶或缓，或细或大，或弱或弦，并无常度，其细缓弱时常多。", "15140": "曰：五藏皆受气于脾，脾伤食减，五藏俱无所禀矣。故脉之不常，脾之虚也。药用补脾，庶几允当。遂以参、术为君，茯、芍为臣，陈皮、神曲、贝母为佐，甘草、黄柏为使，服之泻止食进。", "15141": "问命脉如何？予曰：孟子云夭寿不贰，修身以俟之，所以立命也。夫寿夭固有定命，而人不可委之于命而不修也。人生于世，如烛在笼、火在灰也。罩以笼，壅以灰，则烛与火可保无虞。人能远色节食，养性存心，使汗不妄泄，精不妄施，数须有修短，而得以终其修短之数；命须有夭速，而得以尽其夭速之期。苟或反是，譬犹烛之彻笼，且置之雨侧，则东流西缺，无复完物。修者短，短者亦不得以终其命矣。譬如火之失灰，且移之风外，左吹右击，无复全体。寿者夭，夭者不得尽其数矣。故曰君子修之吉，小人悖之凶。又曰静者寿，动者夭。又曰自作孽，不可活。又曰祸福无不自己求之者。圣贤叮咛告戒，无非欲人自保其命，不可戕害其命也。脉则气血之征兆，气血和则脉和，气血病则脉病，但可以知其病耳。命则在人，不在于脉也，故曰命在我。", "15142": "一人五十，形色苍白。性急，语不合，则叫号气喊呕吐。一日，左奶下忽一点痛。后又过劳，恼怒，腹中觉有秽气冲上，即嗽极吐。或亦干咳无痰，甚则呕血，时发如疟。或以疟治，或以痰治，或以气治，药皆不效。予往诊之，脉皆浮细，略弦而驶。", "15143": "一人年逾三十，形色清癯，病咳嗽，吐痰或时带红。饮食无味，易感风寒，行步喘促，夜梦纷纭，又有𤻊疝。医用芩连二陈，或用四物降火，或用清肺，初服俱效，久则不应。邀予诊之。脉皆浮濡无力而缓，右手脾部濡弱颇弦。", "15144": "旸源谢大尹，年四十时，房劳，病咳血，头眩脚弱，口气梦遗，或时如冷水滴于身者数点，诣予诊视。脉皆濡缓而弱，独左关沉微，按之不应。", "15145": "曰：此气虚也。彼谓房劳咳血梦遗皆血病也，左关沉微亦主血病，且闻肥人白人病多气虚，今我形色苍紫，何谓气虚？予曰：初病伤肾。经云肾乃胃之关也。关既失守，胃亦伤矣，故气壅逆，血随气逆而咳也。又，经云二阳之病发心脾，男子少精，女子不月。二阳者，肠胃也。肠胃之病，必延及心脾，故梦遗亦有由于胃气之不固也。左手关部，细而分之，须属肝而主血；概而论之，两寸俱主上焦而察心肺，两关俱主中焦而察脾胃，两尺俱主下焦而察肝肾，是左关亦可以察脾胃之病也。古人治病，有凭症，有凭脉者，有凭形色者。今当凭症凭脉，而作气虚证治焉。遂用参、耆各三钱，白术、白芍、归身、麦门冬各一钱，茯神、栀子、酸枣仁各八分，陈皮、甘草各五分煎服。朝服六味地黄丸加黄柏、椿根皮，夜服安神丸，年余而安。", "15146": "越十余岁，致政归田。再为诊之，右手三部脉皆隐而不见，身又无病，此亦事之异也。世谓《太素》脉法，片时诊候，能知人终身祸福，岂理也哉？", "15147": "一人形瘦色悴，年三十余，因劳咳嗽吐血，或自汗痞满。每至早晨嗽甚，吐痰如腐渣乳汁者一二碗，仍复吐尽所食稍定。医用参苏饮及枳缩二陈汤，弥年弗效，众皆危之。邀予诊治。脉皆濡弱近驶。", "15148": "一人形色颇实，年四十余。病嗽咯血而喘，不能伏枕。医用参苏饮、清肺饮，皆不效。予诊之，脉皆浮而近驶。", "15149": "村庄一妇，年五十余。久嗽，咯脓血，日轻夜重。诣予诊视，脉皆细濡而滑。", "15150": "一人年逾三十，形近肥，色淡紫。冬月感寒咳嗽，痰有血丝，头眩体倦。医作伤寒发散，不愈。更医，用四物加黄柏、知母，益加身热自汗，胸膈痞闷，大便滑泻，饮食不进，夜不安寝。诣予诊治，右脉洪缓无力，左脉缓小而弱。", "15151": "曰：此气虚也。彼谓痰中有红，或咯黑痰者，皆血病也，古人云黑人气实，今我形色近黑，何谓气虚？予曰：古人治病，有凭色者，有凭脉者。丹溪云脉缓无力者，气虚也。今脉皆缓弱，故知为气虚矣。气宜温补，反用寒凉，阳宜升举，反用降下，又加以发散，则阳气之存也几稀。遂用参、耆各四钱，茯苓、白芍、麦门冬各一钱，归身八分，黄芩、陈皮、神曲各七分，苍术、甘草各五分，中间虽稍有加减，不过兼以行滞散郁而已。煎服百帖而安。", "15152": "一人形色苍白，年三十余，咳嗽，咯血，声哑，夜热自汗。邀予诊视，脉皆细濡近驶。", "15153": "又觉胸腹痞满，恶心畏食，或时粪溏。诊之，脉皆缓弱，无复驶矣。", "15154": "一人年逾三十，形瘦色脆。过于房劳，病怠惰嗜卧，食后腹痛多痰，觉自胃中而上，又吐酸水，肺气不清，声音不亮。已更数医，或用补阴消导等剂。邀予诊治，脉皆细濡无力，约有七至。问曰：「热乎？」曰：「不觉」。曰：「嗽乎？」「夜间数声而已」。曰：「大便何如？」「近来带溏，粪门旁生一疖，今已溃脓，未收口耳。」曰：「最苦者何？」「夜卧不安，四肢无力而已。」予思脉病不应。", "15155": "夫数脉主热，今觉不热，乃内蒸骨髓欤？或正气已极，无复能作热欤？据症，似难起矣。何也？虚劳粪门生疖，必成瘘疮，脉不数者，尚不可为，况脉热乎！盖肺为吸门司上，大肠为肛门司下，肺与大肠府藏相通，况肺为气主，气阳当升，虚则下陷，所谓物极则反也。今病内热燔灼，肺气久伤，故下陷肛门而生疖瘘，肺伤极矣，非药能济。予遂告归。月余果卒。故凡虚劳之病，或久泄，或左或右一边不得眠者，法皆不治也。", "15156": "一妇年三十逾，常患消渴，善饥脚弱，冬亦不寒，小便白浊，浮于上者如油。予诊脉，皆细弱而缓，右脉尤弱。", "15157": "一人形长苍紫，素善食，喜啖肉。年近六十时，六月伤饥，又被雨湿。既而过食冷物，腹中疼胀呕吐。次年至期，前病复作。医作伤食，或作冷气，率用香燥消导之药，时作时止。第三年十月，病又作，食则胃脘励痛。近来忽吐瘀血如指者三四条，大便溏泻，亦皆秽泻，又常屡被盗惊，今犹卧则惊寤。予诊左脉沉弱，右脉浮虚，但觉颇弦。次早复诊，左脉濡小无力，右脉虚豁。", "15158": "一人年十九，形瘦，面色黄白。三月间微觉身热，五月间因劳，伤于酒肉，遂大热膈闷，梦遗盗汗，午后热甚。或作食积，或作阴虚，或作痰火，治皆不应。予为诊之，午间脉皆洪滑。", "15159": "予曰：食饱之余，脉不定也。来早再诊，脉皆收敛而弱，右脉尤弱。遂以人参三钱，黄耆钱半，白术、麦门冬各一钱，黄柏、知母、山楂各七分，枳实、甘草各五分。煎服一帖，热减汗除。五服，去泰去甚，惟梦遗，一月或二次或三次。令服固精丸五六两，仍令节食守淡味，病当愈也。后又觉热，前方减甘草，加石膏钱半，牡丹皮八分。", "15160": "一人年三十，形瘦淡紫。才觉气壅，腹痛背胀则吐，腹中气块翻动嘈杂，数日乃吐黑水一盂盆，而作酸气。吐后嗳气，饮食不进，过一二日方食。大便二三日不通，小便一日一次。常时难向右卧，午后怕食，食则反饱胀痛，行立坐卧不安，日轻夜重。二年后，诣予诊治。脉皆浮弦细弱。", "15161": "一人年逾三十，形色瘦黑。饮食倍进，食后吐酸，食饭干恶难吞。尝有结痰注于胸中，不上不下。才劳则头晕眼花，或时鼻衄，粪后去红或黑。午后至晚，胸膈烦热，肩心时疼。好睡，醒来口舌干苦，盗汗梦遗脚冷。手及臀尖生脓疱疮。医以四物汤凉血之剂治之，不效。诣予诊治。左脉小弱而数，右脉散弱而数，俱近六至。", "15162": "曰：症脉皆属阴虚。作阴虚治之不效何也？此必脾虚湿郁为热而然也。今用滋阴降火，反滋湿而生热，病何由安？宜用参、耆甘温之剂，补脾去湿可焉。", "15163": "问曰：丹溪论瘦黑者、鼻衄者、脉数者，参、耆皆所当禁。予曰：固也，岂可执为定论而不知变通乎？《脉经》云数脉所主，其邪为热，其疟为虚。遂以人参二钱，黄耆钱半，白术、麻黄根、生地、茯苓、麦门冬各一钱，归身、川芎各八分，黄芩七分，麦芽、厚朴、黄柏、枳实、五味各五分，服之而愈。因劳病疟，仍用前方除麻黄根、牡蛎、麦芽、枳实、厚朴、黄柏、五味，加泽泻、柴胡、青皮、山栀各七分，甘草五分。服十余帖，胸腹腰脐生小疥而愈。", "15164": "一人于幼时误服毒药，泄痢。后复伤食腹痛，大泄不止。今虽能食，不作肌肤。每至六七月，遇服毒药之时，痛泄复作。善饥多食，胸膈似冷，夜间发热。嗜卧懒语，闻淫欲动，盗汗阳举。心动惊悸，喉中有痰。小便不利，大便或结或溏。过食则呕吐泻泄。脉皆濡弱而缓，右脉略大，尤觉弱也。次日，左脉三五不调，或一二至缓，三五至驶，右脉如旧缓弱。", "15165": "予曰：左脉不调者，此必欲动淫其精也。右脉尤弱者，由于毒药损其脾也。理宜固肾养脾。遂以人参钱半，白术、茯苓、芍药、黄耆、麦门冬各一钱，归身、泽泻各八分，黄柏、知母、山楂各七分。煎服旬余而安。", "15166": "一人年五十余，形色苍古。五月间泛木，与人争辩，冒雨劳役受饥，且有内事，夜半忽病。发热恶食，上吐下泻，昏闷烦躁，头痛身痛。因自发汗，汗遂不止。遣书来示，脉皆洪数。", "15167": "予曰：脉果洪数，乃危症矣。盖吐泻内虚，汗多表虚，兼之脉不为汗衰，亦不为泻减，在法不治。但古人有言，医而不活者有也，未有不医而活者也。令用人参五钱以救里，黄耆五钱以救表，白术三钱、干姜七分、甘草五分以和中安胃，白茯苓一钱、陈皮七分以清神理气。水煎，不时温服一酒杯，看其病势何如。", "15168": "一人形短苍白，平素善饮。五月间忽发寒热，医作疟治，躁渴益甚，时常啖梨，呕吐痰多，每次或至碗许，饮食少进，头晕昏闷，大便不通，小便如常或赤，夜梦不安，或一日连发二次，或二日三日一发，或连发二日，平素两关脉亦浮洪，邀予适以事阻，令服独参汤二三帖，呕吐少止，寒热暂住。三日，他医曰：渴甚脉洪，热之极矣，复用独参以助其热，非杀之而何？及予往视，脉皆浮洪近数。", "15169": "予曰：此非疟而亦非热也。脉洪者，阴虚阳无所附，孤阳将欲飞越，故脉见此，其病属虚，非属热也。渴甚者，胃虚津少，不能上朝于口，亦非热也。盖年逾六十，血气已衰，加以疟药性皆燥烈，又当壮火食气之时，老人何以堪此？然则邪重剂轻，非参所能独活。遂以参、耆各七钱，归身、麦门冬各一钱，陈皮七分，甘草五分，水煎。每次温服一酒杯，服至六七帖，痰止病除食进。大便旬余不通，导之以蜜，仍令服三十余帖以断病根，续后脉亦收敛而缓，非复向之鼓击而驶也。", "15170": "一人年逾三十，形瘦苍白，病食，则胸膈痞闷，汗多，手肘汗出尤多，四肢倦怠或麻，晚食若迟，来早必泄，初取其脉，浮软近驶，两关脉乃略大。", "15171": "予曰：此脾虚不足也。彼曰：已服参术膏，胸膈亦觉痞闷，恐病不宜于参、耆耶？予曰：膏则稠黏，难以行散故也。改用汤剂，痞或愈乎。令用参、耆各二钱，白术钱半，归身八分，枳实、甘草各五分，麦门冬一钱，煎服一帖，上觉胸痞，下觉失气。彼疑参、耆使然。予曰：非也。若参、耆使然，只当胸痞，不当失气，恐由脾胃过虚，莫当枳实之耗耶！宜除枳实，加陈皮六分。再服一帖，顿觉胸痞宽，失气作，精神爽恺，脉皆软缓，不大亦不驶矣。可见脾胃虚者，枳实须散用为佐使，况有参、耆、归、术为之君，尚不能制，然则医之用药，可不慎哉！", "15172": "一妇五十七岁，五月间因劳夜卧，天热开窗，醒来遍身胀痛，疑是痧症，刮背起紫疙瘩，因而胸膈胀痛，磨木香服之，致小腹作痛，咳嗽气壅，不能伏枕，吐痰腥臭，每次一二碗，亦或作泄，肛门胀急，自汗不止，身表浮肿。医作伤寒，而用发散；或作肺痈，而用寒凉，延绵一月，医皆辞去。其子来告予，予曰：第未知得何脉耳？告曰：医谓脉洪数也。", "15173": "予曰：年逾五十，血气已衰，又加以小劳，而当酷热之时，又不免壮火食气。且脉洪数，乃热伤元气而然，非热脉也。所可虑者，脉不为汗衰，为泄减耳。彼曰：用生脉汤，人参二钱，门冬二钱，五味一钱，病似觉甚。予曰：邪重剂轻也。理宜黄耆五钱以固表，人参五钱以养内，白术三钱、茯苓钱半渗湿散肿，陈皮七分、吴茱萸四分消痰下气，再加甘草五分以和之，门冬一钱以救肺，依法煎服十余帖，后虽稍安，脉与病反，终不救。", "15174": "一妇年逾三十，形色脆白，久病虚弱，余为调治十余载矣。须不能纯，去泰去甚。至嘉靖癸末，便道复为诊之，左脉似有似无，右脉浮濡无力。予曰：平素左脉不如此，今忽反常，深为之惧。越三日，再诊，两手脉皆浮濡，左则不似有似无，右则略近于驶而已，乃知脉变不常，昨今异状者，由虚而然也。今医以片时诊察，即谓其病若何，遂解囊撮药，此亦失之疏略，未必能尽其病情也。", "15175": "予诊右脉濡散，无力而缓，左脉比右颇胜，亦近无力。十五年前，哭子忒甚，遂作忧思伤脾，哭泣伤气，从东垣劳倦伤脾之例，用参、耆各钱半，白术、芍药、天麻各一钱，川芎、玄参各七分，甘草、枳实各五分，黄柏、陈皮各六分，煎服而愈。", "15176": "一人色苍黄瘦，年三十余，病遍身恶疮，因服轻粉而脚拘挛，手指节肿，额前神庭下肿如鸡卵大。方士令服孩儿骨，其法取初生孩儿，置砖地上，周以炭火煏，使死孩成灰，纸裹放地上，出火毒为末，空心或酒或汤调二三钱，谓能补也。邀予诊视，脉皆濡缓而弱。", "15177": "一人年三十余，因患此疮，服轻粉，致右腹肋下常有痞块，右眼黑珠时有丁子，努出如雀屎许，间或又消，身有数疮未痊。一医为治疮毒而用硝、黄，一医为治痞块而用攻克，一医为治眼丁而用寒凉。诸症不减，反加腹痛肠鸣，大便滑泄，胸膈壅闷，不思饮食，嗳气吐沫，身热怠倦，夜卧不安。季冬请予往诊视，脉皆浮濡近驶。", "15178": "予视左脉浮滑，右脉稍弱而滑，幼伤手腕，掌不能伸，右脉似难凭矣。乃以左脉验之，恐妊兼肺痈也。遂以清肺泻肺之剂进之。三服而能著枕，痰不吐，脓不咯，惟时或恶阻。予曰：此妊之常病也。教用薏苡仁、白术、茯苓、麦门冬、黄芩、阿胶煎服，病减。", "15179": "月余，复为诊脉，皆稍缓而浮。曰：热已减矣。但吐红太多，未免伤胃，教用四君子加陈皮、黄芩、枳壳煎服调理。妊至六月，食鸡病作，却鸡而愈。至九月，病又复作，声哑，令服童便获安。予曰：产后病除，乃是佳兆，病若复来，非吾所知。月足而产，脾胃病作，加泄而卒。", "15180": "一妇瘦长面紫，每遇春末夏初，两脚生疮，脓泡根红，艰于行步，经水不调。邀予诊视，脉皆濡弱近驶，两尺稍滑。", "15181": "邑庠司训余先生，年几六十，长瘦色苍，赴福建考试，官回，病背腿痈肿。一肿愈，一肿作，小者如盏，大者如钟，继续不已，俗曰流注是也。医皆欲用十宣散、五香汤、托里散。予为诊之，脉皆濡弱。", "15182": "一人肥短紫淡，年逾三十，因劳感湿，两腿胯间结核痛甚。医用蒜片艾灸，又针大敦、三阴交，又以药水洗之，遂致阴囊肿胀如升，茎皮肿如水泡。复进人参败毒散，皆不中病。邀予往诊，脉皆濡缓而弱略驶。", "15183": "一儿六岁，阴囊胀大如盏，茎皮光肿如泡。一医为之渗湿行气，不效。邀予诊视，脉皆濡缓。", "15184": "曰：脉缓无力者，气虚也。经云膀胱者，津液之府，气化出焉。气虚不足，无能运化而使之出矣。宜升阳补气可也。遂以人参为君，黄耆、白术、茯苓为臣，牛膝、升麻、陈皮为佐，甘草梢为使，煎服一二帖，囊皱肿消，三帖痊愈。", "15185": "一妇瘦小，年二十余，经水紫色，或前或后，临行腹痛，恶寒喜热，或时感寒，腹亦作痛。脉皆细濡近滑，两尺重按略洪而滑。", "15186": "予曰：虽未见脉，详其所示，多属脾胃不足。令服四君子汤加黄芩、陈皮、神曲、归身二帖，红止白减。复以书示曰：药其神乎！继服十余帖，诸症悉除。", "15187": "一妇经行，泻三日，然后行。诊其脉，皆濡弱。曰：此脾虚也。脾属血属湿，经水将动，脾血已先流注血海，然后下流为经。脾血既亏，则虚而不能运行其湿。故作参苓白术散，每服二钱，一日米饮调下二三次，月余经行不泻矣。", "15188": "一妇产后，经行不止，或红或白或淡。病逾八月，面色黄白，性躁，头眩，脚软，医用参耆补药病益加，用止涩药无效。邀予诊之，右脉濡弱无力，左脉略洪而驶。", "15189": "曰：右脉弱者，非病也，左脉偏盛，遂觉右脉弱耳，宜主左脉，治以凉血之剂。遂以生地、白芍、白术各一钱，黄芩、阿胶、归身各八分，陈皮、香附、川芎、椿根皮、茯苓各六分，柴胡、甘草各五分，煎服二十余帖而愈。", "15190": "一妇形长质脆，面色黄白，孀居十余年，平素食少，内外俱劳，年五十二岁。二月忽血崩，若左手觉热，崩则又甚。医用苦寒黑灰凉血止血之剂，益剧。更用胶艾汤，少愈。偶因子病，住药月余，后服前汤，崩则日少夜多。七月尽，来就予治。右脉浮软颇大，左脉软小而，缓独左尺尤近微弱。", "15191": "予谓：左脉主血，得此与病相应，右脉主气，今诊得浮软，此乃脾胃气不足也。盖脾具坤静之德，而有干健之运，虚则不能健运其血矣。胃气者，阳气也，阳主升举，虚则不能升举其血矣。经曰阳病竭而下者此也。又曰阳病治阴，阴病治阳，正其血气，各守其乡，其治此病之谓欤。今气不能健运升举，以致血崩，法当治阳。", "15192": "予适出月余，归诊，脉皆沉细而数。予曰：数脉所主为热，其症为虚，脉与向日不同，而症反觉虚者，多因久服前药，失于加减，故藏府习熟，而病反见化于药矣，令暂止药。", "15193": "乘轿归家，登山度岭，加以应接人事，劳而又劳，越三日，血大崩约一桶许，昏懵而气息奄奄，良久稍苏，是夜又崩二三碗许，仍复昏懵。予往视之，脉仍沉细而数。予曰：五十以后，血气大脱，实难求生，但不忍坐视其毙耳。乃用大剂，参、耆各七钱，归、地、姜、附各一钱，甘草五分，煎服二三帖，脉数略减，头痛昏弱，腰脚腿痛亦愈。日则胸膈似烦，至夜亦愈。但小腹时觉微痛，清水常流不绝。", "15194": "经曰冲脉者，经脉之海，主渗溪谷，与阳明合于宗筋，会于气街，而阳明为之长，皆属于带脉。故阳明虚，则冲脉失养，不能渗灌，气化为水而下流矣。待其胃气稍完，则清者运而为津液，浊者渗而为小便，而水或可止也，经曰「壮者气行则愈」是矣。若遇严寒，又觉小腹腰脚腿痛者，亦由阳虚不御其寒故也。天地稍和，又不觉矣。予曰：病须少愈，然血气虚脱，来春恐无以资生发之气耳。至春，果洞泻而殁。", "15195": "丹溪曰：气病补血，须不中，亦无所害。血病补气，则血愈虚散，是谓诛罚无过。今病血病，而治以参、耆，宁不犯丹溪之戒乎？予曰：学贵疏通，不可执泥。丹溪又曰：冲任二脉为经脉之海。二脉无损，则血气之行，外循经络，内荣五藏。若劳动过极，损伤二脉，则冲任气虚，不能约制其血，故忽大下，谓之崩中。治宜举养脾胃，大补气血。丹溪治血，何常不归于气虚而养脾胃也！东垣亦曰血脱益气。古圣人之法也，先理其胃，以助生发之气，诸甘药为之先务。盖甘能生血，此阳生阴长之理，故先助胃气。且人之身，纳谷为宝。予考圣经前贤所治血病，未尝专主于治血而不养气。要在临病识宜耳。须然此固不免于死，所以得迟延而无苦楚者，恐亦由于药力也。因笔之，幸同志者考其得失。", "15196": "一妇年逾四十，形长色脆，病经不调，右脉浮软而大，左脉虚软而小近驶。尝时经前作泄。今年四月，感风咳嗽，用汤洗浴，汗多，因泄一月。六月，复因洗浴，发疟六七次。疟须止，而神思不爽。至八月尽，而经水过多，白带时下，泄泻，遂觉右脚疼痛。旧曾闪朒脚跟。今则借此延痛，臀腿腰胁尾骨、胫项左边筋皆掣痛。或咳嗽一声，则腰眼痛如刀扎。日轻夜重，叫号不已。幸痛稍止，饮食如尝。今详月水过多，白带时下，日轻夜重，泻泄无时，亦属下多亡阴。宜作血虚论治，然服四物止痛之剂益甚。九月，予复诊视，始悟此病，乃合仲景所谓阳生则阴长之法矣。", "15197": "一妇年二十一岁，六月经行，腹痛如刮，难忍求死。脉得细软而驶，尺则沉弱而近驶。予曰：细软属湿，数则为热，尺沉属郁，此湿热郁滞也。以酒煮黄连半斤，炒香附六两，五灵脂半炒半生三两，归身尾二两，为末，粥丸，空心汤下三四钱，服至五六料。越九年，得一予。又越四年，经行两月不断，腹中微痛，又服前丸而愈。续后经行六七日，经止则流清水，腹中微痛，又服前丸，而痛亦止。又经住只有七八日，若至行时，或大行五六日。续则适来适断，或微红，或淡红。红后尝流清水，小腹大痛，渐连遍身胸背腰腿骨里皆痛，自巳至酉乃止。痛则遍身冷，热汗大出，汗止痛减，尚能饮食。自始痛至今历十五年，前药屡服屡效，今罔效者，何也？予在休宁率口，其母伴女荷轿，至彼就医。脉皆洪滑无力，幸其尚有精神。予曰：此非旧日比矣，旧乃郁热，今则虚寒，东垣曰「始为热中，终为寒中」是也。经曰脉至而从，按之不鼓，乃阴盛格阳，当作寒治，且始病时而形敛小，今则形肥大矣。医书曰瘦人血热，肥人气虚，岂可同一治耶？所可虑者，汗大泄而脉不为汗衰，血大崩而脉不为血减耳。其痛日重夜轻，知由阳虚不能健运，故亦凝滞而作痛。以症参脉，宜用助阳。若得脉减痛轻，方为佳兆。遂投参耆归术大剂，加桂、附一帖。来早再诊，脉皆稍宁。随即回宅，服至二三十帖，时当二月。至五月，予适往城，视之，病且愈矣。盖病有始终寒热之异，药有前后用舍不同，形有少壮肥瘦不等，岂可以一方而通治哉？后闻乳有隐核数枚，彼时失告于予，访之外科，归罪于多服参、耆而然。殊不知肥人气虚多滞，若能久服前药，不惟乳无隐核，纵有亦当消矣。多因病退却药，血气未充，故气滞血凝而成此核，经曰「壮者气行则愈」是矣。予以书喻柢，恐一齐传众楚咻，莫能回其惑也。", "15198": "一妇形质瘦小，面色近紫，产后年余，经水不通。首夏忽病，呕吐，手指麻痹，挛拳不能伸展，声音哑小，哕不出声。医皆视为风病，危之。予诊脉，皆细微近滑。曰：此妊娠恶阻病也。", "15199": "众谓经水不通，安有妊理？予谓天下之事有常有变，此乃事之变也。脉虽细微，似近于滑；又尺按不绝，乃妊娠也。遂以四君子加二陈治之，诸症俱减，尚畏粥汤，惟食干糕香燥之物而有生意。", "15200": "出部脉", "15201": "一妇年逾四十，形色颇实，常患产难倒生，经水不调，或时遍身骨节疼痛，食少倦怠，自汗。予为诊之，两手脉皆不应，惟右关轻按，隐隐然微觉动也。疑脉出部，以指寻按经渠列缺穴分，亦不应。余甚怪之，乃叩其夫。曰：有孕，时医诊亦言无脉。后服八物汤，幸尔易产而得一子。予曰：此由禀赋本来脉不应也，无足怪焉。可见天下事变出无穷，果难一一以常理测也。如《脉经》所谓，但道其常而已。两手无脉，不伤其生，又不妨于胎妊，岂《脉经》所能论及耶？脉或两手出部，或一手出部，予见多矣。两手无脉，而人如故，此亦理之所无，事之大变，故笔记。", "15202": "一妇有病，请予诊之。右脉缓濡而弱，左手无脉，再再寻之，动于腕臂外廉阳谿偏历之分。乃语之曰：左脉离其部位，其病难以脉知。以右脉言之，似属于脾胃不足也，尚当言其病焉。告曰：每遇经未行前咯血数口，心嘈不安，食少懒倦。予以四君子汤加山栀、陈皮、麦门冬、牡丹皮，煎服数帖而安。", "15203": "予尝考孙兆诊一释者，左脉出部，动于臂上。曰：此反脉也，医书不载。脉行常道，岂有移易？或者少年惊扑，震动心神，故脉脱故道耳。年既长大，血气已定，不能复移也。僧曰：果如所言。予询此妇，未尝得惊，而脉如是，可见亦由于禀赋也。后在歙之江村，诊得两手脉俱出部者数人，或左或右，一手脉出部者尚多。信行诊一妇人，两手脉亦出部。凡此皆事变无穷，理之莫测，岂皆由于惊动哉。夫此须非经水之病因，其脉类前案。故录于此。", "15204": "一妇怀妊八月，尝病腰痛不能转侧，大便燥结。医用人参等补剂，痛益加。用硝、黄通利之药，燥结虽行，而痛如故。予为诊之，脉稍洪近驶。", "15205": "一妇尝患横生逆产七八胎矣，子皆不育。予诊脉皆细濡颇弦。曰：此气血两虚兼热也。", "15206": "或曰：气血有余，方成妊娠。气血既亏，安能胎耶？予曰：观其形长瘦而脉细濡，属于气血两虚；色青脉弦，属于肝火时炽；而两尺浮滑，似血虚为轻，而气虚为重也。宜以补阴丸除陈皮，倍加香附、参、耆，蜜丸服之，常令接续，逾年临产，果顺而育一子。", "15207": "一妇产后滑泄，勺水粒米弗能容，即时泄下，如此半月余矣。众皆危之，或用五苓散、平胃散，病益甚。邀予诊之。脉皆濡缓而弱。", "15208": "一妇产后，时发昏瞀，身热汗多，眩晕口渴，或时头痛恶心。医用四物凉血之剂，病不减。复用小柴胡，病益甚。予为诊之，脉皆浮洪搏指。", "15209": "予谓：产后而得是脉，又且汗多，而脉不为汗衰，法在不治。所幸者，气不喘，不作泄耳。其脉如是，恐为凉药所激也。试用人参三钱，黄耆二钱，甘草、当归各七分，白术、门冬各一钱，干姜、陈皮、黄芩各五分，煎服五帖，脉敛而病渐安。", "15210": "一女年六岁，病左手不能举动三年矣，后复病痫。初用人参、半夏，或效或否。予诊左脉浮洪，右脉颇和。", "15211": "其中又有变其常者，亦当变其常以治之矣。经曰冲任二脉，为血之海，主渗灌溪谷。而阳明为之长，阳明者，胃也。或有劳动损其冲任，则血不得渗灌而越上于上窍，故阳明胃脉亦失所养，或饮食无味，或食则难饥，或恶心呕吐，或胸膈痞闷，或大便不常，此又初因阴虚而终致于阳虚也。夫因阴虚而致阳虚，则滋阴降火之法，又难例用，当从东垣阳生阴长而用甘温之剂矣。经曰阳气者，精则养神，柔则养筋。盖心主血而藏神，肝主筋而藏血。若胃之阳气有亏，是阳气之精者亦虚，而心神失养，不能以主血；阳气之柔者亦损，而肝筋失养，不能以藏血。心既不能主血，肝又不能藏血，欲其血之不妄行也难矣。此又阴变为阳之病，岂可以其阴虚例治而损其阳也。", "15212": "予诊之，脉皆细驶，右脉颇大于左，独脾脉弦且滑。扶起诊之，右脉亦皆细数。恐伤酒肉，用二陈汤加黄芩、山楂、曲、蘖，进之不效。再用小承气汤，仍复不利。蜜煎导之，亦不利。乃以大承气汤，利二三行，痛减未除。令其住药，只煎山楂饮之。次日烦躁呕恶，渴饮凉水则觉恶止爽快。次早再诊，脉皆隐而不见。四肢逆冷，烦躁不宁，时复汗出。举家惊愕，疑是房后阴症，拟进附子理中汤。", "15213": "予曰：此治内寒逆冷也。《活人书》云四逆无脉，当察症之寒热。今观所患，多属于热，况昨日脉皆细数，面色近赤，又兼酒后而病。六脉虽绝，盖由壮火食气也。四肢者，诸阳之本。气被壮火所食，不能营于四肢，故脉绝而逆冷也。此类伤暑之症，正合仲景所谓热厥者多，寒厥者少，急用大承气汤下之之类。向虽下以大承气，其热尚有未尽，难以四逆汤症与比。今用附子热药，宁不助火添病耶？如不得已，可用通脉四逆汤，尚庶几焉。以其内有童便、猪胆汁监制附毒，不得以肆其疟也。", "15214": "连进二服，脉仍不应，逆冷不回，渴饮烦躁，小便不通，粪溏反频，腹或时痛，更进人参白虎汤二帖。燥渴如旧，更用参、术各三钱，茯苓、麦门冬、车前各一钱，北五味、当归各五分。煎服一帖，脉渐隐隐见如蛛丝。予曰：有生意也。仲景论绝脉服药微续者生，脉暴出者死是也。", "15215": "但去大便，而小便亦去，不得独利。予曰：小便不利，烦渴未除，盖由内热耗其津液也。大便尚溏者，亦由内热损其阳气，阳气不固而然也。遂用参、术各三钱，茯苓钱半，白芍、车前、门冬各一钱，山栀七分，北五味五分，连进数服，至第九日，逆冷回，脉复见，诸症稍减而向安矣。", "15216": "一人年逾四十，面色苍白，平素内外过劳，或为食伤，则咯硬痰而带血丝。因服寒凉清肺消痰药，至五六十帖，声渐不清而至于哑。夜卧不寐，醒来口苦，舌干而常白胎。或时喉中阁痛，或胸膈痛，或嗳气，夜食难消，或手靠物久则麻，常畏寒，不怕热。前有𤻊疝，后有内痔，遇劳则发。初诊左脉沉弱而缓，右脉浮软无力。续后三五日一诊，心肺二脉浮虚，按不应指。或时脾脉轻按阁指，重按不足。又时或驶，或缓，或浮，或沉，或小，或大，变动全无定准。", "15217": "夫脉不常，血气虚也。譬之虚伪之人，朝更夕改，全无定准；的实之人，朝斯夕斯，常久不移。以脉参症，其虚无疑，虚属气虚，为重也。盖劳则气耗而肺伤，肺伤则声哑；又劳则伤脾，脾伤则食易积。前疝后痔遇劳而发者，皆因劳耗其气，气虚下陷，不能升举故也。且脾喜温畏寒，而肺亦恶寒，故曰形寒饮冷则伤肺。以已伤之脾肺，复伤于药之寒凉，则声安得不哑？舌安得不胎？胎者，仲景谓胃中有寒，丹田有热也。夜不寐者，由子盗母气，心虚而神不安也。痰中血丝者，由脾伤不能裹血也。胸痛嗳气者，气虚不能健运，故郁于中而嗳气，或滞于上则胸痛也。", "15218": "予脉之，皆浮虚洪数，不任寻按，坐起则觉略小，亦不甚数。脉书曰数脉所主为热，其症为虚。三日后再诊，左脉小而滑，右脉大而滑，独肺部浮软，按之似蛰蛰有声。与昨脉不同者，虚之故也。", "15219": "夫阳气者，清纯冲和之气也。或劳动过度，或酒食过伤，则扰动其阳，变而为邪热矣。然脾胃以阳气为主，阳变为热，血必沸腾而越出于上矣。昏晕者，由热熏灼，故神昏运倒而类风也。风之旋转运动，与火相类。每觉下焦热上，胸膈壅塞而即发者，脾脉从足入腹至胸，今下焦热上，乃脾火也。然胸膈，心肺之分，为阳之位。清阳居上，今邪热扰之，则阳不得畅达，而心肺之神魄不免为之而昏乱矣。况五藏皆赖胃气以培养，胃受火邪则五藏皆无所禀，而所藏之神亦无所依，故肺之魄，心之神，肝之魂，脾之意，肾之志，安得不随之溃乱躁扰而昏瞀耶？多发于午前后者，乃阳气所主之时。阳为邪扰，不能用事，故每至其时而辄发也。且汗多津液泄，口干津液少，医用牛黄、朱砂、琥珀、南星、半夏等而复燥之，是愈益其燥，故暂止而复发，不能拔去其病根也。", "15220": "一人年逾三十，神色清减，初因伤寒过汗，是后两足时冷，身多恶寒，食则易饥，日见消瘦，梦遗甚频，筋骨疼痛，久伏床枕，不出门户。医用滋阴降火不效。予视，左脉浮虚而缓，右脉浮弦而缓，此阳虚也。病者言易饥善食，梦遗甚频，似属阴虚，若作阳虚而用参、耆，恐增病矣。予故为之备论其病。", "15221": "古人谓脉数而无力者，阴虚也；脉缓而无力者，阳虚也。今脉皆浮虚弦缓，则脉为阳虚可知矣，参症论之，病属阴虚，阴虚则发热，午后属阴，当为午后则遍身发热，恶热，揭胸露手，蒸蒸热闷而烦躁也。今患并无是症，何得认作阴虚？夫阳虚则恶寒，虽天暖日和，犹恐出门，怕寒恶风。今患两足时冷，身多畏寒，皆阳虚之验矣。又被汗多亡阳，非阳虚而何？今日食则易饥，非阴虚火动也。盖脾胃以气为主，气属阳，脾胃之阳已虚，又被苦寒属阴之药以泻其阳，则阳愈虚而内空竭，须借谷气以扶助之，故易饥而欲食，食亦不生肌肉也。经曰饮食自倍，肠胃乃伤，又曰饮食不为肌肤，其此之谓欤。梦遗亦非特阴虚。经曰阳气者，精则养神，柔则养筋。今阳既虚，则阳之精气不能养神，而心藏神，神失所养，则飘荡飞扬而多梦矣；阳之柔气不能养筋，而肝主筋以藏魂，筋失所养，则遍身筋骨为之疼痛。魂亦不藏，故梦寐欠安，何得而不遗乎？经曰气固形实。阳虚则不能固，而精门失守，此遗之所以频而不禁也。", "15222": "予诊，左手心脉浮小而驶、肝肾沉小而驶，右脉皆虚散而数，此恐乘舆远来，脉未定耳。来早脉皆稍敛不及五至，非比日前之甚数也。", "15223": "夫头之左边及耳前后，皆属于少阳也。经曰：少阳多气少血。今用风药、痰药类皆燥剂。少血之经，又以燥剂燥之，则血愈虚少矣。血少则涩滞，涩滞则壅肿，且血逢冷则凝，今复以寒剂凝之，愈助其壅肿，久则郁而为热，腐肉成脓，从耳中出矣。渐至右耳亦聋者，脉络相贯，血气相依，未有血病而气不病也，是以始则左病而终至于右亦病矣。况病久气血已虚耳，人年六十，血气日涸；而又出久劳伤气血，又多服燥剂以损其气血，脓又大泄，已竭其气血，则虚而又虚可知矣。以理论之，当以滋养气血，气血健旺，则运行有常，而病自去矣。否则不惟病且不除，而脑痈耳疽抑亦有不免矣。", "15224": "予诊，脉皆微弱，似有似无，或一二至一止，或三五至一止，乃阳气大虚也。以独参五钱，陈皮七分，煎服十余帖而愈。", "15225": "诊其左手心脉浮数而滑，肾肝二脉沉弱颇缓，右手肺脉浮虚而驶，脾脉偏弦而驶，命门散弱而驶。第二日再诊，心肝二脉细软，稍不见驶矣。肾脉过于弱，肺脉浮软，亦不见驶。脾脉颇软，命门过浮略坚。", "15226": "予曰：膀胱者，津液之府，气化出焉。淋者，由气馁不能运化，故津液郁结为热而然也。房后而愈者，则郁结流利而热解矣。三月天日和煦，何得伤寒？多由肺气不足，莫能护卫皮毛，故为风邪所袭，郁热而动其肺，以致痰嗽也。得芦吸散而愈者，以辛温豁散其痰与热也。嗽止、身热不退者，因嗽久肺虚，肺虚则脾弱，脾肺之气不能荣养皮肉，故热作也。经曰形寒饮冷则伤肺，又曰脾胃喜温而恶寒。今服小便之寒凉，宁不愈伤其脾肺耶？是以腹胀作痛，胁气触上，或泻或汗种种诸病，皆由损其脾肺也。而脉时或变易不常者，亦由气血两虚，虚而为盈，难乎有常矣。", "15227": "后因解头劳倦，诸症复作。来就予治，脉与前颇同，但不数不驶而已。仍用参、耆各三钱，麦门冬、归身、厚朴、枳实、甘草、黄芩等剂而愈。", "15228": "凡此数者，更相为治。故悲可以治怒，以怆恻苦楚之言感之；喜可以治悲，以谑浪亵狎之言戏之；恐可以治喜，以逼遽死亡之言怖之；怒可以治思，以污辱欺罔之言触之；思可以治恐，以虑彼忘此之言夺之。凡此五者，必诡谲怪诈，无所不至，然后可以动人耳日，易人视听，若胸中无材器之人亦不能用此法也。热可以治寒，寒可以治热，逸可以治劳，习可以治惊。经曰惊者平之。夫惊以其忽然而遇之也，使习见习闻，则不惊矣。惟劳则气耗，恐则气夺者，为难治。喜者少病，百脉舒和之故也。", "15229": "一人因喜成病，庄医切脉，为之失声，佯曰：「吾取药去。」数日更不来。病者悲泣，辞家人曰：「处世不久矣。」庄知其将愈，慰之。诘其故，引《素问》「惧胜喜」。可谓得玄关者也。", "15230": "昔贵人有疾，天方不雨，更医十数罔效。最后一医至，脉已，则以指计甲子，曰：「某夕天必雨。」竟出。贵人疑曰：「岂谓吾疾不可为耶？何言雨而不及药我也？」已而夕果雨，贵人喜起而行乎庭，达旦，疾若脱去。", "15231": "脉", "15232": "重大之病，一日三脉多变，难治；沉疴日日脉不移，亦难治。伏经脉最难求，如积热之久，脉反沉细，而外症又寒，苟非兼以望闻问切，何可得也？世俗讳疾试医，医复讳情妄臆。而豪贵妇女，往往不得望闻，岂不大错？", "15233": "一妇年三十余，十八胎九㱩八夭。复因惊过甚，遂昏昏不省人事，口唇舌皆疮，或至封喉，下部白带如注，如此四十余日。或时少醒，至欲自缢，自悲不堪。或投凉剂解其上，则下部疾愈甚；或投热剂，或以汤药熏蒸其下，则热晕欲绝。脉之，始知为亡阳症也。急以盐煮大附子九钱为君，制以薄荷、防风，佐以姜、桂、芎、归之属，水煎，入井水冷与之。未尽剂，鼾睡通宵，觉则能识人。", "15234": "痿虽软易，其亦有痛者。且其痛时，遍身筋皆肿胀。而右脚内廉筋亦急痛，不能屈伸，以此验之，筋痛可知矣。经曰厥阴少血之经，筋之所主。过汗则亡血，而筋失所养，故急痛也。腿骹肿者，盖人身之血犹江河之水，洪泛则流沙走石；彼细流浅濑，则此阻彼碍而壅肿矣。经曰「怯者著而成病」是也。兼之脾胃太虚，呕逆嗳气，饮食少进。经曰：胃者，水谷之海。脾主于胃，行其津液，以养皮肉筋脉。今胃不受，而脾不运，筋脉愈失所养矣。又加灸砭，焦骨伤筋，复耗其血。丹溪曰：血属阴，难成易亏者也。兹则针灸妄施，则血虚耗矣，欲其疾愈，岂可得哉？且经曰筋枯者，举动则痛，是无血以养，俱难治也。所幸者，精神尚好，大便固秘，夜卧安静。于此健其脾胃，使饮食进，则血自生，筋自舒，肿退痛除，庶或可愈。其脉初皆细软而缓，按之无力。予以独参汤一两，一剂与之，其效甚速。", "15235": "予适他往，更医复灸，又用参、耆、归、术加凉剂，胃气遂不能回矣。再诊，脉变为滑数。脉书言疮科滑脉，未溃宜内消，已溃宜补益。又曰数脉所主为热，其症为虚，是脉与症皆属于虚，亦须大补，托而出之，治亦同法，岂得歧而两途？病居疑似，故详辨之。", "15236": "其父质于予。予曰：儿本气怯，又当暑月过劳。经曰劳则气耗。又曰劳倦伤脾。即此观之，伤脾之病也。身热者，经曰阳气者，烦劳则张。盖谓气本阳和，或劳烦，则阳和之气变为邪热矣。头痛者，经曰诸阳皆会于头。今阳气亢极，则邪热熏蒸于头而作痛也。吐泻者，脾胃之清气不升，浊气不降也。目闭者，盖诸脉皆属于目，而眼眶又脾所主，脾伤不能营养诸脉，故眼闭而不开也。咽哑者，盖脾之络连舌本、散舌下，脾伤则络失养，不能言也。经曰脾胃者，水谷之海。五藏皆禀气于脾，脾虚则五藏皆失所养。故肺之咽嗌为之不利，而食难咽；故心之神明为之昏瞀而不知人。常欲手揾阴囊者，盖无病之人，阴升阳降，一有所伤，则升者降，降者升经曰阴阳反复是也。是以阴升者降，从其类而入厥阴之囊，因阴多阳少，故手欲揾之也。此皆脾胃之病。经谓土极似木，亢则害，承乃制也。症似风木，乃虚象耳，不治脾胃之土，而治肝木之风，欲儿不死难矣！且用参、耆、术各三钱，熟附一钱煎，用匙灌半酒杯，候看如何。", "15237": "服后，病无进退。连服二三日，神稍清，目稍开，如有生意，食仍难咽。予为诊之，脉皆浮缓，不及四至。予曰：药病相宜，再可减去附子服之。渐渐稍苏。初医或作风热施治，而用荆、防、芩、连、蚕、蝎之类；或作惊痰，而用牛黄、朱砂、轻粉等药。此皆损胃之剂，岂可投诸儿？今得生幸耳，实赖其父之知医也。", "15238": "一妇年三十，质脆弱，产后咳嗽，痰臭。或作肺痈治，愈剧。延及两脚渐肿至膝，大便溏，小腹胀痛，午后发热，面红气促，不能向右卧。予诊，脉虚小而数。", "15239": "予侄文焕妻亦患此，医作肺痈治，而用百合煎汤煮粥，食之反剧。予诊，其脉细弱而缓，治以参、耆甘温等剂，二三帖而愈，此由治之早也。", "15240": "一人年逾四十，形肥色苍，因劳后入房感风，夜半疟作，自汗，寒少热多，一日一作。医用清脾、小柴胡、四兽等剂不效。渐至二日或三日一发。予诊，左脉浮洪虚豁而数，右脉虚小散数，头眩耳鸣，四肢懒倦，手足麻、大便溏，左胁疟母，时或梦遗，发则呕吐，多痰，或辰或午发，至酉戌乃退。每至三十日连发二次，子时发至黎明，其发微；辰时发至酉戌，其发如常。", "15241": "予用参、耆、归、术、麦门、知母、厚朴、陈皮大剂与之。初服一剂，痞块反高，小腹胀痛。予曰：药若不瞑眩，厥疾弗瘳，再当服之数帖。后脉皆稍静不数。", "15242": "病者曰：脉平而病不减，何也？予曰：疟邪已深，非数剂之药、旦夕之功所能愈。当久服，待春分阳气发扬，方得全愈。苟惑人言而止药，不惟疟不能止，或痨或鼓，难免后忧。夫疟因感风、暑、寒、水而作也。经曰皮肤之外，肠胃之内，气血之所舍也。气属阳，风暑阳邪而中于气；血属阴，寒水阴邪而中于血。先中阳邪，后中阴邪，则先寒后热；先中阴邢，后中阳邪，则先热后寒。阳邪多则热多，渴而有汗；阴邪多则寒多而汗少。气血受邪而居于其舍。悍卫之气运行不息，不受邪也。日行阳二十五度，夜行阴二十五度，每一刻则周身一度，行与邪遇，则邪壅遏其道路，故与相搏而疟作也。搏则一胜一负，负则不与之搏，而悍卫无碍，故疟止矣。夫邪之盛衰，因气血之盛衰，气血盛，邪亦盛；气血衰，邪亦衰。久则气血衰，或静养二三日，气血复盛而邪亦盛，悍卫行与之遇，又复相抗而疟作。此疟每三十日连发二次者，盖二十八九、三十日，晦日也。阴极阳生之时，夜半微阳始生而力尚弱，故疟发亦轻；辰则阳旺矣，故疟亦重。此疟所感阳邪居多，故随阳气盛衰而为之轻重。其三日一发者，非入于藏也，由气血盛衰而然，非若伤寒之传经也。", "15243": "一人年十九，面白质弱，因作文过劳，梦遗，遂吐血碗许，自是微咳倦弱，后身忽大热，出疹。疹愈，阴囊痒甚，搓擦水流，敷以壁土，囊肿大如盏许。遂去土，以五倍涂少蜜炙为末，敷之遂愈。因感风寒，其嗽尤甚，继以左右胁痛。予诊，脉虚而数，见其畏风寒，呕恶倦动，粪溏，气促。", "15244": "予曰：此金极似火也。夫心属火而藏神，肾属水而藏志，二经属少阴，而上下相通。今劳思则神不宁而梦，志不宁而遗，遗则水不升而心火独亢也。肝属木而藏血，其象震，震为雷，心火既亢，则同类相应，引动龙雷之火，载血而越出乎上窍矣。肝脉环绕阴器，亦因火扰而痛痒肿胀也。火胜金，故肺金虚而干咳。皮毛为之合，亦为火郁而发疹。大肠为之府，故亦传导失宜而粪溏。然金虚不能平木，故木火愈旺而凌脾，脾虚则呕恶而食减。经曰壮火食气。脾肺之气为壮火所食，故倦于动作而易感风寒也，经言两胁者，阴阳往来之道路也，为火阻碍，则气不利而痛矣。然火有虚有实，有似火而实非火。故经言有者求之，无者求之；虚者责之，实者责之。此治火之大法也。前病之火皆虚，非水湿之可折伏，惟甘温之剂可以祛除。譬之龙雷之火，日出则自潜伏矣。若用苦寒降火，正如雨聚雷烈而火愈炽盛矣。世医治火，不惟不求之有无虚实，专泥《明医杂著》咳嗽吐红皆属阴虚，误服参、耆不救之语，概用滋阴等剂。况此服滋阴药已百余帖，而病反剧，岂可仍以阴虚治之耶？且经言形寒饮冷则伤肺，又谓脾胃喜温而恶寒。今用甘温健其脾，则肺金不虚；而咳嗽气促自愈。肝木有制，而胁痛吐血自除，虚妄之火亦自息矣。", "15245": "遂用参、耆各四钱，神曲、山楂各七分，白术、贝母、麦门冬各一钱，甘草五分，炒干姜四分。煎服十余帖，脉数减，咳少除，精神稍健。", "15246": "但后又适新婚，不免耗损真阴，将何以制其虚妄之火耶！盖咳属肺金，数脉属火，咳而脉数，火克金也，冬月水旺而见数脉，亦违时也。大凡病见数脉，多难治疗，病久脉数，尤非所宜。此予所以深为之虑也。", "15247": "一妇年三十余，性躁多能，素不孕育，每啜粥畏饭，时或心痛，春正忽大作，或作气而用香燥，或作痰而用二陈，或作火而用寒凉，因粪结进润肠丸，遂泄不禁，小便不得独利。又发寒热，热则咳痰不止，寒则战栗鼓颔，肌肉瘦削，皮肤枯燥，月水不通，食少恶心，或烦躁而渴，或昏昏嗜卧，或小腹胀痛，诸治罔效。医皆视为死症，诣请予往治之，右脉浮大弦数，左脉稍敛而数，热来左右脉皆大而数，寒来脉皆沉微似有似无。", "15248": "经言脉浮为虚，脉大必病进。丹溪谓脉大如葱管者，大虚也。经又谓弦脉属木，见于右手，肝木克脾土也。又以数脉所主为热，甚症为虚。左脉稍敛者，血分病轻也。今患素畏饭者，是胃气本弱矣。心痛即胃脘痛，由脾虚不运，故胃脘之阳不降，郁滞而作痛也。泻泄不禁，小便不得独行者，盖阳主固，且经言膀胱者，津液之府，气化则能出矣，今阳虚不固于内，故频泄也，膀胱气虚不化，故小便不能独行也。又寒热互发者，盖气少不能运行而滞于血分，故发热；血少不得流利而滞于气分，故发寒。仲景曰「阳入于阴则热，阴入于阳则寒」是也。寒则战栗鼓颔者，阴邪入于阳明也。热则咳痰不已，阳邪入于阳明也。此则阴阳两虚，故相交并而然也。肌肉瘦削者，盖脾主身之肌肉，脾虚食少，故瘦削也。皮肤枯燥者，经曰脾主于胃，行其津液，脾虚不能运行津液，灌溉于肌表，故枯燥也。月水不通者，经曰二阳之病发心脾，男子少精，女子不月。二阳，手足阳明肠与胃也。阳明虚，则心脾皆失所养，而血不生，故不月也。食少恶心，躁渴，嗜卧，皆脾胃所生之症也。小腹胀痛者，乃阳虚下陷使然也。经曰阳病极而下是也。", "15249": "其母孺人病头痛，呕吐十余年，居士起之如故。以望公晚年三染疾，亦三起之。公曰：医力如此，牲鼎，何足羡耶？于是益加研究，诊治病者，百试百中，捷如桴鼓。声名益彰，遐迩以疾来请者无虚日，居士随请随就。不可起者，直告之不隐，可起者竭力治之，至忘寝食。若王公贵人，稍不为礼，不应也，其自重又如此。久之求者益众，所应亦博，活人至数万指。都里、姓名、脉色及方症，其徒周臣、许忠历历纪之，为书曰《石山医按》，试略言之。", "15250": "郡侯张歉斋公，年逾五十，过劳怠倦，烦闷，恶食不爽。居士诊之，脉浮小濡缓。曰：此合东垣劳倦伤脾之论也。冬春宜仿补中益气汤例，夏秋宜仿清暑益气汤例，依法守方，服之良愈。又常虑子迟，居士复为诊之，曰：浮沉各得其位，大小不逾其矩，后当有子，果如所言。", "15251": "歙呈坎罗斯聪，年逾三十，病中满。朝宽暮急，屡医不效。居士诊视，脉浮小而弦，按之无力，曰：此病宜补。以人参二钱，白术、茯苓各一钱，黄芩、木通、归尾、川芎各八分，栀子、陈皮各七分，厚朴五分，煎服。且喻之曰：初服略胀，久则宽矣。彼疑气无补法，居士曰：此世俗之言也。气虚不补，则失其健顺之常，痞满无从消矣。经曰塞因塞用，正治此病之法也。服之果愈。", "15252": "其弟斯俊，形实而黑，病咳，痰少声嘶，间或咯血。居士诊之，右脉大无伦，时复促而中止，左脉比右略小而软，亦时中止。曰：此肺、脾、肾三经之病也。盖秋阳燥烈，热则伤肺，加之以劳倦伤脾，脾为肺母，母病而子失其所养。女色伤肾，肾为肺子，子伤必盗母气以自奉，而肺愈虚矣。法当从清暑益气汤例而增减之。以人参二钱或三钱，白术、白芍、麦门冬、茯苓各一钱，生地、归身各八分，黄柏、知母、陈皮、神曲各七分，少加甘草五分，煎服。", "15253": "罗汝声，年五十余，形瘦而黑，理疏而涩，忽病腹痛，午后愈甚。医曰：此气痛也。治以快气之药，痛亦加。又曰：午后血行阴分，加痛者血滞于阴也。煎以四物汤加乳、没，服之亦不减。诣居士诊之，脉浮细而结，或五、七至一止，或十四五至一止。经论止脉渐退者生，渐进者死。今止脉频则反轻，疏则反重，与《脉经》实相矛盾。居士熟思少顷，曰得之矣。止脉疏而痛甚者，以热动而脉速，频而反轻者，以热退而脉迟故耳，病属阴虚火动无疑。且察其病，起于劳欲。劳则伤心而火动，欲则伤肾而水亏。以人参、白芍补脾为君，熟地、归身滋肾为臣，黄柏、知母、麦门冬清心为佐，山楂、陈皮行滞为使，人乳、童便或出或入，惟人参渐加至四钱或五钱，遇痛进之即愈。", "15254": "临河程正刚，年三十余，形瘦体弱，忽病上吐下泻，勺水粒米不入口者七日，自分死矣。居士诊脉，八至而数，曰：当仲夏而得是脉者，暑邪深入也。上吐下泻，不纳水谷，邪气自甚也，宜以暑治焉。", "15255": "程福仁，体肥色白，年近六十。痰喘声如曳锯，夜不能卧。居士诊之，脉浮洪，六、七至，中或有一结，曰：喘病脉洪可治也。脉结者，痰凝经隧耳，宜用生脉汤加竹沥。服之至十余帖，稍定。患者嫌迟，更医服三拗汤，犹以为迟，益以五拗汤，危矣。其弟曰：汪君王道医也，奈何欲速至此？于是复以前方服至三四十帖，病果如失。", "15256": "一妇，形肥色淡紫，年几三十，艰于育子。居士脉之，两尺脉皆沉微，法当补血。以形言之，肥人气虚，亦当补气。遂令多服八物汤，仍以补阴丸加参、耆，空腹吞之。三月余有孕。复为诊之，两尺如旧。以理论之，孕不当有。昔人云脉难尽凭，殆此类欤。", "15257": "侍御槐塘景之，形肥色黑，素畏热而好饮，年三十余。忽病自汗如雨，四肢俱痿，且恶寒，小便短赤，大便或溏或结，饮食亦减。医作风治，用独活寄生汤、小续命汤，弗效。五月间，居士往视，脉沉细而数，约有七至。曰：此痿证也，丹溪云断不可作风治。经云痿有五，皆起于肺热。只此一句，便晓其治之法矣。经又云治痿独取阳明。盖阳明胃与大肠也。胃属土，肺属金，大肠亦属阳金，金赖土生，土亏金失所养而不能下生肾水，水涸火盛，肺愈被伤，况胃主四肢，肺主皮毛。今病四肢不举者，胃土亏也；自汗如雨者，肺金伤也。故治痿之法，独取阳明而兼清肺金之热，正合东垣清燥汤。服百帖，果愈。", "15258": "郑村汪钿，长瘦体弱，病左腹痞满。谷气偏行于右，不能左达，饮食减，大便滞，居士诊其脉，浮缓而弱，不任寻按。曰：此土虚木实也。用人参补脾，枳实泄肝，佐以芍药引金泄木，辅以当归和血润燥，加厚朴、陈皮以宽胀，兼川芎、山栀以散郁。服十余帖，稍宽。因粪结滞，思饮人乳，居士曰：只恐大便滑耳。果如言。遂辞乳媪，仍服前药，每帖加人参四五钱。后思香燥物。曰：脾病气结，香燥无忌也。每日因食香燥榧一二十枚，炙蒸饼十数片，以助药力，年余而安。", "15259": "庠生罗君辅，年三十余。尝因冒寒发热，医用发表不愈，继用小柴胡，热炽汗多，遂昏昏愦愦，不知其身之所在，卧则如云之停空，行则如风之飘毛，兼又消谷善饥，梦遗诸证。居士观其形类肥者，曰：此内火燔灼而然，虚极矣。诊其脉皆浮洪如指。曰：《脉经》云脉不为肝衰者，死，在法不治。所幸者，脉虽大，按之不鼓，形虽长，而色尚苍，可救也。医以外感治之，所谓虚其虚，误矣。经云邪气乘虚而入，宜以内伤为重。遂以参、耆、归、术大剂，少加桂、附，服十余帖，病减十之二三。再除桂、附加芍药、黄芩，服十余贴，病者始知身卧于床，足履于地，自喜曰可不死矣。服久果起。", "15260": "槐充胡本修，监生，年逾三十。形肥色白，酒中为人折辱，遂病心恙，或持刀，或逾垣，披发大叫。居士诊之，脉濡缓而虚，按之不足，曰：此阳明虚也，宜变例以实之，庶几可安。先有医者，已用二陈汤加紫苏、枳壳等药进二三帖矣。闻居士言，即历声曰：吾治将瘥，谁敢夺吾功乎？居士遂告回。", "15261": "越十余年，因久坐□□，渐次痛延左脚及右脚，又延及左右手，不能行动。或作风治而用药酒，或作血虚而用四物，一咽即痛，盖覆稍热及用针砭，痛益甚。煎服熟地黄，或吞虎潜丸，又加右齿及面痛甚。季秋，始请居士诊之，脉濡缓而弱，左脉比右较小，或涩，尺脉尤弱。曰：此痿证也。彼谓痿证不痛，今以肢痛为痿，惑也。居士曰：诸痿皆起于肺热，君善饮，则肺热可知。经云治痿独取阳明。阳明者，胃也。胃主四肢，岂特脚耶？痿兼湿重者，则筋缓而痿软，兼热多者，则筋急而作痛。因检《橘泉翁传》示之，始信痿亦有痛也。又，经云酒客不喜甘。熟芐味甘，而虎潜丸益之以蜜，则甘多助湿而动胃火，故右齿面痛也。遂以人参二钱，黄耆钱半，白术、茯苓、生地黄、麦门冬各一钱，归身八分，黄柏、知母各七分，甘草四分，煎服五帖，病除，彼遂弃药。季冬复病，仍服前方而愈。", "15262": "溪南吴道济妻，年逾三十，无子。诊视其脉近和，惟尺部觉洪滑耳。问得何病？曰：子宫有热，血海不固尔。道济曰：然。每行人道，经水则来，乃喻以丹溪大补丸，加山茱萸、白龙骨止涩之药，以治其内，再以乱发灰、白矾灰、黄连、五倍子为末，用指点水染入阴户，以治其外。依法治之，果愈而孕。", "15263": "吴传芳妻，年逾五十。病左脚膝挛痛，不能履地，夜甚于昼，小腹亦或作痛。诊其脉浮细缓弱，按之无力，尺脉尤甚，病属血衰。遂以四物汤加牛膝、红花、黄柏、乌药。连进十余帖而安。", "15264": "吴良鼎，形瘦而苍，年逾二十。忽病咳嗽，咯血，兼吐黑痰，医用参、术之剂，病愈甚。居士诊之，两手寸关浮软，两尺独洪而滑，此肾虚火旺而然也。遂以四物汤加黄柏、知母、白术、陈皮、麦门冬之类。治之月余，尺脉稍平，肾热亦减。依前方再加人参一钱，兼服枳术丸加人参、山栀以助其脾，六味地黄丸加黄柏以滋其肾，半年痊愈。", "15265": "吴福孙之媳，年几三十。因夫在外纳宠，过于忧郁，患咳嗽，甚则吐食呕血，兼发热、恶寒、自汗，医用葛氏保和汤不效。居士诊其脉，皆浮濡而弱，按之无力，晨则近驶，午后则缓。曰：此忧思伤脾病也。脾伤则气结，而肺失所养，故咳嗽。家人曰：神医也。遂用麦门冬、片黄芩以清肺，陈皮、香附以散郁，人参、黄耆、芍药、甘草以安脾，归身、阿胶以和血。服数帖，病稍宽。后每帖渐加人参至五六钱，月余而愈。", "15266": "竦塘黄崇贵，年三十余。病水肿，面光如胞，腹大如箕，脚肿如槌，饮食减少。居士诊之，脉浮缓而濡，两尺尤弱。曰：此得之酒色，宜补肾水。家人骇曰：水势如此，视者不曰通利，则曰渗泄，先生乃欲补之水，不益剧耶？曰：经云水极似土，正此病也。水极者，本病也；似土者，虚象也。今用通利渗泄而治其虚象，则下多亡阴，渗泄耗肾，是愈伤其本病而增土湿之势矣。岂知亢则害、承乃制之旨乎？遂令空腹服六味地黄丸，再以四物汤加黄柏、木通、厚朴、陈皮、参、术。煎服十余帖，肿遂减半，三十帖痊愈。", "15267": "侍御泾县萧君吉夫，年逾五十，患眩晕，溲涩、体倦、梦遗、心跳、通夜不寐，易感风寒，诸药俱不中病。居士诊之，脉或浮大，或小弱无常，曰：此虚之故也。丹溪云肥人气虚，宜用参、耆，又云黑人气实，不宜用之。果从形欤，抑从色欤？居士熟思之，色虽黑而气虚，当从形治。遂以参、耆为君，白术、茯苓、木通为臣，山栀子、酸枣仁、麦门冬为佐，陈皮、神曲为使，煎服。晨吞六味地黄丸，夜服安神丸，逾年病安。", "15268": "休宁程勇，年三十余。久病痫症，多发于晨盥时，或见如黄狗走前，则昏瞀仆地，手足瘛疭，不省人事，良久乃苏，或作痰火治而用芩连二陈汤，或作风痰治而用全蝎姜蚕寿星丸，或作痰迷心窍而用金箔镇心丹，皆不中病。居士诊之，脉皆缓弱颇弦，曰：此木火乘土之病也。夫早晨阳分，而狗阳物，黄土色，胃属阳土，虚为木火所乘矣。经云诸脉皆属于目，故目击异物而病作矣。理宜实胃泻肝而火自息。《本草》云泄其肝者，缓其中。遂以参、耆、归、术、陈皮、神曲、茯苓、黄芩、麦门冬、荆芥穗。煎服十余帖，病减，再服月余而安。", "15269": "学士篁墩程先生，形色清癯，肌肤细白，年四十余。患眩晕，四肢倦怠，夜寐心悸言乱，或用加减四物汤甘寒以理血，或用神圣复气汤辛热以理气，又或作痰火治，或作湿热治，俱不效。遣书请居士诊之，脉皆沉细不利，心部散涩。曰：此阴脉也。脾与心必因忧思所伤，宜仿归脾汤例加以散郁行湿之药。先生喜曰：真切真切。服数帖，病果向安。一夕，因懊恼忽变，急请诊视。脉三五不调，或数或止，先生以为怪脉，居士曰：此促脉也，无足虑焉。曰：何如而脉变若此？曰：此必怒激其火然也。先生哂曰：子真神人耶！以淡酒调木香调气散一匕，服之，其脉即如常。", "15270": "汊口孙以德，形肥色紫，年逾五十，颈项少阳之分，痈肿如碗。居士诊之，脉浮小而滑，乃语之曰：少阳多气少血之经，宜补。若用寻常驱热败毒之药，痈溃之后难免别患。彼以为然。遂煎参、耆、归、术膏一二斤，用茶调服无时，盖茶能引至少阳故也。旬余，痈溃而起。", "15271": "程贵英，形长而瘦，色白而脆，年三十余。得奇疾，遍身淫淫循行如虫，或从左脚腿起，渐次而上至头，复下于右脚，自觉虫行有声之状，召医诊视，多不识其为何病。居士往诊，其脉浮小而濡，按之不足，兼察其形、视其色、参诸脉，知其为虚症矣。《伤寒论》云身如虫行，汗多亡阳也。遂仿此例，而用补中益气汤，多加参、耆，以酒炒黄柏五分佐之。服至二三十帖，遂愈。", "15272": "孙杲，年二十余。病咳嗽，呕血、盗汗，或肠鸣作泻，午后发热。居士往视，其脉细数，无复伦次，因语之曰：《难经》云七传者，逆经传也。初因肾水涸竭，是肾病矣。肾邪传之于心，故发热而夜重；心邪传之于肺，故咳嗽而汗泄；肺邪传之于肝，故胁痛而气壅；肝邪传之于脾，故肠鸣而作泄；脾邪复传于肾，而肾不能再受邪矣。今病兼此数者，死不出旬日之外矣。果如期而逝。", "15273": "野山汪盛妻，年逾四十，形色苍紫，忽病血崩，诸医莫治。或用凉血，或用止涩，罔效。居士察其六脉，皆沉濡而缓，按之无力。以脉论之，乃气病，非血病也，当用甘温之剂，健脾理胃，庶几胃气上腾，血行经络，无复崩矣，遂用补中益气汤多加参、耆，兼服参苓白术散，崩果愈。", "15274": "逢村王恕，年二十余。因水中久立过劳，病疝痛。痛时腹中有磊块，起落如滚浪，其痛尤甚。居士诊其脉，皆弦细而缓，按之似涩，曰：此血病也。考之方书，疝有七，皆不宜下，所治多用温散之药，以气言之，兹宜变法治之，乃用小承气加桃仁下之，其痛如失。三日痛复作，比前加甚。脉之，轻则弦大，重则散涩。思之，莫得其说。问曾食何物？曰：食鸡卵二枚而已。曰：已得之矣。令以指探喉中，吐出令尽，而痛解矣。", "15275": "黄豹，年逾六十。病气喘，顾谓其子曰：愿得石山先生来，吾无憾矣。其子夤夜舁至，视其脉皆萦萦如蛛丝。问曰：吉凶何如？居士久之，若有难言者。彼悟曰：吾不得济矣。是夜书讫标书五纸付其子而逝。", "15276": "大坑方细，形瘦，年三十余。忽病腹痛，磊块起落如波浪然，昼轻夜重。医用木香、沉香磨服，及服六君子汤，皆不验。居士诊其脉，浮缓弦小，重按似涩。曰：此血病也，前药作气治谬矣。彼谓血则有形，发时虽有块磊，痛或则消而无迹，非气而何？盖不知有形者，血积也；无形者，血滞也。滞视积略轻耳，安得作气论耶？若然，则前药胡为不验？遂用四物汤加三棱、蓬术、乳香、没药。服之，痛遂脱然。", "15277": "一妇，形长色紫，妊五月矣。托居士脉之，以别男女。曰：脉右大于左。《脉诀》云左大为男，右为女，今脉右大当是女耶。彼则喜曰：我男胎矣。往岁有妊时，尊甫先生诊之，亦谓右脉浮大，当是女孕，后生男。今妊又得是脉，可知为男矣。后果生男。居士曰：脉书但道其常，莫能尽其变此医所以贵乎望、闻、问、切也。", "15278": "九江钞厂主事郑君希大，瘦长而色青白，性急刚果，年三十余，病反胃，每食入良久复出，又嚼又咽，但不吐耳。或作气治而用丁香、藿香，或作痰治而用半夏、南星，或作寒治而用姜附，药俱罔效。居士脉之，皆缓弱稍弦。曰：非气非痰，亦非寒也，乃肝凌脾之病。经云能合脉色，可以万全。君面青性急，肝木甚也，脉缓而弱，脾土虚也。遂用四君子汤加陈皮、神曲，少佐姜炒黄连，以泄气逆。服月余而愈。", "15279": "钞厂陈库子，其父老年患背痈。居士诊视，脉洪缓而濡，痈肿如碗，皮肉不变，按之不甚痛，微发寒热，乃语之曰：若在膊胛，经络交错、皮薄骨高之处，则难矣。今肿去胛骨下掌许，乃太阳经分，尚可治。遂用黄耆五钱，当归、羌活、甘草节各一钱。先令以被盖暖，药热服，令微汗。寝熟肿消一晕，五服遂安。时居士舟去半日，其子驾小艇载鹅米追及，拜曰：吾父更生，故来谢耳。", "15280": "居士弟樟之妻，瘦长色苍，年三十余。忽病狂言，披发倮形，不知羞恶，众皆谓为心风。或欲饮以粪清，或欲吐以痰药。居士诊其脉，浮缓而濡，乃语之曰：此必忍饥，或劳倦伤胃而然耳。经云二阳之病发心脾，二阳者，胃与大肠也。忍饥、过劳，胃伤而火动矣，延及心脾，则心所藏之神，脾所藏之意，皆为之扰乱，失其所依归矣，安得不狂？内伤发狂，阳明虚也，法当补之。遂用独参汤加竹沥，饮之而愈。", "15281": "福州李俊，年三十余。忽病渴热昏闷，面赤倦怠。居士诊之，脉皆浮缓而弱，两尺尤甚，曰：此得之色欲，药宜温热。其弟曰：先生之言诚是也，但病热如此，复加热药，惑矣，居士曰：经云寒极生热。此症是也。肾虚寒者，本病也；热甚者，虚象也。譬之雷火，雨骤而火愈炽，日出火斯灭矣。遂以附子理中汤煎热冷服，三帖热渴减半，再服清暑益气汤，十余帖而安。", "15282": "李一之，年近四十，病反食，与近邻二人脉病颇同。居士曰：二人者，皆急于名利，惟一之心宽可治。遂以八物汤减地黄，加藿香为末，用蜜、韭汁调服而愈。二人逾年果没。", "15283": "一之妻，病痢瘦弱，久伏床枕，粥食入胃，即腹痛呕吐，必吐尽所食乃止。由是粒食不下咽者，四十余日，医皆危之。居士诊曰：病与脉应，无虑也。不劳以药，惟宜饲以米饮，使胃常得谷气，白露节后，病当获安。如期果愈。", "15284": "其侄春，年十七时，秋间病酒，视为小恙。居士诊之曰：脉危矣。彼不为然，别请医治而愈，惟遍身疮痍。十月间，复造诣之，其侄出揖，以示病已获安，意谓向之诊视欠精也。复为诊之曰：不利于春。至立春果卒。", "15285": "汪世昌，形肥色紫，年逾三十。秋间病恶寒发热，头痛，自汗，恶心，咯痰，恶食，医以疟治。居士诊之，脉浮濡而缓，右寸略弦，曰：非疟也，此必过劳伤酒所致。饮以清暑益气汤，四五服而愈。", "15286": "九都许僖，形魁伟，色黑善饮，年五十余。病衄如注，嗽喘不能伏枕，医以四物汤加麦门冬、阿胶、桑白皮、黄柏、知母，进入愈甚。居士诊之，脉大如指。《脉经》云：鼻衄失血沉细宜，设见浮大即倾危。据此，法不救，所幸者，色黑耳。脉大非热，乃脉气虚也。此金极似火之病，若补其肺气之虚，则火自退矣。医用寒凉降火之剂，是不知《素问》「亢则害，承乃制」之旨。遂用人参三钱，黄耆二钱，甘草、白术、茯苓、陈皮、神曲、麦门冬、归身甘温之药进之，一帖病减，十帖病痊。后十余年，复诊之，语其子曰：越三年，寿止矣。果验。", "15287": "一妇，长瘦色黄白，性躁急，年三十余。常患坠胎，已七八见矣。居士诊之，脉皆柔软无力，两尺虽浮而弱，不任寻按。曰：此因坠胎大多，气血耗甚，胎无所滋养，故频坠。譬如水涸而禾枯，土削而木倒也。况三月、五月正属少阳火动之时，加以性躁而激发之，故坠多在三、五、七月也。宜大补汤去桂加黄柏、黄芩煎服，仍用研末蜜丸服之，庶可存全。服半年，胎果固而生二子。", "15288": "一妇，年逾三十，久疟。疟止有妊五月，忽病腹痛，泄泻，头痛，发渴，右脉浮滑，左侧细滑。居士以四君子汤加石膏、黄芩，煎服二帖，头痛、泄泻虽除，又加肛门胀急，其夫欲用利药。居士曰：耐烦二日，候胃气稍完，然后以四物汤加酒大黄、槟榔，利三四行，胀急稍宽，再服枳术丸加黄芩、归身，一料病去，而胎亦无损。", "15289": "一女，年十五。病心悸，常若有人捕之，欲避而无所也。其母抱之于怀，数婢护之于外，犹恐恐然不能安寝。医者以为病心，用安神丸、镇心丸、四物汤不效。居士诊之，脉皆细弱而缓，曰：此胆病也。用温胆汤服之而安。", "15290": "居士之甥汪宦，体弱色脆，常病腹痛，恶寒发热，呕泄倦卧，时或吐虫，至三五日或十数日而止。或用丁沉作气治，或用姜附作寒治，或用消克作积治，或用燥烈作痰治，罔有效者。居士诊视，脉皆濡小近驶，曰：察脉观形，乃气虚兼郁热也。遂用参、耆、归、术、川芎、茯苓、甘草、香附、陈皮、黄芩、芍药，服之而安。", "15291": "胡本清甫，形肥色紫，年逾七十。忽病瞀昧，但其目系渐急，即合眼昏懵如瞌睡者，头面有所触皆不避，少顷而苏。问之，曰：不知也。一日或发二三次，医作风治，病加重。居士诊其脉，病发之时，脉皆结止，苏则脉如常，但浮虚耳，曰：此虚病也。盖病发而脉结者，血少气劣耳。苏则气血流通，心志皆得所养，故脉又如常也。遂以大补汤去桂，加麦门冬、陈皮，补其气血而安。", "15292": "石门陈奈，形短颇肥，色白近苍，年逾二十。因祈雨过劳，遂病手足瘛疭，如小儿发惊之状，五日勺水不入口，语言艰涩。或作痰火治，或作风症治，皆不验。居士视之，脉皆浮缓而濡，按之无力。曰：此因劳倦伤脾，土极似木之病也。经云：「亢则害，承乃制」是矣。夫五行自相制伏，平和之时，隐而不见，一有所负，则所胜者见矣。今病脾土受伤，则土中之木发而为病，四肢为之瘛疭也。盖脾主四肢，风主动故也。若作风痰治之，必致于死，惟宜补其脾土之虚，则肝木之风自息矣。遂以参、术为君，陈皮、甘草、归身为臣，黄柏、麦门冬为佐。经云泄其肝者，缓其中，故用白芍为使，引金泄木，以缓其中。一服，逾宿遂起，服至十余帖全安。", "15293": "陈校，瘦长而脆，暑月过劳，饥饮烧酒，遂病热汗，昏懵语乱。居士视之，脉皆浮小而缓，按之虚豁。曰：此暑伤心、劳伤脾也。盖心藏神，脾藏意，二藏被伤，宜有此症。法宜清暑以安心，益脾以宁意。遂用八物汤加麦门冬、山栀子、陈皮，煎服十余帖而愈。", "15294": "竹园陈某，形瘦而苍，年逾五十。居士诊视其脉，皆弦涩而缓，尺脉浮而无根。曰：尺脉当沉而反浮，所主肾水有亏，其余脉皆弦涩而缓者，弦脉属木，涩为血少，缓脉属脾。以脉论之，似系血液枯槁，而有肝木凌脾之病，非膈则噎也。问之，胸膈微有碍。曰：不久膈病成矣，病成非药可济。后果病膈而卒。", "15295": "陈锐，面黑形瘦，年三十余，患鼻衄，发热恶寒，消谷善饥，疲倦或自汗、呕吐。居士诊之，脉细且数，约有六至。曰：丹溪论瘦黑者、鼻衄者、脉数者，参、耆皆所当禁固也，然不可执为定论。《脉经》云：数脉所主，其邪为热，其症为虚。宜人参三钱，黄耆二钱，生甘草、陈皮、黄柏、白术、归身、生地黄、山栀子、生芍药递为佐使。服之果安。", "15296": "南畿提学黄公，年四十余。溲精久之，神不守舍，梦乱心跳。用清心莲子饮无效，又取袖珍方，治小便出髓条药服之，又服小菟丝子丸，又服四物汤加黄柏，俱无效。居士诊视，一日之间，其脉或浮濡而驶，或沉弱而缓。曰：脉之不常，虚之故也。语曰无而为有，虚而为盈，难乎有恒，此之谓乎。其症初因肾水有亏，以致心火亢极乘金，木寡于畏而侮其脾，此心、脾、肾三经之病也。理以补脾为主，兼之滋肾养心，病可痊也。方用人参为君，白术、茯神、麦门冬、酸枣仁、山栀子、生甘草为佐，莲肉、山楂、黄柏、陈皮为使，其他牡蛎、龙骨、川芎、白芍、熟芐之类，随其变症而出入之。且曰：必待人参加至五钱病脱。公闻言，疑信相半。服二十余日，人参每服用至三钱，溲精觉减半矣。又月余，人参加至五钱病全减。公大喜曰：初谓人参加至五钱，病脱，果然。医岂神乎！凡此皆活法，非定方也。其妙如此，殆非心通造物而执其死生之柄者欤！", "15297": "居士所著有《重集脉诀刊误》二卷，《内经补注》若干卷，《本草会编》若干卷，惠及后学，尤为不浅，然非通儒者，敢望其门墙也哉！", "15298": "兹取丹溪尝治验者以证之。一人咳嗽、恶寒、胸痞、口干、心微痛，脉浮紧而数，左大于右。盖表盛里虚，闻其素嗜酒肉有积，后因行房涉寒，冒雨忍饥，继以饱食。先以人参四钱，麻黄连根节钱半，与二三帖，嗽止寒除。改用厚朴、青、陈皮、瓜蒌、半夏为丸，参汤送下，二十服而痞除。夫既咳嗽嗜酒，不可谓肺无火也，复因行房感冒，不可谓阴不虚也，初服人参四钱，再用参汤送药，不可谓不多服也，何如不死？", "15299": "又一壮年，因劳倦不得睡，咳痰如脓，声不出。时春寒，医与小青龙汤，喉中有血丝，腥气逆上，渐有血线自口右边出，昼夜十余次。脉弦大散弱，左大为甚。此劳倦感寒，强以辛甘燥热之剂动其血，不治恐成肺痿。遂以参、耆、归、术、芍药、陈皮、生甘草、带节麻黄，煎入藕汁。服二日，嗽止。去麻黄与四日，血除。但脉散未收，食少倦甚，前药除藕汁加黄芩、砂仁、半夏，半月而愈。夫嗽痰如脓，声不出者，不可谓肺不热也，又以甘辛燥热动其血，不可谓血不病也，服参、耆亦不可谓不多也，又复何如而不死？", "15300": "丹溪曰苍黑之人多服参、耆，恐助火邪而烁真阴，肥白之人多服最好，此固然矣。考其尝治一人，形瘦色黑，素多酒不困，年半百，有别馆。一日，大恶寒发战，言渴不饮，脉大而弱，右关稍实略数，重则涩。以王氏观之，以形色论之，正合滋阴泻火之法。而丹溪谓此酒热内郁不得外泄，由表热而虚也。用黄耆二两，干葛一两，煎饮之，大汗而愈。既不以苍黑忌用参、耆为拘，亦不以酒色伤阴忌服参、耆为禁。是知丹溪立言以示人者，法之常，施治而不以法为拘者，善应变也。王氏但知其立法之常，而未察其治不以法为拘之变。故于参、耆等剂，每每畏首畏尾，若不敢投，盖亦未之考也。", "15301": "《杂著》所制诸方，虽未尝尽废参、耆，察其用处，必须脉之细微而迟者，方始用也。然而东垣、丹溪之用参、耆，亦不专在于此。东垣曰：血虚脉大，症象白虎，误服白虎汤者必死。乃用黄耆六钱，当归一钱，名曰当归补血汤，以治之。是血虚脉大，东垣亦尝用黄耆矣。丹溪曰：一人滞下，一夕昏仆，目上视，溲注，汗泄，脉大无伦，此阴虚阳暴绝也。盖得之病后酒色，急灸气海，服人参数斤而愈。是阴虚脉大，丹溪亦尝用人参矣，岂必脉之细微迟者而后用哉？", "15302": "考之《本草》，仲景治亡血脉虚，以人参补之，取其阴生于阳，甘能生血，故血虚气弱，仲景以人参补之。是知人参不惟补气，亦能补血。况药之为用又无定体，以补血佐之则补血，以补气佐之则补气。是以黄耆虽专补气，以当归引之，亦从而补血矣。故东垣用黄耆六钱，只以当归一钱佐之，即名曰补血汤。可见黄耆功力虽大，分两虽多，为当归所引，不得不从之补血矣。矧人参功兼补血者耶。人参性味不过甘温，非辛热比也，稍以寒凉佐之，必不至助火如此之甚，虽日积温成热，若中病即已，亦无是也。夫芎、归味辛甘温，世或用治劳热血虚之病，并无所疑。然辛主耗散，本非血虚所宜。彼人参虽甘温，而味不辛，比之芎、归，孰轻而孰重哉？", "15303": "或曰：经言水之精气为营，营行脉中，不能行于脉外，无分昼夜，周流不休，定息数应漏刻，属于阴也。食之浊气为卫，卫行脉外，不能入于脉中，昼但行阳二十五度，夜则行阴二十五度，不与营同道，不与息数应，属于阳也。《内经》所论营卫如此，未闻营中有卫也。予曰：《内经》所论，以阴阳对待言，特举其大者耳。细而分之，营中亦自有卫也。《易》曰阳奇阴偶，故悍卫为阳而奇，营血属阴则两也。", "15304": "或曰：营中之卫亦分昼夜内外乎？余曰：无分昼夜而内外相通。营行脉中而亦行脉外，凡皮肤有伤，不待内及于经，即便血出，可见亦行于脉外矣。卫行脉外，亦行于脉中，盖血属阴而主静，苟非气贯其中，安能周流而灌溉？可见亦行于脉中矣。", "15305": "或曰：营中有卫，有所本乎？予曰：本《灵枢》也。《灵枢》曰人受气于谷，谷入于胃，以传于肺，五藏六府皆以受气，气之清者为营，浊者为卫。营行脉中，卫行脉外，营周不休。又曰其浮气循于经者为卫气，其精气行于经者为营气。又曰营卫者，精气也。又曰营气卫气皆津液之所成。是《灵枢》所言，皆营卫同一气。营卫一气，则营中有卫可知矣，故曰营与卫异名而同类是也。《内经》分而言之，则荣卫不同道，《灵枢》合而言之，则营卫同一气也。", "15306": "子华子有言：医者，理也，意也。盖理明则意得，意得则审脉处方，无所施而不中。于以称国工不难，吾宗杏轩先生其人也。先生性颖悟，工诗，隐于医，为人疗疾，应手辄奏效。余同年鲍觉生，尝遘危疾，赖先生起之，母称道不去口。一日出先生所著医案，属余弁言，余受而读之，见其审脉处方，深得古人四然二反之理，而神明其意，以是叹先生之艺之精，非寻常执经方习针石者所能望其项背也。然则是书其桐君之别录，越人之逸篇也夫。", "15307": "丹溪云：产后当以大补气血为主，他证从末治之。言固善矣，然事竟有不可执者。乾隆乙巳仲夏，岩镇许静翁夫人病，延诊。据述：产后十二朝，初起洒淅寒热，医投温散不解，即进温补，病渐加重，发热不退，口渴心烦，胸闷便闭。时值溽暑，病人楼居，闭户塞牖。诊脉弦数，视舌苔黄。告静翁曰：夫人病候，乃产后感邪，医药姑息，邪无出路，郁而为热。今日本欲即用重剂清解，恐生疑畏，且与一柴胡饮试之，但病重药轻，不能见效，明早再为进步。并令移榻下楼，免暑气蒸逼。诘朝视之，脉证如故，舌苔转黑。众犹疑是阴证。予曰：不然。阴阳二证，舌苔皆黑。阳证舌黑，黑而润滑，病初即见，肾水凌心也。阴证舌黑，黑而焦干，热久才见，薪化为炭也。前方力薄，不能胜任，议用白虎汤加芩连。饮药周时，家人报曰：热退手足微冷。少顷又曰：周身冷甚。静翁骇然，亦谓恐系阴证，服此药必殆。予曰无忧。果系阴证，前服温补药效矣，否则昨服柴胡饮死矣，安能延至此刻。此即仲景所谓热深厥亦深也，姑待之。薄暮厥回复热，烦渴欲饮冷水，令取井水一碗，与饮甚快。予曰：扬汤止沸，不若釜底抽薪，竟与玉烛散下之。初服不动，再剂便解黑矢五六枚，热势稍轻，改用玉女煎数剂，诸候悉平，调养经月而愈。众尚虑其产后凉药服多，不能生育。予曰无伤。经云有故无殒，至今廿载，数生子女矣，壬戍岁，与订朱陈焉。予来岩镇谭医，自静翁始。", "15308": "刘少君年近三旬，春间由都来徽，抱疾数月，食减形倦，心悸少寐，浮火上升，间或见血。医云：肝肺火盛。药投清降，屡治不效。金文舫中翰荐延予诊，谓曰：病由先天不足，心脾内亏所致。丹溪云：虚火可补，实火可泻。虚以实治，宜乎无功。拟黑归脾汤合生脉散，数服稍应。复诊令照原方再进，诸恙渐平，接服丸药。次春北上，秋归晤之，状貌丰腴，前病如失。", "15309": "鲍宫詹未第时，游昆陵幕，抱疴半载，百治不痊，因买舟回里，延予治之。望色，颊赤面青，诊脉虚弦细急。自述数月来通宵不寐，闻声即惊，畏见亲朋，胸膈嘈痛，食粥一盂，且呕其半，粪如羊矢，色绿而坚，平时作文颇敏，今则只字难书，得无已成隔证耶。予曰：君质本弱，兼多抑郁，心脾受伤，脾不能为胃行其津液，故食阻。二肠无所禀受，故便干。若在高年，即虑成隔，今方少壮，犹可无虞。方仿逍遥、归脾出入，服至数十剂，病尚未减，众忧之。予曰：内伤日久，原无速效，况病关情志，当内观静养，未可徒恃药力，续得弄璋之喜，予曰：喜能胜忧，病可却矣。半月后果渐瘥，仍劝往僧斋静养，共服煎药百剂，丸药数斤乃瘳。因更号觉生，盖幸其殆而复生也。", "15310": "洪楚峰孝廉病，遣使延诊。问其使曰：何候?曰：中风。问年几何。曰：耋矣。予曰：殆证也。辞不往，使者强之。将及门，闻邻人语云：病将就木，医来何为。若能起之，其卢扁乎。入视，身僵若尸，神昏不语，目阖口张，声鼾痰鸣，遗尿手撒，切脉虚大，歇至。予曰：此中脏也。高年脏真已亏，况见五绝之候，不可为矣。其弟曰：固知病不可为，然尚有一息之存，安忍坐视，求惠一七，姑冀万一。勉处地黄饮子合大补元煎，以为聊尽人事而已，讵意服药后，痰平鼾定，目开能言，再剂神清食进，复诊更加河车鹿茸，脉证大转。续订丸方付之，半载后因视他病，过其家，见翁矍铄如常矣。", "15311": "萃翁公郎，禀质向亏，诵读烦劳，心神伤耗。初病浮火上升，继则阳强不密，精时自下。诊脉虚细无力，方定六味地黄汤。除茯苓泽泻，加麦冬五味远志枣仁牡蛎芡实，期以功成。百日服药数剂未应，更医病状依然，复召诊视。予曰：此水火失济象也，岂能速效。仍用前方再加龙骨蒺藜桑螵蛸莲蕊须，合乎滑者涩之之意。守服两旬，虚阳渐敛，精下日减。但病久形羸食少，究由脾胃有亏。经云：肾者主水，受五脏六腑之精而藏之，是精藏于肾，非生于肾也。譬诸钱粮，虽贮库中，然非库中自出。须补脾胃化源，欲于前方内参入脾药，嫌其杂而不专，乃从脾肾分治之法，早用参苓白术散，晚间仍进前药。服之益效，续拟丸方，调养而瘳。", "15312": "余氏子八龄，形瘦阴虚，夏患瘅疟，愈后失调。值秋燥时，偶作寒热，幼科泛投疏散之剂，转致躁扰搐搦，危证百出。余翁求视，以决死生。予见其儿，肢掣痰鸣，身热烦躁，势颇危笃。诊脉神根未败，予曰：疾固剧矣，然尚可生。翁喜叩其说，予曰：惊风一证，时世无传，小儿受害，不可胜数。喻氏虽辟其谬，特重外感，轻内伤，经曰：东方青色，入通于肝。其病发惊骇，医昧病因，用方通套，偶遇强实而应者有之，特此儿所患，本非外因，良由肾水下虚，肝失所养，木逢金制，故作寒热。状似外感，误投疏散，津液更伤。因而肝风鼓动，变幻若此。予尚望其生者，因其脉犹未败耳。方拟六味地黄汤，滋水生木，更加归芍甘草钩藤之属，和阳熄风，风熄而惊自定矣。翁闻言甚悦，服药痰平热退，不搐不烦，另制膏子药与服全愈。", "15313": "典翁外孙女年三岁，病经旬日，发热便泻，初服疏导药不应，忽作抽掣，复请前医视之，云系动惊，更加金药琥珀。典翁邀予商酌。望其儿，色白神疲，头身虽热，四肢冰冷，按脉沉细无力，谓曰：病乃质亏感邪，便泻多日，脾元受伤，以致肝风内动。金石之品，不可用也，拟六君子汤加炮姜桂枝，服药热退泻稀，再服肢温泻止，惊亦不作。", "15314": "玉翁孙女年四龄，夏间感受暑风，热发不退，肢搐体僵，目斜口啮。予曰：此暑风急惊也。暑喜伤心，风喜伤肝，心肝为脏，脏者藏也，邪难入，亦复难出，证虽可治，然非旦晚能愈。且内服煎药，仍须参以外治之法，令挑黄土一石，捶细摊于凉地，上铺荷叶，再用蒲席与儿垫卧，慎勿姑息。俟热退惊定，方可抱起，药用防风、香薷、柴胡、钩藤、连翘、川连、石膏、木通、生甘草，引加鲜菖蒲扁荚叶，清暑疏风，一切金石之类，概置不用。盖病因暑风生热，热生惊，金石镇坠锢邪，最为害事，依法服药，守至七朝，热退惊定。渠家以为病愈，恐久卧凉地不宜，将儿抱置床上，当晚热复发。予令仍放土上，热即退。尚不之信，次晚复抱起，热又发，乃问所由。予曰：邪未净也。又问邪何日可净，予曰：伤寒以十二朝为经尽，大概亦需此期。届期上床安卧，不复热矣。药换养阴，调和肝胃，诸恙皆平。惟喑哑不能言，其母忧甚。予曰：无伤，将自复。阅三月，果能言。予按此证，小儿夏间患者甚多，治不如法，往往不救，较之寻常惊证特异。考诸古训，鲜有发明，惟近时吾郡许宣治先生，叙有十则，辨论颇详。至若卧置土上，垫用荷叶一法，犹未言及。予治此证，每用此法获验，盖土能吸热，荷叶清暑故耳。特其惊之作，必由热盛而成。然有一热即作者，有热二三日而作者，其状悉皆昏迷搐搦，肢厥咬牙，轻者时昏时醒，重者七日方苏，极重者至十二朝始转。若由吐泻而起，脉细质亏，不能受清凉者，多不可治。倘不因吐泻，一热即惊，脉洪质实。能受清凉者，十中可救七八，勿视其危而弃之也。再按惊后喑哑一证，诸书亦未论及，每见证轻者，病后多无此，患重者有之。然有喑至一两月愈者，有三四月愈者，有终身不愈者。予堂侄女惊后数载始能言。又见保村族人子，惊后喑哑，至今十余年，竟不能愈。其故总因多服金石之药所致，若未服此等药，虽包络暂闭，当自开耳。", "15315": "荔翁尊堂，年届六旬，初发寒热，疏散不解，越日头颅红肿，渐及面目颐颊，舌焦口渴，发热脉数。予视之曰：此大头时疫证也，东垣普济消毒饮最妙。翁云：家慈向患肠风，体质素弱，苦寒之剂，恐难胜耳。予曰：有病当之不害，若恐药峻，方内不用黄连亦可。市药煎熟，仅饮一杯，旋覆吐出。病人自觉喉冷，吸气如冰，以袖掩口始快。众见其拒药喉冷，疑药有误，促予复诊，商欲更方。细审脉证，复告翁曰：此正丹溪所谓病人自觉冷者，非真冷也。因热郁于内，而外反见寒象耳。其饮药旋吐者，此诸逆冲上，皆属于火也。如盈炉之炭，有热无焰，试以杯水沃之，自必烟焰上腾，前治不谬，无庸迟疑。令将前药饮毕，喉冷渐除，随服复煎，干渴更甚，头肿舌焦如前。荔翁著急，无所适从。予曰无他，病重药轻耳。再加黄连，多服自效。如言服至匝旬，热退肿消，诸恙尽释。可见寒热真假之间，最易惑人，若非细心审察，能不为所误耶。", "15316": "荔翁夫人，怀孕数月，嗽喘胸痹，夜不安卧，食少形羸。予曰：此子嗽也。病由胎火上冲，肺金被制，相搏失职，治节不行。经云：咳嗽上气，厥在胸中，过在手阳明太阴。夫嗽则周身百脉震动，久嗽不已，必致动胎。古治子嗽，有紫菀散，百合汤法，犹未善。鄙见惟补肺阿胶汤，内有甘草、兜铃、杏仁、牛蒡清金降火，糯米、阿胶润肺安胎，一方而胎病两调，至稳至当。服药两日，咳嗽虽减，喘痹未舒，方内加苇茎一味，取其色白中空，轻清宣痹再服数剂，胸宽喘定，逾月分娩无恙。", "15317": "族兄奏韩，年逾四旬，外腴内亏，邪乘虚入，寒热咳嗽，头身疼痛，脉大无力。予初投温散不解，转用补中益气汤加姜枣，辅正托邪。语其侄曰：令叔病候不轻，慎勿泛视。旁人以为病轻药重，更医漫不为意，迁延数日，势渐鸱张。延同道余朗亭先生诊治，不肯立方，既而曰：程某现居比邻，胡不邀来同议。乃复相招，观其病状增剧，面红目赤，舌黑唇焦，神识昏乱，脉息豁大空虚，势欲内陷。因与余君商，以壮中温托，伤六味回阳饮方法。无如渠家皆系女流，其侄少不谙医理，或谓烦热，若此再投姜附，必致逾墙上屋。故此迟疑，药不敢服。又复因循，病势更剧，再请余君不至，阖家张皇，其侄偕鲍履平兄来舍恳治，并乞扎邀余君，予为作书余君始至。宾朋交集，时金融若兄在座，私谓予曰：子可尽力举方，服药之事，吾能任之。复与余君斟酌，仍用前方，融兄俟药煎熟，面督服下。次日神采稍回，脉象渐敛，方除炮姜，加枸杞山萸，又服一剂，热退舌润。再将附子分两减半，加杜仲山药。继进大补元煎，两月始康。", "15318": "嘉庆甲子初秋，牧兄邀视伊母恙云，家慈年逾五旬，外腴内亏，病经八日，上热下冷，痰多汗少，咳嗽作呕。昔患淋痛，兹亦带发，医为散风清暑，治俱不应，又以为肝火，拟用龙胆泻肝汤，求为决之。予曰：淋证为本，感证为标，从本从标，当观病之缓急，未可臆断也。比往诊视，脉细面青，身热足冷，时正酷热，病人犹盖毡被，舌苔白滑，胸腹胀闷，不饥不渴。谓牧兄曰：尊堂之病，乃寒湿内伏，加感外邪。治宜温中逐邪，淋痛无暇兼顾，方用苍白二陈汤，加姜附、白蔻以温中燥湿，桂枝、秦艽以彻其表。牧兄问服药以何为验?何期可愈?予曰：伤寒以舌为凭，舌苔退净，病邪自清，计非二候不可。初服舌苔稍退，再剂已退其半，服至四剂，寒热全解，舌苔退净，淋痛亦止。惟腹闷食少，大便未行，次日忽便泻数次，佥以伤寒漏底为虑。予曰：无妨。仲圣云：胃家实，秽腐当去也。方易六君子汤，加谷芽苡仁泽泻神曲，健脾渗湿。三日内共泻二十余行，始得胸宽食进。越日忽又发热，诊脉浮大。予曰：此复感也。牧兄曰：病人日来俱卧帐中，邪何由入。予曰：想因日前便泻，夜间下床，恙久体虚，易于感耳。仍用六君子汤，加姜附秦艽，一服即平。", "15319": "道友曹肖岩翁，故居杨村，侨寓岩镇，乾隆甲寅春初病寒热头痛，自服温散不解，又因胸膈胀闷，疑夹食滞，加用消导亦不效。直至七朝，热发不退，精神恍惚，予视之曰：病由冬不藏精，又伤于寒，邪伏少阴，乘时触发，即春温两感证也。渠虑客中不便，乃归，诘朝延诊，势渐加重，神昏脉大，面赤舌黑。方仿理阴煎，补中托邪。渠师仇心谷先生，见方称善。次早复诊，予告仇公曰：此病全是真元内亏，邪伏于里，猝难驱逐，吾料其热烦过二候，始能退去。热退神自清耳。复订六味回阳饮与之。越日再视，热盛舌干，烦躁脉数，因易左归饮，令服两剂，期届二候，果汗出热退。守至两旬，饮食大进，日啜糜粥十余碗，便犹未圊，其昆季问故。予曰：人胃中常留水谷三斗五升，每日入五升，出五升。缘病中全不能食，胃中水谷，久经告竭，今虽日啜糜粥，不足弥缝其阙，并未有余，焉能骤便。予阅方书，案载一人病后，纳食颇多，并不欲便，亦无胀楚，众疑之。医曰：胃津亏耗，燥火用事，所进之食即销熔，其渣滓须待津回燥润，方能便利如常，阅月余便始通，今才两旬，何虑为?后至三十余日便通，病亦全却。", "15320": "理翁年逾五旬，耽于酒色，时值寒夜，邻家邀饮，起身小解，昏眩仆地。促予往视，面白肢厥，口鼻气冷，神昏遗溺，脉细如丝。予曰：阳脱矣。奈何?渠子弟泣求拯治，仓卒市药不及，令先取艾火，炙气海关元数壮，并煎姜汤灌之。少顷，呻吟出声，方订参附汤，因其力难办参，姑用党参二两，附子一两，浓煎服讫，四肢渐温，目开能言。舁归，诘朝脉色略回，惟呕恶畏寒，不思饮食，将前方分两减半，参合理中汤方法，与服二日，转用右归饮，温补肾元，月余方能起箦。", "15321": "晋翁乃媳，秋间咳嗽，不以为意。交冬渐甚，午后寒热。医云外感，服药不效，遂致形倦肌瘦，食少便溏。予视其行动气促，诊脉弦劲无胃，询其经期，三月未至，私谓晋翁曰：此殆证也，危期速矣。翁惊曰：是病不过咳嗽寒热，何以至此?予曰：经云二阳之病发心脾，有不得隐曲，女子不月，传为风消息贲者，死不治。矧脉弦劲无胃，乃真脏也。经又云：形瘦脉大，胸中多气者死。脉证如此，何以得生。辞不举方，逾旬而殁。", "15322": "潘氏室女，年十五岁，初患腹痛，驯至咳嗽寒热，形瘦食少，诊脉细数，询经事愆期三月。予曰：瘵证也。辞不治。未百日而殁。历见妇人咳嗽寒热，脉数经闭者，多不可治，若室女更无一生。任用补虚清热，解郁调经诸法，总无灵效。求诸古训，鲜有良法。惟《金匮》载有大黄䗪虫丸，及百劳丸二方，喻氏阐发其义，窃思此证当其初起，血痹不行，痨瘵将成未成之际，即以此药投之，祛旧生新，或能图功，亦未可料。倘迁延时日，元气已衰，则无及矣。识此质诸明哲。", "15323": "灿翁年近七旬，向患腹痛，一夕忽吐下紫瘀血块数碗，头晕自汗，目阖神疲，诊脉芤虚，谓其子曰：此血脱证也。书云：久痛多蓄瘀。盖腹痛数年，瘀蓄已久，一旦倾囊而出，夫气为血之帅，高年气虚，切虑晕脱。古人治血脱，每用独参汤以益其气，但目下参价甚昂，恐难措办，乃订大剂黑归脾汤，资其化源，固其统摄，未几获痊，次年病复。虽不若前之剧，亦觉困倦莫支，仍守前法治愈。其子忧甚，恐其再发，商图善后之策。予思血蓄之故，必有窠囊，如水之盈科而进，按胃为生血之源，脾为统血之脏，苟脾健胃强，则气血周流，何蓄之有?经以六经为川，肠胃为海，譬诸洪水泛滥，究缘江河失疏，为订二方，早用归脾丸，晚用参苓白术散，每方俱加丹参干漆二味，冀其去瘀生新。服药经年，其病遂绝。", "15324": "农人某，久患痞积，腹如抱瓮。偶遇方士，教以外用炙法，内服末药，即可刈根。某信之，数日后，忽觉心嘈如饥，吐下紫瘀，成碗成盆，头晕不能起坐，无力延医。舁至镇中戚家，招予往视。病者倦卧榻上，闭目呻吟，方欲诊脉，又血涌出，状如豚肝，遍地皆污，昏晕手战咬牙。戚家恐其脱去，急欲扛回。予按脉虽虚细，尚未散乱，戒勿惊扰，姑俟之。少顷晕定，令先灌米饮以安其胃，续灌党参汤以益其气，再与八珍汤一剂，嘱尽今晚服尽，明日再商。诘朝人来请云：昨服药血幸止，惟心慌气坠，睡卧不安。思血脱之后，心脾必亏，乃易归脾汤，加黑姜，令其扛归，多服自效。后果如言。", "15325": "以翁乃郎年五岁，夏月病逾两旬，诸药罔效，发热不退，汗多口渴，色白肌瘦，切脉虚数无力。阅前方悉皆清散之属，翁问病势何如?答曰极重。又问此为何病?予曰：暑病也。初治甚易，医不如法，热久伤阴，元气被伐，犹幸肝风未动，急宜养阴，保金生水，尚有生机。方用首乌、料豆皮、扁豆、沙参、玉竹、麦冬、五味、石斛、茯苓、丹皮，令取稻露煎药，守服四剂，汗止热退，更进麦易地黄汤，神采渐转。惟饮食欠旺，参用六神散，餐加元复。", "15326": "以翁自病寒热胁痛，口苦食少，呻吟不寐，已经月余，服药不应，自以为殆。诊脉弦急，知其平日情志抑郁，肝木不舒，病似外感，因系内伤，与加味逍遥散，一服而效，数服而安。", "15327": "秀翁年将五十，体虚多劳，初病足痹，医治数月不效，诊脉虚濡无力，视其腓肉枯瘪，膝盖肿大，谓曰：此干脚气也。又名鹤膝风。病由肝肾下亏，邪乘虚伏，医者不知温补托邪，泛从标治，转致血气耗伤，无性命之虞，有终身之患。治仿大营煎，加附子、党参、河车、鹿角胶，初服十剂，其痛已减，再服十剂，足能履地，续服丸药，枯回槁泽，行动如常。", "15328": "炳兄禀质多火，喜凉恶热，夏月常以冷水灌汗，露卧石地为快，素患痰火，方用生地、丹皮、麦冬、山栀、栝蒌、黄芩、知母等味，发时服之即安，乃至他病亦服此方，并食肚肺馄饨汤，汗出即解。暇时向予道及，予曰：痰火药应用凉，若凡病守服一方，似无其理。倘属伤寒阴证，恐其误事，后当慎之。一日果患阴暑感证，寒热身痛，脉细肢冷，予投以附子理中汤不应，再强服之，病反加重，坚不服药。索食馄饨肚肺汤，予谓荤油腻邪，戒勿与食，不听。食后得汗反安，欲服常治痰火方，家人劝阻不可，竟服之。病却，后亦无损。予思咫尺间，人病体质之殊若此。则南北地土不同，风气各异，其人其病又何如耶。《素问》异法方宜论，不可不玩索也。", "15329": "嘉庆甲子秋，予在邻村，偶值余朗亭先生云：日前往富谒视一女子，病甚奇。初起无故发癍，医言是火，多投凉药，渐变损怯，今脉证俱败，此何故也?予曰：无故发癍，事属罕闻。若云变怯，大都清凉过剂，元气被戕耳。越日荫兄令爱，两胫癍出，密密形如锦纹，诊脉和平，询其寝食如常，别无他疾。予曰：勿药。荫兄曰：癍乃重候，安可勿药。因以余公所云告之，竟听予言。后癍退无恙，设当时杂投汤药，不几踵富谒女子之覆辙乎?", "15330": "闻兄体虚感邪，兼挟内伤，病起寒热肢厥，诊脉沉细，初投当归四逆汤，肢厥虽回，身热未退，审属少下亏，邪乘虚陷，更进理阴煎两剂，复诊脉转浮大，舌黑面红，奄奄欲脱，贫士无力服参，姑以党参熟地各四两，熬成浓汁，昼夜与浆粥间进。神稍回，脉稍敛，尚觉心烦内热，舌枯津涸，嘱煮团鱼汤煎药。诸候渐平，又转为疟。发时甚剧，多方图治，百日始痊。后数年，因夏伤于暑，秋发痎疟，邪伏于阴，寒热夜作，予用补中益气汤，参香红饮数剂未止，自求速愈，杂服截疟诸方，气血大伤，面青形倦，寝食俱废，目中时见红光，溲溺淋漓。复迓予治，悉屏疟门套药，仿四明治久疟不愈，用养营汤送八味丸法，十剂而止。", "15331": "绣兄夫人，旧冬曾患弱证，今春又病肝风，俱予治愈。续复得一奇证，口吐清涎，日计数碗，《道经》云：涕唾精津汗血液，七般灵物总属阴。涎亦液属，久吐真阴必伤，然百计治之不止，语其妇曰：古有咽华池真水之法，咽之不吐何如。妇曰：若强咽下，即愦愦欲呕。诊手少阴脉微动，问经事两月未行，告绣兄曰：脉象似属妊娠，不卜昔年怀孕有此证否。曰：拙荆往年受孕，原有吐证，但所吐者食耳，此番证绝不类。况旧病体虚未复，焉能受孕?予曰：据脉多属重身，不然断无此等奇证，今不论其孕否，专意补养肝肾，兼益脾胃，以俟消息。交夏后腹中跃动，孕形渐露，复邀诊视，绣兄笑曰：拙荆累孕矣。但吐涎如故奈何?予曰：无伤，产后当自止。分娩后涎竟止。计自春徂冬，十月之间，所吐涎沫无算，而津液竟无所损，且胎前诸治不应，产后不治自痊，亦异事也。", "15332": "德兄乃郎年十四岁，证患水肿，医投利水诸药无效，转致腹大如鼓，足冷如冰，头身俱肿，阴囊光亮欲裂，行动喘促，势甚危急，诊脉沉细无力。谓曰：此脾肺肾三脏内亏之病也。肺虚则气不化精而化水，脾虚则水无所制而反克，肾虚则水无所主而妄行，仲师金匮肾气丸，如禹之治水，行所无事，实为至当不易之方。无如病久形羸，消耗药多，真元败坏，恐难挽矣。德兄固请救治，仍用本方，旬日而验，不月而痊。", "15333": "咏兄先天不足，形瘦质弱，夏夜贪凉，醉而使内，邪乘虚伏，交秋病发。初诊脉细肢冷，舌白面青，畏寒不热，腰痛无汗，方订附子理阴煎。服后夜发壮热，次日复视，谓其尊人曰：令郎病候，乃夹阴伤寒，势防内陷，药当温中托邪，冀其云蒸雨化。令守原方。服至六日，病犹未减，举家忧甚。予曰：正亏邪重，未易驱除，日来证未变幻，即为见效，须过二候，方望转机。方内加入参耆枸杞杜仲，一意照顾真元，毫不杂投标药。届期得汗热退，渠家以为病愈，是晚复发寒热。诘朝往视，予曰：疟作矣。咏兄曰：疟疾吾生平未曾患过，恐其缠绵，恳为截之。予曰：子病乃极重伤寒，赖温补诸剂，守住三阴门户，不使内陷。经言少阳为枢，今未净之邪，得从少阳转枢而出，乃佳兆也，乌可言截。于是早进八味丸，晚服补中益气汤，十数发才止。予曰：慎之防复。旬日后疟果复，更用养营汤，吞八味丸乃愈。按胎疟一证，诸书鲜有言及，患者多至淹缠，轻则月余，重则数月，治不如法，或成虚劳，或变肿胀，即质实之人，亦累成疟母，为终身之患。且常疟有不入阴，胎疟每多入阴，常疟愈后少复，胎疟愈后多复。又究此病淹缠之故，想由经隧路径生疏，故邪不易出耳。续阅《会心录》云：常发疟者，邪从毛窍熟径而出，其愈易。若胎疟则隧道少疏通之机，毛窍非熟由之路，其愈难，乃知昔贤之言，先得我心矣。再按其证，似与痘疹相类，人生皆不能免。夫人禀父母之精血以成形，其所以必患痘疹者，盖因淫火种于有形之先，发于有生之后，不识胎疟之因，果何所本耶，录中惜未详及。或谓此乃胎中感受风邪，故名胎疟，是说予未之信。", "15334": "方兄体素清癯，证见身热足冷，喉红肿痛，脉息沉细无力。诊毕谓予曰：贱恙似属风热，烦君为我散之。不卜喉痛可吹冰硼散否。予曰：不然。君病乃少阴伤寒，少阴之脉，循喉咙，良由肾元下虚，寒邪客之，雷龙不安其宅，是以上热下寒，其喉为痹。治当温补下元，引火归根。若泛视为风热而清散之，殆矣。方仿镇阴煎。一服喉痹愈，再服寒热退。是日有何生者，从本里吴谵泉先生游，证候相类，向与喉科某善，因便道托诊。某与清散药一剂，服后彻夜烦躁不安，比晓，吴公迓予，至已逝矣。归告闵君，骇为吐舌。后数年，渠又患脚气肿痛，予初为祛风渗湿，因其下元素亏，兼益肝肾，诊视数次，病犹未减，更医消散过剂，血气耗伤，腿膝枯瘪，致成痿废，足不任地，阅十余年，始能出户。", "15335": "汪心涤兄夫人，体孱多病，怀孕三月，腹痛见血，势欲小产，延余至时，胎已下矣。血来如崩，昏晕汗淋，面白如纸，身冷脉伏。予曰：事急矣，非参附汤莫挽。佥谓用参恐阻恶露，予曰：人将死矣，何远虑为。亟煎参附汤灌之。少苏，旋覆晕去，随晕随灌，终夕渐定，续用参术耆草归地枸杞大剂浓煎，与粥饮肉汁间服，旬日始安。再投归脾汤数十剂乃愈。后张效伊翁夫人，证同，亦照此法治验。乾隆甲寅秋，予室人叶孕三月，胎堕血晕，日进参耆十数两乃定。后仍半产数次，势皆危险，均赖补剂挽回。倘惑于浮议，并殆矣。", "15336": "嘉庆辛酉夏，立翁幼孙，伤暑发热，吐泻不止，神烦体躁，唇赤舌黄，口渴欲饮，饮后即吐。诊脉沉伏，手冷过肘，足冷过膝，料非寒厥。欲投凉剂，恐其吐泻，脾胃受伤，拟用六君子汤，除白术加川连木瓜黄土稻花，安脾胃，祛暑邪。服药不效，维时赤日当空，暑气正酷，偶见庭前花卉，枝叶枯萎，童子汲水溉之。因悟病机，乃与生脉地黄汤一服，吐泻即止，再服，脉出肢温，未及旬而愈。思前脉伏肢厥者，乃童真未充，吐泻日频，津液顿伤，脉乃血派，脾主四肢，脾不能为胃行其津液，四肢不得禀水谷之气故也。六味大培真阴，生脉保金化液，小儿脏气易为虚实，是以效速。", "15337": "郑鹤鸣，君平之流，冬月适患伤寒，初起寒热身痛，不以为意。延挨数日，陡然肢冷，脉伏肌肉青紫，面赤烦躁，呃逆频频，请同道曹肖岩翁诊视，询知系欲事后起病，以为少阴下亏，寒邪乘之，逼其真阳外越，与六味回阳饮。服之不应，势已濒危，邀予商酌。予曰：景岳回阳二方，皆能救急，其中尚有分别。夫寒中阴经，审其阴阳俱伤，而病尚缓者，则从阴阳两回之法。苟真阳飞越，重阴用事，须取单骑突入重围，搴旗树帜使，既散之阳，望帜争趋。若加合阴药，反牵制其雄入之势。定方单用姜附参草四味，煎令冷服，外用葱艾炒热熨脐，老姜附子皮煮汁蒸洗手足，于是一昼夜厥始回，脉始出，惟呃未止，每呃必至百声，知为肾气上冲，于前药中参以熟地枸杞五味丁香，摄纳真元。诸恙渐减，改用右归饮，与服二日，目辣舌燥，投六味地黄汤，浮阳顿平。复为调理脾胃及脾肾双补而起。", "15338": "郑媪年逾古稀，证患便闭，腹痛肛胀，寝食俱废，已经两旬，诸治不应。延诊以下为嘱，切脉虚细而涩，谓曰：此虚闭也，一补中益气汤足矣。何下为。服药两日，便仍不通，自言胀痛欲死，刻不可耐，必欲下之。予曰：下法吾非不知，但年高病久，正气亏虚，下后恐其脱耳。媪曰：与其胀闭而死，莫若脱之为快。因忆心悟篇云：病有不可下，而又不可以不下，下之不得其法，多致误人。沉思良久，于前汤内加入制大黄三钱，仿古人寓攻于补之意。饮后肠鸣矢气，当晚便解，结粪数枚，略能安卧。次日少腹尚痛，知其燥矢未净，仍用前方大黄分两减半，再剂便行两次，先硬后溏，痛止食进而愈。夫补中益气汤，原无加大黄之法，此虽予之创见，然医贵变通，固不容胶柱鼓瑟也。", "15339": "董千云卖花为业，年逾四旬，外状丰腴，冬月患伤寒，诊脉沉细无力，证见寒热烦躁，头身疼痛，面红目赤，舌吐唇外数寸，病来势暴。询因房劳感受寒邪，逼其虚阳外露，即格阳证也。方定六味回阳饮，令其煎成冷服。无如饮药旋呕，并吐蛔虫，躁扰如故，甚为踌躇。其母跪求救治，勉取前药半盏，冲入猪胆汁数匙，试服不呕，良久又与半盏，夜间尽剂。晨诊躁象略安，舌收吐止，仍照原方再进，次易八味地黄汤。时届九朝，忽口噤不语，十一二日，又寒热如疟，有从外感起见者，予曰：温中即可以散邪，强主正所以逐寇。力排众议，坚持数日，稍见转机，此后尚多枝节，极力扶住正气，守至两旬，寝食虽安，神采欠爽。因思前病重时，只图固正，未暇驱邪，温补药多，未免留邪闭窍，曾记方书论伤寒时疫，愈后神识不清，有属邪滞心包之语，与服蛮煎两剂，神明顿清，续为调理而痊。", "15340": "许妪冬月病伤寒，寒热头痛，医投疏表和解不应，渐致昏谵口渴，更进芩连清之亦不应。便秘经旬，用大黄亦不下。予初望其面赤烦躁，意属阳证，及切脉细涩，又疑阳证阴脉，思维未决，因问其汗自病起，至今未出，扪之肤熇而枯，予曰是矣。且不立方，姑先与药一剂，有验再商。幸彼农家不谙药性，与药即服。次日往视，面红稍退，烦躁略平，肤腠微润。予曰生矣。疏方付之，乃大青龙汤也。又服一剂，更见起色，转为调理而安。渠族人佩之兄与予善，亦知医理。问曰：君治此病，殆有神助，不然如斯重候，何药之奇效之速也。予曰仲圣云，太阳病不罢，面色缘缘正赤者，此阳气怫郁在表，其人躁烦不知痛处，但坐以汗出不彻，更发汗则愈。何以知之?脉涩故也。子能参悟此篇，自知此病之治法矣。", "15341": "吴某尝富后贫，体虚多郁，病患时疟，坚不服药，已半月矣。一夕忽发热不退，胸闷干呕，医投小柴胡汤不应，热盛汗多，神昏体倦，脉细无力，呓语音低。急延予诊。按仲师云：谵语有虚有实，实则谵语，虚则郑声。《素问》云：言而微，终日乃复言者，此夺气也。用补元煎合生脉散，两服霍然。", "15342": "族叔晓堂，向在吴地贸易，情志不舒，抑郁成病，神迷谵妄，诸医无效。同人虑有不测，送回里中，诊脉弦急搏指，知其因郁生火，因火生痰，痰火扰其神明，蒙其心窍，是以语言不正，举动异常，与阳明胃实狂乱之候不同，故前医用下药不应。病久正气固虚，补之又恐助其痰火。爰仿服蛮煎加梨尖铁琥珀辰砂为引。初服谵妄稍定，再剂寝食渐安，共服十二剂，神清语正，举止如常。盖此方能清心肝之热，而通神明，故效速如此。", "15343": "堂妹适邻村许姓，夏日浴罢，忽头晕仆地，家人扶起，旋即发热，夜间热盛。烦渴呕吐，谵妄不安，手指掣动，医药无效。予诊脉息弦数，视舌尖绛苔黄，谓其翁曰：病由暑风相搏，邪热燔炽，亟宜清解，以杜痉厥之患。方用川连、香薷、甘草、半夏、茯苓、钩藤、防风、青蒿、羚羊角、荷叶、扁荚叶。服药两剂，热缓神清，呕渴亦止。方内除川连、香薷、钩藤、防风、半夏，加沙参麦冬石斛稻露，又服两日，证减七八，再除青蒿、羚羊角、荷叶、扁荚叶，加玉竹、生扁豆、女贞子、当归、白芍，调养而愈。", "15344": "炳兄女在室，年已及笄，性躁多郁，初春曾患吐血，夏间陡然发厥，厥回呕吐不止，汗冷肢麻，言微气短，胸膈胀闷，脉息细涩，状似虚象。医投补剂益剧。予诊之曰：此郁病也。经云：大怒则形气绝，而血菀于上，使人薄厥。又云：血之与气，并走于上，乃为大厥。议与越鞠丸加郁金、枳壳、茯苓、陈皮、半夏。兄曰：女病卧床数日，粒米不入，脉细言微，恐其虚脱。奈何?予曰：依吾用药则生，否则难救。盖此脉乃郁而不流，非真细弱，欲言而讷，乃气机阻闭故也。观其以手频捶胸臆，全属中焦郁而不舒。且叫喊声彻户外，岂脱证所有耶。请速备药，吾守此，勿迟疑也。取药煎服。少顷，膈间漉漉有声，嗳气数口，胸次略宽，再服呕止，寝食俱安。转用八味逍遥散，除白术加香附、郁金、陈皮，病愈血证亦泯。", "15345": "陈某子感证体脉俱厥", "15346": "陈某子年十六岁，夏月患感证，壮热神昏，面赤烦渴，唇燥舌焦，口鼻牙根出血，俱属热象。惟脉息沉细，四肢厥冷，诸医不效。时届九朝，延予商之。予曰：此非阴证，乃阳证也。今日本应重用凉药，恐汝家畏而不服，姑以小柴胡汤去半夏人参，加生地、花粉、山栀、丹皮试之。无如歙俗以为吃坏热药有救，凉药无救。因见方有凉药果畏不服。三日后势更剧，复来迓予，予辞不往，乃浼友人胡君景三代请。予曰：救病如救焚，彼病已重，况复迁延，恐难治矣。胡君曰：试往一决，可治则治之。至诊其脉，前之沉细者，今竟绝，抚扪其肢，则冷过肘膝，更加腹痛拒按，欲便不解，惊狂不定。予曰疾急矣，非承气汤下之不可。疏方讫，胡君私叩予曰：从来伤寒阴阳二证，凭脉用药，不拘浮沉大小，总以有力无力分之。有力为阳，无力为阴，今按脉全无，四肢冷甚，恐属阴证奈何。予曰：此乃阳极似阴，证载吴又可《瘟疫论》中，所谓体脉二厥也。归检书与阅，胡君以为然，竟服下剂，夜间便行二次，比晓厥回脉出，改用甘露饮，后易生脉地黄汤，匝月而痊。", "15347": "陈某子病愈后，其妇忧劳传染。初起头疼寒热，予与香苏饮一服汗解。旋又劳复发热，口苦耳聋，兼值经期，恐其热入血室，酌以柴芩煎加生地、赤芍、丹皮，热犹不退，更加面赤舌黄，谵语脉数。予曰：邪犯少阳阳明也。仿生生子小白汤，炒黄芩换生黄芩，加竹叶灯心为引。并语某曰：予适有他出，倘明日迟到，可请胡君商之，或照原方先服一渣亦可。次日午刻予归，渠已著人相促数次，急造其庐，其泣曰：病大变矣。问其何状，曰昨服尊剂，夜来烦热不眠，今早忽咬牙闭目，昏厥遗尿，已请胡君斟酌，并照原方煎服一渣，迄今不转奈何。予曰：昨病虽重，然已加增药味，即不应验，亦不至此。岂更服他医药欤?某曰：小儿病承救活，深为感佩，今且专心倚仗，曷敢易医。胡君恍然曰：往日市药，吾未之阅，今早阅剂内生黄芩，药店错发生黄耆，比令换去，得无昨剂中误服黄耆耶?因验昨倾之药渣，果然。予曰：此病受邪本重，前药悉力驱之，尚不能解，误服黄耆，将邪热补住，内攻心包，迷塞窍隧，故致变若此。惟有急泻心包之热，通窍避邪，庶有生机。拟导赤各半汤，除人参，加银花金汁，外用紫雪点舌。饮药至墓，神采略回，连投四剂，浸有起色。惟神呆耳聋，时多妄语，易以服蛮煎两服，神明稍清。后用养阴定志之品，月余始平。是役也，使非胡君验明药误，在病家必归咎于医，而医亦不自知其故矣。识此凡治重病，所市药剂，医须亲验，不可忽也。", "15348": "许生咏堂母病请治，据云因食豚肝面饼后，偶触怫郁，致患腹痛，自用麦芽楂曲香砂二陈不应。因其痛在少腹，以为寒凝厥阴，加吴萸炮姜服之益剧。予问痛处可按乎?曰拒按。又问日来便乎?曰未也。切脉沉细，视舌苔黄，中心焦燥，顾谓生曰：此下证也。生曰：连服温消诸剂不验，思亦及此。因家母平素质亏，且脉沉细，故未敢下。予曰：痛剧脉伏，此理之常。质虽虚而病则实，书称腑病以通为补，仲师云：腹满不减，减不足言，当下之。又云舌黄未下者，下之黄自去。今痛满拒按，舌黄焦燥，下证悉具，夫复何疑。方定大承气汤，用元明粉代芒硝，仍加香砂楂曲，兼行气滞。服头煎后便行一次，其痛略定，随服复煎，夜半连下三次，痛势大减，舌干转润，易以调中和胃，旬后起居如常。", "15349": "族兄女三岁，出痘如蚕种，医初认为麻，越日始识为痘，骇甚辞去，更医泛投清解套药。延至九朝，色白顶陷，势欲痒塌，兄商于予。予曰：毒盛气虚，船轻载重，本属险逆，初起按法图治，尚望生机，今无及矣。兄恳救治，勉订保元汤，用糯米鲫鱼羊肉煮汁煎药，昼夜频灌，喜得浆行陷起，再加熟地、当归、枸杞、鹿茸温补之品，侥幸收功。无何。妇病感证，两进逍遥散不应，热盛脉数，口渴舌黄，照方加生地黄芩，次日证仍未减，神昏舌苔干黑。予曰：疾急矣，非重剂莫挽。乃用大剂甘露饮，令其浓煎数碗，尽今日夜服尽，诘朝复视，昏热舌黑如故，反增胸腹胀闷。旁议二冬寒凉，二地滋腻，与胀不合。予曰：古人论治感证，始终以存津液为主，今热炽舌涸如斯，舍是别无良法。兄曰：固知药好，然腹胀药势不行奈何。沉思良久，令市大西瓜一枚，取汁与服。汁尽少顷，忽作寒战，目阖昏睡，汗出如雨，衣被皆濡，至晚始定。兄问故，予曰：此战汗也，非此则邪不能达，今无忧矣。嗣此热退神清，知饥纳食，惟觉身轻如叶，倦怠不支，徐为培养血气而安。", "15350": "胡某乃媳，夏月患感证，延诊时已七日矣。切脉弦数搏指，壮热谵狂，面目都赤，舌黑便秘，腹痛拒按。诊毕令先取冷水一碗与服，某有难色，予曰：冷水即是妙药，饮之无伤。盖欲观其饮水多寡，察其热势之轻重耳。其姑取水至，虽闻予言，心尚犹豫，勉倾半盅与饮。妇恚曰：何少乃尔。予令尽碗与之，一饮而罄。问曰：饮此何如。妇曰：其甘如饴，心地顿快，吾日来原欲饮水，奈诸人坚禁不与，致焦烦如此。予曰：毋忧，今令与汝饮，但勿纵耳。因谓某曰：汝媳病乃极重感证，邪踞阳明，已成胃实。问所服何药，某出前方，乃小柴胡汤也。予曰：杯水能救车薪之火乎?即投白虎泻心，尚是扬汤止沸耳。某曰：然则当用何方?予疏大承气汤与之。某持方不决。邻人曰：吾妇昔病此，曾服此方得效。于是取药煎服，夜间便行两次，次早腹痛虽止，他证依然。改用白虎泻心及甘露饮三方出入，石膏用至四两，芩连各用数钱，佐以银花金汁驱秽解毒，数日间共计用药数斤，冷水十余碗，始得热退病除。众皆服予胆大。予曰：非胆大也，此等重证，不得不用此重剂耳。", "15351": "汪氏妇患热病，壮热不退，目赤唇干，舌黑起刺，便闭溲赤，诊脉弦数有力，应用清剂无疑。试问：渴乎?曰不甚渴，惟喜饮沸汤数口，稍凉即不欲思。如此热证，当渴饮水，何反嗜饮沸汤?若以此一端而从阴治，似乎不可。偶忆律云：二罪俱犯，以重者论。今脉证均属阳热，乌可以喜饮沸汤一事为疑。先与小白汤，病状仿佛，知其药不胜病，乃进大剂白虎汤，石膏重用四两，因其胃热上冲，呕恶不食，更加芦根竹茹为引，另取元明粉蜜拌涂舌，以润其燥。如此寒凉叠进，阅十四朝，始得热退神清，便通舌润。使拘古法，以喜热从阴而投温药，不几抱薪救火乎?孟子云：尽信书，则不如无书。斯言可证矣。", "15352": "蒋某夏月病患发热，口渴，头疼，身痛。医云伤暑，初用香薷饮不应，因其热盛，更加青蒿连翘。服之益剧，诊脉沉细，望色，舌白面青，身虽热而反近衣，口虽渴而喜热饮，谓曰：此阴暑证也，非姜附莫治。其家人曰：病者日来热盛，连服凉剂，尚未见效，且天时酷暑，姜附恐未可用。予曰：夏月伏阴在内，人多畏热贪凉，受寒最易。若云夏月不可服热药，则冬月不可服凉药矣。何仲景治冬月伤寒，每用石膏芩连耶。舍时从证，自古有之，乃投附子理中汤，一服热退，再服病却。", "15353": "汪木工年二旬余，夏间患感证，初起寒热呕泻，自汗头痛，他医与疏表和中药，呕泻虽止，发热不退，汗多口渴，形倦懒言，望色青白不泽，舌苔黑黄而润，诊脉虚细。经云：脉虚身热，得之伤暑。因拟清暑益气汤加减。服药一剂，夜热更甚，谵狂不安，次早复诊，其脉更细，凝为阳证阴脉。及视舌苔与昨大异，色紫肉碎，凝有血痕，渴嗜冷饮。予思此必内有热邪，蕴伏未透，当舍脉从证，改用白虎汤，加生地、丹皮、山栀、黄芩、竹茹、灯心。下午人来请云：服头煎药后周身汗出，谵狂虽定，神呆肢冷，不识何故。予往扪其手足，果冰冷异常，按脉至骨不见，阖目不省人事，知为热厥。命再进药，旁议以为体脉如此，怕系阴证，前药恐未合宜。予曰：此非阴证，乃阳极似阴耳。若误投热剂，则殆，否则今晚勿药，明日再看何如。众然之。次日神呆略回，体脉如故，视其舌苔，又与昨异，形短而厚，满舌俱起紫泡，大如葡萄，并有青黄黑绿杂色，腻胎罩于其上，予甚惊异，辞以不治。其母哀恳拯救。予悯之，揣摩再四，令取紫雪蜜调涂舌，于前方内加入犀角、黄连、元参以清热，金汁、人中黄、银花、绿豆以解毒，另用雪水煎药。翌日再诊，厥回脉出，观其舌泡消退，苔仅干紫耳。再剂热净神清，舌色如常。是役也，予虽能审其阳证似阴于后，然未能察其实证类虚于前。自咎学力未到，但生平历治伤寒瘟疫诸候，曾未见此舌苔之异，且诊视五日，变幻如出五人，前贤诸书亦鲜言及，真匪夷所思也。谚云：读尽王叔和，不如临证多。洵非妄语。", "15354": "农人某患伤寒，数日寒热交作，自汗如雨，就予诊治。脉虚神倦，视其舌苔白滑，分开两歧，宛如刀划，考己任编中有阴证误服凉药，舌见人字纹之语。阅前方果然，予辞不治。渠恳拯救，先与六味回阳饮服之有效，继进左右二归饮数剂，舌苔渐退，诸恙续痊。", "15355": "李某患伤寒，畏寒发热，下体如冰，脉息沉细，饮沸汤犹不知热，阴寒脉证悉具，药当从温无疑。然视其舌色如朱，方书云：舌见纯红，热蓄里，与证不符，因其病初起，凭脉用药，先与小剂理中汤探之，无碍，随用重剂六味回阳饮，数服病痊，舌色亦退。为详其故，殆所谓肾水凌心，逼其心阳外越者欤。", "15356": "郑妇年近三旬，质亏多郁，证患头痛，上及巅顶，下连齿颊，医称太阳风邪，药用羌防芎芷，痛剧而厥，呕吐不食，经脉动惕。予曰：此肝风也。经云：诸风掉眩，皆属于肝。下虚上实为厥巅疾。究由水虚不能涵木，怒木生风，勃勃欲动，误投温散，益助其威，鼓舞鸱张，渐变痉厥，诚可虑耳。方用地黄汤加菊花、钩藤、白芍、甘草，数服稍应。思阳但上冒，阴不下吸，熄风务用咸寒，潜阳必须介类。方加阿胶、鸡子黄、牡蛎、龟板，取用磁石为引，使其吸引肝肾之气归原，服之病释。", "15357": "汪某头痛预见真脏脉", "15358": "汪某中年质薄，且多斫丧，头痛时作时止，夏间诊脉弦急而枯。嘱以脉象欠佳，速宜静养，多服补药，切勿因循。病者以疾虽时发，然寝食如常，犹不为意。逮冬至前二日，忽目花面赤，昏晕不支，延予至，势已败坏，且无力服参，因辞不治。逾日而逝。是病虽败于冬，而真脏脉早见于夏，乃枝叶未害，本实先拨故也。", "15359": "方氏妇本体血虚，偶患目疾，眼科认为实火，初用芩连清之，更用大黄下之。饮药一盏，顷忽晕去，舌吐唇外，不能缩入，肢厥脉伏。时已薄暮，急延予诊，谓曰：寒下耗伤真阳，阳气暴脱，势属可畏，速投温补，希冀挽回。方疏通脉四逆汤，药熟不能下咽，令取艾火炙气海关元数壮，身始动，舌始收，忙灌药一盅，移时又厥，仍令再炙。厥回，复进前药，守至黎明始苏，续进左归饮，及滋肾生肝诸剂，病痊目亦明矣。", "15360": "闵某处境艰难，向多忧虑，脘痛经岁，诸治不瘳。望色萎黄，切脉细弱，问痛喜按乎?曰然，得食痛缓乎?曰然。予曰：此虚痛也。古云：痛无补法，此特为强实者言，非概论也。为订归脾汤，嘱多服乃效。如言服廿剂有应，百剂获痊。后一丐者患同，某检方与之，服数十剂亦愈。", "15361": "许细长，石工也。病起少腹胀痛，坚硬如石，医用消导药，转致吐蛔，便溺俱闭，更医目为寒凝厥阴，投以姜附吴萸，痛剧而厥，肢冷脉伏。急来延予，予以手按其少腹，见其眉攒难忍之状，谓其妇曰：此食厥证也。妇曰：病果因食冷面而起，然已服过消导药无效，或药力不及，亦未可知。第停食小恙，何至厥逆吐蛔便溺俱闭。予曰：谷食下行，由少腹右角后出广肠，今食积不下，故大便不通，直肠紧胀，撑迫膀胱，小溲因而不利，下既不通，气反上行，故为呕吐。呕多胃逆，蛔必上攻，是以随呕而出，务得大便一通，通则不痛，诸证自释矣。但病经多日，凝冱已坚，非精锐之品，不能奏绩。旋进备急丸三钱，顷之腹中雷鸣，下结粪数枚，再与钱半，复泻十余行，厥回脉出，痛减腹软，观者动色，惊有神助。后畏药不服，将息而起。", "15362": "汪氏妇，夏月初患齿衄，衄止旋吐血，血止鼻又衄，大流三日，诸治不应。诊脉弦搏，知其肺胃火盛，非寒凉折之不可，乃用犀角地黄汤，取鲜地黄绞汁，和童便冲药，外用热酒洗足，独蒜捣涂足心，一昼夜衄仍不止。因忆门人许生曾言：人传止衄奇法，先用粗琴线数尺，两头各系钱百文，悬挂项下，再用手指掐定太谿穴（太谿穴在两足内踝下动脉陷处，）神验。外治之法，于病无伤，今既诸治罔效，姑一试之，衄竟止。惟神形疲困，头昏少寐，思血去过多，真阴必伤，改用麦易地黄汤加龟板、石斛、白芍、女贞、沙参、阿胶、旬日霍然。识此以广见闻。", "15363": "洪大登为人厮役，体虚多劳，初病夹车紧痛，服疏风药二剂，卧不能起，口不能张，日饮米泔，仅以茶瓶嘴灌入，四肢挛急，每小便须两人抬起，痛甚汗淋，诊脉细濡，两尺尤弱，有从外感起见，仍欲用风药者，予曰：此痉病也。气血大亏，服此即不救。拟用大剂补元煎，旬余未效，病家亟请更方。予曰：毋庸，药力未到耳。原方令守服二十剂，渐能掉动，服至两月，始出户庭。", "15364": "王木工反关脉", "15365": "王某木工也，向患胃痛，诸治不效，一医以草药与服，陡然便血半桶，时时晕去，闭目懒言，汗淋气怯，诊脉全无。按脉乃血派，此必血脱之故。然血脱益气，须用人参，彼木工，焉能得此。辞不与治，料其旦晚必脱也。越月遇诸途，见其行动如常，心窃讶之。后因他病来视，问其前恙如何得愈。曰：先生言我病危非参莫救，求医无益，只得日煎党参汤饮之，侥幸得活。予曰：此亦血脱益气法也。再诊两手仍然无脉，思人久无脉，焉能得生，沉吟半响，恍然悟曰，此必反关脉也，覆候之果然。渠乃匠人，脉之如何，原不自知，予前诊时，因见其外证之危，仓卒未及细究，识此，告诸诊家，务须留神详察也。", "15366": "敬兄向在金华贸易，恙患咳血，医治无效，食微肌瘦，虑成损怯。予时至兰溪，友人荐延诊视。阅前诸方，偏于温补，谓曰：古人治血证，虽有此法，然须审其证属虚寒，方为合辙。据兹脉证，责诸肺肾阴亏，肝阳上僭，咳甚火炎，血随溢出，理应滋水生木，润肺保金，得以咳稀，血当自止。服药投机，予欲辞回，敬兄固留，为治月余，咳血全好，餐加神旺，肌肉复生。", "15367": "圣翁夫人，夏间病患热盛无汗，烦渴昏谵，医治旬余不解，圣翁外贸，伊郎荫千兄，廷予诊视。脉数舌黄，谓曰：此热病也，非清不可。疏竹叶石膏汤与之。时夜将半，闻叩扉声甚急，启视，荫兄慌入而言曰：病危矣。询其故。曰妙剂，当服头渣，至暮未见动静，再服复渣，更静后，忽寒战肢抖，少顷汗出如浆，肤冷息微，闭目不语。众以为殆，归咎药性太凉，欲投参附以救其脱，亟求复诊以决之。予即随往，扪其肌肤果冷，细按脉虽虚耎，然至数和缓，并不急疾。曰无妨，此战汗也。因本气不足，邪气鸱张，予重用清剂驱之，邪不能留，逐与正争，是以战而汗出。邪虽从此而解，正亦由此而亏，且任其养息，切勿惊扰，元气来复，自然肤暖神苏，若骤进参附，诚恐余烬复炎，反为害矣。叶氏论温热病战汗解后，胃气空虚，有肤冷一昼夜之说。取书与阅，群疑始释。另立一方，用生脉散加茯神、玉竹、白芍、甘草，嘱市药煎好，俟其苏醒与服，并啜稀粥，以养胃气。次早荫兄来谢云：昨夕非子有定见，几为旁言所误，遵嘱静守，逾时汗敛神苏，忙将煎好之药服讫，复睡至晓，肌肤已温，唯形倦气怠耳。更为辅正养阴和胃，渐次而康。", "15368": "安波按：斯证若脉急数，自汗如雨，躁烦不安，神志不宁，是自气脱阳越之候，速宜大剂回阳，与此大相悬绝。", "15369": "子钦兄幼年质弱，偶因停感，发热腹痛，儿科药用荆防查曲，服后热退痛止，以为应验。距意次日卧床不起，头重目阖，气怯懒言，不饮不食。急延予至，见其形状倦怠，切脉细软无神，维时伊舅柳荫千兄在座，予告之曰：令甥之恙，乃元气不支，切恐虚脱，亟宜峻补，迟则难救。荫兄云：舍甥病才两日，消散又未过剂，童质固虚，何至遽脱?岂可骤投重补耶?予曰：小儿脏气易为虚实，脉证疲惫如斯，舍此别无他策。仿补元煎方法与服二剂，病仍未转，伊乃堂忧甚，予曰：凡治病，补虚与攻实不同，攻实可求速效，补虚本无近功。服药病既不增，虚能受补，即为见效。古称填补，如地有陷阱，方能容填。若平地填之，成敦阜矣。仍依原方加入耆术、茯、神、枣仁合归脾汤，守服浃旬，头竖目开，饮食照常，俨如无病。", "15370": "安波按：于庚辰岁治余杭金姓稚子，年甫五龄，形颇肮脏，忽患暴注下迫，形神顿减，小尿短滴，幼医以消导之属，靡不备尝，或有以暴泻属热者，需胡黄连之类，其泻转甚，延余诊治。脉之细弱乏神，按之则空，胎微黑不渴，曰寒邪直中太阴所致，非附子理中汤不可，迟则恐变，乃尊曰：邪中太阴，已领教矣。然小儿体若纯阳，胡可以热济之乎。余曰：医贵活泼，不可纽执一说，以塞见闻。彼以为然，投之果应。此症与斯案相类，险为肤见所阻，故录出为固执者鉴。", "15371": "荔翁年逾强仕，冬月重感寒邪，诊脉细紧，见证寒热无汗，头疼体痛，初投附子理阴煎，汗发不出，复诊方加人参麻黄，翁曰：麻黄性悍，驶不能御，吾质素弱，恐不可服。予笑谓曰：他人之麻黄或不可服，予之麻黄放心服之。盖医当论方，不当论药，若以此加入表散药中，则诚驶不能御，今合补剂，有人参熟地监制之，虽勇过孟贲，亦难肆其强悍之性矣。古人用散法，有皮毛肌肉血脉筋骨之殊，峻散平散温散凉散之异。至于阳根于阴，汗化于液，云腾致雨之妙，独景岳先生得之。其所制理阴煎，及麻桂饮、大温中饮数方，真可称长沙之功臣，而补其所未备也。况理阴煎方后，有原加麻黄之法，又何疑耶。翁信予信，一服汗出而解。", "15372": "安波按：于辛已岁，治王少莲者，夏月纳凉痛饮，日晡觉头重恶冷，至次日壮热憎寒，口燥渴而不饮，目赤汗沾，诊得脉洪大而空，沉按若无，苔来黑滑。余曰：此肾阳为阴暑所迫，致见阳气上戴，目赤口燥不饮，脉空无神，壮热恶寒，即伤寒论之戴阳证也。拟附子理中汤加香薷人参，一剂而神清楚，寒热顿减，口不燥，目赤退，诸恙稍愈。后以斯方减轻，加以祛暑渗湿而痊。似此案之相类，故亦录出，以广后来者之目。", "15373": "召翁夫人怀孕三月，胎动血崩发晕，促往诊视。乃告翁曰：妊娠胎下血晕，已为重险，今胎未下而晕先见，倘胎下晕脱，奈何?翁嘱立方。予曰：血脱益气，舍独参汤别无良药。翁问所需若干，予曰：数非一两不可。翁出取参，予闻房内雇妇私语，胎产服参不宜。亟呼之出，语曰：尔何知，勿妄言以乱人意。少顷翁持参至，予欲辞回，思适才雇妇所言，恐病人闻之，疑而不服，岂不偾事!只得俟之，翁持参汤，予随入房，病人果不肯服。翁无如何，予正色言曰：性命安危，在此一举，今若不服此汤，胎下晕脱莫救，俗见胎产忌服人参，无非恐其补住恶露，在胎下后，犹或可言，今胎未下，与平常临产无异，岂平常临产可以服参，今昏晕欲脱，反不可服乎?予治此症颇多，勿为旁言所惑。病人疑释，一饮而罄。予曰：有此砥柱中流，大势可守，尚防胎下复晕，其参渣再煎与服为妙。诘朝复诊，翁云：昨遵谕，仍将参渣煎服，薄暮胎下，恶露无多，晕亦朱作，令多服培养气血之剂而痊。续翁媳升冶兄令政半产，胎下血晕，时值寒冬，夤夜招诊，两脉已脱，面白肢冷，亟以参附汤灌苏。一家两证，势俱危险，皆仗参力保全，胎产不可服参，殊属谬语。", "15374": "引翁年将花甲，秋季患痢，缠绵日久，清利过剂，肛如竹筒，直下无度，卧床不起，诊脉细濡，望色憔悴，知为脾肾两亏，元气下夺，所幸尚能纳谷，胃气未败。仿胃关煎，调石脂余粮末，与服两日，其痢稍减。再加桑螵蛸，晚间参服四神丸，治疗匝月始。", "15375": "汝兄乃郎，年方龆龀，秋间咳嗽，入冬不止，初起呛嗽痰涩，气急面红，渐次潮热脉数，食减肌瘦，药如泻白散、止嗽散、清燥救肺汤，遍尝无验。汝兄虑成童怯，嘱予筹治。令且停药，每日用甜雪梨一枚，去皮渣，雄猪肉四两，同切块，清水煮汤啜之。其肉与粳米稀粥同食。儿病日久，戒食荤油，复为药苦，得此可口，食而甘之，数日而效，浃旬而痊。汝兄称谢，并问其故。予曰：斯证即喻西昌所谓秋伤于燥，冬生咳嗽之候也。夫燥者濡之，其所以服诸清润之剂而不应者，缘童质向亏，嗽久阴伤，凡药皆草木根荄，只可濡其时邪之燥，未能滋其津液之干耳。经云：阴之所生，本在五味，五谷为养，五果为助，五畜为益，故用猪肉雪梨粳米，诸多濡液滋干之品，气味合而服之，以补精益气，岂寻常方剂可同语耶。汝兄慨然曰：人知药能疗病，不知药反增病。人知食肉病复，不知食肉病愈。今而后益信医理渊深，不易知也。", "15376": "汝兄令爱，笄年在室，时届季夏，薄暮忽觉微寒，夜发壮热，头痛呕吐，次早迓予，其女出房就诊。脉弦急数，舌苔白腻。谓汝兄曰：证属时感暑风，来势不轻，防其生变。方用葛根防风以祛风，香薷茯苓甘草半夏滑石扁荚叶以清暑。诘朝入房诊视，脉证如故，舌苔转黄，热盛口渴，目定神呆。方除葛根防风半夏，加入连翘知母花粉鲜荷叶，四朝再视，病者扶坐榻上，昏昏不语，令其伸舌，勉伸半截，尖绛起刺。汝兄云：小女夜来热炽，烦渴呻吟不安，黎明稍定，以为病减，不意神更昏迷，肢渐厥冷，未识何故。予曰：此暑入心包，邪陷于里，热深厥深，肝风欲萌，势属危险，可延他医酌之。汝兄坚嘱拯治。思暑由上受，首先犯卫，渐传入营，叶氏有清络热，必佐芳香，开里窍，以清神识，用至宝丹一法。吾乡苦无此药，姑用生地、元参、银花、麦冬、川连、犀角、鲜菖蒲、西瓜翠衣，令取荷露煎药。翌日复召，病势益剧。目阖肢掣，口噤牙咬。予曰：肝风已动，证成痉厥，不可为矣。汝兄乞筹以希万一。揣诸病情，治法不过如此，奈服药不应。无已再想外法，令桃黄土摊地上，铺荷叶，将病人抬置其上，另用紫雪牛黄蜜调涂舌，方加钩藤、桑寄生、羚羊角，平肝熄风。至第六朝，汝兄来云：昨晚肢掣不作，口噤已开，似有生意，再烦视之。至见病人眼戴口张，痰声漉漉，切脉如丝。予曰：此非掣定，乃元气内夺，无力鼓动故也。脉证俱败，危期速矣。延至七朝而殁。未几，又见鲍菶莪翁令媳之证。", "15377": "礼翁儒而通医。因乃侄媳病见招。晤间予告以近视张鲍两女病。均不治之故。翁蹙然云：舍侄媳病候，与此仿佛，奈何?予问病经几日矣。曰五日。问其状。曰身热肢凉，昏迷瘛疭。予曰，邪已入脏，不可救矣。其姑坚托诊视，脉证俱殆。翁求举方，予曰：适谈前视张鲍两女证，维时病人犹能行动，尚不可疗，况如是乎?辞欲登车，其仆乞诊妇病，询其何疾，云病起三朝，发热不退，神渐昏冒，今早手足微掣。予曰：此亦暑入心包之候也，可不必往。翁强之。皆至其家，见妇昏卧于床，热盛息粗，面赤唇干，舌伸不前，抉视色绛，苔黄，切脉弦数。辞不用药。仆人跪恳，勉议清解暑邪芳香宣窍之剂，并嘱用黄土荷叶垫卧。越日仆来言，主母已故。妻病服药热缓掣定，神识稍清，复为加减，幸得获痊。后期年再见洪蕊春兄令媳之证。", "15378": "蕊兄乃媳，长夏患病，四朝热盛神昏，舌黄口渴，肢冷脉细。予诊之曰：此暑邪内犯心包，棘手之候。蕊兄嘱治，勉商清暑涤邪，参以芳香开窍，并语之曰：服药热减神苏，庶可图幸，若肝风一动，则难救矣。旁议予方过凉，另延他医，以病者肢冷脉细，认为阴寒，遂用姜附，置诸阳证不问。歙俗病家服药，喜热畏凉，膏粱殆甚，维时姻娅咸集，度其少年新婚，当从阴证治法。蕊兄自不知医，因听众咻，信以为是。友人方瑞征，病者之表兄也，予视病时，渠亦在座，见后医之方，与予相左，私叩所以，予曰：病属暑邪入脏，热极似寒，实非阴证。亟为清解，犹恐不及，再投姜附，岂不火上添油乎。瑞兄云：家姑现在伊宅，吾往告之，勿服其药如何?予曰：子固婆心，但予虽能决其服彼药而必死，然未能料其服予药而必生。续闻竞服彼药，肝风大动，颠簸反张，凭空跃起数尺，爬床搔席，啮舌断齿，未至一候而亡。予所见数证，临危俱动风抽掣，然不若此之剧，盖由姜附燥烈，以刚与刚，益助其威耳。后十余年，复见吴蔚扬兄令爱之证。", "15379": "蔚兄令爱，适本里洪宅，即星恒翁之乃媳也。年近二旬，形瘦质弱，星翁乃郎，向外贸易，因病遄归，媳侍汤药，忧劳交集，时值溽暑，偶作寒热，次日热发不退，头痛呕吐，逆予诊之，拟属暑风相搏，投以轻解之剂，诘朝脉证如故，神识欠慧，予谓星翁曰：令媳病势颇剧，刻防传变，可速告知令亲，切勿轻忽。原方佐以清热辟邪，四朝再召，蔚兄在座，据言昨夕热盛烦躁，今晨人事更迷。予入房诊毕曰：邪已入脏，旦晚肝风即至。病人体薄，且多忧劳，料难支撑。并将畴昔所见诸证向说，嘱早延医斟酌。蔚兄务求画策，勉于昨剂中参入芳香开窍，以尽人工。五日黎明，星翁遣价来请，予辞不往，再四相邀，至见病者昏卧肢掣，喉中痰鸣。予曰：内闭外脱，蔑能为力，他医用药，亦无效灵，越日而殂。", "15380": "安波按：于壬小春初二，治钱清场司秦积卿公祖，年将古稀，神采矍铄，六旬余得类中症，后以大补获痊。今岁秋季。忽觉形寒怕热，溺短便涩，素善饭膳，须豚蹄之属，饥必以大碗燕窝，其余茶食之类，常不辍于口，寒热之际，啖食亦恐失饿，致见神采蒙瞆，口牵指搐，目闭溲遗，切脉沉伏，撬视舌苔，干燥黄厚。余曰：此伏暑候也。年高怯弱，慎防内闭外脱之险，辞以不起。彼人固求立方，余勉拟芳香开窍，辛凉豁痰之剂。今伊速觅妙手评酌，医亦吾药仿佛，竟服彼方。次日复诊，余视脉病仍然，令搜真西黄几厘，调至宝丹抹涂舌上，倘得神定搐回，可望万一。如是弥留者五日矣。渠竟获得西黄几厘，调至宝丹将涂，讵期舌初沾染，而公竟仙逝矣。兹阅斯案，益奇先生之明决于一候之间，神乎神乎。", "15381": "蔚兄来诊云：病初右胁刺痛，皮肤如烙，渐致大便闭结，坐卧不安，每便努挣，痛剧难耐，理气清火，养血润肠，药皆不应。切脉弦急欠柔，谓曰易治耳，一剂可愈。蔚兄云：吾病日久，诸药无灵，何言易治?予曰：此乃燥证。肺苦燥，其脉行于右，与大肠相表里，方书论胁痛以左属肝，右属肺，今痛在右胁而便闭结，肺病显然。但肝虽位于左，而其脉萦于两胁，内经言邪在肝，则两胁中痛。今痛虽在右胁，不得谓其专属肺病已也。夫金制木，忧伤肺，金失其刚，转而为柔，致令木失其柔，转而为刚，辛香益助其刚，苦寒愈资其燥，润肠养血，缓不济急。订方用栝蒌一枚，甘草二钱，红花五分。蔚兄见方称奇，乃询所以。予曰：方出《赤水元珠》。夫栝蒌柔而润下，能治插胁之痛，合之甘草缓中濡燥，稍入红花，流通血脉，肝柔肺润，效可必矣。服药便通痛减，能以定卧，随服复渣，微溏两次，其痛如失。", "15382": "静翁孙女，年甫三龄，夏月发热，医作暑风治，投清散药两剂，忽颏脱音哑，食莫能嚼，饮莫能啜。又以为风中会厌，仍用散药，静翁迟疑，邀予商酌。谓曰：颏属肾，颏脱肾虚之征。肾脉循喉咙，挟舌本，为声音之根。经云：内夺而厥，则为喑痱。儿质本薄，暑复伤气，更服辛散，元气益漓，致变若此。倘再行疏泄，肝风一动，慢惊旋至，不可救矣。仿左归饮合生脉散，服之而瘥。", "15383": "萃翁公郎葆晨兄，禀质素弱，曩患滑精，予为治愈，案载初集中。斯病之始，偶因登山跌仆伤足。吾乡专科接骨颇善，但其药狠，弱者每不能胜。葆兄缘伤重，欲图速效，日服其药，已戕胃气。又患腹痛，更服温肝行气活血等方，胃气益伤，神疲倦卧，痛呕不止，药食不纳，邀予诊视，脉虚细涩，气怯言微，面青自汗。谓萃翁曰：公郎病候，乃药戕胃气，恐蹈脱机。人以胃气为本，安谷则昌，治先救胃，冀其呕止谷安，然后以大补气血之剂继之，不徒愈病，且足得血而能步矣。但治呕吐之药，最宜详辨气味，不独苦劣腥臊不能受，即微郁微酸，亦不能受，惟人参力大气味和平，胃伤已极，非此莫可扶持，而单味独用，分两需多，购办不易，姑以高丽参代之。日用数钱，陈米水煎，缓缓呷之，守服数日，呕止食纳，神采略转。接服大补元煎，渐可下床，移步尚苦，筋脉牵强，行动艰难，翁虑成跛。予曰：无忧，血气未复耳。仍服前方，半载后步履如常。", "15384": "壬午冬萃翁患外证甚重，因往候之。翁卧于床，谓予曰：背偶生毒，已经旬矣。知子不专疡科，故请潘日章兄看视。溃脓无多，并不痛楚，惟形疲食少，烦为诊之。切脉沉细而耎，观其毒形平塌，乃告之曰：此疽也。其病在阴，治须温补内托，由阴转阳，焮肿作痛，毒化成脓，庶几无虑。嘱邀潘日章兄同议。方订十全大补汤加白芷、穿山甲，薄暮使来促云：刻病甚剧，祈速往。入室见翁靠坐于地，众皆仓皇。予惊问故，乃弟子桥先生言：家兄因起身更衣，站立不住，忽然跌仆。遂作昏晕，故此不能动移。按脉迟细欲伏，面青肢冷，呕恶频频。予曰：此中寒也，病上加病，切防脱。变计惟参附汤以济其急，呕多胃逆，更以干姜佐之。古有霹雳散之名，形其迅速也。适日兄亦至，意见相符，于是用高丽参五钱，附子干姜各二钱五分，令先扶掖上床，药熟倾服。予与日兄同坐室中，俟其消息。时届三鼓，渐见呕定肢温，神苏脉出。予喜曰：可无忧矣。令煎二渣与服。次日复召，谓日兄曰：昨夕中寒急暴，幸赖参附汤挽回，今视其疽，形仍平塌，尚不知痛，昨同议之方，犹恐不济。商以大剂养荣汤，加附子。再诊更增枸杞、菟丝、巴戟天及河车、鹿茸血肉之属，日渐知痛，肿起脓稠，腐化新生，治疗月余，疮口始敛。", "15385": "玉翁大郎，童年曾患头昏，诸药不愈。予作肝风治，疏归芍地黄汤。佥谓头昏是有风寒，童子不可轻服熟地。翁排众议，依方多服而瘳。次春又患腹痛，呕吐便泻，延诊，药用温中调气，两服未愈，家人著急，令更他医，日请数人。或以为虫，或以为血，或以为火，治总不验，淹缠旬余，痛甚不止，呕泻不停，寝食俱废。复邀诊视，脉细面青，呻吟疲惫。予思病势增剧，玉翁固虽相信，然旁议纷纷，难与著手，转荐同道余朗亭先生诊治。初投五苓散，续进真武汤，亦俱不应。玉翁坚嘱想法，予曰：非不欲为借筹，奈令郎病久，胃气必空，轻剂谅不济事，若背城借一，尊公爱孙如珍，见方骇然，焉肯与服。翁沉吟云：有一善策，今早友人谈及邻村有扶鸾治病者，家人欲往求方，予呵止之。祈拟一方，予持语家人云，是乩仙所开，自必信服。予曰：策固善矣，治法尚难。令郎之病，起初不过寒凝气滞，本无大害，因求速效，诸治庞杂，痛久伤气，吐多伤胃，泻多伤脾，故困顿若此。倘仍见病疗病，必至土败气脱，计惟扶阳益气，以拯其急。爱议附子理中汤，米水煎饮。气固胃安，庶堪保守。诘朝玉翁来舍，喜云：曩服他药，如水投石，昨服尊方，不但病减，并可啜粥。家人信为神丹，相烦往视，恳为加减。予曰：药已对证，勿轻易辙。今日照方仍服一剂，明日再为斟酌。次早往诊，病势大转，因其体素阴虚，方内除去附子，又服两日。更用参苓白术散，调理而痊。是役也，非玉翁平素信心，兼施权变，安能图成?志此以见医家临证，不特病情之难窥，而人情之难处尤甚也。", "15386": "玉翁次郎，形貌丰腴，向无疾病，丁亥季秋望后，陡作寒热，延予次儿光墀诊治。药投温解，其热即退。嗣后单寒不热，肢麻指凉，口吐冷涎，脐腹隐痛，便溏畏食。知系伏寒凝冱，方换姜附六君附子。初用八分，增至一钱，未见松动。邀予商酌，切脉迟细无力，望色面白舌润。予曰：此正仲圣所谓无热恶寒，发于阴也。前方不谬，尚恐病重药轻，附子加用二钱，更加吴萸、肉桂、砂仁、川椒。次日复诊，病状仿佛，思火为土母，阳虚生寒，温理脾阳不应，非补火生土不可。王冰所谓益火之原，以消阴翳也。仿生生子壮原汤加吴茱萸、葫芦巴、肉果、巴戟天，附子增至三钱，以为必效矣。诘朝脉证依然，玉翁问故。予曰无他，药力未到耳。盖市中种附力薄，况经制透，其味更淡，可增四钱，再加鹿茸、枸兔峻补真阳。自可春回旸谷。依法服之。证仍如旧。翁侄召成兄私询予曰：舍弟之病，先生审属阴寒，第用如许热药，毫不见功，理殊不解。且附子大毒，今已服过数两，久而增加，可无患否?予曰：其他勿论，时下秋燥，此等纯阳之药，若不对证，一匕亦不能堪，况其多乎。夫攻病之药皆有毒，无毒之品不能攻病。凡伤寒中阴等证，非附子不能驱阴回阳，有病则病受之，何有余性，遗留作毒，即使有毒而生，不胜于无毒而死乎。仍守原方，附子加至五钱，维时旁议沸腾，幸玉翁信而不疑。予告之曰：此证确属沉寒痼冷，然煎剂温药止矣。再得硫黄丸佐之，庶有裨益。于是煎丸并进，渐见好机，热药稍减，参入熟地河车杜仲。予与墀儿日为诊视，两阅月始得全愈。共计服过附子一斤，硫黄丸二两，干姜六两，鹿茸一架，党参三斤，高丽人参共十余两，其他肉桂、吴萸、川椒等，不可胜计。予生平治阴证用温药，未有若斯之多，而效验亦无如此之迟也。", "15387": "宅翁令政，质亏恙久，是岁季春病剧，延诊，投以大补之剂，诸证渐减，六月初旬，病人夜卧受凉，微觉怯寒体痛，其时宅翁往淮，公郎辉远兄，遣仆相招。予至视毕，谓曰此新感阴暑，但病躯不胜表散，暂进参附汤，得以邪从汗解，仍服本药，比用人参二钱，附子钱半，各煎和就，正待与服，恰病人睡去。少顷辉兄出，告曰：家母方才睡醒，身已有汗，体痛亦松，不甚怯寒，日内天暑，附子过温，或可不用，即服本药何如。予曰：质虚偶感，邪原无多，标证既除，自应治本。仍将旧方加减配药，其所和之参附汤，留贮盏内置方几上。时值正午，辉兄留餐，甫将举箸，忽仆人之妇，张皇奔入，泣云：伊夫病在重危，叩求拯救。予曰：尔夫早间迓我，随同归来，并未见有病状。妇云：陡然晕倒，不知所由。辉兄本家莆田翁偕往，果见神昏汗冷，肢厥脉伏，初为踌躇，继而猛省，笑顾莆翁曰：证固危殆，然有一大奇事，可望生机。翁惊问故。予曰：此证乃卒中阴寒，阳欲暴脱，而救脱必须人参，伊等焉能得此。况安危呼吸，急不可待，顷辉兄乃堂所煎之参附汤未服，人参虽贵重之物，但和有附子在内，他人无此病，断难服此药，不意盛纪突遘斯疾，适与此药吻合，岂非天造地设乎。令妇跟至辉兄宅中，予道其详，众咸称异。当将几上参附药盏付之持去，谕其稍温与服，再看动静。下午其妇来云：服药逾时，汗敛肢温，人事渐苏。复诊脉出神清，惟倦怠耳。方疏参耆建中汤，仍加附子，嘱向伊主人处乞高丽参四钱，分两剂服，更见起色。续增枸杞、山萸、当归、杜仲，服之而瘳。观此可见，人之死生有数，而一饮一啄，莫非前定矣。", "15388": "䌹兄质亏多病，予为调治，所用药剂，不外归脾汤、补元煎之属。一日遣使相促，至时将薄暮，䌹兄蜷卧榻上，起告予曰：早晨齿牙忽痛甚，不可耐，予至今不止，恐挟风热外因，故停前药。相烦诊视，暂解标邪，切脉沉细无力，见证形寒足冷，谓曰：此属虚寒，非关外感，不徒用补，更须从温，爰仿古方八味地黄汤，加骨碎补，一服痛已。", "15389": "尚兄体素清癯，夏月病温，延诊，金迈伦翁偕往。据述昨午先寒后热，头痛汗出，热灼不退，口渴心烦，夜不安卧，形倦莫支。就榻诊之，脉虚浮大而数，视舌无胎，抚如干版。予为之骇曰：此证乃春温两感，至危至急。仲圣云：发热而渴不恶寒者，为温病，发汗已身灼热者，名曰风温。《内经》云：冬伤于寒，春必病温。冬不藏精，春必病温。既伤于寒，又不藏精，同时病发，谓之两感。凡伤寒瘟疫，热盛舌干，亦须至一候之外始见。今病才一日，舌即干涸，足征肾水素亏，冬伤于寒，邪伏少阴，暗吸肾真，劫其家宝，故一见发热，津液无以上供，舌即干矣。热论篇云：伤寒一日，巨阳与少阴俱病，则头痛口干而烦满，断为两感，不可救药。比类而推，殊难著手。爰用熟地一两，当归三钱，料豆五钱，玉竹五钱，甘草一钱。疏方讫，告迈翁曰：予生平治少阴，先溃于里，太阳复感于表，伤寒春温两感危殆之候，初起悉宗景岳新方，理阴托邪，往往获效，无如此证津液既涸，再投姜附，则阴立亡。故但师其意，以广期前辈风温汤佐之。虽一时之权宜，亦经营之惨淡耳。迈翁曰：善。遂服其药，热减神安，舌稍转润，再加沙参、麦冬、女贞、石斛，更进复脉、左归渐次而愈。", "15390": "靖兄乃郎，年甫四龄，禀质向亏，夏冒暑邪，发热便泻。幼科佥用清散消导之品，服至匝旬，热泻如故，形疲气馁，食入作呕。医称邪滞未净，仍用前药，乃至食粥泻粥，饮药泻药。更医以为脾虚，投六君子汤不应，始来逆予。儿卧几上，阖目无神，脉细如丝。予曰：胃气告竭，慢惊欲来，不可为矣。靖兄曰：固知病久属虚，然昨服六君补药，亦无灵效何也。予曰：病有倒悬之危，一缕千钧，焉能有济。考古人制六君子汤，原为平时调养脾胃而设，非为救急拯危而设也。且阅方内并无人参，仅用钱许党参，数分白术，而市中种术味苦性烈，与苍术等，不能补脾而反燥脾。复有二陈消之，茯苓利之，欲求拨乱反正之功，真蚍蜉之撼大树矣。靖兄曰：然则治当如何。予曰：非真人参不可。盖参者参也，与元气为参赞也。鱼一刻无水即死，人一刻无气即亡，儿质本薄，泻久气伤，加以医药重戕胃气，经云：食入则胃实而肠虚，食下则肠实而胃虚。今肠胃通为一家，幽门阑门洞开不固，饮食入胃，不使少留，即从肠出。仓廪之官，废弛厥职，此诚危急存亡之秋，惟仗参力，急固其气，气不夺则命不倾。然须独用，始克见功，古有独参汤可法也。靖兄闻言大悦，即恳立方。专用人参二钱，令分两次，米水煎服，热退泻稀，次日照方再进，便泻全止，啜粥不呕，更制八仙糕与服而痊。", "15391": "头痛久而不愈，名曰头风。头风多害眼，方书固已言之矣。尚有一种突变，神迷肢掣，不可救治之证，前贤未经道及。曾见曙翁乃郎，年约十岁，头痛时发，予因他事过其家，见儿号泣，询之，翁告之故。出方药皆辛散之属。予曰：此由先天不足，木失水涵，风阳上冒，辛散不宜。翁求方，疏归芍地黄汤付之。翁惑旁言，遂置不服，仍请原医看视，以为前药尚轻，更增细辛藁本，一夕痛剧而厥，手足瘛疭，急来延予。予曰：肝风动矣，不可为也。翁恳拯援，勉用熟地、党参、麦冬、阿胶、炙甘草、麻仁、枣肉、茯神、白芍，合复脉汤，参入牡蛎、龟板方诸水介潜之法，不验辞之。更医无功，迁延数日而殁。续见仇姓稚子及方氏女，证同皆不治。推详病机，证属头痛巅疾，下虚上实，治当上病下取。医昧病原，恣行辛散，以致变幻，其理显然。凡诸痛厥可治者尚多，惟此证一经神迷，即莫能救，此其故岂所谓甚则入肾，内夺而厥，则为喑痱者与。初集载有郑氏妇一证，予虽为治愈，然亦幸也。", "15392": "秀兄年逾五旬，向在维扬贸易，患病数月，延医多人，愈疗愈剧。因买舟载归。望其形容枯槁，行动艰难，诊脉弦劲欠柔。询其病原，据述旧冬少腹痈起，渐次痛连中脘，时作呕恶，彼时纳谷虽减，尚餐烂饭一盂，交春病势日增，即啜稀糜亦吐，形羸肉脱，便秘皮枯，药饵遍尝，毫无一效。迩来更加恶闻药气，入口即吐，君将何以教之?予曰：医之审病，如吏之审案，审案必得其情，审病须明其理。推详脉证，其病机已了然心目矣。按弦为肝脉，诸痛属肝，厥阴之脉，循少腹，究缘平日情怀不适，木郁失条，少腹因而致痛。然肝为将军之官，脏刚性急，医投辛香温燥，希图止痛，肝阴被劫，怒木益横，冲胃为呕，此肝为受病之原，胃为传病之所。医多药杂，胃气益伤。夫胃为水谷之海，气血俱多之经，既不安谷，气血从何生化?肤无血润则枯槁，肠无血润则干燥。阳气结于上，阴液衰于下，欲走噎途，岂区区草木所能回枯转泽耶。经云：诸涩枯涸，干劲皴揭，皆属于燥。燥者濡之，治法固无难也。无如濡润之品，恒多凝滞。现今胃气空虚，呕吐恶闻药气，焉能强进?考古人治血气两伤之候，先当益气，气为血之帅也。但益气药品殊多，首推人参者，以其能回元气于无何有之乡也。再考东垣云：胃中虚热，谷气久虚，而为呕吐者，但得五谷之阴以和之，则呕吐自止，不必用药。谨择参米饮一方，气味冲和，谅当合辙。于是每日用人参二钱，陈米水煎，果受不吐，服至匝旬，餐加色转，再合参乳汤，守服两月，便濡肤泽而起。如此大证，只此二方，并未别参他味，药简功专信矣。", "15393": "吾郡别驾何公，续迁甘肃，眷属仍居郡城。宅中一仆妇，重身九月，偶患头痛，医作外感治，其痛益甚，呕吐汗淋。至二鼓时，忽神迷肢掣，目吊口噤，乍作乍止，何公少君六吉兄，当晚遣力相召，晓造其宅，六兄告以病危之故，入视搐搦形状，诊脉虚弦劲急，谓曰：此子痫证也。势虽危险，幸在初起，当不殒命。六兄曰：昨夕仓皇，恐驾到迟，故近邀女科一看，亦言证属子痫。然服药不效奈何?出方阅之，羚羊角散也。予曰：此乃古方，原属不谬，不知子痫疾作之由。因子在母腹，阴虚火炽，经脉空疏，精不养神，柔不养筋，而如厥如痫，神魂失守，手足抽掣。其病初头痛者，即内风欲动之征也。医家误作外风，浪投疏散，致变若此。至羚羊角散，方内惟羚角入肝舒筋，当归、枣仁补肝益血，茯神安神，甘草缓急，与证相符，其余防、独、木香、杏仁，俱耗真气，苡仁下胎，多不合宜，岂可以为古人成方，漫不加察耶。于是仍以本方除去防独等味，参入熟地、沙参、麦冬、阿胶、芝麻，养阴濡液，少佐钩藤、桑寄生，平肝熄风。头煎服后，其搐渐平，随服二煎，搐定头痛亦减。六兄喜甚，予曰：病来势暴，今虽暂熄，犹恐复萌。嘱再市药一剂，尽今晚服尽，搐不再作，方许无虞。次日复诊，痛搐俱止，神清脉静，纳食不呕。方除钩藤寄生，加白芍、玉竹、女贞、石斛，逾月分娩，母子俱得无恙。", "15394": "就兄体素虚寒，向患腹痛，服温药相安，年来痛移上脘，气逆呕吐，饮食渐减，丁亥之秋，病发益剧，食全不纳，自服理中六君之属，温理脾阳未应，形羸气怯，卧床不起，遣价逆予。诊脉胃少弦多，望色青白不泽，自以为殆，予曰无妨，治未中肯耳。尊体平素虚寒，原宜温理，据兹脉证，由于心境欠舒，木郁不达，厥阴干犯阳明，肝气逆横，胃降失职。仲圣云：厥阴为病，气上冲心，心中热疼，饥不欲食。夫肝为将军之官，脏刚性急，脾胃虽俱属土，然须分别治之，不容笼统而论。叶香岩谓胃司受纳，脾主运化，脾宜升则健，胃宜降则和，太阴湿土，得阳始运，阳明燥土，得阴自安数语，实发前人之所未发。观其食入即呕，足见其病在胃而不在脾。理中六君，皆是脾药，不能治胃，今胃空若谷，必须参力扶持，始克有济，寒士购参不易，姑思其次，以高丽参代之，乃于六君子汤中，除术甘之守，加入川椒、乌梅、干姜、木瓜、白芍，另用陈仓米水煎服。药则辛酸并投，法合制肝安胃。予辞归。越日就兄专札来云：妙方连服两剂，痛缓呕止，稍能安谷，颇见效灵，深为感佩。尚祈加减，照原法略为出入，守服而痊。次春相唔郡城饶君扬翁宅中，丰采倍胜于前。", "15395": "戊子夏，征郡蛟水暴涨，横流泛滥，田庐人畜，到处被湮，歙休尤甚。公奉委往勘，暑湿烦蒸，感伏膜原，交秋疾作，始而寒热似疟，继则单热不寒。吾宗思敏翁为治两旬，大热已退，日晡微潮，拟属邪去正亏，转为养阴和胃。越日寒热又作，以为感复，辅正驱邪，病状如故，神形益疲。度其恙久，阴阳两虚，连投补剂，寒热总不能止，嘱邀予商。予进署时，公寒热正发，卧榻呻吟，诊毕思翁适至，谓予曰：燕公祖之恙，吾看多次，愈而反复，烦子酌之。予曰：顷诊脉象数犹带弦，热时口犹作渴，是属秋时晚发，感证似疟之候。大局无妨，但恙久正气固虚，余波似仍未净。过补恐其腻邪，过清虑其伤正，酌以辅正剂中，微寓和解之意，邪退而正不伤，斯为美也。思翁称善，遂令疏方。药用首乌、人参、当归、茯苓、甘草、料豆衣、扁豆壳、陈皮、半夏、糯稻根须，引加鲜姜红枣，另以井河水各半煎。露一宿，明早温服。后旦再议，届期复召，询其家人云：昨服药后，寒热未来，夜眠安稳。入室公起坐就诊。笑曰：疟魔已被君驱去矣。复与思翁斟酌加减，不旬日而痊。公善画山水，有倪迂风，惜墨如金，求之不得，病痊后，亲绘一箑赠予，并序其事。", "15396": "道光戊子冬，郡城饶君扬翁公郎厚卿兄病，初起寒热头痛咳嗽，服辛散药一剂，次日单热不寒，口渴烦躁，嗽痰带血，下午突作昏晕。当晚折简逆予，黎明至郡，见其面目俱赤，舌黄耳聋，呛咳胁痛，汗出而热不衰，诊脉洪大数疾。谓君翁曰：公郎之恙，乃风温犯肺，邪在上焦，速为清解，免致蔓延中下。辛散之品，不宜用也。方用料豆、甘草、桑叶、蒌皮、杏仁、桔梗、牛蒡子、贝母、梨皮之属。诘朝复召，问知夜来热甚烦谵，咳血甚多，望其面目仍赤，诊毕昏晕又作，额汗淋漓。翁甚彷徨，适黄就唐表兄至，予告之曰：此证确属风温为病，但质亏病重，虑难支撑。昨方力薄，故不应效。就兄曰：鄙见亦然，不识当如何用药。予曰：噫，难言。考风温名载仲景《伤寒论》中，但只言脉证及误治之变，并未出方。叔和以下，亦皆无治法，惟朱奉议创立六方，可谓登坛树帜。然既言不可发汗，何葳蕤汤中又用麻黄、羌活等药耶?宋元迄今，名贤代出，所论风温证治，未有一言折衷，可为法守者。惟近时休邑汪广朝先生，所立风温汤一方，只葳蕤、料豆、甘草三味，药简功专，颇有深意。予治此证，每宗此方范围而扩充之，往往获验。就兄以为然，于是照方加入沙参、生地、丹皮、地骨皮、知母、贝母、黄芩，引用芦根梨汁白蜜，服之大效。诊视数次，热势渐退，苦寒渐减，转手养阴润肺，调理两月，幸得保全。是役也，使非君翁信而不疑，就兄推诚赞助，未见其有成功也。予常语人曰：凡起一大证，务须病家能笃信，医者有主持，旁人不妄议，三者失一，不可为矣。", "15397": "君翁盛纪，年将二旬。暮春之初，始觉头筋抽痛，旋见口眼歪斜，肢凉脉细。以为风寒外感，药投温散，其病益剧，肢掣头昏，心悸汗浆，君翁令舁至舍，嘱为诊治，按诸风眩掉，皆属于肝。春深时强木长，水不涵木，阳化内风，乘虚绕络。凡治风须分内外，外入之风则可散，内出之风，散之益助其升腾鼓动之势。现在左肢瘛疭，防变痉厥神迷。议以滋水涵木，和阳熄风。方用炙甘草、黑参、熟地、麦冬、阿胶、芝麻、茯神、枣仁、五味子、牡蛎、小麦、南枣，初服四剂，势已减轻，更加白芍、当归、葳蕤服至廿剂，病瘥。虚犹未复，令制丸药，数阅月，始得元复如初。", "15398": "兑兄尊堂，年将及耋，本质阴虚，时常头昏，口干耳鸣，心悸，药服滋补相安。秋初患痢，后成休息，延至次春，昼夜或十余行，七八行之不等，每便腹痛后重，粪带鲜红，间见白垢，形疲食少。医治无效，召诊脉如平时，予曰：体素阴亏，原宜滋养，但痢久脾虚肠滑，滋药又非所宜。方仿异功散，加首乌、白芍、山药、扁豆、莲肉、老米，剂内俱用人参，数服痢仍不止。复诊告兑兄曰：令堂证属休息痢疾，病根在大肠曲折之处，诸药力不能到，即复人参，亦皆无益。兑兄云：然则奈何?予曰：非鸦胆子莫能奏效。特此物本草未收，他书亦鲜论及，惟幼幼集成载其功能，名为至圣丹。予用治此证，颇多获验。检书与阅，兑兄云：据书所言，并先生经验，自必不谬，第恐此药性猛，家慈年迈难胜耳。予曰：所虑固是。但每用只三十粒，去壳取仁，不过二三分，且有桂圆肉包裹，兼服补剂，扶持正气，断乎无伤。盖非此莫达病所，病不能除，正反伤矣。如法制服，三日全瘳。是秋其疾复作，家菡洲兄为治，多日未瘥，复邀同议。予曰：上春曾投鸦胆子见功，何不再用?兑兄仍以高年质虚为忧，予曰：有病当之不害，亦三服而愈。兑兄虑疾复萌，商用此味，研入调养丸药内，冀刈病根。予曰：善后之图固妙，然研末入丸，似不合法，更与菡兄斟酌，仍照原制，每以五粒与丸药和吞，服之两月，至今三年，其病不发，可见此药之功效如神。", "15399": "月翁令爱患齿衄，药服生地、丹皮、赤芍、连翘、石膏、升麻之属，衄反甚。予于方内除升麻加犀角，一服即止。翁问曰：古人治血证，用犀角、地黄汤云，无犀角代以升麻。盖升麻能引诸药入阳明也，今服之不效，岂古方不足信与。予曰：朱二允有言：升麻性升，犀角性降，用犀角止血，乃借其下降之气，清心肝之火，使血下行归经耳。倘误用升麻，血随气升，不愈涌出不止乎。古方未可尽泥也。翁又问入阳明清胃热，药品尚多，惟犀角与齿衄相宜者，得无齿属上部，角长于头，本乎天者亲上之义耶?予曰：不宁惟是，人之上齿属足阳明，《礼》云戴角者，无上齿。阳明之血脉，上贯于角，齿衄用之辄应者，职是故也。", "15400": "予侨居岩镇，距祖居之东溪几五十里，丁亥春，族弟羲采证患吐血，近延予弟春圃门生咏堂酌治，血涌不止，势欲晕脱。专价星夜逆予。至见病者仰靠于床，气息奄奄，自云脐下热气上冲，血即涌出。切脉虚大不敛，顾谓弟与生曰：此水火失济之候也。经云水为阴，火为阳，夫人身之阴阳相抱而不脱，是以百年有常，故阳欲上脱，阴下吸之，不能脱也。今阳但上越，阴不下吸，恐蹈危机，所服皆滋纳之品，药病相当，其所以不验者，病重药轻故耳。方定大剂两仪煎，合生脉散，更加龟板、怀牛膝、白芍、茯苓、山药、童便、阿胶之属，服后血虽不涌，脉犹未敛。予曰：慎之，防复吐，上午因亲属问病，应答烦劳，血又上涌，神思飘荡，几欲脱去，忙照原方熟地由一两增至二两，再加磁石，吸引肾气归原。另煮团鱼汤煎药。盖治真阳之飞越，不以鼋鳖之类引之，下伏不能也。如言饮药，血旋止。日晡又因家人嘈杂，血复溢出，虽不若前之甚，亦觉难支。思血属阴喜静，动则阳化，故越出上窍，令其闭户屏烦。如此两昼夜，始得脉敛神安，血止不吐。仍守前法调治，月余而瘳。", "15401": "戊子之春，予由旌邑至孙村汪生德辉家，伊族绍由翁尊堂病剧延诊，比至，已治木矣。入见病者色白如盐，切脉弦劲少胃。予曰：此脱证也，何以至此?翁述病原云：家慈年近古稀，体虚多忧，向患气痛，服辛香之品稍快。旧夏病目，眼科疗治，其目已盲。今春又因痰嗽，药如二陈、枳、桔、杏仁、苏子，服经多日，前夕忽心慌晕汗，至今不止。畏食懒言。出所服诸方，予阅之曰：病伤犹可治，药伤最难医。今脱机甚速，驷马追之，尚恐不及，奈何?翁恳举方，商以两仪煎合生脉散，每剂拟用人参三钱，熟地八钱。翁云：家慈因患气痛，补剂向不取尝，分两过重，虑其不受，请小试之如何。予曰：亦可。但大厦摇摇，一木恐难支耳。姑用人参一钱，熟地三钱，麦冬一钱五分，五味子五分。予下榻汪生宅中。次早翁郎岷山兄来云：家祖母昨夕服妙药后，安睡片时，汗敛晕定，略啜稀粥，稍能言语，幸已获效，乞求复诊。予曰：子归先煎人参二钱，熟地五钱备用。往察脉证颇有起色，仍守原方，续仿《千金》复脉汤以救阴液，再加茯神、归、芍、牡蛎、女贞、石斛，柔肝养胃，渐次而瘥。", "15402": "商翁夫人，本质虚寒，常多疾病。旧春曾为诊治，药投温补有效。今春因乃郎心疾，昼夜看守辛劳，风寒之邪，乘虚袭络，比时不觉，渐致颈脊酸痛，喜暖畏寒，欲人揉打，纠缠两月。医用羌独防风以驱风，香砂陈皮以理气，屡服不应。季夏，予至孙村，延诊。谓曰：此风寒袭络之证也。夫初痛在经，久痛在络。经主气，络主血。考督脉并于脊里，至风府入属于脑。素问云：痛者，寒气多也。寒则泣而不流，温则消而去之。大法治风先治血，血行风自灭。理当养血为君，佐以温通脉络，非驱风理气所能治也。方定当归、枸杞、杜仲、巴戟天、附子、鹿角胶霜、狗脊、五加皮、秦艽、桑枝，四剂全愈。", "15403": "复诊寒热依然，神采更倦，前方初服，微见痰红，疑系附子温燥所致。续服五剂，红不再吐，口并不渴。仲圣云：身大热而反近衣者，热在皮肤，寒在骨髓也。且越人明以阳维为病，苦寒热为训，岂寒栗如此，经年累月，憔悴不堪，不从温补，尚有何策可施耶?王太仆云：热之不热，是无火也。益火之源，以消阴翳。旨可悟矣。虽内经有诸禁鼓栗，如丧神守，皆属于火之言，丹溪有治用清凉之案，然与此似乎不合。无如补虚门中，归脾、十全、补元煎、养营汤之属，均已服过，即治奇经之鹿茸河车，亦无应验。殊为棘手。但细详脉证，总不外乎阴阳精气两亏，张介宾所谓以精气分阴阳，则阴阳不可离，以寒热分阴阳，则阴阳不可混。古人复起，不易斯言。", "15404": "诊脉沉伏模糊，证见肢厥声鼾，口鼻气冷，人事迷惑。处由真元内戕，阴寒直中，阳气外脱，势属危殆。内经以阳气者，若天与日。今则冱寒凝泣，阳霾用事，使非重阳见𬀪，何以复其散失之元乎?夫人身之真阳，譬之鳌山走马灯，拜舞飞走，无一不具，其间惟是一点火耳。火旺则动速，火微则动缓，火熄则寂然不动，而拜舞飞走之躯壳，未尝不存也。方用参附二味，重加分两，昼夜频进。本草言人参能回元气于无何有之乡，附子为斩关夺门之将。潭底日红阴怪灭，分阳未尽则不死。但脉证败坏如斯，欲图断鳌立极之功，亦难之难矣。", "15405": "脉沉细缓，外腴内虚，饮多谷少。恙经三载。发时脘痞嗳噫，小便欠利，年来戒饮，其疾虽平，然精神起居，未能如昔。饮食稍有失调，脘中犹觉不快，虑其病根复萌，商图善后之策，此不治已病而治未病也。夫脾胃清和，始能生化气血。酒者熟谷之液，其气慓悍，入于胃中则胃胀气上逆，满于胸中，故致患若此。今病虽愈，而仓廪之官，未得骤反清和之旧。计惟调养脾胃，以资运化。考古治病，有煎膏丸散之别，心肺病在上焦，宜用煎膏。肝肾病在下焦，宜用丸。脾胃病在中焦，宜用散，审其致疾之因，投药自中肯矣。", "15406": "岐伯虽言五脏六腑，皆令人咳，然其所重，全在于肺。盖皮毛者。肺之合也。皮毛先受邪气，邪气以从，其合其寒，饮食入胃，从胃脉上至于肺则肺寒。肺寒则内外合，邪因而客之，则为肺咳。是咳之不离乎肺，犹疟之不离乎少阳。据谕病缘夏热，晓起感冒凉风，更兼饮冷，始而微咳，渐至咳甚，服药月余，咳仍不已。经云：形寒饮冷则伤肺。此致病之大端。医者只知天时之气热，不察人身之脏寒，频投滋润，希冀清火止咳，适燕指南，无怪药愈服而咳愈频也。盖肺为娇脏，性虽畏热，然尤畏寒，金被火刑固为咳，金寒水冷亦为咳。五行之理，生中有克，克中有生，金固生水者也。然金寒则水冷，使非火克金，则金不能生水矣。譬诸水冰地坼，犹以霜雪压之，其能堪乎?诊脉沉细，口不干渴，时当盛暑，背犹怯风，使非温中涤邪，何以春回旸谷。倘再因循贻误，寒邪不解，久咳肺伤，更难为计，拟温肺汤一法。", "15407": "先天禀薄，情志欠舒，心脾抑郁?诊脉细涩，细为气少，涩主血虚。问寝食如常，惟月事失调，每值经期，洒淅寒热，腰膂酸疼。按冲为血海，任主胞胎，二脉交通，乃能有子。脉证若此，即无他患，恐难孕育。间进加味归脾汤，调养心脾血气之源，常服毓麟珠，补益冲任，阴阳和协，冲任调匀，则合浦珠还，蓝田玉茁，可预必也。", "15408": "安波按：冲脉为经水之本，故内经言太冲脉盛则月事以时下。兹以毓麟珠等药以补益冲任，正合其旨。", "15409": "经曰：水火者，阴阳之征兆也。肾为坎卦，一阳居二阴之间，故须阴得其平，然后阳藏于密，童年知识已开，阴精早泄，此致病之大端。及壮，血气方刚，尚不觉其所苦，人四十而阴气自半，起居日衰，精神不充，蝉联疾作。诊脉尺虚细涩，寸关大于平时，按尺为肾部，脉见细涩，肾虚奚疑。寸关大于平时，阴弱阳浮之象耳。夫医之治病，不以用补为难，而以分别水火气血为难。冯氏书云：小病治气血，大病治水火。盖气血者，后天有形之阴阳也。水火者，先天无形之阴阳也。太极之理，无形而生有形，是治大病，可不以水火为首重耶。请以不寐言之，人知其为心病，而不知其为肾病也。心虽为神舍，而坎离尤贵交通。越人以阳不入阴，令人不寐，岂非水火未济，坎离失交之故乎，内经又有头痛巅疾，下虚上实，过在足少阴巨阳之语。形容厥晕，病机最切。方书称风、称火、称痰，漫无定见。景岳师其意，以为无虚不作眩，治当上病疗下，滋苗灌根。精矣精矣。暂服煎剂，再订丸方。王道无近功，内观颐养为要。旧患眩晕，怔忡不寐，遗泄，本属心肾两亏，水火失济，曾订煎丸，服经十载。兹诊脉候平和，精神矍铄，此亦颐养之功，非全关草木之力也。惟食多尚难运化，腰膂时痛，遗泄间或有之。药物所需，仍不可缺。考古人用药，有攻病保躬两途，攻病则或凉或热，当取其偏，保躬则适其寒温，宜用其平。盖温多恐助相火，精关不藏，润多虑伤脾阳，坤元失健，如云食蜜，便即溏泻。脾虚不胜润滑之征。青娥丸固能治肾虚腰痛，但故纸胡桃味辛性温，久而增气，恐其助火，且常服丸药，亦须分别气候。夏令炎热，远刚近柔，以防金水之伤。冬令严寒，远柔近刚，以遂就温之意。将交夏至，一阴初变，元精不足之时，商以益阴保金，兼调脾胃，秋季再为斟酌。", "15410": "水火之道，宜交而不宜分。水上火下，名曰交。交为既济，不交为未济。由是观之，水火之切于人身者大矣。据脉与证，处由肾元下亏，水火失济，以致魄汗淋漓，玉关滑泄。腰为肾腑，肾虚则腰膂多疼。心为神舍，心虚则夜卧欠逸，面赤颈热，虚阳上炎；体倦头倾，髓海不足，且金乃生水之源，肺肾为子母之脏，子虚盗窍母气，此喘咳之所由。肾开窍于二阴，心与小肠相表里，心热移于小肠，此血淋之所自。昔肥今瘦，虚里跳动，种种见证，虚象奚疑。不知持满御神，日啖草木无益，积精自刚，积气自卫，积神自旺。酸以收之，介以潜之，厚味以填之，水火交，精神治矣。", "15411": "经云：任脉为病，男子内结七疝，督脉为病，不得前后为冲疝。是疝病虽属于肝，而实冲任督三脉所生。据证睪肿，少腹形坚痛甚，攻冲腰俞，病根深远，愈发愈剧。考任脉起于中极之下，上毛际循腹里，冲脉起于气街，督脉统督诸脉，而为奇经之长。叶氏云：大凡冲气从背而上者，系督脉主病，治在少阴，从腹而上者，系冲任主病，治在厥阴。揣诸病情，确为奇经受病无疑。医不中肯，是以药治无功。", "15412": "疟虽小病，而内经论之最详。首称夏伤于暑，藏于皮肤之内，肠胃之外，因得秋气，汗出遇风，内外相搏，是以日作。可知疟病由于暑风相搏而成。然暑必兼湿，若无湿但为干热，非暑也。即此推之，疟病虽属暑风相搏而成，又必挟有湿邪酝酿之所致矣。特六淫分配四时，暑之与湿气虽异，而因则同。有可分不可分之义也。今岁太阴司天，湿土主事，其变骤注，其灾霖溃，人在气交之中，感而即病者，为霍乱、吐泻，肿满诸候，其不即病，邪伏膜原，内趋大肠则为痢，外走少阳则为疟。故疟之寒热往来，亦犹痢之赤白胶黏耳。恙逾匝旬，疟经五发，胸腹饱闷，呕恶不渴，脉沉弦缓，显系湿郁中焦，腑阳失运，幸得从枢外达，不至滞下疸满，邪净自瘳，无烦过虑。", "15413": "产育多胎，冲任受亏，兼之自乳，阴血更耗。恙经年远，腰膂刺痛，转侧维艰，小便血淋，痛引少腹。揣摩其故，非特血气之伤，而且奇经亦损。故归地养阴，参耆益气，均无灵效。冲脉起于气街，任脉起于中极之下，淋痛诸候，必有所关，即寒热一端，亦阳维为病耳。病由血海空虚，损及奇经八脉，寻常药饵，谅难奏功，宗《内经》血枯，治以四乌鲗骨虑茹丸。", "15414": "安波按：古言病久入八脉。", "15415": "前患痱风，调治小愈。案牍劳形，元虚未复，腰膂虽能转侧，足膝尚觉软弱，肝肾真元下亏，八脉不司约束。参耆归地，仅可益其气血，未能通及八脉。古人治奇经精髓之伤，佥用血肉有情，岂诸草木根荄，可同日而语。推之腰为肾府，膝为筋府，转摇不能，行则振掉，不求自强功夫，恐难弥缝其阙。恬澹虚无，御神持满。庶几松柏之姿，老而益劲也。", "15416": "脉弱质亏，操持多劳，昔年产后少腹起有痞块，不时作痛，迩来痛于早晨，日日如是。经云：任脉起于中极之下，循腹里。任之为病，其内若结，男子七疝，女子瘕聚。再考古人论积聚，分症瘕两端。症者征也，有块可征，其病在血。瘕者假也。聚则有形，散则无迹，其病在气。良由新产之后，或因寒侵，或因气滞，以致循经之血，凝结成形，胶黏牢固，长大则易，铲削则难。须待本身元气充旺，始能消磨。倘务急攻，非但积不可消，反伤正气。内经有大积大聚，其可犯也之戒。旨可见矣。现在痛势攻冲较甚，滋腻之补，似非所宜。思久痛在络，冲为血海，先商煎剂，调和冲任，使其脉络流通，气机条畅，痛势稍缓，再议丸药，图刈病根。", "15417": "时疫十朝，正虚挟邪，证见神卷耳聋，热发不退，脉息沉细无力。凭脉用药，理应壮中温托，阅方曾服理阴煎三剂，病样日增，前法似难再进。夫阳证阴脉，原属不宜，方书有时疫，邪伏于里，脉多沉细，不同伤寒邪自外来，脉多浮大，语属可参。仿赵氏六味汤加柴胡一法。复诊脉仍虚细，神形倦怠，唇齿干枯，舌苔黄燥变黑。夫邪热最为真阴之贼，高年肾阴本亏，热甚津液更耗。《己任编》所谓感证始终以存津液为第一义，盖阳明燥土，全赖少阴肾水以滋养之。如旱田侧有井泉，犹可供其灌溉之资，倘并井泉干涸，燥土炎蒸，则苗槁矣，宗甘露饮。", "15418": "书云：卫虚则恶寒，营虚则发热。证见日晡寒热往来，已经数月，洵为营卫二气之虚，断非客邪外感也。病既属虚，虚则当补，昨服补剂，胸鬲反增滞闷，此中消息，颇难窥测。盖非药不能应病，乃胃气不行药力耳。夫上损过胃，下损过脾，越人且畏，姑遵经旨，虚痨不足，当与甘药。两进甘药，寒热依然，惟粥食稍增，咳嗽略缓药病尚觉相符。稽古补虚方法，千蹊万径，而其关键，总以脾胃为之主脑。夫人之一身，内而五脏六腑，外而皮肉经脉，何一非藉谷气长养之功。苟土母倾颓，既难输化饮食之精微，焉能传送药力，宜乎虚不纳补也。难经发明五损，勿过脾胃，仲景治虚痨诸不足，出活人手眼，其所立建中方法，亦皆稼穑作甘。此古圣贤明训，内伤大病，可不以脾胃为首重耶?然病真药假，终难图功。", "15419": "恙经半载，脉证合参，究属质亏烦劳，以致坎离不交，水火失济，五液内涸，虚阳不藏。误服苦寒，重伐胃气，诸证蜂生，纠缠不已。揆之古训，以虚能受补者可治，虚火可补，参耆之类，实火可泻，芩连之类。劳伤之火，虚乎实乎，泻之可乎。赵氏谓阴虚之火，如盏中油干，灯焰自炽，须以膏油养之，专主补阴。其说是已。然阴生于阳，血生于气，顾此食少欲呕，脘闷不快，又难强投滋腻。反复推详，计惟培养脾胃，默运坤元，以为先著，脾为土母，安谷则昌。《金匮》治虚劳，首用建中。越人言损其脾者，调其饮食。脾元日健，饮食日增，变化精微，滋荣脏腑，不治火而火自熄，不润燥而燥自濡，充肤热肉之功，可渐见矣。然内伤之病，宜内观静养，所谓大病须服大药。大药者，天时春夏，吾心寂然秋冬也。参透此关，以佐草木之不逮，为妙。服药旬余，脉象稍转，寝食略安，惟足膝酸软，项脊时疼，形神疲倦。考治五脏之虚，难经言之甚悉，曰损其肺者益其气，损其心者调其营卫，损其脾者，调其饮食，适其寒温，损其肝者缓其中，损其肾者益其精，阐发精微，了无遗蕴。再考《金匮》云：男子脉大为劳，极虚亦为劳。夫脉大为真气泄越，心脾耗伤，此归脾、建中、养营、四君等汤之所宜。极虚亦为劳，乃精血内夺，肝肾下衰，此六味、八味、天真、大造等丸之所宜也。但病证多端，治须次第。首先稼穑作甘，培补中宫，专崇其土，次当荣养心脾。盖心为离阳，补心阳以生胃土，虚则补母之义。至于皮枯肉瘠，肢懈形羸，精髓内竭，筋骨废弛，明属本实先拨，舍填纳固摄，则解㑊何由而振?枯槁何由而回?特草木无情，须假物类之脂膏，益人身之血液，煎丸并服，脾肾分施。炼石补天，而收桑榆之效矣。调治两旬，虽未大效，然处境烦剧，犹能支撑，未始非赖药饵扶持之力。七年之病，三年之艾，原无速功。春三月此谓发陈，恪服煎丸，春气得生，夏可得长。一阴来复，自可霍然。病机前案已详，其中奥义难测者，尚有数端，请再陈之。凡人病若劳动，反觉精神强健者，此阴火沸腾，扶助于内，不觉其元气之衰，若静养调适，反觉神疲气弱者，此阴火退，本相露故也。病情有类乎此者一也。解㑊一证，由于肝肾二经之虚。肝虚则筋软无力以束周身，肌肉皆涣散而若解，肾虚则骨痿不能自强，遍体骨节皆松懈而多㑊，故恹恹悒悒。若不知所以为人，病情有类乎此者，二也。男子精未满而早摇其精，五脏有不满之处，异日有难状之病。病情有类乎此者，三也。卫气昼行于阳主寤，夜行于阴主寐。平人夜卧，则阳升阴降，阴阳交合，然后渐入睡乡。若营弱卫强，坎离失媾，神明之地，扰乱不安，万虑纷云，却之不去，卫气刚入于阴，契合浅而脱离快，升者复升，降者复降，是以欲寐之时，忽惊而寤矣。病情有类乎此者，四也。至若饮食虽能强餐，腹中常觉不畅者，胃得受纳之司，脾失健运之职也。大便燥结，数日始一更衣者，肠脂枯涩，传导艰难也。脘中时痛者，木失水涵，肝吐怒张而迫鬲也。心乍怔忡，营虚之故。臂多青脉，血脱之征。更有皮肉之间，时如冰水滴溜，证状之奇，方书未载。曾治一妇患此疾，数年投补药百剂而愈。岂非血气空虚，失其温分肉、实腠理之司耶。", "15420": "两寸关脉候俱大，左关尤急。据述前冬因情志抑郁，先见此脉。后觉心烦不安，旧春心烦稍定，咳嗽至今不止，舌苔时黄时退，此肝为受病之源，肾为传病之所。夫肝之伤脾，人所易知，肝之伤肾，人所不识。譬如折花枝安插瓶中，花枝日茂，瓶水日为吸干，肝阳吸引肾阴，此之谓也。且肺为肾母，子虚必盗母气，不特金不制木，而木反得侮金。肝阳上升，冲心为烦，冲肺为咳，脉大不敛，舌见黄苔，要皆阳亢阴亏之所使然。所幸寝食如常，别无兼证。议以滋肾生肝，保金化液，辛温刚愎，似非所宜。复诊脉急依然，连日嗽甚，于前夜卧欠安，头额手心俱热，是属挟有风温外因。若云阴血之热，当发于日晡，不应发在午前，且其来也渐，何骤若此。质虚恙久，固不能正从标治，然亦未可过补。仿汪广期前辈风温汤方法。", "15421": "安波按：于庚长秋，行医于杭笕桥，一士子患水肿，面目无缝，阴大如栲，小水点滴不爽，切脉沉细模糊，苔腻白滑，不渴。阅前医有开鬼门者，有洁净府者，有用五子五皮者，有需《金匮》肾气法者，服之如石投海。余意肾气虚则水泛为肿，以肾气丸为旗鼓之剂，何反不应。追忆《己任编》有益气阳，送肾气丸之法，翻书令彼视之，伊以为然。服之竟验。视此与先生暗合也。", "15422": "《金匮》云：妇人新产有三证，一曰痉，二曰郁冒，三曰大便难。三证所因，无非阴伤血耗之所致耳。人知四物汤能补血，此第认其面目，而未审其根源。夫血生于心，统于脾，欲求其源，舍此谁与?再按脾主肌肉，脾虚故肌肉发热，心主神明，心虚故神明失藏。计惟黑归脾汤一方，可称对证之药，泛涉他求，恐多岐也。语云：宁医十男子，莫医一妇人。盖女科病本无难，其所难者，胎产两端而已。胎前诸病，尚须培养气血，况乎产后百脉空虚，不言可知矣。产经十朝，发热昏冒，肢掣烦躁，夜卧欠安，脉息数大无力，断非蓄瘀风邪，显属阴亏阳越。病关根本，非枝叶小恙可比。归脾汤培养心脾化源，喜其虚能受补。第补药治虚，如旱田稼穑，灌溉宜频。病人畏药，昨晨至今，停药未进，心烦肢扰，痉厥欲萌，原方加胶黄枣麦，守服勿懈。", "15423": "伤寒论厥证，分别阴阳，阴厥属寒，阳厥属热，寒宜温而热宜凉。杂病论厥证，分别虚实。夺厥、煎厥、痿厥为虚，薄厥、尸厥、食厥为实，实可消而虚可补。病由情怀不释，肝失条达，血气日偏，阴阳不相顺接，因而致厥。与全虚全实者有间，理偏就和，宜用其平。偏补偏消，乌能治情志中病。厥证妇人常有之，其为情志郁勃，致病显然。惟昼夜频发，阴阳脏气俱伤，却为可虑。若乍发乍止，疏而且轻，亦无妨碍。所嫌病关情志，难以除根，务须戒怒舒怀，惜劳静养，冬令收藏之际，加意慎持，来春草木萌动，庶可不致复发。厥证有因痰者，有不因痰者，因痰而厥，厥时喉中必有痰声漉漉，此则厥来寂然无闻，且痰厥脉应带滑，今脉细兼弦涩，洵属气厥无疑。持脉之道，须知人之平脉，然后察其病脉，质亏脉细，此其常也。惟细中见涩，右寸关兼带弦象，故主病耳，涩者血虚气滞，弦者胃弱肝强，细小弦涩，主病尚轻，牢大弦长，主病重矣。诸厥属肝，女子以肝为先天，肝主怒，怒则气上。经云：血之与气，并走于上，乃为大厥。其由肝郁为病可知。考古人治郁证，多用越鞠逍遥二方，但越鞠燥而逍遥则润矣，越鞠峻而逍遥则和矣。治肝三法：辛散、酸收、甘缓。逍遥一方，三法俱备。木郁则火生，加丹栀，名加味逍遥。滋水以生木，加熟地，名黑逍遥。《己任编》中一变，疏肝益肾汤，再变滋肾生肝饮。前用逍遥减木者，恐其守中，用丹皮减山栀者，恐其苦泄伤胃也。肝胃二经同病，须分别其肝阴胃液已亏未亏。如阴液未亏，气药可以暂投，若阴液已亏，治惟养阴濡液。所谓胃为阳土，宜凉宜润，肝为刚脏，宜柔宜和。叶氏论治郁证，不重在偏攻偏补，其要在乎用苦泄热而不损胃，用辛理气而不破气，用滑润濡燥涩而不滋腻气机，用宣通而不揠苗助长数语，深得治郁之理。血虚治当补血，四物汤为补血之首方。然其中尚须分别阴阳。若血虚肝燥，木火沸腾，芍药微酸微寒，在所必需，地黄先应用生，凉血生血，继则用熟，补水涵木，川芎辛窜，固属不合，当归亦须蒸去辛温之性。养血诸药，除四物外，惟丹参为胜。本草言其色赤入心，有去瘀生新之能，功兼四物，乃女科要药，可以备用。木郁生火，火则宜凉，第此火非从外来，良由木失水涵，以致肝阳内炽，芩连知柏，苦寒伤胃，洵非所宜。不若生地丹皮之属，清肝凉血为稳。", "15424": "五行克制，木必犯土，肝气上逆，胃当其冲。洵其厥来，脘中有块，按之则痛，食下阻滞，此肝犯胃，厥阳顺乘阳明故也。既知气逆为患，治应先理其气，无如气药多燥，肝阴胃液已亏，如何燥得?经言兰除陈气，并能醒胃舒肝，可加为引。桑叶轻清，能泻肝胆之郁热，叶案每与丹皮同用见功。虚则补其母，肝肾同治，乙癸同源乃治肝病第一要诀。然须俟其痞消厥定，以作善后之筹。若用六味汤，可加当归白芍，或去山萸，恐其温肝故也。如用须陈者乃佳，分两减轻，并用盐水拌炒。肢掣名为肝风，此非外来之风，由乎身中阳气变化，故曰诸风眩掉，皆属于肝。第肝为刚脏，须和柔济之。治用和阳熄风，及养阴甘缓等法。至于钩藤、菊花、桑寄生，均有平肝熄风之能，发时随宜加入。内经有肝苦急，急食甘以缓之之语。金匮出甘麦大枣汤，只用甘草小麦枣肉三味。盖小麦春生，肝之谷也，最能养肝，合诸甘草枣肉之甘，以缓其急，后贤治肝风诸病，每参此法。木喜滋而恶燥，阴亏血燥之体，或逢天时阳气泄越，或触情志恚嗔，因而激动肝风，变幻痉厥，纠缠日久，阴液内竭，可以借用《千金》之复脉汤。盖脉乃血派，血脉既亏，藉其药力以通营卫，致津液，叶氏于方内除去姜桂益精。诸厥虽属肝病，然心为君主之官，主安则十二官各得其职，厥发日久，肝风内扇，震动心营，养心安神药品虽多，首推抱木茯神者。盖茯神本治心，而中抱之木，又属肝，以木制木之义。其次柏子霜，既能养心，更可润肾滋肝。用枣仁须猪心血拌蒸晒，用麦冬须辰砂拌染，或加琥珀龙蛎，均有镇静之功。肥人之病，虑虚其阳，瘦人之病，虑虚其阴。阴亏后下，则阳越于上，下虚上实，而为厥巅之疾。是故养阴药中，必佐以潜阳者，如畜鱼千头，须置介类于池中之意。牡蛎鳖甲淡菜龟板，皆介类也。方中只用牡蛎鳖甲者，取蛎之咸能软坚，鳖之色青入肝，不独潜阳已也。", "15425": "质亏烦劳证，经多日诊脉，虚弦带急，精神欠充，夜寐少逸。询其病初，并无寒热，知非外因。惟头痛乍轻乍重，推求其故，东坦云：内伤头痛，时痛时止，究缘烦劳抑郁，水不涵木，肝风上扰，清空鼓动不定。夫头痛神烦，倏然而至，迅速莫如风火。但身中阳化内风，非发散可解，寒凉可平，必须阳和，庶乎风熄。经旨以下虚则上实，阴伤阳浮，冒上病疗下，滋苗灌根，语可味也。", "15426": "病起偶然眩仆，医谓急虚身中，猛进甘温峻补，转增胸胀呕吐，不饥不便，有时浮阳上腾，面赤，唇口干燥。然脉尚和平，寝尚安稳，言语尚觉明白，求其所因，良由肾元下虚，水不生木，肝风鸱张，以致发时，状如中厥。经谓诸风眩掉，皆属于肝。温补药重，激动肝阳，其胸胀呕吐，不饥不便者，无非肝风扰胃，阻胃之降而然。使果真阳飞越，雷龙不藏，则脉必浮大无根，证必烦躁，无暂安时。且前服温补诸方，岂有不效，而反病增之理。所定制肝安胃，尚有商者，盖肝阳冲逆，非介不足潜其威，木火沸腾，舍酸无可敛其焰。拟于方内加牡蛎乌梅二味，更觉相宜。痰涎频吐，胃液必伤，再加赤斛蔗汁，益阴保液，尤为符合。", "15427": "脉大不敛，阳虚，体质兼多烦劳，旧病喘汗，服温补煎丸相安。月前偶感咳嗽，续见鼻衄痰红，日来吐多不止，口苦食减，头昏气促。若论寻常吐血，不过肝肺之火，药股清降，火平，其血自止。尊体精气本虚，一阳初复，形神交劳，水火不交，气随血脱，病关根本，再投清降损真，则阴阳离决矣。先哲有见血休治血之语，可味也。议从黑归脾汤，培养心脾，佐以生脉保金，摄纳肾气。服药三剂，血止脉敛。经云：人四十而阴气自半。平素质亏多病，今复大失其血，生生不继，脏真耗伤，灌溉栽培，尤非易事，夫血虽生于心，藏于肝，实则统于脾。古人治血证，每以胃药收功，良有以也。再按痰之本水也，原于肾，痰之动湿也，由于脾。《内经》以痰多为白血，此果痰也，果精血也，岂精血之外，别有称痰者耶。故昔贤又有见痰休治痰之论，参五阴煎，水土金先天一气化源也。", "15428": "向患血证，发将匝月，医用血脱益气之法，未为不是。惟嫌脉数不静，肌肉咽干，呛咳莫能正偃，咳甚则血来，咳止血亦止。血去阴阳，阴不恋阳，水不制火，刻值金燥秉权，肺被火刑，金水不相施化。《医贯》云：不投甘寒以降火，骤用参耆以补阳，此非医误，不知先后著也。自述胸脘乍觉烦冤，即咳频血溢，按冲为血海，其经起于气街，挟脐上行至胸中，冲脉动则诸脉皆动，岂非下焦阴火上逆，血随火升之故耶。火在丹田以下曰少火，出丹田以上曰壮火，少火生气，壮火食气。欲止其血，须止其嗽。欲止其嗽，须熄其火。然非寻常清火止嗽之药所能奏功，务使下焦阴火敛藏，火不上逆，金不受刑，嗽止血自止矣。", "15429": "安波按：拟一阴煎，加青铅山萸，收纳冲脉之逆。", "15430": "寒热仍来，邪犯未解，口仍不渴，体犹怕风，时当盛夏，姜附服至四剂，并无火象，使非阴暑，安能胜任。不问是疟非疟，总属正虚邪留，辅正即所以祛邪，强主即所以逐寇。昨发热至五更，汗出始退，今日午初又至，呕恶呵欠，前次尚有微寒，此番并无寒意，脉见弦急，由阻转阳之机。大凡阴证得以转阳为顺，证既转阳，温药当退，中病则已，过恐伤阴。病经多日，正气受亏，辅正驱邪为是。汗出热退，头痛稍减，脉仍弦急，舌苔转黄，疮刺俱见，寒邪化热无疑。恐其热盛伤阴，酌以补阴益气煎出入。质亏感证经十二朝，单热无寒，午初起势，黎明汗出退凉，确系伏暑为病，较之伤寒，其状稍缓，较之正疟，寒热又不分明。经云：少阳为枢，阴暑伏邪，得从枢转，尚属好机，不然则邪正溷淆，如白银中参入铅铜，不成银色矣。夫伤寒一汗可解，温暑数汗不除。盖暑湿之邪，伏匿膜原，所以驱之不易。今寒邪既化，似可清凉，惟嫌受病之原，终从阴分而来，甫经转阳，苦寒未便骤进。昨用养阴和解，夜热稍轻，头痛稍减，脉急稍平，窥其大局，守过二候，当可获效。热来稍晏，势觉和平，黎明退凉，渴饮较多。汗至午时，尚未收静。夫暑汗与虚汗不同，经言暑当与汗，皆出勿止，脉急渐缓，头痛渐轻，小便渐淡，邪剩无多。今将二候，愈期不远，按纯热无寒，曰瘅疟，瘅即阳亢之名，用药自应转手。昨热作止，势犹仿佛，脉急已平，神采稍好，惟舌根尚有黄苔，口犹作渴，仍属伏暑余波，今明两日，热难骤止，好在发作有时，上瘅疟同例。内经以为阴气孤绝，阳气独发，参加减一阴煎。昨热仍作，其势较轻，证属瘅疟，因系伏暑，了无遗义。喻氏论瘅疟，会《内经》、《金匮》微旨，从饮食消息，调以甘药二语悟入，主用甘寒保阴存液，《指南医案》治用梨蔗，亦此意也。推诸病状，似与秋时晚发之证相类，气候稍有不符，情形不略则一。必须两三候外，日减一日，方得全解，届期可许霍然。", "15431": "恙经两旬，起初喉痛，清凉叠进，喉痛虽好，变出舌强语涩，食少形疲，头昏足麻，虚里跳动，一派虚象。切防肝风变幻。若恐余烬未熄，亦当壮水养阴，断无再用苦寒之理。舌乃心苗，肾脉系舌本，当于心肾两家，求其水火既济之道。早诊言防肝风变幻，午后突然口眼歪斜，心悸肢掣，此肾真下虚，水不涵木，以致内风鼓动，更怕痉厥之险。经云：肝苦急，急食甘以缓之。祖千金复脉方法。连日肝风已平，食少欲呕，人以胃气为本，病久正亏，全仗饮食扶持，胃气不旺，药难奏功。究缘前患喉证，煎吹二药，清凉过度，脾胃受伤，不必虑其有火，且恐变为虚寒。脾开窍于口，脾和则口能知五味。口冷不渴，岂非脾胃虚寒之明验。与温养脾阳，仿理中六君方意。服药两剂，呕止胃安，虚里跳动，舌强口歪，诸证尚未见效，虚风不息，谷少胃虚，固当扶助脾元，建其中气。第土由火生，既虚且寒，更须兼补其母。", "15432": "日前诊视，拟属质亏，受暑热伤胃阴，诸呕吐酸，皆属于热。商仿黄土稻花汤，养胃涤邪。服药呕减热缓，惟舌腻未退，脉急未和，寐仍欠逸，心烦体躁，正虚邪留，辅正兼理余波。治法固虽不谬，所嫌热久呕多，形倦不支，目阖少神，不独伤阴，亦复伤气。不患邪之不除，而患正之不守。未可以呕减小效，恃而不恐。昨夜仍不安寐，今日巳刻，陡然神昏齿噤，状类痉厥，舌苔黄腻，反甚于前。证虽多朝，伏邪未透，本体向亏。况经三候之久，驱辅两难，暑喜伤心，风喜伤肝，入心则昏迷，入肝则瘛疭，其危若此。姑订甘露饮，合干一老人汤，养正涤邪，稳持不变，庶可转危为安。夏暑内伏，秋时晚发，前见热势鸱张，不得不为清凉，复虑正气不胜，兼佐养阴固本，以杜痉厥，脱变其热，朝轻暮重，口渴心烦，舌黄欲黑，足征内热燔灼。若非急为徙薪，必致焦头烂额，幸得热退，方许坦途。质亏伏暑，病经多朝，邪热虽减，正气更虚。自云心中焦烦，口渴嗜冷，固知邪热未清。然形倦如此，清凉又难再进，前案所谓不患邪之不除，而患正之不守，洵非虚谬。原知邪实正虚，未敢直行荡扫，无知邪热蕴炽，舌苔欲焦，神迷欲厥，所商养阴固正，清热涤邪，睹斯证状，邪未净而正欲倾，将何图治耶。复脉生脉合参，再望幸成。昨订亟固真元以拯危殆，夜来狂叫晕汗，黎明神识渐苏，脉大稍敛，面赤略退，舌苔仍黄，口仍作渴，头额手心尚有微热，倦怠依然。惟询问病原，略能应对，较昨昏沉形状稍好，质亏载邪，纠缠四候，正虚固不待言，余烬似乎未熄，苦寒虽不可投，甘寒尚可佐用。证将匝月，危而复苏，虽属伏邪黏著，迅速难驱，亦由正气不充，无力托达。凡治质亏加感之病，起初最难著手，不比壮实之躯，发表攻里，邪去病除之为易也。神明清爽，似属转机，然肌热未退，大便欲圊不解，固非实热为殃，亦缘虚焰不熄，仍议育阴固正，濡液存津，阴血下润，便自通耳。养阴濡润，便仍未圊，热仍未净，病人自言心烦口渴，喜吃生冷，总属热久阴伤，津液被劫，虽仲景有急下存津之法，现在正气动摇，焉能商进?考诸张介宾及高鼓峰前辈，所论伤寒温暑，热甚伤阴，舌黑便闭之候，悉用左归六味甘露等方，以代白虎承气，见效虽迟，稳当过之，谨宗其旨。病候缠绵，变幻不测，刻诊脉耎，形疲，气坠，都系虚象，外热已轻，舌苔既退，内热料亦无多，大便未圊，腹无苦楚，听其自然。知饥啜粥，胃气渐开。一意固本培元，当此九仞，加意留神为上。", "15433": "经云：阴虚阳搏谓之崩。又云：悲哀动中，则胞络绝。阳气内动，发为心下崩，病机已见大端。至于治法，方书虽有暴崩宜温，久崩宜清之语，要知此温清二字，乃示人大意，未可执论也。夫气为血之帅，暴崩气随血脱，每见晕汗诸证，故宜甘温，以益其气。盖有形之血，不能速生，无形之气，所当急固。初非指温字为温烈之温也。阴为阳之守，久崩血耗阴伤，每见躁热诸证，又当滋养，以培其阴。盖壮水之主，以镇阳光。盏中加油，浮焰自敛，亦非指清字为清凉之清也。病由半产失调，始而经漏，继则崩中，黑归脾汤一方，按心脾肝三经用药，暴崩之顷，洵属合宜，若谓反复之故，除肝脾失其藏统之外，或情怀不释，因怒动血者有之，或冲脉空虚，不司约束者有之，或肾水下亏，不能坐镇心火者有之，或元气大虚，不能收摄其血者有之。断无因服归脾汤而反致崩之理。凡血离宫便成块，未可见血之有块，即认为瘀。果真内有蓄瘀，必然胀痛拒按，何崩决数番，腹无所苦耶?血色紫黑，固多属热，然须辨其热之虚实。经言阳搏其阴必虚，心崩由乎悲哀太甚，其旨可见。再按肾开窍于二阴，冲为血海，脉起气街，据言小解后血随溢出，此肾真下亏。冲脉不固，益彰彰矣。", "15434": "病由不得隐曲，以致脏真内伤，经期阻闭，女科不察病原，佥用清热安胎，愈医愈剧。考金匮虽有䗪虫丸治虚痨血痹之法，顾此羸躯，恐难胜任。即水土金俱病，古人亦无笼统治理。议以早用四阴煎，育阴保金，晚仿周慎斋前辈，淡养胃气，甘益脾阴。盖土为物母，脾乃至阴，其他退热止嗽之药，皆置不用。叶氏云：勿见热而投凉，勿因咳而理肺，诚哉是言也。形瘦阴亏，脉虚近数，证见咳嗽侧，卧汗多食少，经停九月，失红三次。据述曩因腹中微动，疑是妊娠。经云：妇入手少阴脉动甚者，孕子也。又云：身有病而无邪脉也。今脉证如此，谅非孕征。果真有孕，不过气血之虚，胎不长养，虽费调理，尚在可为，无孕则血海干枯，势走怯途，殊难著手。且妇人重身，即有病端，但去其病而胎自安。漫究妊娠之是否，惟论疗治之何知。君以育阴保金，佐以调养胃气，夏至一阴能复，差可保守。", "15435": "安波按：女子以血为主，首重在乎冲任。治冲任之法，首重养血，胃为冲脉本，故阳明气旺，则月事行。先生以育阴调胃，良由斯乎。", "15436": "安波按：案内直犯心肝之句，似欠融化，盖暑邪最喜犯心，其故由肺逆传，肺病则肝无所制，故手足制动矣。下句有五十余日之久，其邪深入下焦阴分，故前辈以甘露复脉等方，虽不治肝，而已治肝。下言肝风两字，日久者少似。盖肝居位不及心肺之高，岂邪一中即直赴至阴之地乎。", "15437": "年届五旬，心事内伤，兼挟外邪，误药因循。邪留不解，脉濡无神，汗多头晕，交午寒热。此阴阳衰惫，邪正交争，乌可与传经少阳之寒热同语?张介宾云：邪气如贼，其来在外，元气如民，其守在中。足民即所以强中，强中即所以御外。斯证斯时，曰但驱邪可以却病，吾不信也。曰舍辅正可以拯援，亦不信也。仲圣云：伤寒若吐，若汗，若下，若温，针不解者，名曰坏病。知犯何逆，随证治之。虽然理固如斯，而病已濒危。大厦欲覆，一木恐难撑持。劳感经旬，因循误治，邪陷正亏。喻氏所谓轻则半出不出，重则反随元气缩入。观其晕汗，每现于寒热之顷，此阴阳交争，正不胜邪，脱机显露。如盗入人家，门户洞开，藩篱不固，主惫如斯，何堪与贼角胜负邪。请先救人，后医病。", "15438": "诊脉细濡，恙经多时，始而便泻，继则下血，渐致食少欲呕，形疲心愦，药无灵效。略投辛温，血下即多，稍用清凉，饮食即减。辗转却难借箸。然医贵变通，未可见病治病，印定眼目，经曰：湿多成五泻。病始于泻，脾虚酿湿，治湿固宜于燥，但脾为血之统，刚燥过剂，致动其血，内溢不已，阴络受伤。无如养阴之品，恒多腻滞，又与脾胃欠合。此培其中州，抉其土母，不得不为之亟亟也。昔贤治血证，每以胃药收功，土厚自能胜湿耳。酌以淡养胃气，甘益脾阴，宗嘉禾饮。服药数日，谷食稍增，视其病状，与痢相似，即痢久正气未有不亏，亦当培养本元，资其生气。据述脘中如饥如嘈，是属下多亡阴，兼伤其气，观其得食则安，情已显露，方内参力加重，佐以乌梅，取其酸能生津，并可摄血。再考方书，论久痢病根在大肠曲折之处，药力所不能到，有用至圣丹一方，余仿其法，治验颇多，可备采择。经云：阴络伤血内溢。然药用清热养阴而不效者何耶?经曰：营出中焦，中焦取汁，变化而赤，是谓血。中焦盖指胃而言。夫胃为水谷之海，气血俱多之经。病之浅者，饮食如常，旋去旋生，病之深者，谷少气衰，所生不偿所耗，脾与胃以膜相连，胃弱则生化无权，脾虚则统摄失职。书称不问阴阳与冷热，先将脾胃为调和。万物以土为根，元气以土为宅，议进归脾理当如是。又述向有肝阳冲逆之恙，近兼举发，方内加入首乌，既可益阴，又可固摄，非熟地滋腻可比。乌梅畏酸，不用亦可。但肠滑已久，须参涩以固脱。李先知云：下焦有病人难会，须用余粮赤石脂。便稀食进，大有好机，病缠两月，气血受伤，以故尻骨酸楚，颊车乍痛，便时急坠，行动乏力。初议专培脾胃，乃血脱益气之法，续进归脾，乃虚则补母之方。李士材先生云：先天之本在肾，后天之本在脾。二脏安和，百骸皆治。今既食增泻减，脾胃已调，自当进加肾药。治疗匝月，诸证均减，寝食俱安，精神渐长，体素阴亏，加以便血，久伤阴络，屡服胃药，气分虽充，阴犹未夏。金为生水之源，金燥不能生水，是以上膈焦干，鼻痒咳呛。夫药随病转，移步换形，医如珠之走盘，贵乎活泼。气不足便是寒，气有余便是火。改议养阴润肺，金水相生，津回燥自濡矣。经言：虚邪贼风避之有时。恙后体亏，加受外因，形寒头痛，脘闷欲呕。然舌无苔，脉不急，受邪知不甚重，正气不充，未可直行表散，治宜辅正驱邪。外感已解，痔疮举发，肛痛便复见红。然每日便止一次，并不溏泻，此乃痔血，非前肠血可比。痔平血当自止，知饥能食，食后脘中微痛，按胃司受纳，脾主运化，脾健失职，运化较迟，若果食滞致痛，则饱闷不饥矣。地黄益阴固妙，稍嫌其腻，不利于脾。暂商养胃调脾，复诊再筹进步。据谕向来冬春左畔畏风，夏秋上焦热闷，药投清散，服时虽效，过后依然。揆度其故，谅缘营卫失和，籓篱不固，邪之所凑，其气必虚。断无六淫之邪，久羁人身之理。使非探本寻源，徒泛治标无益，且俟新病瘥后，再为图之。下极为魄门，魄门亦为五脏使，痔血去多，阴亏阳冒，上焦燥热干咳，阳加于阴，谓之汗。前则泻多纳少，故仿胃药收功。兹则大便如常，多食善饥，病情迥别。丹溪谓男子阳常有余，阴常不足，阳主动，阴主静，理当育阴济阳，静以制动。据言每届秋时即患咳嗽，服清润之剂颇验。目前感后，恐有余邪，地黄滋腻，似未可服。按质虚偶感，邪本无多，既已驱逐，谅无逗留。肺与大肠相表里，肠热上熏，肺燥则痒，痒则咳，此咳嗽之故，非关于风，而实由于燥也。经云：燥者濡之，痔血咳嗽，同归一途，无烦分治矣。", "15439": "本证风痱，近加受暑，脉虚身热，倦怠口渴。经云：脉虚身热，得之伤暑，暑伤气是以倦怠。夫暑乃六淫标邪，虽无大害，特恐质亏不胜病耳。商仿清暑益气汤大意，以俟消息。脉仍虚急，热甚心烦，夜不安寐，方内酌除耆术，加以玉竹，本草言其用代参耆，不寒不燥，且能治风淫湿毒，寒热痁疟，大便五日未圊，小溲数热，肺与大肠相表里，又与膀胱通气化。古人治暑证，每用生脉散者，以其有保肺清金之能也。病躯加受暑邪，恙经六日，两进清暑益气，辅正涤邪，形倦肤干，热仍熇熇，心烦口渴，溲数便闭。张介宾云：干锅赤裂，润自何来，但加以水，则郁蒸畅然，而气化四达。宗玉女煎。早服玉女煎，薄暮复视，病势依然。暑邪留著，原难急驱。今日已服药两渣，末便再进，暂与荷蜜煎代茶。便通肤泽，往日早晨热缓，交午复甚，心内如焚，今午热势平和，无焦烦辗转之状，病躯治标，亦不得已。兹既势平，自当斟酌，无使过也。前药退松，昨午其热复甚，溲数口渴，心如煎熬，质虚恙重，况加反复，切虚变更。揣诸病情，得无心营胃液，为热灼伤，以致焦烦嘈杂者欤。宗阿胶鸡子黄汤法。", "15440": "病逾四载，起初呕吐，渐致经期不行，温清攻下，遍投无验，医乃视为痨瘵，弃而不治。诊脉不数，亦无风消息贲，寒热咳嗽兼证，似与痨瘵有间。果真损怯已成，病人膏肓，焉能久延岁月乎?经云：治病必求其本。又云：先病为本，后病为标。恙由呕吐而起，自当以呕吐为病之本也。苟能止其呕吐，则仓廪得藏，生生有赖，气血周流，诸证不治而自安矣。考诸方书，论吐证非止一途，斯病既非真寒，又非实火，所以温清俱不投机。至于下法，乃治伤寒暴急之方，施于内伤久病，殊属悖谬。询其饮食，下嗌停注膈间，不肯下行，旋即呕出，冲逆不平，时时嗳噫。所以然者，乃肝为受病之源，胃为传病之所，胃宜降则和，肝气横逆，阻胃之降，致失其和而为患也。夫脾为湿土，胃为燥土，六君异功，止可健运脾阳，今病在胃而不在脾，湿燥异歧，不容笼统而论矣。再按肝为将军之官，脏刚性急，木喜条达，最嫌抑郁。古人治肝病辛散酸收甘缓，与夫补水生木，培土御木，方法多端，非仅伐之泻之而已。治宜安胃制肝，厥阴阳明两调，王道无近功，戒怒舒怀，以佐药力为要。", "15441": "病逾一年，医称阴亏阳升，水不制火，育阴清火潜阳，屡治无效。若云痨瘵已成，非草木之所能治。现在饮食如常，脉不细数，似又不侔。求其何以屡治不效之故，理殊难测。岂非另有隔膜未窥透耶?据述病缘旧春郊外垂钓，感冒风热而起。经云：肺主皮毛，皮毛者，肺之合也。皮毛先受邪气，邪气以从其合，此肺为受病之原，比诸劳风，法在肺下，巨阳不能引精，青黄之涕，不能咳出，适足伤肺之例，当时虽曾服过清解之剂，但外邪入肺，如油入面，有仓卒难以浣涤者，胶黏酝酿，郁而为热，郁热熏灼，津液受伤，所谓因病致虚者，由肺病而累及之也。何以言之。凡人咽喉两管，咽通于胃，喉通于肺，今喉虽辣痛，而纳食无碍，可知其病在喉而不在咽。人身之气左升右降，肝主升，其脉萦于左，肺主降，其脉萦于右。今左畔肢体如常，而病端偏著于右，足见其病在肺，而不在肝。肺脉虽萦于右，然位居上焦，为脏腑之华盖，观其上脘烦热，时冲喉咙，颈下皮肤作痒，搔爬如痱，咯吐痰色灰黄等因，其为肺脏蕴热，金燥液干，情已大露。再按大便坚硬，数日始一更衣者，肺与大肠相表里也。倘果因虚致病，悉属内伤，水不制火，而致喉痛，早已咳血音嘶，走入怯途，焉能缓待。且滋阴壮水，药证相符，何以久服不应耶?然病情虽窥一斑，治法尚难计议。盖治病须分新久，用药贵审机宜。病初体质无亏，治惟涤邪，无庸顾虚。兹则病魔经岁，正气已亏，岂容孟浪!进而求之，肺为娇脏，喜润恶燥，邪热久处肺中，金被火刑，津干液涸，是以养阴药饵，只可滋其津液之干，莫能驱其蕴伏之燥耳。古人治燥甚少良方，惟西昌喻氏，会悟经旨，发明燥病，根源见得，诸气𪱥郁，诸痿喘呕，以及心移热于肺，二阳之病发心脾，各种病机，俱关于肺。所立清燥救肺一方，颇有深意。盖辅金制木，即所以治肝，清肺澄源即所以治肾，僭仿其法，谅当有应。", "15442": "质亏，生育多胎，此番重身三月，又复半产，气随血脱，昏晕频发，幸赖独参汤挽回。日来热发不退，时时怯寒，舌白，喜饮热汤，头痛形倦，脉急无力，合参脉证，明是气血两虚，即有外邪，投鼠忌器。丹溪云：产后当以大补气血为主，他证从末治之。仿甘温除大热之旨。下午复诊，脉象仿佛，早间服药，安眠片时，顷复寒热交作，此属阴阳两虚，正气不胜，非疟证也。原方更进一渣，明日再议。两进甘温，昨午寒后热甚，扶掖下床，小溲遗出，直至半夜，热始渐缓。切恐今午寒热复来，撑持不住，揣其寒热之故，非阴阳两亏，即正虚邪陷，当此危迫，不问有邪无邪，一意扶元固本。盖辅正即所以祛邪也。本草谓人参能回元气于无何有之乡，古人治气随血脱之候，悉仗参力斡旋，昨药分两固虽加重，惜乏参力，故难奏效耳。昨午寒热仍来，神形益倦，二更后热势渐平，然起床劳顿，即作昏晕，顷进诊间，晕又复发，连服温补大剂，尚未见功，即云寒热由于外因，睹此狼狈情形，焉可再从标治。仍守原制，佐以河车，亟挽真元。医当医人，不当医病。昨夕昏晕频作，顷诊右脉虚要，左犹带数，体倦无力，气怯懒言，虚象无疑。病缘质亏半产，加之寒热纠缠，波涛汹涌。现在热退神清，固见小效，奈病来势暴，大厦摇摇，前议补元归脾，更从养营进步。两日未诊，脉象依然，在前发热之际，脉由热搏而数，今外热既退，理当和缓，何至数犹未平。口不干渴，并无火象。无非产时血去过多，营阴受亏，脉乃血派，是以急数不平耳，但诸药皆是草木根荄，人身真元耗伤，仓卒焉能挽转。参力既艰，他策又无可画，前方减去辛温，稍佐柔和之品。产后崩晕，血气大亏，阴阳枢纽不固，见出种种疲惫之候，赖诸温补药饵，竭力挽回。寒热已除，胃安谷纳，无如事多磨折，臀生疡毒。痛楚不安，疡甫溃脓，痛势稍定，又加时感湿邪，腹痛便泻，节外生枝。暂与香砂六君，俟其痛泻愈后，仍须峻补真元，冀图恢复。", "15443": "孕妇脉来滑数，证见便溺不通，二阴牵胀，足膝浮肿，医药滋阴，疏利升举，屡施不验。按肺与大肠相表里，又与膀胱通气化，是二便之通闭，肺有所关系焉。金燥水无以生，清肃之令不能下降，是以二肠交阻。喻氏谓人身之气，全关于肺，肺清则气行，肺浊则气壅。清肺之热，救肺之燥，治其源也。气行则壅自通，源澄斯流清矣。凡禽畜之类，有肺者有溲，无肺者无溲，故诸水道不利而成肿满者，以治肺为急。前商清燥救肺，小溲虽通，大便未畅，足肿未消，二阴仍然牵胀，夜卧不适，口苦舌黄，原方加枯芩梨汁。", "15444": "经云：肺气通于鼻。又云：胆移热于脑，则辛頞鼻渊。可知鼻渊一证，病端虽责于肺，实由胆热移脑之所使然。证经数载，腥涕流多，肺肾为子母之脏，金被火刑，阴液受伤，加之鼻窍右侧，旧夏曾已穿溃，甫经收口，左侧又溃一孔，至今红肿未消。经谓热胜则肿。虽由胆移之热，酝酿为患，但治病须分新久，诊脉数大无力，是属恙久，阴虚阳浮，非新病实热可比，苦寒伤胃，洵非所宜。计惟壮水保金，冀其水升火降，庶几红肿可消，溃口可敛也。", "15445": "经云：呼出心与肺，吸入肾与肝。是肺主出气，肾主纳气。肺为气之主，肾乃气之根。母藏子宫，子隐母胎，金水相生之义也。前商保金生水，纳气归根，正本澄源，治不为谬。据述服药脘中微觉痞闷，心疑药补，即不敢尝。此由胃虚不能传送药力之故，与补无干。如果补之为害，何喘不见增，病不见甚耶?经曰：能合脉色，可以万全。岂色悴神疲，喝喝不继者如是，而能以耗散收功者乎。先哲有云：喘生毋耗气，气本弱而复耗之，元本亏而复竭之，抱薪救火，入井下石，脱机甚速。勿怪言之不祥。", "15446": "恙经三月，脉大而急，证见呛咳气筑，胸满背胀，夜不安卧，卧则气冲，呼吸不利，目烂舌赤，口干心烦。审诸脉证。是属肺感燥邪。加之抑郁，痰气胶结，肺窍阻闭，清肃失司，酿成肺痹危险。盖肺为气之主，肺气逆则诸气皆因之而逆矣。平素质亏受补，兹则补剂不投，虽虚虚而病则实，不去其病，徒补无益。经云：诸气𪱥郁，皆属于肺。秋伤于燥，冬生咳嗽，计惟清燥宣痹，幸得胸展痹开，方许机关衄转，仿苇茎汤遵《金匮》法。服药四剂，喉口燥象稍减，舌根焦苔亦退，脉象依然，痹犹时发，甚则胸膈䐜胀，喘喝不已，欲人捶摩，咯出浊痰，略觉宽展，病由燥邪蕴伏上焦，治节不行，痰壅无形之火，火灼有形之痰，交相为患。夫痹者闭也，内闭则外脱，至危至急，无如上焦不开，未能填补其下，是以每投补剂，其闭更剧。按肺窍蕴结之痰，如屋之游，树之萝，石之苔，胶黏滋蔓，岂寻常消痰之品所能芟刈。原方加蒌皮海石，轻清宣痹，病象未减，下虚不能纳补，上实通之无功。消补两难，颇为棘手。据述每痹甚时，惟饮菔水则痰气稍平，即此推求，定有顽痰胶黏肺管，阻塞气机，苇茎频投不应，惟有进步葶苈一法，非不虑及老人质亏难任，当此危迫，畏首畏尾，身其余几，奈何。苇茎葶苈，乃金匮治肺痹两大法门，前因年高恙久，不敢骤用葶苈峻攻，惟取苇茎轻清宣痹，冀其病去，元气不伤，服药虽见小效，痹终未宣。前论燥热酝酿为痰，肺窍气机阻塞，清肃失司，因而逆满，却非谬语。夫顽痰滋蔓，譬诸顽民，不服王化，不忍猛而宽，则萑莩盗风，何由而息。所加葶苈，虽系无可如何，亦理之所当然，非徒行险侥幸也。现在痹势稍松，足见有故无殒，从来峻剂，原属可暂而不可常。然证经数月之久，痰热弥漫已极，甫得稍开，若旋行易辙，病根尚在，虑其复萌。今早鼻仍流血，可知肺火未清，方加石膏、山栀、竹沥彻其痰热余波，今夜得以痹再减轻，明日可为转手。老人病逾百日，痰凝气壅，肺痹不舒，上实下虚，原难想法，数番诊视，因其痰火势盛，不能受补，无已初投苇茎轻清宣肺，继进葶苈涤饮除痰，佐以膏栀竹沥，以彻痰热余波，此皆古人成法，非杜撰也。今痹象稍减，虚状渐露，高年恙久，恐其元气不支，商佐保金辅正。", "15447": "女子二七而天癸至，任脉通，太冲脉盛，月事以时下，故曰月经。经者常也，反常则为病矣。是以妇人首重调经，经调则百病不生，失调则诸证蜂起。夫血生于心，藏于肝，统于脾。而冲为血海，血犹水也。若江河之流行，设有枯涸崩决，其为患也大矣。求其致病之因，有谓血枯者，盖女子以肝为先天，索性多郁，木郁生火，火灼阴伤，以致经血日耗，地道不通。经言二阳之病发心脾，有不得隐曲，女子不月者，此也。有谓崩决者，崩如山冢崒崩，决如波涛横决，盖血属阴，静则循经营内，动则错经妄行。经言。阴虚阳搏谓之崩，阳气内动，发为心下崩者，此也。病经日久，形瘦阴亏，木火郁勃，旧春经阻崩晕，现又愆期两月，勿愁血之不行，切恐崩患复发。议养肾阴以济心阳，兼培冲任，冀其生生有自，血气调匀，无错妄之虞，复经常之度，不徒病去人安，更可勿药有喜。", "15448": "经云：风寒湿三气杂至，合而成痹。风气胜者为行痹。据述证由右足膝盖，痛引腿胛，渐移于左，状类行痹。行痹属风，治以驱逐，理不为谬。但邪之所凑，其气必虚，况童质禀薄，肾元未充，驱逐过猛，血气受亏。肝主筋，筋无血养则挛急，脾主肉，肉无气煦则枯瘦，以致腓日干，髀日肿，足不任地，酿成废疾矣。古云：治风先治血，血行风自灭。闻所服诸方，非全无治血之品也。无如桂麻羌独，药性太狠，难以监制，故只见其害，不见其益。在病初血气未衰，犹可辅驱并行，今则疲惫如斯，尚有何风可逐，何络可通?倘再求速功，见病医病，非但病不能医。而命亦难保矣。要知疾即成废，欲图转泽回枯，诚非易事，惟有培补肝肾一法。膝为筋府，肝肾之脉，丽于足，足得血而能步。复有调养脾胃一法。四肢皆禀气于胃，脾病不能为胃行其津液，脉道不利，筋骨肌肉皆无气以生，故不用焉。脾强胃健，四肢得禀谷气，脉道流行，自能充肤。热肉二法，虽不言治病，然治病之旨，在其中矣。", "15449": "曩议和中通腑，大便解后，痞闷渐舒，谷食稍进，时候寒暄不常，质虚最宜加感，以致寒热愈而复作。日来寒象虽除，热犹未净，脉虚近急，是属节外生枝，尚非本证变幻，特元亏未复，腠理空疏，起居最宜谨慎。若谓此番寒热不关外感，全属内伤，则是阴阳两虚，奇经为病，不应急骤至此。且内伤之寒热，当在日晡，日日如是，不能偶然。其状洒淅，亦不若此之重。据理推详，似当不类，现在大便又复旬余未解，腹中虽无所苦，总觉欠舒，呆补惟恐不受。所以然者，病由湿凝气滞而起，医药庞杂，胃腑欠和，输化失职故耳。淡养胃气，甘益脾阴，参以润肠，不至蹭蹬再生，自可渐跻蔗境。复诊便虽半月半圊，腹无所苦，下不嫌迟，毋庸亟亟。日前感复，寒热作后，至今申刻仍有微潮。热时口渴，交戌汗出始退，固属余波未清，但热久津液必伤，商进养阴，阴血下润则便通，非徒退热已也。感证反复，热盛阴伤，肠枯便结，叠进养阴濡液，热退餐加，脉急已平，神采渐转。据述昨午便圊燥粪依然，努挣艰难，足见病魔经久，元气受亏，津液未充。便通犹防复闭，按救阳气当用建中，救阴液须投复脉，宗《千金》方法，佐以人乳团鱼燕窝，血肉有情，且俟液复虚回，胃强脾健，再议善后之图。", "15450": "时热四日，头痛身热，舌苔腻白，胸闷，口干而喜热饮，脉俱沉象，邪伏募原。", "15451": "午后大汗，热势渐退。主家因头汗过多、四肢清凉，以为虚脱之象。余至，细绎病情：出汗未半刻，所以汗多者，因棉被过遏所致，非虚脱之汗也。况病者清爽，问答明白。表邪固从汗解，而里热亦从斯而退矣，否则，问答何能自如？而脉象惟有细数，并无虚脱之象。倘轻信旁言，自无主见，未免误人。察脉审证，望色听声，于四诊中悉心推索，庶几得之矣。汗解后，用后方清其余热。", "15452": "时热半月，人事不知，狂叫呼骂，不避亲疏，诸医束手，坐以待毙。其母寡居，独此一子，索治于余。细按脉象，左寸、关数而带滑，此热邪入里，痰火壅闭。当清心、肝之火，佐以开窍豁痰，庶可图其转机。", "15453": "服前方并敷药后，觉膝盖中温暖松爽，稍能伸，筋脉渐有活动之机。再如前服，右膝之坚硬亦渐有柔软之象。", "15454": "右耳常鸣，七载以来苦无宁刻。细按脉象，左关虚弦，两尺虚数。水火未济，相火未静，治宜养水济火，俾火下降，则耳鸣自平，匪朝伊夕也。", "15455": "病后脾虚，四肢、面目浮肿，腹大脐凸，肿及阴囊，鼓胀将成，幸未过投杂药，尚可挽回造化。脉象虚弦，舌之两旁有紫红胎两条，约各半寸。夜睡不久即醒，腹胀兼疼。病起月余，食饮稍减。", "15456": "风痰上壅，喘哮声急，脉象沉细，气逆不能卧，议用代赭旋覆法。", "15457": "服后喘定哮平，脉亦渐起，进粥安妥，再剂而痊。", "15458": "身热有汗，五日未解，兼之腹膨，脉象浮缓。风邪外束，食饮中停。治宜表里疏通，俾邪外达为妥。", "15459": "腰腿酸痛，偏于右畔。寒湿内郁，此脉之所以沉迟而独见于右也。法宜温通。", "15460": "（案12）休宁叶汝良两肩疼痛，筋脉抽掣治验（附药酒方）", "15461": "两肩疼痛，不能举动。皆由寒湿郁于经络，以致筋脉抽掣。病经半载，脉象虚细。先宜温疏，再商善后。", "15462": "时热三候，热邪内蕴，痰火郁闭，时而上逆则蹙頞头摇，时而下奔则转脬甚急。脉则右寸、关细数而滑，左关、尺弦细。知其痰火郁闭，升降不灵也，拟用黄连汤合小陷胸汤加减之。", "15463": "又，大便已解，体虚脉耎。用六君子汤，去白术，加山药、杜仲、木瓜、怀牛膝、建莲肉，服后可以起身，稍可步行。", "15464": "两朝方，案：色滞顶平，脉象虚数，毒火未透，仍宜升散。", "15465": "三朝方，案：平者渐起，滞者渐活，但脉虚无力，恐行浆时不能充足耳。", "15466": "喘咳旧疾复发，痰厚，喘急不能卧，心中热闷，却不口渴，喉中水鸡声，脉象沉细而滑，专治痰喘为最耳。", "15467": "体胖多痰，好饮浓茶，喜啖厚味。湿毒浸淫，近于后项大椎，小者如黄豆，大者如桂圆核，共计十有五粒。滋水淋漓，痛痒异常，甚者出血或出黄水薄脓。迄今十有余年，无分寒夏，不时举发，冬来更甚。医治有年，毫无一效。于嘉庆十三年八月二十一日，甫求治于余。余细绎病情，兼参色脉，知其体肥多痰，喜啖厚味，好饮浓茶。深悉脾中之湿热素盛，胃中之湿痰常存，兼挟湿郁之火而上升头项，发为湿毒。穴近太阳膀胱，而实关乎脾胃也，先以表里双解一法，再为善后之谋。", "15468": "凡灸法不用蒜铺疮上，只用艾著肉灸之，谓之明灸。凡用火补者勿吹其火，必待从容彻底自灭。灸毕即可用膏贴之，以养火气。若欲报者，直待报毕贴之可也。用火泻者可吹其火传其艾，宜于迅速，须待灸疮溃发，然后贴膏。此补泻之法也。其有脉数、躁烦、口干咽痛、面赤火盛、阴虚内热等症，俱不宜灸，反以火助火。不当灸而灸之，灾害立至矣。道光乙酉冬竹亭注。", "15469": "据述风府穴下，十余年来后项常觉板硬，似乎皮如夹袋，手摸之犹如中间有物在皮肉，抓之不仁。疮则不时而发，四季中惟夏稍缓，冬则愈甚。发时头面亦有，项后为最。自今灸后，非惟疮平，且自觉皮肉软和灵活，抓之痛痒自知。所最快者，灸时觉背脊左右两边之气上下往来，气脉温和流通，越灸越快。予闻此言颇是，如《灵光赋》云：灸时气下砻砻然如流水之降者，即此谓耳，足征古人语非泛设，此灸法之妙也。至内服煎剂数十帖，自觉胸中疏畅，湿痰止，呕哕平，食增卧安，此服药之妙也。自八月至此，内外调治，通计八十日而安，亦大费苦心矣。竹亭（邻）识", "15470": "是方内用蜜丸者，即六味地黄丸。以猪苓易茯苓而出入之，以固里而入阴，兼通督脉，直达病所。外用为衣者即六君子合玉屏风散，以固表而通阳。合而用之，诚表里两固、气血并调之良法也。", "15471": "串疬有年，初从足小腿外侧生广疮而起，渐溃出水。疡科作毒治，攻伐太过，腹痛便泄，疮究未平，惟堆沙结盖，盖脱斑黑。未几又发，抓之水出，缠绵不已。药投罔效，本元日亏。于嘉庆二十二年冬间，头颈始发瘰疬，发于右颈，相近牙床骨，形如龙眼，随后又串一疬。于二十三年四月，渐白溃烂出脓，疮口不合，滋水凝结似盖，堆满复脱，脱后依然如前。两疬俱溃，一长一圆，长约寸余，圆如钱大。今春两疬中间又结一核，大如胡桃，坚硬不散。更兼屡屡梦泄，上腐下遗，牵连两载。从外走内，由浅入深，一转虚损，尤难许治。于廿四年四月渡江来吴，与门人金书山为友，特求治于余。余诊其脉，右三部虚软小数，左三部虚弦濡小。知其脾肺虚而坎阳不充，肝肾亏而相火易动。不此之求而专以疡科套药以治疬，非但疬不能除而反节外生枝。然不治疬而概以滋补降火为法则串疬难除。治如之何？曰：善治者，于标本先后缓急轻重之间，兼合外内之道以求治，庶几毒可清而疬可除也。于是月廿九日，先于右臂肩髃穴用葱白捣饼贴穴，以艾铺于葱上灸之，以泻经中之凝滞。灸数壮，觉疼而止。复又于肘后曲池穴中，如前法点火于艾上，亦灸数壮，觉疼而停灸。每间三四日一灸，灸至颈核渐渐化松，核腐脓薄而停。然亦有不宜灸者，全凭望色切脉。俱无一定规则，亦无限定日期也。", "15472": "瘰疬一症，所关甚钜，有因湿痰而生者，有因湿火而生者，有因风毒而生者，有因热毒而生者，有从气弱血滞而成者，有从阳虚阴亏而成者，又或从纵欲过度、淫火炽盛而毒火上窜者。种种情事，察脉审证，于标本后先、缓急轻重之间而求治，斯为尽善，岂可执一以应无穷之变哉。是疬也，色脉合参，知其疬由下焦阴亏，相火与湿毒相绊，始于足疮。《易》曰：「震为足」，足属东方木也。继而上炎项侧，《书》云：「火曰炎上」，惟木生之相火挟湿毒而上升，此瘰疬之所由来也。形如贯珠，坚者坚，而坚如梅核；溃者溃，而溃似桃胶。自去春至今，一年以来医更数手，疬日加深，脓血相兼，亦苦无宁刻矣。自崇游苏，遵海而南，就治于予。予察脉辨色，敢云能治？聊尽婆心，以报知己。今也疗治三月，坚者溃而溃者痊，肌完肉长，循序结痂而愈。未必良工，却有良药，亦先生专一诚心之报欤。昔齐侯怠于皮肤之微，以致骨髓之痼，皆由不专一于医而致斯也。甚矣！医之难也。今毒解火清，疬已痊可，尚有梦泄之虞。始也治标，继也治本，亦先后缓急之意耳。第病经有年，肾水内亏，水不济火，水火隔而心肾乖，交媾之道不堪回想矣。满拟一阴一阳大化云中之雨，谁之三战三北，空扬马上之鞭。设不大补真阴，何能生生不息。然阴非阳不生，阳者气也。气为水母，水出高源。生气者肺，纳气者肾。补肾不补肺是母贫而冀子富，源竭而望流长也，必无是理。况右寸虚软，左尺濡小，又显有明征耶。及早图之，商瞿有后，亦何嫌其迟也。", "15473": "凡热起至收完，但看右手一指脉。洪大有力，虽有别症亦不为害，此定存亡之要诀也。仁端录注。", "15474": "患巅顶痛、鼻塞、目眶疼、齿浮痛。病经一月，诸治不应，乃求治于余。余细按脉象，右寸关浮缓，左尺浮小，知其足太阳受邪而兼乎肺胃，上通巅顶。问其至早远行否？答曰：「缘船务事每每天明早行，自觉为此而得疾，先生何见之神也！」曰：「非神也，凭之于脉耳。」", "15475": "复诊：据述因四肢浮肿俱渐退，停药半月，食减呃增，兼多涎痰。诊其脉，两关弦硬，肺脉短促。固属戊土壅滞，亦关卯木横冲，大非所宜，当静养调摄，以免变迁。议「四君子」合「左金」意。", "15476": "《内经》所谓哕者，即呃逆也。成无己、许学士亦以哕为呃逆也。《经》云：「胃气逆为哕」，哕者即呃也。人之阴气依胃为养，胃土伤损则木气侮之，此土败木贼也。阴为火所乘，不得内守，木挟相火乘之，故直冲清道而上为呃逆。然呃之来非止此也，亦有虚实、寒热、表里之不同，未可一概论之，临时切脉审证可也。", "15477": "案云：背心酸疼，三载沉疴，苦无宁刻。君以病试医，医以药试病。试之久而未能一效者，究未得其窍耳。予岂尚医，敢曰能治。就脉论之，右寸关沉滑而细，湿痰为患。其所以治痰之法，又在乎用药者。拟胃苓汤法。", "15478": "丸方：证脉合参，酸疼每见三椎，肺穴攸关，而揆其源则受累于脾土者居多。盖土虚则生湿成痰，痰湿交阻，脾阳不运而肺金愈弱。外则易于冒风，内则痰凝湿郁，故不时背心酸疼，波及肩臂、腰脊也。虽非疾痛害事，而三载沉疴亦苦无宁刻矣。服予煎剂病减大半，继之以丸，自尔痊可。", "15479": "风疹八载，不时举发，发则肤热燥痒，色红块现，头面遍身以及手足俱有，甚至小腹㽲痛，脉象浮弦，治宜凉血疏风。", "15480": "又，膏滋方：脉右寸虚浮，左关、尺虚濡。卫气不固则易于冒风，营血不充则血热生风。外风与内风相召，肤热痛痒，风疹随起。所谓风独不利于血热之人者，良有以也。治宜固表养血，血行风自灭。", "15481": "余色脉合参，用清火解毒之剂，兼服五宝丹一分，以土茯苓汤调送，日三次。", "15482": "一日自广来吴友人传以种子壮阳之方，并送其鹿茎、驴茎、狗茎三物，配合前方浸酒常服，酌之于余。余细阅来方，用参、耆、归、地、杜仲、川断、首乌、黄精、苁蓉、巴戟、仙茅、淫羊藿、覆盆子、骨碎补、破故纸、菟丝子、狗脊、杞子、牛膝、黑枣等。此广人纵欲之方也，虽有参、耆、归、地辈之补，而其间纯热兴阳助火之燥药颇伙。不惟无益有损，且阴亏之人服此未有不从兹丧生者。即阳虚阴弱者，亦非所宜也，余特阻其断不可服。盖阴阳之道，阳密乃固，两者不和，如春无秋，如冬无夏。故圣人于男女之际，其交会之法度不过，使阳气秘密乃得坚固不泄耳。然而阴阳贵相和，有春无秋是无阴也，有冬无夏是无阳也。所以圣人但调其偏以归和同，允为交会之法度而已，何可偏也。因坚请代处一方，仍欲将前三物配合浸酒之法，因用阴阳两平之药以应之，即经文「阴平阳秘」之旨也。况脉右软小乏力，左脉濡虚，又显有明征耶。", "15483": "今于庚午五月二十七日买舟就治于余。余细审病原，再望其色黄乃熏黄晦色，非明黄娇亮可比，即此可知其为阴黄而非阳黄也，明矣。既知阴黄，则知其在脏、在里，而不在腑、在表，益明矣。再切其脉，左脉弦硬，尺则稍涩；右寸、关虚而细，尺则浮而无力；知其病关脾肺，波及肝肾，于此求治，或可图维。疏方于后，属服十剂，再为斟酌。第乔居槎溪，即日解缆，数百里之遥，服毕之后究不知能从予治否？中无阻隔，竭力调治则幸矣。", "15484": "案云：色脉合参，脾阳不运，肝肾有亏，此黄疸、溲赤之所由来也。但疸经两载，概以治疸套药清热利湿，攻伐太过，恐脾土败而肾阳亏。中满之变，虽「长沙」复起亦无如之何矣。为今之计，宗经旨虚则补母，俾中宫之脾阳得以运动，则肺之元气旺，而能通调水道、下输膀胱，庶肾水不致凌土，肝木不致侮脾，不治黄而黄自退矣，何必枝枝节节而求之。", "15485": "今于庚午九月五日复诊，案云：证脉合参，肝阴有亏，肾水不足，此风疹之所以有年也。宜以壮水以滋木，养血以润燥，而补气之品亦不可少也。益气有生血之能，血无扶气之力也，是又在乎用药者。丙寅冬所定膏方记前七十四页内，可查阅。", "15486": "于十一月十三日始求治于余，余细按脉象，右关细而软，左关、尺濡小兼数，按之不足。素有内痔脱肛，合而参之，治病必求其本。知其肝肾阴亏，小腹乃至阴之地。纵啖西瓜，暑热为寒凉所逼，致脾土伤而中气下陷于阴也。挈领提纲，治在脾肾。", "15487": "咳嗽数日，痰中挟血。案云：脉来细数，幼年咳呛痰红，最防成怯，速于调治，尚可图维。", "15488": "外邪已解，夜来微热，天明渐退，脉象濡小。阴分素亏，治以养阴退热法。", "15489": "据述乃郎素体质薄，白幼有鼻衄、风疹，举发无时。成婚之后，少不节欲，又多咳嗽。于嘉庆辛未二月邸吴，初七日求治于余。病者自云：迩来惟盗汗、腰疼为最。诊其脉，右数急，左弦劲。卫虚营亏，先议固表养血，俾其盗汗止而腰疼平，再为之计。", "15490": "又，二月初九日复诊：服前方盗汗、腰疼已停，而向有之鼻洪又发，更兼咳嗽。证脉合参，皆由于金虚不能平木而肝火上逆，木来乘金，此衄血、咳嗽之所由来耶。况左右脉来弦数而急，又显有明征欤。", "15491": "又，十六日复诊：汗止咳减，脉之数象稍缓，而弦急之势究未平也，弦主于肝。法宜清肺以养肝，肺气旺而木不侮金，金气足而肾水赖以生之，则水能养木，而木自平矣，又合隔三之治。", "15492": "又，二十七日复诊：盗汗、咳呛，脉仍弦急，益气养营是其治法。", "15493": "又，三月初三日复诊：允功因其汗止咳停，意欲在寓缓缓调理。恐新婚之后早归，究防病覆，假此调治，亦爱子之心也。其如子心非是，终日默默无言，体瘦食减。诊其脉，弦急者究未一减。左右寸口脉仍弦劲，火乘金也。两关弦急，木侮土也。左尺虚数，水不足也。水不足则木失所养，肾阴亏则肺金愈虚，未有子贫而母独富者，无怪乎鼻衄、咳呛、盗汗之常发也。今病虽小愈，而脉仍未平，攸关心病，有诸内而形诸脉也。脉既如斯，强留异地则恐变端莫测，而悔之不及也何。允功谓予曰：「君何知之深，而见之明也？」曰：「病以脉为主，今病减而脉不减，寸脉仍弦急，此心病也。更见肝脉弦，出寸口，上鱼际，则为思室何疑。年少新婚，归心如箭，而必欲阻之，大非所宜。」允功深信余言，恳求丸方途中调理，因以益气养营、壮水滋木之法以应之。于是月初八挂帆回里，与其后悔，莫如早归为善也。后于壬申春仲邸吴，适允功至主戚患病于苏，特荐治于予。述及乃郎回家未几而逝，允功始信予之脉理毫发无爽也。", "15494": "当脐作胀，胀在午后，不食亦胀。痰黏口干，却不喜饮，惟法制半夏或蔗浆润之，则口干缓、黏痰减，而其胀则仍然。向喜饮酒，迩来不敢饮，饮之则上焦觉热，痰愈增，胸中不爽。年近五旬，病起于嘉庆戊辰五月，据述医更数手，药服罔效，于辛未闰三月初二乃延余诊。观其诸方，有因胸闷、痰多而用香燥破气者，有言阴虚而纯用滋阴腻补者，更有因口干腹胀而以知柏地黄汤加破气疏通之品者。其余之方杂乱无章，更不足观。据云每服一二剂似乎稍减，再服之则胀势愈增，而口干、胸闷等情亦愈加矣。病近三载，终未得瘳，其所以不瘳者，皆缘医者只识病标，不识病之本也。第知治胀，而不知胀在当脐，脐属于肾。胀在午后，午后属于阴。再请验之于脉，右关、尺虚耎，左关、尺弦数。自是坎阳不足以生脾土，肾水不足以滋肝木，水不足而相火上炎，故时觉口干。坎阳不足，脾土愈亏，故当脐作胀，胀则中宫之食不能运化而成痰，甚至清阳不升，浊阴不降，以致胸膈窒塞不爽而黏痰常吐也。", "15495": "证脉合参，予于滋肾养肝中寓补火生土法以治本。", "15496": "病由寒热咳嗽而起，医用清肺治咳之品，每增芦根、丝瓜络辈。延绵月余，寒热渐退，而咳呛日盛，浓痰愈多，肌肉日削，始告治于余。诊脉右虚软，左脉虚弦，面白无神，食饮不贪，盗汗淋漓，更兼气逆痰稠且腥，固防痰血之虞，亦恐肺痿之成。正值夏令初交，火烁金伤，危险极矣。姑拟肺胃并治，以冀转机。", "15497": "服此气逆稍缓，脉仍如昨。", "15498": "据述素有头眩，又兼三疟之后，医者专治头眩，不思扶脾，而常服肝肾滋阴之药，更兼素喜浓茶，迩来脐下不时作疼，食饮渐减。于嘉庆辛未冬十月，始问治于余。诊其脉，右关、尺虚软无力，知其脾阴弱而肾阳不足也，此所以脐下作疼无已也。及早图之，恐成中满。", "15499": "服此两帖，目中流泪，流泪者风自火出也，故觉目珠松爽，而白珠之红究未退也。诊脉右寸浮数，左关弦数。白珠属于肺，目窍开于肝，肝肺火未清也。", "15500": "合参色脉，阴亏痰结，内服养阴、化痰、软坚之剂，外用艾灸。连灸十日，疬上俱结厚盖，再灸之盖已浮起。次日浮盖脱落，中间皮肉色白并不破损。年余之疬半月而消，非精于灸法者焉能速奏全功。", "15501": "素体阴亏，近感温邪，忽寒忽热，不饥食少。医人误认阴虚内热，重投滋阴腻补之剂，病势日增，延绵二十余日，热终不解，于嘉庆壬申五月朔日特求治于余。诊脉象虚数，温邪内陷，乍寒乍热，两颧甚红，舌苔边白中黄。深怕邪烁真阴，劫夺胃津，势属重险。姑念客途，聊尽婆心。治宜育阴祛热，以冀转机，议复脉汤法。", "15502": "间日疟疾，入发已停。停后胸腹满闷，饮食不贪，口吐稠痰，几无宁刻，大便十日未解，脉象虚滑。满拟他医寒凉过抑，以致此极。及历阅前方，热药居其大半，想因西人素畏寒凉，故作逢迎之态耳。噫！何不辨脉审症，而草菅人命耶。", "15503": "痢久而得虚弦之脉，肠胃伤矣，而肺、脾、肾、肝亦无不累及。盖胃与大肠同属阳明，大肠滞而久虚之胃气未必运行。肺与大肠相为表里，大肠滑而久虚之肺气何能统摄。且肾乃胃之关，肾气久虚而关门不固。脾为胃之妻，脾气久虚而妻道有亏。再者肝木逢春，理应生气充沛，乃左关之脉不弦，而反弦于右关以克脾土。肝气上冲而清阳扰乱，肝气下泄而浊阴留连。病已九月有余，医竟百治不效。岂无补气者，而重则助邪。亦有理气者，而急则伤正。旦晚蒙蒙何，自有氤氲化醇之日，惜乎未有以化气之说告之者。而气有阴阳之分，化有变通之妙，得其法者可与言医。", "15504": "按其腹，外膨内坚。手足心热，便溏溲赤。诊其脉右关虚大，左关浮弦。色脉合参，脾虚积蓄，湿郁虫生，虫蛊之征也。察色、辨脉、按腹，腹中之虫不少矣。欲愈斯疾，预为扶土疏木，佐以调之、运之、和之而引动之，亦须禁生冷肥甘及杂杂难化之物。调治半月，至月之初三、四、五之日，正值治虫之的候。再以人参辅正，佐以驱虫之法。服后果然虫下，三剂而积除虫尽，诸证咸安矣。通计服煎剂二十六帖而痊可，继以丸剂调理收功。", "15505": "色脉合参，补脾和肝，佐以祛积引虫，最为稳当。", "15506": "又，初四日复诊方案：昨以辅正驱虫法，虫下九条，形色若鳖。证脉详谛，尚有未尽者，仍宜固本养胃，少佐祛虫之法，尤为上策。", "15507": "如法服药，腹中不攻不痛。至二更时泻出如前之虫二十五条，挟稀粪积滞而下。至五更初，仍将前一半药汤与四味药末调服。服后至辰时，又泻出如前之虫六条。连日疲倦欲睡，自虫出之后觉精神稍健。自昨至今，共出肉鳖虫四十条，皆从大便夹稀粪积滞而下。腹中有如此之虫累月穷年，无怪乎颈细腹胀、食减体羸、脐突筋青、时痛时止、好啖水果生冷肥甘油腻。脾愈伤，胃愈弱，以致积愈滞，虫愈增。庸工无识，不敢治疗，延绵至今，求治于余。余察脉辨色，明知积虫满腹，所不即驱者，深悉脾土久亏，骤然一攻，儿命何存。必得调元辅正，中佐以酸、辛、甘、苦而引导之。待其坤元日健，然后以人参辈益胃养正，佐以消积去虫之剂。服后约三时之久而虫下九条，更方再剂而又下三倍零四，非但神识不疲而反觉精神稍健。服予煎剂半月，虽得验于此刻，倘前无数日之良剂，则又难以效速于今日，医岂易易哉。", "15508": "脾胃久亏，得之纵啖生冷，肥甘不禁，以致积蓄虫生。头大颈细，腹膨筋青，肚痛脐突，面色痿黄，骤然呕出三虫。虫何状，色红形扁，有嘴无足，异形怪象亦人所罕见者。余虽经验有年，然亦有可治而不能治者，有不能治而可治者。其说有二，一者有腹如铁石，胀大如鼓，面浮足肿，种种恶象不能治也。然喜其食能稍进，六脉虽洪大，冲阳脉尚平，知其胃气犹存一线生机，尚可救活，所谓不能治而可治者此也。二者娇养过爱，证已成而尚纵啖无忌，予以药治，彼以食乱。竟是诱之、劝之而详述之，反生怨尤。虽有婆心，其如功亏一篑，何所谓可治而不能治者此也。如三令郎之疾，则介乎二者之间。五疳虫积，原非轻证，况积非食积，虫非蛔虫。色脉合参，虚实相兼。将谓驱虫以存正，而僻壤岂可勤兵。抑或辅正以驱虫，而朽索终难驭马。谛思良久，莫如补之、调之、和之、运之，间佐以引动之。不数剂而脉渐有神，面之挟青亦渐转而微黄。黄者，中央戊己之土色也，亦渐有生机之征也。虽精神尚疲，喜其脐突渐平，腹筋渐退，知是积将松、虫将动，又值治虫之期。于是以人参、苓、术辈，少佐化积祛虫之法。三日来循序而下，通计四十余虫，不为不伙也。况年将十有三岁，日食几何，气血几何，能容此虫而日蚀精华乎。不久变易，命何如之。设非辅佐之法，何能一驱而去之。然而，初无数日之工夫预备潜藏，虽有参、苓辅督，亦难一驱而出。犹如用兵伐寇，须预为藏伏，然后得「一战以取胜之」之意耳。今也积消虫除，脉象渐平，惟右关脉虚大无力，左关微弦，肝脾之正气未复，加意调治，继之以丸，三易其稿，不无小补云尔。至于食淡茹蔬，莫贪生冷肥甘，保身之家，料知慎重，亦毋烦余之过为叮咛者。", "15509": "案定方成，适有客过予而诘之曰：「子之案则明矣，何用药之意不遵古方，而私心自用，所谓学古者何在！」曰：「因脉定证，因证制方，无取乎学古不化必执古方以治今病。试问轩岐又宗谁氏之方？可知今日之古方即昔日之新方也，安见今日之新方非后日之古方乎。」曰：「子之理则明也，辞则达也，志则高也，未免言大而夸矣。」曰：「否，碌碌庸庸，草菅人命，吾忍乎哉。」客唯唯，不复辩。", "15510": "风寒湿合而成痹，气血凝滞，右腿疼痛，大筋急缩，足不任地，屈而不伸，其病在筋，迄今月余。疡科妄作外症治，几乎误事。现在膝盖大而腿弯小，渐成鹤膝。况在新婚之后，更非所宜。脉形细涩，法当养血，佐以温疏，再为之计。", "15511": "大腹疼痛，右脉紧滑。感寒夹食，温疏运食为宜。", "15512": "服后寒热更轻，口不甚渴，大便次早解结粪成条。从此胸闷渐宽，脉之弦滑者亦渐平矣。", "15513": "头胀、身热、欲呕，舌苔腻黄，时值七月，脉象浮小。风暑夹食，治宜清疏。", "15514": "腹痛旧恙，正值秋令，感寒停食而发，此气口脉之所以紧滑也。速宜疏通，防转寒热。", "15515": "脉形沉数，暑湿热三气内阻，秋凉外袭，头疼，腹痛兼呕，泄泻稀水，胸闷不饥，小溲短少。病关上下，实由邪闭中宫，霍乱之征也。当和其中，俾邪解湿降，以免变端。", "15516": "卒然昏默，口角流涎，语言蹇涩，目呆鼾睡，体倦肢冷，遣人邀予救之。其脉浮小而软，左关带弦，右关兼滑。口㖞于右，病属于左，所谓正气反急而邪气反缓也。正值春令，假外风而引动内风，风火煽而痰升，此类中之征也。权拟调卫和荣、顺气化痰一法。冀其神识稍清，再为之计。（正月二十四日案）", "15517": "服后神识渐安，痰涎稍减，左手足亦渐活动，溲便如常，少可进粥，语言仍有似清非清之象，身中畏寒，脉形如昨。原方去青皮、僵蚕，加生黄耆、防风。再剂，服之畏寒之势渐止。", "15518": "案云：喘咳有年，不时举发，发则气逆痰壅不能卧，必得气平痰缓始能渐卧。即此知其喘咳之发，实由痰之不易出也。而痰之所以不易出者，则又关乎气与火耳。盖「气有余便是火」，火即无形之痰，痰即有形之火也。于此三者而分虚实缓急之治，是为尽善。而分之之法，又在乎脉之虚实而定之。此脉之右寸软小不疏，关脉滑数，左尺濡小，而按之皆无力者是其验也。当宜治本，而少佐治标之法，庶乎近理。", "15519": "上、下齿痛不止，兼之头胀，脉象浮缓小数。风火相搏，用蔓荆子、甘菊、薄荷、元参、细生地辈。服三剂头胀平，惟齿痛尚有二三，用后方再两帖而痊。", "15520": "间一月后，忽又胸背疼痛，咽嗌不爽。气闭痰凝，脉络不利。当用瓜蒌仁、丝瓜络、半夏曲、陈皮、枳壳、杏仁、桔梗、牛蒡子等，三剂而愈。", "15521": "忽然畏寒发热，略兼腰疼，周身不疏，无汗，舌胎白腻。贪凉恶热，不无冒风受凉，脉象浮小。法宜疏解，俾邪达表为妥。现在足冷，恐高年人难以胜任。", "15522": "次日复诊：据述依法行之，少顷渐自汗出，遍体松爽。傍晚热退身凉。是方之妙，妙在苏叶、防风、秦艽、薄荷之功，取其疏表解肌，合薄荷而凉散之，佐群药以疏通之。服后歠粥饮以助之，仿桂枝汤之服法。少顷渐渐汗出透表，其病若失。设宗时下庸工以为温邪忌汗之说，则未有不误人于反掌间者。如果温邪，其人必壮热口渴，热自内达外，其脉多在肌肉之分而不甚浮，且右手反甚于左手者，诚由怫热在内故也。是以仲景曰：「太阳病发热而渴，不恶寒者为温病也。」此证不渴而恶寒发热，舌苔白腻者，非温病也明矣。", "15523": "患春温症，由乍寒乍热而起，头重胸闷，舌白恶心，溲少腹疼，骨节痛，口干不喜冷饮，脉象浮弦。病经四日，温邪内蕴，疏解为宜。方以豆豉、苏梗、蔻仁、橘皮、枳壳、赤苓、半夏辈。服后乍寒之势不觉，其余如前。", "15524": "春温身热，六日未解，昨夜汗出遍身，今仍有微热，胸闷不饥，舌腻溲少，大便六七日未解。素多劳苦思虑，于三月二十四始求予治。诊脉象浮小，头痛胸闷，身热未彻。温邪内蕴，拟轻疏退热法。", "15525": "素有吐血症，迩来咳喘气逆，痰块凝结，肌肉消瘦。脉右弱，左虚弦。正值春令，防其见血。", "15526": "服此四帖，咳呛、气逆、痰稠俱减。停药数日，又多步劳力，忽于三月初五日气逆呛血，色红无块，火升面热，约吐血一茶杯。右寸虚数，关脉见芤，左关弦数。速宜益气养阴，佐以引血归经之法，冀其渐止为最。", "15527": "服两帖仍未吐，惟痰中带红。是日少劳动，至酉后忽又吐血几次，共约杯许。戌时延诊，其脉右虚、左弦、尺濡。随诊足脉，趺阳、太谿两脉尚存。然血吐过多，究防陡然汗脱，亟亟固气以统血，益阴以降火，不致再吐为最。", "15528": "去春患腰痛颇重，服予煎帖全愈。今二月间，舟中受寒，睪丸胀疼，牵连两腰，脉象沉细。乃寒湿闭于下焦，宜以散寒却湿，防引动旧恙。", "15529": "先粪后血，此远血也。脉形两关虚耎，法宜益气养荣，俾血止、肛收为妥。况值仲冬，水冷金寒，尤非所宜。", "15530": "素患风癣，见于股足。近又肢体手、腹湿毒浸淫，瘙痒无宁。起于肝脾，而波及于肺肾。艮、坤属土，震、巽属木。震为足而巽为股，坤为腹而艮为手也，二经有疾则见于部位。其所以又关肺、肾者，以肺主皮毛，肾主骨髓也。土虚挟湿而金弱，金弱而水亏，水亏则木火动而筋脉不荣也，一以贯之。法宜益气养水，润燥除湿，兼之壮筋健力，大可益寿延年，岂仅为风癣湿毒已也。", "15531": "身热头胀，舌淡绛，胎腻，先凛凛而后热，脉象数而不浮。湿温内蕴，法从清解。", "15532": "痢起于六月下旬，先一日腹痛水泻，次日转为白痢，约昼夜十余行，今则纯下红痢，一痛即下，却无寒热外感，脉象沉滞。暑湿交阻，法宜疏通，服后方两帖而愈。", "15533": "忽于初五日寒热交作，胸膈满闷，骨节疼，头顶痛。据述于未病前一日，无梦精遗。两日来壮热不解，四肢遍身皆疼，甚至头痛不能举，足痛不能立，口不甚渴却喜饮凉，舌胎满布皆白。大便溏，日二三次。小溲短赤，出时觉痛，喉亦少痛。医因肢末清冷、便溏、咽痛，以为夹阴挟湿，用前胡、枳壳、赤芍、牛蒡、荆芥、苏子、大豆卷辈。服后反觉遍身不能动摇，因邀余治。诊其脉，寸、关小数不浮，左关、尺弦细。此时邪挟湿，伏于募原。虽滑泄于得病之先，不足深虑。所虑者，恐邪不外泄而内陷，致有劫津昏厥之虞。速宜疏解，使邪达表，是为上策，拟达原法损益之。", "15534": "是方疏解时邪，兼之除湿治痛，因加灵仙、木通，既能除经脉肢节之湿痹，而木通又治历节痛，且能利小便，此一举而两得之矣。", "15535": "是方服后惟臂痛渐缓，其余未减，似乎药之未见奇绩也。而后忽烦热无宁，其脉见浮，得汗而解，岂非斯药之功欤！", "15536": "又，复诊方：服前方惟臂痛渐缓，仍然壮热无汗，齿板干燥，痰多甚稠，筋脉抽掣疼痛，腿足尤甚，大便稀水，小溲赤少，胸中热闷，有时畏寒，盖被肢凉，忽又揭被烦热。究属邪伏半表半里，是以身体壮热，胸前烦闷，所饮汤水尽走大肠，而不能分利小肠，故大便溏泄，小溲短赤也。细绎脉形，今见脉浮，大有出汗之机。何以知之，缘忽烦于未汗之先，而脉见浮者必得汗而解也。", "15537": "患时热一句，大便溏薄，溲少，胸闷，口干，舌苔干糙，不饥不纳，服药罔效。于五月二十五日始乞治于余，诊脉形弦数。邪阻中宫，深虑陷阴劫津。法宜清解，俾热退泄止为妥。", "15538": "复诊：仍觉口干，胸中热。舌中央仍带腻黄苔，渐润，非昨之干糙可比，脉仍弦数。", "15539": "咳嗽由去夏六月感冒而起，缠绵十月。土医作阴虚治，皆未获效，特买舟就治于余。细审病情，咳嗽十有余月，昼轻夜重，内热喉痒，痰不易出。幸食饮如常，神识不倦。右寸、关脉来细耎兼滑，肺气有亏，勿因内热而恣投寒凉，以致转怯。宜先清补肺脾，使金旺而水生，土旺而气充，则咳嗽自平矣。", "15540": "忽身热头胀，骨节兼疼，脉小数不浮。时邪内伏，法宜疏解。", "15541": "年逾五旬，一妻三妾，酒色过度，阳事不甚举。就治于土医，皆以为阳不足，概以兴阳助火之剂。如桂、附、鹿茸、蛤蚧、楮实、破故纸、淫羊藿、巴戟天辈备尝之矣。间有知为阳不足而侑以养阴者，其阴药较所用之阳药不过十之三，何济其事。是以阳事虽举，据述交媾时并无精出，徒劳空阵。即此，知其身中之元阴、元阳皆大亏矣，而尚欲兴阳助火之剂以图战，何自轻命若斯哉。而医者亦不究水火阴阳之偏盛，惟附会其情而竟妄施兴阳之法，谁之咎欤？无怪乎遍体不疏，肢节酸疼，腰膝无力，口燥喉干，一身难以鸣状也。皆为妄投药饵所误，亦自取之也。于乙亥秋七月，买舟来郡，寓于虎丘我与山居，友人钱上舍荐治于余。诊其脉，右寸、关虚细，尺虚而小数。左寸虚小，关弦，尺软如绵。知其气虚而血弱，火少而水亏。盖坎离交济宜平而不宜偏，经云「阴平阳秘，精神乃治」。阴以阳为主，阳以阴为基也。老子云：「知其雄，守其雌。」「知其白，守其黑。」人能知雄之有雌，白之有黑，则阴阳水火之不可偏盛者明矣。不于此而求治，而妄投壮火兴阳之剂，吾何忍哉，因制丸剂以善其后。", "15542": "四月二十八日复诊：据述服前丸，遍体疏畅，阳事亦举而带坚。他如喉舌之干燥、腰腿之酸疼等状咸若失矣。细察脉象，右寸短涩，惟欠浮耳，关虚小滑，尺脉举之数而按之不足；左寸浮数，关脉虚弦，尺则濡耎；合而审之，究竟水少于火，而阴阳犹有未平也。今交夏令，必得使其平而不偏，则气血和而荣卫流通矣，岂仅为阳事之举而已耶。前丸将毕，治法可征，再继以丸剂调补，尤宜节欲为紧要关头。《黄庭经》曰：「急守精室勿妄泄，闭而实之可长活」，旨哉斯言！", "15543": "体小形瘦，六脉沉细乏力。痛起于左乳下，因痛而呕，呕则食物俱出，甚则酸水上逆。病起于七月间，客于上洋，医作肝胃气治，用「左金」合归、芍、厚朴、郁金辈疏气、平肝、温中，间有用参、附、川楝、吴茱萸等。服药月余，似效非效，因买舟来郡，友人程梅溪翁特荐治于余。", "15544": "细审病情，合之色脉，呕痛两月却非每日如是，或因食不如意而痛呕并至，或因劳役动怒而即痛且呕，日积月累。痛呕皆从左乳下起，正阳明胃络也，可以容受水谷，即痰饮之征也。医者概作肝胃气治，用香燥破气、辛凉之品以治标。岂知胃气弥伤，脾阳愈弱，即间佐参、附于泄肝药中，亦非法也。据述日来饮粥方安，得饭即有呕痛之势，每发约在午后者居多。所呕之物，或稠痰兼酸，或仍是所食之原物也，且有冷气自下冲上。足征脾土之不运，胃底之无火可知矣，此又虑其下膈反胃之成也。不思扶土温中，补火生土，佐以养肝疏木，而妄行耗散，鲜有不误事者。今先以调脾温中，少佐补火生土法，再为之计。", "15545": "乙亥九秋病感身热无汗，未经表解，早投寒凉，斑未透发，误进「白虎」，又进犀、羚、生地、石斛、芩、连辈，一派苦寒，以致壮热不解，昏沉呓语。更医用鸡子地黄汤加减，似觉手指牵动之势稍缓。又投参须、黄连、阿胶等，两剂不应。再以人参、芩、连、阿胶辈，服后人事昏迷，二便不禁，腿膝觉冷，款证毕集，邀予诊视。其脉两手细软无根，二目戴眼，面赤神迷，口开鼾睡。头汗如珠，分颗不散，此油汗也。", "15546": "真阳既已外亡，万难挽回。必欲求救，勉拟生脉散合四逆汤。煎好，临服入黄连一分泡须臾服，以尽人力耳。", "15547": "节庵方中，参、附、姜、草、麦、味，此生脉合四逆汤方也，命名回阳返本汤。内加腊茶、陈皮，取其芳香苦降通气，以作向导。如面戴阳者，下虚也，加葱白、黄连少许，取其（指葱白言）通阳，又取（指黄连言）热因寒用之义耳。余方后所加黄连一分泡服者，亦是意耳。", "15548": "延程疡医治，半月间不过如是。于嘉庆丙子四月望日，友人钱君荐治于余。诊其脉皆阴脉也，此先天禀质所成，非病脉也。其右手举之不足，按之似数。左关虚弦，尺脉濡小。知其气弱血亏，相火旺而坎水不足以济之。再加厚味不禁，嗜欲过度，水愈亏而火愈旺，此瘰疬之所由生也。不思探本穷源之治，而概以疬门套药为法，恐坚者不消，而溃者难以完口矣。就色脉而详审之，虚中挟毒。先以调气养血为主，使血活动而腐者自去，俾气流通而坚者自消；或间以补中解毒，益阳助阴，补阴济阳；或水火并治，皆王道法也。神明变化，存乎人耳。此为内治之法，而外治之法亦必精详熟玩，不用刀针，亦无拘执于板方图形。察脉辨色，活法在人，则治疬如拾芥耳。", "15549": "身热呕吐，无论汤水食药，到口即吐，稍带酸味。是证已起二三载，不时举发。发则必先头痛，痛则呕吐随至。每发必延余诊，脉形右滑、左弦。", "15550": "案云：呕痛常发，食入即吐，吐盛则酸水如涌。六脉细小，右关虚弦。脾胃久亏，木来乘土，曲直作酸，此呕痛之所由来耶。先议和法以治标，再为扶本之计。", "15551": "疟延日久，虽已停止，而脉右虚数，肢跗浮肿。脾弱胃强，恐转中满，亟宜益胃调脾，俾清升浊降，庶乎尽善。方用异功散加苡仁、建莲、芡实、川石斛、鸡内金。服两帖，脾胃颇调，足肿稍退，小便夜间少，大便之溏少减。", "15552": "身热起自去冬二十七日，稍能进粥。至正月二日，延张姓治，桑叶、牛蒡、苏、杏、甘、桔、川贝、橘红、枇杷叶辈以疏解肺气。连用此等药四帖，身热不减，反增胸闷，遍体酸疼，食饮毫不能进，到口即欲呕。因其喉舌黏腻干燥，惟少饮开水以润之，非口渴可比。苔色中间焦黄如钱大，舌边淡红而不干。夜来神识不爽，少有昏语。小溲短赤，大便时有稀水溜出，脉象沉小。此邪伏于冬，而发于春也。恐有陷阴之变，当用苏叶、防风、豆豉、制半夏、瓜蒌全、枳壳、陈皮、神曲、薄荷、秦艽辈。服后汗未出，口干喜饮，诸恙如前，小溲短热，面色带红，二目内眦多眵，最虑邪热内陷劫津。", "15553": "初九日：用生地、丹皮、葛根、黄芩、瓜蒌、二苓、车前、石斛等，服后反不如前之妥当，愈觉周身疼痛，并左臂痛剧，身热，胸闷，不食，腰背俱疼，大便仍泻出稀水，小溲短赤热痛，烦躁不宁。病起十四日，脉形沉小弦细。邪气留恋，深虑内陷。所幸者，热虽未解而尚知遍体疼痛，夜来虽有乱语而日间应答尚清，此际犹可图救。若待其神识昏昧，陷阴劫津，则用药棘手矣。今拟表里和解一法，以冀转机。", "15554": "服前方，未几汗出，头面、胸背俱到，却不淋漓。当时遍身疼痛顿减，即左臂、腰背亦不觉痛。胸脘痞闷十去其七，可进薄粥一二杯，大便稀水亦止，小溲稍长。脉象稍起而究嫌弦细，热势虽退，余邪未清，加意图维。", "15555": "患腰痛偏左，脉形右大，左耎，小溲混浊。法当壮水温阳。", "15556": "素有肠红廿有余年，近又泄泻，日数十次，脾肺脉虚。服予益气止泻法，出入于「补中益气」、「四、六君」，或间用「归芍六君」，佐赤石脂、禹余粮辈。服数余帖，泻有时止，偶又见肠红旧恙。仍以炙耆、党参、山药、莲肉、归、芍、炙草、陈皮、益智、炮姜、旱莲草、降香、罂粟壳辈，以之益气扶土，佐以止泻、止血、收涩之剂以图之。服后血止，泻又减，日二三次，非六月间日泻数十次可比。连日亦有无稀粪者，亦有稀粪中兼结粪者，此皆气虚不能统，土弱不能运之故，所以得油腻肥甘而即泻者是之谓尔。继以丸方调理收功。", "15557": "体倦食少，咳痰浓厚，脉右浮滑，法宜肺胃并治。", "15558": "疟发间日，脉来弦细，右关滑数。痰食交阻，少阳之邪未楚，风邪不避，无怪乎至期热重寒轻，节食避风，以免缠延。", "15559": "痢下色红，腹痛后重，昼夜数十次，寒热，舌苔白腻，脉象滞涩，积垢犹存。病起半月，表里俱病，法宜导滞温中。", "15560": "天明后忽然呕吐，汗多，头眩，眼闭羞明。细绎病情，昨进夜膳，多啖火腿肉，临睡毫无所苦，天明骤然暴病，呕出尽是痰涎，素喜贪凉。舌胎白腻，脉象细小，按之无力。暑湿内伏，感寒挟食而起。第年高汗多，头眩眼闭，未便表解。宜用和胃调中，俾呕停眩止，庶无变幻。", "15561": "晚诊：服前方呕吐渐停，冷汗止，身温，目开，眩晕大减。至申后又呕酸水几口，据述味甚酸。又大便稀粪一次，小溲有。舌仍白，脉仍细小而软。知其正虚感寒，暑湿中停，舍温中和胃一法，竟难许治。既药服建绩，原渣尚在，即于复渣内加河水一钟，煎好去渣，加左金丸三分研细冲服，服后呕酸顿除。", "15562": "咽喉疼痛，脉右浮小，左尺虚数，上过于关，此相火挟外邪而上炎。得斯脉者，必从泄精而致，且咽喉色红，非浮游之火挟邪者，不能有此形色。当问之，答曰昨曾有之，足征脉证相符。有诸内而形诸外，特恐人之不善于审察色脉耳。方用元参、川贝、牛蒡、桔梗、荆芥、前胡、甘草等，两贴而痊。", "15563": "痛起于腰，波及肝胃，发则腹痛块现，形如葫瓜。痛止块消，遍体不疏，脉左右弦细沉紧。此气滞而兼寒痰为患也，以故痛甚欲呕，口吐冷痰耳。不速治，恐痛剧见厥。病经匝月，慎勿轻视。", "15564": "时值孟冬，遍体酸疼，腹痛兼之，脉象沉滞。此风寒湿合而成痹之象。痹者，闭也。是以酸疼中又兼腹痛、便结也，证起月余。他医缘便结，屡进大黄推荡，便虽通而前证不减。何取乎通，且苦寒伐胃，食饮减而胃阳衰，病日加深，证颇棘手矣。法宜祛风寒、渗湿和胃、疏理经隧，庶可图之。", "15565": "又，复诊方：进前方，疼痛大减，食饮渐增，惟大便甚结，欲解不能，脉虚涩而小。此气弱血燥，肠胃不滋，宜养荣润燥为法。若性急而欲速，如前医用「大承气」以推荡，而大便甚结，解之不畅，次日反增恶心不食，周体酸疼，大腹胀痛愈增，皆缘性急妄攻，几乎误事。日来服余方，幸诸恙俱减，惟便结不通，仍宜养荣润燥，侑以通幽一法，最为稳当。", "15566": "又，复诊方：自服余方后，疼痛俱减六七，日饮粥五六盏，较前增半，是好消息。第右脉尚微细，左脉虚涩，犹恐变迁。", "15567": "体肥身长，素有脚气，举发无时。发则腿膝胀痛，呕吐痰涎，胸脘闭闷，牵连腰痛，必得痛至足指方渐减可，据述此常例也。现在痛胀尚在膝弯，不能下行，是以胸闷、呕吐未已，脉象细小沉滑。法当祛湿，兼之疏通，通则不痛。脚气，古称壅疾。最虑上冲，冲则虚阳上越而防脱，慎勿轻视。", "15568": "痢起两月，点滴色红，缠绵不已，左脉细微难寻。阴气大伤，脾阳不运，食少体瘦，口味不禁，以致于斯，难图奏功。用补中益气汤去黄耆、陈皮，加白芍、木香等。", "15569": "凡痢疾，脉不拘浮、沉、迟、数，但指下无神便属虚象。所谓无神者，短而松，按之虚软也。", "15570": "右手无脉，因其手坏于手腕交际之处，故无脉可凭。然何以知其脾阳之不运，观其面色痿黄，食少肌瘦，肛门时坠而不痛也，是其征也。", "15571": "复诊：用鲜石斛、茜草、苏子、人中白、茯苓、山药、甘草、叭哒杏等，煎好去渣，仍以血余冲服。服后咳稍平，痰血三四次，较前又少。第脉象细小无力，而尚东奔西走，日行数余里。肺气虚，加之劳力，冬寒不避，现在咳血未除，尤难胜任，何西人之不自量也。", "15572": "畏寒欲呕、胸脘作疼，舌白胎腻，溲赤，脉象浮紧。法宜解表和中，当用桂枝、秦艽、干姜、草蔻、防风、制半夏、香附、赤苓辈煎服，仍然畏寒，两腿觉冷稍松一二，其余未减。", "15573": "次日复诊：脉仍如昨，畏寒稍缓，而遍体拘束，两大腿又觉冷疼，虽近火炉亦不见暖，法宜温散。用：", "15574": "十一朝方（十九日）：遍体浆回，头面痂渐结矣。脉虚小数，气血亏而余火未尽，宜清补兼施。", "15575": "由感寒误治，几成劳倦，于嘉庆戊寅二月初一日始问治于余。余细审病情，据述恶寒、身热、无汗，起自正月十七日。他医作温疟治，以柴胡、桂枝二汤出入，寒热稍减，而咳嗽转增，稠痰盈碗，俱是风痰，上有浮泡。不饥纳少，缠延半月，口中作甜，舌绛有津。日来仍然背心作寒，咳痰甚多，如前有泡。前医又作体虚治，用六君子汤加减，服之更不合宜，特求余治。诊其脉，右寸浮紧，左脉浮弦。知其风寒射肺，究未透表。是以起病至今，并未见汗，遍体不疏，终非疟也。不亟治恐涉劳倦之门，况年逾七旬有一，速宜疏肺为第一著，俾邪得汗而解。拟麻杏石甘汤去石膏，加鲜石斛辈，缘病在肺胃两经耳。", "15576": "前症愈后，于十九日庙中公事备斋，多啖面筋杂食等物，觉胸中胀闷、脐下作痛。探其情，不食痛减，食则痛增。诊其脉，举之软小，按之沉滑。知其气滞食凝，又值病后脾土失运化之职，以故中脘胀而脐下痛也。急则治标，于是以鸡内金、广木香、半夏曲、焦谷芽、神曲、青陈皮、乌药、沉香、煨姜等十味煎服，两帖胀除痛止。再以「香砂六君子」，服四五剂调理收功。", "15577": "咳嗽，痰稠不易出，脉右虚弦。肺气亏而中气虚，速治为妥。", "15578": "素好饮酒，厚味不禁，历有年矣。忽于嘉庆戊寅春得彻夜不寐症，两耳常鸣。遍访医治，月余来毫无一效，因邀余诊。余始作中虚湿阻挟痰治，不应。又以归脾法兼以安神、镇肝之剂，服数帖亦不应。又更医，医以「温胆」、珍珠母等法，经半月亦不应手。于三月初一日仍复求治于余，余再谛审病情兼察色脉，左脉细数。知其阳有余，阴不足，相火上炎，以致两耳常鸣、目不瞑者两月矣，求一刻安卧竟不可得也。于是处以四物汤为君，配以镇肝舒气之法。最后以酒浸炒龙胆草为引导之使。服两剂而耳鸣之声渐低，可以稍睡片刻。于此加减出入，治经一月而收全功。", "15579": "病由暑湿内伏，邪热未楚。医投清脾饮温燥之剂，不但热未清而反增口渴喜饮。医又投「四苓」加沙参、黄芩、白芍辈以清利之。服后舌色纯红，舌尖芒刺无津，比前尤渴，日饮茶数十碗而不能解其渴，因就诊于余。右脉浮数，渴饮无度，知其热在气分，几成消症。于是以白虎汤加竹叶、麦冬治之，渴饮顿减，热亦渐彻。即于方中加鲜石斛服之，渴减七八，舌尖红刺渐退而润。再以生地、丹皮、花粉、麦冬、元参、知母、甘草、竹卷心辈，三剂而瘳。", "15580": "暑湿内蕴，由单寒而转疟，寒轻热盛，头重且胀，小溲浓赤，舌腻如粉，脉右大左弦细。延绵有日，速治为妥。", "15581": "单热不寒，瘅疟之象，脉数不洪，舌苔尚白，口虽干而不喜多饮。暑热内伏，早投黄连，以致遏邪，应用和解法。", "15582": "瘅疟十数发不止，脉大身热，有汗而渴。入夜则发，天明方退。先伤于暑，而后伤于风也。仿「白虎加桂」并小柴胡汤之意而化出妙方，一帖即愈，快甚！快甚！此我得意之笔，可与山西陈慈民之方合参，亦大同小异也（嘉庆元年八月二日）。", "15583": "脉象沉滑，得食则呕，病经四日，拟和胃运食法。", "15584": "素有喘症，举发无时，向延他医治，屡发屡平。迩来发之甚剧，于是月二十二午后，因登圊陡然汗出如雨，舌根强，不克多言，气急神呆。医以生脉饮，重加熟地八钱、牡蛎一两、熟附子六分。煎服后，渐自汗少气缓，而痰咳甚艰，自云要从脐下咳出（凡咳从脐下逆上，皆属肾气不固也），咳时必有汗出气急之状，小溲热而赤，其痰纯是白沫，日咳数盂。两月来头不著枕，喘不能卧，惟以被褥厚壅其背而倚卧之。据述每咳有浓厚之黄痰出，始能安卧。刻下五六日一发，神疲难支，精力日败，特求救于余。余诊其脉，右三部细软如绵，左脉寸小、关弦、尺濡。知其肾水素亏，相火易升，又值断弦纳妾之际，阴分更亏无疑。然喘而不能卧如平人者，此又关于肺气之虚。盖人卧则金气藏于肾宫，今肺气畏火刑金，则母不能隐于子胎，其为气虚者又可知。历阅前方皆以养阴为主，地黄亦用之无算，而喘症终屡发无休，深虑陡然一脱。既然望治情殷，必需亟固肺气，兼理脾胃，俾肺金得令，相火下降，脾土一健而胃中之水湿不停，则肺中之浊痰亦清。要之，调脾肺尤甚于养阴则可，专一于滋阴而不补脾肺则不可。况地黄辈群阴之药，惟能腻膈滞脾，更无所取。及今加意亟固，犹恐上脱，岂可慢用滋腻之品而日伐肺脾之生气耶。今拟益气定喘之法，以冀转机。", "15585": "复诊（初七日）：喘止咳平，食增睡安，大小便如常。惟痰味带咸，脉象软小乏力，尺脉濡细，法宜调坤土以助干金，壮坎水以滋震木。则子有受荫之乐，母无食气之虞。得其意者，可与论治。", "15586": "四月初十日复诊：用「归芍六君子」加制首乌、女贞、益智、蛤粉辈，间以「五味异功」、「四君」等，加一二养水滋木之法而收全功，亦再生之幸也。第六脉未知，肌体未丰，精神未足，元气未充，此际首重在节欲养气，为紧要关头。盖「气乃神之祖，精乃气之子。气者，精神之根蒂也。大矣哉！积气以成精，积精以全神。」于此而加意求之，再继之以丸，庶几无遗憾矣。丸方列下：", "15587": "素有脚气，举发无时，嘉庆戊寅六月告诊。年逾四旬，体肥身大，好啖厚味湿面。脉象沉细，腿膝胀痛，右甚于左。湿气内侵，下达为顺，最怕上升，拟疏通法。", "15588": "始于额痛，喉疼、寒热，舌苔白腻。当用羌、防、甘、桔、藁本、僵蚕、牛蒡、马勃、桑白皮、干浮萍草煎服。次日天明，微汗，头额痛缓，而面额、颈项俱发作红丹成块，大小不一，光亮而痛于外，内痛大减。仍先寒后热，喉痛未减，早轻午重，时有呓语。脉形浮弦，左大右小。再以荆芥、牛蒡、酒炒黄芩、连翘、葛根、蝉衣、生地、薄荷、甘、桔辈清疏之，使素蕴之风热丹毒出表为最。服后寒热俱轻，额痛十减六七，惟丹块愈觉高突，足征丹毒外达之象，故胸膈不闷、语言清楚。三日间头面、手臂肢体俱发丹毒，大如胡桃，小如蚕豆。此即时行丹毒、大头疙瘩瘟之类也，当以家制霞城散水调涂丹，顷之痛减，高突渐平，而寒热未罢，口干欲呕，小溲色赤，究竟邪毒未尽。即于前方去葛根、蝉衣、生地，加花粉、山栀、贝母、滑石辈，加雪梨肉二两同煎服，仍用霞城散水调涂，甚妙。服煎剂，夜稍寐，无乱语，头额之丹块亦十平其七八。惟两颧、耳后及唇下尚未大平，肢臂、下体之小块亦稍平，痛大减。仍于前方损益之，服后寒热、喉疼俱退尽，而犹觉口中不爽，自知难过而又不能言。其所以然之故，细审之，此口糜也，兼之鼻声如齆。《经》云：「心肺有病而呼吸为之不利也」，又曰：「膀胱移热于小肠。膈肠不便，上为口糜。」治以苦寒之剂，以辛温佐之，拟既济解毒汤法，以清余蕴之邪。", "15589": "素有喘症，今于十一月初二日因伤风而起。西人好啖面食荤，日来不禁。昨夜半，忽然喘发不能卧，胸脘闷，背板如缚，而喘声一刻不停，犹如抽风箱之声，特延余诊。其脉右寸浮紧，关脉小滑。知其风寒闭肺，痰凝气滞，阻塞清道，此喘之所由来也。速宜疏肺定喘，佐以豁痰顺气。势属险途，慎勿轻视。", "15590": "白浊半月，服通利之剂罔效。予以清降相火法，佐以疏泄。服四帖，白浊渐减，溺端不封。惟小便时及完后，少有针刺之象。脉寸、尺小数，此相火未静，宜养阴以济之，浊自止矣。", "15591": "身热数日，热非壮热。口干喜饮，却不多饮。舌苔中央腻滞淡黄，不饥纳少。问答尚清，起坐自如。兼之耳聋，脉左大于右。此暑伏湿闭之象也，拟清解以和之。方用「小柴胡」去参，加葛根、香薷、瓜蒌皮、赤苓、花粉辈，加藕煎服。热稍缓，小溲增。但舌根腐腻、胎黄，大便十有余日未解，有欲解未能之势。宿垢内蕴，以解表通里法。方用瓜蒌实、豆豉、槟榔、枳实、黄芩、油当归、大腹绒七味。煎好去渣，入元明粉二钱冲服。", "15592": "风邪上攻，脑后、鱼尾二处牵掣抽痛，寒热。舌苔淡黄、边白，脉象浮软小数。速宜舒解退热，恐高年人难以胜任。", "15593": "大小腹俱痛，痛则大便溏泄，早三二次，晚五六次，病起月余。脉左小，右大，尺浮。肾阳虚而脾土亏，兼之食积中宫。当以理脾、温肾为主，不得泛泛治痛。服后方三帖，腹痛大减，便泄顿止。", "15594": "小溲涓滴有年，举发无时，于道光二年正月初十日延诊。小溲急数欲解，出时涓滴不爽，刻刻欲出。出时溺窍不疼，疼刺在半出未完之际，如刀割刺痛难忍。出未几而顷之又欲出，及出仍如前般。日间数余次，口中觉干，夜来频出不爽。坐直则腿中筋急，溺管中即刺痛，必得曲腰坐之则少安。且溺时，阴茎底面筋急则溺窍越觉酸疼之极，若筋柔软则安。种种情事，病由昔年溺情过度所致。攸关厥阴肝木而兼乎阳明宗筋，波及膀胱、肺、肾者有之。况右脉之细软，左脉之弦急，尺数，非无自也。第年逾六旬，病根已久，性急心活，屡屡更医，纵有妙手亦难以建绩也（是证可与后之黄其祥之病合参）", "15595": "病由暑湿内蕴而起，未经疏解，药饵乱投，以致身热两月未退，耳聋体倦，不饥纳少，小溲短赤，大便溏泄，日解数次。医更多人，寒、热、温、凉备尝之矣，热终未退。舌苔灰色，边淡白，医又疑为虚热，以熟地、归、芍、鹿角胶、参、耆，加升、柴、术、草。其白术用至四钱，炙草用至二钱，以六一散为引。炙草二钱已嫌其过，而又加「六一」中之甘草，何其善用甘草若斯之甚也。更奇者，病已奄奄一息，其人仍将前方加附子一钱，并牡蛎、黑山栀辈温凉燥热并投，视人命如草菅。幸遇伊同乡子毂谷汪君，阻其所加附子之方不可再进，观其病势危笃，特求救于余。余至，诊其脉两关弦细不静，问其病则曰耳内常如蛙鼓蚊锣之响，察其色舌中灰色边淡，兼之溲赤、便溏。合证脉而详谛之，热未尽彻，棘手极矣，难以许治。姑念客途抱病，怜孤儿独子之形单，不得已，惟有和中一法，清暑却湿，俾上下交融，庶乎尽善，所谓击其中而首尾皆应也，或可图其幸耳。", "15596": "服此，头额之热今始退清，舌转之淡黄苔亦从兹而渐退，鼻洪止，大便一次始结，小溲色淡，诸恙俱平，惟脉象软小濡细，精神尚疲，耳内犹响。加意图之，自尔痊安。", "15597": "又，九月初一日复诊方：今可扶起诊脉，究未能多坐。", "15598": "连进五六剂，肝肾之阴渐复，耳鸣减半，食饮亦增，惟六脉尚虚小乏力。大病两三月，气血久亏，肌瘦神疲，节食戒怒，毋贪厚味，淡蔬最宜，俾食饮旺而精气充，加意调摄，庶无他虞。", "15599": "暑湿内侵，病已十八日，尚有余热未尽，有汗喜饮，小溲短赤，舌苔腻滞淡黄，知饥纳少，大便六七日未解，夜能寐。脉右小数，左弦细。此湿阻而兼暑气之未彻也，表之无益，即清之、凉之亦未见却病，莫如和中祛湿，俾暑湿由中以下达，庶几无变迁之虞。", "15600": "进一剂热退，再剂解结粪成堆，小便长、赤减，自觉安妥。停药两日，又有微热。早上饮粥少有汗出，热渐退，午后又渐微热，知饥能寐。二十日复诊脉如前而舌胎愈觉腻滞，小便又短而赤。前方去猪苓、泽泻、山栀、西瓜汁，加鲜石斛、姜半夏、鳖甲、地骨皮等。两剂，热又退清。", "15601": "素多劳苦，娶妻甚迟。于道光辛己五月初十日延诊：尿血数月，日渐小便涓滴，甚至疼刺难出，大便欲解不能，必得溲先出而大便始解，小便时刻渗出，大便愈难一解，迩来以绢围扎阴头使其渗入。有时小腹疼痛，茎中又有鲜血频滴。面带虚浮，食饮如常，睡卧尚安。脉象虚软，左关弦劲，尺脉濡细小数。缠绵日久，深虑头倾背曲，变证蜂起，岂是小恙而可藐视之乎。", "15602": "又，十二日复诊：侵晨出街，步行劳力，午前陡然尿血如箭，内有紫块。前后胀急，大便欲解不能，尿血仍频滴不止。少顷大便解出成条粪些少，溺管中解出血块一二，立觉松爽。病在二阴之间，迄今半载余矣，不无溺情所累，况血从精窍而出，非比血淋之茎痛由膀胱溺窍而出者可较也。当急以半通半涩之法，兼以治本，以照顾左关、尺之弦急小数之意耳。服后尿血减而胀急未除，更医用龟板、熟地、知、柏、麦冬辈，反增胸前胀闷，二便秘结难忍，气壅于上，面浮㿠白，不饥不纳，较前之进食如常者大不同矣，因于十四日复求治于余。诊其脉，右寸、关虚滞，左关、尺弦紧小数。二便不通，弩力并睁，不由自主。前阴血出涓滴、胀急，必得瘀块出、大便稍通，渐自宽松。二三日来无一刻之安宁，甚至小肋胀痛。证属险极，姑念告治情殷，亟以升降通幽法，或可望诸。", "15603": "据述先进丸，后服煎剂，少顷即睡。睡醒觉面浮稍退，口干舌糙亦少润。至夜半又少有小腹并紧之势，至天明解出粪如大指粗者三二条，小溲稍增，却无尿血。少顷饮粥杯许，忽然欲呕，呕出盈碗之水。顷之又呕，其味带酸，非痰非涎，中兼黄色，好似昨进更衣丸外之朱砂也。想连日下焦秘结不通者，上焦必壅而不能下达者有之。更兼前医用寒凉无温热之佐，不无阻滞中宫，假此米饮而痛呕，呕后反觉上部稍宽，况有余之升降、疏补、通幽之法，是以前后二阴稍通，故小腹不觉并紧胀急也，药服颇合。第右脉如昨，左关、尺弦紧小数未平。肾为胃关，胃土壅滞，故胸中胀而兼疼，而食不贪也。厥阴不舒，郁结前阴。肾关不利，幽门难通。深虑复闭，闭则必结，结则必厥。当以和法开其上壅，佐以疏通下焦，仍不外乎升降一法。冀其二便通利，庶几可图。", "15604": "又，复诊方：右脉虚耎，左关、尺弦细小数。固气养荣，兼理肝肾。俾二阴之气调匀，则气旺水充，肝木滋而相火不升。心不下荡，血自归经，而尿血可止矣。当加意图维，耐性静养斯可矣。", "15605": "六脉虚大，脾肾两亏，又兼肝气作楚。病延日久，正值春令，土为木乘。脾主四末，无怪乎手足掌心痛剧难忍，且肿也。二目水光外含，其为肾水之不足已露先声矣，盍早图之，深虑骤变。权拟一方，先治筋脉，兼之调脾和肝，待病势少衰，再为之计。", "15606": "复诊（十三日）：仍用前方加虎掌骨、木瓜辈。服后如前，每至申酉后，觉手足心之疼渐增，胸中气闷不爽，两胁作痛，引动肝气。当理气血，和其筋脉，再商。", "15607": "复诊：四肢无力，遍体不疏，幸手足心不痛，时觉筋惕。诊其脉，幸肺脉之数急已缓，惟左关弦劲未舒。知其木有侮土之象，故食不贪，而素有之痰饮黏腻者时而呕出。常多怒，怒则火升。脾土不运，肝木过旺，过旺者肝亦自伤。为之调脾温中，佐以舒肝，和其筋脉，通其经络。俾其渐减，再为之计。", "15608": "服三帖，更妥，行步可不用人扶，手足不痛，筋脉安舒。", "15609": "复诊：脉之虚软、弦劲俱渐平可，惟左尺濡耎、右尺浮虚乏力。阴气亏而命火不足，是以腰疼膝冷，虽丝绵固护而膝骨中究嫌其冷，攸关元阳、元阴之不足耳。议火土相生、水火并济之法，或不无小补云尔。", "15610": "去年七月间得淋症，溲出疼痛，溺窍封口，迄今未已。半月前曾身热、咳嗽、胸闷、痰稠，医治热稍减。据述，淋症自己讳疾忌医，乃尊细审方知，始告治于医。医以生地、丹皮、芩、连辈不应，继以鲜石斛、麦冬、竹叶、石膏、芩、连、知、柏一派苦寒，不第客热未除，即淋症亦未减。夜不安宁，不饥纳少。溲赤，出时疼，完时痛，茎中胀刺不爽，因延治于余。余至，前医已定一方，用温胆汤加味以作不寐治，杂乱无章，妄治误人。余诊其脉，右浮大，左弦细。春温未解，兼之湿热下注。淋症半载，疼刺胀痛，此脾湿而兼少阳甲胆之火郁未清，又兼风温上受，无怪热难彻而夜不安宁也。此皆前医滥用苦寒之误耳，一误而两病不瘳，再误而虚怯之虞难免。就余视之，退其热则神安而自寐，清其湿热、解其郁火则淋症之胀痛可平，何必妄治哉。", "15611": "复诊（二十八日）：病后气荣两虚，大便半月余未解，审其平时亦要三四日一解。色脉合参，益气养血，兼以舒运。俾其缓缓而解，庶乎渐安。", "15612": "复诊（二月初一日）：进前方两剂，计出结粪约七八寸。右脉虚滞，左脉细弦。宿垢未尽，第廿余日之大便秘结于淋浊身热之后者，必体虚肠燥而宿滞难尽。诸恙向安，仍宜益气、养血、润燥以滑之，斯为正治。", "15613": "腹痛块攻有时，甚则欲厥。色脉合参，食积挟虫。", "15614": "细绎病情，素不节欲，于二月十三日畏寒而起。未病前三日泄精两次，既病后又溏泻三四日。其始也，他医作春温症，用清解退热之剂不应，日渐加重，始显三阴见厥之势，体倦，微热无汗。医又用四逆散加干姜，服后肢冷稍温，少顷又冷，更医。医作风温化热见厥，以清疏法，加羚羊角等（未曾服）。主家见势危险，特求治于余。余诊得脉形右脉沉细、左脉虚微。知其阴阳两亏，寒邪陷入于三阴，而致四肢厥逆，邪难达表，以故神识模糊、语言错乱、舌根短缩、口不喜饮也，难以许治，姑念客途抱病，聊尽婆心以应之（二月二十一日诊）。", "15615": "据述点灯前进药，少顷睡著，约更余方醒。醒后小便一次，清白且长。未几又睡，睡醒饮粥一盏，又小便一次，渐觉四肢温暖，身热微汗，不喜饮，时欲起坐，语言似清非清。舌缩渐伸，中心淡黄。病势稍减，脉亦渐起，足征里邪少有出表之机。", "15616": "复诊（二月二十二日）：证脉合参，仍以辅正兼以和解，俾邪由里达表，取微汗而解。方用「小柴胡」，去黄芩之苦寒，加生地以退荣分之热，得姜汁以和卫。桂枝汤中去芍药之酸收，而加葛根以解肌。且柴胡得葛根使邪由少阳而出阳明，葛根得桂枝使邪由阳明而出太阳也。无非为阴阳两虚之体辅正以和解，祛邪以达表，斯为标本两固之法，加减于柴、桂二汤之间，妙义深矣（方附后。）", "15617": "复诊（二月二十三日）：证脉合参，寒邪陷入三阴而致四肢厥逆。进前后两方，脉形渐出，有鼓指之势，自是邪有出表之象。今始口干喜饮，溲转淡黄，大便黏腻而臭也。再以生津退热、调和荣卫，取小汗以彻热，庶几无遗蕴矣。", "15618": "复诊（二月二十四日）：汗出热缓，陷阴之变庶可免矣。第脉尚细微，左关、尺更觉弦细，自是邪退而余波未尽也。议养阴、生津、和胃之剂。", "15619": "复诊（三月初四日）：大病之后，理应大补，而数日之宿垢留恋中宫，昨始解之。证脉合参，尚有余垢未尽，权以疏而运之、和而达之之法，再为议补自无遗憾矣。", "15620": "复诊（三月初五日）：昨以舒运一法，果然余垢已解，且结如弹丸，亦从权之良剂也。伤寒之后，胃阴烁而津液不敷，脾阳虚而肌肉瘦削。不但此也，土虚不能生金，肺金失平木之职，此脉之所以兼弦也。土虚不能制水，肾水有泛痰之虞，此痰之所以带咸也。预为扶土，厚培坤元。中宫健运，妙在资生。方用六君子汤加归身、柏子仁，引以鸡内金。服后次日又大便结粪成条，先黑后黄，此宿垢尽而正粪出也。知饥食增，胃土渐旺。", "15621": "丸方（四月初五日）：证脉合参，大病之后，气血两亏，理宜补气养血。然气阳而血阴，又当壮坎阳而滋离阴，使荣卫冲和，则气血流通，而精髓可填。第填精益髓之法又非草木之所能尽其长也，须借气血有情之品而少佐导引之法，始能胜其任矣。若不此之求，而泛作气血不足之治，何济其事。法宜补火生土、壮水滋木，俾元气日充，精神自健。商瞿有后，尚可望诸。", "15622": "右脉沉紧，腹中频痛，寒与食并，小便短赤，宜以温中运食法。", "15623": "脉形沉滞，尻骨酸疼。肾阳虚而肝木不舒。服后方四帖，酸疼顿平。", "15624": "脉形右关濡软，脾湿中阻，口吐涎沫，自觉从两腮涌出。半月前不过偶吐，三日间涎涌无时，不酸不苦，自有一种气味难言。一日约吐四五盏，频频而出。", "15625": "去冬劳力损膜，以致吐血，今夏复发。诊得脉象过硬，知其素性刚勇，遇事不耐，性急火升，此血之所由来也。从此耐性，庶可无虞。今血止之后，忽尔得食即呕吐者，胃病也。细审之，吐血时前医过用寒凉之剂，血虽止而胃土为寒凉所遏，以故食入即吐。不容少待，余以治呕药中而佐温胃之法，故一剂而呕吐立止，效如桴鼓之相应也，快哉！", "15626": "胸闷块攻，脐之上下俱痛。西人素好食面，不忌生冷，寒与湿食交阻，脉息沉滞，宜于温舒。", "15627": "两足浮肿，朝退夕肿，脉右软滑。不速治，防成中满。", "15628": "病原：气出于中焦而行于遍体，贯注百脉，往来不息。近缘怔忡时发，心荣不足，胃土失养，肺气因而不充，肝木乘之。以故三日间，每至四鼓气由脐而上达于胸，并紧不舒，且胀且疼，必得手捺重按而后渐散。种种情事，合之脉象之浮而不沉，似与病象不符。惟两关细小兼弦，又未尝不关乎肝胃，而其源实由于心荣之不足，中气之有亏也。《经》云：「缓治其本，急治其标」。宜乎先治其标，再为探本穷源之法。", "15629": "小溲频频欲出，出而不爽，溺后窍底酸疼刺痛。病起有年，得之少不节欲，举发无时，遍治罔效，以致精力不充，食饮渐减，于辛巳六月二十四始邀予诊治。脉息右寸关浮数，左关、尺虚数。湿火下注，兼之相火不静，当从肺、肝、肾三经落想。", "15630": "风暑相搏，单热不寒，发为瘅疟。每于午后热至，酉后热渐退。但退时无汗，必待睡著汗出如淋，醒后始知席湿不堪。每夜如斯，已六七日矣，服药罔效，特求治于予。予诊得脉息弦细小数，午后热时心热如焚，口渴喜饮，热退无汗，眼一闭而汗出，顷之睡著盗汗淋漓。阳盛阴弱，荣卫两伤，水中火发，与温疟何异，岂可作泛泛疟治。", "15631": "右脉虚软，左脉弦细。素有肝胃气，迩来腹胀无时，由下而上。肢倦食减，或嗳气，或转失气，则腹中渐爽。其气自胸腹而上升，必得头项举直，则气能嗳出而胸顿宽，或转失气下亦然。大便不结不溏，每解不畅。此气虚气滞而脾阳不温也，当用理中汤加益智仁、广木香、茯苓、木瓜、续断等，加沉香汁二分冲。", "15632": "症由六月二十五多啖湿面而起，次日觉胸闷不饥，身倦微热，呕恶腹疼。医不审起病之因，误作暑湿治，以致吐泻交作，投利湿药不应，又以清暑益气法，甚至腹块内攻。复更医，又以疏通法数帖，病益增，又有用芩、连、槟、枳等清攻并投。病延月余，奄奄一息，始求治于余。其人肌瘦肉削，不饥不纳，日呕清水。口干喜饮热汤，到口即吐。不呕时又吐白沫，兼之腹疼水泻，昼夜约二十余次，纯是薄水。小溲少，出时甚热。脉右细软，左小弦。脾不运，胃不和，以致上呕下泻而中宫阻滞不舒也，先理中宫为亟亟也。", "15633": "又，八月初二日方：今晨进粥一盏并无呕意，诸恙安妥，惟脉息仍细耎无力、体倦神疲为虑耳。", "15634": "用「四君子」加木香、砂仁、青皮、鸡内金八味，加姜、枣煎以和营卫，因呵欠多也。服后又大便一次，不结不溏，惟神疲、肌瘦肉削、脉息软弱为虑耳。", "15635": "感寒挟食，先寒后热，小溲多，此寒感于下焦也，脉息浮紧。年近八旬，轻舒为宜。", "15636": "素有外痔，好酒喜茶，忽然肛脱如鸡卵大，胀坠痛如鸡啄，起坐不能，睡卧不安，大便欲解，疼痛难忍，此痔也。脉形右关、尺并数，知其湿火注于大肠，非清不能散，非通不能除其胀坠疼痛，亟治之，免其痈漏之虞。", "15637": "又，十月初五日方：肛脱渐收，外痔将平，肠中偶而见红，坐立不克自如，未免心烦食减。诊其脉，右脉耎短，关中见数，按之不足。左关弦而按之软，自是弦非真弦，数非真数。得其意者于此中消息之，庶乎尽善。", "15638": "脾土不运，食滞中宫。肝木横冲，腹胀且痛。七旬老人，脉软大无力。不饮不纳，中焦气馁，亟宜温中以和之，深虑中满之虞。", "15639": "二十八日方：用姜、附、淡茱萸同前，加乌药、当归、柏子仁、生首乌八钱，鸡内金等。煎服一帖，痛胀俱减，大便十日未解，仍宜温中运食。缘年高脉弱，未便擅投攻伐。", "15640": "门人书山谓余曰：「胞叔抱病有日，胀痛异常，得先生温中法，一剂知，二剂已，三剂便通而霍然矣，何其神也若斯？」曰：「非神也。证与脉合，药与病对，是以效如桴鼓之相应也。」书山钦服。", "15641": "汤水下咽即呕，胸胃作疼。脉象沉小，左弦细。寒气内蕴，食阻于中，宜以温之和之。方用苏梗、香附、豆豉、陈皮、木香、半曲、赤苓、神曲、藿梗、生姜渣等，河水煎服。", "15642": "胸脘闭闷，腹中小疼。舌胎白腻，脉象细小。小便赤，大便四五日未解。此湿阻上、中二焦，治宜温舒。", "15643": "得溺血证，日三十余次。中夹血条，约长四五寸，去后茎管中始松。少顷或尿血，或纯鲜红血，忽又出血条如前，或弩力睁出，尿管中渐松。顷之，觉管中空冷如冰，应心而疼。腰腿酸软，食饮无味，大便欲出不能。缘前阴之血去过多，后阴之肠燥不润耳。脉右细小乏力，左手反关，弦细小数。深虑神疲难支，议益气养水、去瘀生新之法，以冀转机。", "15644": "又，七月初二方：进前方，溺血减半，脉仍细软无力。试思人身血有几何，而能当此之去血过多也，阴固亏而阳亦伤。血之瘀条尚有，茎中仍觉冷疼。人第知血之热，而不知虚冷而见瘀也，庸工焉能明此，近代惟薛立斋深得其旨。照方服之，毋得妄为增减。", "15645": "泄泻两月未止且痛，食纳脘中不爽，惟饮粥无妨，脉形沉细无力。日夕数次，脾土大惫，岂可渺视之乎。", "15646": "前曾溺血，调治全愈。仲秋因二便不畅，他医以通利二便之法，前阴稍通，后阴仍秘。复又往药铺告其所由，竟用凉膈散，内大黄用五钱。服后大便仍未通，而反增大小腹俱痛剧难忍，睪丸胀大，食毫不进，面青有浮油光起，兼之畏寒身热，有顷刻垂危之势，伊叔渭川张灯扣门求救。绎其病情，实为寒凉攻伐所误。诊得脉象细软无力，左脉反关弦紧。中下二焦为寒凉所遏，表里不和。以故外则畏寒身热，内则卵痛偏左。势属险途，治在温舒，冀其转机。八月廿三日案、方附后：", "15647": "素有血症，因咳而吐者居多。忽于立冬前三日，呕血几口渐止。至初八日夜，骤然大吐，据述约有四五大菜碗。甚至血涌不及吐，以致从鼻内噀出。当饮童便，血势少平。是日夜深，在城中过宿，初九买舟送归已夜。至初十日邀余往诊：身壮热，头少疼，咳呛气逆，痰稠。舌胖苔白，不饥纳少，面带浮光，痰中挟血，脉见芤数，按之无力。气血大亏，深恐汗脱，亟宜益气养荣法以固之。", "15648": "服此热退，自早至未时进粥两盏。惟脉象仍空虚无力为虑耳，痰血渐止。", "15649": "服后，咳呛气逆十减其七，痰亦甚少。惟脉右软大无力，食饮未健，入夜心神不静，交阳分渐安。仍将前方略为加减，再服四剂。昨大便一次，不结不溏，舌苔白退，口苦亦减，仍不知饥。", "15650": "复诊（十月二十三日）：气血渐和，食饮渐增，咳呛大减。惟两寸脉究嫌细耎难寻，夜寐不安，左尺虚濡。法宜荣卫并治，佐以养神安魂为善耳。", "15651": "吐血之后，调治颇宜，食饮如常，精神渐健。遵俗见「药补不如食补」，图口腹之欲，而竟忘气血之未充，精神之未旺耶，停药月余。渐自咳呛气逆，稠痰盈盂。从此食减，舌色呆白，胃气攸关。脉右急，关滑，皆无力；左关弦，两尺浮濡。乃病后气血大亏，又值严冬水冷金寒之际，子母并虚已属棘手，若再见血尤非所宜。", "15652": "下焦感寒停食，手足逆冷，腰疼足蜷，尺脉沉紧，其为受寒于房劳之后也无疑。细绎之，曰：诚然。当用穞豆皮、独活、香附、木香、杜仲、神曲、楂肉、木瓜、葱须等煎服。服后腰疼足蜷顿平，惟头眩、不饥、胸闷，余邪、宿食未清。次日用蔓荆子、苏梗、穞豆皮、枳壳、制半夏、神曲、麦芽、木香，加葱白二枚煎服，全愈。", "15653": "余诊其脉，右关虚软，左关弦细。此脾不能统，肝不能藏。当从肝脾治，是为探本穷源之法。", "15654": "畏寒腹痛，痛在脐之上下。其痛据述如拔肠之痛，忽止忽痛，痛甚口角流涎。唇红舌腻，脉象弦细。病起数日，外有寒而内有虫也。先宜散寒止痛为妥，方用桂枝、苏梗、淡茱萸、干姜、木香、乌药、小茴香、楂肉、陈皮、青葱等。两剂畏寒止，脐腹痛如前。", "15655": "细绎病情，素好饮酒，迩年尤喜火酒，每日数餐。以致肌体羸瘦，咳嗽喉疼，便泄直溜，得食即泻，昼夜数余次。业已半载，诸治罔效，告治于余。诊得脉形虚濡，面色痿黄，知其湿热伤脾而土弱，虚火烁肺而金哀，此便泄、咳呛等证之所由来也。宜戒其酒而治以药则可，治以药而加之酒则不可，请问醉翁之意何在。", "15656": "得暑热症，忽然畏寒，顷之身热、头胀，当用疏解。午后又寒复热，至晚呕吐。次日热退，午前畏寒肢冷一二时，周身仍热，手足亦温，饮汤不呕。舌苔白腻，脉象浮弦。乃邪伏募原，究未达表，故肤燥则遍身不松，汗出身润则周体松爽矣。治宜解表和中，俾邪外彻为最。用竹茹、瓜蒌皮、小生地、丹皮、青蒿子、地骨皮、葱汁炒防风、姜汁炒半夏、薄荷、赤苓等。服后身热稍减，日晡略增，仍少恶心，舌苔白腻，胸脘气短，不能提起。此邪郁阳明，宜以退热、解肌、和胃之法，冀其得汗而解。", "15657": "脐之上下作痛，痛甚块结如石伏于脘底，左右俱有，按之稍缓。寒与气食交阻，病起二旬，脉来沉紧小滑，显有明征，拟温中法。用厚朴、香附、干姜、草蔻、木香、陈皮、赤苓、甘草、莱菔子辈。煎服一帖，痛稍缓，块亦渐小，大便溏粪一次。", "15658": "证脉合参，素好浓茶，痰吐盈盂，精薄囊冷，攸关脾肾。脾土虚而湿痰上溢，肾阳亏而精气不充，无怪乎痰多、精清而囊冷也。此右关之所以虚弦，弦主痰饮，尺脉迟耎，左关、尺弦细虚濡，显有明征。法宜厚培坤元，大壮坎宫，不凉不热，不润不燥。其中水火宜平而不宜偏，取水旺而木滋，相火自静；火足而土温，湿痰自除。正合脾肾同治之法，岂仅愈疾已也。从兹气血融和，精气贯注，百脉流通。纯阳子云：「精养灵根，气养神。」于此中消息之，他日充闾之庆，可较商瞿之有后矣。", "15659": "又，复诊丸方（乙酉九月二十二日）：连进前丸，诸恙悉减，得子甚艰。证脉合参，水火并济，保肾固精即种子之良法也。治法戬谷，颇有至理存焉。", "15660": "怔忡有年，心荡无时。迩来胸膺气筑，不食少缓，食稍增则肚脐收缩吊紧，背曲，两乳下有似筋抽难状之势。头眩足浮，脉象细小。进后方六帖，心荡大减，食后脐腹之收缩顿平，背曲、头眩俱缓。方附下：", "15661": "胎疟间发，寒轻热重，午后始至，已发五六次。舌苔白腻如粉，小溲色赤，大便稀粪，水果湿面不禁，腹中有块，邪食内蕴，脉象弦硬。正值九秋，速退疟邪，以免变幻，拟清脾饮出入之。", "15662": "头疼畏寒发热，骨节疼。舌苔腻，脉来浮缓。风邪外袭，治宜于散。", "15663": "胸脘腹胀闷且痛难忍，呕吐酸水，舌苔白腻，小溲赤疼。脉右沉紧，左小弦。拟温中定痛止呕之法，方用厚朴、姜制半夏、木香、豆蔻、菔子、赤苓、橘红、麦仁、车前子等。煎好去滓，用左金丸五分，煎药汤送下。服后呕酸、腹痛顿止，惟胸脘胀闷未平。", "15664": "素体阴亏，骤然血吐两三盏，申后又吐如前之多，今早复吐两盏。两日间约吐七八盏，特求救于余。诊得脉形虚芤，左弦数无力。深虑汗脱，亟亟扶正，犹恐鞭长莫及。", "15665": "气食相凝，脐腹胀痛，得汤即呕，小溲短赤，脉象沉滞，宜以温舒。", "15666": "疟虽太阴，而脉象弦细，右关浮缓而细。细者湿也，浮而缓者风也。岂非风湿之感于肌肤，而侵于太阴湿土者乎。然脉左之细弦，是又少阳而兼乎太阴者有之。仲景云「疟脉自弦」，由少阳而兼他经者亦有之。谓他经而全不涉少阳者，则不成其为疟矣。旨哉斯言！于是用小柴胡汤加草果、藿香、车前、滑石、赤苓、青皮辈。早上煎服，午后疟至，寒热俱轻，转为单日。发时惟腕臂仍痛，较前减半，而痛时仍不能耐。即于原方加减，疟日减轻，来亦渐早。三四日来，每疟至腕臂必痛。", "15667": "复诊（六月）：疟邪渐减，寒热俱轻。第脉息软大无力，左关弦细。连发有日，汗出过多，正气不足，阴气又亏。发时臂痛伤神，汗乃心液，神更伤矣。不饥不食，胃土又伤，颇属棘手。议养阴、祛邪以冀疟停。", "15668": "复诊：昨疟复虽停，而心中烦躁扰乱，食少妄语，目瞑见鬼无算，脉象虚豁似空。知其阴气亏而阳不能入于阴也，究非阳虚见鬼而致汗脱者可比也。病者于床中向余跪哭求救，当以和阳益阴敛神法以救之。", "15669": "初次来苏，水土不服，纵啖油腻荤腥，泄泻日数余次，迄今四日，忽然转筋于两腿足跗。此缘泻久伤脾，脾虚肝乘而致筋转也。脉象虚弦，右脉沉细，舌苔白腻。中宫又为寒阻，以故进汤即呕，幸不腹痛。病势匪浅，宜以和胃、止泻、舒筋为最。", "15670": "身热一旬未解，始投清疏不应，复以生地、羚羊、翘、栀、青、陈、牛蒡、地骨皮辈，服后仍热，再进，便溏、胸闷。药投数剂，以致耳聋、脐下疼、溺时窍痛、溲赤，病日加深，特延余诊。其脉左弦细，右小，舌白如粉。胸前气闷，溲短赤色，邪陷耳聋，此伏暑症也。当用香薷饮加赤苓、木瓜、蔻仁、蒌皮等煎服，身热渐减，气闷稍宽，白苔渐化，小溲仍赤。", "15671": "又，复诊：伏邪晚发，头额潮润则热势必清。设不潮润则身中干热不爽，足征伏邪内陷可知。证脉合参，冲龄阴亏邪陷，议益阴彻热法，冀其转机。", "15672": "据述病情：前月远出，天气炎蒸，舟中过啖西瓜，寒凉阻胃。素体丰肥，湿痰中虚，途中冒暑贪凉。八月上旬回苏后，渐有畏寒，舌苔腻白，自服姜、附各一钱半，又苏叶三钱，佐桂枝、厚朴等。温热之药过重，巳后舌苔白退而复白。至十六日始问治于余，诊得脉象软小而濡，左脉沉细而弦，知其暑伏湿阻。连日口渴，喜饮温汤，汗出如雨，胸前闷，身微热，小便短赤，舌苔糙白，得汤即呕，时吐稠痰，夜有昏语，眼闭即梦。证脉合参，暑湿感于盛夏，发于深秋，治法未当，疾反增重。亟宜祛痰以止呕，利湿以清暑，为紧要关头。", "15673": "先寒凛，后发热，热无巳时，似汗非汗，口干喜饮，却不渴，舌苔腻白，小溲短赤，头痛欲呕。未病前曾食冷饭，胸闷不饥，晨轻午后烦，两足小腿觉冷，脉象濡细。此湿温也，服清暑等剂不应，特延余诊治，当用：", "15674": "二十五日侵晨诊脉，右浮左弦，知其风暑搏而成疟，当用蔓荆子、防风、半夏曲、柴胡、黄芩、草蔻仁、神曲、青皮，加六一散煎服。服后至申正，仍先头痛畏寒，约半时即热，热至更余，汗出而热渐退。", "15675": "胸脘痛胀，痼疾五载，春减夏愈，秋发冬甚。今正举发，胸脘刺痛，痛剧则胀，渐横至脐腹，早缓午甚，夜间更增，天晓渐减，得食亦稍减，脘中时响，脉右沉细而紧，此皆沉寒痼冷，脾阳之不运所致也。是以交春而减者，寒得温气而痛缓矣；逢夏而愈者，寒得热气而痛解矣；至秋而发者，寒得凉气而痛作矣；遇冬而甚者，寒得冷气而痛益增矣。议附子理中汤加味治之，庶可立起积岁沉疴，永免终身大累，非曰仙丹，理可信耳。", "15676": "病由寒热而起，他医未经疏解早投寒凉，以致身热不退，病势增重，迄今半月，始求治于余。此风温症也，寒热头胀，胸闷口渴，不喜冷饮。舌苔中心绛，边白无津。耳聋，脉小，溲赤。防邪内陷，亟亟祛邪，冀其热退为稳。", "15677": "咳嗽喉痒，夜甚于昼，天明渐已，痰出稠黏。脉右软，左弦细。宜清补肺胃之阴，俾其火降而自平。", "15678": "上下齿龈作痛偏左，左脉细小兼数。心肝虚火上炎，法宜养阴以降火。", "15679": "于去秋九月发三疟，三发而止。已后渐自腹膨有块，小腹疼痛，由阴囊而上冲小腹。土医误作虫症治，反增。食少体瘦，肌皮骨立，夜间发热、足肿，迄今九月矣。于端阳日，特求余治。诊其脉，右关浮软，左弦细。症属内疝，任脉为病，病根深沉，不此之求，药饵妄投，恐有虚损不测之虞。先以和肝法，冀其病缓，再为良图。", "15680": "是病由受凉停食而起，以故身热胸闷，按之而痛。未经解肌透表，早投「陷胸」，继又妄用「承气」。服后大便先软后溏，不但热不除而反增重。业已六日，口渴喜饮，舌苔糙刺无津，阴液涸矣。且愈热愈渴，日饮茶数十瓯而究未能解其一渴。脉息左弦劲，右滑数。此温邪留恋于气分也，缘误治而至此极。议「仲圣」竹叶石膏汤法出入之。", "15681": "胸膺痛痹症，由劳力而得，迄今三载，举发无时。右脉弱，左脉细涩，血凝气滞也。当以养荣祛瘀，佐以疏之和之，庶乎渐安。", "15682": "胸腹俱痛，舌苔腻白、根黄，小便短赤。进厚朴温中法，顷之即吐，痛仍如前，左脉细小难寻，右关中按小数。再以温凉并进以和之，方用香附、木香、陈皮、枳壳、槟榔、乌药、良姜、生山栀、甘草、楂肉等。服之脘腹痛始减，而舌苔仍腻白如粉，口不觉干，知其湿与寒并。服后方一帖，上下痛止。", "15683": "素体肥胖，好酒贪荤，迩来肌瘦其半，业已六载。腹有时膨，足有时肿，肢节亦有时作痛。屡进燥湿之剂，终未克奏绩，因求治于余。诊得脉形软细，先宜调中却湿，佐以疏运，再为之计。", "15684": "复诊：进前方，脘腹渐松，便结已解，而食仍未贪，惟日饮粥二三盏。证脉合参，法当养胃生津，以图胃气旺而食饮渐贪。", "15685": "复诊：舌苔滞白，口淡溲赤，不喜饮，脉象耎小，究属脾土不运，命火不足以生之。论口淡似胃热，而按脉审症当理脾胃，兼补肾中之阳为上策。", "15686": "中虚气壅，壅则痛，痛则不通，脉象沉滞，当和其中，调其气，气舒而痛缓，食自贪矣。", "15687": "夜间内热，波及四肢。口唇燥裂，牙龈出血，脉来弦细小数。脾阴虚而荣血不足，缠延周年。冲龄阴弱，尤防骨蒸劳热，亟宜调摄，勿得忽视。", "15688": "滞下红白，昼夜二十余度，迄今三月。体瘦食减，所下污秽异常，肛门甚热，小溲短赤，脉形濡数。乡人长夏田野劳苦，湿热酿成久痢，脾虚而兼湿热为患者，究宜调脾祛积，兼清湿热，庶乎尽善。", "15689": "左鼻出血，十有二日。昼轻夜重，每至二鼓频频而滴，约有盈盂之多，阴气弥伤。他医妄投苦寒，如犀、羚、知、芩，加以凉膈散辈，屡投不应，衄血反增，而致举头即眩，朝轻暮盛。脉形细数，右脉虚芤，究关阴火潜然，非实火可知。再衄防晕，亟议启玄子益阴济阳以救之。", "15690": "三疟年余，发于子、午、卯、酉日。先寒后热，热甚呓语绵绵，口渴喜饮，至半夜后始得汗而解。寒少热多，肌瘦食减，便结溲赤，脉形软滑，左关弦细。正虚而疟邪留恋也，治在肝脾，当用六君子汤，加首乌、鳖甲、黄芩、草果、车前子辈，姜、枣为引。", "15691": "脘痛已久，午后尤甚，且有泛泛欲呕之势。素好饮茶，右脉细小，左关、尺濡小。先理中焦，再为之计。", "15692": "素有吐血症，迩来因喘兼咳。月余来，卧不著枕，痰不易出，口燥舌干，大便溏薄，食饮日减，脉象虚软，按之细数。议益气、定喘、化痰，冀其渐缓，庶乎尽善。", "15693": "阴虚体质，内热咳嗽上气，缠绵年余。肌瘦肉削，脉息濡小，右软。脾胃日损，便泄不止，食饮维艰。虚损之门，已露先机矣。更兼鼻衄常发，阳络又伤，胃气难复。日投滋腻之品，坤元愈耗，无怪肠滑不固。亟宜扶脾保肺，为正本究源之法。（九月二十日诊）", "15694": "复诊：服前方颇合，因方中无熟地滋阴，以为不能速效，以故复延前医用熟地、枸杞、归身、附子、霞天曲、茯苓、党参、白术、五味子、白石耎辈三四帖，喘咳反增，而且日间尤甚于夜，痰咳不易，食减，不能卧。始知余药对症，复求诊治。脉右虚耎，左弦硬。较前病增，自取之也。其人意，中老年续弦，自揣肾虚极矣，非熟地不能补。殊不知脾肺久虚，重用熟地辈滋泥之药，徒然腻膈滞脾，又何取乎早投。况便溏日久，更非所宜。今虽深悉，其如喘咳已增重矣，议益气定喘法。", "15695": "食后脐下作胀，脘中闭闷，嗳之不畅，酸水时呕，黏痰并出。病经匝月，大便秘结，二三日一解，脉象两关弦细。土制于木，当以二陈汤合温舒之法不应，又以「旋覆代赭」法出入亦不应。", "15696": "案云：脉右软左濡，上则吐红，下则遗白。病经有年，屡发无时。攸关坤土之不足，坎水之有亏。而脾恶湿，肾恶燥，二者最难调摄。善治者，于先后缓急轻重间而求之，斯为善矣。", "15697": "病后中气不足，动辄冷汗，舌苔肥白，尾骶骨（即尻骨）痛。脉形细耎，不能鼓指，左三部濡小不足。阴气亏而卫阳不护，当扶阳益阴，冀其汗止，庶免虚波之虞。", "15698": "进药后，头与手臂冷汗未出，稍动即有小汗，食仍未贪，胸中气闷，额心胀疼。有上轻下重之势，又有头眩欲仆之象，前方益气、护阳、敛汗颇为合宜，而食饮不贪，舌苔腻白，胸闷、额疼亦须兼治。进谷乃昌，亦是紧要关头。据述向年痰发，姜、附服过四十余帖而奏绩，自信虚寒之体。就余论之，药以治病对证便是良方。阴虚体质而兼阳弱者，又非概以温热之药为法也。昨方之用附子理中法者，亦救急从权之治也，暂用取效，分量多寡不同，随证脉而增减斯可矣。", "15699": "病由七月间暑湿内侵，寒热胸闷。医以清疏却湿，热虽退，而胸闷、痰多、溲赤、便秘未减。更医，医以清凉佐大黄、芒硝等服之，大便仍未解。又以消导佐更衣丸，亦不解。又有用麻仁丸等法，不应。医更数手，非但便秘十余日不通，反增口糜、咽干，舌胎淡白湿润，上腭、两颔干燥无津。刻吐白痰，黏腻如胶，状若瓜子大，时吐无宁刻。小溲短赤，大便十余日未解，食饮甚少。细审之，因口苦黏腻，痰胶满嘴，牙龈白腐，上腭干涸，以故粥难下咽，惟用炒米泡汤咽下以充饥，非不欲食者可比。于八月十四延治，诊其脉左沉细如丝，右脉稍大于左，亦在沉小、弦细之间。知其中焦阻膈，上则口糜，下则便秘。概以通幽攻伐，非惟大便不通，徒伤中气，无怪乎口糜腐而干涸喜饮也。当以厚朴、蒌仁、二苓、麦、斛、阿胶、南枣、元参辈服之，肢体少有微汗，身中渐有活动之机。", "15700": "体丰身健，劳神会计，两妾，子幼，每夜饮酒半斤之酣。忽于初十二鼓时，身蜷语謇，畏寒身热，痰声如锯，连泻数次，举家仓皇。于十一日侵晨，乃甥陆琴轩六兄特邀余诊治。余至，问答无知，神识模糊，敲齿视舌。舌苔白腻，中心淡黄。诊脉时，手臂牵掣，忽然转里，有劲厥之象。脉形软小，左弦细。类中之萌，深恐昏厥，权拟温中、却湿、除痰之法，俟其转机再商。", "15701": "去秋衄血，几乎昏晕而脱，得余大剂壮水而痊。记前三百五十一页内，可检阅之。今正期年复衄：先觉胸闷不爽，三四日而鼻衄随至。右脉浮软，左弦大。相火上升，治宜养阴降火，兼之逐瘀。", "15702": "食入至戌初，腹中之气必上逆，嗳出腐气或朝食原味之气。中宫奔响，腹胀，气从下行即便泄有声，迄今匝月，脉息两关沉细。寒与湿食交阻，久防成「膈」，法宜温中、却湿、运食为妥。", "15703": "寒湿上侵，颈肩酸疼，转侧维艰，波及两臂。脉象浮紧，右滑。防有痛痹之虞，拟舒风活血法。", "15704": "虚羸有年，频发无时，气逆痰鸣，舌白无苔。胃阳虚而食饮不贪，荣阴亏而夜寐少安。肌瘦肉削，脉息软弱，深虑虚波之险。", "15705": "左寸虚数，卜心神之失守；左尺虚浮，知肾水之有亏。是以火升则心惕足冷，火降则惕止足暖。时而口苦作酸，忽而口甜带臭。痰有时黑，亦有时黄。种种见证，虽关心肾，亦未尝不关乎脾也。盖心为姹女，肾属婴儿，其中无黄婆为之媒合，则心肾难交，水火难济也。况右关脾脉虚数而滑，膏粱厚味阻滞中州，痰火内结，常常梦泄，非无以也。吾于斯而得其治法，识者鉴之，匪朝伊夕功也。", "15706": "疝症有年，兼之滑精，肝肾有亏。体肥痰多，食后腹膨，又关坤土之不运。此右脉之所以软，左关、尺之所以虚弦也。暂服汤药，继以丸剂调补，自无遗憾矣。", "15707": "丸方：右三部浮小软滑，左脉虚弦尺濡，病关足三阴。方中用异功散益气调脾，俾脾土得令，食后不致膨胀气腐，而湿痰可祛也；加以壮水滋木、温肾固精之法，则疝可平而精滑可已也；诚善治肝、脾、肾之良法也。", "15708": "中满症由痒疥湿气而起，疡科重投清火解毒之剂，致湿气内蕴。面色痿黄，渐白面目虚浮，大腹膨胀，两足浮肿，便溏溲少，食减肌瘦，脉象虚濡。证名肿满，中虚挟湿，治之非易。法宜温中除湿，加意调摄，斯为善矣。", "15709": "天气通于喉，地气通于咽。喉中燥痒咳呛，痰不易出，如有物阻。必得渐次痰出，咳始平而喉始爽。初不介意，刻则日发数次。固由于气之上壅，亦关火郁于脑门。气为火伴，清肃之令不降，斯疾之所由来也。何以知之，验之于右脉细小微数是其征耶。", "15710": "胎疟初发，发在申末，寒凛手战，至戌初而渐热。热时口渴喜饮，饮则汗出，而热不止，至二鼓而渐退，迄今五六发。服前医方，疟不减。二日前，因便秘，治疟方中佐麻仁丸始解结粪，夜半腹痛，继解溏粪。是以疟至，寒热更盛，因请治于余。诊其脉左弦细，小腹有块且疼，此疟邪内伏；体瘦食减，正不胜邪，岂可妄攻。细阅前方，尚用桂枝解肌，又加以茅术、石膏，连进二剂，疟势愈剧。就此时汁，究宜和阴阳，冀其寒热速减为最。", "15711": "案云：绕脐作楚，脉形弦紧，寒为气阻。旧疾有年，今始复发，业已十日，温舒为宜。（滞下积存奇效方载后）", "15712": "阴亏体质，潮热匝月，头眩眼花，腰疼腿痛，食少肌瘦，舌绛喉疼，兼之咳呛。脉形右虚软，左弦劲，尺濡小。金虚水亏，木旺火升，而心神不静也。心何以不静，相火内动也。固宜养水，亦须保心，而心尤难言之矣。禅机云：赤肉团上有一无位真人，诚哉是言！惟无位乃称真人，设有位则仍为赤肉团矣。于斯而守真，于斯而求治。冀其心肾交而水火济，速退潮热，庶乎谷毂。", "15713": "因气、食、湿交阻，以致胸闷、骨节疼，舌苔白。私进大黄及青麟丸辈，致令腹痛甚剧，坐立难忍。脉象沉细，法宜温舒。", "15714": "病由暑热挟湿而起，医妄投川连、厚朴，继又早进犀、羚、翘、连。病增更医，又进竹叶石膏汤佐芩、连辈，而热仍未解。因大便秘，用麻仁丸等始解，先结后溏，身热稍缓，究未尽彻。两耳失聪，口干喜饮西瓜汁，据述饮时似乎喉舌觉爽，不饮顷之唇舌仍干，喉中黏痰时吐，惟饮米汤，粥不喜进，小便短赤，独赖西瓜汁以润喉舌之干。医更数手，病势日增，于庚寅六月初九始问治于余。诊其脉右浮软无力，左关弦细尺濡。知其暑热为寒凉遏抑，阳明胃津已涸，是以口干喜饮弗克少待，兼多咳呛痰黏，不喜纳谷。种种见证，一身津液尽为寒凉所伤，无怪乎喉舌干而热终未能退彻也。病延匝月之久，当以养胃生津之法，冀其津回而食自贪，不治热而热自退矣。弗此之求，变端莫测，药岂轻投哉。", "15715": "骤然泄泻，昼夜无度，脉息沉细。受寒挟湿，法从温舒。", "15716": "病得之六月二十七，身热而起。次日尚啖荤面，再日又食肉点。至二十九日又犯房劳，少不节欲，阴气亏而暑湿之邪留恋于内，未克达表，以故身热忽轻忽重亦无定期也。加之食阻中宫，口干喜饮，水湿之邪未得从膀胱气化而出，同走阳明大肠而便泄也。有时足冷，固由阴气之不充，亦关湿阻于足胫，二者兼有之也。明知证非轻候，况脉象濡细，显有明征，而其所以犹可治者，邪达阳明。阳明为多气多血之乡，于斯而求治，或可免其变幻之虞矣。（道光十年七月初六诊）", "15717": "是证初起，至夜烦躁，渐有昏语。房中女伴传言内戚，议论纷纷。次早延诸庸工诊视，以为夹阴伤寒，非温燥之剂不能救，非茅术、厚朴、姜、桂之药不能治，立方深嘱早进，迟恐不及，使竹坡狐疑，几误大事。然竹坡素信于余，特问余：「能治不？」应之曰：「能治！第须依余用药，庶可无虞。」盖此证重在暑湿夹食，兼之房劳，不过阴气有亏。然年壮邪盛，究宜祛邪外达，不使内陷为最。纵是热盛，不过较平常之热增重耳，以阴虚阳往乘之也。如果症为夹阴所感，必有脉证可凭。不得概作阴症之治以误人，使冤鬼夜嚎，诚堪痛惜。竹坡深信余言，悉屏他医，将性命寄于指下，余一力担承，前案可鉴。仍以前法出入，清舒运滞，俾邪解、食消、热退、津生，不数日而全活。设当时轻信旁议，竟遭若辈之手而以温燥为法，其性命不知何有矣。此皆竹坡兄为善之报欤，与余何功焉。", "15718": "服此四帖便泄止，虽不结亦不溏。咳嗽渐减，食饮稍增，惟脉象仍软濡，舌苔绛剥。究关胃津未复，脾气未旺。咸由咳嗽内热，他医日投养阴滋腻之误也。自九月二十日问治于余，诊脉察色，首重脾胃为紧要关头。盖土为万物之母，胃为水谷之海，坤土一健则肺金得令，而便泄、咳嗽皆可从斯而向安矣，此药之所以效如桴鼓之应也。", "15719": "二十四日：用四君子汤，内人参用六分，加沙参、玄武板、降香、漂淡人中白等，煎服四帖而血止。两足常冷如冰，天寒愈甚，再用四君子汤加女贞子、枸杞子、左牡蛎、鹿角霜等。服之如前之妥，再以归脾汤加减。至岁暮严寒，脉象虚软，间以益气养荣之法调理收功。从兹体丰神健，亦再生之福也。", "15720": "年三旬，好酒贪色，寓所潮湿。忽然小便淋閟，涓滴难忍，内如刀割，出时腰弯背曲，脉形弦数。湿火内郁，用后方两帖而霍然矣。木通（一钱）赤苓（三钱）猪苓（一钱半）泽泻（一钱半）青皮（一钱）黑山栀（一钱半）萹蓄（一钱半）瞿麦（一钱半）甘草梢（六分）车前子（一钱半，炒）十味，顺流水煎。", "15721": "素好酒喜面，纵啖厚味，脾土久亏。迩来脘腹胀痛，得食愈增。舌苔厚浊腻滞，大便三日不通。小溲短赤，出时热臭。脉息濡细，佥因气壅而兼湿食交阻也。急则治标，先以舒通法。（道光庚寅九月初八日诊）", "15722": "病愈后，至仲冬胸脘作胀，小腹兼疼，知饥不敢多进，因其胀也。于近处就医，治之不问，因又问治于余。诊其脉，右关细硬，左脉弦劲。气壅湿阻，上胀下疼，病在脾而波及于肝。宜以温中运湿，舒补兼施，庶几无妨。", "15723": "素属中虚阴亏之体，每早喜啖湿面，至夜又好饮酒，酒后食饮可进可无，向来如斯。忽于数日前觉胸中摇荡，初不介意，渐自火升，头目不爽，舌尖刺痛，喉音不清。少顷心荡渐平则诸恙如失，忽而又至则前恙复作。三日前更增左乳下跳动异常，以手按之内如沸羹。尤奇者，脉亦三五不调，自治罔效。于庚寅十二月初二日特求治于余，细绎病情，胸中摇荡，此怔忡病也。火升头眩，兼之左乳下跳动异常，穴名虚里，胃之大络也。脉象忽迟忽数，忽止忽来，静则神安，烦则火升。土虚木摇，水亏火起，病关心、脾、肾、肝，岂是轻候，虑其跌仆神迷。", "15724": "《经》云：「胃之大络名曰虚里。贯膈、络肺，出于左乳下……其动引衣宗气泄也。」动之应手者，无常耳，乃知无常之脉指左乳下之动脉为言。有常，则宗气不虚。无常，则宗气大虚，而上焦之气始恹恹不足也。", "15725": "服此一帖，诸恙若失，虽饥亦非昨之饥不待食可比。惟右脉弦硬，左脉未静，究宜加意图维。", "15726": "病痊之后于辛卯二月复发，心一荡则火升面红，有脱衣去帽之势。舌中心裂纹，两边红。齿舌润口苦，却不喜饮。惟有胸闷气阻，火欲升而不能，欲降而不得，必须胸脘气松，自知火降神安。证脉合参，前治可鉴，其所以屡发者，固关中虚阴亏，亦由心思过度、郁闷不舒而又难以告人者，是以越想越郁以故病发，则心荡火升、面红舌裂、胸闷不爽等情随至，必欲胸脘一爽则气顺火降矣。今心事郁结，因感而触之者，无怪乎易复也，最难调治。所谓实病易治，七情难疗，信不诬也。就症脉而详谛之，升降不灵也。用仲景黄连汤先治其标，再为治本。", "15727": "滞下昼夜三十余度，至圊积减，寒热腹膨，面目虚浮，有表里两感之势。第素有喘咳痰饮之症，房帏不节之躯，更兼体弱肌瘦，食饮不贪。脉象浮之小，中按沉滞，再按无力，险在此耳。姑拟煨葛根、苏梗、楂肉、桔梗、枳壳、神曲、木香、五谷虫、赤茯苓等。", "15728": "忽畏寒身热，渐自脐腹绞痛，小便赤，大便秘。舌苔满白，脉象沉紧。寒与气食交阻，法宜温散。方用苏叶、秦艽、草蔻、木香、夏、陈、楂、麦芽、乌药、枳壳、干姜等煎服，寒热减，脐腹胀痛如前。", "15729": "胸脘脐腹作痛，迄今数日。食少溲赤，舌腻苔白。体素瘦，痛剧防厥。脉形细耎，证颇棘手。当用厚朴、蔻仁、半夏、木香、赤苓、车前、陈皮、薤白、淡茱萸辈，加生姜煎。服后脐腹痛稍减，胸脘仍痛如前。因大便不解，西人最喜通便，且擅用丹、丸，如青麟丸、九龙丹及木香槟榔等丸。弗论年之强壮虚弱，概以通为法，诚愚人之见也。况脉软痛甚，食少体弱，倘经攻伐，便泄、汗出而脱，咎将谁归，予深阻之。惟有温理中宫，免其痛厥为最耳。", "15730": "痛症数年，举发无时。每痛于脐之左右，甚则呕吐食物。脉象沉滞，肝胃为病，法宜温舒。", "15731": "肠红见于粪后，此远血也。脉息濡软，关小弦，坤土虚而震木不滋也。兼之素好浓茶，又不无湿阻中宫，法宜肝脾并治。", "15732": "滞下逼迫，水多于粪，昼夜十有余次，腹痛里急，至圊一响，稀粪随出，而仍有后重之势，脉象弦细。暑湿挟积，阻滞作痛。宜于舒通，通则不痛。", "15733": "于辛卯六月二十六日因质弱肌瘦，丸剂调理。脉右软小，左濡细。冲年质弱，肌瘦食少，咳嗽将痊。宜以益气以养阴则坎水自充，所谓水出高源是也。加以调脾运食则坤土日旺，干金愈足，自尔食健肌丰矣。", "15734": "因数日前过啖厚味，食填太阴，适感温邪，身热头胀，胸闷恶心，骨节痛。舌腻苔白满布，脉形浮滑。当服疏解消食之剂，病虽减而身热、胸闷俱未一减。至初五日用清火退热之剂，至酉后神识半清半昧，是晚一夜乱语，忽起忽坐，并出床行走。初六日用小生地、羚羊角、麦冬、茯神、远志、龙齿、橘红、黑山栀辈服之，热仍不解，口干喜饮，痰黏如胶，吐出不易，神识似清非清，行坐不定，与昨无异。初七日诊得脉息滑数，知其日前过啖厚味，兼挟湿温充斥。身热一候，朝衰夜盛，多语妄言，奔走无宁，胸脘不爽。此皆向日之厚味宿食阻塞中宫，酿成胶痰黏韧难吐，与温邪化热，是以痰火凝结不散，乱语奔走，而热终不能退也。亟宜清火化痰，以冀转机。", "15735": "又于次年戊子岁冬十月初三日，因五六日前又过啖厚味，外受风寒，而致身热胸闷。初以散寒消食之药二三剂，身热稍减，而神识似清非清，一夜乱语不止，朝轻暮重，起坐不安。口吐黏腻如胶之痰，白韧异常。证与前次颇同，脉形右滑数，左弦细。", "15736": "于三日前头疼如蒙，身热无汗，自服疏散药不应，于是求诊。体倦好眠，口淡多痰，胸闷不饥，脉形右大左小。暑风挟湿，热不发扬，邪内蕴也，未可忽视，祛暑却湿为宜。", "15737": "月余后至九月初五延诊，面目手足渐有虚浮之势，咳痰又增，仍从脐左而上至胁即有漉漉之声，上虚里，至缺盆，而入咽嗌，气稍顺则易于咯出，一有阻滞则窒塞于咽嗌之间，内如刀刺，呼吸不灵，厌厌一息，必得耐久，候脘腹中之气渐从痰中透出，然后始能出口，即出亦要逐渐咳出。倘或顺利，得中气送出一块凝结厚痰，则适意极矣。一日之难过如此，而夜亦复如斯，以故求生不能，欲死不得，于床中向余哭告求救，情惨极矣。不得已而蹙额频思，索想良久，痰之生也，皆有脾胃之不运，肾气之有亏也。古人云：「脾为生痰之原，胃为贮痰之器」，本此意而求治，庶乎尽善，惟脉息软弱乏力为虑耳。（九月初五日方列下）", "15738": "此刻惟面目、小腿之虚浮渐增而波及小腹，手足并阴囊亦有肿胀之象，此又虚鼓将成之候也。旧恙垂危，进药渐有生机，今又继以鼓症，虚羸之体恐难胜任。脉息微弱，色脉同参，脾土不温，坎阳不足，岂不虑其一脱。不得已而以温中养胃之法，调其坤土。临卧用金匮肾气丸四钱，陈皮泡汤送下，此至当不易之法也。", "15739": "至二十二日余甥至，据云服一帖，尊人嫌其丸中有桂、附辛热之药，不肯再进。因气逆食减，面目、手足、脐腹肿胀愈增。更难过者，阴囊冷重而胀大，阴头肿大光亮如鸡卵之大。小溲甚少，不能平卧，危在顷刻，复延求救。呜呼！病极至此而尚自作主张，无怪其三五日来病日加深。夫肾气丸者，以能收摄肾气，使水不泛滥耳。内用桂、附，所谓益火之源以消阴翳，为肿胀之圣药，诚对症之良剂。何自误之，而反谓痰积停阻必得峻攻为快，尤属可骇。往视之，证脉谛详，阳弱阴衰，惟有背水一法死里求生。若再不遵余用药，则必不可活矣。余甥求方，于是用金匮肾气丸加味治之。", "15740": "于九月三十正值霜降节日，于是以附子理中汤去参，加生黄耆，因其畏冷而用之护表也，合之五苓散，取脾肾两温。内附、桂之分两悉照昨方，二方合用即前金匮肾气丸之意而变易之方也，亦各有深意存焉。再佐以制半夏钱半、胆星五分，紫衣胡桃肉（连鬲）等，河水煎。更余服之，未几即觉腹中甚热，手臂牵掣，目闭神呆，喉中痰声，有发厥之势。张灯延余，乘舆而至，视其黏痰满口，唇吻间俱稠痰淋漓。斯时问答尚清，有吟咏之声而无痰涌之势，脉尚缓和。知其温中之剂入胃，与积痰相争，以致上则痰涎阻塞，下则遗屎，皆从温热之性相激而出也，究非脱象。如果是脱，何遗屎而不见尿出耶？", "15741": "温邪十日，胸闷无汗，口干喜饮温汤。早投寒凉，恶心频频，黏痰阻喉，舌胎淡黄无津，脉象濡数，不饥溲赤。速宜达邪退热，免其内传骤变，议「泻心」合「陷胸」法（四月二十九日）。", "15742": "素有湿痰，脾阳不运，肾阴有亏，右脉虚滑，左脉虚弦，非无以也。病起半载，医以滚痰丸、三子养亲汤辈，徒以消痰为法，脾土日亏，病势反增。又有作湿火治，投以苦寒辈清之，致令腹痛不食，泻多白沫，寒热，灯后畏寒。病颇棘手，乃尊甘谷特求治于余。余细绎病情，色脉合参，证缘误治日久，中焦失运化之职，先以仲景苓桂术甘汤加木香、半夏曲、淡干姜等煎服。", "15743": "素好饮酒，数十年来受累于火酒也久矣哉。细按脉息，左小右大，脾胃脉来弦滑，中按无力。知其胃土久伤，津液不充，胃中枯槁，以致食入则噎，甚至呕吐稠痰，粥饮入口即吐，涎痰并出。食难用饱，惟日进火炙糕聊以充饥。此反胃噎膈之渐也，盍早图之。议定呕化痰法，急治其标。", "15744": "是证年高脉弱，火酒伤中，致成噎膈。既服药应手，理宜加意调治，俾坤土得令，庶几可图。岂可性急欲速，惜费停药而自误之耶。然余用方之意颇妙，桴鼓相应，录案存之。", "15745": "自幼有痛症，以后渐胀、渐痛、渐呕水。一呕水，自觉胸腹爽快，宛然无恙。不时举发，发则胀痛难忍，必得胸中气松，呕水即已，屡屡如斯。至嘉庆十九年则发之甚勤，而痛胀呕水更甚，或味酸、味苦，或色青、色黑、色绿。数十年来不能睡下，惟坐靠而睡。睡则水声漉漉，惟右更甚，左右有块。于六月至今四十余日毫无宁刻，大肉消瘦，肋骨皆见，大腹膨而软。平卧于床，以手拑腹右则水声如鸣。日来胀痛异常，内如鸡啄。甚至发厥，冷汗如淋，危在顷刻。自早至晚呕出黄绿水一中钵，约有数余碗之多。上有油面薄衣浮于上，宛似豆腐浆上之衣式，惟色带秽黑耳。以箸挑去浮衣，内俱青黄黏水。右关脉来弦硬，按之不足；左脉弦细，两尺虚小，按之如绵。此属悬饮之症，水走肠胃之外膜原之间，而不在脏腑之内，独成窠囊。如孤军悬处于僻远之地，攻伐之所不能遽及。此由脾土久虚而太阴之阳微弱，不能随气升举消散，故名之曰悬饮。", "15746": "复诊：前方去半夏、肉桂，加归、芍、茯苓、川椒、元胡索、大南枣（去核内填乌梅肉二分，线扎同煎），服后呕痛如前平。因其安妥，喜啖炖肉，食饮稍增，与亲友叙谈至三鼓而睡。即此观之，其人之不能静养调摄可知矣。且久病在身，去年尚生一子，其好欲又可知矣。再兼厚味不禁，最喜食蟹。诸如此类，病深药浅，虽有良方，恐难济事。辰初饮粥一盏半，午前进饭半盏，以糟鱼过口。至午后觉腹中小疼稍胀，渐自痛增。以指探吐，又吐去如前之水小半钵，上有浮衣油面俱与前同。脉仍如前，趺阳脉较前细小，幸无头汗发厥之势。", "15747": "细绎病情，证属呕哕。夫呕哕者，即反胃、噎膈之渐也。病经十载，非不终朝医治，而治之不得其法，病根难除。据述素好饮酒，酒后贪饮浓茶，继以水果，坤土暗耗，是知脾胃之受累于酒也久矣哉。吾于此而想其原由，吾于此而卜其究竟。或食前贪生冷，寒气伤胃；或酒后喜浓茶，寒气归肾；或情不自禁，每多内作之荒；或力不能支，尚行外强之乐。以致坎阳不升，离阴不降，水火隔而心肾乖，君相动而脾胃虚。他如劳神会计，心一烦而胸中郁郁发呕。发呕者，反胃之征也。设或事不遂意，火一升而胃底泛泛欲哕。欲哕者，噎膈之兆也。又或食后遇事不快，而即呕酸吐食、咳嗽喉痒。种种情事，其为坤土之不运也无疑。再请验之于脉，两寸细软，左关小弦，右关虚软乏力，两尺虚濡。证脉合参，病关脾胃而波及心肝肺肾者有之。治脾胃而兼治他经则可，治他经而不保脾胃则不可。《易》曰：「至哉坤元，万物资生。」坤属于土，未有土不足而能生长万物者，此余之首重在脾胃者近是。先理脾胃，再为善后之谋，庶几病根可除而诸恙向安矣。", "15748": "服数剂后复诊：素多劳心会计，预事心烦，即觉胃中郁郁不舒，甚至呕哕、咳呛喉痒等情作矣。自进予方后，渐自平可，脉形两寸细小，关脉虚耎。先调心脾，再为之计。", "15749": "复诊（九月二十七日）：脉右关渐起，而两寸、尺尚嫌濡软，气血不充而真阳有亏也。宜以调中益气，兼治心肾，庶乎可也。", "15750": "病起于嘉庆二十一年冬间，楼下潮湿，睡处褥下俱湿。至次年春，移于楼上而卧，近于窗，又为风寒所侵。春间自觉胸前胀闷，已后心窝下，歧骨间（俗名人字骨下）起一梗，如指粗，长约四寸，不动不痛，累月经年。至己卯春，天明胸前作胀，食后胸闷，闷则气紧，必得嗳气稍松。夜间侧睡于左则腹中时响，若睡于右则不响。病脉合参，脉象虚细兼滑，痰湿交阻，凝滞脘中，结郁成条，有时微疼，按之如长竿，似属伏梁之征也。症经三载，沉疴积岁，先议调中顺气治其标，再商治本，第匪朝伊夕之功也。", "15751": "素有喘咳，兼好饮酒。于六年前曾呛血挟痰，逢节必发，或劳心费神亦发。幸食饮未减，酒戒有年，虽不时举发，尚无妨事。今季春适友人传方，用连壳鸡蛋四十枚浸尿桶内七日，取起再埋地中七日，然后煮熟。每早食两枚，连服二十日，共服鸡蛋四十个，从此喘咳不发，呛血全无，而且步行廿里亦不觉其气喘劳力。今半载未食其蛋，日来旧恙复发，咳痰挟血。鸡蛋将浸，特延诊治。脉象虚细小数，两尺濡耎。肺金虚而肾水不充，相火升而气逆呛血。幸胃脉尚平，犹可图维。先治其标，俾喘定血止，再为扶本。若徒以浸蛋之法，而无调补之功，恐非探本穷源之治。", "15752": "（案8）山西武良佐脉象沉紧，畏寒、舌白、胸闷作痛、得食即呕吐极重治验，论治颇的，细阅便悉", "15753": "六脉沉紧，遍体不疏，舌苔白泥如粉。胸前闭闷，食入气逆呕吐，脘中时痛。小溲色赤如血，大便半月未解。年近三旬，病经月余，夜间畏寒尤甚。比症得之冬间伏寒，西人纵啖湿面，致令中宫气阻、食滞、痰凝，有表面两感之候，岂可渺视之乎。于是以秦艽、桂枝、制半夏、瓜蒌仁、柴胡、枳壳、白蔻仁、甘草、赤苓、猪苓、生姜皮等煎服。服后次日午前稍松，夜间依然如昨。", "15754": "素有脚气，侨寓江南，更多卑湿，身长体伟。西人好面，湿痰常有。于嘉庆己卯七月下旬，脚气病发，由暑湿夹食，阻滞中宫，上下不疏，以致两足肿胀，寸步难行，脘腹攻痛，头胀，舌苔糙泥，遍体酸疼，欲呕不饥，不嗜饮，小溲少，脉息细小。治宜清暑、却湿、和中。", "15755": "时行感冒，风火上攻，头胀，耳聋且鸣，病起九日，大便七八日未解。舌胎泥黄，咽嗌不爽，脉象浮缓小数，是非轻候，法宜清解。", "15756": "西人好啖面食，南方地土卑湿，脾土不运，水湿浸淫，肢体漫肿，渐自腿足，阴囊及茎俱肿。脉息沉细软小，湿鼓将成，便溏腹胀，脾肾攸关。", "15757": "据述病情：因昨游虎阜贪凉饮酒，回寓至半夜腹痛甚剧，呕之不畅，吐之不爽。天明叩门延治，证脉合参，暑湿挟食，此属霍乱，治当温舒。方用厚朴、半夏、藿香、青皮、枳壳、楂肉、麦芽、滑石、赤苓、木香、豆蔻、陈皮等十二味煎服。未服前先进左金丸六分、生姜两片，泡汤送。服之，吐泻、腹痛俱稍减。", "15758": "由湿阻中宫，胃土不和，心似荡，不知饥。舌苔白腻，脉息濡软。当理阳明为最。", "15759": "案：肝主疏泄，肾主闭藏。梦泄无时，兼多腰疼，晡热，溲赤。固属肝肾之有亏，亦关心荣之不足。脉形虚濡小数，良有以也。", "15760": "晡热渐退，舌苔尚泥。上则耳鸣，下则精滑，脉息濡数。相火升而水不能济，当于心肾求之，所谓心象垂滴，肾象拱鞠，而再得黄婆为之媒合，安靖上下，庶几坎离交济矣。于斯论治，可与谈医。", "15761": "右脉虚软，左部濡下，自是肺肾两亏之征欤。盖肾主水，肺主气，气上腾便是水，水下润无非气。一气贯注，百脉流通，得其意者于此中消息之。", "15762": "风寒湿三气合而为痹，四肢两腿、肩背皆牵引板滞，动辄疼痛，头重转侧筋强。舌苔泥白如粉，脉象细耎，左弦紧。亟以祛风逐湿、散寒温中之法，冀其渐松为妥。", "15763": "大病之后复感温邪，迄今一候，得大汗而解。尚口渴喜饮，昏语如前，往外奔走，舌绛痰多，似清非清。证脉合参，痰火留恋，又值复感，虚实相兼，难以稳许。即用川黄连、羚羊角、天竹黄、半夏曲、陈皮、赤苓、胆星、甘草、黑山栀等。煎服后，次日依然如前，大便一次，先结后溏，脱势之象。叩门乞方，不得已拟助正生津以应之。", "15764": "痛症有年，屡发无时。今感寒气阻，湿食相凝，以致呕痰畏冷、胸脘痛剧难忍。病经四日，医以疏气活血之法不应，因延余诊。脉息浮小，用苏梗、蔓荆子、草蔻、木香、神曲、麦芽、香附、莱菔子、陈皮、生姜等。服之，呕吐即已，而胸脘仍痛，不饥。", "15765": "其人手工为业，家贫母老，少妻幼子。伤寒垂危，医药罔效。其母往向日相帮之王氏主人处，哭告独子垂危之苦，主人因许伊请封，并嘱人代往余处告诊求救。予往视之，细绎病情，于去冬严寒衣薄深感寒邪，更兼新正其母往向日之主人家恭喜贺节，不无有年糕、粉团携归，其子任意纵啖，又食荤腥湿面，以致胸脘闭闷，逐动伏寒，甚至畏寒身热，狂言奔走，继又默默不语，尿出无知。病势日增，又为误投寒凉，神昏呓语，人事不知。诊其脉浮小，况滑。食毫不进，汤水与之少饮。奄奄一息，难以图救。惟二日尚灵活有神，口鼻热气直冲却非喘也。其母哀哭泪下，叩首乞方。不得已索思良久，其人冬寒内伏，又加过啖黏糕肉食阻塞中宫。始也畏寒身热，继又食化为痰，久之寒化为热，痰火内蕴，致令神昏谵语而不知人。病经两候之久，缘荐人之诚心代请，伊母之叩首乞方，不得不竭力图之。", "15766": "复诊：邪闭心包络，神识昏昧，似清非清，呓语绵绵，舌泥干糙无津，喜饮兼咳。服前方，顷之解溏泥粪，如胶如漆者甚伙，摄拳手痉。脉右软小，左弦大。正虚邪恋，棘手极矣，拟辅正祛邪法。", "15767": "次日午后复诊：观其问答稍有明白，能识伊母，且能叫余。顷之又有欲睡之象，是倦怠而非脱势可较。按其头臂，热已退其大半。脉右如昨，左之弦大已减。再以昨方去黄芩、胆星、沉香三味，如前煎服。其万氏牛黄丸仍照昨法先服，服后日渐平妥。若非对证之药，万难一救。余怜其极贫，两日不受请封，肩舆往诊，自此两剂而愈。快矣！快矣！", "15768": "风暑相搏，胎疟初发，寒短热长，似属热甚于寒，而寒时戛齿鼓颔，战栗恶寒，合之色脉则又寒甚于热矣。治法当先和荣卫，俾寒减热缓，再为之计。", "15769": "脾肺久虚，土不生金，而木寡于畏，不惟伤土而且犯肺。肺虚则表不固而感冒易，脾虚则痰渐升而咳嗽频。痰壅气逆，宜乎口多涎沫，而动辄多汗也。脉象虚滑，左弦尺濡，显有明征。法宜补土以生金，因脾为肺母也；滋水以养木，因肝为肾子也。从此水土合德，金木相安，又何虑夫咳嗽痰升而致多汗也。", "15770": "昨于午后，陡然寒热，背疼胸闷，呕吐不畅，脘腹痛甚有汗。脉形浮弦，当用疏解法。服后，背疼止，呕平。", "15771": "复诊：脘腹痛发，痛剧甚至叫呼不已，手指厥冷，有汗。稍可进粥半瓯，大便欲解不解，口不喜饮。脉息浮滑，左弦细，舌苔糙刺、泥黄。证岂轻候，亟宜舒运、安蛔止痛，兼之润燥通幽，取通则不痛，以冀转机。", "15772": "右齿疼痛无宁，脉象浮弦。风火上攻，引动相火，治在轻清。", "15773": "素体虚肥，色带痿黄，又多湿痰，向来大便溏薄。日来感冒客邪，灯后寒至凛凛，微热不解，无汗，不饥，舌苔糙泥，迄今六日。进他医清解法，精神日疲，尿便不由自主。脉息右弱，左弦细。高年人恐难胜任，亟宜却寒和中。方用苏叶、防风、桂枝、陈皮、豆豉、枳壳、麦芽、秦艽、楂肉、半夏曲，加姜、葱同煎服。进一剂，病若失矣。已后至来年癸巳五月十六日，因湿阻中宫，致伤坤土，食入脘中不爽，大便溏泄则腹中舒畅，便或结秘则脘腹滞塞不松。数余年来，便溏日三四次或六七次无定规。脉象右细耎，左小弦，此由脾及肾。素嗜浓茶，以故湿阻不化，似觉便溏则爽，便结反闷也。然究其源，实关脾阳之不运耳，如果坤土健运，何至便溏则爽，结则反闷耶，亟亟培养中宫为第一著。", "15774": "风暑挟湿，忽然手足逆冷，皮寒毛耸，顷之渐热，热至潮润有汗则身中渐爽。早晨热微神安，午后渐热则心烦多语，少顷又有忽寒忽热之势，未病前一日走泄夺精。病由是月初八冒暑奔走，多啖西瓜，晚归自述腰疼足软，当夜始发寒热。初九延余次子茂常往诊，进疏解法腰痛即平，寒热未减。初十日特告治于余，细绎病情，知其先伤于暑，暑必挟湿，又为风搏。是以先凛凛而后热，热至有汗而渐爽，顷之又复寒热无定。此暑为风搏，湿郁于中，三气交阻而未能疏泄也。至于病前夺精，不过阴气亏而寒热觉重耳，第不可作夹阴论治而节外生枝也，况于盛夏乎。因以生地、丹皮、地骨皮、黄芩、通草、黑山栀、葛根、葱汁炒防风等，加川郁金汁五分冲服，服后夜间烦躁，欲寐即梦，胸中气闷，恶心，口干喜饮。至二更时，大便结粪一次甚畅。饮粥后渐睡至天明，热渐缓，醒后气闷已平，仍有恶心之势，余俱如前。舌苔糙泥淡黄，小溲少，色赤，脉形浮软，尺濡。复诊仍于前方加减服之。", "15775": "手臂肩项动辄牵疼，舌苔泥白中黄，脉右大于左。长夏湿升，胃土不和，脉络不利，口黏、溲赤皆有之也，治宜和胃却湿。", "15776": "睪丸肿痛偏左，证名偏坠。脉象沉弦，受寒所致，温舒下焦为妥。", "15777": "六载头风，百治罔效。想亦虚实未辨，缪执成方耳。细绎病情，合参证脉：体伟脉软，两关弦细，左尺濡小，素好饮酒，其为中虚挟湿之躯也。头风之因，由鼻洪过伙，骤然如涌，治之不应，后有以寒凉并进者渐自停止，然虽止矣亦未尽善矣，以故转成头风一症。头脑畏风，须重绵固护始能稍安，然必得汗方平，是以逢夏则安，遇冬则发也。病情如斯，实有至理存焉，请论之。夫头为诸阳之首，鼻气通于天。天者，头也，肺也。肺主一身之气，统诸经络血脉，上下贯串，莫不本之于气。今血去过多，气不能统而阳络大伤。阳络者，胃络也，是以血从上溢也。何以独见于鼻右，右属西方兑金，与阳明艮土为子、母。且阳明胃脉环鼻，鼻通于脑。脑为元神之府，上有九宫，同气相应也。外邪固不可侵，内风亦不宜生也。头风之发，每于春夏得温热之气易于汗出，而即不觉其胀也；遇秋冬凉寒之气腠理渐闭，而即知其畏风且胀也。其所以然者，血去多而肺金之气弗克上充于脑。金土虚而肝木乘之，内风易生。气虚表不固而外风易入，与内风相煽，头胀随之。然风必兼火，火必挟痰，更兼素有之湿合而为一，日积月累，无怪乎病魔久矣。每多忘事，或二目作疼、内眦发红、多泪，或小溲溷浊不清，则胸中不舒，种种见证，上则内风生而痰火凝，中则湿气阻而升降不灵也。病从肺胃，而波及于心、脾、肝、肾者有之。治当益气护表，侑以引经之法，俾气升火降，中宫健运。六载沉疴或可从斯而平矣，无再赘矣。", "15778": "溲出茎中疼痛，败精留阻，频出无时，左脉弦数。此淋症也，妄作白浊治故无功。宜以舒通，通则不痛。", "15779": "大病将痊，脾阳未复，运化机迟，荣阴不滋，肠燥便闭，脉形虚软。补其中，调其荣，而气既充满，血亦流行，阴阳和而英华发，高年恙后，颇合时宜。", "15780": "脘中作痛，在于歧骨间（俗名人字骨下），迄今八载。迩来日渐作楚，食入不爽，有似于胀。每痛发于午后，早上犹可。病关足阳明胃，波及太阴，湿土气阻不舒，中州失运化之职，未免生湿成痰者有之，此痛之所由来也。还恐坤土弱而震木乘之，致令呕吐，酸黄苦水直涌而出也，预防云乎哉，况脉息耎小，左弦细，尤显有明征耶。", "15781": "素好饮酒，阴亏体质。夜间手足发热，业已久矣，脉来虚濡乏力。防潮热骨蒸之变，亟宜退热为最。", "15782": "脾土不舒，肺卫表疏，易于冒风。头额有时热而有时疼，鼻流清涕，胸脘易闷，食无味，口不干，脉右细耎。虽额热、头疼时有时无，合之脉象却无风寒食阻，究属内因，攸关脾土、肺卫，当护表和中，再为之计。", "15783": "脘痛经月，胃络大伤，还防血溢。舌苔中央淡黄泥浊边绛，痛剧伛偻难忍，朝轻夕重。药饵乱投，苦寒攻伐更非所宜。脉息沉细难寻，权拟温舒法，以冀转机。", "15784": "痧后二旬，余邪未楚，药饵乱投。咳嗽痰厚，咽嗌色红，上腭红点满布，声哑音低，咽唾觉痛，食减饮粥，脉右弦数。深虑痧劳之险，断断不可忽视。", "15785": "似寒似热，医作伏邪治，一派寒凉之剂屡进无功，热终不解而仍兼寒凛之势，食减神倦，求治于余。审证切脉，冲龄质弱，脉象浮软，似寒似热。外为风搏，内为热阻，防甚转疟，拟轻舒法。", "15786": "病后中虚，湿蕴坤土，发为黄疸。身目俱黄，指甲亦然，色滞而晦，脉息软大、左弦，先从温中却湿治。", "15787": "虚鼓危症，由病后屡复，食饮不节，早啖荤味。睥土不运，更兼阳弱阴亏之躯。病后两月，于前月自足跗渐浮，而致腿足皆肿，按之成凹。日来大腹亦肿，拊之如鼓。小溲甚少，大便频解溏薄，日数次，每解腹中必痛，脾不运而成积滞。脉左虚弦，右软滑无力。鼓胀已成，荤腥不禁，最难调治。", "15788": "是鼓也，缘伤寒后不禁油腻、荤腥等物，致令病后屡复，甚至腿足皆肿，面目俱浮，大腹膨胀脐凸。渐自便泄日数行，而小溲全无，皆从大便中出，清浊同行。何至若斯，亦为任意恣食，纵啖无忌，而变症蜂起矣。鼓势已成，药投罔效，特求治于余。余细绎病情，合参证脉，知其脾土日惫，积滞丛生，湿气内蕴，水凌土位而肿满随之，此虚实相兼之鼓也。治当先以扶土却湿运滞，俾湿滞渐松，随证脉而消息之。不四五剂果然二便分利，肿势渐减，食饮渐增，皆得力于汤丸并进之功也。病者因其效速，渐自贪食，纵啖之故态依然。是日予至诊视，自云昨进腌蹄荤味，觉腹中稍不爽。今食豆板炒冬菜，素味甚美，竟啖其一小盏矣，予深恨之。次日告诊，据述昨夜腹中一夜不爽，且增膨急，足跗小腿益加紧硬，脉形弦急。予曰：「皆自取之也。」其人即于枕旁取出火炙糕与余云：「自后不拘食何物必须先请教，今就此糕到底吃得吃不得么！」观其色面红动怒，再与之言必反受其辱矣。录此以为纵啖自误者戒。", "15789": "服前方，热势渐缓，午后稍增，夜安寐。利由泄泻而起，日夜数次。便时一响而溜出，色黄，并不腹痛。此湿阻也，以故小便短少，口不喜饮，舌中心淡黄边白也。自进昨方，夜间未解，次早解一次，少顷又解一次。服药颇属应手，惟高年脉来濡耎，究防变幻。", "15790": "身热胸闷，舌苔腻白如粉，骨节疼痛，不饥不渴，体倦昏语，脉象细小。风寒内闭，食阻中焦。治宜温舒，得汗为妥。方用厚朴、豆豉、苏叶、桂枝、半夏曲、谷芽、楂肉、赤苓、陈皮、生姜等，十味河水煎。服一剂，顷之觉烦，烦后汗出遍身，从此热退胸宽，继以和胃运食而安。", "15791": "患淋症廿余日，溲出兼疼，茎中带痒，大便秘结。旧有痔疾、脱肛。脉形弦数，按之不足。阴亏挟湿火，灯后浊甚，静则少，动则多，色带淡黄。拟益阴降火，佐升清降浊法。", "15792": "时气喉肿，身热两日。前延疡科治，溃脓后痛缓热平。今忽复热，喉腐未痊，由右移左。相火升而风痰上扰，舌苔泥白，中心淡黄，夜寐呓语，脉息濡小。法宜清舒退热，深恐变幻。", "15793": "午后忽然身中先凛凛而后热，胸前气闷不爽，舌苔白泥，便溏，病得于夺精之后，自觉烦躁，脉息浮小，左手弦细，时邪内伏，阴亏之体最宜小心，俾邪由内达外，免其变幻。", "15794": "西人素好湿面，脘腹痛胀难忍，脉形沉细。寒与湿食交阻，时值八月廿有八日，更余延诊。当用香附、草蔻、半夏、莱菔、木香、枳壳、薤白、陈皮等，服后痛胀更剧。", "15795": "复诊：脐腹上下痛胀甚剧，舌苔中心淡黄，小溲赤，大便三日未解，脉仍沉细。未便遽投攻伐，宜以温舒，以冀痛缓胀平为善。", "15796": "客途暴疾，风寒束肺，气逆畏冷，咳嗽痰稠，舌苔白泥如粉，脉象浮紧。素有吐血症，内虚之躯不可藐视。", "15797": "溲出痛如针刺，淋症初起，脉息弦数。败精留阻，舒通为最。", "15798": "时邪六日，身热忽辍忽作，却非壮热。胸脘稍闷，微咳，纳粥，舌苔中心淡黄。年将冠，主家有夹阴之疑，医者有湿温阴虚之虑。四肢清凉，而以四逆散加葛根、芩、连、栀、豉、茅根等，服之不应。又云阴虚之体，防邪热内陷等语。总之，不识病情，妄闻主家之言而附和之，殊属可笑。又投以清凉退热之剂，仍然寒凛而后热。又云肤中隐隐红点，犹恐邪陷。主家仓皇，特延余诊。细绎病象，证于是月十三日夜在堂饮酒啖荤而归，当晚觉身中凛凛而后热，热亦不盛，脉形弦细小数。感冒时酸所致，非湿温症也。经曰暑湿相搏，名曰湿温，是谓贼邪。至于脉象，必「阳濡而弱，阴小而急」，方是暑气蒸湿也。就色脉详谛，宜舒表和里转疟为妥，不可概以湿温论。况小暑未至，何来湿温。业医者，不宗《内经》、《伤寒》，开口便错，误人匪浅。方用厚朴、豆豉、杏仁、桔梗、牛蒡、赤苓、楂肉、橘红等。未服之前，先凛凛而寒，四肢厥逆，后复热得汗渐松，方服前药，夜间安逸。次日延诊，热缓，诸恙减可，仍宜表里并调，前方损益之，服之颇安。", "15799": "复诊（五月二十日胎疟间发初次）：申初先凛凛而后热，未几汗出热退如平人。即此观之，脉象弦细。时酸之邪，本伏膜原半表半里之间，今渐转为时疟，益信予之前言不爽也。", "15800": "身微热，舌苔白，脉象浮濡细小。外为风邪所搏，内为湿食交阻，此腹痛水泻之所由来耶。", "15801": "六月初十复延诊治：便溏将平，食入不运。年近古稀，坤土弱而坎阳不足以生之。脉息虚耎，咳呛痰少。先理脾肺，再为善后之谋。", "15802": "月余后，因不饥纳少，脉右软尺弱。议火土并治法，服后方数帖，始平复如常矣。", "15803": "暑湿夹食成疟，寒热俱长，间日一发，舌苔白泥，得食即呕，胸闷且热，兼之泄泻，脉形弦细，耐性调治。", "15804": "身热，胸闷，腹痛，呕吐蛔虫。舌苔白泥，脉息沉紧。气闭受寒，温舒为宜，以苏梗、厚朴、防风、姜半夏、橘皮、白蔻仁、赤苓、枳壳、莱菔子、开口川椒、木香等十一味。煎服后，身热渐退，呕平痛缓，胸闷顿松，舌之泥白渐转淡黄薄苔。", "15805": "胸脘气闷，得食即胀，悠悠而疼，波及左胁腰腿，兼之块攻，舌苔白泥，口不喜饮，小溲色赤，脉象沉迟，两尺浮耎。病经廿余日，医以旋覆花汤加新绛葱管，不应，又以温中、通气、消食等药数帖，亦不应，因求治于余。余细绎病情，脾土不运，肝肾有亏，先以扶脾温中，再为之计。于是以温中却湿等药治之，罔效。后用香砂六君法，午前服之；临卧前再以桂附八味丸二钱，滚水送。自进此丸之后，当夜腹中稍松，并不胀闷。西人性好啖面食，因其胀宽而多进之，腹中又有反复不舒之象。仍以「香砂六君」，加熟地、归、芍等养阴。服之非但胀平，且痛与块皆从斯而散矣。", "15806": "痛痹复发，自不节食所致。上部肩背手臂俱已不痛，惟右腿膝壅滞不能下行，脉来细耎小滑。湿痰阻络，温舒为宜。", "15807": "住居三吴，自浙回苏，河中舟底漏水甚急，惊吓异常，引动旧恙痛症。归家未几，朝轻夕重，宛如刀刺，在于人字骨下，即歧骨间也。太阴、少阴所居之地，久痛非宜，还恐见血。脉息沉迟，不可忽视。先以调气和荣，佐以温舒为稳。", "15808": "又，二月十八日：痛症有年，惟今发之最剧，连日心嘈易饥，得食渐平。年高脉弱，中气久虚，当益气和中，肺胃并治，兼养心荣为最耳。", "15809": "自服参剂八帖，气短心嘈渐平，食饮渐贪，精神稍健。停药数日，兼之劳心，于三月初八日歧骨间痛又复发，夜甚于昼。气荣交阻，脉象沉滞，权拟温舒，再为之计。", "15810": "余案中所论痛症治验甚伙，亦非概以温补为法也。医贵灵机活变，切脉审证无拘拘于板法，庶几尽之矣。细阅便悉，兹不再赘。丙申六月二十三日竹亭老人再笔于遗安堂之有竹居。", "15811": "又，自服前方之后，惟祈仙方以应之，兼多烦劳操心，饥饱失时，忽于乙未十一月二十三日旧恙痛症复发，仍起于歧骨间，昼轻夜重，痛剧则呕吐酸黄水，甚至臭汁黑水，皆从胃底泛来，致令气逆呃忒而无已也。脉息沉滞，左弦乏力。病关心荣肺胃，而兼肝胃者有之，议仲景和法治之。", "15812": "又，十一月二十五日：天明，呃逆一二声即止，心窝疼缓，自觉脘中郁郁不爽，大便秘结，胃口不开，舌苔泥白糙刺。用二陈汤合「左金」法，加沉香、丁香、柿蒂等煎服。至夜半痛又至，复呕酸黑水一大盏，幸未呃逆。色脉合参，再痛防其厥脱，议代赭旋覆汤法，以冀转机。二十六日方附下：", "15813": "又，十一月二十七日夜诊：即前方去谷芽、南枣两味，加醋炙元胡索、荔枝核等煎服。痛减，因进烂饭有时小疼，胃口稍健，神识渐清。第易于动怒劳神，高年脉弱，左弦急，与呕痛、呃逆等症最不相宜。岂可因小愈即下楼管理家务，与亲友操心代劳。不思谋虑决断、曲运神机、多言事冗，皆伤心、脾、肝、肾，而一身之气总统乎肺也。以故发则痛呕并至，岂非心与脾也；味酸色黑，岂非肝与肾也；剧则气逆且呃，岂非肺气之虚也。理宜竭力图维，犹嫌鞭长莫及，岂可藐视之乎。", "15814": "痛疾有年，屡止屡发，前论颇明，无再赘矣。要之静养调摄，无烦劳，戒多语，俾食饮贪，精神健，即可冀其痛疾之常平，况平素脉带阴象，岂非永年之基也，勿自误之。", "15815": "先生溧阳名医也，远近慕之，乡宦有疾问治于先生者居多。忽于左颧生一小颗，不疼不痒，无足介意，由渐而大。始也自医，继也告诊于疡科。外敷、内服毫无一效，而反坚硬不移。千方百计，越治越大，大如鸡卵。斯时有外县请诊于先生者，概弗克往，朝夕踌躇。适遇伊同乡金子竹溪兄，特荐治于余。予证脉合参，知其用心过度，更兼色欲无禁，好啖厚味，此脉之所以软弱细小，尺按之如绵也，此就脉而言之也。再视其外形，坚如铁石，推之不移。知其厚味之毒乘虚而盘踞于颧骨之间，更兼舟车，更深夜半，不辞劳苦，寒气又乘虚而侵其骨，以故根深外坚而成骨疽之名。延绵十月之久，最不易治，况年逾半百，若斯伤精耗气之躯，尤难之难矣。盍早为之尚有法焉，迟矣！迟矣！方案列下以俟自裁。", "15816": "脉右虚耎，左脉细小，尺按之如绵。左颧漫肿，坚如铁石。病经十月，牙关难开。攸关心脾，波及肝肾，精血久亏，寒侵于骨，骨疽之征也。病由内生，所谓「有诸内而形诸外也」。不此之求，而妄作外症治，恐溃后难以痊可，必得调其荣卫而侑以外灸之法，正合外内之道也。", "15817": "素体肥胖多痰，于乙未八月二十八日痛症复发，脐腹绞痛，叫呼难忍，迄今三四日。据述服桂附八味丸及脾约丸俱不应，痛如故，危急极矣，特求治于余。予细绎病情，合参色脉，舌苔泥白如粉，脉象沉紧，痛无宁刻。此寒与气食交凝，大便闭塞，痛剧防厥，未可藐视。拟温舒法，用香附、干姜、淡附子、木香、沉香、乌药、淡茱萸、元胡索、荔枝核等九味，河水煎。服后少顷，腹中上下奔走，至胃底而复上。自觉肛门塞紧，便秘不能解。是以下部不通，而脐腹之痛不止也。", "15818": "又，申刻诊：痛已大减，较之辰时初诊伛偻剧痛之势大相远矣。第脉形尚滞，舌白如前，大便通而余滞未尽。此际宜和其中，佐以舒涤肠滞为最。且食宜少进，庶无变幻之虞矣。于是以生谷芽、苡仁、木香、砂仁壳、大腹绒、薤白、鸡内金等七味煎服。服后妥甚，又解黏腻粪两次，贪食，但舌白泥未转，胃土之津未复，食饮究宜节制。", "15819": "又：进前方颇宜，仍于前方加减，调和坤土。四五日来，精神渐健，有时腹中稍有疼刺，得食即安。舌苔已退，脉象虚耎无力。议用异功散加玉竹、归身、枣仁、南枣等以调心脾，则坤土和而夜寐安。", "15820": "素有肠红，操劳多步，或贪凉饮冷，则便血频下，色带鲜红，幸饮食睡卧如常。脉象虚耎，左关弦细。此脾阳不运，肝阴有亏。先理坤元，再为之计。", "15821": "又，咳血虽止，脉仍弦数，究宜静养为最。", "15822": "右脉软，左寸虚、关弦、尺浮小数。肺胃虚而肾水不足，相火易升，此吐血之所由来耶。", "15823": "又，昨辰诊脉左关弦硬，相火上炎，防吐血复发。至夜果然胸膈热闷、喉痒，忽吐血一口，随又痰中带一二口。今日肝脉反不过弦，而按之不静，犹恐再吐。自前吐血迄今，约有二十四五日未吐。已后咳呛、便溏，脾肺并治，食增泻平，皆得于用药之权衡也。细审之，其中有不相宜处在于日贪肥甘厚味，朝夕必啖肉食，未免生湿成痰，而脾胃弗克健旺者有之。古人云：「宁食淡茹蔬，莫贪肥与甘。」旨哉斯言！予深嘱之，料知命者依法调治，庶可无妨。七月初七日方：", "15824": "又，进前方痰红即止，再二剂如前安妥。惟耳鸣，睡醒喉中似干，日间并不喜饮，食贪睡安，所嫌脉未平静耳。用沙参、首乌、元参、龟腹心、巴旦杏、山药、苡仁、芡实、炙甘草、白花百合等十味。煎服五六帖，诸恙向安。煎帖屡效，继以丸剂调补，列下。", "15825": "左关虚弦、尺濡，右脉虚软无力，自是肺、脾、肝、肾皆虚。肺何以虚，土不生金也。肝何以虚，水不养木也，木无水养，而相火易升。肾何以虚，金不生水也，水无金生，而肾精易竭。且子虚者，必求救于母，肺求脾，肝求肾，而肾复求肺，肺金之虚愈加亏缺。夏间之吐红未必不由于此也。调治虽痊，脾肺久虚，第知补肝肾之阴，而不思调脾固肺，究非挈领提纲之治。", "15826": "又，溲出茎中疼痛，完后稍缓，脉息弦细小数。议益阴降火，佐以祛淋，免其淹缠。", "15827": "藜藿之体，质弱劳苦，去冬受寒，今春头面渐自浮肿，而致大腹虚膨，阴囊胀大，甚至阴茎渐粗，阴头绞转朝上，小溲少，脉息虚软迟小。此水肿症，由脾阳之不运所致，拟温中法。", "15828": "淋浊症，溲时尿管疼痛，完后亦然，兼有败精频出，口干喜饮。相火未清，脉形细数，宜益阴降火法。", "15829": "疟发间日，寒甚于热，迄今三发，每发于午正，脉来细弦。温舒和解是其治法。", "15830": "两胁作疼，波及于腰，少有干呛，脉左濡小。肝肾攸关，法宜舒络，侑以却湿为妥。", "15831": "年近四旬，素多操劳，阴虚之体，忽而呛血杯许，色带紫红，有时成蔑，脉息弦数。血犹未尽，拟去瘀生新法。", "15832": "据述病由长夏冒暑身热而起，愈后未几，复又寒热。调治将痊，忽于七月十四发痫症。乃尊云：「体质素薄，未发前两日友人适谈及鬼怪事，当闻之自觉其惊，次日即自言自语，东步西走，默语声低，食饮不减，夜不成寐。」医作虚痫治，用参、术、菟丝、肉桂等温补不应，又有用滋阴安神等法亦不应。皆以为痫症论无功，因于二十五日始求治于余。余细绎病象，癫也，非痫。盖痫病发则陡然跌仆，口作六畜声，痰涎随出，或手足牵引。少顷病退则宛如平人，问答无差，惟觉软倦，精神不足，或十日、半月一发是也。如此癫症，岂可妄认为痫耳。癫之发也，终日坐立无定，口内默语不知，文而不武，或笑或悲，食饮多进少进亦无饥饱，朝暮皆同，非痫症之陡然发，少顷退如平人可较也。迩来时医以癫作痫，案中称虚痫者是也。以故病家亦以为痫症，而竟不知其为癫也。医人尚不明，况病家乎。脉息细滑，左弦小数。虚痰挟火，凝滞包络，阴亏体质，亟以祛痰降火之剂。进四五帖后，朝进归脾丸五钱，麦冬泡汤送。晚间临卧前再以白金丸二钱，橘皮泡汤送。急则治标，缓则治本，汤也而继之以丸，职是故耳。", "15833": "新产之后，感冒风邪，脉带浮缓，身热欲呕，少腹疼痛，恶露未消，兼之咳嗽。治宜轻疏，侑以散瘀。", "15834": "两目胀痛羞明，午后更甚。上部觉热，下部足冷。病经二旬，脉象浮数。风火内郁，治宜清散，俾邪外达，则胀痛羞明自已也。", "15835": "肝阴素弱，脾阳久虚。脾何以久虚，火不温也；肝何以素弱，水不养也。经停半载，气血两亏，脉之左关、尺虚弦，右寸、关虚弱，显有明征，盍早图之。", "15836": "上齿时痛，数日来痛无宁刻，至午后尤甚。上齿虽足阳明所属，而齿乃骨之余，亦未尝不关乎肾，况尺脉虚数，非无以也。", "15837": "得时热证，延余诊两次，即更医。医以犀角、大黄、茅根、芦根、芩、芍、夏、陈、枳壳、麦芽、佐荆、防等。服后泻溏粪二次，而身热胸闷如前。医至两候，病势沉重，复求治于余。身热未解，舌边白中黄，口渴喜饮，胸闷按之痛。时邪为寒凉所遏，脉象浮数，症兼结胸。拟小陷胸加味，以冀转机。", "15838": "又，进前药便解身凉，脉象小数。是以汗多口渴，舌色淡红，稍兼恶心。固余火之未清，亦胃土之未和也。", "15839": "病后体虚，又冒风邪，微热，舌白，食凝气滞，少腹痛甚。块偏脐右，按之愈痛，痛剧块攻，约长五寸，阔有四寸。右寸浮小，关脉沉滑。此冒风而兼气食交阻，非温疏难以去疾。", "15840": "案云：营气不从，逆于肉理，乃生痈肿，此外症之大概。今则脉数见于沉分，右关尤甚，知其暑湿郁于土中，发之不透，根盘散漫，脓未成而孔多，自非轻候。幸按之尚热，但不可早投寒凉，以致遏抑。治宜托之、散之、清之、和之，随症脉而变通之，合外内之道也。", "15841": "下焦感寒停经，腹痛不止，血块时下。年近二旬，病起四日。脉左牢大，瘀血内蓄。细审之，痛因行经房劳而起。脉症相符，治在温疏。（八月十二日）", "15842": "又，经行房劳，下焦受寒，血紫块攻，痛剧防厥，脉左牢大。前剂小效，药力尚轻。再以温经散瘀，佐以疏通。通则不痛，而瘀块自消矣。", "15843": "服一剂，痛平血止，并脐腹下之硬块全无，诚良方也。然必须按脉审症，的信经水为下焦寒郁成瘀，方敢重用温通散瘀之法。不然，仲秋时附子、炮姜各用一钱五分，如此重投，岂不有误。即是深冬，经非寒郁，不过气滞血凝作痛，惟有疏气和血而已，亦不敢用此重剂。如前初用元胡、归尾之方，原是轻剂。后方之用，因有血块攻痛形迹，合脉左牢大而用之也。阅斯者，宜细心体会而详辨之。（竹亭自识）", "15844": "究竟因脉症之不虚而不用补剂，非论乡僻藜藿之人而概不用补剂者言也。（竹亭自识）", "15845": "又，半载呕吐，病已痊可，继以丸剂，以善其后。案云：经行迟速无期，或二旬或四旬一至。午后发热，经行之前则尤甚。骨节酸疼，带下绵绵不已。细按脉象，右寸关虚软无力，左关尺虚弦小数。自是肝肾之阴弱，脾肺之阳亏。又恐补脾不利于肝肾，滋肾不利于脾胃，以脾恶湿而肾恶燥也。今处两方，分早、午服之，不无小补。第仍宜节食戒怒，庶乎尽善。", "15846": "又，衄血昨已停止，今晨因咳呛而气逆，左鼻稍有一滴，脉之弦数已缓，无足虑也。", "15847": "经水淋漓，月余未止。头汗如雨，剂颈而还。胸中嘈杂，举动则头晕眼花，不能安卧。六脉虚小乏力，关脉见芤。去血过多，阴固亏也，阳愈弱矣，亟宜益气扶阳。盖有形之血不能速生，无形之气在所急固。若不此之求，而概以纯阴之品，究非所宜。速用固气以统之，犹恐鞭长莫及，慎之！慎之！", "15848": "前因崩血月余，头汗剂颈，几乎欲脱，不得不急固气以统之。今血停七日，日进粥数碗，脉象虚小。犹当调和脾胃为最，俾饮食得运，气血渐充。此际不宜过补，过补妨食，恐反难以运化也。遂以五味异功散加广藿梗、煨木香、生谷芽，服七八剂食饮倍增，安卧如常。至六月初五日延诊，用八珍汤加制香附调理收功。", "15849": "新嫁月余，小溲涓滴，溺时甚痛，又兼尿血，经水迟速无定。医用龙胆泻肝汤，尿血虽止，而小便之难、溺时之痛则更甚于前。忽又于六日前，夜间手腕郁筋，酸痛难忍，仍邀前医。伊以为手发背，内服煎方如前出入，外用敷药，肿势更增，尤加酸痛。程梅溪翁荐治于余，余细阅外象，漫肿无头，自手背至腕后俱热。即用白棉料纸一小方，以水浸湿贴于手背上，亦不见有即干之象。如其是疮，漫肿无头，一时难辨，即以湿绵纸敷上，先干者即是疮头。此则非是，实缘郁筋而起，他医误指「手发」，再治之，弄假成真。予按脉象，左关尺弦细小数，下焦湿热为患。小溲涓滴，溺时痛甚，此淋症也。服以分清却湿之剂，敷以活血疏筋之法，则外之疼肿，内之淋痛，皆可从斯而缓矣。何必节外生枝，草菅人命耶。", "15850": "经停半载有余，切脉审证并非胎象。始因食茶而起，不无虫积。继而停经腹胀，时痛欲呕，病属肝脾。夫肝藏血，脾统血。今火郁于肝，湿郁于脾，无怪乎两关沉细，而经水不行也。因经而致病者，究宜调经解郁为主，俾经血通而诸恙可平，不然恐有虫、血二蛊之虞。", "15851": "头痛虽分九宫，而新产之后气血两亏又当别论。右脉虚大无力，左脉浮小而芤，于气血并补中少佐一二轻疏最稳。", "15852": "素属气血两亏，经行腹痛气虚血少可知。今停经两月余，忽尔经行，腹痛腰疼，数日来犹未停止。虽因虚而不能固，亦关滞而不能舒，此所以痛而兼淋漓也。脉左虚涩，右则细弱，痛在脐下，冲脉为病。先治其标，俾经止之后再为治本。", "15853": "肝肾阴亏，内挟痰火而上升巅顶，以致脑痛丧明。昨又发厥啮唇，朝轻暮重，脉象弦滑，两尺虚数，惟左尤甚。病经年余，虚痰挟火，匪朝伊夕。法宜壮水滋肝，佐以降火豁痰，冀其厥止再酌。", "15854": "三四年来，背心酸疼无时，每发必著人扑背、摸鼻则酸疼稍缓。左腹有块，不时腹痛，痛甚则厥。每朝吐痰，痰如破絮。土医治疗，毫无奏绩。家居横塘，买舟就治于余。余细审病情，兼察色脉。每发必起于背俞，三椎酸疼而波及于鼻。夫三椎乃肺之穴，而肺窍又开于鼻，故疼则俱疼，酸则俱酸，前后相应也。其所以如斯者，实风痰痹于肺穴也。更兼饮冷伤脾，脾土壅而生痰，故每朝必吐痰如败絮之状，或吐青色稠痰。此脾肺虚而木来侮土、乘金，是以或受寒，或冒风，或停食饮冷，亦必如前而发。病经四载，屡受肝木侵欺，然肝木过旺，肝亦自伤，所以块起左腹，痛剧发厥，是脾肺而又兼乎肝也久矣。迩来常厥，内风挟痰，此右寸关之所以虚滑，左关之所以弦数者，又显有明征耶。为今之计，急则治标，扶脾和肝兼祛风痰，少佐引经之法为亟亟也。俟其少安，再为治本可耳。", "15855": "九龄幼女，沉疴积岁，非不终朝医治，而治之者概作湿热、湿痰，或作肝气、肝风。如此妄治，无怪乎病日加深，而愈发愈勤也。皆缘审证不明，而又未能尽切脉之巧，是以终无成功也。予于斯症，于四诊中详谛之。知其年幼之女，症非七情所关，唯于六气、内伤中合参之，定为风、痰、痹、肺四字求治，加以调中疏气为活法。先治其标，药投四剂果然中的，再数剂而收全功矣。四载沉疴，数日而霍然全瘳。瞻君谓予曰：「诚神方也，令人口张舌缩。」予曰：「非神也，理也。岂有理明法备，而药不应者乎？」", "15856": "自七月初旬经水行后，至今五月未通。夜来咳嗽寒热，每至天明必大汗出后热渐退，迄今月余。营卫两虚，脉右浮小，左虚弦。法宜养阴和卫，速退寒热，冀其经转，庶免成怯。", "15857": "寒热起自丁卯孟冬，月余方止。已后渐自咳嗽口干，痰中见红，食饮渐减，肌体日瘦，经停五月。交春咳嗽日增，气急喉鸣，浓痰甚伙，日约二三盂。午后欲睡，夜来盗汗，腿酸腰疼，白带淋漓。日进二地、阿胶、归、芍、知、芩及二冬、参、苓辈，屡进滋阴之剂，少佐益气之法，浓痰益增，食饮益减，几乎成怯。于戊辰季春之十日始告治于余，余细审病情，合参色脉，形羸气喘，咳嗽声哑，食饮维艰，面色痿黄。右寸关细小兼滑，左寸关弦涩而劲，两尺虚浮小数。知其五脏皆亏，惟脾为最。盖土虚不能生金而肺气弱，金虚不能生水而肾水亏，水亏不能滋肝木而相火炎上烁金，以致咳喘交加，食饮下咽尽变浓痰，肌体骨立，经事不行，而更加之以嘈杂、怔忡、痰红、盗汗又关心液之不足，由肝而波及其心，此予之所谓五脏皆亏也为此。其所以尤重于土者，何也？以土为万物之母，胃为水谷之海、六腑之大源也，坤土一虚，诸证蜂起矣。为今之计，亟宜扶土保金，佐以清燥宁嗽。冀其食增咳缓、浓痰日减，渐次加入养心、滋肝、补肾、调经之品。至于其中标本后先、缓急、轻重之法，又在临时辨脉审证而权衡之，亦无能预料其必然也。", "15858": "又，病起五月，医更数手，百无一效。得予扶土保金、益气养阴，而更加以壮水滋木之法，药进三十剂，病除十有八九。再以前方出入，俾气血融和，脉络贯串，血海流通，冀其经事之转为最耳。", "15859": "痫症有五，治法不一。细审病情，每发时必先从左足筋惕而起，痰升气逆，耳有闻而目无见也，退则如故。诊其脉：左关弦数而滑，按之不足，知是肝病无疑。盖肝主筋而行属木，震为足而位居东，东方木郁生火，火郁生风，风火煽而痰升，痰火冲而气逆，急则治标不外乎此，而探厥本源定属肝虚。虚不受惊，惊则魂飞；虚不耐烦，烦则气越。不此之求，而重投疏风、破气、降火、消痰之剂，如虚虚何，而气火风痰亦不可尽置不问也。", "15860": "呕吐两月，无论粥饭，进胃即呕。或呕而带酸，或吐而挟痰。药投罔效，诸医束手，乾隆乙卯五月二十日乃延治于予。诊其脉，两关双弦，按之不足，知其木乘土位，犯胃则呕。呕吐久而胃气弥伤，肝木愈强，木强者肝亦自伤。且为之养胃和肝，俾其食入不出，再为之计。用六君子汤加炒川椒十粒煎，送左金丸一钱。两剂呕吐减半，再剂呕止。惟痰中仍兼酸意，此胃中之正气渐复，肝家之郁火未清。仍以六君子汤加姜汁炒生山栀子一钱五分，临服冲沉香汁三分。三剂，痰中之酸意无矣。原方去山栀、沉香，加归、芍、女贞子养胃补肝，治其本也。十剂而安，继用八珍汤加制香附作丸，调理两月全瘳。", "15861": "下指脉沉，气也。沉而兼数，火也。数而带滑，痰也。形如梅核，不随胃气为往来。状似桃胶，直阻咽关之出入。经停三月，或以为胎，似也。而有胎之脉，胡为乎沉细。余作梅核气治，而不用碍胎之品，即曰有胎亦何不可。", "15862": "原方再二剂，据述服后胸胃不响不嗳，惟响在脐腹之下。而咽中咽食之窒塞，呼吸之哽碍则俱不觉矣，即糕饼、汤饮下咽亦自松爽而无妨于事也。第所虑者，脐腹之下响声不辍，似有坠动欲溲之势，得毋小产之征欤。予曰大凡胎象三月脉必滑疾，何反沉细，前案中论矣。况所进之丸亦无关于胎也，前亦言之。而其所以脐腹响而坠，坠而欲溲者正为美事，何反虑其响坠而妄疑其胎也。渠虑之，吾取之。取其气与痰火皆由上而下达脐腹，脐腹乃下焦膀胱之地也，知其湿郁之火有从气化而出之象也。其所以犹未能出者，药力未足，功亏一篑耳。仍以前丸用荷蒂二钱煎汤送之，自然通泰矣。如言服之，果然小溲即出，出时热而且赤，约三四次后渐转清白而收全功矣。数月之病，四日而瘳，始终藉一丸之力。而前以橘皮汤下，后以荷蒂汤送，此中微妙可为知者道耳。", "15863": "间半月复来延诊，问其症，答曰：「内子经转，始悟非胎。今已七日，经水色淡，绵绵不止，少腹微疼，仍求良治。」予诊其脉，右寸关软小，按之不足；左三部缓涩无力。此气虚不能统摄耳，当以益气和肝则血自归经，无足虑焉。于是以四君子汤去茯苓，加黄耆、炮姜、炒黑当归、醋炙青皮、伏龙肝等，两剂经止、痛平。", "15864": "左关脉弦数而虚，右寸关不任重按，知其病起于肝而波及脾肺也。盖肝火素郁，发则冲肺烁金；木气过强，甚则侮脾克土。土虚不能生金而肺弱，金虚不能平木而肝强。且肝邪过旺，肝亦自伤。不此之求，而专于降火消痰、疏风破气，不过稍缓须臾，而究非善后之策也。为之扶土以生金，金气足而木有所畏；兼之养肝以疏木，木气调而火不能升；由此而厥逆渐停，癫痫幸免。岂谓沉疴积岁，无计可施耶。虽然气郁之病女子为多，其所以散虑逍遥不尽归功于用药者。", "15865": "头为阳之首，发乃血之余。头皮何以痒，血以热而风生也。发根何以腐，血以热而湿蒸也。血何以热，血虚故也。血虚何以发脱，或因新沐当风，或因头汗湿郁，邪气袭虚，而真阴不能固济也。再请验之于脉，左关弦浮卜肝风之上扰，右关濡数知脾湿之上蒸，左尺沉涩而虚益见肾阴之不能上达。况经事不调，后期而至，其为血虚也何疑。", "15866": "年逾二旬，经水应期。于去冬十月间患湿毒，手足腿股溃烂成疮，大者如盆，小者如杯，痒甚则抓，抓则水出。他医皆指为疯瘫症，有用麻黄、羌、防而兼凉血者，有以芩、连、生地、银花、羚羊角辈而清火解毒者，俱不应手。更奇者，有粗工用银花、苦参、大风子各五钱煎服。据云服之内觉热极难忍，几乎丧命。今始少平，特买舟求救。予闻之深为悲痛，不思大风子性热燥痰伤血，惟外治疮癣疥癞，岂可用此内服。即一钱五分尚不敢轻投，况五钱乎！以人命当儿戏，庸工之作孽，罪莫可逭也。予从症脉合参，知其脾家之湿毒，肝经之郁火。外用解毒生肌、收水定痒之法，内以燥湿扶脾、凉血清火之功，何患其不瘳也。", "15867": "服前方五剂并外搽药，手足腿股之溃烂已十去其八九。两日来经行过多，未期先至，觉头眩身疼，左脉虚数。以四物汤加女贞子、生香附、陈皮煎服，外仍以前膏搽之。服三剂，经止疮愈。", "15868": "下体不洁，阴门生疮。据述疮口长约一寸半，深约半寸。起自正月八日，医更数手，疮口愈深且肿，痛无宁刻，迄今四十余日。适岭南王子荐余诊治，斯时正值经水临期，脉虽弦数，未便过投寒凉，遂以四物汤加金银花、甘草、人中黄、贝母、青皮煎服。", "15869": "产后三月，经水未行，体虚腹膨，两足浮肿，便溏食减，中满之征也，病属肝脾。《易》云「震为足」，足属东方木也。固宜扶脾，亦须养肝，斯为尽善。他如头眩、口干、腹疼、痰多、内热，无非肝阴之不足，脾阳之不运也。况左脉虚弦，右脉软小乏力，更显有明征欤。", "15870": "自乡往署，舟中感冒风暑，寒热头疼。泊舟虎丘，邀予诊治。案云：证脉合参，暑风外袭，食饮中停，乍寒乍热，似疟而阴阳未分也，疏解为宜。", "15871": "疟发间日，寒热交作，舌苔白腻，不饥纳少，脉左弦右滑。邪伏少阳、阳明，宜从和解治。", "15872": "每食饮入胃，少停即呕吐。病经半月，进药无效，邀余诊治。其脉右关沉滑，左关小弦。胃不和，肝不疏，此呕吐之所由来也，以代赭旋覆汤加味治之。（呕家不喜甘，原方去甘草、大枣，以干姜易生姜，而加山栀、青皮也。少佐盐花亦止呕，咸降之意耳。）", "15873": "身微热，头顶痛，无汗，不欲食，脉右浮缓。此连日阴雨，地土卑湿，久坐针工，湿气内侵。况值长夏，更非无因，宜平胃散损益之。", "15874": "体质素健，三日前头疼微热，服疏解药即停。后渐腹痛欲解，解下纯是白冻，日夜十余行。服温中消导之剂，仍然腹痛，里急后重，一昼夜约廿余行。食饮稍减，舌苔腻白，脉右沉紧。寒积中停，温通为宜。", "15875": "寒积阻于肠胃，自应温通，故以大黄佐附、姜而温通之，服后寒积顿减。次日大黄减用五分，服后积反增如初，脉仍沉紧，知其大黄减半而病复，寒积犹存，因用附子理中汤加酒洗生大黄，佐疏运之法。服后寒积始尽而无余，一剂而霍然矣。斯时倘畏其虚而不敢推荡，则积垢终难尽除，自是大黄之力也，且非酒洗之生大黄亦不能若斯之速奏功也。然大黄之用，非姜、附佐之，则寒积必不能除。设重用姜、附、轻佐大黄，则积垢亦必不能尽彻。制方之妙，妙在大黄之重于姜、附，姜、附之轻于大黄也。其所以然者，缘肠胃暴受新寒之积垢，非锢冷之积滞久留肠胃者可较也。是以用方之意与叔微之温脾汤，又自觉其同而不同矣，亦各有取意存焉。", "15876": "平素经行愆期三日，未至必先胀痛，痛甚经行，血中兼块。左关尺虚濡，右寸虚软，关脉沉小。自是气血两虚，理宜益气养营为主，而中间佐以调血通经之法亦不可少。方用八珍汤加制香附、女贞子、元胡索、茺蔚子、广木香，炼白蜜为丸（桐子大）。每服五钱，清晨滚水送下。服两月余，经行如期，腹竟不痛，血块亦减，颇为合宜。", "15877": "由忿怒伤肝渐发寒热而起，服疏解药寒热究未尽彻，食减口干。又以疏肝和胃法似觉稍安，忽夜间腹中大痛，上吐下泻，痛甚头汗如雨。随用藿香正气散出入之，外用香附、皂角、姜、葱煎汤熨之，似缓。而少顷又大痛、大吐、大泻，如此一夜。次早以汤饮下咽，顷之即呕。因用黄连汤治之，下咽未几，呕、痛立至，于是以旋覆代赭石汤煎服，呕吐始平，而痛势仍未一减，非但不减而反增腹胀脐突，宛如小锅覆于大腹之上，痛缓渐平，痛剧即高起。得汤仍呕，惟泻渐停，自觉痛甚欲绝。因延同事老医陆君诊视，方用金匮肾气丸，每服三钱，开水送下。服后痛势渐减，腹胀脐突之势亦缓。次早仍服之，而痛势又甚。午后仍然腹胀脐突，且呕青黄水。复延诊治，仍以前丸，惟用水泛者三钱服之，仍然大痛，脐腹胀突，头汗如雨，奄奄一息。至更余时，予默坐静候，索想久之。面青少神，其脉左关（肝部）沉弦小数，原于忿怒伤肝，气结火郁无疑。假外因而发，故初起似寒似热、似疟非疟，从乙木而波及甲木，表里并至。甚至肝木横冲直撞，木乘土位，以致腹胀脐突，大痛而吐泻并作也。色脉谛详，深知脾土之受困于肝也匪浅。陆先生所定肾气丸似属中窾，故初进小效，而再服则不应矣。盖肾气丸乃肝脾肾三经之药也，虽有桂、附而究不能专主于脾也。谛思良久，时已三鼓，必得以和中之法为最当。曾记先大人曰：「凡上下不和者，当击其中而首尾皆应也。」旨哉斯言！于是以理中汤合黄连汤，少佐柴胡。煎好，徐徐服。服后未几即渐睡著，时已天明，痛阵渐缓。至辰初，仍然一呕，尽是酸黄水，觉口齿酸软。虽呕未泻而痛阵已缓，兼之泻停，自是药之对症也。", "15878": "素有肝气，去冬偶发。今交春令，不时常发。二月间，痛甚气逆，两胁块攻。腹胀必得以滚水灌之渐引其呕，呕出新谷，腹中稍觉平和。著人揉摩腹胁，始觉块平腹软。土医作肝气治，以槟、沉、枳、朴辈疏气，间有用旋覆花、代赭石加诸破气之品，服之亦间或奏效者。第不日仍然大发如前，有时新谷未入即呕出旧谷觉酸，医用左金丸加归、芍、金铃子、石决明，佐降气法。延至三月初旬，痛势更甚，以至头汗如雨，四肢俱冷，仍以滚水灌之引其自呕，一呕稍宽，加以揉腹，人事渐苏，神识渐安。日来食饮维艰，大腹有膨胀之势，两颧浮肿，病象沉重，始求治于余。其脉右关细软无力，左关弦细按之不足。病由痛起，痛甚伤肝，木来乘土，脾胃已亏。痛极引呕，呕时似快，而脾胃则益受其累矣，以致不饥纳少，痛发无时，头汗淋漓，四肢厥冷，土为木贼，乃极险极危之候也，幸胃气未绝，还图一线。", "15879": "至半月后买舟就诊，据述服前方两剂诸恙向安，停药有日，痛症又发，较前稍缓。证脉合参，究属脾阳不运，肝木乘之；肝气过旺，肝亦自伤。为之扶脾温中，兼之养肝舒木，加意调治，自尔平可。", "15880": "素体肥胖，贪凉恶热，喜冷饮，向有痔症，此脾虚挟湿，肝虚血少。夜热口干，经行腹痛，腰腿酸疼，四肢虚浮，腹块有年，小溲短赤，种种见证，皆肝脾为患。况右脉虚小，左脉虚数，又显有明征耶，盍早图之。", "15881": "胎怀三月，据述以伤胎药一服，当晚即下恶血甚多，两日后血渐少，气逆上冲，恶心头眩。延余诊视，其脉虚数不静，烦躁微热，气从下而逆上，已属险途，再乡僻之地又不能避风节食，更兼所进下胎之丸如此效速，必有毒药，余气未清，均未可知。合色脉而谛详，气血两伤，恶血未尽，务宜气营两固，佐以温疏为最，否则恐其郁冒痉厥之虞。（壬申三月二十四日）", "15882": "素体劳役，恶热贪凉，微冒风邪，阴虚邪乘，夜间身热，骨节疼痛，食少体倦，连发两日。诊其脉，浮而缓，按之小数。知其邪入于阴，用后方一剂，半夜汗出身凉，骨节疼痛等症俱平矣。", "15883": "牙龈肿痛，内如针刺，更兼咽疼口干，经水未期，脉象浮小，治在轻清。", "15884": "病由内热咳嗽而起，痰中渐带红丝，夜来寒热，不饥纳少，经停四月。医更数手，肌体日瘦，腹左块攻，病势日增，买舟就治于余。诊其脉，右部数急，左部弦紧。知其肝阴不充，血海无潮；胃阳久弱，贲门纳少。色脉合参，虚怯之征已露先声矣。且议养阴退热之法，俾寒热退，咳嗽缓，再为之计。", "15885": "又，初八日方：药投数剂，诸恙渐平。但脉右之数虽缓，而左部之弦劲未平。总是气血未旺，八脉未和，故中宫亦时有微疼之象也。加意图维，俾阴阳和而经事转斯可矣。", "15886": "吴豫得女调经丸方：色脉合参，年将十八，经停五月。胃阳弱而贲门少纳，肝阴涸而血海无潮；寒热交作，咳呛痰红，腹块攻痛。脉右数急，左则弦劲，干血之征已露先机矣。念其路途遥远，望治情殷，不得已而用乙癸同源之治，侑以退热生津之法，不数剂而寒热止矣。再以补肺养肝兼益脾肾之剂，块平咳减。又以扶土生金、滋水养木之法，食饮渐增，气血渐和。诸证向安，治法可征。继以丸剂，以为行经之计。据述每多趱前，一月两至，似属血热。而脉症并参，究关中气之大虚。盖气为阳血为阴，《经》云「阳生则阴长」也。自宜益气为争先之著，少佐和血通经之法亦不可缺也。", "15887": "妊娠三月，痢下红白，昼夜百余度，点滴后重，知饥纳少。痢起数日，年三十五岁。医用痢门套药治，甘、苦、寒凉备尝之矣，奄奄一息。适渠戚程君荐予诊治，其脉沉数而滑，重按无力。知其正虚邪实，攻补两难，盖攻之恐其伤胎，补之又恐邪毒不去。索想久之，幸胃气犹存一线生机，尚可图救。不得已而用攻补兼施之法，取其辅正驱邪，保母留胎，未始非一举两得之法也。《经》云：「有故无殒，亦无殒也」正此谓耳。", "15888": "十九日：脉浮小而不沉数，按之少有力矣。日进粥六七碗，粪带焦黄色，早晚一二次。当以四君子汤加黄芩、芡实、广木香，仍用荷叶托煎，两剂全安。继以香砂六君子汤调理，五剂而愈。", "15889": "腹痛且呕，脉沉而细，气食交阻，痛甚防厥。", "15890": "产后三月，咳呛延绵，气逆痰稠，日间畏寒。医作冬温，误投疏表不应。更医用小柴胡汤加鲜生地辈，致病日增，始问治于余。诊其脉，右部虚小，左部虚濡。乃气血两虚，表气不固，易于畏寒咳呛。当益其气，调其营卫，兼以降气化痰，痰自除而气自不逆。服四剂，咳呛畏寒可自平矣，如数服之而瘳。", "15891": "病愈停药二十有五日，行经后干咳无痰，脉象浮数，按之不足。肺金之虚火不宁，治宜清润，议喻西昌清燥救肺汤损益之。（四月初八日）", "15892": "咳嗽有年，起于产后，举发无时。近感暑湿之邪，咳嗽兼呕，气逆痰稠，骨节疼烦，脉象浮小，咳甚防血。（七月十四日）", "15893": "寒热一日，缘经行而寒热止。日来遍体不疏，食饮无味，口吐清水，舌腻欲呕，脉按之则数。其为邪之蕴于内者无疑，治以和解，使其微汗润泽，邪自退矣。", "15894": "色脉合参，见证多端。冲为血海，任主胞胎，二经俱虚，无怪乎经前之趱前，而生育之维艰也。时而肝火内动，不耐烦劳。一眩晕而眼底模糊，恍如倦鸟翻云之后。一恼怒而胸中跳跃，宛似游鱼脱水之初。十指觉麻，腰背痛而身如刺，百脉兼疼，肢节酸而筋似抽。他如口干唇燥，肌肤索泽。或有时而外寒，或有时而内热。种种情事皆卫阳虚，而营阴不足也，为之固表以扶阳，和里以益阴，则气血充而阴平阳秘矣，何必枝枝节节而求之。", "15895": "又，脉象沉紧渐减，仍宜疏理肝脾，痛自平矣。", "15896": "气郁痰凝，挟火而升，谵语妄言，不时歌泣，脉数而虚，癫也，非狂。", "15897": "怀胎七月，因身热泄泻，胎动小产。素体质弱，产后恶露无几。虽不腹痛，自觉膨胀，不无瘀阻。微热口干，便泄未已，头汗体倦，骨节疼烦，求救于予。诊其脉，左关弦紧，右脉浮数如绵，知其恶血停留，虚阳外越。色脉谛详，神倦汗多便泄，症属险极，亟宜益气养阴，兼除恶露，以防汗脱。四月十五日方：", "15898": "又，十七日诊：服昨方，身仍大热不解，便泄数十次不止，口干喜饮滚热汤，气急神倦，腹膨鼻煽，恶露全无，脉右数大而软，左脉弦紧而数，彻夜不安。主家知其危笃，业已治凶具矣，勉求立方。余见其头汗渐减，恶露未行，合之色脉，尚有一线生机。方用扶阳益阴以退热、温中、逐瘀、敛阴、固肠，俾恶露行而便泄止。若能应手，尚可无虞。", "15899": "予立方后，因病危笃，又延他医，亦云脉急促，危在顷刻。方用荆芥、黑豆皮、琥珀、归、芍、丹、苓、炮姜辈，主人见渠方与予方大不同，戚友议论纷纷，举家彷徨无措。福堂之岳母素信观音大士，将余方卜之神灵，随示大吉之签始敢煎服。先将稀粥带热照数调和赤石脂、禹余粮与服，服后即觉便泄大减。随将煎剂与服，服未两时觉神识不定，病者又欲饮滚烫之粥，仍用二末调和，服一碗之后渐渐睡著，微微之汗。约睡三时，至酉时方醒，醒后壮热顿退，神识安静，便泄亦止。至夜半恶露渐下，色红且多。从此腹亦不膨，饮粥两碗，语言清爽，面色之浮光亦退，诸恙悉安，惟觉其疲倦乏力，何足虑焉。设两日间，病家狐疑，误投他剂，其不立毙者几希。自此守服原方三剂，粥内二末自此而止。日来恶露将停，食饮渐增。后因下床劳力，复又壮热、便泄，饮入即泻，福堂乔梓又甚惶惑。予曰：「此气虚劳复，固病后常事。」补中益气汤加赤石脂、禹余粮煎服，三剂而霍然矣。继以归脾、八珍等剂，调理收功。", "15900": "患三阴疟，每发在戌初。先寒后热，热甚于寒，口渴喜饮。舌苔白腻，脉左弦右滑。迄今半月，已发五次。小柴胡汤加减。", "15901": "身热头疼，恶心不饥，兼之泄泻日数行。舌苔白，脉沉小，左弦细。此夏感暑湿，热交秋而发，治宜解表疏里。", "15902": "胎怀七月，五月下浣因时热小产。产后热势更甚，头疼胸闷，舌苔糙腻，口渴喜饮，腹中微痛，恶露全无，脉虚大而弦。邪乘虚入，若因壮热而误进寒凉，危在反掌。当以生化汤加味，俾恶露行而热渐退，庶有生机。", "15903": "案云：咳嗽起自去秋，干咳无痰，气逆喉痒，午后先寒后热，口舌干燥无津，不饥食少。阴虚内热，阳虚外寒，气血两亏，脉象细小无力。还防涉虚损之门，亟宜补肺生津，俾咳缓思食，庶可图维，幸勿视为小恙而懈怠之。（正月三十日）", "15904": "进两剂，咳渐有痰，口舌有津，夜能睡，寒热、盗汗俱减，药颇相宜，惟脉仍如前耳。", "15905": "素有鼻衄，不时举发。经水应期，常多白带。迩来因咳嗽而致鼻衄者居多，亦有时缘喷嚏而来者亦不少。夫鼻乃肺窍，咳嗽、喷嚏皆属于肺。肺为五脏之华盖而属金，金虚木旺，木挟火势而乘金，金叩则鸣，此咳嗽、喷嚏之所由来耶。甚至气逆火升，此又鼻衄直注而出也。再验之脉，右寸虚数，左脉虚弦，又显有明征耶。先治其衄，再商善后。（八月二十四日）", "15906": "平常经水约廿余日即至，自去年出嫁之后经水愈觉趱前，或半月或数日一至。今于前月二十九日畏寒发热，骨节酸疼，咳嗽不已。延邻医治，用轻疏不应，随用玉竹、白薇、丹皮、黄芩、紫菀、赤苓、旋覆花等治咳，而咳转剧。始问治于余，诊其脉右寸浮紧，寒邪客肺。身热六日，咳呛不已，舌苔腻白，经水适来，寒郁营分。亟宜疏肺以免变迁，拟麻黄汤加味，兼治经水。", "15907": "起自六月十四日，汤水入胃即呕，大腹阵痛难忍，甚至于手指厥冷，二便不通，胸闷不饥，邀余诊治。细审病情，昨晚忽然腹痛，痛甚即呕，呕不自禁，六脉沉小，气郁食阻，舌中淡黄，苔糙。痛剧防厥，素体质弱，恐难胜任。议和中法，佐以定痛止呕为最。", "15908": "产后未满百日，始而经水淋漓，继而白带绵绵。至二月望前，呕而腹痛，时作时止。医者皆作肝气治，概用香燥破气疏肝之剂，呕痛愈甚。以致汤药入胃即呕，呕之不止，甚至黑汁从肠中泛出，黄浆自胃底翻来。愈呕愈痛，痛甚则胸腹气胀，两臂直竖，有角弓反张之势。举家彷徨，诸医束手，始求治于余。予谛审病情，兼察色脉。脉之右关虚而滞，左关细而弦，一呕而痛剧难忍。前症毕集，危在顷刻，惟嘱家人备办衣物后事，且向予哭告求救，情惨极矣。予索想良久，呕痛起于产后，脾土早已先亏，更兼贪食啖荤，野味不禁，以致脾胃愈伤，中宫阻塞，痰凝气壅，以故呕痛无已。必须急则治标，先以止呕为最，使呕止而痛可渐平。医者不究呕痛起于产后，误作肝气治，反以破气止痛为先，所以终无成功而呕愈剧也。予于斯而深得病情，莫妙于先理脾胃立止其呕。若不此之求，再呕必然汗脱。吾何忍立视其毙哉，于是以代赭旋覆汤略为更变，立救其呕以尽婆心耳。", "15909": "初五日：清晨腹中又忽痛忽止，至灯后又大便结粪成条者二三断，如此腹中松爽，毫不痛矣。戌初予至，病者自述今自早至晚饮粥四碗矣，安妥如常。惟嫌其胁背刺痛不在肌肤，自觉其经络中收束刺痛，此亦关产后失调，脾胃虚而气血不和，不能营养贯注，脉络滞涩之故耳。方用西党参、归身、木瓜、杜仲、续断、山药、陈皮、广木香等，五剂而前症悉除。", "15910": "经水延绵，血去过多，业已八日，犹未停止。脉右虚小，左脉虚大，阴亏阳弱。正值大暑，血下成块，形如鱼肠，腥秽不堪。肝脾两伤，亟宜扶土滋木，引血归经。俾其速止，庶无他虞。", "15911": "又，复诊方：脉形如昨。", "15912": "忽身热头痛，胸闷咳呛，口干不喜冷饮，舌苔黏滞淡黄，脉俱沉细。时邪内伏，凛凛畏寒，四末清凉，入夜热盛，阴虚体质最虑邪陷，是非轻候。议和解法，以冀周体微汗为妥。", "15913": "进一剂，汗出热退，头痛止，肢末温，脉之沉细渐起。唯舌胎如前，口干无味，便结不爽，小溲短少。邪退胃未和，清胃调中自平。", "15914": "寒热滞下，色兼红白，表里俱病，昼夜无度，腹痛点滴，脉象沉滞。乃暑湿之邪感于盛夏，发于秋后，又为寒凝食积，郁而成痢。不饥纳少，防有噤口之虞。", "15915": "于丙子九月初旬得伏邪症，身热，舌苔白，有汗，右胁刺痛难忍，咳嗽胸闷。医以牛蒡、杏仁、枳壳、丝瓜络等以泄肺热，不应。两日后更医，医用羚羊角、生地、丹皮、青蒿、地骨皮辈以泄肝热，不应。又用生地、豆豉同捣作黑膏法，再佐诸寒凉，服后愈觉身热，右胁益加刺痛，昼缓夜甚，有时昏语，耳聋，口渴不喜冷饮，头汗黏手。举家彷徨，乃延余治。余至医已立方于前，用鲜生地、羚羊角、茅根、黄连，一派寒凉尤甚于前，且生地用一两五钱。余诊其脉，右寸关滑数而大，按之无力，知其痰火非实，因立阻前方断不可用。盖现在口渴不喜饮冷，舌胎腻白，情已大露。再观其身热、咳呛、气逆、痰稠，明明是客邪内蕴，湿痰中停。不此之求而概以寒凉遏抑，邪无从出，以致耳聋、昏语、神识模糊，变症蜂起矣。倘再误治，定然昏厥痰升而脱矣。为此时计，亟宜清解肺胃之邪，兼以和中退热，为紧要关头。（重阳日方列下）", "15916": "又，初十日诊：身热已退，而神识尚似清非清，汗出黏手，咳频痰稠，气逆耳聋，脉形如昨。再以肺胃并调，俾清肃之令下降，则胃中痰火湿浊亦可从斯而除矣。", "15917": "病由感冒而起，邪退正虚，日进滋补，胃土不醒。是以不饥纳少，厌厌不乐，体倦神怯，怵惕不寐，心营虚而胃土之精衰。诊其脉，左寸虚涩，右关耎小无神。视其舌，舌形胖大，胎白如雪花片散布于舌上者，乃胃气败也，难以许治，拟益胃养营法以尽人工。", "15918": "似寒似热，头痛且重，呕恶痰涎，小溲赤痛，腹膨时疼，经水匝月未行，骨节酸疼，脉象沉小，病起数日，食饮不贪。乃风寒内蕴，兼之肝胃不和，法宜疏通，俾经行，庶乎渐安。（四月初六日）", "15919": "年十六岁，天癸未通，素体质薄。向来便溏，日二三次，面色痿黄。今夏患疟，寒热交作，已后似寒似热，蔓延日久，咳嗽有汗，不饥纳少，大便愈溏，较前倍增，气怯神弱，肌体羸瘦，药投罔效，渐成虚劳。于戊寅九月十一日始问治于余，余诊脉辨色，面无神彩，脉之右寸微若秋毫，关则虚小，尺软如绵，左脉弦细乏力。知其肺脾大亏，而肾阳不足以生脾土，则肺气愈弱。心肝久虚，而肾阴不足以滋肝木，则心血少充。无怪乎咳嗽寒热，食减便泄，而致天癸未通也。阴阳两亏，虚劳之征也，难以许治。怜其幼年丧母，望治情殷，谛思良久。肺脉虽如秋毫之微，而他脉未败。面色虽无神采，而夜间尚能安睡。寒热虽有，而汗出尚不淋漓。平素大便溏薄，今则倍增水泻，乃肠中之湿邪下注，究非脾阳之下降可比也。再舌中腻黄腐烂，四边淡白，食不知味，口干欲饮，此又胃中之湿阻不化，以致清浊不分，而升降不灵也。是以上则耳聋，下则便泄。种种情事，虚中挟滞。滞者壅也，郁也。知其意者，可以神明变化之，因立方以救之。方用补肺和中，先调肺胃，少佐养阴退热之品，疏补兼施。服后咳缓热减，舌胎渐退，从此增损，取不润不燥之法，而便泄渐退，如平时之溏，食饮日增。", "15920": "又，十月初一日诊：气血稍和，脾肺渐调，右寸脉指下按之亦稍有力矣。其右尺之软如绵者渐转濡小，而浮分按之似无也，是属佳兆。再拟气血并补、温胃固肠之法。俾脉络流通，阴阳交和，预为行经之计，且素有之便溏亦可从斯而止矣。", "15921": "咳嗽旧恙，交冬频发。外寒内热，卫阳虚而营阴不足。经水淡少，脉象细而小数。冬至在即，痰红已见，加意图维。", "15922": "经断身热，血室空虚，时邪内陷。医用犀角地黄汤佐芩、连辈一派寒凉之剂，数日来身热愈增，神识不清，耳聋呓语，变症蜂起。戊寅七月十九日，门人金书山荐治于予。诊其脉，右部软大，按之无力；左关弦细，尺脉细小难寻。口虽干而不喜冷饮，身虽热而不烦躁，齿唇焦燥，舌胎灰黑，拊之有津。就证脉而详谛，寒凉难投，岂知医者今又定犀角地黄汤合竹叶石膏汤，群药不计。斯时已更余，尚有一医未至。余与主人云：「昨既进凉剂，热反增，证反重，未敢再投，予立一方以俟明眼裁正。」同书山议用大生地、生鳖甲、麦冬、丹皮、知母、石斛、青皮、归尾、桃仁泥、鲜稻根须等，留方而别。至二十四日书山会予，知前方占卜未服，仍延前二医及书山诊治。延书山者，缘其家之伙与书同乡契友也，虽然而其家议论纷纷，不能专主于书山，故终无济于事也。连日医以生地、丹皮辈合利小便法，二三日不应。复又用犀角、生地等合蝉衣、板蓝根、牛蒡子以化斑，三日来热仍不退，神识愈昏，食饮不贪，日泻稀粪二三次。又用清燥救肺法，而热仍如前，病势甚笃。复属书山求治于余，往视之，热已十三日之久，而一毫未减，食饮不进，午后想食西瓜，约饮半杯而稀粪直溜，此等情境岂是退病之象也。身热干燥，神识乍明乍昧，语言似清非清，舌色红润，中心灰黑。病由经水适断而起，血室空虚，邪热内陷。徒事清热，热非实热；徒以散邪，而邪已内陷于血室空虚之所，徒清、徒散均无益焉。是以《内经》有无犯胃气及上二焦之论，仲景《少阳条篇》有适断空虚邪陷一说，明指少阳胆腑，亦有三禁，与经文暗相符欤，各有深意。神明变通，全藉心领意会，始能得其妙旨，岂泛泛医流辈所能深悉其意者也。况此等症最易变迁，如前之脉则右大左小，今则两关浮弦、尺脉小数而按之无力，又非前比。变端不一，岂可同日而语哉。今病已危险，若再延误，措手不及矣。为此时计，宗启玄子育阴存津以退内陷之热，合之仲圣《少阳篇》血海空虚邪陷胆腑之小柴胡合而成方，以冀转机。不此之求，恐肝风一动，劲厥随之，又当如之何耶。案定方成，适前医至，即于方中加其茯神，甚属合宜。方列于下，七月二十四日定：", "15923": "脉右虚左弦，肝脾两亏，湿热下注，两足肿痛，屈而不伸，紫斑成朵，证名湿脚气，古称壅疾者是也，宗东垣疏理肝脾，是为上策。", "15924": "产后失调，瘀血凝滞，结而成块，块偏于左，迄今三月。结块时痛，大如碗口，偶尔寒热，不时腰疼。疡科不明产后变端，误认小肠痈，妄投破血散气、通经导滞之药，以致块坚痛增，小溲不爽，食饮维艰，肌瘦神疲，脉象虚软，气血日亏，郁而不散。诛伐无辜，弄假成真，深可痛恨。如果小肠痈，当小溲数如淋，身皮甲错，腹痛异甚，按之濡如肿状，身无热，再验之于左尺脉独数，知小肠痈之脓已成也，宜以药内溃之，亦无庸刀针开之。今既无此形，无此脉，何可妄治。自予审之乃产后气血大亏，营卫失调，恶血阻络。理应调摄脾胃，和其气血。俾营卫流通，食饮渐增，庶几块消痛止矣。", "15925": "经水停阻，淋漓不绝，小腹块攻时疼。病经一月，口虽干，喜饮温，小溲少，赤带多，舌淡黄，脉象沉小，乃下焦之瘀滞未清耳。六月二十五日", "15926": "素有血崩，兼多内热，肝火易升，不时牙疼。种种见证似属肝火为患，而细按脉象，左关虚数，火非实火；右寸虚小，关脉虚软，知脾土之受累于肝也久矣。盖土虚不能生金而肺弱，金虚不能平木而肝强。然肝强者，肝亦自伤，故脉虽数而虚也。徒事平肝伐木，清火抑阴，皆非法也。当先清补肺胃，少佐养肝舒木之法，再为良图。", "15927": "又，复诊：病脉合参，理宜气营并补，第秋令初交，暑热未楚，药后颇效，仍宗前法。", "15928": "巅顶作痛，畏寒恶风，咳嗽呕恶，舌胎白腻。医者以为暑风闭于肺胃，用枇杷叶、川贝、橘红、豆豉、佩兰叶、大豆黄卷、桑叶、杏仁等。三四帖，呕、咳、畏寒减，而巅顶之痛仍然，反加内热不饥。予诊其脉浮小，乃风邪上受，兼之早出晚归又为露水所侵。因用轻解法，以散上部之风邪，庶乎渐安。", "15929": "素常内热，贪啖生冷，不时腹痛。今于七月十九日，身热无汗，头疼，大腹时痛时止，痛时如啮，口干舌绛。医用清疏药二三帖不应，又用小柴胡加连翘、青蒿辈，反加闭闷、壮热，仍无汗。早上热轻，午后甚，因延余诊。案云：身热头胀，干热无汗，腹中时痛时止。舌绛唇红，脉象浮数不弦。似疟非疟，乃风暑内蕴而兼蛔虫作痛也。宜以疏表和里，佐以祛虫，俾邪外达为最。（二十六日）", "15930": "进药后，今项背发出白㾦，少有汗，下半身无汗，微咳，胸闷齿疼，热势较昨减半，口干喜饮亦减，脉浮小数，邪未尽彻。", "15931": "产后两月，冒风头疼，感寒腹痛，滞下数次，脉软小兼浮，宜用清疏法。十一月廿三日", "15932": "经行腹痛，时值三冬，脉象沉迟，非温不通。", "15933": "六脉沉细，胸腹急痛如锥，呕吐肢冷，汗多且厥。寒凝食滞，气阻中宫，来势甚险，先以熨法，再投煎剂。", "15934": "食入则胀，胀甚则痛，脉右弱左弦。脾阳不运，肝木乘之，宜补坎中之阳，以生己土之不足。老年得此，防成虚臌。", "15935": "发热两月未退，脉虚而数，阴气亏而肝火内郁。前进四物汤去芍药，加鳖甲、地骨皮、青蒿子、丹皮、花粉、甘草、赤茯苓辈三帖，以养阴退热，据述热未已。体虚之人远路步行就诊，途中不无冒风，药难奏功，须择近便者调治最妥。议逍遥意，合养阴退热法治之。（三月初六日诊）", "15936": "未诊脉前，据云服初三方夜间热势更甚，甚至头眩眼花，欲饮冷卧凉方快。观其舌，舌绛无胎；诊其脉，虚而带数；明是阴虚而相火不静。阅予前方理当合宜，何服之而反热甚，因立案嘱其近便处就治，性急欲速，难与之言。再思之，既服药不合复来求治，又不得不尽心以图之，因仍用养阴法合逍遥散加减之。疏方毕，深嘱戒怒、饮酒，若能遵之，尚可图功。设二者不戒，难以许治。谈至此，而病者与来人鼓掌大笑曰：「名医也！君何见之神也。」追问之，则曰：「前自初三四两日进药后，夜热大减，十去其八。惟初五日服药后，复饮陈酒半斤而睡。是夜身热大甚，饮冷就凉，夜不安宁。至于气恼，常常有之。既蒙嘱戒甚切，特诉真情，仍望一救。」予始解疑，不然何药与病合而服之反不符也。因将原方之银柴胡改用小青皮与之。甚矣！医之难行也，设不叮咛再嘱，何能探其实情。柴胡之用，有可用可不用之道也，去此而增青皮以舒肝，未始非良策也。", "15937": "中脘作疼，起自去冬十二月，不拘食前食后、或早或晚，大率受凉则愈觉耳，喜饮温暖。至今春二月，胃中时刻隐隐作疼，食饮渐减，饥也不敢多食，食后胃中不疏即疼，连痛三二日，甚至牵引左胁。诊其脉右关软小不疏，幸左关肝木不弦，故无兼证。惟以调和脾胃，兼之温中运食为法，自尔痊可。（十一日诊）", "15938": "新产旬日，发热头疼，小腹觉痛，延余诊治。据述产后恶露甚少，于三四朝时腹痛甚急，忽下血两大块，当即痛缓血少。迄今十日，心一烦而汗出，火一升而头疼。发热腹痛，两耳常鸣，口干咽疼，喜多言语，舌绛光剥。右脉虚滞，左脉见芤。细审之，乃产后大血去多，营阴不足，肝火内郁，少有恶露未尽，气滞不疏。宜先舒肝和血，俾恶露清而相火降，再为之计。第须避风戒怒，庶免产后余波。", "15939": "服两剂，汗出渐减，头角不疼，口干耳鸣亦缓。惟夜睡时醒，咳平痰尚多。自早至晚可饮粥四五盏，知饥口淡，两足不温。脉右虚大无力，左三部虚小微数。气血两亏，虚火渐降，理应峻补，而胃气未旺，脾土未健，肝肾之阴虽虚，而滋补腻膈之药究嫌其骤。且以益气扶阳，佐以养心宁神之剂，再为善后之谋。", "15940": "又，十一日方：新产之后，气弱血亏，脉细无力，诸恙俱平。大便数日未解，而血海空虚、肠燥便结者，又未便擅用通幽之法使虚者益虚，必得益气以充之，养血以润之，佐以温肾以达之，便自通矣。", "15941": "新产十日，头疼身热，腹痛耳鸣，汗出无时，口干咽疼，咳呛痰稠。种种见端似属外因之象，而证脉合参究关气血两亏。予专作新产论治，随机应变，逐日平可，深中肯窾，此其所以收功之捷也欤。", "15942": "咳嗽吐血，起自上年，医治罔效，渐成虚怯症。脉右细耎无力，左脉寸涩，关脉弦数，尺脉濡小，知其素体阴亏阳弱。腹块攻痛，白淫绵绵，任脉为病。日来咳呛痰血，颧红口干，痰沫常吐，虚怯之征已露先声矣。色脉详审，自是相火上炎，水不养木，宜乎滋阴为最。而脾肺久虚者概以滋阴降火，又恐不利于脾。必得土旺金生，使木不侮金，金气充而肾水自旺。为今之计，亟宜扶脾保肺，佐以养肝，是为上策。（初七日方）", "15943": "又，十二日诊：进前药，咳呛渐缓。就色脉而详谛之，阴固亏也，阳亦虚矣。阳何以虚，由于气之不充。阴何以亏，由于火之上炎。是以喉干舌燥、咳呛痰红。至于腹块攻冲，肠鸣白带，虽关任脉，然亦未尝不关乎脾阳之不运耳。无怪乎右脉虚软，左脉弦细极也。且再调治肺胃，佐以养肝，斯为善矣。", "15944": "又，十六日方：始也咳血，继也骤吐。《经》云：「阳络伤则血上溢」，是肺气虚而胃土不充也，前案已详。《易》之《彖》曰：「大哉乾元，万物资始」；「至哉坤元，万物资生」。坤属于土，干属于金。未有气不充而血能固者，亦未有土不足而血能统者，此予之所重在肺胃者近是。证脉细审，行经趱前，刻在临经之际，骤然一吐，是属倒经之象也。不然何脉不见数急，而神识反安静也。议益气养胃，侑以疏之调之而运动之，庶乎可也。至于块之上攻，腹中雷引，白带绵绵而下，亦无非气不充而清阳不升也。一以贯之，不必枝枝节节而求之。", "15945": "又，二十一日诊：肠覃有年，缓图可消。若因块坚而速投峻厉之剂，恐反节外生枝。证脉合参，宗罗氏《宝鉴》方出入之，庶乎尽善。", "15946": "进四剂，痫病未发，自觉喉中痰少，体健食增，原方加天竹黄一钱五分。再四剂，痫病仍未发。渠家因药颇合，如前再服，仍不再发，精神更健，喉中痰声全无，口舌并不干燥，二便通利，知饥能纳，脾胃调和。复诊之，左脉之弦数者大减，惟右寸关反觉其滑而少力耳。当用二陈汤加焦冬术、柏子仁、归身、远志、沉香，煎送白金丸八分。服十五剂，痫病霍然全愈，天癸亦通，精神健旺，肌体未复。向予索调理方，予以归脾汤去木香，加熟半夏、制香附，用荷叶煎汤洒叠成丸，每服五钱，食后滚水送下。", "15947": "素有胃气作楚，近冒暑风，痛而兼呕，得汤则剧，手足麻，头小胀。舌胎腻白，有汗恶风，六脉沉小。议和中法，佐以辛苦。", "15948": "日晡寒热，得汗而解，头胀恶心，小腹膨急，溲便不爽。舌苔白腻，合之脉象似疟而阴阳未分也，素属阴虚挟痰。经行一月两至，兼之腰疼，内如针刺，遍身不疏。先以解暑却湿，少佐治本之法。（初四日方）", "15949": "又，初六日方：寒热、腰疼俱缓，而小腹尚急疼，大小便不爽，胸闷恶心，暑湿之邪未尽也。脉左弦细而数，防经水骤至。拟和中法，佐以舒之运之。", "15950": "服后未寒，少有热象即退；仍然呕恶，口干舌腻。经水未停，少腹仍疼，血块仍有，腰胯酸软，左脉小数兼弦，右脉小滑。胃不和而少阳之邪未彻也，还防寒热。", "15951": "案云：头疼责之太阳，齿痛责之阳明。左右脉俱沉细小弦，邪由表达里。仲圣云：「身热头疼有汗而热不彻者，此营弱卫强，阳邪内陷。」况在经断后得之，其为营虚邪陷更无疑矣。兼之舌苔白腻、胸闷欲呕、二目羞明，邪闭未能出表，岂是小恙。议调营和卫，佐以豁痰解郁，以冀热退汗止，庶几无虞。", "15952": "照法煎服，据述至三更时，汗出遍身至膝，惟小腿下未到。当即热退，头疼齿痛顿减。少顷饮稀粥一盏，渐睡至天明后而醒，醒后安妥，非昨之烦躁可比。至辰刻又少有热象，却不烦躁。大便稀粪一二次，胸胁尚有不舒之状，时欲嗳气则松。小溲甚少，出时甚热。时有转失气，据述极臭。究属阳明宿垢未清，余邪未尽。吐痰盈盂，右关脉稍起，左脉弦细如前。正虚挟滞，痰湿中阻，先宜舒中却湿，再为之计。十七日方：", "15953": "晚诊：据述午前进前方，服后安妥。至戌初，大便结粪一次。至更时，陡然手足厥冷，上至腕，下至足跗，谵语胡言，已后默默不语。予至诊脉，脉左如丝，右脉稍起。气凝痰厥，用竹沥、姜汁、陈皮、半夏、沉香汁冲服，服后顷之厥回。", "15954": "又，二十日诊：右脉虚耎，左寸细涩，关脉弦数，尺则濡小。气营两亏，水不滋木，肝火易升，心烦乱语，舌苔中央腻滞。转失气仍时下，宿垢犹未尽也。证属虚实相兼，议益气养水，佐以清降，庶几两擅其长矣。", "15955": "案云：产后停经，迄今两载。日晡潮热，脉象浮大，按之不足，两尺沉迟，左关弦细。肝阴涸而血海无潮，胃阳衰而贲门少纳。缠绵有年，将涉虚损之门矣，盍早图之。", "15956": "又，复诊方：左腹向有一块，据述大如杯口。证脉合参，宜以调经为主，俾气血流通，块可从斯而消矣。", "15957": "又，复诊方：气血并调，八脉融和，经事可行。", "15958": "细审病情，玉门生菌，形如小茄。起于产后，迄今半载，苦难鸣状。非不终朝疗治，而数手频更，究无一效。诊其脉，右脉虚细耎小；左关沉弦小数，惟寸则浮小空虚。知其产前受惊，产后肝郁。郁火不舒，致成斯疾。无怪乎物一触而心惕，闻一响而胸中跳跃。小腹作疼，子户肿痛，溲赤便结。种种见证，病在肝脾而兼乎心也。本此意而求治，加之静养戒怒，庶乎渐安。", "15959": "脾不醒则胃络不舒，脉右沉小，此右胁之所以疼刺不舒也。", "15960": "经水愆期，约四十余日一行，行时必腹痛。平素贪凉恶热，体瘦食少。肝木不舒，腹膨时痛。右脉耎小无力，左寸脉涩，关弦尺濡。气虚血少，先理肝脾，再商善后。", "15961": "喉痛二十余日。据述忽痛于右，忽痛于左，有时又痛于中，大率腐于何处，即痛于何处。缠延不已，药投罔效，邀余视诊。右颐漫肿，悬乳腐白。舌胎中央腻白如糊，秽浊无刺。喉不干燥，亦不欲饮。天癸未期，脉右缓滑。此风痰上侵，当理肺胃。", "15962": "平素经行或前或后，来时或多或少，腰胯酸疼。今春经行，半月复至，缠绵二十余日而未能已。服余养阴止经之剂，两日而停。左右脉来虚涩濡小，法宜气血并调。", "15963": "腹块由疟而起，历有年矣。不时举发，发则攻痛且胀。惟昨晚攻痛最甚，以致发厥，由渐苏醒。脉象左关沉弦，右关沉滑。气与痰并，挟块攻痛，肝木侮土。正值经行之际，当以疏通法，再为之计。", "15964": "又，壬午春三月得消症：脉右浮数，渴而多饮，证名上消。病经廿日，速治为最。", "15965": "经停三月，心烦欲呕，体倦食减，口干便结，脉束滑而小数。恶阻之象，勿药有喜。议养胃阴，二剂而已。", "15966": "二目白珠甚红，脉右按之数。肺火内郁，宜以清散法。", "15967": "新产五朝，左目陡然失明，毫无一线之光。头不疼，腹不痛，恶露未清，并无他苦。举家仓皇，向予叩首乞哀，泪潸然下。予因此细察脉形，右虚小无力；左关举之浮，按之弦。再视其左目，瞳神不敛。知其血虚血滞，于是以气血并补法，佐以舒滞、敛神，庶几目可复明。", "15968": "忽然腹痛难忍，甚至手足厥逆，目闭神倦。更余张灯延诊，予至观其形色，面青少神，低头不语，背曲足踡。再三问之，惟云腹痛难忍，奄奄一息。勉强视其舌，苔白而腻。诊其脉，六脉沉伏。知其寒伏三阴，深虑转筋入腹。况腹左兼麻，更非无自。亟宜温中舒肝，以冀转机，慎勿迟延。", "15969": "立方时，在座者铁珊乃兄楚望、乃舅王芝峤先生也。予方一定，铁珊谓予曰：「内子素有齿痛症，平日最畏热药。」芝峤云：「如此暑热，用此热药，恐非所宜。」予闻二公之言皆以为必不可用，大拂予之婆心一片。不思古人云：「寒者温之」，治寒以温，良医不能废其绳墨而更其道也。况色脉谛详，明明是夏月感寒，何谓必不可用。既畏热药如虎，第恐亥、子二时阴阳分而生气绝矣，咎将谁归。因又谓予曰：「服之当如何？」曰：「亟亟煎饮，腹之痛者可平，足之倦者可伸，伸则活矣。」二公始信而无疑，速取药煎，予心方安，乘舆而归，时已二鼓之余矣。次早铁珊会予，曰：「服药后如言痛止足伸，霍然全安。妙剂若神。」叩首感谢：「内子余生皆先生赐矣」。", "15970": "次日复诊，脉之伏者渐起，惟软小不舒耳。用理脾和肝之法，食饮渐贪。继以扶脾养胃之剂，调理而痊。", "15971": "产后恶露未清，寒热头疼。医者作产后外感治，转增汗多，气逆兼咳，因求治于予。细审病情，产后半月，恶露未尽，腹中不痛不膨，夜来寒热频发，咳呛气逆，汗出无时，脉象虚耎无力。气血两亏，深恐涉蓐劳之门，药饵岂可妄投哉。（正月三十日诊）", "15972": "细审病情，素有肝胃气，迄今十有余载。发则胀痛交加而兼之呕。呕属阳明，胀属太阴、知其脾胃之受累于肝久矣。夫土为万物之母，胃为水谷之海。《易》曰：「至哉坤元，万物资土。」未有土不足而能生长万物者。今土被木乘，脾胃愈惫，以故食入即胀，胀则欲卧，卧则胀安。岂知脾土从斯愈滞而愈壅，食饮难运而难磨，甚至水谷之精气不能四布，上下难以贯串，精气暗耗，食饮日减，肌体日瘦。运化失职，中满之虞，其能免乎。阅诸君论治，颇中肯窾。而犹时止时作者，想亦沉疴积岁，蒂固根深，而未能一时奏绩也。今证脉合参，右脉细软兼迟，左脉沉小而弦。种种见证，皆脾阳不运，肝木乘之。亟宜益气扶阳，间佐以疏之运之、和之温之、举之降之，而引导之。俾坤元日旺，中满可免，再为善后之谋，庶几无遗憾矣。《老子》云：「万物负阴而抱阳」，意自显然，先得我心之同矣。予岂上工敢治未病，而未尝不愿学焉。", "15973": "服七剂，安妥如前。即偶有腹胀之势，亦不欲卧而自平。夜来头足浮肿至早起身渐退之势亦减半，腰股牵引抽痛俱已。惟身中常常畏冷，绵皮衣不能离体。证脉合参，究属脾阳不运，卫气不充，八脉有亏。经事每多趱前似属血热，其实亦肝阴之不足耳。", "15974": "素有肝胃气，忽于月之初旬胸中跳动，脐下作痛，脘腹不爽。医者作湿温治，以四苓、平胃散辈消息之，病益增。继用气血并调中加入八味丸同进，以为汗多防脱。举家仓皇，因邀余治。审其证，脐下痛剧难言，必得著人以手重按其腹，痛始少缓而气逆亦少平。诊其脉，左关弦细，尺脉迟涩。此冲脉为病，并足少阴之经逆气上冲，乃下焦虚寒为患。痛甚防厥，勿藐视之。", "15975": "脉右虚软无力，左关小弦。食后作胀觉疼，腰腿漫肿，经停两月。肝血亏而脾土更亏，土虚金弱，又兼咳呛，防有中满之变。", "15976": "呕吐有年，不时举发。今于癸未五月二十一日呕吐，至今二旬未已。呕出不酸、不苦、不甜，腹亦不痛。更医屡屡，药进无功。且汤药到口中即呕，饮粥有不吐之时。北人素喜食面，又喜水果生冷。右脉沉小乏力，左关虚弦。阳明胃土久伤，肝木乘土犯胃。既进汤药不合，莫若暂投丸剂，待呕吐渐平，再为善后之谋。", "15977": "素多肝郁，胸中常闷，木火上炎，或目珠红肿，或有时鼻衄，或偶尔舌痛，已有年矣。今于道光癸未春，忽左鼻出臭水，或清，或浓，或如豆腐脑者，其臭不堪。始为鼻渊，继成脑漏，病成而前之鼻洪、目肿、舌痛等并不一发。合证脉而详审之，皆肝火郁而冲肺。肺窍开于鼻，木火侮金，故见于左鼻也。肝与胆为表里，经云：「胆移热于脑」，发为鼻渊。甚则漏下如豆腐脑者，此之谓脑漏也。虽分两名，其理一也。予于斯而得一探本穷源之治，庶几无遗蕴矣。", "15978": "泄泻有年，长夏尤甚，食后膨胀，兼之肠红。医因肠红概以凉血清火，泄泻益盛，延绵季夏。日泻数十次，夜间少减。食饮维艰，腹疼且胀。家居吴江，买舟就治于余。诊其脉，脾脉细软无力。当调坤土，以免中满。", "15979": "经水将至，喜饮冷茶一碗，当即经止。次日结块如杯，伏于胁下，觉痛。延疡科治，以为串痰流注，服破气攻块药六帖，块反增大，疼痛不已。更延内科，断为经水停蓄，防成中满，初剂用温经活络通瘀法，块顿移于脐旁，其痛如前；次帖用两头尖二钱（旁注：不可为法）佐青葱、韭子辈，服后则痛如刀割。三日前曾发寒热，今已止。病势日重，于六月初八日复求治于余。细按其腹，痛块左脐旁之左，大如五寸盆，坚硬不散。块之中央痛如鸡啄，手不可近。小便如常，大便不爽。舌绛无苔，口干喜饮，脉象细小。证脉详审，始为冷茶阻遏经水，以致经停成块。理应温通一二剂，而块消痛止矣。疡医不明此理，谬指为流注，妄治误人，无怪病反增重。后之内科论意颇是，而用药又不中的，故块顿移下，而又痛极难忍也。自予观之，有弄假成真之象。大凡痈疽之生，皆因营气之不和，逆于肉理而成者。今经水为寒所凝，成块且痛，其为营气之不和可知。疡医误投攻伐，内科妄用猛剂，俾气血交阻，经络凝滞，痛如鸡啄，肚痈已成，所谓弄假成真者此也。第脉未数疾，脓未成也。亟宜调气和营，继以内托排脓，使其脓出而不至有内攻之忧，是又在乎用药者。", "15980": "服后块痛如前，中间一点如龙眼大者，按之渐□，惟此最痛，乃痈之头也。脉象浮数，有溃脓之□，再议托里排脓之法。", "15981": "每夜四鼓时，脐上微痛即泻，已六七日矣。脉右沉迟，知其受寒停食。服后方一剂，是夜腹痛便泄顿止。药之对证，效如影响。", "15982": "又，四月初二日方：经行半月余，忽多忽少，色带紫泡。四日前，自觉内热，晚间尤甚。诊其脉，关尺沉中兼数，左稍大于右，舌色纯红无苔，口干不渴，知其阴虚内热。用后方一剂夜间不热，惟觉疲倦，懒于言动，食饮稍减。", "15983": "寒热两月，脉象虚弦。速宜退热，久恐骨蒸之虑。", "15984": "舟中不避风邪，风疹屡发。发则内热口干，骨节疼痛，脉左浮数。风化为热，治在清散。", "15985": "案云：新产受凉，虽寒热、头汗兼痛，而产后见之又不得作外感治。况脉息虚数无力，显有明征。丹溪云：「产后气血俱亏，虽有他证，以末治之」，旨哉斯言！（九月初十日诊）", "15986": "右胁疼痛，数日间时轻时重，忽又兼脐上胃脘痛，朝轻夜甚，因以木香、当归、元胡、神曲、干姜、枳壳、甘草辈。服二三帖，胃脘痛稍缓而右胁仍痛，又以香附、元胡、麦芽、莱菔子、枳、陈、姜、草等。服一二帖，胁痛似缓，而胃脘又复痛，夜间尤甚，痛时手按之稍缓。仍将前第一方再服两剂，痛仍不减。幸食饮尚贪，脉息右关沉实而滑。痛时牵引背骨，知其胸痛彻背，夜间更甚，不能安卧，非仲景瓜蒌薤白半夏汤不可。因兼右胁痛，又少佐木香以舒肝脾。煎以河水，再加陈酒一小杯同煎。服此一剂而胸痛彻背如失，胁疼亦从此全愈。廿余日之疼痛，服前两方俱未对证，得此一剂，痛若失矣，快甚！快甚。", "15987": "产后十九日，身热有汗，头疼胸闷，舌苔淡黄，口干少饮，耳鸣兼聋，不饥纳少，手指颤振。此产时去血过多，新冒风邪，六脉软大、小数。病已四日，防其发痉。《金匮》云：「新产妇人有三病，一者病痉，二者病郁冒，三者大便难」是也。当明辨之。", "15988": "进昨方，半日安妥。天晓发厥于下床小溲时，顷之即醒。今晨诊，六脉如昨，头痛渐减，食粥即呕。产后去血过多，荣血大亏，孤阳外浮，神魂不守，此厥之所由来也，是属险途。议益气养阳、和胃止呕，以免痉厥。方用大生地、党参、茯神、当归、白芍、枣仁、麦冬、甘草、制半夏等煎服。", "15989": "廿二复诊：未厥，呕止，纳粥。据述进粥三次，约有二盏。惟热势未尽，左脉空虚，右脉稍小无力。细审之，产时去血过多，兼之汗出不少。两日间，汗虽减而心血大亏，以致藏血之肝亦虚，此昨之所以见厥也。血既大亏，无怪虚热难退。宜乎补血为先，而产后之补血又不能全责之血分，必以气分之阳为血分之阴之主为最。盖气阳也，血阴也。扶阳可以生阴，亦阳生阴长之义也，必需益气养血、调和营卫为紧要关头。即此软大无力之脉，神疲难支之状，视一人如两形证名视岐，岂非气血大亏，究恐虚脱，立方于下，酌之高明。", "15990": "不时呵欠、恍惚、视岐，阳气外越，阴不内守，脉软大而空。仍议固纳一法，以冀转机。（五月二十三日）", "15991": "此方气营两固，理应佐姜枣以退虚热。因素不喜姜，执性不用，方中惟用南枣耳。服后精神稍健，耳聋渐减，舌绛稍淡，忽热忽退，喉干引饮，小溲二三次，出时觉热，转失气时有，食饮渐贪，脉仍虚大无力。用六味地黄汤加人参、麦冬、远志、南枣。煎好去渣，以蔗浆五钱冲服。", "15992": "产后气血将复，食饮渐增，天癸已行，而肌体未丰，八脉未充。色脉合参，当以益气培阳，使气血融和，精神自旺，且素有之脾约症亦从斯而渐润矣。", "15993": "素喜烧酒，左鼻瘜肉有年，迩来疼痛无时，牵连左目头角，痛极防其失明，脉浮数有力。病起数载，治之匪易。", "15994": "风邪客肺，气闭火郁，咳嗽痰黏，脉象浮数。宜于疏解，方用前胡、防风、苏子、桔梗、杏仁、陈皮、甘草、桑叶、瓜蒌仁、葱白同煎。服后咳减痰薄，舌苔尚腻，脉仍弦数，夜间口干内热。经水素准，今过期旬日未至。先理客邪，再为之计。", "15995": "十四日：原方去石斛、藿梗、地骨皮，加前胡、桑叶、枇杷叶。服三帖，咳嗽十去其八，痰亦甚少，天癸已止，知饥贪食，脉息虚浮，夜间有汗，表气不固，肺胃并调。", "15996": "体瘦食健，素性暴躁，易动肝火。数年来左胁有块，每发必先寒热交作，间五六日一发，其块仍伏而不动，必待寒热发勤其块始动，动则寒热不发。块移于中，心下跳动无宁刻，甚至手指抓桌，形如捉物，叫呼如狂。待其少缓而问之，则曰心中难过如火势上奔之状。发于春，延至长夏而渐减，交秋而渐愈。素性不喜服药，即或病重虽服药亦不过一二剂耳。咸缘病者性躁，不思沉疴积岁岂一二煎帖所能愈病者，故缠绵至今而未能已也。于嘉庆丁丑正月十七日履安再三延诊乞方，余按其脉，右关虚大无力，左关沉弦而劲。块伏于左胁，即《内经》所谓肝积，曰肥气者是也。块欲发动必先有寒热者，正少阳甲胆木气之报使也，肝与胆为表里。寒热停而左块攻上，横冲直撞，怪形异声，不由自主，亦人所罕见者。今正值寒热之时，间五六日一发，已发二三次矣。发时食后胸中必胀闷不爽。证脉合参，先宜养肝、舒肝、调中，待其块缓再为扶土保肺，间以养水滋木之法佐之，常使土气润泽，木气畅茂。仿灌园之法，合《内经》「亢则害，承乃制」之治，自无遗憾矣。第予有愈疾之手，而究不知病者能从乎否耶。", "15997": "经水已断四载，于前月二十五日忽吐血，三日而止，共约有一大盏。数年来好饮火酒，孀居十有余年，掌管家务，不无劳心伤脾，此吐血之所由来耶。虽止而头汗无时，渐自耳聋昏倦，自早至暮可饮粥四中碗。至申、酉时，仍然头汗如淋，当以扑法亦不应，惟睡著汗即止。脉息虚大无力，其为阳虚气弱可知。然吐血过多，阴亦伤矣。血止之后，身中似热非热，亦阴虚内热之象也。渐自耳聋无间，虽肾窍开于耳，而心亦寄窍于耳也。心主血，血去多而耳聋者亦有之。《素问》云：「精脱者耳聋」，仲景云：「耳聋无闻者阳气虚也」，更兼朝夕不离火酒，中气弥伤，肺金久耗。血止而继以头汗无时，岂不虑其虚脱耶。姑拟益气养荣，佐以达之敛之，俾荣卫和而阴阳交，卧安汗停，庶免一脱。方用五味异功合四物汤，去川芎，以茯神易茯苓，加远志、炒枣仁、五味子、巴旦杏、左牡蛎等十三味煎服。服后稍可多卧片刻，而汗究弗克一减。次日往诊，余门人程子，病者之婿也，予至，适程生先至，与予曰：「进昨方渐可多睡，是佳兆也。」予蹙頞频思，头为诸阳之首，汗出不减，神倦语低，脉形豁大而空，究属阳虚气衰，有立见倾危之险，岂佳兆也，程生唯唯。亟与议四逆汤加人参一钱。煎服一剂，头汗顿止，继以气荣并补之法调理收功。", "15998": "病由肝郁厥逆转为寒热无期，或日发两次，或间二日而连发两日。种种见端未便遽以为疟，况脉形细小而劲，舌苔光剥，唇齿干燥，食饮维艰。细绎病情，阳弱阴亏，荣卫两虚，此寒热之所以无定期也。迄今两月，虚损之征已露先机矣，亟亟护阳益阴，虽有良方惜乎鞭长莫及，拟方于下，斧弄班门，既蒙垂青，聊为塞白。", "15999": "素体肥胖，经行落后。风寒湿三气合而成痹，起于颈项，波及肩臂肢肘，下及两股，痛剧难忍，业已九日。他医作痿证治，妄用鹿角霜、琐阳、归、芍、沙参等温补之剂三帖，无怪乎痛势更增，寒热交作，脉象浮小而细。法宜祛风渗湿、通经活络为最也。", "16000": "进昨议方，崩血渐减。因欲贪食，稍啖荤味，便泄随至，脉象细软。滋腻之剂，究宜缓投。宜以益气扶脾，冀其坤土得令，庶几无妨。用党参、山药、芡实、茯苓、益智仁、煨木香、炙草、陈皮、南枣等。煎服三四剂，漏下已停，而便泄仍日四五次，皆缘脾土之不足耳。拟异功法加建莲、芡实、砂仁、归、芍、陈皮、南枣等治之。服两帖，便溏日一次，再二帖而止矣。", "16001": "素有肝胃气，发时遍体不疏，腹痛且胀，甚至欲呕。又有目疾频发，发时白珠色红，昏花起星。偶尔寒热，经水有时应期，脉形左弦右缓。种种见端由肝郁而波及于胃也，法当土中疏木，俾土木合德，诸恙向安矣。", "16002": "素有肝气，当脐作痛，痛甚则厥，必得重手按脐方缓。今发尤甚，于前月二十五痛之不已，服他医通气泄肝药即止。未两日复痛，又用党参、首乌、石决明、沉香等药不应，因求治于余。腿膝觉冷，得暖则脐中痛缓，脉右沉细、左小弦。冲脉为病，里虚而痛者阴不足也，温养下元是其治法。", "16003": "下消症迄今数日，他医用萆薢分清饮法，不应。病得之肝经郁结，而波及于心肾，致水火不交。口渴溲数，出如膏油。《经》云：「二阳结谓之消。」饮一溲二，此下消症也。由于肾水不能上承，心火难以下降，火在水上，正合未济之卦也。故渴饮溲数，下如稠浓膏油，脉形软数，尺脉虚濡，证岂轻候。", "16004": "泄泻五日，由食面、肉而起。胸闷不饥不食，食则呕吐并至，腹痛即泻，脉软滑而细。虽在高年而宿食停阻，当以运食舒中，使痛泻呕止为最。宜以生谷芽、制半夏、山楂肉、麦芽、藿香、枳壳、赤苓、甘草、木香等九味，加煨生姜两片。煎服两帖，而呕痛泻顿愈。", "16005": "脘腹作痛，痛剧脐中块攻，气食交阻。脉象沉滑，沉者气之滞也，滑者食之阻也。法宜温中运食，防痛甚发厥。", "16006": "于道光六年两足小腿疼痛而起，已后举发无时，甚至痛剧难忍，小腿细小肉削，证名干脚气。渐至大小腹痛而且胀，以致食减。今于九年己丑岁六月十九求治于余，据云于四月生产，迄今两月，而脚气又发，疼痛如锥，大小腹仍然痛胀，食少，大便干结如栗，脉息细耎而涩。知其血燥筋枯，足能屈而不能伸。水不滋木，木强乘土，此大小腹之所以痛且胀也。议养水滋木以舒筋，俾其痛胀平而筋自舒，得谷乃昌。服后方三剂，而诸证全瘳矣。", "16007": "左胁肋块痛，自道光七年冬由寒热而起，缠绵日久，块渐大如杯，硬而不高，痛甚牵引腰背。延至九年秋，骤然吐血盈盂，三日而止。当时块痛顿平，后又复痛。是月望前，忽尔寒热成疟，而痛块又平。待疟止而块又至，且痛无宁刻，食少体瘦。自血吐之后，天癸未至约近两月。诊其脉，右软小无力，左关浮之弦细，按之小数。知其胸中郁郁不舒，肝火易动，甚至直冲而血溢上逆。病起两载，痛块日增，卧床食减，大便燥结。防涉虚门亟治之，或可从凶化吉。若假庸工之手，尤难之难矣。议以扶脾、养肝、润燥，兼之舒运，俾痛块日减、肠润、经行斯可矣。", "16008": "中脘胀痛，波及小腹膨急，痛无宁刻。现在见厥，深虑汗多，食不喜进，脉息沉细迟缓。病势颇险，勿得忽视。", "16009": "至初七日仍延余诊：右脉软小无神，左脉弦细。肝胃并亏，面色㿠白，神疲难支，二目半合，额有黏汗。自昨至今午，食毫不进。素亏之躯，加以痛剧见厥之后，深恐骤脱。议四君子加味，亟固胃气兼之定呕、纳谷为最。", "16010": "病由前月，黄昏微寒渐热，热至天明微汗而退，热时颇甚。舌苔早黑，少顷淡红。耳鸣，骨节疼，食无味。迄今廿日，寒热未解，脘腹膨胀。医以疏表清凉之剂，皆未去病，因延余治。脉象两关弦大，按之不足。邪热内伏，当以和解退热，俾胃土得令，纳谷为最，恐犯虚热之门。议小柴胡汤去半夏，加花粉、扁豆、苡仁、二苓、泽泻、秦艽、归身、地骨皮等，加姜、枣。煎服三帖，寒热顿减三之二，惟脘腹膨胀、腿足浮肿未退耳。", "16011": "暑湿热三气交阻，得于行经之后。血室空虚，邪乘虚入，以故寒热无期而朝轻暮重也。迄今十八日之久，更兼吟咏呓语、口干喜饮。阴气亏于下，而邪终不能解也。脉形弦细，按之不足，非无以也。证颇棘手，姑拟益阴退邪以冀转机。", "16012": "脘腹作楚欲呕，发厥手颤，二日上窜，牙关紧闭。面色娇红，鼻衄色紫，左脉弦滑且数。肝郁火升，此厥衄之所由来耶。", "16013": "内唇肿硬畏寒，波及鼻傍漫肿，疼痛难忍，得热布熨之稍缓，见风则愈剧，脉象沉紧。荣气闭固，郁结不散，而成内唇疔。外宜疏解风寒，内以散肿拔疔为亟亟也。先用针刺唇口鼻下，泄其气并未见血。外用葱汁调家制霞城散敷肿上，如药干再以新绵蘸汁润之，则肿易消。内服苏叶、防风、蔓荆子、桔梗、柴胡、连翘、陈皮、甘草，加干浮萍草、葱白头同煎服。", "16014": "每遇临经前后，小腹必痛，而兼呕酸水，甚则增泻，据述病起四五载。脉右软小，左弦细。肝木犯胃土，甚则大便作泻者，以胃与大肠同属阳明也。自云幼年最喜生冷，迩年暑热水果不能戒，益见阳明胃土之久虚。及早禁之，服药勿懈，庶乎渐安。现在经转，治宜舒肝和胃。", "16015": "素多劳役，连日头疼、骨节痛。昨早忽然头痛且重，举头不直，骨节间疼如针刺，身微热，口苦舌干，淡白苔，内热不喜冷饮，脉浮小乏力。阴虚体质，血不荣筋，加以外风相搏，故遍体疼如针刺。申刻进后方一剂，渐自微汗二三次。少顷觉饥，当饮薄粥盏许，顷之周身小汗。至戌初，头痛、骨疼顿缓。次日早晨，病若失矣。方附下：", "16016": "风暑搏而头胀，小腹闷而疼痛难忍，带浊绵绵。病经六日，脉象浮小。当以疏解和肝，未可忽视。", "16017": "脾虚挟湿，稠痰盈盂。肝气不舒，腹膨背胀。腰胯漫肿，波及大腿，惟小腿与足跗未肿。白带频下，阴户湿痒。食能进，多则胀。经停三月之久，脉形细耎，左虚弦，尺无滑疾之象，非胎也。诚恐脾土不运，而致有中满之虞。", "16018": "向有三疟，年余方止，脾土大亏。夏间劳碌过度，迩来食入即胀，胀时腹疼。左腹有块，积成疟母。脉右虚小无力。失于将息，防成单腹胀。", "16019": "道光丁亥六月望前得红痢症，延绵至八月初旬腹痛虽止，而昼夜尚有粉红冻七八次。小腹膨闷不爽，带下直溜，腰疼食减，脉息虚软。脾胃两亏，亟理坤土，痢止为最。方用冬术、山药、扁豆、茯苓、煨木香、益智仁、炙甘草、地榆、椿根白皮等。煎服三帖，昼夜痢减二次，其余如前。", "16020": "复诊：滑泻如冻，带下直溜，得食精神渐健。高年脉弱，治以益气调中，兼之厚肠固脱，亟平为妥。", "16021": "中虚挟湿，气声如鸣，两足浮肿，大便溏泄日夜数行，食入觉噎。寒湿内蕴，面色痿黄，深恐木乘土位，致令腹胀成膈。脉形濡小，法当温中运湿。", "16022": "血崩旬日，每发于夜。血去过多，阴虚血热，脉来濡数，速止为妥。", "16023": "痛块作胀，近于脘左，迄今四载，举发无时，脉象沉细，拟舒肝和胃法。", "16024": "停经三月又半，连发寒热四日，每日早晚两次。昨由寒热而致经血骤至，当即腰疼腹痛，随下一大块，外有衣膜裹血而下，果系小产。因病者讳胎，诊时嘱余莫谈，并云案中不可明言，亦执性也。据述腹中尚有如杯大之块，而今日之寒热更重。舌苔光滑而绛，气逆呻吟，口干喜饮，时欲恶心，脉形软小。议去恶露、退寒热为紧要关头。", "16025": "复诊（二十一日）：服昨方血缓、痛减，腹块小如胡桃，惟气闷、神倦、欲呕如前。午时进诊，寒热未至，最妥。第脉象仍软小乏力，闭目则神思恍惚，张目则火光散大，是属险候。方意同前，少佐姜汁炒竹茹、川郁金，取其定呕恶而疗胸前之气闷。", "16026": "服后二十二日诊：据述服之，昨寒热仍未至，极妙。但胸背热气时升，鼻孔似煽，脉仍耎小模糊，纳谷维艰。昨夜半大便后，精神更疲，多梦纷纭，至天明神识少安。色脉合参，深虑虚阳上越防脱。议亟护真气，兼之镇肝、敛神为稳。（早诊方附后）", "16027": "咳嗽痰红，旧恙复发，脉虚小数，喉痒气逆。正值土旺之际，亟宜停止为妥。服后方一帖，血止。", "16028": "（案54）邵氏女血崩逾月，寒热兼厥、脉形虚芤治验", "16029": "血崩逾月，脉虚无力，左脉虚芤。血去过多，阴亏阳弱，荣阴不守，卫阳不固。此寒热而兼厥也，深虑骤变。为此时计，亟宜扶阳济阴，俾崩止厥回，庶无他虞。", "16030": "产后脾虚泄泻，昼夜廿余度，口干足肿，迄今匝月。脉虚无力，脾气下陷，先理中宫。", "16031": "喘症有年，举发无时，经水落后无定期。迩来喘发越勤，肌体瘦极，食饮日减。或冒风，或感寒停食，发则咳嗽频增。必先左目发痒，痒甚则喘症随发，发则气壅痰塞，呼吸不利，气尽奔于胸脘而不下达，以致声如曳锯，鼻煽畏寒，甚至一咳则小便直溜。卧不著枕，倚靠而坐，食难下咽。其所以难下者，缘胸脘气壅痰阻耳。今自初五喘发迄今，他医用紫菀、郁金、「三子养亲」及葶苈、二陈等汤，投之不应而反增重。更医，医作冲脉气逆治，以熟地、沉香、桑、丹、苓、芍、紫石英等以为纳气之法，服后胸脘愈觉壅塞，大便燥结十余日未解，喘汗肢冷，米饮不进，奄奄一息，于七月十九日始求治于余。余察脉审症，气喘汗冷，胸前窒塞，肌体骨立，食毫不进，溲出热短。脉细如丝，左脉微弦。肺金虚而气壅，脾土弱而痰生，子母并亏，肝木从中乘土侮金。以故病发则目之上下两弦作痒异常，而喘病随发，因目为肝窍，两弦属脾，喘属于肺。木之乘土凌金，信不爽也。察脉审症，脱势已显。权拟一方，若能气渐下降再商。", "16032": "复诊（七月二十日方）：进昨方约申正煎服，服后胸脘之气渐松而下达，上焦毫无壅塞而喘急之势顿平。少顷遵予言，随捣鲜芡实作粥，饮其一盏颇安。已后进米粉糕等胸中适意，可以坐立问答，与昨之病形大相远矣。第脉仍如昨，能于斯而日渐减可，庶乎尽善。即于原方内去牡蛎，加百合、五味子等。服之如前未喘，饮粥如前安妥，大便之燥结亦从此而解矣。", "16033": "道光十年七月十八产子，腹痛腰疼，顷之包浆水下，稳婆未至，儿已落地。约半时之久婆至，始将脐胞顺手而下，当时恶露甚少。次日血下无几而停，斯时惟日进益母草汤及米粥调养。于二十日后早进野味，至二十四吃饭四盏，较之平常反增倍，而犹嫌心嘈，贪啖野味。至廿五日忽觉胸腹胀闷、气阻不爽，延医，医以为产后体虚，当用四物汤加减。廿六日神识似清非清，夜来错语，头汗如雨，牙关紧闭，小腹膨胀。主人问其恶露有否，医者答曰全无。用熟地、归、芍、龙齿、牡蛎、茯神、枣仁、黄耆诸补纳之剂二三帖，病愈剧，于二十九日始求治于余。余至，细审病情兼察色脉。脉象虚而滞，左脉弦紧。答问如常，神识尚清。舌中焦黄有津，口唇燥裂，却能纳粥。据述昨夜腹膨痛胀，陡然汗出自头至膝，牙关紧闭，与前无异。将参片含之，少顷渐自关开，神清。余知其恶露未净，医者过投补纳而无逐瘀之法，是以至夜而病愈剧也。当亟以辅正通瘀，佐以止汗，为吃紧关头，迟恐棘手矣。", "16034": "又案（七月三十日）：察脉审证，问答清爽。自觉脐下尚有一块如杯大者，仍时痛膨胀。主家仍防如昨之厥，余曰昨立方时，曾已告明产后十二朝恶露停畜已久，深虑血不下而致厥脱上攻之变，而不得不用之方也。岂仍宗前医补纳，顷遭斯变，幸急进余前方而恶露瘀块顿下。今细绎之，犹未净也。再以益气、温经、逐瘀，冀其恶露尽彻，庶乎渐安。若不此之求，而概作产后补纳为法，其如瘀恶未净从何可出。无胆无识，难以救人于顷刻。仆才疏学浅，既蒙垂青，聊为塞白。", "16035": "服之恶露又下，从此痛缓块平，而脘腹中究有不舒之势，食饮未贪。脉象虚耎，右关沉小。八月初一，用和胃调中兼以润燥之法投之，大便内又解黑粪成堆，与前畜积未化之食物齐下。足征新产之后，胃火升而多啖食物，兼之产后肠燥得余和润之剂，而腹中宿滞顿下，从斯块消痛止矣。再用和胃生津之剂，口唇之燥裂、脘中之不爽亦俱减矣。数余日后又因口燥便结、白带频下，用生津润肠之剂而渐平复。又肝脾并调，俾脘腹舒畅、肠胃滋润，调治两月而痊。", "16036": "素有肝胃气，发则呕痛交加。日来寒热，咳嗽无痰，头疼。舌绛，脉右浮缓，左弦细。先理寒热为妥，用苏梗、前胡、蔓荆子、杏仁、川芎、茯苓、瓜蒌仁、地骨皮、黑芝麻、沉香辈，加生姜皮五分同煎服。进三帖，寒热退，咳嗽未平。", "16037": "二十日诊：用沙参、款冬、巴旦杏、冬桑叶、苡仁、茯苓、苏子、百合、黑芝麻、枇杷叶去毛煎服五剂，咳嗽全愈，旧恙肝胃气又发，脐之上下作痛，兼之呕吐，每发于申酉而至夜半者居多。年近三旬，前缘产后，面目、小腿俱有虚浮之势，亦脾土之久亏也，脉息两关小弦，当理肝胃。", "16038": "齿痛异常，夜间更甚，进清火、舒散等法皆不应。诊得左脉虚数，因其痛而食饮难进，用后方一剂，疼痛顿缓，再三剂而痛止。已后又有小疼之势，又进数余帖而全愈。此道光十一年辛卯岁五月初一日方也，方附下：", "16039": "体丰多劳，酷好浓茶，中虚挟湿多痰、肝脾不足之躯。前月初旬得臂腕疼痛难忍，波及手指。延次子茂常诊治，用舒筋活络间佐气荣两补之法，调理而安。忽于九月初十午刻，骤然头眩，眼暗欲仆，兼之呕吐酸苦食物，舌白胸闷，起立运跌如在舟车，上重下轻，脉形浮滑弦紧。外受之寒引动内风，风火交煽，气阻痰凝，此头眩、呕酸之所由来耶。深恐变幻，亟宜止呕、定眩为最，不可藐视。时在道光辛卯岁九月初十日诊。", "16040": "进前方一帖，未大热。次日再剂，至更余身热，至二更而渐退。少顷汗出过多，神倦眼闭渐渐而平。舌心淡黄带润，大便燥结，食仍不贪。产后气血大亏，虚热不已，加之汗出过多，岂不虑其虚脱。况脉形软弱无力，必得气荣两固、扶养胃气为急急也。", "16041": "据述病由：九月间胸闷不爽，腹中时疼，疼久口吐涎沫。医用疏通不应，又有作虫治，用乌梅丸等，偶有蛔虫一条泻出。以后痛仍作，淹延二三月。天癸自起病至今，三月之余未转。日来脘腹闭闷，不饥纳少，腹按之如裹水之状，漉漉有声。脉象沉紧弦细，按之无力。其为痰饮无疑，致令络脉不利。病在脾、胃、肝，而关冲、任脉也，一以贯之。", "16042": "复诊（二十三日）：服前方痰多，腹未痛，按之仍觉腹中漉漉之声，不按不响，响在脐上，得转失气下觉脘腹舒畅。脉象沉紧弦细无力，四肢觉冷。中脘寒痰凝阻成饮，是以按之有声如水，中气有亏，停经三月余。当温理中宫，自尔渐平。方用附子理中汤合「香砂六君子」去陈皮方也。", "16043": "素体瘦弱食少，气血不足，天癸每逾期二三月而至，白带频下，脉象细焮尺濡。阴阳两亏之体，宜温养血气，俾八脉融和，冲为血海，经行应期，庶几无妨。", "16044": "寒热发于酉后，寒甚热微，顷之复寒，夜半而止。病起三日，每日如期。舌苔白腻，脉象耎小。年近二旬，经水已过。法从温中和解，兼治头疼。", "16045": "旧恙屡发，气逆不降，神疲肢冷，食少肉削。脉弱，按之若无。脾阳大败，元阴亦亏，只恐骤变。议用扶土益金法，究防虚脱。", "16046": "产后八月，冒风咳嗽咽疼，身无寒热。于两日前，忽吐鲜血数口，次日又吐杯许，色带紫块，今日亦然，因邀予诊。脉象浮小兼数，阳明胃土攸关。《经》云：「阳络伤则血外溢」，宜以清降则血散火退矣。", "16047": "梅圃乃室复诊（六月初二日）：脉右软小，左濡数。热未净尽，是以食不贪耳。议育阴降火一法，免其变幻。", "16048": "又，初四日：忽又大便溏泻，自早至申泻已六次。脉软小无力，左濡小。肝郁乘土，拟养胃止泻法。", "16049": "初八日：仍于前方出入，食贪神健，便溺调匀，脉形尚耎小无力。已后延诊著次子茂常往诊，调理收功。", "16050": "脘腹膨胀有声，脉息右耎，左微弦。脾土亏而肝木不舒。病起有日，经水尚调，当从土木并治。", "16051": "肝虚气滞，热郁生风，发而为痫，脉左虚弦。治在养肝，毋泛作风痰治。", "16052": "病热夹经，胸膈热闷，手足清凉，并兼指麻、舌麻，不时冷汗，谵语烦躁。眼一闭即惊惕，眼一开则怕火。大小便两日不通，左寸关脉弦数。想此女风暑相搏，内有郁热，故眼开羞明，闭则魂不归肝而发惊也。曾服荆、防、藿香等不应，用后方一帖病减八九，身凉人静，二便俱通。", "16053": "病由感寒腹痛而起，渐自右股骱骨，痛如刀割，朝缓夜剧，迄今匝月，证名骨痹，痛甚见厥。乃寒与气郁，湿阻关节，引动内风，肝虚气滞，脉象沉紧。法从温舒，方用制香附、元胡索、当归、肉桂、木瓜、陈皮、独活、杜仲、淡茱萸等九味。煎服两帖，痛如前，不增不减。", "16054": "次日复诊：恶露未尽，心荡口苦，食无味。脉形虚芤，左弦细，体倦神疲，加意图维。方用当归、川芎、炒蒲黄、五灵脂、炙草、陈皮、炮姜、苡仁、生谷芽等。煎服后，恶露渐少，心荡头眩，夜寐不宁。", "16055": "喘咳气逆，旧恙屡发。肺金虚而痰沫频频，纳谷维艰。每发必眼鼻作痒异常，易于动怒，肝火冲肺也。昔年案中已详论之。今脉右软弱，左弦细。深虑喘汗并至，亟宜益气定喘为最也。", "16056": "吮乳两载未停，数日前忽然经行，骤阻，小腹痛胀，经带并下，溲出疼痛有涓滴不爽之势，脉象弦数。经阻挟淋，兼而疗之。", "16057": "吐血有年，举发无时，体伟神健，素好浓茶，不无湿痰。白带频下，年逾半百，天癸未停。时而气逆喉痒则血势上溢，时而火升心嘈则胸中摇荡，皆血去过多故耳。虽阳明为多气多血之乡，而久吐非宜。《经》云：「阳络伤则血上溢」。胃络岂可久伤也，况值天癸应止而未止耶。此刻虑其上溢，久恐防其下崩，《经》又云：「阴络伤则血下溢」，正此谓耳。脉形虚软，预为调摄，庶乎戬谷。", "16058": "风寒湿三气合而为痹，始于左足，屈伸不便，疼痛抽掣。素喜浓茶，经水愆期，病起半月。进舒筋、除湿、调经、活络之剂。服三帖，痛势渐松，波及于右，右轻而左甚。《易》曰：「震为足」，足属东方木也。由左达右，木强乘土，土虚金弱，西方之兑金弗克制木，以故内风动而风生。「风淫末疾」，此腿足之所以疼且痛也。再验之脉右虚耎，左弦细，更显有明征耶。法宜扶土祛湿，舒肝却风，庶乎戬谷。", "16059": "经行五日未停，色淡且少。夜寐不宁，内热火升耳鸣，心凛凛而肌肤毛耸，易于出汗。舌苔淡白，脉象耎，左小弦。皆血海不足，虚火上炎，荣虚卫弱，见证多端耳。理宜气荣两固，第胃土未和，当先调荣护卫以止汗，兼之养胃和肝，冀其纳谷乃昌。", "16060": "咳嗽朝轻夕重，内热口干，手足心热，食饮稍减，痰中偶兼血丝，白带频下，脉形细数。阴气亏而肺胃之气不足，延绵日久，土虚金弱，水亏火升。日进滋泥之剂，与肺、胃大不相宜。以故内热咳嗽终未除也。于六月初旬延余诊治，用后方数余剂而诸恙顿平。", "16061": "暑风内侵，畏寒身热，头重无汗，胸闷，骨节疼，腰胯酸痛。舌苔白泥满布，脉形浮缓。其势匪轻，速于舒解，微汗为妥。", "16062": "两足大指夜睡即麻，攸关肝脾。盖足大指属脾，穴名隐白，临睡即麻，脾阴不足可知。而又兼乎肝者，肝之大敦穴亦在足大指也。况经事每多趱前，有时一月两至，非无以也。右脉软和，左脉濡细乏力，经水虽速，究属虚象，脉可凭耳。于是用于术、熟地、归身、白芍、制首乌、炙甘草、制香附、木瓜（乳香同炒），服数剂全瘳。", "16063": "肝气旧恙复发，胸脘刺痛，气逆呕吐，肢冷发厥，脉象沉紧，感寒挟食，舌苔泥白，宜于温舒。", "16064": "素体丰健，惟多湿痰，迩年天癸每多愆期，头眩眼花，肠红频发，小溲频数有不及登圊之速。脉形软滑，左弦细。此肝肾阴亏，脾土弱而不能统摄者皆有之也。", "16065": "时热虽解，而胸脘满痛高凸。酸邪固结，不为无因。脉象弦涩，年近七旬，证在垂危，未便许可，而究不忍坐待也。", "16066": "案云：脉虚细而数，始而便血，继则呕血。肝不能藏，脾不能统，而阳明之受累也深矣。盖脾与胃相为表里，大肠与胃同属阳明也。脱血过多，「有形之血不能速生，无形之气在所急固。」本此以治，是为上著。", "16067": "复诊：血止汗停，脉象稍静，似好消息，而调治之法尚费经营。", "16068": "复诊：食纳呛稀，而且粥进三碗而未足，胃口已开。脉来五至而有余，阴气渐得，是好消息也。但脱血之后务须归经，而引导之法不可躐等，亦不宜过泥，是在乎用药之轻清。", "16069": "历年肝气时发，今因胀痛之极，忽而大便下血不止。药饵乱投，甚至呕血盈盆，十日之内约有斗许。虚汗淋漓，几乎欲脱。予用养阴吸阳法，一剂回春，并无点血。继用脱血固气、阴阳双补等法，调治全瘳。因立丸方，以善其后。此症之所以敢治者，因病在垂危尚有胃脉也。", "16070": "余读郑素圃先生医案，而深叹先生仁育之功之大也。先生体验深，故见之独确，阅历久，故信而有征。具卓然之识，而能好学深思，心知其意，故其视人病，不啻见垣一方。苟非司命，无奈之何，先生莫不使之霍然而起。今年已老，不忍没其生平之苦心，全活之实效，举其尤大彰明较著者，笔为医案，斯真足以信今传后，而垂无穷。吾闻先生之于医，非偶然也。先生早年痛其尊公先生即世，自伤为人子而不知医，旋又自膺疢疾，复苦医之多不精脉，不达阳生阴长之故，苟非大相乖舛，即同胡广之中庸，味道之模棱，遂致宛转于药炉间者，凡五年。用是忧愁发愤，恣意搜讨，上自轩岐，下迄近代，不遗余力，一旦确然有以会其指归。夫五年之久，切身之火，其间四时之更迭，七情之感触，标本虚实，藏府传变，方剂损益，无不饮食寐寐，甘苦亲尝。始悟医之互相沿习，多事虚声，而古先圣人医之源本，方之准绳，欲求神明变化于其间，固非仿佛袭取之所能得也。夫医之为书汗牛矣，穷年涉猎，而无当于治，虽多亦奚以为。今缝掖之儒，无论帖括稿本，匝地弥天，即自谓羽经翼传，著述衰然。求其接孔孟心传，千百中无有也。苟能体之身心，验之实践，则求之六经四子而有余，先生之于医，亦若是而已矣。灵经素难，先生之六经也。仲景东垣，则先生之濂洛也。本身征民，先生之道，其庶几乎。吾观医案之中，凭脉者十之八九，三指不明，误人七尺，先生之脉精矣。参之望闻者勿论，则隔帏不出一语，而能决其为幽阴之隐疾也。意得者十之一二。医者意也，先生之意神矣。则观市中之多觝鱼，而能知其中毒；见几上之葡萄干，而能知其舌之非不可治也。如此者不能胪举，要皆他医敛手莫措，而先生迎刃奏功，则先生之医案，其可不流传以示后世哉。且医案不可与医方同日语也。先是先生之曾祖梦圃公，有墨宝斋经验方，焦弱侯太史公序而行世，闻有秘方，不惮数千里购之。虽重赀勿恤，兵燹之后，板多散佚，先生重修而广布之。然方虽良，必视乎证，苟证之疑似，介乎毫芒，则犹恐不免于泥古谈兵，按图索骥。案则详于证而方具焉，如法家之成案，供其事之始末，而判其尾，又如禅家之公案，举其语之触背，而透其宗。后之留心于此者，取而例之，而参之其通变，不尤足多乎哉。或疑先生医案中，多著他家之误，何也？曰：是先生之仁也。先生悃愊无华，非若李士材之工于排俗，而于医之误者，必备载之。世之病而死者半，医而死者亦半，徒避彰短炫长之小嫌，而使后之误者踵其误，是听人之相借以死，先生不忍为也。且讳其人而第著其误，何伤乎？故曰仁也。或疑先生医案中偏于温补，何也？曰：非偏也。亦先生之仁也。吾闻阳道舒，阴道肃。故干统乎坤，卦昼于一阳，所以生生不已之元也。万物体阴而用阳，二气屈阴而伸阳，圣人贱阴而贵阳。人之身，阳不尽，则不死，阴不盛，则不病，而道家谓阴尽而后仙。此其旨惟先生明之，故医案所载，得姜桂而起者为多。夫过于辛温，投以清凉即解，一失于苦寒而顿殒者，比比也。且先生非胶柱而鼓者也。故曰：亦先生之仁也。先生仁被斯人之功大矣哉。彪不敏，时有采薪，唯先生托命焉。会先生卷帙有成，一二同志，将寿诸梨枣，因踊跃以襄不朽。但愧言之少文，又无能窥见闲奥。以当年侍先君子时，时与闻导引，得诸过庭之言，今读是书，触绪而有合也，故不揣而序之如此。", "16071": "魏虞成学博，壬申秋，得伤寒似疟。诸医皆以柴葛解肌，枳朴化滞，或作疟治，而寒热无定期，且无汗解。因热不退，又进大黄丸下之而不便。至十八日，招余诊视。脉来弦细而紧，三脉皆阴，舌黑而滑，干哕不休，频欲饮汤，甫下咽，即呕出，而水倍之，当胸结硬，腹亦微痛。告之曰：余治法不类诸医，恐不相信也。此证已转虚寒，非温剂不效。舌黑而滑，肾水凌心，饮汤即吐，引水自救，皆属少阴。况已汗已下，而邪犹不解，反增呕哕，阴躁不眠，乃亡阳之机，常药不效。遂立方，用生附子三钱，茯苓四钱，干姜二钱，甘草五分，乃茯苓四逆汤也。令其多迎高明参议，未敢奉药，惟团弘春首允，他皆不然。至暮，乞药于余。服二剂躁定，四剂舌退黑，六剂热除，八剂呕止，能进谷汤。照此药再加半夏，八九日后，粥食渐进，而大便冷秘不通，兼服半硫丸五日，大便方通，而病解。计服温药一月，甫能离床。", "16072": "又如君汪，庚申年在瓜镇，时九月杪，得伤寒。初幼科医治，先发表，即大汗如水，继和解而热不退，益增烦躁，再投白虎凉膈，即神昏默睡，唤亦不醒，摇之惟开目而已。病至十九日，自郡迎余至瓜镇。切其脉洪大无伦，重取则散，身重蜷卧。余曰：此因误治，寒入少阴矣。初必夹阴伤寒，宜用温经，误投表药，致魄汗淋漓，阳因汗越，益增烦躁，再服苦寒，阳气愈消，致耳聋昏睡。此少阴，非少阳也。脉反散大，乃真阳欲脱之机，特进投附子理中汤二剂。服后脉稍敛，欲小便，及就桶，小便已，即寒战口张欲脱。再以理中汤重加人参，连进二剂，方阳回苏醒。次日回郡，留理中汤方药调治，半月始痊。", "16073": "赵宅寡居蒋氏，年四十外，五月得时疫伤寒。初医未辨时疫，概作伤寒正治，发表有汗而热不退，再用清热，即干呕吐蛔。七日后延余往治，脉弦数而无力。余曰：此时疫证，乃邪自里发于表，非若伤寒自表而传于里也。初因误汗，徒伤正气，清热必定寒中，以致干呕吐蛔，急宜温中安蛔，免邪入里。即以小柴胡汤加炮姜，去黄芩，四剂呕止蛔安。而经水适至，夜则谵语，即前方加当归、赤芍、红花，作热入血室施治。至十一日，乃大战汗出而解，已身凉脉静，一日一夜矣，忽复烦躁，面赤戴阳，渴欲冷饮，赤身跣足，或歌或哭，谵妄如狂。他医有谓汗后余热未尽，当用竹叶石膏者，有谓汗虽出而里未通，宜用承气者，又有谓余先误用炮姜药贻患者，议论杂出。余答曰：皆不然，初因邪未出表而误汗，以伤阳气，致中寒干呕吐蛔，又值行经而伤阴血，气血两虚，故出战汗。幸战而有汗，邪方外解，若战而无汗，正属不治。今身不热而脉反大，乃真阳外越，不急用参附，必再战而脱。余主用四逆汤加人参，煎成而不敢服。瞬息间，病人索被恶寒，方信余言。即以前四逆汤乘冷灌之，面赤渐淡，就枕略睡片刻。醒则又躁，即急煎如前大剂，亦用冷饮。方熟寐一时，及醒，问前事全然不知，反倦卧于床，不能昂首矣。用参术炮姜，一月方瘥。", "16074": "吕惟斗翁令眷，住居仪真，癸亥正月初旬，余自真州发郡，路遇令婿黄苍润兄价，执帖相招。至诊其脉，细数近疾，重取全无，舌卷焦黑，齿垢枯黄，卧床去被，露胸取凉。问其病源，初二日开窗梳头受寒，前医用麻黄汤发汗，汗出后即烦躁，因而又用石膏白虎汤，遂致如此。口索冷水，复不能咽，而房内又设火三炉。余曰病人如此怕热，何须置火？家人答以主母平素畏寒，日常所设。余曰：若此乃阴极似阳，亡阳脱证。辞不治。其时朱性生翁在座，力嘱用药，勉以四逆加猪胆汁汤主之。生附子三钱，干姜二钱，人参三钱，甘草一钱，人尿、猪胆汁各五匙，煎成灌下一半，而人即昏沉不能咽。约一时许回苏，已离魂至江口，醒云扬州医生药好，复索余药。服后熟寐，次日回阳，齿舌润滑，如常畏寒矣。继用理中生脉汤十数剂而愈。", "16075": "续溪堪舆方于长，年将六旬，自徽初到维扬，为方宅卜地。时癸亥初冬，彼不知江北较冷，多啖海珍，盖覆单薄，夜受寒冷，因之头痛发热。忍隐不药，而饮食又未节，迨传至阴经，干呕胸胀，舌黑干卷，脉细如丝，方求医治。因其脉证，诸医佥云不治，宜迁别寓。而卜地主人，不忍使迁，最后招余以定去留。余诊脉望形，答以不死。其语音清响，身轻自能起卧，无烦躁下利厥逆等证，病脉似少阴，而实太阴也。因肥甘在胃，冷结不通，食压太阴，致脉不出，中宫壅滞，津液不能上输，致舌干齿燥。用四逆汤加人参，作太阴霍乱治法。干姜三钱，附子二钱，人参、甘草各一钱，陈皮二钱。服至六日，腹中肠鸣，冷食熔化，大便畅解二次，脉出舌润。次日黑苔转黄，胸宽思食矣。此证内实似虚，冷证似热，若不以形证相参，几至不救。要之。阳气未伤，身轻不厥，为可治也。", "16076": "附误治案，全椒胡子任寓王东木兄宅，二月上旬，舟中受寒，即中阴经。王兄知医，自以桂枝姜附治之。暂减，因无发热头痛，病者漫不为意，饮食不节，酒肉无忌，致邪不解。如此半月，坐食时忽不能起立，遂困卧于床，渐变神昏谬妄，舌黑而干。迎医治疗，不识寒邪入里，食满胃中，误以舌干谬妄，认为前服热药所致。因身有红影，遂作斑狂。初用生地黄、玄参、麦冬、石膏、升麻、黄连，不效。益加犀角、大黄，如斯三日，大便不动，而病愈笃。前医自逊不辨何证，易余诊视。脉则一息二至，似雀啄之象，证则舌干而黑，身痛不能转侧，口不能言，余辞不治。因告之曰：此水极似土，《内经》亢则害之证也。今舌干不渴，阴也。脉只二至，阴也。谬妄声低，乃为郑声，阴也。身重痛，不能转侧，阴也。夜则谵妄，日则但寐，阴也。身有疹影，乃寒极于内，逼阳于外，阴斑也。具此六阴，其舌干黑者，乃寒极于下，逼阳于上，假热也。因一假热而弃六阴，悖谬殆甚。王兄力嘱，勉用附子人参茯苓四逆汤，五日脉起三至，身轻能言，稍有生机，至六日真阳欲绝，夜汗三身，遂肉𥆧筋惕，脉脱亡阳，乃苦寒结阴，大便冷秘，竟成藏结，药难下膈，又延六日而殒。前方于长舌干齿燥，用四逆汤而愈。以此证之，诚误治也。存为舌鉴。", "16077": "余青岩广文令眷，年近三十，夏初得时疫伤寒，初起不恶寒，但发热身痛目赤。用败毒散，二日微汗，而热不退。延至六七日，身发稠密赤斑，狂乱谵语，声变北音，发则不识人，似属阳明热证，但脉细如丝而弦紧，口虽干而不渴。有议用凉膈化斑者，余以脉为主，作时疫阴斑亡阳危证，幸程至飞团弘春，定议佥同。主以真武理中合剂，重用参附者五日，阳回斑散，始克有生。此余致恭同道冢媳，因自如医，故弗疑而治效也。", "16078": "吴李履兄，庚午七月间得伤寒，初不知其病状，至半月后始延余治。诊其脉弦而紧，哕声越邻，舌苔灰黑，胸发紫斑，结硬而痛，脐旁动气，大便利水。询其何以至此，答云：初医说是伤寒，不效。又医说中暑，进香薷饮二剂，遂变至此，仍欲用化斑汤，未敢煎也。余曰：此阴斑也。因冷极于内，逼其阳于外，法在不治。幸神气未昏，手足未厥，初剂用四逆汤加茯苓、半夏、吴萸，温里以治哕，次日加人参以培阳。六剂斑散利止，惟呕哕胸结不开，仍用前剂，不加增减，半月后胸开痛止。方用白术理中，计用参斤许，附子斤许，两月方起床。贻害至今，遇病必须姜附。", "16079": "又令媳汪宅，未出阁闺女，甲申春月，感寒喉痛。浙医称火，遂恣食水果，饮冷伤肺，致增咳嗽。因不温散，咳甚则吐血。又易一医，竟认阴虚，用生地黄二冬二母元参等药，更加生藕汁半钟，令其冷服。服后即呕吐不止，气塞喉中，急以咳嗽吐血，求治于余。及诊其脉，沉弦而紧，搏手甚紧。余曰：岂愚我乎。此脉乃沉寒痼冷，未经温散，直入于里，其证必恶寒身痛，胸中阻塞，呕逆喉痛。问之果然，诸证皆备。余曰：此当表里双温，逼寒外解。遂用桂枝、细辛、赤芍、附子、干姜、吴萸、半夏、桔梗、甘草，二剂喉不痛，亦不呕矣。如斯六日，寒邪出表，发寒战，微热微汗，邪从外解，胸塞咳嗽皆减，能食米汤矣，彼畏热药，遂中止，旬日后，因前汗未周，遍身疼转为痛痹，仍以前方去吴萸、桔梗，加当归、木通，服七八日，痛减未痊，又畏热药而止。半月后余寒内搏，腹肋大痛，呻吟不绝，盖因吐血时值行经，服藕汁冷药，经因冷阻，故当经期，遂致大痛，复用前方加肉桂、五灵脂，去细辛、木通，六七日瘀血下而痛旋减。又畏热药中止，留痛经余证，至今未除。", "16080": "方安止郡丞，素虚寒，脉本细小。丙子年初冬，因酒后盖覆不周，感寒呕吐。次日即发热恶寒，身痛脉浮，犹有表证，作太阴病治法，用桂枝苍术炮姜二陈等药，温里解肌，得汗表解，旋入少阴，脉细如丝，舌黑下利，尿如煤水。因病重，又请一医参治，见舌黑而滑，作肾虚，用八味地黄汤加人参，甫一剂，即呕吐，半夜而增呃逆。因吐汗多，遂致亡阳，筋惕肉𥆧，大便频下，神昏蜷卧，急以真武汤换干姜，每剂人参五钱，附子三钱，日服三剂，如此十日，未少间断，方得神清利止。幸天生胃气，能进粥食，计用人参三斤，姜附二斤，医治两月，方获痊可。", "16081": "又令郎年十五岁，因夏月贪凉食冷，致仲秋发热腹痛。初幼科医治，十日不效，令余接医。诊脉弦紧，仍以童稚治法，用温中化滞，苍朴桂枝炮姜，又四五日，亦不效。以手按其痛处，则在脐旁季肋之下，此少阴部络，且年已十五，不可作童子医矣。已经汗而热不退，每日大便而痛不减，渐增烦躁，此内真寒而外假寒，少阴病也，用茯苓四逆汤，暗投附子，恐病家之疑畏也。初煎服下，即热退，再煎挤渣服，即安卧。次日直告明用附子，照前药遵原方，加人参一钱。如此七日，热退痛除，即转咳嗽，前之季胁痛处，变为不能著席而卧。盖前痛乃外寒客于少阴，今之咳嗽，则因病而内虚寒。改用八味地黄汤加人参，十数剂咳止，方能侧卧。病后唾水，仍以八味地黄丸，两倍桂附，水叠为丸，服年余，乃唾止。", "16082": "江豫臣兄，戊辰夏病，初属周医治疗，五日后相招，脉则弦涩，身无大热，惟胸中饱胀，呕哕不息，前医用柴平汤不效。一医用枳实理中，亦不效。余详辨之，病似太阴，而多身热，又不下利，面目皆黄，又似阳明，而尿不赤，脉不长，口不渴，盖弦脉属肝，涩主血，病夜则独语，胸腹皆痛，岂畜血证乎。未敢遽投桃仁承气，先作厥阴畜血，以桂枝、赤芍、炮姜、半夏、陈皮、甘草，日投三剂，胸中遂宽。至第三日，竟属厥阴，少腹急痛，不及登桶，便下紫黑血块半盆，随昏晕大汗，尊堂慌迫，以人参两许，煎汤灌下。余急往诊，脉则散大，此气随血脱也。频以人参汤进之，方汗敛人清。立候前治周医，告之曰：伤寒蓄血已下，略去伤寒二字，惟有固气一法。周医首允，复同验舌，舌则全黑，议用人参五钱，白术三钱，附子、炮姜各二钱，甘草一钱。不易方者半月，舌黑全退，饮食大进，幸血下之后，不复再便。议去附子者三日，舌复全黑，加入附子旋退。计服参附药匝月方瘥。", "16083": "黄庶常翁令政，年近四十，于五月初旬，惟熟睡不醒，呼醒又睡，胸背胀痛，呕吐不能食，不知何病，招余诊视。脉沉细紧滑，恶寒足冷，以前病论之，此少阴中寒而兼痰饮也。经曰：少阴病但欲寐。此证是已。诸阳受气于胸中，转行于背。今胸背胀者，寒痰冷气，上参于阳部。幸未厥逆，急以四逆汤加半夏、茯苓，日投三剂。计用附子七钱五分，服至七日，即霍然起矣。", "16084": "黄迪人兄令眷，为方星垣兄之令爱也。夏月畏热贪凉，过餐生冷，八月初，患午后发热，腰疼腹痛，大便频泻，咳嗽带血。先医数位，皆主阴虚。病经半月，招余一诊，主以肺寒咳嗽，而用桂枝、炮姜，与诸医药不合，置而不用。逾半月病剧，又增呕哕喉痛，烦躁不寐，方宅令其复请，其脉弦紧，前病属厥阴，今病将入少阴矣。而病家素畏热药，病已至此，亦难顾忌。以桂枝、细辛、附子、干姜、赤芍、半夏、吴萸、木通、桔梗、甘草，姜枣为引，表里兼温。服至六七日，喉全不痛，得卧躁宁，泻亦大减。少阴病衰，仍归厥阴，现寒热混淆之证，尚咳嗽而不吐血，或小便不通，而痛不可解。服厥阴之乌梅丸则通。或两乳肿痛欲裂，以当归四逆汤加柴胡，而乳消。如此上下游走而痛者，又半月，皆以当归四逆汤加附子、干姜、茯苓、半夏，兼用乌梅丸，以治诸错杂之邪。盖始病皆未以伤寒治之，致寒邪伏于厥阴，不能外解。计服桂枝姜附药四十日，里气方温，发出周身大疮，如豆磊磊然，痛楚不堪。计又半月，邪渐解而疮渐愈。医治两月，方能举筋而食。盖厥阴主血，经云：厥阴病不解，必发痈脓者。此证是也。", "16085": "吴象采太学令堂，年近五十，春间得伤寒，初不知病状，经历四医，至四十日，始迎余治。诊得脉沉而紧，按之甚坚，全无和柔胃气，呕吐发呃，胸结如石，舌黑而滑，渴欲冷饮，而滴水不能纳。询其治法，初则发表，继则解肌，皆不效。后浙医包治，先用黄连、枳实，后用大黄、芒硝，惟下粪水，反逆上而结于胸。幸不烦躁下利厥冷，犹为可治。以生附子、生干姜、半夏、茯苓、吴萸，大剂与之，始能下咽，亦不觉辛辣。如此五日，胸前稍软，而下痛于腹矣。余曰：此病必原胃冷，误投凉药。若阳病结胸，岂堪此大辛大热。所以黄连、大黄，闪烁至坚冰，今得温剂，冰化为水，将必洞泄，勿谓热药致泻，乃前黄连、大黄未动也。倘利泻不止，仍属死证。至七日，果大泻不禁，其家以余先言，竟备终事。急用人参二钱，合理中汤一剂，入腹片时即止矣。续以理中汤调理一月而瘥。原籍山西，胃气本厚，病饿四十日，误治不伤，而人参一剂即应，所谓有胃气则生，此证足征矣。", "16086": "叶奉宇媳丁氏，孕三月，恶寒呕吐，腹痛下利。前医作霍乱治，至第三日腹痛而厥者，三次，回苏则喉无音而竟哑。前医辞不治，其母迎余诊。其脉尺寸皆伏，惟寸口尚应指。余曰：此少阴寒证，肾脉循喉咙，散舌本。经云：肾气厥，不至舌。今寒极于下，阳气不升，致喉无音，惟救病人，不能顾胎矣。病家唯唯，遂以四逆汤加桔梗，大剂灌下，片刻音出，再剂痛止，手足回温，脉亦渐出，第五日果胎堕，而产母无恙。若徘徊瞻顾，产母不救，而胎何能独存乎。", "16087": "许蔚南兄令眷，暑月因食瓜果，得夹阴伤寒，至第七日，迎余往真州，时当酷暑，诊其脉，数大无伦，重取无力，乃虚阳伏阴之脉。烦躁席地而卧者五日矣，身发赤斑，目赤畏亮，口渴频欲冷饮，复不能饮。前医不识夹阴，误为中暑，投以香薷，以致阴极似阳。余因其怀孕六月，姜附未敢即投，初用温中平剂，又属女病，不能亲视病容唇舌，脉大而虚，亦似暑证。恐热药伤胎，先以井底泥敷脐，以试其里之寒热，便投温剂，甫以泥沾腹皮，即叫冰冷入腹而痛。急令拭去，余曰：此真病状也。遂用茯苓四逆汤，茯苓三钱，附子二钱，干姜、人参各一钱五分，甘草五分，令煎成冷饮。余方撮药，病家惊畏而哭，谓人参、附子尽剂也。倘不效，奈何？有孕在怀，即药效，胎将奈何？余曰：经云：有故无殒，有病则病受，不伤胎也。正在迟疑，吴中璧兄曰：此吾女也，年少可再孕。接药加参，煎成立令服下。五日未寐之病人，得药便睡，醒则登床。再剂斑消热退，熟寐半夜。次日余辞曰：药效矣，病未除也，尚须药六日，倘畏热，予告去矣。病家云：药虽效，而附子、干姜，必致堕胎，汝去谁为先生任过耶。因留七日，每日人参五钱，附子四钱，干姜、白术三钱，甘草一钱，服六日，胎不堕。而病回后，足月产一女，今成育。", "16088": "吴云翼兄秋杪赴席，夜归已寐，半夜后寒战，呕吐汗多，次日微发热，他医作阳证伤寒，用汗法，汗后热愈甚，反增身痛腹疼。三日后就诊，脉细紧，身无大热，因思酒后已寐而病作，寒战不热，呕吐汗出，此病从中发，寒邪在里，不在表也。因药汗出，而身反疼，岂非误汗乎。初以桂枝理中汤解肌温里，二日不效。至夜即转少阴，而现亡阳烦躁，狂呼抚几而立，不能卧床，少腹急痛，肉𥆧筋惕，两足厥冷。急用四逆汤加人参三钱，夜投三剂，至四鼓方躁定，登床得寐。次日，夫妇悲泣畏死。余慰曰：昨夜应死，今日不死矣。改用真武汤加人参二钱，六日后方能坐于床。后用理中汤加减调治，半月方愈。治病须意会表里阴阳，此寒霍乱，初治即当用理中汤者。", "16089": "吴骏声大行令政，因经行半月不止腹痛相召。至诊其脉，则弦紧也。予曰：此非血虚之脉，必因经血虚而寒袭之也，其证必头痛身疼，发热呕逆。询之果然，初以桂枝、细辛、当归、赤芍、炮姜、二陈之剂。不应，邪因药发，渐增寒热头痛，胸膈胀满，呕哕不食，脉犹弦紧，全见厥阴经病。用当归四逆汤，加干姜、附子、半夏，表里双温，续续微汗，表解。因经行既久，血海空虚，邪乘虚而入血室，夜则妄见谵言，寒热混淆，胸中热痛，口干作渴，小便涩疼。煎剂用当归、赤芍、桂枝、木通、吴萸、附子、干姜、人参、甘草，兼服乌梅丸三十粒，以治烦热便痛错杂之邪，随病机之寒热而圆活治之。两月后，经水再至，方脱然而愈。", "16090": "吴隐南主政尊堂，因大劳后得时疫，初病但发热身痛，胸胀作呕，脉弦数。外无表证，此邪从内发，所谓混合三焦，难分经络者也。用芎苏饮疏解之，至第三日，两颐连颈肿痛，此邪由太少二阳而出，正合败毒散证。服二剂，邪不外解，次日，反内陷而入少阴，变为胸胀呕哕，烦躁不寐。因病增剧，日请数医，皆用柴胡、苍朴、半夏、青陈皮、枳壳。余虽日到，而诊视者五人，药剂杂投，余不能肩任。至第九日，脉变细疾，烦躁下利，干呕胸满，令汗自出，遂直告隐南曰：病危矣。不知连日所服何药，已传少阴，将致亡阳，若不急救，明日即不可治。遂立方立论，用茯苓四逆汤，茯苓三钱，附子二钱，干姜钱半，人参八分，甘草三分，留药为备卷，以俟众议。其日历医八位，皆曰不可服。延至二鼓，病人不躁，忽变为笑矣。隐南和笑为恶证，勉煎服半剂，即安睡。至四鼓醒，索余药尽剂服之，又熟睡。至天明，再请不准服四逆之医，又云当服矣，但造议宜减附加参。病家崇信，减附一半，加参一倍。甫下咽，即烦躁干呕，急复相招，竟去人参而加附子，随即相安。盖寒邪在少阴，重在附子，其加人参，不过助正气耳。终竟去人参，以俟邪尽，六日后，方甲人参理中汤加半夏，弥月乃安。病九日而传变三经，医不明经，何能治病。", "16091": "黄兰孕翁令政，年五十外，壬午隆冬，病伤寒，初不知何经受病。至第八日请治，脉则细紧而弦，呕哕痰涎，神昏但寐，腹痛下利，足冷舌灰，时发谵语。先治之医，犹用苍朴柴苓汤，作协热下利治，指谵语为实热。余曰：病经八日，正阳尽入阴之时，已经发汗消导，而神昏下利，将至亡阳。急用四逆汤以救其逆，安敢再肆疏削乎，撮附子、干姜、茯苓、半夏、甘草一剂而别。前医阻挠不决，置药不煎。至夜病剧，卜之灶神，神允余药，方敢煎服。服之即得寐，醒后神清。次日再招，相信委治，诊脉稍和，即以前药加人参一钱，日服二剂。至五日，哕利方止，继用附子理中汤，半月始愈。", "16092": "吴佩六兄由歙暑月到扬，路受风邪，脉浮弦滑，头疼身痛，寒热而呕。初一医用桂枝、细辛、干姜、附子作厥阴治，失之过重。继余往诊，作风暑夹食，以柴葛平胃投之，因而大汗。殊不知风暑之汗，不足畏也。浙医曰：汗多亡阳，误治之矣。急用人参、黄耆敛汗，劝其进食，六七日邪不解，日晡寒热。又作疟治，用人参、何首乌截疟，复增泄泻矣。此景何翁之堂弟也。复招余治，云系代彼里中觅地，家中妻子多人，倘不治，关击匪轻，切嘱甚力。余曰：此阳明病，须断饮食，方敢经手。病家唯唯。复用十日前柴葛平胃等药，因服首乌而作泻，加入炮姜，寒热渐轻。五日后积滞频下，七八日霍然而起。病者笑曰：省用人参银数两矣。", "16093": "君荣族叔，居镇江，年三十外，夏月患伤寒，初不知何证。服京口医家药，发汗过多，即小便难出。又用五苓散，服下旋通旋闭，点滴难出，少腹胀满，头汗时出，迎余渡江。脉虚大而迟，坐不能卧，气微促，不小便者三日矣。余曰：此误汗亡阳，非大剂人参不能救。时京口老医黄石仓适至，余与彼两议相同，遂用人参一两，茯苓三钱，附子一钱。服下合目片时，略有尿意，又进一剂微滴，夜又一剂，五更则频频而出，遂不禁矣。次日再以理中汤加茯苓、益智仁调治半月而康。后七年，中暑而病，尿又不通，力薄不能市参，终至不救。盖此人纵欲，肾气大虚，每病必撄此患。", "16094": "瓜镇侯公遴，深秋伤寒，始自以为疟，饮食如常，寒热渐甚。至七日方迎至，则阳明证矣。服药五日，渐变神昏谵语，胸腹满痛，舌干不饮水，小便清长，转为畜血证。遂用桃仁承气汤，下黑血碗许，即热退神清。次日忽小便不通，犹有点滴可出，用五苓不效，乃太阳药也。病者素清癯，年近六十，脉细而涩，此畜血暴下，阴气必虚。经曰：无阴则阳无以化。原病阳明畜血，仍用阳明之猪苓汤，汤用阿胶，是滋阴血者也。以本方猪苓、茯苓、泽泻、滑石、阿胶，而加桂枝、芍药，以和营血，甫一剂，小便如涌泉矣。", "16095": "方伦远兄族弟，年未二十，自歙到扬，秋杪伤寒，先为扬城某医所治，至八日迎余。诊得脉弦而细，身微热，足冷呕逆，胸满咳嗽喉痛，而吐血水，腹痛下利，阴茎内痛而尿血，夜则谵语。此证阴阳错杂，寒热混淆，乃厥阴经病也。检前医之中，乃柴苓汤也，辞不治。病人泣曰：我孤子也，家有老母，乞怜而救之。予曰：此厥阴经病，宜表里兼温，使邪外解，前医不识邪气内搏，故呕哕下利，厥阴主血，邪搏血，故上下皆出，用药与前医天渊，必须桂附，如不效，必归怨于热药矣。伦远答以大数决不归怨。遂用桂枝、细辛、当归、赤芍、干姜、附子、木通、桔梗、甘草，姜枣为引，解肌温里，以治身热喉痛，腹疼下利，外用乌梅丸以治呕哕吐血尿血，而祛寒热混淆之邪。余以一念矜怜，遂忘旁议，不意竟以汤丸二药，坚治半月而获痊。病起方初冬，而病者日已围炉烘足，设以吐血尿血为热证，岂不殆哉。", "16096": "汪方伯潘姓纪纲，寒夜随赴席，食席余冷物，五鼓回家，即腹痛作泻，次日早辰，则喉音顿哑，外无他证，手足不冷，但脉沉细耳。《灵枢经》曰：寒中少阴，卒然而哑，因腹痛泻利后随哑，脉又沉细，全属少阴无疑矣。初用麻黄附子细辛汤一剂，则有喘汗之意，其身不热，寒不在表，而全入于里。易用四逆汤加桔梗，服二日，脉方略起，计每日用附子七钱五分。至第四日，犹喘厥片时，醒得微汗，其音始出。黄成九兄未出室之女，壬戌冬杪，小便后卒然而哑，予作少阴中寒，用麻黄附子细辛汤，其时某医畏热不用，后七八日竟至不救。（附记）", "16097": "方纯石兄，五月初，两颐肿痛，先为疡科所医，外敷内服，不知何药，至八日见招，肿势将陷，寒势交作。余曰：此时行之虾蟆温也。用荆防败毒散二剂，表热随退，肿消大半。不虞少阳之邪，直入厥阴，脉变沉弦，喉痛厥冷，呕吐胸胀。改用当归四逆汤，加附子、干姜、吴萸。坚服三四日，得微汗，喉不痛而呕止，脉起足温尚有微肿。病家以为愈矣，次日往看，肿处尽消，但笑不休，问其所笑何事。答曰：我亦不知，脉复沉细，舌有灰苔，已笑半日矣。追思初病，必服凉药，所以少阳传入厥阴，厥阴不解，又传入少阴，少阴寒水，上逼心火，心为水逼，发声为笑。不早治之，将亡阳谵语，不可治矣。幸孙叶两医，以予言不谬，遂用大剂四逆汤，加人参三钱。服后片时，略睡须臾醒，即笑止，一昼夜共服三剂。次日肿处复起，仍用当归四逆汤，加附子、干姜，三四日肿处回阳发痒起皮而解。其时有不解事者，谓予多用姜附而致狂，医难用药，有如此夫。", "16098": "又令眷隔十数日，两颐亦肿而不痛，若属少阳，则脉当弦数身热。今脉弦细，身不热，亦属厥阴。始终以当归四逆汤加附子、干姜治之。服至半月，方从外解，发热脉浮，身发瘾疹，作痒而愈。彼因未服凉药，故不致内陷呕吐逆冷，而传少阴发笑也。时行虾蟆温一证，稽之前贤治法，皆主少阳，而用辛凉，并无传经之说。然虞天民《医学正传》，谓喉痹证不可遽投凉剂，恐上热未除，中寒复生，变为发喘不休，将不可治，又陈若虚《外科正宗》亦云：饥年毋攻时毒。夫饥年指正气虚也。即此二说，则前贤之发明久矣。", "16099": "邵子易兄，四月间自江右回扬，素有中寒痰证，数日腹中微痛，渐次痛甚。先医者已用炮姜附子苍朴温消，继用六君子加香砂，作太阴寒治，而痛益甚。迎余往诊，其脉沉细而紧，汗出沾衣，面赤腹痛，腹形胀大，干呕欲吐，小便频数，大便下利，少阴证全。此因前之苍朴耗气，继用白术闭气，是以不效也。但久痛伤气，须急扶阳，不宜疏气。以附子、干姜为君，肉桂、人参为臣，吴萸、甘草为佐。用生附子三钱，人参、干姜二钱，肉桂、吴萸、甘草一钱，日三剂。三日后减一剂，又三日痛止而愈。", "16100": "瓜镇赵姓，伤寒半月余，前医发表攻里俱备。已经两下，心下痞硬，肠鸣下利，干呕心烦，形容瘦削，六脉沉细，前医辞治。其母求救，予曰：胸痞硬而不痛，非结胸也。因两下胃而气逆，故痞硬，惟温中泻实一法可施，以甘草泻心汤主之。用黄连、干姜、甘草、半夏、大枣，二剂知，六剂即效。盖前治之不如法，所以易效也。", "16101": "方诞初孝廉，盛暑患咳嗽吐血，午后发热，腹痛作泻，病四五日，自以为虚损，觅广三七治吐血，招余参治。诊得脉弦细而紧，舌紫苔白，两足冰冷，咳嗽血涎。余曰：此厥阴伤寒，非虚也，乃恣食生冷，畏热贪凉，寒中肝经。肝主血，此厥气上逆而吐血涎。形寒饮冷则伤肺，肺寒则咳。冷饮注于下焦，则腹痛下利。拟用桂枝、细辛、赤芍、附子、干姜、吴萸、半夏、茯苓、甘草。呈方令尊翁，未敢用药，因药太辛热，不合病状故也。幸其令岳主持，方敢投剂。服至三日，则得汗而热退。再四剂咳泻亦宁，而阴茎内痛。兼服乌梅丸煎剂，减去吴萸，加当归、木通，合当归四逆汤，又两日，小便旋通，七日后步行于途矣。", "16102": "吴非昨表侄，初夏喉痛，疡医不辨寒热，用黄连四剂，喉痛止而变呕吐，胁肋大痛，三四日不进米饮矣。令尊若翊兄，急迫商之于余。诊其脉弦细而紧，此厥阴吐逆，外科谓之过关喉痹，因误用苦寒直折，痹下结于胃口矣。先用乌梅丸三十粒，以开其寒热格拒之邪。日进三服，至夜吐止而能纳食矣。即转腹痛，手不可按，此上焦之寒，下注于中焦。急用四逆汤加桂苓人参，日进四剂，服附子一两。如此六七日，腹大痛方止，尚微痛作泻。后乃若翊兄自行调治而愈。", "16103": "乔揆文兄令眷，年近四十，夏月畏热喜凉，以水渍巾披身，瓜果无忌。初胃中胀痛，手足酸麻，作呕欲吐。余初诊脉细紧无力，言系中寒停冷之病。因脉细紧，用六君子汤加桂枝、干姜，旁议盛暑安得用此热剂，易医服药。闻用苍朴二陈消导之药，治经九日，病剧复招。则寒直入少阴，干呕烦躁，脉紧近疾，腰痛似折，常以滚水渍巾熨之，冷则又易，气塞喉中，水饮不纳，甲紫舌黑，骨寒而痛，病势危笃。余曰：阴极似阳，阴阳格拒，若能纳药，方可治疗。先以半硫丸一钱，开其格拒之寒，服下不吐。继以生附子、生干姜各三钱，半夏、茯苓二钱，吴萸一钱，频频灌下，方呕止躁定。遂换熟附减药，如斯九日，诸证皆退。遂改用理中汤加人参一钱，温补五日，忽然呕吐血水。病家虽不言，而意谓前之姜附贻害也。余曰：始病太阴中寒，脉既无力，则宜温胃，误用消克，以致伤阳，阳消阴盛，致传少阴，少阴得温，转属厥阴，此由重致轻也。但厥阴寒势错杂，忽阴忽阳，缠绵时日耳。旁议疑信相半，遂多延众医。有医竟认阴虚而用地黄者，有医见余用桂枝、吴萸，遂收箱不用药而去者。惟孙其犹亦主厥阴，用当归四逆加附子吴萸。于是病家不为他医所惑，余得尽心治之，皆以当归四逆汤。用桂枝、当归、赤芍、半夏、茯苓、吴萸、木通、甘草，姜枣为引，兼以乌梅丸治其假热。如此半月，渐次呕止，而血亦不吐矣。病愈多劳，遂脉转数，内热咳嗽而吐血，左胁不能卧，竟有阴虚咳嗽之机。盖厥阴风木，内藏相火。乙癸同源，暂用六味地黄汤，以滋化源，且服辛热药一月有余，阴气不无受伤，不得不权机应变。服半月，热退嗽止，脉亦不数。虚热方退，而中寒复生，且值秋杪，霍乱吐泻大作，胸腹胀满，脉来细紧，温剂难投，惟平调胃气，以俟其胜复，半月方平。再以参、术、归、芍、橘红、茯苓、丹皮、石斛，平补半月，气血稍充，余邪外解，周身发出瘾疹，作痒起皮。盖夏月水中之寒邪，化热出表也。从前各证，至此方除，计治五阅月，足征厥阴病寒热混淆不一，邪气出入不常。若非病家信任之专，或从证，或从脉，随病变迁，圆机施治，岂能获痊乎。", "16104": "王汝振仆妇，年近三十，冬杪患头痛，以无发热恶寒表证，前医遂以火治之。至三日，痛益甚，头疼如裂，小便频出无度。予诊之，六脉弦紧而细，面赤如妆，此厥阴头痛也。三阴惟厥阴有头痛，以厥阴之络，络于巅顶也。检前方乃石膏、栀子，误用苦寒，致寒极于下，逼阳于上，面赤戴阳，头痛如破。且妇人厥阴之络，内络廷孔。廷孔者，溺孔之端也。寒客内络，故小便频数矣。幸未厥冷下利，邪犹在经，用桂枝、赤芍、细辛、生姜，以解经邪，用附子、干姜、吴萸、半夏，以温里冷，日服三剂。先出冷汗，后出热汗，头痛便频随止。此藜藿之人，里气不虚，故邪易解也。", "16105": "吴南皋兄家人，年二十余，五月间得伤寒。初系他医所治，至八九日忽发狂谵语，躁欲坠楼，其妻拉住，挥拳击妇，致妇胎堕，数人不能制。用醋炭熏鼻，方能握手诊脉。脉则散大无伦，面赤戴阳。此误服凉药，亡阳谵语，瞬息即脱，众药陈几，有用白虎汤者，承气汤者，柴胡凉膈者。病家云：因服香薷凉药，大汗至此，故不敢再煎。求余决之。余辞不治，主人力嘱，遂以真武汤本方易干姜，用生附子三钱，令其煎成冷饮。服后片时，即登床就枕，略睡片刻，醒则再剂，加人参一钱，熟睡两时，即热退神清，询其前事，皆云不知。继用理中汤六七日而愈。其妇因击堕胎而反殒。", "16106": "郭元威学博令政，平素虚弱，正月杪夜发寒战，寒后发热。次日招诊，脉细紧而近于疾，其证发热头疼，左胁痛甚，上至臂，下至腰足，皆牵引而痛，干呕胸胀。因脉沉细，作厥阴病主治．用桂枝、细辛、赤芍、附子、干姜、半夏、茯苓、吴萸、木通、甘草，姜枣为引。四剂上身微汗，痛减而下体痛甚。因向有脚气证，加独活。至第五日有出少阳之机，以前剂稍加柴胡，令其微汗。不虞亲属覆以重裘，逼汗大出，虽热退半日，至夜即烦躁不寐，呻吟不绝，胸中大热，欲饮冷水。暮夜再诊，脉变数大无伦，重取近散。此汗多亡阳也，急以茯苓四逆汤救之。用人参三钱，茯苓四钱，附子二钱，干姜一钱，甘草五分。一剂稍安，二剂得寐，一夜三剂，至天明热退而安。随增咳嗽，半身不能侧卧，此又属肝肾阴虚，伤寒病后，每多此证。若认少阳而用柴胡二陈苏杏，必致不救。仍以前厥阴为主病，用桂枝、当归、白芍、茯苓、附子、甘草、人参、五味子，姜枣为引。十数剂咳止，可侧卧矣。半月后，紧脉退尽，方去桂、附，以归、芍、参、术、苓、草，平补而愈。", "16107": "吴方平表侄，冬月夜饮归，睡后有胁作痛。初系浙医作少阳治法，以柴胡、白芍、青皮、贝母、香附等药治之，七八日痛愈甚，至夜坐不能卧者三日矣。招余往治。脉沉弦而紧，足冷畏寒，胸满不能食，胁肋皆痛，不能著席而卧，舌紫微喘。余告曰：此厥阴伤寒，厥气上逆，不得卧而喘，病关少阴。若增烦躁下利，则全属少阴，不可治矣。今并无少阳寒热头眩，口苦干呕，脉弦数等证，何得以少阳治之。遂用官桂、赤芍、吴萸、附子、干姜、半夏、甘草，温经以下厥气。服至七日，方回阳，发热微汗，痛止喘定，就枕得卧而痊。若作少阳治法，不知作何景状也。", "16108": "汪文年兄，冬月伤寒，初诊脉沉细紧，少腹背皆痛，外证反发热头疼。余曰：此阳证阴脉，法当难治，应以脉为主，作厥阴病治法，不用表散，惟主温经。用桂枝、细辛、赤芍、附子、干姜、吴萸、甘草、生姜，服三日，得微汗，头痛表热尽退，腹中尚隐隐而痛。如此六七日，胸中亦不饥，惟进清米饮，脉亦不甚起，正为可虑。盖以厥阴不回阳外解，邪搏于里，恐转少阴，而变下利也。至夜果腹痛，下黑血数碗，即眩晕汗出。次日往诊，脉仍如前之细小，未因脱血散乱，幸前预用桂附温经，故不致气随血脱。彼之尊人，十数年前，夏月病此，医作暑疗，血下随脱，病人恐甚。急用真武汤日投三剂，每剂加人参四钱，附子三钱，茯苓、干姜、白术各二钱，赤芍一钱。幸下血之后，更不再便。如此大剂，七日后方减参附，加甘草，合理中汤，调治一月而愈。", "16109": "汪次履兄，年逾二十，夜寝发寒战而醒，战后发热。次日迎诊，大热，肩背皆痛，但头不疼，而面赤，脉亦浮大，惟重按无力，肠鸣欲便，知为夹阴伤寒。用桂枝、炮姜、苍术、赤芍、二陈两剂。次日再诊，各证俱减。照前留药二剂，嘱其一日全服，勿进饮食。少年畏药，只服一剂，更因便通热退，遂食饭行走，两日不药。至三日，其病复作，大热身痛足冷，呻吟不息，胸中气塞，口中臭气逼人，自云吐痰亦臭，脉细沉紧。此乃病中不慎，复传少阴矣。盖府气本于肾，脉既细紧，断非胃热。肾藏寒邪，逼真气上出于口，亢害之证。初病已汗已便，今病复作，何得旋有实热，此为少阴身热可知。用茯苓四逆汤，加桂枝、半夏，温里解肌。如此六日，热退便通，口亦不臭。但里寒未解，腹痛便溏，不思饮食，仍用姜、附、桂、苓、人参、半夏、甘草，六七日方能起坐。计服参附桂苓理中汤三十六日，因事劳辍药一日，即寒战厥冷，倍用参附方回。又温补半月乃健。若因口臭遂为胃热，不几大误耶。", "16110": "汪象成兄令眷，年三十外，素有肋下脐旁寒积，每发必痛，吐痰饮，非一日矣。乙酉年初秋，复感外寒，而旧病同举。初不以为病，医者亦以姜附轻剂治之，至第九日，病势沉重，路截邀治。则两尺脉全无，呕呃不已，手足厥冷，气塞喉中，耳聋神昏下利。予曰：病剧矣，此少阴证也，非重剂不能回生。先以半硫丸治呃，继用生附子三钱，干姜、半夏、茯苓各二钱，吴茱萸五分，日投四剂。虽未变坏，阳总不回，如此三日。隔墙厨内烹雀，彼忽知之，急索欲食。予曰：此真阳飞越，将亡阳矣，急用四逆加人参，药未熟，即大笑不止，随即服药，而狂呼挥拳乱殴犹甚。急服再剂，方宁而寐。次日问之，全然不知。若非知机急救，岂不亡阳而逝哉。继用四逆加人参、桂苓、半夏，日投二剂，月余方阳回利止。复冷秘，吞半硫丸十日，大便乃通，皆稀溏粪水。因脐旁动气，始终皆属前方。若加白术理中汤，便胀痛不已，以动气禁用白术也。", "16111": "汪其晖兄，秋夜深坐，游湖食冷，遂致胸腹不宽，日日大便，无寒热身痛诸证。自以为停食，而前医犹用香薷。延至第三日，邀予便诊。虽不出门，犹堂前会客，其脉濡细带紧。此寒中太阴，宜温中断食。余用炮姜、桂枝、苍、朴、二陈等药，病人全不介意。日惟服药一剂，间日再诊，脉变弦紧，以危言告之。彼方不食，其夜则呕哕腹痛，身热大困矣。此太阴病不解，而传厥阴，改用桂枝、干姜、吴萸、赤芍、半夏、苓、草。立有厥阴病案，预言防下利。因前医用香薷，故未即投附子。其内亲吴焕若兄，密加附子入药，哕遂止，随腹痛下利脓血，日夜二十余次。病家以为痢疾，余告曰：此厥阴病下利脓血也，若作痢疾处治，而用香槟，则不救矣。即以当归四逆汤本方，加干姜、熟附，日投二剂，每夜通身微汗，次日利即少减。如此七日，药不易方，七夜皆汗而利止矣。此厥阴外解证也。后以脉细紧未退，仍用前方，去干姜、吴萸。至十余日，大便方通，饮食可进而愈。", "16112": "绥远族侄，八月杪步至予家就诊，自称病疟求治，盖前医之言也。及诊脉，则沉弦紧而无力。予曰：何轻视之，此厥阴伤寒也，必手足微冷，寒而不热，少腹隐痛，腰腿冷疼，有是病否？应曰：均有之。视其舌色紫无苔，即投桂枝、细辛、赤芍、半夏、熟附子、干姜、甘草。次日往诊，则手回温，脉不沉而但弦紧，少腹隐痛，下痢血水而增呕矣。此厥阴内搏之证，遂全用当归四逆，加吴萸、附子。七日出表，发热烦躁，汗出而解，进粥食矣。被友拉出门巷，语多时，受冷而劳，次日脉反彰大，身热腹痛，下利足冷，胸满作呕。仍用前剂，则汗出脉陷，其细如丝，证转少阴，遂用四逆汤加人参、肉桂、茯苓。如此不易方者半月，方得利止，脉渐出，便实而愈。前汪病案，乃太阴传厥阴，里不甚虚，仍从外解，此初病即属厥阴，得温里法，亦外解矣。因劳而复里虚，遂传少阴，少阴无外解之理，所以直用温里而愈。此伤寒表里之大关也。", "16113": "张其相兄家女婢，年十五岁，初冬得病，因循未服药。延至四五日，头疼身痛，微热恶寒，气塞喉中，呕哕不纳药，脉沉细紧。浙医认头疼为太阳，因脉沉而用姜附，杂以羌防白芷苍朴，不能下咽。次日无可奈何，改用柴葛平胃以试之，不得效。迎余往诊，而前证具在。予曰：此厥阴表里齐病，宜用温里，但阴寒上逆，竟成格阳矣。先用乌梅丸二十丸，以通其格拒，呕止能下药。随用桂枝、细辛、干姜、熟附、吴萸、赤芍、半夏、赤苓，如此四日，两得微汗，表证皆除，惟骨寒痛未减。至五日即入少阴，下利五次，彻夜号呼，齿皆枯垢，鼻有烟煤，手足厥冷，脉微欲绝，脱阳见鬼，拟其夜必死，但形神未脱，怜而救之。遂用生附子五钱，干姜三钱，茯苓、甘草各二钱，一剂手温，再剂利止，脉亦微出。如斯重剂，七日方获回阳而愈。若以人贱忽之，必无生理矣。", "16114": "程靖宋兄，就诊于亲家李宅，尚能强步，但称左胁痛甚，已四五日矣。诊其脉弦紧而细，两手清冷，面色纯青，咳嗽则痛引头胁。此寒中厥阴肝经，须温经散寒，痛方得止。用桂枝、细辛、当归、赤芍、吴萸、干姜、半夏、甘草，二剂痛减。再剂加附子，遂大汗而痛除。又二剂，又汗而痛全止。但少腹微痛，似动气之状，三四日通夜不寐。幸不烦躁，脉则细涩无力，此必因两汗亡阳而不寐也。仿大青龙误汗法，用真武汤去白术加人参、当归，易炮姜，加肉桂，收阴摄阳，如此五六日，方能熟寐而愈。此乃厥阴病，惟用桂枝、细辛，尚汗出亡阳，几至危殆。若少阴误汗，更当何如哉。", "16115": "瓜镇卞祥生，七月外感内伤，午后潮热，天明汗出而解。前医误认阴虚，更劝其加餐肉食。至七八日食塞胸中，药饮难下，招余往诊。其脉细数，俨似阴虚，重按则滑而有力，此外感轻而内伤重也。用仲景泻心汤法，以柴胡解外之晡热，以黄连、干姜、半夏、枳实，泻胃中之湿热。但中宫胶固，恐发呃则难治。其夜果呃，次日更加干姜，七八日胸次方开，食滞出胃。然后以小承气汤两下而愈，计断食十二日。盖此证脉细，乃食结中宫；下午发热，乃阳明内实；五更盗汗，乃湿热熏蒸。三证非虚而是实。若以脉细误认为虚，不以滑而有力为实热，岂不再误耶。", "16116": "行九族弟，夏月得伤寒，初医者不知何药。至第八日招诊，脉大而数，按则无力，身有微热，烦而不寐者三日矣。云已发汗解肌消导，皆不效，相商议下。余曰：脉大为病进，今八日已阳尽入阴之期，而汗和不解，脉反彰大，此虚阳伏阴，非温不效。用茯苓四逆汤温里收阳。彼不肯服，延扬世医决之。彼云：脉大面红，口中大臭，乃阳明内实，非大凉大下不解。见余四逆汤，摇手而去。又迎团弘春决之。弘春曰：阳气外越，里实虚寒，急服无疑。犹不敢用。余因族谊，迂道复探，则席地而卧，烦躁不宁。余曰：病急矣，若再不药，必寒战大汗而亡阳矣。令急煎药，坐视其下咽。片刻面白，合目欲卧，扶其登榻。再留二剂，通夜服完。次日脉敛热退，口亦不臭，而手足反清，就枕便寐，全见少阴本证。如此温剂十日，继用理中汤半月方愈。", "16117": "巴绣天主政，隆冬檐际脱裘，易近体之衣，觉受寒，尚不为困，本夜又梦遗，次日即寒战头疼，发热腰痛，脉反细紧。病属阳证阴脉，幸脉但细而不沉，犹有头痛身热，乃厥阴表证，用当归四逆汤温里散寒。以桂枝、细辛、赤芍、附子、干姜、半夏、茯苓、甘草，姜枣为引。因有急务，遂昼夜四剂，三更得汗，五更即乘舆远出，自为无恙。次日即饮酒茹荤，三日回家，午后又寒战发热，更增呕吐痰涎，仍用前剂，夜半得汗，热退而解。次日又复乘船远出，于路寒战发热，吐泻腹痛而归，自称疟疾。余曰：非也。疟之为病，必受邪于半表，蓄久而发，此证先日受寒，次日即病，脉不浮弦，断非疟疾，乃厥阴表证，而兼里病也。仍用前剂，因增腹痛下利，脉变细紧无力，加人参以固里，则寒轻汗少。四剂寒热下利皆减。如斯三四日，寒热顿止，呕泻皆宁。姜附药服至十二日，退用当归四逆汤本方，去细辛而加参术，温补匝月而康。", "16118": "辛酉仲夏，予迁郡城之次年，其时疫气盛行，因看一贫人斗室之内，病方出汗，旋即大便，就床诊视，染其臭汗之气，比时遂觉身麻，而犹应酬如常，至第三日病发，头眩欲仆，身痛呕哕外，无大热，即腹痛下利，脉沉细而紧。盖本质孱弱，初病邪气即入少阴，脉证如斯，不得不用姜附人参以温里。如此六七日，里温利止，而疫气遂彰，谵言狂妄，胸发赤斑数点，舌苔淡黄而生绿点，耳聋神昏，脉转弦数，此由阴而出阳，必须汗解之证也。病剧回真州，诸医束手不治。适山紫家叔来探问，数当不死。余忽清爽，细道病源，谓非正伤寒，乃染时疫，缘本质虚寒，邪气直入少阴，服参附里气得温，逼邪外发，但正气甚弱，不能作汗。今脉弦耳聋，邪在少阳，乞用小柴胡汤本方，加人参三钱，必然取效。山紫家叔遂照古方，一味不加增减，而入人参三钱，一剂得寐，再剂又熟寐。夜又进一剂，中夜遂大汗至五更，次日即霍然矣。继服人参半斤始健。", "16119": "戊寅年九月杪，余年六十一矣，又染时疫，初则巅顶微疼，夜则两腿酸痛，次日即呕哕，午后寒热似疟，而无汗解，夜半热退，邪气混合三焦，难分经络，若六七日不得汗，势必要死。预召门人熊青选，授以治法。而脉弦紧无常，寒则细，热即数，漫无专经。惟以初病巅疼，作厥阴病治。用桂枝、细辛、赤芍、半夏、姜、附、吴萸、人参、甘草，解肌温里。如斯五日，病不减而增剧。至六日，中夜寒热不得汗，烦躁欲死。与门人商之，余非邪气实不得汗，乃正气虚不能汗也。以人参三钱，生姜三钱，仿露姜饮法试之。煎服颇安，渣再煎服，有欲睡之机，而胃中饥甚，索米饮。家人见热甚不与，余勉起床，取糕数片，索汤，家人不得已，与汤一碗，将糕泡化，尽食之，觉胸中泰然，就枕片刻，即汗出，自顶至瞳，衣为之湿，至五更汗方敛，次日即全解矣。经云：汗生于谷。良不诬也，以此征之。时疫邪不传胃，不能尽绝谷气。", "16120": "杨紫澜兄，夜劳不寐者屡日，春杪犹寒，致受夜冷，直犯阴经。初以受寒就诊，脉则弦紧，恶寒身痛，但微热耳。用温经散寒药二剂，略减，自不为意，起居饮食如常。寒未外解，数日后，内搏于里，肛门坠痛，遂易疡科作痔医之。延数日，痔不溃，亦不为楚，即转痛于季肋之后，近腰软处。又作肝痈治之，遂夜发热烦躁作渴，通夜不寐，复迎余治。脉沉紧而细，两足厥冷，舌紫苔白。余辨曰：非痈也。初病脉弦紧，原属夹阴，邪在表里之间，因不治疗，传至少阴，肛坠而痛。盖少阴肾藏，开窍于二阴也，失之不温，今入肾之本位矣。且脉不数，痛处按之，内无硬形，外不作热，而痛肋反欲著席而卧，其无实肿可知，断非内痈，皆因失于温里。寒极于内，逼阳于外，所以夜热。阳既外越，里必虚寒，所以阴躁不寐。下冷必阳厥于上，所以渴而欲饮也。今已手足厥冷，脉已沉细，若不急温，必加下利，则难治矣。而杨兄素恶热药，奈病在厥少二阴之本，非同阳证可以泛治，不得不肩任之。遂以官桂、当归、赤芍、干姜、茯苓、甘草，暗投附子二钱，以防下利。夜服一剂，半夜安寝，烦躁惟一刻耳。次日又服二剂，则热退痛减，再二剂痛止全卧，手足回温，肛亦不坠矣，如此药五日，即霍然而起，续以温补药而痊。此证与三卷张紫山小便频数似痔之案相同。", "16121": "汪静夫兄，五月初一真州得病，服过羌防柴葛药七剂，初四日回扬，扬医犹以真州套剂治之，皆前不效药也。令余婿朱与白相招诊，则脉沉而紧，两尺如丝，汗多而热不退，头疼身痛，呻吟不能转侧，烦躁欲席地而卧，干呕欲饮冷水，复不能饮，舌紫无苔，少腹硬痛。以《伤寒论》之阳证阴脉，法当不治。因有头痛，定属厥阴，又多烦躁，兼有少阴，须两经并治。用桂枝、赤芍、细辛、附子、干姜、茯苓、半夏、甘草八味投之。二剂躁定熟寐，而身痛减半。又四剂脉起不呕，能食米饮矣。忽尿茎内痛，小便黄赤，乃厥阴阳回吉兆。而旁人遂谓余误用热药，劝进灯心汤。因停余药，延至午后，即腹痛下利，初硬后溏，抵暮复加阴躁，起床抱柱而立，此真武汤证擗地就实之状。因便后里虚亡阳之机已露，遂不从旁人之言，仍煎余药，服后躁定而安卧。至初七日清辰再诊，全属少阴证矣，脉沉细，手足冷汗不止，肠鸣下利，两腿筋惕。急用大剂真武汤一剂，至午厥回汗止，犹有利状。遂加人参，昼夜三剂，计用附子一两，人参六钱，方阳回利止。因有身热腰疼，远迎京口名家，犹谓表邪未解，里滞未清，药用柴葛二陈，病人畏不敢煎，然终以身热为患。余告曰：少阴身热，乃为可治，若厥冷则下利不止矣。余所以留热，以存阳也。竟服真武汤五日，少阴病衰，余邪仍转厥阴，耳前时或一痛，夜则气上冲喉，渴而多饮，皆厥阴表证，恐致发颐，必怨热药。遂以当归四逆汤本方，不加姜附，少入人参，以助正气。二日四剂，周身微微似汗者一昼夜，邪尽外解，而口渴气冲耳痛茎痛全愈矣。因旁议纷纷，除去姜桂，甫五日，即腹痛作泻，复用桂枝人参汤五日，便实而痊，续用平补药十余日。因食苹果，又胸胀不食，胃本虚寒，岂余浪投辛热。今病已痊，而附子之谤不息，执肤浅之见，妄论是非，《内经》不失人情四字，医家诚戛戛乎难之矣。", "16122": "吴西烁兄，酷暑染病，身无大热，但称下体酸痛，多饥欲食，小便频出，下气频泄而不臭，口中反秽气逼人，舌紫苔白，自以为虚，又疑为暑。及诊脉则弦紧而细，皆阴脉也，无经络之可凭。若谓口臭多饥为阳明，而脉不长大，无恶寒发热头疼，全非阳证，且不腹满自利，断非太阴。今脉弦细而紧，心悬如病饥，腐气上逆，清气下泄，舌紫便频，皆属厥少二阴之病。初病不暴者，邪从中发，其势未彰，乃时疫也。因脉细紧，用桂枝、赤芍、细辛、独活、半夏、干姜、赤苓、甘草，温里解肌，俾邪外出，二剂颇安。遂加附子，服后一刻，即周身皆麻。病者畏，停后剂。三日后，其邪乃发，遂头眩身热，烦躁作渴，身疼腹痛，脉仍细紧，全现厥阴经证。竟用前剂，得汗数身，邪气稍解。病者因夜烦躁，令去干姜。次日即下利呕哕，易以温里治法，用附子干姜、茯苓、半夏、甘草四剂，则热退利止，渐次则愈。数日后，食鲜鸡海味，即发热腹痛，下利脓血，日夜十余次，脉复弦大而紧，自称痢疾。余曰：乃厥阴余邪，因复而下利脓血，非痢疾也。脉变弦大，宜从汗解。复用厥阴之当归四逆汤，加干姜、附子以温里。二剂大汗，病遂减半。四剂热退利止。次日忽阴囊肿大如瓜，痛不能立，称旧疝复发。余曰：尚是厥阴余邪，甫离后阴，又注前阴，非疝也。仍用前剂，疝亦旋消。因脉尚弦，知邪未尽，药不易方。二剂后，周身皆麻，如初服附子状，随即手足拘挛，颈项强直，俨如痉证，少刻大汗，通身痉麻皆定。余慰之曰：可不药矣。病者但称口渴，胸中热甚，此厥阴逆上之虚阳，令吞乌梅丸二十粒，顷刻渴热皆除，脱然而解。病家因麻痉惊骇，延他医诊视，不识病，因但称附子毒而已。嗟乎！殊不知初服附子麻者，欲作汗也。若不畏而再剂，必大汗而解，失此汗机，使邪蟠踞于表里之间，入藏则利，注经则疝，出表则麻，乃邪自里出表，其病实解，而反似危。因始终未用苦寒，里气得温，逼邪外解，病复五日而三变证。惟执厥阴一经，不为利疝所惑。此认经不认证也。", "16123": "张廷玉文学尊堂，年七旬外，癸丑年夏月，中暑头眩，身热呕吐烦渴，高年气虚中暑，正合清暑益气汤。而前医误作中热，以香薷饮合葛根治。服四剂后，遂大汗不止，昏沉默卧，六脉散大。余曰：此汗多亡阳也。以丹溪加味生脉汤，人参、黄耆、甘草、麦冬、五味子，大剂二服。脉忽敛小如丝，人事略清，旋即下脱，饮食倍常，大便频下。随用人参、耆、术各三钱，姜、附钱半，五味子、甘草为佐，日投三剂，汗泻减半，而脉不起。因思高年茹素，气血两虚，草药不应，宜加有情血肉。遂以黄耆、白术熬膏，用鹿茸为末入膏内，以人参煎汤调膏，日服三次。如斯半月，汗泻方止，始能言语，方省人事。询其月日，皆言不知。盖高年气弱，因暑伤气，以致身热头眩，此气虚发热，若初投参耆，则热自退。所谓人参、黄耆、甘草，退虚热之圣药也。失此不用，反辛香散气，阳因汗越，所以表愈热而里益虚，致大便频下而垂脱矣。", "16124": "郑襟宇，余族叔祖也，年六十外，初秋每日仆仆道途，夜忽小便多极，两倍于平常，且频数不已，次日即发热口渴。先医作疟治，一二日即小便淋滴不断，竟无宁刻。余往视之，见其面垢齿燥口渴，脉浮而弦，此病似疟而非疟，乃仲景之中暍证也。暑邪中于太阳膀胱经，以膀胱自受病，不能司出纳之权，是以小便频数，且面垢齿燥，口渴脉弦，的属中暍。用白虎加人参汤，一剂身得微汗，热渴旋止，小便即如常矣。", "16125": "苏茶馆内人夏氏，年近五十，身素瘦弱，盛暑得病半月，历医数人，因其身热烦躁，舌干口燥，间出妄语，胸前发红疹数十点，皆作伤寒治之。至十七日，招余一诊，以备终事。诊其脉，细迟无力，重取欲绝，并无伤寒六经形证，乃中暑虚热也。以汤试之，惟咽一口，响至少腹。唇口虽干，全无血色，渴惟热饮。病中日出大便，惟三日未通，此腹馁，非阳明内实也。斑乃胃虚，虚火游行于外。急用米汤以救胃气，药用人参、白术、麦冬、五味、茯苓、甘草、陈米。甫一剂下咽，即神清舌润，斑俱散矣。劝其进食，其夫恪守前医之言，坚不与食，至夜则咬牙寒战，现虚寒真象。再用理中苓桂，温补回阳，后虽欲进食，而胃气大伤，见食即呕，乃于榻前烹炮香饵以诱之。温剂两月，方得起床。袁调寡内入，年近五十，身肥，夏月患病，昼夜不寐，痰喘呕逆，大小便秘，将十日矣，历医多人不效，惟治棺于卧侧，以待死耳。其婿邀诊，以决迟早。诊其脉，弦而滑，重按有力，其证烦渴发晕，呕哕不食，痰喘不能卧，有汗身热，前后便秘，喜暗畏日，窗牖布障。余曰：此暑痰也，何至于死。以大剂古方香薷饮加二陈汤合剂，令煎热服。病者云：大小不通，服药徒胀，惟候死耳。延至次日，其婿力劝，方服一剂，吐痰涎甚多，微得汗，即合目，略睡片时。再进次剂，腹内肠鸣，大小便齐通。次日再邀诊视，抬棺他所矣。", "16126": "金尔立仲子，七月间暑途奔走，头面生小疖甚多，不数日，遍身发大红斑如云片，卧则色赤，坐则色紫，幸而作痒。前疡科用凉血清风之药，三四剂后，渐变壮热烦躁口渴，卧则斑紫，起则紫黑。迎余往治。切其脉弦长有力，乃风暑中于阳明，未用辛凉解散故也。盖阳明多气多血之府，血为热郁而成斑，卧则气下，坐则气上，所以卧则红，坐则紫矣。温热病发斑自内而出，皮外不痒，若如此大斑而且紫，万元生理。此风暑瘾疹，虽非热病，必须仿伤寒治法。以葛根、赤芍解阳明之风，香薷饮解阳明之暑，白虎汤化胃热之斑，三汤合剂，四剂后斑色渐淡，十剂斑散痒止，惟热渴未除。六日后以小承气汤一剂，微利而愈，计断饮食八日。", "16127": "程兰颕太学尊阃，年将五十，平常茹素，时当酷暑伤气，因食瓜果寒中，遂大吐泻，证属霍乱。因本体自虚，吐泻汗出，遂致亡阳，烦躁乱走，复不能走，用两妇挟之而行。余急往视，竟不避亲疏，亦不自知何以至此。诊其脉，散大而数，面赤戴阳，欲食冷水。余曰：病急矣，不急救，一寒战即脱。先以大顺散，用熟水冷调服下，面赤渐淡，欲扶进房。余曰：得之矣。时令叔馨九兄，在座主持，即取人参五钱，附子、炮姜、甘草各二钱，煎成冷饮，然后躁定，方扶上床，闭目片刻，脉始收小。计一夜服人参二两，姜附各两许。次日兰兄真州回扬，已大定矣。温补半月，方得起床。若其时用药不力，何能挽垂脱之真阳乎。次日延请外境名家，只用归芍六君子汤，加人参一钱，抑何轻视前证耶。", "16128": "吴瑾仲郡宰令政，年近五十，素有经水似崩之证，乃气血两虚之体也。暑月出门拜寿，劳而中暑，归家手足麻木厥冷，汗出如浴，脉细如丝。此气虚中暑，正合清暑益气证。不虞前医作中寒治，用人参一两，加干姜、附子、半夏、吴萸，其时手足虽温，汗虽旋止，而虚烦畏热，席地而卧，渐至怔仲不寐，日夜频餐，有类中消，内伏暑邪，时时泄泻。如斯四十余日，日服人参二三两，又拟加鹿茸以止泻。病家惟恐亡阳急脱，请余诊治。切脉至止调匀，虽虚细而兼数，虚则有之，未至于脱也。人参当用，不须若是之多，此中暑之膈消也。用人参三钱，白术、茯苓、石斛、麦冬、五味子、当归、丹皮、枇杷叶、甘草，兼补兼清，出入加减。五日后即登床而卧，十日后即食减如常，半月后经水行多，即加黄耆、枣仁，而减少人参，去丹皮、枇杷叶、麦冬。但家事多劳，气血本虚，参耆补剂，服之经年，而不能少间耳。", "16129": "一坊役贫人，素有失血咳嗽证，夏月过劳伤暑，次日发热而有汗。前医作伤寒治不效，又作中热治，绝食五日，忽大喘大汗，其父慌迫，急迎往视。则大汗淋漓，发喘不已。两手脉细如丝，尚不及三至，幸未厥冷。余曰：外无伤寒形证，脉证欲脱，必误饿至此。询其气从何处起，病者云从心下起。余曰：尚可治，若自脐下起，则宗气离原，不可治矣。急以粥救之。食下喘甚，入胃片刻即喘定，少刻又喘。因思胃中空虚，粥入胃，旋即下入肠，肠实而胃仍虚，所以又喘，须糜饭留胃乃可。续进饭一碗，汗即止，喘即定，稍停又进饭一碗，喘亦定。后徐徐进食，未药而愈。", "16130": "程姓、同舟之人也。盛暑在船，忽大吐泻，吐止即头汗如雨，草枕皆透，水泻不禁，任其下流，周身抽搐，证类转筋，又或有时麻木，如是者半日。诊其脉，则浮弦有力，且头汗身热，断非虚寒。经云：暴注下迫，皆属于热。此暑风证也。余未携药裹，舟至丹徒镇，市药用香薷、葛根、防风、厚朴、扁豆、赤苓、木瓜、泽泻、甘草，煎服得卧片时，反周身大汗，遂热退痢止。晚至京口，即可步行登岸矣。", "16131": "方哲先兄在室令爱，夏月恣食瓜果，伏暑霍乱，泻止而呕吐不止，已三日矣。他医用薷藿二香汤，皆吐不纳。第四日延余，而脉细紧无伦，他医以紧为数，将用黄连，乞余决之。余曰：若暑霍乱一经吐泻，邪解即愈。今泻止而吐逆更甚，此中寒厥逆于上也。紧寒数热，相去天渊。今阴阳格拒，药不能下，失之不温，发呃烦躁厥冷，即不可治矣。先以来复丹，以开格拒而止吐，继用四逆汤，去甘草加半夏、茯苓，以温里，嘱煎成冷饮。仍令质之前医，再行与服。恐招谤也。及余甫出门，病者即发呃，少顿即欲下床卧地，方以余言不谬。先化服来复丹，果吐定，再服四逆汤，片刻稍宁，继服二煎，呕止得卧。次日再诊，紧脉下移两尺，乃寒注下焦，反增腹痛。仍用前剂加肉桂、甘草，服三日而愈。", "16132": "吴苑仙守戎，戊午年七月酷暑，乘马出门，恣食瓜果，归署即寒热身痛，脉得弦数。告以疟证，用芎苏饮二剂，汗出而解。次日自以为无病矣，殊不知间日疟也。其夜犯房事，次日疟作，寒热烦躁，因里虚不能作汗，热遂不退。更医作伤寒治，二三日热仍不能退。用滚痰丸下之，大便后即于秽桶上气脱，大汗遗尿，进人参一两，灌下方回。回则脉细如丝，汗犹不止，继以附子理中汤回阳，三日里气得温，邪方外出。间日之疟，依然发作，但发时左胁胀痛，咳嗽不已，将解必大汗亡阳，几致晕脱者数次，皆重用参汤救回。治疟则以桂枝、当归、赤芍、白术、人参、茯苓、半夏、甘草，姜枣为引。如此补剂，疟止者二次，皆因劳而复。再用参术，汗愈多而咳愈甚，竟致坐不能卧，即卧亦左半身不能著席。因思先伤风暑，已经两愈，其病中犯房事，肝肾之阴虚未复，邪深入于里，故致咳嗽不能卧。用六味地黄汤加人参五钱，日服二剂。如此半月，疟咳皆止，尚半身不能著席，几成疟劳。仍以地黄汤加人参二钱，兼服地黄丸，一月方健。病中犯房，岂细故耶。", "16133": "陈玉生秋间病疟，截药乱投，将一月，疟未止而又病痢，疟痢并作者，又数日矣，最后延余诊。其脉尚浮弦有力，盖疟邪因截，不得外解，内搏作痢，邪犹在半表半里之间。以仓廪汤本方，不用人参，即败毒散加陈仓米也。连进四剂，令其取汗，上身得汗而疟止，再进二剂，通身得汗而痢止。乃经营之人，见疟痢皆止，便不药矣。遂大劳，致中气下陷，又似欲痢之状，然脉虚大，有汗不热，用补中益气汤二剂随愈。又不药矣，五六日后，忽神昏谵语，慌迫求治。诊脉弦滑而数盖前疟痰未清，不药留病劳而伤气不得不补，此虚回痰作，所以谵妄也。用温胆汤古方，陈皮、半夏、茯苓、枳实、甘草、生姜、竹茹，六剂后呕吐痰涎甚多，其病如脱。此证几两月，始终以去邪而病解，未常以久病补虚，故治病必以脉为准也。", "16134": "王君圣翁，乙丑年七月下旬，得疟疾，前医者已半月，皆柴葛、黄苓、二母、二陈等药，不效。困惫在床，迎余诊视。面目黧黑，间一日发，脉则单弦而硬，历医甚多，补泻温凉用之已尽。历秋至冬，益至危笃，元气大虚，竟无汗解，身目皆黄。其发也，由两足筋抽，即恶寒，渐次上冲于腹，腹则胀大如鼓，汤饮不下，惟能仰卧，两足直伸，不能转侧，寒热轻而胀重，全无汗解，发则必一昼夜，耆术下咽，腹肋胀痛，脐旁有动气，诸医束手矣。盖此翁年逾五十，素恃强健，初疟汗解，以为病退，房室无忌，情或有之。深思疟状从两足上冲入腹，腹胁胀痛，面目黧黑，小便点滴难出，脉弦而硬，不受耆术，皆肾肝病也。病经五阅月，真气败伤，疟邪深入，须补肾藏阴阳，使本气壮实，逼邪外解。今气已冲胸胁，未及于喉，若再上冲，必增喘呃。以金匮肾气汤本方，两倍桂附，加人参五钱。病人苦药，日投一大剂。服至七八日，足抽气冲减半，而疟势反彰。余曰：无虑也，此正气与邪争也。正胜则得汗而邪外解，执方不用增减。又服二旬，至大寒节次年初气，则大汗三身，而疟止矣。但一足筋挛，不能步履。至次年上元节，方登室会客，而足跛者仍半年。病之前段，众医所疗，后半节专意委任，乃以意治效，未作疟医也。", "16135": "梁德卿在室之女，八月间患疟，四十日矣。前医见久不愈，用参术归芍鳖甲知母，补截兼行，治之愈甚，每日只二时安宁，随又发矣。诊其脉弦而紧，且不发时仍恶寒身痛。余曰：病虽月余，表邪未解，半入于里，所以似疟而非真疟。幸为室女，里气不虚，未尽传里，何以补为？即于是日起，停止饮食，作伤寒治法，以羌活、桂枝、柴胡、苍、朴、二陈、生姜，表里两解。四剂方得汗，寒退身不疼，去羌活。又四剂，热退。至六日，寒热皆尽，而似疟亦止，大便随通。病虽久而邪未除，必以去病为急，即所以保正气也。", "16136": "吴静含河员，初秋患疟，乃因热求凉，过餐生冷，寒疟也。起时殊不重，余初诊令其节饮食，戒瓜果，不合病人意，遂易医。恣其所欲，疟热作渴，纵饮冷水。至一月后，病势危笃，形骸骨立，胸中塞满，粒米难吞，呕哕不息，昼夜俯坐于床，不能平卧，每日一发，自午至寅，无汗而止，日惟二时进药饮汤而已。不得已，复邀余治。脉则细紧如丝，两足冰冷，虽疟发热，而足亦不热，坐不能卧数日矣。此寒极于下，厥气上逆，中冷甚矣。辞不治。坚托不已，议用附子三钱，干姜、半夏、茯苓各二钱，人参一钱。如此不加减，服十余日，呕逆方止，能平卧，得进米饮，续续得汗，疟亦寻愈。后因劳两复，仍用前方减姜附一半，加入桂枝、白术、赤芍、生姜，至十一月冬至后，方脱然。", "16137": "许用宾翁，溧水李令亲，秋月患疟，呕吐长虫，盖先医过用苦寒所致。六七日后，招余往治。脉弦而迟，乃阴寒脾疟，主用桂枝、苍术、干姜、半夏、茯苓、白蔻、生姜，服五日，疟止矣。即以六君子汤加炮姜调理，饮食亦半餐。忽然舌黑不干，脉变虚数，别无他证。病人惊怖，余曰无伤。因本体阴虚，前治疟过温，疟虽止而阴气稍伤，用地黄一二剂可退。用宾曰：前药热而效，今药用凉，倘益病奈何？余曰必效。果一剂而舌红黄矣。若系中寒虚冷，脉必沉迟，见呕胀诸证矣。", "16138": "方豫章部司尊堂，秋患疟，本体虚寒。前医误投黄芩、知母多剂，致发寒，时大吐，吐极大汗，遂昏厥而脱，全不知人。时半夜矣，急迎往看。则六脉全无，手足厥冷，目合不语，牙关半开半闭，惟身体不僵，未全冷耳。余曰：证脉全脱，药能下咽，方可救也。试以姜汤能咽，即以人参五钱，附子三钱，白术、干姜各二钱，煎成频频灌下。至天明，手足回温，再剂目开，三剂手能动，四剂脉出如丝，至一周时，方能言也。至第三日，元气稍振，而疟复发，即以前方减参附一半，加桂枝、赤芍、半夏、甘草、生姜、大枣，解肌温里，每日二剂，六七日疟止矣。苦寒伤胃，亦至如此。", "16139": "族其五主政，仲秋舟中感寒，归来患疟，寒多热少，巅顶痛，腰背疼，汗出不止，脉弦细而紧，疟发则小便不禁，滴点不休。此非三阳证，乃厥阴疟也。用人参五钱，桂枝、赤芍、细辛、炮姜、半夏、甘草，姜枣为引。服后汗少寒轻，而尿不固。加附子五分，遗溺止，病人畏热，不肯再剂。疟势减轻，方加白术、当归。因调理失宜，疟复者三，皆以参耆归术桂枝赤芍甘草姜枣等药，月余痊可。若宗时派，以柴胡为套剂，岂不益病乎。", "16140": "王木文兄，初秋场中筑盐，日受酷暑，夜沾风寒，回扬疟作。历医数人，皆柴葛香薷知芩二陈等剂，病全不减。十日后迎治，脉则浮弦而数，疟发身痛，寒极而热，热则渴甚，汗多，小便痛而难出。此风热未解，须用仲景阳旦汤，风热两解也。用桂枝、赤芍、黄芩、甘草，加葛根、厚朴、茯苓，二剂知，四剂减轻，六剂疟止。不数日，又复往场，半月后回扬，三四日疟又复发。初亦非余治，势甚重，始招再医。询其病状，大非前证，发寒时，便腹肋胀痛，热则起床乱走，谵言妄语，其势若狂，渴饮不休，诊其脉，则细数无伦，巅顶作痛，小便痛而难出。此皆厥阴病，岂非女劳复乎。遂用当归四逆汤，加附子、生姜、大枣，一日轻，二日减，三日六剂，疟止矣。治疟效速，惟有此证以辨经不谬也。若以前用黄芩而效，再用前剂，岂不殆哉。", "16141": "高学山文学尊堂，年逾六十，平素多痰而胃冷，初夏便餐水果，因而病疟。历医十三位，已两月余，而疟不止，渐增呕逆，滴水难下，药亦不纳，舌苔全黑，疟反不发，微有利意，最后相招。诊其脉沉弦而紧，重按滑而硬，求治于余。苦药不能下咽，检前方皆黄芩、知母、贝母、柴苓汤也。原因停冷致病，又益以寒中冷药，疟邪全入于里，寒痰格拒，非寻常药能破其坚垒。以半硫丸一钱，姜汤送下，觉胸间冲开，即不作呕。继进干姜、附子、半夏、茯苓、白蔻、橘红，大剂与服，竟不吐。余曰：能药矣，但疟复发，方允可治。学山曰：他医要截药，而先生反欲疟发，岂不相反耶？余曰：疟者，外受之邪也，知在何经，宜用此经之药，驱之使出，此善治疟者也，尊堂太阴脾经疟也。当用脾脏之药，则中的矣。而用柴胡、干葛、黄芩少阳阳明之药，与太阴何与焉？今疟固在，脉尚双弦，固本气自虚，邪陷于内，非竟止也。中气稍振，疟必再发。加人参一钱于前药内，以助中气，俾邪外解。服至三四日，胃温呕止，能进米饮，而疟发矣，较前更甚。遂改用桂枝、赤芍、生姜以解肌，不用人参，以苍术、半夏、干姜、附子、陈皮、茯苓、甘草以温里。如此六七日，饮食略进，疟发有汗，寒热减轻。复加人参，换白术，又六七日，饮食可餐，而疟全止。不虞先原停冷，又服凉药，积冷尚存，少腹遂胀痛溏泻，而又转痢，脉复紧滑。此肠胃尚有积垢，又去参术，用苍、朴、香、槟、姜、附、赤芍、二陈等药十数剂，大便通畅，泻痢寻愈。调治五阅月，方能步履。嗟乎！疟之较伤寒，只差一间耳。伤寒则自表传里，疟则专经而不传，何得疟疾不分经而套治耶？", "16142": "吴㑲庭文学，年二十余，本质阴虚，秋病疟，至冬未痊，迎往真州以治之。病已五月，疟邪虽轻，而真阴大损。因病中时时梦遗，不能禁固，致疟不瘳，脉弦细数而无力，畏寒不欲揭帐，胁肋气冲而痛，脐有动气，半身不能侧卧，腰膝酸疼，不能久立，间或咳嗽，自汗盗汗，而阴毛皆变白色，证现肝肾两虚。检其前方，皆柴芩二陈二母鳖甲清疏之品，间有用人参、白术者，亦未服。余主补阴，俾邪自解，用桂枝、当归、赤芍、何首乌、葳蕤、茯苓、人参、甘草，姜枣为引，仿建中汤治法。因当脐动气，胁肋气冲，皆肝肾之病，故不用耆术也。外朝服枸兔丸以固精，全不作疟治，半月而疟止矣。后以参耆入六味地黄汤，调治而康。十数年前，㑲兄尚在幼龄，秋病痢，前医辞不治。余不知也，迎往真州治之。诊其脉，滑数有力，乃湿热痢证，不足虑也。检前方则山楂、厚朴、当归、白芍、木瓜、金银花、陈皮而已。余曰：邪重药轻，何能破其积滞耶。遂用黄连、木香、槟榔、苍朴、枳壳、赤芍、山楂，大剂二脉，而下结粪尺余，两日痢止。次日辞行，复诊留药，其舌或变黑，见几上𪻳贮葡萄干，问曰：食此乎。㑲庭曰：然。令拭去无迹。家人问曰：食此能黑舌乎。余曰：然。㑲兄笑曰：无怪前某先生辞不肯医矣，彼固因舌黑也，其日亦食葡萄干。附记以为舌鉴。", "16143": "吴坦如兄，初冬真州抱病回扬，外证则微热微寒，头疼咳嗽，喉痛不甚，而胁肋连腰则痛甚，脉则弦细紧而搏手，按之又无力。自以为风伏火，求为发散。予曰：脉证阴阳相半，表里皆寒，幸有头痛发热，邪犹未全入里也。此厥阴伤寒证，以其十数年前，年甫三十，曾患中风，半身不遂，用过桂附，故不惊疑。遂用桂枝、细辛、赤芍、附子、炮姜、吴萸、半夏、桔梗、甘草、生姜，以当归四逆加减投之。如斯七日，喉痛止，诸证减，遂转为疟疾。胁痛虽减，而不能侧卧，咳嗽不除，疟疾日发，其紧脉虽退，而转弦细，七八日后，脉更兼涩。平素肝肾虚寒，遂加人参、当归，以培阴血，因肋痛咳嗽，恐成疟劳。服参附归芍桂枝苓夏甘草之药百剂，其中三复，皆如此治法，方获脱然。", "16144": "程越峰文学，南场应试，患疟归扬，初医不辨何经，惟投套剂，不过柴苓知贝，治不愈，遂用截疟毒丸，空心井水吞服，以致少腹里急似痢。而前医犹称暑气，益用香薷，阴凝寒肃，疟邪入里，竟不发矣，而手足厥冷，腹肋隐痛，下痢红水。求治于予，脉则弦紧无伦。此厥阴经疟也，急宜温里，使疟仍从外发。不然，即痢下不止矣。以桂枝、细辛、附子、干姜、赤芍、吴萸、半夏、茯苓、甘草重剂，七日手足渐温，惟腹尚痛，或下脓血，因里得温，阳气稍振，疟仍发出。但缘误治伤中，遂以前剂加人参、当归，去细辛、吴萸，半月疟止。因力薄停参，疟又复作，以白术代参，计服姜附药九十剂。疟已止而便实，彼因齿痛，遂去姜附。无参而加黄耆，遂胸胀不能食，少腹随痛，仍照前方去黄耆加姜附，十数剂疟方止而痊。误用苦寒井水，姜附百剂，方得破彼坚冰。前吴疟案，亦厥阴疟也。始即用温药，亦百剂方瘥，未误苦寒，故未下利。治疟不辨六经，不分阴阳，浪投劫药，医家病家，皆当致警。", "16145": "朱贞启文学，年六十外，初秋患痢，其证恶寒发热，脉浮而数，头疼身痛，目赤口干，而又腹痛，痢下脓血，不离秽桶。此虽挟表之证，其势甚危，乃疫毒痢也。表里皆病，必须先解其表，而后攻里，正合败毒散加陈仓米，乃属仓廪汤之证。遂以羌活、独活、柴胡、前胡、川芍、茯苓、枳壳、桔梗、甘草、陈仓米，日投二剂，身得微汗，表热里痢皆减半。浮脉虽平，而虚数不敛，此高年气虚，即以前药遵古方加人参一钱。二剂遂大汗通身，热退痢止，邪从外解，竟不须攻里矣。", "16146": "休邑黄益之，时寓瓜镇，年七十四岁，秋初患痢疾，六脉虽大，而尚有力，赤白相间。初以平胃散加归芍香砂，四剂积滞已行，而痢不止，下迫益甚，小便难出，六脉更大而无力。余议用参附，其邻医曰：痢脉忌洪大，而又有血，反用参附，殊为不合。余曰：老人脉大为虚，今脉大而不数，重取无力，此气虚非热也，乃中气虚寒，逼阳于外，致脉亦浮于外也。痢疾属肾，肾主二便，开窍于二阴。今小便秘而大便不禁，乃元气下脱，宜升阳温肾，非桂附不可。遂用人参三钱，耆、术、桂、附、炮、姜、当归、茯苓各钱半，升麻、甘草各五分。四五剂后，小便即通，脉亦敛小，不十剂而痢止矣。后用八味地黄丸加破故纸、五味子，调理一月，计服人参半斤而痊。此治痢变法，因其年迈也。", "16147": "溧水药店张姓，初秋患痢，昼夜百度，不能离秽桶，干呕烦热，而手足反时冷，脉又细数，渴食西瓜，片时随即利下，而色不变。医议纷纷，或云完谷不化，手足时冷，恐属胃寒。余复细验，脉虽细，重按则长，齿燥舌黄，断为热厥，此邪热不杀谷，因胃热极，传化失常，不及变而速下，此经所谓暴注下迫，皆属于热也。用大黄三钱，黄连二钱，厚朴、槟榔、白芍、木香为佐，乘热与服，微寐片时，腹中大鸣，洞泻数次，积粪甚多，而痢减半。即去大黄，加当归、陈皮、泽泻，数剂而愈。", "16148": "周子仁深秋患痢，自恃知医，先以巴霜丸下之不减。恣啖酒肉，全不禁忌，又进大黄丸下之益甚。又自服平胃香砂归芍等药，亦不效。昼夜四五十次，将近一月，急招予治。脉则细数身热，干呕不食，面白唇红，左肋气冲而痛，下痢纯红，愈便愈坠，投以黄连归芍香槟苓草陈皮不效。然所见诸证，皆痢所忌，视其人清瘦，素属阴虚，巴豆治寒痢，大黄治热痢，寒热乱投，下多亡阴。季肋属肾，痢亦肾病，当变法以治之，补阴为本，治痢为标。用生地黄、归、芍为君，黄柏、人参、陈皮、甘草、陈米、神曲为臣，日进二剂，脉数唇红稍退。遂执此方坚服半月，渐次减少而愈。若以脉数身热，下血唇红，干呕不食，弃为逆证，而不以下多亡阴，用滋肾治法，奚望其生乎。", "16149": "族兄晓斋先生尊阃，深秋患痢，年近六旬，夏日贪凉食冷，乃寒痢也。以自知药性，喜补畏消，更恶热药，诸医顺其性，惟以平妥套剂治之。因循日久，转变虚寒，有用肉桂者，有用黄连者，无所适从，决之于余。诊其脉两尺全伏，舌苔灰黑，哕声近呃，足冷至膝，布障窗牖，畏见日光，脉证皆大虚寒，以书证病，确当温补。遂用人参三钱，附子、炮姜、肉桂、茯苓、芍药各钱半，暮夜请医不到，势急勉煎。而病人亦神昏不辨何药，服后随得熟寐。醒索再煎，又照前方一剂，次日足温呃止，痢亦减半。继延团分璜，余适往探，不令余诊，恐余用热药也。然分璜以余药为宜，随又迎京口吴时乘，用药亦同，惟加附子三分耳。因病人最恶热药，时乘令将人参炮姜先煎汤于药罐内，以白术、归芍、茯苓、甘草、陈皮、佐助群药，面投罐内，以免疑畏，用术治愈。", "16150": "汪紫臣翁深秋患痢，历冬不瘥，日不过三四次，夜或便，或不便，腹不痛，但腰下一坠，即便脓血矣。历医二三人，皆不效，然饮食起居如常。最后问治于余，诊其脉弦而无力，两尺细紧。余曰：非痢也，此经所谓大瘕泻，乃肾气虚也。盖肾主二便，今大小两便，一齐并出，小便不能单行，此五虚证之一，谓之泻利前后。理宜补气，用人参、耆术、当归、桂、附、故纸、五味升麻，服十剂。紫臣云：全不效。余曰：虚回痢自止，不能计日取效，非余故留病也。遂疏方请自制药日服，期以小便能单出为效。服药将一月，相遇于友家，喜曰：昨日能立出小便矣。令其再服十余剂，勿功亏一篑，后遂全愈。若作痢治，则去道远矣。", "16151": "方豫章部司，素虚寒，初秋患痢，日夜十多次，红白相半，脉弦细紧，反不恶寒，而微发热，头疼身痛。若以脉细紧为寒，大当头痛发热，以头痛发热为湿热，脉又不当细紧。然必以脉为准，定属厥阴病，寒凝于内，反逼阳于外也。况厥阴病原有头痛，且肝藏血，理宜用当归四逆汤。本方加附子、干姜、吴萸，解肌温里，俾邪外解，每日服药，夜必微汗，次日必热微利减。如此六七日，则表热里痢皆痊。以后三年初秋必病，皆如此治之。", "16152": "余弟思承，年五十六岁，宣城贸易，初秋酷暑，日食苦蔗菜，即本草所谓败酱也。且餐石膏豆腐，淡薄水酒，平素中寒，因而腹痛作泻，泻后数日，即痢疾矣。十余日余归，脉双弦紧硬，而两尺尤甚，胸中饱胀不能食，脐旁动气，按之痛，昼夜五十遍，腹反不痛，惟尾闾一酸坠，即下痢矣，小便点滴难通，惟与痢并出。观脉之紧硬，腹之不痛，此肾藏虚寒之痢无疑矣。初即用附子、干姜、肉桂、归、芍、苍术、香砂，十数日不减，而下迫益甚，更换白术、茯苓，去香、砂、干姜，亦不效。益之以人参、黄耆、升麻，亦不效。再以八味地黄三倍桂附为丸，清晨吞服，夜用鹿茸鹿胶鹿角霜为丸，虽稍减而亦不愈。如斯大药，服之百日，至立春方减至十数便。因痢久下陷成痔，日下鲜血，而紧硬脉不退，但停鹿茸丸煎剂之桂附，八味丸之桂附，仍日服不辍，至春分日方一夕而痢止。次年八月，即上年得痢之日，又复痢疾。仍如前煎丸并服，又不见效，再以硫黄之玉粉丹服之一月，至冬至前后方痢止。乙酉仲秋，前痢又作因，食蟹所致，如前治法，冬至方回。此痢之虚寒，世不多见，因属胞弟，彼此不疑，故得获效于万一也。", "16153": "方惟善翁，年七十，夏月忽右手足不用，口眼㖞斜，舌强面赤，脉虚大而参伍不调，两寸脉十数至一歇，但止数不齐耳。问其脉何以歇至，彼云：今十年矣，每心一掣跳，则脉必歇。余曰：心掣为肾病，此心肾气虚，并无风邪六经形证，温经大补，或可复原，若作风医，必致屡废。遂用人参、黄耆、白术、桂枝、芍药、附子、天麻、当归等药，每日用参两许，医治月余，口眼端正，步履如常。方在调理之余，忽发咳嗽，彼自误为痰火，参附贻祸，数日后目窠微肿，颈脉大动，尿如煤水，乃肾藏真阳不足，将成水蛊之证也。随即咳喘不能卧，足趺先肿，渐延两腿，余用金匮肾气汤，加倍桂附，更入人参三钱。时当酷暑，悬大帐于庭，伏枕于几者二十八日，药近百剂，小便渐多而肿消。适因病后营葬劳烦，调理失宜，遂时发喘咳，不能平卧，至八旬乃终。", "16154": "汪大扶兄，年四十五，善饮贪凉，此素性也。雪途昏仆于地，抬归始醒，即遍身拘挛，腰足冷痛，手足不能举，已具六经形证。此真中风也。先医者作虚治而用人参，困顿于床。后延余治，脉弦而沉紧，此夙昔之风，加以雪天新中于寒，两邪并发，致昏厥而仆，风寒未解，何用补为。余以桂枝、细辛、羌活、附子、赤芍、干姜、半夏、甘草、小续命汤加减，温里解表。五六日邪气外出，脉略浮弦，而增咳嗽，再加麻黄、杏仁，续续得汗而痛减。将一月，身发瘾疹作痒，外解而痊。", "16155": "吴敦吉翁，年逾五十，善饮多劳，二月间盥洗时，忽然发晕，呕痰未仆，即右手足不举，言语蹇涩，口眼不歪，尚能扶步，脉弦滑有力，而无他证。此痰中也，用六君子汤去人参，加胆星、天麻、秦艽、竹沥、姜汁，半月后病减。方少加人参，兼用归、芍，一月后即言语，步履如常矣。", "16156": "赵智善因酒后愤争，随即昏仆不语，手足厥冷，前医用牛黄丸不效，用风痰药亦不效，已经一日夜矣。余视之，六脉皆沉弦，而歇至来去不乱，喉无痰声，手足微冷，口眼端正，牙关半开，呼吸调匀，面无贼色。盖中风则身湿，中气则身冷。此中气也，用皂角末吹鼻，得嚏一声，随叹气一口，手有动意。继用乌药顺气散，加木香、沉香，微煎数沸，缓缓灌下，即嗳气一声而苏。", "16157": "瓜镇刘玉吾，年六十外，混堂浴归，卒中一日始醒，初医以风痰火杂洽，风则羌防，火则膏连，痰则星夏，继进苏合丸数枚，则遗尿矣。十日外始迎余治诊，其脉虚大无伦，昏睡不语，身重遗尿，肢不偏废，口不歪斜，喉无痰声。原非中风，因老年贪浴，汗多亡阳而暴脱，有似中风。失此不用补中，反行疏导，阳气愈虚，致遗尿不语，竟成脱证。急用归脾汤原方，入人参一钱，四剂即能言语饮食，惟尿不禁耳。每日间用八味地黄汤，去丹皮、泽泻，加人参、破故纸、益智仁、五味子，而尿固。数日后，舌苔全黑而滑，此中气虚寒，肾水凌心，用苓桂理中汤，四剂而苔退。后仍以归脾汤甘温之剂，调补一月，方能步履。但因多食苏合丸，辛香散气，病愈后，言语随忘，欲言又止，终不能复也。", "16158": "镇江巡江营王守戎之媳，抱子登署后高楼，楼逼山脚，若有所见，抱子急下，即昏仆者一日夜。姜汤灌醒，如醉如痴，默默不语，不梳不洗，与食则食，弗与亦弗索也，或坐或卧，见人则避。如此半月，越江相招。入其室即避门后，开门即避于床，面壁不欲见人。令人抱持，握手片刻，而两手脉或大或小，或迟或数，全无一定。此中恶也，与苏合香丸。拒不入口，灌之亦不咽。明系鬼祟所凭，意惟秦承祖灸鬼法，或可治也。遂授以灸法，用人抱持，将病人两手抱柱捆紧扎两大指相连，用大艾团一柱，灸两大指甲角，灸至四壮，作鬼语求食求冥资。灸至七壮，方号呼叫痛，识人求解，继进安神煎剂，熟睡数日而愈。", "16159": "吴翰臣兄令眷，予族之女也。清明夜，门首看城隍会，甫入堂，忽昏仆于地，不能言语，抬上床一刻，即大吐，口出妄言，谓城隍夫人需侍者，已得三人，令其入庙服役，语毕，仍闭目昏睡。其家惊畏，暮夜迎余。自门首至寝所，皆烧冥资。观其色无青黑鬼气，切其脉两手相同，至止不乱，但虚大无力。余询其声变否，家人对以如常。此殊不似中恶之证也。又问前有病否，家人云：经水行有半月未止，数日前，即燃灯通夜不熄。翰臣外出，要人作伴，似有畏惟之状。盖邪之所凑，其气必虚，因脱血心虚，夜看城隍会，见扮鬼形，心布而神乱矣，即或中恶，亦因其虚也。以人参五钱，桂心一钱，银一锭煎熟灌下，又将渣再煎灌下，片刻即醒。问其前事，全然不知，惟记门首看会，不知何由在床，但称心慌手麻而已。随用归脾汤数服，经止病愈。", "16160": "魏老者，冬月自郡归瓜镇，夜食毕，方就枕，即昏厥，手足僵直而厥冷，牙关咬紧，面青脉沉。此老年气弱，被严寒所迫寒中也。先以浓姜汤抉齿灌入，牙关略开，继以附子干姜半夏甘草四逆汤，大剂灌下，至五鼓身方回温，人亦渐醒。", "16161": "巴其臣主政令眷，年未三十，遭新丧悲郁之后，忽眩晕昏仆不语，脉弦数而涩，有时手抽掣，面上发赤，喉无痰声，药亦能咽，惟昏睡不语者三日夜矣。经医数人，主风主痰主虚，与以牛黄抱龙丸，皆能咽，但终不醒。予以脉弦数，独主火中，盖木郁化火，肝火暴甚，故卒倒而无知也。经云：阴气衰于下，则为热厥。以滋肝清火，逍遥散为主。用归、芍、丹皮、柴胡、郁金、栀子、贝母、羚羊角、竹沥频灌，一日夜回苏能语而愈。嗣后遇怒仍发。", "16162": "吴坦如兄年将三十，酒后行走，忽昏仆不知人事，扛上床一刻方醒，即右手足不能举，尿不禁而口眼不歪，舌微强，时发寒而汗出，小便频下，六脉细濡无力。此元气大虚，类中风之脱证也，若不急行温补，恐致大汗喘厥亡阳，乃显明易见之虚病。时火治庵盛行之际，亦不能别生他议，遂以参、耆、归、术、桂、附、天麻、半夏、益智等药，补益月余而健。", "16163": "从容庵僧，饱食后混堂洗浴，昏晕抬归，手足温暖，呼吸调匀，口眼端正，牙关不紧，又无痰声，其人气实本无病者。诊其脉，两关沉滑有力，惟闭目不语，掐其人中亦知痛。此证非风非痰，非寒非虚，以意度之，饱食之后，久浴伤气，胃中食满，气虚不能运转。经云：一息不运，则机缄穷，岂非食中耶。以手重按其胃口，则眉皱手推。遂用姜盐汤探吐灌下，即呕哕吐出未化之饭半盆，嗳哟一声，目开而醒矣。", "16164": "扬州大守如夫人，年及三十，平素虚弱，参术汤丸不辍，盛暑忽身疼发热，呕吐痰水，犹以平日之虚，召用补剂。及诊其脉，浮弦而细，对以非平常之虚，乃暑热伤气，复受风邪暑风证也。须先治风，以葛根、藿香、二陈、砂仁、厚朴、生姜，一剂即汗出发热身痛皆愈。少刻手足挛搐，目珠上视，喘喝遗尿，身僵不语矣。署中惊畏，急复再召。脉则不浮，但弦细耳，神昏僵卧，但能咽药，因脉之细，乃气虚伤暑而卒中也。面垢遗尿，皆属暑病，而非脱证。用古方消暑丸三钱，温胃涤痰。服药时许，又得微汗，即目开能语，续以香砂六君子汤，二剂而愈。", "16165": "汪嵩如翁，己未年维扬患病，随余迪兹至瓜镇，就彼治疗，寓江干从容僧舍，因药未效，又问治于余。昼夜不寐者，已月余矣。诊其脉虚大而数，重按豁然，日惟食清粥两三盂而已。时当仲秋下旬，衣单纱，犹畏热之至，令仆挥扇，方可伏枕，否则起行，不能著席矣。先医用药，秘不令知，但云日服人参而已。审其病，因始于愤怒，兼恐而致病。余即病因，合病之状，而议治焉。盖暴怒伤阴，则肝气逆，恐伤肾，则气下，肾水不升，心阳不降，肾肝两病，魂不归肝，气不归肾。因卫气常留于阳，则阳跷盛，不得入于阳，则阴虚，故目不瞑矣。真阳外越，脉虚大而不敛，天令虽凉，而犹畏热，似与阴盛格阳同病，又非真武四逆所能治也。经曰：阴者阳之守也，阳者阴之卫也。病始于暴怒伤阴，阴不守阳，孤阳飞越，寒之不寒，是无水也。用从阴引阳法，以八味地黄汤，倍用桂附，加人参，四剂病知，八剂得寐，半夜十日后，即熟寐矣。病痊心感，劝余迁扬，代为税居，逾年之后，因移寓郡城矣。", "16166": "熊伟男司训，正月上旬，贺节饮酒，即于席上腹痛吐泻，并作厥冷大汗，竟不能归。先医用炮姜、香砂不效，又进平胃、二陈，亦不效。因吐泻大汗，真阳外越，反面赤脉大腹胀而痛，延京口名家。见其腹大而痛，视为实证，投以木香、槟榔、腹皮破气劫药。病家不敢服，自真州迎余至瓜镇。已病四日矣，诊其脉，洪大无伦，重取即散，素有肋下肝肾气病，自以为旧疾作楚。予曰：非也。盖首春苦冷，暴寒所伤，此寒霍乱也。故卒然大痛，吐泻并作。因吐泻汗出，里气虚寒，真阳外越，以致面赤戴阳，阴躁不眠，口干呕哕，腹胀如石，胁痛气冲，脉洪散乱。此汗泻亡阳，大虚若实，危笃急证。若不急救，必致厥冷汗出不治矣。非若寻常霍乱，吐泻止而愈者比也。遵仲景霍乱治法，以四逆汤加人参、肉桂、茯苓，小剂先投，得闭目片刻。继用人参五钱，附子三钱，干姜、肉桂、茯苓各二钱，日投三剂，胀略敛小，而两足太谿冲阳，皆陷下不见。如斯重剂，六日始胀痛止而得卧，十二日大便方通，可进饮食。因平素脐旁肾藏有动气，耆术皆不能入剂，用四逆桂苓二十余日，饮食始餐。易用八味地黄汤，三倍桂附，加人参，调治两月方健。其时瓜镇医家，佥云误补，必致危殆，因令子青选为予门人，不得不肩任也。", "16167": "李元亮书吏也，因书写过劳，秋杪忽咳嗽火上逆，头面皆赤。前医苦寒直折，随吐粉红白血如肺肉，则火愈上逆，一日三五次，火一逆则遍身皆赤，咳嗽益甚，间有白血，头面汗多。余往诊之，两手脉大而数，重取全无神力。若以失血之后，见此数大之脉，则为逆证。咳白血亦属不治。病者云：卧则不咳，坐起则咳甚。余熟思之，久视伤血，书写伤力。此气中虚火，宜人参、黄耆、甘草以退之。所谓虚火宜补，误用苦寒，虚以实治，则火愈炽。坐起咳甚，肺虚也。脉大无力，所谓劳则彰，亦气虚也。多汗面赤，乃虚阳上泛，非阴虚之火。遂用大剂黄耆为君，人参、当归、白芍、麦冬、五味、甘草为臣佐，一剂汗收脉敛，三剂火息咳止。如此滋补，一月方能起床。火之阴阳，可不辨哉。", "16168": "万守澍文学尊翁，年七旬外，长斋独宿，二十年矣。因心事怫郁，夜中忽大吐紫血碗许，随腹痛，又便紫黑血碗许，昏仆于地。室内无人，及其自醒，始登榻。次日相招，两手脉大而芤，幸不散耳。他医议用凉血滋阴，予曰非也。此畜血证，因郁怒伤肝脾，肝不藏血，脾不裹血，致血无归，而成瘀败，上吐下便。幸老翁闭关已久，不致气随血脱，尚敢滋阴以伤胃脘之阳乎。用大剂归脾汤，加炒黑干姜，计用人参数两，匝月乃康。", "16169": "程于宫兄，首春自场来扬就医，面目皆黄，胸腹饱胀，腹痛便溏，脉沉而紧。此太阴脾藏之阴黄，色黄而黯，非胃府之阳黄，色如橘皮也。言场服茵陈、栀子、四苓清热之药，病将一月而不效。此证本中寒，误作湿热，岂不益甚乎。而病者素畏热药，今病患中寒，不得不温。先以苍术、炮姜、二陈、砂仁、茵陈、泽泻投之，胸虽稍宽，脉沉不起，紧亦不退。遂加附子，易干姜，十数剂黄退腹消。即前方苍术换白术，去茵陈，加甘草，调理而愈。此瘅病正治，亦须辨阴阳寒热也。", "16170": "崔魏子病疝一月，清肝理气，消坚攻劫，无不备尝，最后招予。诊其脉，细濡如绵，惟有三至，羸瘦不堪，色枯貌瘁，卧床不起，疝坠于囊，全不知痛，时值秋暑，畏寒服绵。予曰：虚寒极矣，元气下陷，须温而举之。用人参、黄耆、肉桂、附子、当归、升麻、甘草，姜枣为引，温肾升阳五七日，疝方渐收能坐，温补而愈。越三年，又疝痛牵引胸背，胃中亦隐隐而痛，历医多人，有疏肝者，有理气者，有用安息诸香者，渐至阳虚自汗，惊悸不眠，较前病更甚。病两月矣，自惭不便请凂人求治。诊其脉细涩不堪，乃气血两亏，津枯髓减，肝肾病也。经曰：诸阳受气于胸中，转行干背，此气虚胸背痛也。又经曰：肝虚则令人胸痛引背，下则两胁胠满，此血虚之胸背痛也。肝虚不藏魂，故不寐。气虚不能卫，故自汗，脉又细涩。此伤精亡血之证，以熟地黄、当归、枸杞、山茱萸、枣仁补肾滋肝，以肉桂、破故纸引气归肾，加人参、黄耆以益卫气。初服病知渐减，多服寻愈，两月方瘳。前医执痛无补法，岂定论乎。", "16171": "王用明兄，新正登金山，日中痛饮，攀缘山巅，劳而汗出，归卧火箱，夜又梦遗，次日四肢清冷，面惨不光，肌肤似麻非麻，似痒非痒，惟皮外不欲沾衣，觉衣之硬甚也，夜卧被席亦如之，脉浮而濡。医初用疏邪实表驱风剂不效。予曰：此肉苛也。虽正月犹属冬令，阳气在里，劳而汗出则卫虚，又值梦遗而营弱，所以不胜衣而肉苛也。以黄耆建中汤加白术、当归，姜枣为引，三剂而愈。", "16172": "熊辟疆兄，秋间食冷物，当风假寐，次日即胸前结硬冷痛，干呕作泻。随服平胃、二陈、炮姜四剂，稍减而未痊。因循两月，服药断续。其间或服姜桂温中之剂，则痛愈甚。以手扪之，胸皮皆冷，呕吐酸水，小便涩少，脉初诊则细，重按反滑而有力。余曰：初因寒中，积之既久，郁而成热，所以姜桂反增痛矣。皮外虽冷，乃阳郁于内也，用仲景泻心汤法，但苦以泻实，辛以散结。以二陈汤加黄连一钱，干姜一钱，四剂后，胸中作响而宽，胸皮回温，续得大便畅解数次方愈。", "16173": "员虞肱中翰，己巳年三⿰亻⿳亠口衣河舟中，忽奋身跳河，家人拉住，嗣后言变志乱，举止失常，经医数辈，皆以癫证治之。月余罔效，未始招余。脉弦细而数，尺寸皆涩。予曰：脉不长滑，非痰非狂。然未察其病证，及相对揖让如常。但言语无伦次，一日，以笔昼几作横竖云：此我也。又以笔圈之云：此困我也。一日，手摘桃叶搓之纳口中，手掬鱼缸水欲吞，复并桃叶吐去，入席又言语如常。又一日，倦卧内房，就榻诊之。初自逊云：我少年也，奈何卧于床，致劳先生之多步耶。忽又云：昨日得一竹片，刮之甚光，遂口作击竹之声，以手和之。予见言乱而出，随令纪纲传语，谓适言竹片者，妄言也。嘱余勿信，余方恍然悟矣。经云：肾气不以时上，故言变而志乱也。谓之失志，此非癫狂，乃肾病也。次日往诊，问其竹片，彼尚记忆。予告曰：尊恙肾虚证，独宿百日，可勿药而愈，否则定成废人矣。彼拍案而立云：果如此，明日即出城税居僧舍，屈先生迂步就诊可也。次日果移寓天宁杏园。余以六味地黄汤，去泽泻，加当归、麦冬、五味、远志，而用人参三钱，不加增减，半月即神气清朗，微发一次。嗣后兼服天王补心丹，又半月，则应酬如故。计住四十二日，因家事重大而归。晤对曰：旁人谓先生必用桂附，殊不知竟是六味地黄汤清凉药也。相视大笑。", "16174": "休邑蔡毓征兄，寓瓜镇，修得异疾，时四月初旬，或周身头面作痒，痒至不可解，遂赤身卧于棕床屉，滚擦不休，少刻头面遍身皆红肿而痒不息。余至诊脉，则浮数无伦。《内经》有刺风一证，不若此甚，而多红肿，脉又数甚，殊不似也。因见肆中觝鱼甚多，《本草》觝鱼别名癞鱼，食之令人多发癞。疑其食觝鱼，询之果然。问其食时有异否，云食鱼脑觉舌麻，此中鱼毒无疑矣。急用甘蔗汁、芦根汁橄榄汤，频频杂进，时许即止。而遍身皮破，痛楚旬日，落去外肤方愈。大凡食物有异，即当弃而勿食，此可鉴矣。", "16175": "吴佩元兄，狎妓酣饮，真阴亏，损其本质也。忽两胯结两核，但肿而不红不痛，疡科以鱼口治之。盖因其平素有外色，彼亦自疑，遂甘服五虎毒剂，下之不消，久而自散。缘此伤阴咳嗽，亦属他医所治。后两膝下忽又结两核，亦肿而不痛，就治于余。诊其脉细数无力，上咳嗽而下结核，此真阴虚竭，津枯血少，为火结核也。以《外科证治准绳》结核证，与彼视之，作下部疮疡，用六味地黄汤，加沙参、贝母、归、芍、麦冬等十数剂，其核一夜全消。医治一月，嗽亦全止。隔年余，忽大吐血，其素相好之医，斥地黄汤为毒药，吐血者服地黄汤，百不一生。不曰阴虚，而曰虚冷，先以桂枝、归、芍、细辛、木通、甘草、姜、枣、当归四逆汤治之。血不止，改用真武汤。又不止，再加干姜，乃血尽自止，遂归功于姜附，用之经年，渐至喉痛失音，藏毒溃脓，而犹不悟，延至喉烂肛烂，百苦而殁。夫恣用苦寒，浪投辛热，不辨阴阳，皆非王道，病家医家，可不慎诸。", "16176": "吴虞能兄，得肺痈证，自不知，而医亦不识也。正月半后，招余往诊，则围被抱火，身坐火箱，犹畏寒甚，但云咳嗽不能卧，寒热时发，胸背胀痛，初医先云伤风，继云肺寒，用桂枝、细辛、干姜、二陈等药，已十余日矣。诊其脉，两寸涩而数，以手按其胸背，则内痛甚，口出腥臭腐气。此肺痈将溃，故作寒热，非真寒，乃内痈作脓之寒也。令其去火，急平肺排脓，使痈早溃，免传他叶。用苡仁、贝母、桔梗、甘草、防风、桑、杏、地骨皮、金银花、白芨，四剂，则黄白臭脓日吐两碗。因嗜烟酒，肺素大热，幸不气虚，脓尽之后，现阴虚细数之脉，发热盗汗之证。此盖金病不能生水，纯用六味地黄汤，去泽泻，加苡仁、贝母、麦冬、沙参、紫苑、五味等药，百剂方护完口。乡居数月，静养而康。", "16177": "族叔伟然，自扬来就诊，但称两足无力，喜饮茶汤，其脉细而数，两尺尤甚，乃伤精失血之脉。询其梦遗否？答云：并无此病。因其多饮，拟为消证，令其尿贮盆中以验之，然后用药。次日复来，云尿上有浮脂，下有浑浊。予告曰：三消之证，已得二矣，渴为上消，小便变为下消，精随溺出，两足无力，将成痿躄，大病也。须清心寡欲，以善药治之，何独以足疾为患耶。遂以六味地黄汤，去泽泻，加人参、黄耆、菟丝子、麦冬、五味子为煎剂，早晚服枸菟丸三钱。客寓于真州园亭，医治百日而愈。复立左归丸方，令其归场日服。后因中年无子，不能节欲，数年后疽发于背而殁。消证有心自焚而死者，此证是也。", "16178": "员秉干中翰长郎，年十三岁，出痧之后，咳泻两月，诸药不效。最后医家竟用二神之破故纸、肉蔻，而咳泻更甚，便令予诊。脉长而数，告曰：此胃热，非脾虚也。必因瘀证未用石膏，致余热仍归肺胃，邪热不杀谷，故洞泻。幸热毒未全入肺，赖有洞泻分消其热，若不泻，则咳嗽发热，已成痧劳矣。予以清热为主，热退则泻自止。遂用苡仁、贝母、栝蒌、地骨皮、麦冬、知母、桑皮、木通、桔梗、甘草，四剂，反大泻数次而泻减。再十余剂，咳嗽皆愈。治病必求其本，若见病治病，奚有当哉。", "16179": "族誉六郡丞，莅任梧州，其地山多而湿，暑月病疟，土医攻劫而愈，不无伤气。病方愈，即丁艰回籍，道经梅岭，路发眩晕，有如中证，晕退即两足痿痹不能立，不能步矣。归来召诊，脉细濡微数，头微晕，足肿微痛，尚可伸缩，未致缓纵，但形盛气虚，多痰多火，表虚多汗。此气虚而伤湿热，谓之痛痿。群医主治不同，或用桂附，或用知柏，或专补肾。余曰：病居下体，著而不行，脉不浮弦，非风也；脉不紧而痛不甚，非寒也。今脉濡而细数，两足肿，此气虚伤湿。遵经治痿独取阳明，以人参、白术、半夏，补脾燥湿；天麻、秦艽、续断，补湿热而利关节，湿则客人皮肉筋骨；归芍滋血以舒筋，乃热因湿化，不用苦寒，恐其有伤胃阳，转致湿不能解外；以加减虎潜丸，滋补肾元，以坚骨痿。如斯平补，半载有余，遂可步履矣。", "16180": "西林族侄，本脾肾寒之质，因未得子，常服温剂，房事之后，气忽欲脱，心慌头眩，汗出不寐。他医用人参两许，附子三钱，如此重剂者。四五日，已服人参十数两，汗出虽止，而心慌眩晕，多餐不寐，仍然不减，相招治之，诊其脉，细数无伦。余曰：始病庸或阳脱，参附未为不善，今已阳回而阴竭，遂当阴阳平补，脉细数不寐多餐，皆阴虚脉证，附子不宜用矣。余用古方益气补肾汤，人参三钱，黄耆、白术、茯神、山药、山萸、当归、五味子、甘草平补之剂，服五七日，遂得寐，眩止。渐次平调，百日后，食饭毕，必吐饭一二口，并无饱胀恶食之象。彼以为多食之故，遂减饭，而吐如故，用六君子汤不效，用清胃降气药，亦不效。因思随食随咽即不吐，停食不咽即吐者。盖不咽，则肾气不下吸也。《脉经》曰：阴虚阳无所依，故令人多呕者。此证是也。即遵其治法，用六味地黄汤本方，服四剂，吐即止，饮食如常。已现阴虚证矣，而日服补阴之药，加入人参，调治年余，已可出门，应酬如旧。但因三年前阳脱之后，毕竟真阴大伤，遂有微咳，咳之不已，即吐血。因吐血而易医，尽翻前案，谓多服人参之过。遂绝去人参，专投苦寒，以图一时见效。虚作实医，致蹈虚虚之祸，反成真劳病，不半年而殁。", "16181": "李子立兄，便浊经年，因豪饮而起，初必湿热，久则成虚，迎余求治。余曰：淋浊须分：淋自膀胱，出于尿窍，或膏或血，与尿并出，出则无余；浊为败精，出自精窍内，虽大痛而尿自清，或在尿前，或在尿后，便后尚有余沥，马口常湿，必污裈裆。以此分别，庶知疗法。李兄云，如此则是便浊。及诊脉细涩无力，两尺尤甚，盖此证便久伤精，愈通愈痛，所以内痛连肛，以及尿管。医者疑是梅毒，用疳疮治法，以龙胆泻肝汤，合八正散，服下痛不可解，腰曲不能伸，皆误用通利之太过也。余用六味地黄汤，加当归、麦冬、五味子、车前、菟丝子、人参，十数剂痛止，而浊尚不禁。再以卫生膏早服三钱，煎药更加黄耆，夜服枸兔丸三钱，两月余浊止而病全愈。但尿不能直出，必分岐两道，觉中略有碍处。予曰初病时，乃因酒湿流注，阴茎内必有小疮，故阻小便分为两道也。易以清心莲子饮，用人参、黄耆、生地黄、当归、麦冬、黄芩、地骨皮、车前子、泽泻、甘草、莲子，十余剂疮消，小便遂为一道出矣。", "16182": "张紫山学博，初夏自真州归，其夜小便频频欲解，又复不多，有二三十次，初不知服何药。三日后小便略通，即肛门下迫而痛，频欲大便，而粪又不燥，竟不能坐，惟欹倚而立。诊其脉，沉弦细紧舌紫微渴。余以初病小便频，脉又沉紧，作厥阴中寒处治。用当归四逆汤本方，四剂不效。先年曾患痔，又令疡科视之非痔，用补中益气汤，则痛坠愈甚。详审其脉，沉细而紧，少阴脉也。肾主二便，闭窍于二阴，频频欲便，亦少阴病也。作少阴下利治法，用四逆加人参汤主之。附子三钱，茯苓、干姜各二钱，人参、甘草一钱，二剂知，四剂减，八剂肛全不坠。又仍如初病时小便频而痛也，余因悟初由厥阴失治，传入少阴，得四逆汤出少阴，又复回厥阴矣，重用当归四逆汤本方，加干姜、附子，两阴并治，惟恐过热伤阴。每日间服乌梅丸六十粒，以通其格拒之邪，七日后则全愈。议以八味地黄丸调理，三四服后，虚火发而停药，病已痊。一月复如前，小便频解而作痛，彼以前效之方，自配药服，愈服愈甚，又求治。则脉细数，两尺更甚，与前脉不同。余曰：此肝肾虚火，必失精之故。紫兄云：数日前果梦遗惊觉，未泄也。余曰：此肝火证，非前肝冷证，因遗未泄，必有瘀精，用生料地黄汤，去山茱萸，加牛膝、车前子、当归、赤芍、生甘草，七八剂后，痛止溺通，出败精而愈。夫均一人也，同一病也，前后治之各别而皆效者，凭脉故也。此凭脉不凭证之治法。", "16183": "乔世臣大行，少年时伤寒，为医过饿，又多服苦寒贻患，中寒痰饮，每年必发数次，腹痛呕吐，痰水盈盆，而前医犹清饿消克。及余治之，例用干姜、桂枝、茯苓、半夏，甚则加附子，每发辄效。医治屡年，发亦渐轻，病已愈矣。而世兄犹恐其夏至举发，先期预服效剂，乃前姜附苓夏等药，不虞病退不胜辛热，遂至吐血，方停前剂。然余亦不敢用苦寒，因其辛热伤阴，非真阴虚损，暂用生地黄、茯苓、山药、丹皮、鳖甲、阿胶、麦冬、苡仁甘寒之品。然吐血不过一二口，随发亦随止。一年后渐增咳嗽，胁肋隐痛，间有喘咳不能卧者一二次，脉亦细数，将成弱证。常以熟地黄、茯苓、山药、丹皮、人参、沙参、麦冬、阿胶、紫苑、五味子滋补肺肾之药，服之下辍。前所服术附干姜，一片不能入剂矣。如斯三年，幸善为调护，方得血不吐，而咳亦宁。然后可服参耆归术补阳之药，但遇劳发咳，仍用前地黄取效。今年逾强仕，阴阳两虚，即麦冬、贝母，皆不禁清凉，反用八味地黄丸而咳嗽止。此皆因先之苦寒过饿而伤阳，后之辛热过剂而伤阴，致体虚多病，用药可不慎诸。", "16184": "郭元威学博，壬午年三月犹寒，深夜步归，平素脾肾阳虚，有痰饮夙病，次日即胸胁大痛，呕吐痰涎，虚阳上泛，面赤脉大，汗出如水。药用干姜、附子、人参、半夏、茯苓、吴萸，时痛时止。如此七八日，忽痛吐紫黑血碗许，则胸胁痛减，下移于腹。前方加当归、赤芍、官桂，换炮姜以逐下焦之瘀。又数日，大便下黑血，其痛乃止。此中寒痰饮，血因寒畜也。继以理中丸加桂、苓、半夏，兼用八味地黄丸，加倍桂附。更入胡芦巴，以宣下焦之气，水叠为丸。每日仍服理中汤一剂，虽不能如平常之健，亦复起居无病。至癸未年四月初旬，旧病复作，又如前痛吐，手足厥冷，汗多面赤，彼不自以为虚，坚不用参。殊不知痛吐亡阳，胸痛引背，脉疾烦躁，势将痛脱。急令用人参五钱，生附子三钱，干姜、茯苓二钱，渐次痛宁得卧。续用熟附子、炮姜、理中、苓夏调治，犹未起床。因夏至将临，惟恐阳虚阴逼，所以姜附未退。至五月初一，即咳嗽，犹以为寒痰，用桂枝、生姜、苓夏温肺，而咳愈增。至初六，适值夏至，即大热大渴，大咳吐血，不能平卧，脉变大数，全现阴虚，反属阴气当生不生，而转阴竭。未敢遽用清滋，先以入味地黄汤试之。犹不胜其热，再以六味地黄汤加沙参、麦冬、五味子，方合病机。热遂退，咳渐止。人参减半，未全去也。自夏至秋，皆如此医治，亦复起居如常。因本质虚寒，立冬后即改服八味地黄丸煎剂，用去附理中汤加半夏、茯苓、人参未辍。至十一月初一，冬至将临，又现阳气不生之证，忽霍乱腹痛，吐泻大作，痛止即下利不禁，呕呃昏沉，手足厥冷，已治终事。急用四逆汤，加人参五钱，姜附各三钱，日服三剂，三日方回阳。又医治一年，药不少间。然过劳必发，寒热腹痛，呕吐汗出，热退即身目俱黄，溺赤，俨如瘅证。此阴黄也，全不用茵陈等药，坚服参术姜附苓桂。三年之中，濒危者数次，至甲申年冬月，方能出门，应酬如常。若非任医之专，服药之一，何能至此耶。", "16185": "许沧澄兄，年二十外，久病真州，招余往治。询病源于前医，谓秋间患夹阴伤寒，治未痊可，而即停药，至冬则甚。其时十月上旬，诊其脉虚细无神，而举止无沦，神思疲倦，默默不欲见人，一派阳气虚弱之证。用归脾汤加肉桂、益智仁，去木香。告曰：须冬至一阳生，病退方妙。至其时果半愈。后因庄房回禄，闷步于庭，三日不寐，遂病剧矣。次年三月，复招往看。及就诊，两手掩面，不敢见人，窗牖障黑，昼日燃烛，两手枯白，筋露青紫，两足筋惕，身肉𥆧动，足踏火，手抱火，犹然畏寒，三五日必梦遗一次，虽无梦亦遗，尿管连肛精道涩痛，口渴欲饮，饮必火上沸汤，惟吞一口，旋吐冷涎，日食十余餐，俨如消证，闻人履声，便惊汗出。惜费不肯市参，以致危笃至此。又米令兄，见其沉重，托余急救，一日三诊，而脉三变。初则虚大无伦，服参术姜附药一剂，脉略敛。近夜即细涩无神，盖脉资始于肾，脉之频变，肾虚失其常度。渴者，肾虚引水自救也。多餐者，胃阳发露，皆亡阳脱证，非寻常药之能治。立千言医案，定议用仲景附子汤治少阴病者。人参三钱，附子三钱，白术、茯苓各钱半，芍药、炮姜各一钱，不须加减，以俟阳回。如此坚服一月，而畏人畏亮，筋惕厥冷阳脱诸证皆愈。四月来扬就医，则脉证与前大不侔矣。脉虚大而尺数，两足阴囊皆肿，肛右尿茎内痛，微咳多餐，夜反不寐，梦遗虽疏，而未全止，多怒詈骂。此阳甫回而阴旋虚，用金匮肾气丸，日服三钱，以消其下部之水。用归脾汤去木香，加菟丝子、龙骨、五味子以固精。用一旬则脉数大，咳嗽胸痛。又用六味地黄汤，去泽泻，加当归、人参、麦冬、五味子、菟丝子，相参间服。如此调治五十日，方能步履。回真州，肌肉充于平昔。病有变迁，医不可执，岂以初治辛热得效，遂为始终不易者乎。", "16186": "山西典客宋兄，因多餐肉食，而兼生冷，微有感冒，胸中饱胀，腹痛便秘。此当温中化滞，而前医概用山楂、神曲、麦芽、腹皮、枳朴消导之剂。殊不知冷食积中，须温方化，过用消克，反伤胃阳，而食愈结。医不知此，消导不放，以大黄下之，惟便粪水。又以丸药下之，则冷结不通。计二十日，请治于余。脉细紧，手足清冷，胸结而硬，舌紫苔白。幸肾阳不虚，上结于胸，未下结于藏，用苍术、半夏、干姜、附子、白蔻，十剂胸结方开。下注腹痛，加肉桂，日服半硫丸二钱，惟进谷汤，不令清饿。冷秘二十八日，大便微通，初硬后溏，大黄丸得温方化，洞泻数次，然后胸腹大开。后以理中汤加苓夏砂仁温胃，匝月方瘥。", "16187": "大升典客毛兄，素有眩证，发则昏仆不知人事，一刻即苏，起则如常，积有年矣，前医皆作痰治。近因眩跌阶石，触落门牙二个，血流不止，急招诊视。牙已落矣，而人事如常。诊脉细数，两尺尤甚。问彼眩时何状，答以头一眩，便不能自主，瞬息即苏。问素有何病，答曰：梦遗三两日一次。余曰：此虚火也。阴精竭于下，阳火逆于上，龙雷之火，一发即隐。《内经》所谓煎厥也。用生地黄、熟地黄、山萸、山药、元参、菊花、菟丝子、丹皮、石斛等药为汤，丸亦如之，日服不辍。经今数年，已不发矣。", "16188": "贡姓武弁，年二十余，取耳时为同辈所戏，竟以铜穵刺通耳底，流血不止。延外科治耳，初不以为楚，仍行走街衢如常。旬日间即头痛，又延内科治之益甚。迎余往治，则头痛如破，身体僵直，烦躁面赤，脉弦而紧，仰卧于床，口流脓血。余沉思良久，以为此必破伤风也。检前所服之药，皆石膏、栀子、芩连，作火头痛治。病人云：口吐脓血，不是喉出，不知从何而来。予曰：此的系破伤风矣。脑中脓血，流入鼻内窍，而渗于口中，非由咯吐而出也。破脑伤风项强，已属不治，此幸未柔汗厥冷。用小续命汤重加桂枝、附子、干姜，去黄芩，一剂微汗，头痛减半，两剂颈柔。十数剂后，耳内结痈，脑涎亦不流，但其耳褎然无闻矣。", "16189": "程士莘兄，朱姓家人，身体壮实，跌伤手臂，皮破出血，专科不过膏贴药敷而已。不自知谨，混堂洗浴，脱衣伤风，次日便恶寒发热，头疼身痛。先医者作伤风阳证治之，三四日后，大汗呕吐，僵卧于床，手足拘挛，角弓反张，始招予治。左右脉皆沉弦细紧，口眼抽掣，而跌伤之处，反不知疼。此证初病失于温经，反行解表，致风寒内入，直伤肝经，破风反张，大汗呕吐，均属不治。幸未入少阴而下利耳，遂用桂枝、细辛、芍药、附子、干姜、当归、独活、天麻、吴萸、甘草重剂，五日汗敛身柔，呕止能食，而手反不能举，软卧于床。桂附大剂，一月方能起而立，若非年少壮实，万无生理矣。", "16190": "吴瞻大兄，冬月足背生疮，久溃不敛，一医者令用刀去顽皮，不无新伤。春日苦寒，跣足就医，又敷以冷膏，随即作痒，更乘舆河畔，迎面大风，遂遍身麻痒，面肿唇紫，舌强语涩，俨似中风。先医未辨何证，杂用风火痰药，服后呕哕不止。余至，诊脉则弦紧，面赤舌紫，手冷多汗，乃肝经风病，定属患处刀伤，为风寒所袭，又兼冷膏外敷，证类破伤风，不宜缓纵。急用桂枝、赤芍、独活、细辛、附子、苍术、天麻、半夏、生姜，日投三剂，夜半患足方温。又二剂，微汗身轻，疮方知痛。如斯八剂乃愈。若非急治，缓则传里，不易医矣。", "16191": "王东木孝廉，素有中寒痰饮证，暑月头痛，医作火治，投以石膏栀芩而痛甚。自以为剂轻，益加大剂，则头痛如破，以冷水渍布，覆于巅顶，渴欲冷饮，入口即吐，阴躁卧地，因便请诊。脉已六至，细疾无伦，赤身犹谓热甚，而实身冷多汗。余曰：此阴盛格阳，若不急温，则一战而脱。急进大剂四逆汤加吴茱萸、半夏，连投二碗。孙医后至，亦同前药，但加人参，少刻寒战索被，覆以厚棉。幸先投药，少刻回阳，次日阳躁虽愈，而头疼不止，至巳午时头痛，痛即呕哕不能食，因而废食者连旬。余以头风治疗，用当归四逆汤，加附子、生姜、半夏、天麻。恐头风损目，故用归芍以滋肝也。京口医家，犹云误用辛热，及彼复投大剂石膏，则痛而厥。又易医以湿痰处治，用苍术、五苓、吴萸、半夏，而痛不止，渐至患目。经云：因于湿，首如裹，而不痛。痰厥头痛，则不患目。其家以余言不谬，复召余治，易用清肝滋血辛平之剂，头痛目患渐愈。王兄自检眼科补肝丸方，以夏枯草、香附、甘草三味为丸，日服不辍，遂头目两证全愈。其方虽名补肝，实清肝也。乃知治病宗经，必不至于大谬。", "16192": "刘振寰翁令眷，己未年在扬患病，其长郎刘必远兄，祈签令彼问治于余，遂至瓜镇。道其病源，病人年五十外，清癯茹素，初秋因郁怒，遂胸腹不宽，两肋胀痛，不食则嘈，食则不能过膈间，或吐出。郡城诸医，皆以清痰理气，丁沉香燥，治之愈剧。渐至大便秘结，数日一通，每至黄昏，即后重欲大便，空坐秽桶，不能起立，又无粪下，至五鼓方可登床。如此四十日，百药不效，困惫不堪，坐桶时能食饮汤稀粥，至登床后，天明即呕逆不能食矣。余未诊脉，以意度之，此肝火也。先因郁怒伤阴，继复香燥耗血，致火上逆，则呕吐，下迫则后重，昼则气升故吐，夜则气降故坠。但病久气血皆虚，须用血药以滋肝，左金以折肝，参草以补中，定方立论，用当归、白芍、人参、茯苓、甘草、黄连、吴茱萸、山栀、橘红，令彼持回试之。如大效，再易方。服二剂，即不吐，四剂即出下气，不坐秽桶，夜可就枕。再索药，即照前方，服至二十剂，即霍然起矣。余初有移居郡城之意，未果，因彼再三谆请，迁意遂决。", "16193": "吴言修封翁夫人，年近六十，素有痰饮证，发则胁肋大痛，呕吐屡日，痰尽则痛吐自止。乙亥首春，痛吐已六日，前医以宣气利痰为主，用旋覆代赭石汤，加吴茱萸、干姜，药皆不纳。第七日招余，左右手六脉皆伏，推筋著骨皆无，水饮不能下咽，似属逆证，而声高音朗，坐起如常，无厥逆汗出等证。此吐甚伤气，致脉全伏，当以温里为急。用干姜、附子、人参、半夏、茯苓各钱半，吴茱萸五分，一剂即下咽不吐，再剂相安得寐，四剂痛止。但脉不出，续进米汤，三日后脉出如丝，大进粥食，脉始全见。嗣后每痛吐，脉必伏，用前药即效。痛吐止后数日，方能服白术理中等汤，而甘草竟不能入剂，用则必呕。至壬午年四月，痛吐数日不止，因年增气弱，即痛引肩背，欲食冷物，畏亮阴躁，以幔蔽窗，有虚阳上越，痛吐亡阳之机。余每剂用人参四钱，附子三钱，姜夏、茯苓各二钱。而病者坚不服参，不得已，暗加人参。大剂温补，三日方阳回躁定，去蔽窗之幔，不畏亮光。嗣后常服半硫丸，则饭食多餐，而姜附之剂，居恒不能久辍。人之藏府虚寒，此固世不多见者也。", "16194": "孙思睿翁令眷，壬戌年怀孕丧子，悲泣过伤，因而咳嗽，自秋至冬，渐至喘不能卧，两足水肿，腹胎六月。诸医治咳分利罔效，最后招予。水势泛溢，腹大如鼓，其面反瘦，脉细如丝，两尺全无，此肾水也。孕妇患水，其胎必伤，况两尺脉全无，胎已息矣。宜急治其水，以全孕妇，惟金匮肾气汤可救，遂以本方加人参一钱，附子、肉桂各一钱。如此半月，水忽大下，尽湿被褥，流溢床下，而腐胎随堕，其时气脱昏厥。令急服参附汤，而稳婆诸妇，争论不肯煎，盖以扬俗产后，禁用人参故也。幸思翁自主，推诸妇出房，用大铫自煎频灌。半日半夜，通服人参六两，附子两余。夜半回苏，而余咳余水未尽，仍用金匮肾气汤一月，始水尽咳止。", "16195": "殷凌霄兄令眷，年近年十，体肥便血，先医皆用芩连凉血寒中之剂，将两月而未痊。仲秋忽遍身发麻，合目更甚，因不敢合目，遂不寐者半月矣。诸医作风痰治疗，用星夏天麻秦艽，病益甚。请余求治，病人畏怖，许以重酬。诊其脉虚大而濡，便血犹未止，胃弱不能食，面上时有火起，此气随血下而虚也。盖卫气行阳则寤，行阴则寐，卧则卫气行于阴，气虚行于阴，遂不能周于阳，故合目则身麻也。正合东垣补气升阳和中汤证，即用补中益气汤，加苍术、黄柏、干姜、麦冬、芍药各五分，二剂病知，四剂病减，十剂血止病痊。予再往诊，病者托故他出，以避药矣。夫对证合方，其应如响，于此可见。", "16196": "陈圣年令眷，年近三十，夏月大劳之后，伤风发热，汗出不止。初医作阴寒，用参附理中汤，汗虽止而增烦热作渴。易医作伤寒热病，用柴芩白虎不效，议投承气汤下之，取决于余。诊其脉，虚大如绵而不数，烦躁不得卧者，已六日矣。视予曰：先生何著红衣耶？望其色，面赤如妆，舌苔灰黑而滑，以脉合证，乃虚阳外越也。用汤试之，喜热饮，饮止一口，则非大渴可知。盖此证本于劳倦内伤，而兼风暑，所以多汗发热。初医者因汗多误用姜附，以致烦渴。继医者不辨虚实，翻用苦寒，虚作实医，逼阳外越，俨如热病，正合东垣当归补血汤证也。证似白虎，但脉不弦长为异耳，误服白虎必死。今误服不死，幸也，岂堪复投承气乎。余用黄耆五钱，当归三钱，麦冬一钱，五味子五分，服后得寐片刻。再剂熟寐时许，醒则热退面黄脉敛。次日往诊，惟舌黑不改，盖前姜附之余也。用前药减黄耆一半，加人参、茯苓、甘草二剂，舌苔黑退，变微黄色，遂思饮食。如此平补半月而愈。", "16197": "程若思守戎令眷，年二十外，腹痛作泻已久，渐增口舌生疮，因疮痛不能食热物，益致痛泻不止。前医谓痛泻宜温，口疮宜凉，用药牵制，辞不治。决之于余。诊其脉，两关虚大无力，食物便呕，呕止即腹痛，痛则下泻，而满口之疮，白如米粒。余曰：此脾虚寒也。盖脾土虚则肾水乘之，逼心火上逆，致口舌生疮，乃上焦假热，实中焦真寒。惟治其寒，不惑其热，宜用附子理中汤冷饮，使暗度上焦之假热。而冷体既消，热性随发，脾土得温而实，则肾水不上乘心，心火不逆，口疮不治而自愈，此五行相乘之道也。遂以附子理中汤加茯苓，令其冷饮，病人不知有姜附也。服四剂，口疮果不痛，再求治痛泻。予曰：但药热饮，则痛泻自止。温补一月，痛泻方愈。后十余年，怀孕病痢，亦用桂附干姜而愈，胎竟不堕。人之藏府各异，不可以一例论也。", "16198": "休邑汪介臣，流寓瓜镇，孙媳素有脚气证，余不知也。产后弥月，脚指微痛，继又乳痛。前医者不知用何药，脚乳皆不痛，渐次发热耳聋，言语谬妄，或歌或笑。又一医作阳明病，用大黄下之，下后愈甚。十日后求治于余，两手脉沉细欲脱，耳聋神昏，唇焦舌黄，身微热，口苦干呕，身痛僵卧，不能转侧，夜则呢喃谵语不休，至辰刻乃止。邪之错杂，不辨何证。但足三阳经皆病，身痛僵卧太阳也，夜谵语阳明也，耳聋干呕少阳也，又非伤寒三阳合病下利之证。先以三阳经药投之，观其应否。用紫苏、葛根、柴胡为君，二陈为使，日投四剂，通身微汗，遂能认人。自言腰腿痛甚，余方识其为脚气也。盖前医初误致脚气冲心，再误下致脉细欲绝。幸人壮实，两误而邪尚在三阳，未入于阴，犹得汗解，始能神清。即以前药加苍术、防己、独活、赤芍、当归，作脚气主治，痛渐下注于足指，半月方愈。若入三阴脚气冲心，即喘汗厥逆，不可治矣。", "16199": "俞子浩兄令眷，年近四十，艰嗣多郁，颈傍结一核，数年矣。后因丧子，其核渐大，内逼咽喉，妨碍饮食，有似外科失荣证。疡科作瘿瘤治，愈大愈坚，渐加发热咳嗽，竟似失荣证矣。用逍遥散治之不效，又仿《外科正宗》，用益气养荣汤，内有参耆。甫二剂，便喘不能卧，由是医药杂投，有用葶苈泻肺者，有用苏子降气者，渐致汗出泄泻，阳气下脱，六七日喘犹不止，已备终事，复商于余。诊脉细数，余沉思良久，其先结核，乃肝木部位，郁久化火，此火结之核，尚非失荣，误用黄耆，助其肝火，火灼肺金，因而大喘。先无他病，虽然喘久，断非气脱，盖乙癸同源，肾肝同治，补肾滋肝，引气下归。用六味地黄汤，加归、芍、麦冬、五味子、牛膝，服四剂喘定，二十剂能平卧。后用六味地黄丸，加沙参、元参、贝母、归、芍丸药三斤，并结核亦全消矣。", "16200": "吴侣张佥宪尊阃，素有饮证，频发呕吐，医者用生半夏、生附子，以生姜汁入药调服。如斯一月有余，计食生姜二十斤，意图除饮之根，不无用药过激，遂致耗气亡阳，七日夜不能合眼而寐，招余往诊。脉浮细如羹上之浮脂，指点便散，自知周身之气，行于皮内，淅淅有声，行至巅顶双目前，如眼镜两圆光荡漾，即遍身汗出，昏眩不知身在何处。余曰：此真阳外越，不急救之，瞬息便脱。用仲景之附子汤，人参、白术、茯苓、附子、赤芍各二钱，服后得合目昏睡片刻，醒时两圆光即收。本日又进一剂，夜则熟寐达旦。如此六七日，人事方清爽。痰食是其本病，嗣后以前药去芍药，加半夏、甘草，畏生姜不用，医治两月，方能出户而立。缘生姜辛能散气，多食几至亡阳，此过剂用奇之患也。即以前药为丸，十年不发矣。", "16201": "李三升文学尊堂，年七旬外，春末胃中大痛，呕吐紫血碗许，而痛吐犹不止，脉细数而弦，两胁肋胀痛，胃中硬满，因怒未伸而致病。经云：怒则气逆，血郁于上。此证是也。用归、芍、郁金、黄连、制吴萸、丹皮、黑山栀，以滋抑肝气之逆，少加沉香，以为向导。连服五七日，痛虽止，而胸阻塞不开。易医谓高年胃冷，用辛温宣气之品，即大便秘结不通，食饮难下，脉变细涩不堪。予议高年血液枯衰，火结于上，恐成膈噎，辛燥不宜。而病人亦恶药，遂以芦根、甘蔗、梨、藕、莱菔各取汁煎膏，用人乳、竹沥调化，频频咽之。半月胸结始开，能吞稀粥。竟不服药，惟食汁膏，尚延数载。", "16202": "程锡蕃兄令眷，夏月酷暑，夜忽畏寒索被，即气塞喉中梗噎，无奈坐起，大吐紫血条并血水，约半盆。深夜请附近医家，误认阴虚，用凉血藕节等药。次日往视，脉沉而紧，手足清冷，胸腹胀大。此因暑月贪凉食冷，本质虚弱，气被暑伤，中宫益冷，不能健运，蓄血暴吐，乃经之阳络结，则血上溢之病。急宜温里，若作阴虚，指日便成蛊证。用桂枝、赤芍、生姜以温经，用苍术、茯苓、炮姜、砂仁、甘草、半夏以温里。如斯八剂，身得大汗，腹中肠鸣，溏泻数次，肿胀方消。后以六君子合理中香砂，调治而愈。", "16203": "萧我容翁令眷，年近四十，戊辰夏月，胸胁胀满，吐血涎血片，两三日一发，饮食衰少，而经水时或大行不止，有似崩漏。初真州时道，皆以凉血滋阴为主，以致脾胃益虚，竟不能食，来扬就医。脉之细濡不任寻按，有时忽大。此思虑伤心，脾血不归经，非真阴虚损。丹溪云：胃虚则血出上窍，脾虚不裹血，则血下崩。此非血热妄行之证，用人参、白术、茯苓、炮黑、姜香附，温补中宫。用当归、白芍、枣仁、丹皮，以和营血。重用人参，服一月，吐血先止，下血暂少。后脾胃得温而胀减，再加黄耆、元眼肉，合归脾汤以收功。", "16204": "张其相兄未出室令爱，首春咳嗽，乃恣食生冷，肺受寒邪，所谓形寒饮冷则伤肺也。前医初作伤风，以苏前解表。殊不知邪不在表，而直伤肺，不知温肺，致寒不解，咳甚吐血。前医见血，遂改用归、芍、丹皮、苏子、杏仁、贝母，以清滋肺热。服二剂，遂发寒战栗，手足厥冷，身痛腰疼，咳吐冷水，脉沉细紧，表里皆寒，正合小青龙加附子证。用麻黄、桂枝、细辛、赤芍、干姜、附子、半夏、茯苓、杏仁、甘草，二剂手足回温，四剂通身冷汗大出，咳止大半。再去麻黄、附子，二剂全愈。若泥吐血阴虚，迟疑其间，安得有此速效耶。", "16205": "周旦友令眷，年近三十。两年前产，值隆冬，又因气郁，少腹之旁，结有弹大一丸作痛，初亦甚微，后渐痛甚，上冲心胁，呕吐不食，必待其痛吐气衰，一二日方止。医治两年，作气积血积寒气，攻劫皆不效。人渐消瘦，经水数月不至，家居于乡，上城就医。其脉弦而紧，询其病状，答以不发时间或寒热似疟，胁肋常胀，发则少腹之弹丸即长大如王瓜，痛冲于心，呕吐不能食，衰则仍归于少腹。此产后冲任脉虚，寒气内袭，积瘀凝结，为妇人之疝瘕。此厥阴肝病，故自下而厥于上也。用肉桂、附子、当归、赤芍、柴胡、川楝子、乌药、小茴香数十剂，发日渐疏，而痛亦减轻。续以东垣酒煮当归丸服半年，经水始通，痛亦不发。但少腹之弹丸，终不能消，而亦不孕，数年后变蛊病而殒。盖此证攻劫所伤，经水断绝，正气衰微，邪终不散，故寿亦不永也。", "16206": "吴饮玉兄令眷，未出室时，左肋下素有气积，时时举发而痛，在家皆用逍遥散治之罔效。嫁后怀孕三月，此积竟冲心而痛，痛甚昏厥，手足逆冷，口出冷气，脉沉弦而紧。此肝经积冷，结为冲疝，非桂附莫效。又属世医之女，且怀有孕，举世皆禁桂附，予何敢用焉？其太翁言修先生曰：大人要紧，胎且置之。遂投以当归四逆汤，桂枝、附子、当归、芍药、炮姜、吴萸、甘草、茯苓，服下即应手取效。每食生冷必发，发则必须前剂，怀孕在腹，屡发屡医，而胎竟不伤。今所生之郎，已十有余岁矣。后以东垣酒煮当归丸，服三年未断，其冲疝不发，并形俱消，屡屡生育。经曰：有故无殒。先圣之言，岂欺人哉。", "16207": "徐从甫令爱，年近四十，暑月病疟，治失其宜，疟虽止而遗病不痊，自毗陵来就医。脉细涩无神，脾胃败伤，呕酸腹胀，面目浮肿，发热自汗，不思饮食，形骸骨立，经绝不行，已半年矣。检毗陵药方，皆干姜、丁、沉、吴萸、半夏、陈皮、厚朴疏削等药。疟后气血交虚，何能当此燥剂，致增诸证。余用人参六君子汤，加当归芍药砂仁，平补以调气血。一月有余，病减半能食，热退而汗全止。次年春间，值彼诞辰，大劳数日，前证复作，更多咳嗽喉痛，口舌生疮，夜出盗汗，俨似阴虚劳病，拟治后事。予曰：脉不细数，虽经不至，真阴未伤，犹可治也。不过因劳而复，仍属脾虚。《中藏经》曰：脾虚则上下不宁，谓咳嗽发热也。此为假火，不可以水折，反用人参、白术、茯苓、炮姜、麦冬、五味、甘草，合理中生脉汤。服二剂，口疮愈，再二剂，喉痛止。去炮姜，加归、芍，十数剂热汗咳嗽全退。后以白术煎膏，人参汤化下，专主补脾，百日而康，经亦续行。", "16208": "教门阮汉章室女，年十七岁，素脾虚作泻，因丧弟悲恸，即经闭半年，腹中有形而痛，发热咳嗽，腹胀作泻，虚劳证全。《内经》云：二阳之病发心脾，有不得隐曲，女子不月，其传为风消，为息奔者，死不治。此证幸其脉细缓，不涩不数，真阴未伤，尚属脾虚，犹为可治，然非百剂，断不能取效。市井之医，欲攻积通经，予止之曰：血之源本于心脾，今心脾俱病，血源不生，虽通无益，徒伤阴也。遂用白术、茯苓、甘草、丹参、土炒当归、鳖甲、沙参、香附、陈皮等药，果热渐退，咳泻皆止，但腹胀未减，经闭未通，腹有结块。此必积瘀，用古方万应丸，以生干漆炒去黄烟为末，用地黄、牛膝熬膏为丸，日服三十丸，米汤清晨吞下。将一月，经水即通，下紫黑血块，渐次腹消。仍以前药调治而愈。若不先治其本，妄行攻坚，鲜有不败者也。", "16209": "程其相兄令眷，咳嗽二旬，先医作伤风治不效。又医作肺寒，以桂枝、干姜、细辛治之益甚，又一医作痰火治颇安。最后延余，诊其脉三部皆涩。不浮弦，非风也；不细紧，非寒也；不滑数，非火也。每日寒热汗出，鼻有清涕，咳嗽不能卧，右身不能著席，痰涎甚多，又非虚损。初诊未得病情，即前医痰火颇安之药，姑以应之。及出门后，追思其证，应属肺痈，令人取回前药。问所吐痰涎，气味腥甜否，彼令侄追至黄师古兄宅中，答以腥甜。余曰：几误矣，此肺痈将溃也。易用苡仁、贝母、甘、桔、桑、杏、麦冬、白芨、银花、防风，服后臭脓大出，间吐鲜血，脉方现数。盖因前痈未溃，肺胀大，脉反涩而不出，故不数也。病人素阴虚，臭脓去后，便有发热盗汗等证，易用熟地黄、山药、茯苓、丹皮、紫苑，兼补肾阴。时当酷暑，少加人参、五味、合欢皮，以救肺金。迨秋气清凉，方获口完咳止。隔年因多食椒姜，其痈复溃，亦如前法治之而愈。", "16210": "式武族侄令眷徐氏，年将三十，平素嗜烟，因内热复恣食生冷，性又畏热。夏初伤风，未经发散，肺藏寒热素伤，外风未散，郁而为肺痈。初不知服何药，痈已成，始迎诊视，则咳喘不能卧，寒热互作，项强不能转侧，脉浮大而数，此肺痈将溃矣。告曰：肺上生疽。彼尚不信，用苡仁、贝母、甘、桔、葶苈、防风、桑、杏、栝蒌等药，服三四日，大脓一出，皆粉红淡血，及黄色稠脓，但腥不臭耳。他医谓非肺痈，果痈则隔幔犹臭，今不臭，非痈也。不知此痈因风因冷而伤肺，非火热刑金之证，乃肺疽，故不臭也。医治十余日，脓尽肿消，不甚咳嗽，彼以为脱然而愈矣，遂畏热露卧檐阶，夜受风凉，次日大热大喘，犹秘不言。至第三日手足抽搐，头痛如破，汗出不止，周身痛极，颈项后仰，角弓反张，昏厥下利。询之再三，始言其故。余然后知为破伤风也。外患疮疡，破伤风寒，角弓反张，尚为不治，今内痈伤风，则更难治矣。已备棺衾，求余格外治之。遂以桂枝、细辛、赤芍、附子、炮姜、茯苓、甘桔，先治风寒，仿小青龙治法。如此药不易方，服七日，身方柔软，汗泻稍宁，略有生机。忽又发喘，不能平卧，腹胀如鼓，两足肿硬又成水蛊，此平素饮冷之故。遂朝服金匮肾气汤一剂，桂附各一钱，以治水，午用人参、白术、炮姜、茯苓、苡仁、五味子、甘桔，补中保肺。盖病者中寒，麦冬贝母清润之药，一片不能入剂。倘误用之，则泻不止故也。肿消喘定之后，肾气汤易为丸，参术煎药，计服百剂，然后痈完咳止。嗣后不能断烟食，冷咳肿病，每年必发，皆以温肺温胃而愈。此肺痈变证，治病必须圆活，因病制方，不宜固执也。", "16211": "真州张右山兄令眷，久便血不止，以病状来郡，问治于余。询前治法，先用归地凉血不效，继用补中益气不效，又用归脾汤，重用人参，亦不效。困惫在床，求药治疗。证经三治法罔效，岂非阴结乎。经曰：阴络结则血下溢。余用桂枝、赤芍、生姜、大枣，和营而开络，人参、白术、茯苓、炮姜、甘草，补脾以助其健运之常，当归、枣仁引血归肝。姑以此试之，不意竟属斯证，三次来郡取药，半月而血全止。续后咳嗽气促，乘船来郡就诊，脉细紧，两尺犹甚，咳而兼喘，颈脉大动。予曰：便血既久，气随血脱，肺脾肾三经皆虚，将成水肿，惟有金匮肾气，汤丸并进，加人参于汤药，坚心久服，方得取效。病者乃同道李仲易兄之姊，仲易兄医理精通，不以予言为谬，坚服百剂而愈。", "16212": "李怀白兄令眷，程休如先生之令爱也。怀孕六月而便血者，三月矣，群医治不效，请余治之。诊其脉，濡溺如绵，视其爪甲，全无血色，两足虚肿。问其食，每餐一盂，食后即腹痛泻去，方不胀满。问其药，则四物汤加地榆、秦艽、蒲黄、香附、陈皮而已。余曰：脉证如斯，脾土大伤，不急补脾，何以大产，用白术、茯苓、炮姜、砂仁、甘草补脾为君，桂枝、当归、赤芍、艾叶温经为臣，姜枣和胃为佐。如此四剂，三月不止之便血，一朝而止矣。继以此药，不加减者两月，至次年大产一男，皆吉。产后半年，又复便血，习以为常，一月不药，因劳昏仆，此乃复病，遂卧于床，用参数两，服前药弥月方愈。反不似怀孕之时，真阴在腹而易效也。嗣后遇怒，便血常发。", "16213": "卞宅内眷屈氏，五年前便血，因医过用黄连乌梅苦寒凉药，血去肝虚，苦寒伤肝。肝主筋，遂手足拘挛，项背强痛，两胁结块，手不能曲于后，足不能履于地，坐卧于床者四年，饮食衰少，形骸骨立。幸经水犹通，天真未绝耳。因往屈宅，便令诊之。脉弦细紧。答以肝经虚冷，须服温经热药。用桂枝、细辛、当归、赤芍、半夏、茯苓、附子、吴萸、甘草立方，令其自制药服。彼畏药辛热，反多谤议，弃置不用。一年后又往屈宅，别诊他病，再请诊之，病益甚，予曰：仍是前方，如放心百剂，或效，然不可必也。因诸医遍治不效，不得已，以余方自制，姑试服之。十数剂颇安，两手和柔。来又求诊，更加干姜。往诊十余次，皆前药加减，或官桂，或桂校、附子，每剂钱半，姜亦如之。惟立药方，彼自制药，坚服半年，手即能举，足亦可步，胁块皆消，周身筋舒，竟为全人。屈宅本籍关东，崇敬时道，因不相信，故不用药，惟立方也。", "16214": "李子立兄令眷，年三十外，频次半产，产后未及满月，便乘凉食瓜果，中秋夜乘凉，外感风寒，即咳嗽恶寒，呕吐痰水，又当经水大行之后，前医不辨外感风寒，犹用调经养血补剂，见咳嗽益甚。又疑去血过多，阴虚咳嗽，再用麦冬、贝母，以致表邪不解，里冷益深。恶寒发热，汗出咳喘，坐不能卧，吐不能食，腹胀作泻，遍身麻木，筋骨冷疼。自疑必死，促备终事。急迎救疗，脉浮细而紧，余曰：风寒积冷，表里皆邪，须重剂方解，无足虑也。以小青龙汤加减，用桂枝、细辛、防风、赤芍、附子、干姜、半夏、茯苓、杏仁、厚朴。二剂得冷汗一身，遂喘定得平卧。如斯八剂，表邪解后，咳喘身痛甫退，旋即里冷发作，腹痛下痢白脓。转用附子、干姜、肉桂，合胃苓汤八剂，冷积消。胃气本厚，故易效也。", "16215": "邵子易兄令眷，年四十外，形盛多痰，素有头风呕吐之病，每发一二日即愈，畏药不医，习以为常。二月间感寒头痛呕吐，视为旧疾，因循一月，并不服药，渐致周身浮肿，咳喘不能卧，呕吐不能食，已五日矣，方请医治。切脉至骨，微细如丝，似有如无。外证则头疼身痛，项强肤肿，足冷过膝，咳喘不能卧，滴水不能下咽，沉寒痼冷，证皆危笃，必须小青龙汤，方能解表里之寒水。但苦药不能下咽，先以半硫丸一钱，通其膈上之寒痰。继以麻黄、桂枝、细辛、附子、干姜、半夏、茯苓、吴萸，煎剂与服。初剂尚吐出不存，又进半硫丸一钱。次剂方纳，如斯三日，虽小有汗，足微温，而脉不起，全不能卧，寒水之势不退。余辞之，令其另请高明。有一浙医视为湿热，用木通、灯草、腹皮为君，幸病家粗知药性，不令与尝，专任于余。改用生附子，十剂至四五日，通身得汗，喘咳始宁，方得平卧，频频小便。而下体水清，非此大剂，何能化此坚冰？后用理中桂苓加人参，匝月方健。询彼家仆人，乃平素贪凉冷所致。若此证属脾肾虚寒，则不可治矣。", "16216": "洪育沧兄令眷，于归未久，正月上旬，胃中大痛，前医用苍朴炮姜香附不效，至夜痛厥。次日迎诊，六脉沉紧而滑，昏卧于床，不知人事，手足微温，身体软重。告曰：寒痰满中，非辛热不醒。时孙医先用附子，不敢服，余用附子、干姜、半夏、茯苓、白蔻、陈皮一剂，服后半夜方醒，自言为人释放回也。次日再诊，谆言人虽醒，而脉未回，寒邪犹在，仍须前药，勿巧亏一篑也。而洪宅素畏热药，弃置不用，以他医参、术、炮姜、半夏平和之药为稳妥。殊不知邪未退而温补，反致助邪。医将一月，终日呕哕不息，饮食不餐。至二月初三，哕变为呃，其音似吠，越邻出户，连声不息，口张不能合，四肢厥冷，扬手掷足，欲裂衣袂，目珠上视，其势危笃，从未经见者也。京口名家，见病愈重，而药愈平，但用丁、沉、柿蒂、乌药、橘红、半夏应世之药而已。急复求治，余曰：脉细疾无伦，几于不见，若不以大温之药，疾驱其寒，亥子之交，必致阳脱。遂用生附子、生干姜、半夏各三钱，吴茱萸一钱。一剂气平，二剂手足回温，其夜计服四剂，吠声方止，仍如前呃。次日仍用前方，但换熟附子，加茯苓、橘红，每日仍服半硫丸三十颗。一月后，加白术合理中、六君。共计服药百剂，方能食饭不呃，经水始通，渐次调治而愈。此证可为病家医家，惟求平妥，酿病不医之鉴。", "16217": "萧俎玉兄令眷，年近三十，病头眩呕吐，饮食减少，经水不调，积年已久，因其大便秘结。真州时道，皆作血虚肝火，而以归、芍、丹皮、生地黄、麦冬、贝母治之，病益甚。甲申冬，自海陵回真州，舟中招诊。脉细紧而滑，畏寒抱火，手足麻木，十数日一发，饮食不餐，胸口一胀，即头眩呕吐，吐去痰水稍愈，隔十数日又发，遇行经而血甚少，亦不如期。以脉证相参，此气病，非血病，乃脾胃虚寒痰饮证也，所以脉紧而滑。若血病则涩矣，滋阴养血，适足益病。夫大便秘结者，津液上吐，无以润肠，乃冷秘虚秘，非燥秘也。遂用人参、白术、茯苓、半夏、炮姜、天麻、香附、生姜，以东垣白术半夏天麻汤为主，专用气药，以温胃阳，全不杂一味血药，恐助阴也。立方回真州，令其常服，两月后萧兄持煎药方来，求立丸方，谓药已中病，病愈大半。今大便反溏，非若从前之秘结，观此则非血虚燥结明矣。凡人禀气血之躯，患病不偏于气，即偏于血，不辨气血之偏，何能求效耶。", "16218": "曹启心兄如君，生育多胎，体质虚弱，有脑寒鼻塞流涕之证，怀孕七月。先咳嗽，前医不谙，以流涕为伤风，误用发散，因虚愈咳，咳甚则吐食。又以为胃寒，用六君子汤加炮姜，服之愈甚。继招余治，脉弦数六至，胎脉固当数，然不滑数而弦数。此必阴血大亏也。启兄云：平素胃寒，麦冬、贝母，入口便吐泻奈何，予曰：治病必以脉为准，今脉弦数，定属阴虚，滋阴不可，补阴独不可乎？此因咳而吐，非不咳而吐也，但治其咳，自不吐矣。《脉经》曰：阴虚阳无所依。令人多呕者此也，岂阴虚独无呕病乎。定以熟地黄为君，山萸、茯苓、山药、石斛、苡仁、沙参为臣，枇杷叶为佐。四剂知，十剂咳嗽全止。而产一男，产后再以当归、川芎、桂枝、辛夷、炮姜、黄耆温补之剂，以医鼻矣。", "16219": "瓜镇胡宅之内眷，隔幕诊脉，两尺弦数，左关单弦，独异他部，默不言病，似欲考医者。余因脉言病，谓两尺弦数，定为下部之痛，数则为热，必有血证，但不知为何病。彼家然后直告，谓一月前小便淋秘而痛，因其夫常宿青楼，疑为梅毒。疡医以斑蟊毒剂下之，致血大下而痛愈甚。经数医杂治，而病不减。非敢试医，因亵病不能直陈耳。余遂以脉辨证，弦者肝病，数者火证，少腹乃肝部，妇人肝经，内络廷孔。廷孔者，溺孔之端也。郁怒生肝火，火循经而结于廷孔，所以初病小便淋秘而痛，误行攻劫，以致益甚。因属隐疾，不便明言。以逍遥散去白术，加生地黄、炒山栀、龙胆草、木通，连进二剂。次日痛减，因复再招，遂以阴疮证书封问其夫，合病则治，否则当别延医也。其夫云的是此病，即以前方服十余剂，痛止。减去胆草、木通，加丹皮、白术、香附，十数剂而愈。", "16220": "程毓松兄令眷，年近三十，素贪凉食，冷寒注下部，致成寒湿脚气，夏触风凉，其疾即发。脚气之恶，从未经见，往岁轻举他医所治。壬午年夏月，脚气上冲，头疼身痛，呕吐不纳药，阴躁不能卧，令人扶挽而走，彻夜达旦，如犯之状，脉细疾而硬。煎剂不能咽，此阴甚格阳，格拒不入，作伏暑夹阴治法。先以来复丹碾碎，汤调服下，以通其格拒，服后方能纳药。再用六物附子汤，以治阴寒脚气，附子、干姜、肉桂、防己、苍术、茯苓、半夏，驱逐逆上之阴寒。四五剂后，脚气方下归于两足，而烦躁呕逆渐除，能进米饮。七八日足始热而痛愈。", "16221": "同道周兄令媳，值阿翁作古之后，怀孕三月，患脚气，两足肿痛，用药敷之，已不合治法。母家见痛甚，又用炒热麦麸，频熨不息，脚果不痛。而申酉时即跳跃如狂，谵言乱走，天明至日中皆安。如是三日，不识何病，因以相招。脉弦长而数，余告曰：此脚气冲心，故语言谬妄。幸两寸脉未变，脉长而数，尚在阳明。此因火迫上逆，须用肉桂，引其下行，使脚仍痛方妙。彼因有孕，不肯用桂。余谕之曰：狂跳不息，胎亦不安，去病即所以安胎。经曰：有故无殒。用桂无害也。竟用肉桂五分，余皆三阳经治脚气药，二剂即两足复痛，人事清楚，不狂妄矣。后彼家自治而愈。", "16222": "吴中璧兄令爱，年将及笄，出痧后半月，惟口甜喜唾，不思饮食，胃中隐隐微痛，脉虚软而迟。幼科以口甜为胃火，作余热治之。此常理也。但脉不长不数，口不渴而反喜唾，必以前过用膏芩，热虽解而中寒生，致有此证，且口甜者，脾虚之真味也。胃阳发露，无实热脉证，反属虚寒，当变法治之。用六君子汤加炮姜、益智仁，二剂知，四剂即口不甜而能食。大凡痧痘真阳未破之童身，苦寒可以恣用，出幼男子，经通女子，及已婚娶破阳，痧痘当用膏连十分者，宁用七分，以防中寒。曾治一妇人，产后未满月出痧，幼科尚未用凉药，痧回七八日，卒然腹痛厥逆呕吐，六脉全无，竟用四逆汤加人参、肉桂，数剂方痛止脉出。又见一幼男子出痘后，未得温补，卒然腹痛厥冷汗出，未终日而殒。", "16223": "汪彦玉兄令侄女，年十三岁，夏月喜食瓜果，仲秋患心内怔忡作呕。幼科作气虚治，用参术不效。又易医误认为大虚，用归脾汤，本家恐其过补未服。至夜呕吐，即昏厥，手足逆冷，不知人事。用生姜汤灌下，数刻方苏。次日迎诊，六脉沉弦而紧，身疼头眩，手足冷麻，胸前嘈杂。余曰：沉弦主饮，紧则为寒，此外感风寒，内停冷饮，表里寒邪未解，脉沉怔忡，皆痰饮证，非虚也。用桂枝、苍术、半夏、茯苓、炮姜、白蔻、陈皮，数剂呕止，转发呃。更加附子，则每日吐冷痰水碗许，呃乃止，怔忡亦愈。仍用前剂，则夜夜微汗，身发瘾疹作痒，身痛方除。此风邪化热而外解也，继用理中、桂枝、二陈，医治月余，里寒退尽，能食不呕而痊。", "16224": "乔俊升光禄令爱，年七岁，二月苦冷，右胁忽大痛，呻吟不绝，手不可近，脉沉弦而紧，手足厥冷。幼科不知何病，嘱余治之。予曰：半月前曾呕吐长虫，不能饮食，用乌梅丸吐止，今又胁痛，合而论之，厥阳寒证也。当温里为急，用桂枝、赤芍、细辛、干姜、半夏、吴茱萸、茯苓，日进二剂。右痛移于左，而下连于肋，此少阴部位也。遂加附子，又二剂，则夜发热，咳嗽喘促，鼻煽，下利黄水。余沉思良久，其吐虫时便尔受寒，未经解表，今见诸病，皆属小青龙汤证，乃寒水冲逆于上下，当以汗解。但病因循日久，必兼温里，用桂枝、细辛、麻黄、赤苓、半夏、附子、干姜、五味子、甘草、生姜，日服二剂，得汗而热退喘定。再二剂又汗而泻止，胁肋之痛，移于少腹。始去麻黄、细辛、桂枝，换肉桂以温里，其痛方除，每日微汗。八日后咳嗽始宁，十日后以理中汤合桂枝汤，温经调治而愈。观此足征幼儿伤寒，当与大人同治。世俗皆谓小儿纯阳，不宜温热，岂小儿竟无三阴病耶。", "16225": "吴楚佩国学令政，年五十八岁，十数年前病寒，误用凉药，几至危殆，得团弘春温剂而愈，致遗中寒痰饮，咳喘胀满，不能卧之证，数年一发，例用温肺汤加附子而平。己酉仲秋，不由外感而咳嗽，因素有痔血之病，乃追怨弘春之热药，恶姜附如仇。延至初冬，则虚寒毕露，右尺脉全无，反真阳外越，两足发热，夜置被外，面赤咳喘，右肋气冲，不能著枕而卧，乃寒水上逆，水蛊之机。暗加附子，以茯苓为君，附子、炮姜、半夏为臣，芍药为佐，用真武汤之意，日投二剂。将一月，咳止胀消，反恶寒足冷。彼方知本体虚寒，遂加人参白术，冬至后阳回足温。药不易方，至立春尺脉略出半部，春分后始得满部，而痔血亦愈。芍药加多，必致溏泻，病时傍议汹汹，惟病人不为所惑，必不易医。右尺半年无脉，姜附药二百余剂，方起于床，可谓沉寒痼冷矣。", "16226": "王蔚园兄令眷，山右先生六媳也。怀孕八月，忽下血不止，其胎欲堕，又值秋暑，呕吐非常。医士沈目南，与余同道，主以固气防脱。用大剂参附汤，频灌一夜，服参三两，熟附两许。天明胎堕，而产母幸全，惟虚惫之极，脉微似脱，饮食就枕匙进。扬俗产后例不用参，次日不免大减，至第三日忽然床上跳下，满房乱走，或笑或哭，竟似颠狂。而沈医先生，认为瘀血发狂，用芎归汤加童便，煎成将服矣。余适至，急止之。诊其脉散大无伦，面赤气促，不避亲疏。予曰：前夜血脱于下，今复阳亡于上，不急救瞬息脱矣。此亡阳证也。仍用前法，以人参五钱，附子二钱，急煎与服，随又一剂方定。令人抬上床，闭目一刻，及醒，前事皆忘，仍复卧床，头不能举。继用参、耆、归、术、炮姜等药，医治七日，忽腹大痛，先泻后痢，红白频下，二便不禁，势更危笃。因询夏月食瓜果否，若曾恣食瓜果，尚为寒痢，不然，此即五藏之气绝于内，为下脱证，万无生理矣。家人答以日食西瓜，于是告以必须姜附。王兄首允，即用附子理中汤，加肉桂、赤芍、茯苓、砂仁。七日痢止，转变呕呃，吐痰眩晕，大便频而溏，大能登桶，全不欲食。盖平素胃冷多痰，元气稍振，本病复萌，其呕呃眩晕，皆痰饮也。屏去血药，专用附子理中汤，加茯苓、半夏、天麻、白豆蔻，每剂人参三钱。医治百日，计服人参数斤，床上方能坐。若其狂跳时，倘无灼见，则差之毫厘，便失千里矣。", "16227": "瓜镇吴象衡兄令眷，怀孕临盆，丧子悲恸，不数日，生产一女，悲怒交加，产后即胸胀寒热烦躁。历医三四位，皆主疏气消瘀。至七日不效，始迎余治。脉虚大无伦，烦躁作渴，辗转于床，时值秋暑，目中流火，视物皆赤。予曰：此产后虚烦，真阳外越，若不温补，必致危殆。象衡素自用，答曰：胸胀如此，岂胜补药耶，烦热如此，岂胜温剂耶。余言之极力，其岳家亦以前用消克，其病愈甚为辞。象衡为理屈，不得已，听余用药。余勉以归脾汤加炮姜，用人参一钱，服一剂颇安，再剂则热止得卧。如此三日，诸证皆回，但胀满未解耳。彼怀疑误补，又惑前医之言，以前胡、厚朴、陈皮、半夏、知母、丹皮，清热宽中，五六日胀满未除，更增腹痛泻利，汗多不食，呕哕似呃矣，病益加重。前医束手无策，又复求治。余曰病危矣。前药亦不应，须用附子干姜，挽回于万一，言明不效勿怨。遂用人参五钱，附子、白术、干姜、肉桂、茯苓各钱半，大温大补，始克有济，下咽一刻，即汗敛呕止。如此大剂，十日泻止能食，一月方减药，而病亦渐愈。若其复请时，以前医翻案，置怀不一援救，岂不坐视其毙乎。", "16228": "程元美兄令眷，年近三十，产后未满月，得发热咳嗽，吐血盗汗等证。产前并无此夙疾，合当温补。而前医竟作阴虚主治，投以四物汤知柏花粉黄芩，病愈笃矣。予往视之，脉浮大而数，按之中空，壮热喉痛，咳吐血涎，腹胀作泻。此产后误用苦寒，中宫虚冷，逼阳于外也。用理中汤加麦冬、五味子、黄耆，服后阳气内归，则脉细如丝矣。其初吐之血淡红，血涎乃脾虚不裹血，非阴虚火逆冲出之血也。煎药仍主前方，更加八味丸，兼补肾水，所谓土旺自生金，毋拘拘于保肺，水壮自火息，毋汲汲于滋阴，是也。调治半年，经水方通一次，旋即不通，咳嗽未全止，脉涩不滑，脐下结块。其时喜尊素先生诊脉，亦云非胎，定为血假。以八味地黄丸，加倍桂附，添入降香节、牛膝以通经，日服不辍。忽腹大痛，意其经通，不意竟大产而生一男。夫病中及质弱者，胎脉临产，尚且不形于诊，则脉不足凭矣。医道诚难言哉。", "16229": "马彬五别驾，未出仕之十年前，尊阃大产，去血过多，昏晕大虚。前医重用人参耆术，已虚回血止，饮食如常，惟昼夜卧于床，不能坐起，坐则头眩耳鸣，必睡下乃可。如此已七十日，日服人参四五钱不效，招予治之。诊脉惟细迟无力，而饮食不减平时，肌肤声音，似无病者。此产后不慎起居，肝肾气虚，肝虚不摄气，故眩晕也。仲景谓之褥劳，久则成痿，用仲景之羊肉汤治之。用精羊肉二两，煮熟去肉，再以黄耆五钱，当归五钱，人参一钱，入汤煎熟，日服二剂。十日后即能起坐，二十日即可步履，回季宅母家调治而痊。", "16230": "瓜镇曹实甫令眷，年将三十，产后二日，忽恶寒发热，头痛身疼，医认作伤寒，断食三日，汗大出而热不退，更增烦躁。实甫具病状，问治于镇江何似充先生。何答云：产后以大补气血为主，虽有他疾，以末治之。药用参、耆、归、术、茯苓、炮姜、麦冬、五味、甘草。实甫复呈方于前治之医，斥之曰：老朽已聋瞽失时，此等伤寒热证，岂堪补耶。又任其专治七日，则愈热愈躁，而脉愈大。暮夜相招，脉散大，呻吟狂躁热渴，扬手掷足，几不欲生。予曰：产后虚烦，急须温补。发药加参。实甫以何药见示，药竟相同，遂放心与服。服毕即安卧，次日脉敛热退。嘱其仍要加参。实甫惜费不用，逾一日夜，复热躁欲脱，通夜服人参七钱始安。如前参耆归术，调补匝月而起。", "16231": "瓜镇王笃之兄，适严宅之女，怀孕九月，冬月苦寒患病。据严宅云：初病是伤寒，已经半月，发表攻里，俱已备尝。因腹中大痛，恐是临盆，稳婆已伺候矣，迎余决之。诊其脉沉细而紧，畏寒之极，坐卧火箱中，犹抱火烘面，其痛在脐上，左右冲击而动，不在少腹，而脉又沉，非欲产之候。此误用攻导凉药，致中焦寒极，非温不可。而前医犹要用行药，谓通则不痛也。予议用姜桂，病家畏桂堕胎。予谕之曰：将产之胎，非若一两月血胞，畏桂行血，且中宫冷极，桂至中宫，尚不能敌其寒，何能下达而伤胎乎。失之不温，产妇且危，去病即所以安胎也。遂用人参、炮姜、肉桂、当归、砂仁、陈皮、甘草，一剂痛减，温补半月方产。产时几至虚脱，得补而回。", "16232": "萧朋玉兄令眷，自真州来郡就医，因小产后发热吐血，真州时道认为阴虚，竟以生地黄、白芍、丹皮、麦冬、贝母治之。殊不知此乃小产后瘀血未尽，因而发热，血不下行，而逆于上也。将两月，渐致腹胀而痛，呕吐不食，面黄浮肿，少腹结块，发热恶寒，脉沉细紧，按之坚硬而长，血为凉药所凝，病成血蛊，必须温暖，其瘀方化。用附子、肉桂、炮姜、当归、赤芍、五灵脂、香附、延胡等药，四十剂，遂大下黑血如泥者数碗，由大便而出，肿胀痛一夕皆消。而人虚困殆甚，继用温经和血健脾之药，半载新血渐生，而经再至方健。", "16233": "黄美倩翁令媳汪氏，产后腹痛四阅月，真州来郡，借居吴天其翁宅就医，诊脉细数而涩，脐下作痛，午后发热，恶寒咳嗽盗汗，俨然虚损矣，而经水或红或淡，犹未止。询真州时道治法，或用大黄、红花、桃仁，或用肉桂、炮姜、附子，遍治不效，渐增发热咳嗽，脉证皆属阴虚。但败浊屡月不止，则非积瘀，又腹痛有形，脉不紧，且已用姜桂附子，而痛不减，则非寒。余拟其为肠痈，未遽用药，令其看腹皮粗糙否，脐中有臭水否，腹内可有水声，大小二便可坠胀，所下败浊似脓血否。病人答云：件件皆有。余曰：此肠痈，误治无疑矣。今已溃，未收口，须两月方愈，不能急效。病人唯唯。遂以六味地黄汤，去泽泻，加人参、苡仁、当归、赤芍、桃仁、肉桂为煎剂，外用六味地黄丸，去泽泻，加人参、黄耆。此外科治肠痈之七贤散也，用蜜为丸。如此煎丸并服，一月咳嗽发热先退，又半月，脓血方净，而痛亦止。完口之后，回真州。", "16234": "孙飞闻二尹令弟妇蒋氏，产后瘀血未尽，满月后腹渐大痛，脐下有块，大小二便，里急后重，大便难出，小便如淋亦难出。前医已用芎归姜桂温之不效，及余往诊，床上不能坐，下迫痛甚，两尺脉独数，肠中水响，而又不泻，两腿并腹，牵引而痛。予曰：此积瘀为患，尺脉己数，乃血积于肠回环处，寒化为热，将成肠痈，不急通之，成脓难治。先用当归、赤芍、苡仁、丹皮、栝蒌、桃仁，痛虽略止，而大便不通，不得不用大黄以宣导矣。遂用旧方乌金丹，乃大黄膏、苏木膏合群血药为丸者，早晚各服一丸。大便次日虽通，仍无瘀血，痛不止，又一日进三丸，紫血方下。次日痛减，仍用前苡仁煎剂，以逐其余。至下月经水大通，而痛始全去。", "16235": "方汉辰兄令眷，右周族叔之女也。大产死胎，稳婆手重，致伤子肠，七日后招治。大小两便不通，已四日矣，少腹肿痛如坟，仰卧于床，不能转侧。他医作肠痈治，用菜瓜子为君，食之不效。又医作瘀血治，亦不效。诊其脉涩而数，因小便胀痛，遂不食，虚惫不堪。余深思良久，肠痈乃瘀血积肠中，久而始化脓作痛，今产后方三日，而即肿痛，断非肠痈。若瘀血作痛，血病不秘小便，若寒痛，少腹不当高肿如坟，且脉不紧而反数。以「藏府内景图」为证，妇人胞门子户居中，膀胱在前，直肠在后。以理揆之，产时手取死胎，伤而不觉，后三日肿大，前逼膀胱，后逼直肠，故大小便皆不通。其少腹肿高如坟者，乃膀胱中小便也。令老成妇人，以热汤渍布，揉按肿处。问痛在前按处否，病人答以肿处不痛，其痛在里。予曰是矣。令渍布者以手重按肿处，则尿如涌泉，瞬刻肿消。续有败脓瘀血，源源而下，急令煎大剂参、耆、归、芍、肉桂、附子、炮姜等药，促令煎熟，频频灌下。又令再煎二剂，恐大便随下，以防气脱。后片刻，大便果下，几乎晕脱，然卒无害者，幸服药在前也。后用内痈疡科治法，皆用参、耆、归、芍、桂、附、炮姜、苡仁收功。独不用白术者，恐助脓也。医治百日，方能起床，嗣后仍复生产。", "16236": "汪公肃兄令眷，夏初大产，天气犹寒，生时亦快。而不解事之稳婆，巳至不令上床，令其久坐秽桶，以俟下血。次日即腹痛，大小便皆不通，玉门肿闭，小便反自大肠渗出。第五日请救，脉沉紧。先医用芎归消瘀不效，又用理中补中亦不效，痛胀益甚。细询病状，盖由产后玉门未敛，久坐秽桶，寒气袭入下焦，阳气不通，前阴肿闭，阴阳乖错，小便反从后阴渗出。此非交肠之病，乃属厥阴中寒明矣。所幸者，尚未厥逆于上耳。但乙癸同源，肾肝同治，且肾主二便，开窍于二阴，又属厥阴纯寒，只得借用少阴治法，以四逆汤主之。附子三钱，干姜二钱，甘草一钱，肉桂、当归各钱半，日进三剂。小便微通，肿处微消。如此药三日九剂，小便通而瘀血甚少，五日大便通。半月臀上生痈，盖因瘀血未净，寒因热化而作脓溃也。病者幸因前药见效，不致怨热药贻患。", "16237": "许蓼斋太守令眷，中寒痰饮，姜附时服，平素皆然，产后十年不孕。甲申秋自称怀孕，下血，胎脉不现，用补气安胎药三四剂随止。隔一月，又下血，又如前药，又随止。隔一月，又大便下血甚多，以平常时有之证，不服药而饮灯心汤，又服凉药，不但血不止，更增腹胀不食，头眩身麻，冷痰上壅，大便下迫，不能坐立，诊脉弦细而紧，胎脉不见。余遵《内经》阴络结则血下溢治法，用人参、白术、桂枝、当归、赤芍、炮姜、甘草，少加附子。四剂血随止，即现中寒夙疾，胸腹胀大，呕吐痰涎，喘促不能卧，脉更沉小。此证必须姜附，然恐伤胎，而令尊汪闲先翁主持。谓大人要紧，遑顾其胎，且怀胎四月，三见血下，脉不又旺，姜附素常服惯，竟用无妨，遂用姜、附、茯苓、半夏、吴萸、橘红，日服三剂颇安，而胀呕不减。换生附子连服七剂，始得不胀不喘不呕。方改用熟附、炮姜，加参、术，胀满然后全消。未几又气虚似脱，心内怔忡，令人抱按，方能卧。又非痰证怔忡，余暂用人参三钱，归脾汤三五日，正气虚回，痰饮又发。仍用前剂，但以干姜配熟附，兼用参、术，而对夏、苓，将一月，年终病退，即不药矣。乙酉之春，因痰咳嗽相招，胎脉始现，腹大有形。至六月大产男胎，产后本日血不下，小便一日夜不通，脉两尺沉迟无力。此产后下焦虚冷，不能小便。而病人自云旧年病急，多服姜附，致内热小便不通。余亦不与辨，至更余则腹胀如鼓，直坐于床，不能转动，腹中冷气上冲。彼方知尚属虚冷，向余云：内热之说误言耳。惟求急救，若迟则痛胀死矣。其时亦汪闲先翁主持，用附子一两，肉桂、干姜、当归、茯苓各三钱，大铫急煎顿服。少刻腹内肠鸣，尿血大下，至五更方得平卧，后用温补而愈。怀孕服姜、桂、附子药百剂。而不伤胎，产后一夜，服附子一两，亦不觉热，此证世不多见。经云有故无殒，其斯之谓欤。", "16238": "孙以𬆭兄令眷，予族侄女也。怀孕值暑月，以西瓜浸井，日食为常，至产后气血交虚，积寒在腹，三日后胸腹胀满，而坚，犹如未产，干呕不能食，咳喘不能卧，足冷过膝，脉沉细而硬。其母谓三朝食面，著气停食，再三嘱用消导之药。余曰：形寒饮冷则伤肺，所以喘咳积冷于中，先有胎元真阳在腹，可以胜其冷物，今胎已产，气血两虚，其沉寒痼冷，蟠结于上中下三焦，否塞不通，惟宜助阳消阴。若克伐伤气，则阳益消矣。此证非大温热宣补兼施，不能望其效也。以𬆭唯唯，遂以生附子、生干姜、半夏、吴萸以温里，桂枝、细辛、生姜以温经，助以人参、茯苓、赤芍，以培气血。以𬆭日藏人参于怀，暗投药中，以免其岳母之恶补也。服至半月，上身微汗，而咳喘宁。再服一旬，胸结略下，而能纳谷。冷秘二十余日，日服半硫丸二钱，大便方通，其矢碧绿，弹丸续续而下，计两月腹中上下方通。沉寒痼冷，未有如斯之甚者，若顺人情而妄用消导，不知作何结局矣。", "16239": "张渭光兄令眷，年逾二十，怀孕三月，时值仲秋，胎动见紫血水。前医犹用生地黄、黄芩保胎，一二日紫血下不止，腹胀痛甚，延予托诊。脉沉紧，坚而搏手，此下焦冷极，胎已无气，所以血紫也，再用凉血，是益其冷矣。用芎、归、炮姜、砂仁温中活血之药，腐胎始下。痛止而胀不消，腹坚如石，胁肋胀满，上冲于心，滴水难下，哕呃烦躁，坐不能卧，卧则气喘，两尺脉皆伏，他部弦细而紧，不任寻按。据证脉竟是肝藏中寒，须作厥阴伤寒治法，其产后芎归套剂，一片不能入口矣。此暑月贪凉食冷，不慎起居，积冷下焦之病。一医犹用参术补中，病家因胀甚不与，病状危笃，力辞不治。坚托无奈，用半硫丸一钱，以开隔上之寒痰，方能纳药。继用生附子、生干姜、肉桂、赤芍、吴萸、半夏、茯苓，每日三剂，兼服半硫丸三十粒。如此三日，方就枕不喘，能下谷汤。而胀呃犹然不退，肋下有形而痛，前药换熟附子，又服六七日，胸口稍软，哕呃始减，而少腹犹坚，再加当归，以和厥阴之血。腹内凝冰，幸而不利，服半硫丸半月，大便通，色皆青绿，终无一点血下，而腹亦消。扬俗满月洗浴，以致受寒病复，前证皆集，但不喘能卧耳。仍用前药治半月方回。胎前积冷，产后中寒，竟与前孙案相同。但此证不大虚，惟不用人参差异也。怀孕内眷，当以此示警。", "16240": "程农长兄令媳，吴宅之女也。二月大产，天气尚寒，未满月，便开窗梳洗，方满月，便尔洗浴，因受风寒，次日头痛身疼，遍身筋惕，汗多而热不退，脉不浮而单弦。初诊便告病家，此产后中风大病，不可轻视。用当归四逆汤，当归、赤芍、桂枝、细辛、茯苓、炮姜、甘草，姜枣为引。医治三日，因本气大虚，风邪不解，更头疼如破，筋惕肉𥆧，汗出如浴，手足抽搐，时时昏厥，病甚危笃。余曰：此产后气血大虚，风邪直入肝经，已现亡阳脱证，须急用人参固里，附子温经，使里气壮，逼邪外解：否则风邪入藏，必昏厥不语，手足逆冷，呕哕不食，不可治矣。未几果哕，病家遂信予言，重用参附，加于当归四逆汤中，更加吴萸以治哕，间加天麻、半夏，兼治虚风。如斯大剂，日服人参两许，附子六七钱，半月后方渐次而回。再去细辛、吴萸，增耆术，四十日方能起床。此证幸病家不吝人参，而任医得专，故获收功也。", "16241": "吴绍先兄令眷，年三十余岁，平素脾虚中冷，而夹痰饮，生产多胎，气虚时晕。癸未春间，怀孕一二月，便下血，服药而止。隔一月，又下血，药亦不止。听其淋滴不断者半月，欲其堕而不堕，反自止。本性畏热喜风，兼嗜瓜果，六月夜分，霍乱大吐，吐后汗多厥冷，遂昏沉不语，手足抽搐，目珠上窜。次日往看，脉弦细而紧软，卧于床，手足微温，手筋惕动，而手即挛，灌以药能咽，呕则欲吐。幸小便未遗，欲小便则有起床之状，人扶起能自立而便。但目不瞠，口不能语耳。此因大吐中虚，寒痰上涌，须用类中风治法。扬医众议不一，适金坛周医驻扬，议论相合。于是定方六君子汤，用人参一钱，白术、茯苓、半夏曲、桂枝、吴茱萸、姜汁、天麻、橘红，灌服二剂，至夜半回苏。计昏厥一昼夜，次日能言，谓周身皆痛，气塞喉中，胸中胀闷，腹痛作泻，外则筋惕而手拘挛，呕呃不能食。又迎鲍医，亦主温补，议用肉桂，予因频次下血，恐桂破血，易用桂枝合真武汤，换炮姜，救其亡阳虚脱。议用人参一钱，白术、茯苓、炮姜、附子、芍药、桂枝、甘草，姜枣为引，如此温补之剂，服一月方能坐床进食。后渐次去附子，调理而愈。至冬杪生产一男。母子平安。若病时执怀孕不用附子、半夏之说，病必不除，则产母不保，母不保，又安有子乎。程案产后中风，则气血交虚，故施重剂。此胎前中风，因未产不甚虚，故剂轻也。", "16242": "张其相兄令眷，年望四旬，隆冬大产后六日，家务烦劳，遂恶寒发热，身痛呕吐，不知何脉。前医认伤寒，用桂枝、细辛、干姜、吴萸、赤芍、半夏等药，二剂遂大汗不止，血下如注，晕脱者二次。本家先以人参数钱灌回，予踵至，汗犹未敛，脉细如丝，血尚未止，虽有声音，而不能言。予曰：血脱益气，此定论也。用人参五钱，附子二钱，炮姜二钱，连进二剂，方汗敛血止，而能言语。次日，即改用归脾汤，加黑姜、官桂，温补满月而起。", "16243": "程载锡兄如君艰产，产后即晕厥，醒后喉哑，全无声音，而人事清楚，脉细如丝，手足厥冷。盖艰产玉门久开，寒气袭入，经云：寒中少阴，令人卒然而哑。且脉细厥冷，可征也。用四逆汤疾驱其寒，以防变证，用附子三钱，干姜三钱，甘草一钱，当归三钱，连进三剂，次日音出，瘀血方下。盖少阴经络尽于喉，寒极于下，肾气不能时上，致卒然失音，若非重剂，入里之寒，何能骤解。数日后，因难产内伤肿痛，去附子加肉桂、赤芍、桃仁，肿消痛止，半月方愈。", "16244": "英德县令王公仆妇，年三十外，本出西人，夏月恣食瓜果，八月初旬，产后积冷在腹，五日后腹痛，先泻后痢，两关紧滑，用姜桂香砂胃苓汤，四剂而愈。两三日后，因前寒未解喉痛，又开窗取凉，复受寒邪，以致头疼发热，身痛脉浮紧，用芎苏饮微汗而表解，热尚未除。继用桂枝葛根汤，二剂热即退。忽变为神昏不语，掐指剔牙，肠鸣下利，问病若聋，诊脉弦细无力。产后尚未满月，知属里虚，证类中风。用桂枝汤加白术、半夏、天麻、炮姜、附子二剂，五更后即能言，至未申即不语，坐卧如凝。能言时谓身痛腹疼，其渴饮茶汤，日夜两大壶，随即洞泻八九次，肠鸣水食，脉弦细紧。此为风邪直入肝经，乃厥阴之病。盖厥阴病本消渴，风邪不解，内搏为泻，身痛多汗，脉不浮，断非表证，乃骨寒而痛也。且午后不语，定属阴邪，准作厥阴治法，不治洞泻。用当归四逆汤，桂枝、当归、赤芍、细辛、附子、炮姜、人参、白术、茯苓、甘草，姜枣为引。服六剂，渴全止，夜得微汗，腹痛身疼即解，泻止能言。自立方付彼，令其照方撮药，服十余剂即全愈。若用育神止泻，不察病名，岂不大误乎。余每见产后不语，不治者多矣。此北人胃气本厚，故合证之药，易于取效也。前程案乃寒中少阴寒水之藏，故终日不语阴也。此证乃风中厥阴风木之藏，木中有火，午后方不语，非纯阴也。所以药亦阴阳对待，不似程案用纯阳药矣。", "16245": "适朱宅三小女，体素虚寒，怀孕将产，先胃寒呕吐，服理中汤而止。续即两足少肿，未旬日，上肿至腿，渐上至少腹，内怀双胎，其腹胀大欲裂，气喘不能行立，脉细如丝，两足冰冷，小便点滴不通。水已上溢，不急治水，胎必浸伤，而孕妇更不能保矣。谅桂附尚不能敌水，何暇伤胎，且胎已足月，桂附不能犯。遂用附子、干姜、桂枝、人参、白术、茯苓、泽泻，大剂与服，日投二剂。四剂后足微温，小便略有。服至十剂，上腹略软，水尽下注于两足，惟卧床不能坐矣。又十余剂，水从大小二便齐出，消大半，而双生两男。产后因胎前药力，三朝尚全无病，遂经理家事，忽然腹大痛，大吐大泻，困惫于床，脉细紧无伦，惟恐痛脱，仍用前人参、附子、干姜、肉桂、茯苓、甘草。因腹痛，故去术也。日服人参六钱，药三剂，六日痛止。加白术，温补四十日始康。其产后惟两血饼，所下皆水，此阳气虚，血反化水，若执怀孕桂附伤胎，而水不下，必致子母两殒。经云：有故无殒，良不诬也。其所生之子，出痘甚轻，则桂附不贻害于儿，亦可知矣，出痘之儿，因痘甚轻，未满月便出户见风，至满月后。作泻十数日，忽患惊风，幼科皆称慢惊不治，已掷于地，惟候死耳。予视之，忽啼号数声，即手足抽搐，眼珠上视，头向后仰，身体僵直。夫慢惊抽搐，不先啼叫，且头不后仰，身不僵直，今有此数证，则非慢惊，盖天钓风也。其先啼者，腹中痛，谓之内钓。内钓后即外钓抽搐。此因痘后失调，又经久泻而兼风邪，故有是证，必须温经补中。余遂用桂枝、赤芍、钩藤、人参、白术、炮姜、附子、半夏、甘草，灌下二剂，即回苏，但不能吮乳，日进米粥，然一日必啼号十数次，抽搐十数次，而参附药不辍。幼科畏热，暂止数日，即泻不止，泻甚则内钓外钓亦甚。不得已，坚用之，抽搐止，即右手足痿软，半身不遂。如此大剂，一岁之儿，服至百剂，泻方止，足可站立。但右手尚不能持物，笑则口歪，若非参术桂附干姜，何能有生。有斯病则用斯药，岂以幼儿纯阳，不堪辛热，执为定论者哉。", "16246": "闵脉沉静而不宣畅，故至夜宜静而反动，《内经》谓：阳𫏋盛，不得入于阴，故不寐。当体此意以行之，或中病机。", "16247": "蒋失血后虽不至数，而干咳无痰，火升不得卧，脉象虚数，皆属气火不下潜，真阴失守之所致。姑服大补阴丸。", "16248": "程（29岁）失血后咳呛，脉象虚数，虑其火炎扰肺。", "16249": "叶右关脉弦搏，肝木乘旺，气扰胃脘，痛微见红，所由来也。心中悸动，夜间多汗，阴虚阳浮，治宜滋填固摄。", "16250": "丁（21岁）诊脉短而数。经云：长则气治，短则气病，数则烦心。据经而论，气不足而营分热，虚者益之，热者清之，两得其平，斯可以治病。", "16251": "周失血之后却不咳嗽，上传之患，此时无庸虑及。但脉象见数而右关微搏，恐火邪侵犯中州，又不可不急为之防也。议进滋养方。", "16252": "沈（17岁）饮食如常，而脉象少生动之气，虽咳嗽未久，亦当为未雨绸缪之计。", "16253": "转丸方：脉神未旺者，以精气未充故也。", "16254": "张脉数而寸尤甚，口干燥，便溏泄，手、足太阴皆病。先宜调和二脏。", "16255": "徐脉小弱，阳浮易动，从督脉上升，心中震荡，惊惕不宁，治以填镇固摄。", "16256": "李脉小而数，但热不寒，汗多渴饮，与竹叶石膏汤加桂枝。", "16257": "张（女）余至时，门人周蕴石在坐，出所治张方，以下痢不止，手足厥逆，用附子理中，合茱萸、大枣、白芍，服后神气略定，痢稍缓。余谓此方极中病机，可仍服之，俟明日再议。孰知服后病忽增重，下痢日夜不止，面赤戴阳，神昏谵语，诸恶毕集。余制此方与之，服后痢乃止，辰粥四盂，神气宁静，脉亦循经，大是奇事。", "16258": "录张女病原方案：下痢不止，面赤戴阳，神昏谵语，循衣摸床，撮空理线，左脉中部短促而急，恐其下痢亡阴，神魂飞越，岌岌乎有难返之势矣。今议进救逆法，加参、附、术以收拾飞越之虚阳，以桃花汤固摄下焦。拦截去路，急存耗散之阴精，少厥同治。断鳌正极，在此一战，以冀挽回于万一，此亦不得已之极思耳。", "16259": "吴寒热已微，似病渐愈，但据证则指头寒，脉微欲绝，神气倦怠。仲圣所谓少阴病也。危机已兆，恐地水火风，猝来莫御，将若之何？姑拟一方。", "16260": "转方：服药后两手已温，脉微已现，阴分转阳，属吉兆。但胃腑未通，津液未复，邪热劫阴，正赖调理，危然后安，谈何容易。今姑拟益阴通腑方。", "16261": "王肝脉滞而涩，是肝气郁，郁则风不宣畅，焉能发鸣？当借金以开之。", "16262": "严天道左升而右降，人身一小天地，亦左升而右降。故肝之位在左，其气常行于右。今营分大伤，络脉不营，是以动作而皆痛。治先调营为主。", "16263": "郝（32岁）诊脉小弱，时吐蛔。风入胃，七日而生虫。脾胃得温则伏，气塞则上出而呕。用药以辛酸为主，苦味为辅。杀虫之品，又次之。", "16264": "程风阳鼓动，右手足筋脉抽引。治宜养营熄风。", "16265": "某筋脉抽掣，风阳鼓动。", "16266": "蒋气似浮，故脉不得沉而降，气亦随之。", "16267": "王两足筋脉时攻痛。攻之甚，头且晕。", "16268": "祝（崇明）据述平素以筋脉牵引为舒畅，惟轻则适。肝之性曲直，喜条达也。过重则抽掣太甚，下之海底必微湿，湿少则稍安，多则周身不适，如有物为之遮蔽。又若抠进，必口中大气为之一嘘，方为之廓然，此风阳之鼓动，燥火升腾也。其在经曰神，在天为风，在地为木，在体为筋，在脏为肝，在变动为握。握，搐搦也。火盛水衰，风随火动，所谓火空则发也。海底之湿，肝火之盛，子盗母气也。昨小便失溺不禁，厥逆随至，危机已著。今搐搦不已，苟非大剂滋培镇摄，暴脱可虞。今据理立方，以审察病机之所向。", "16269": "复诊：脉象带数，咳甚则肺气阻抑，便溏则胃阳不宣，土金俱病。宜以神农上品之药治之。方与中宫有裨。", "16270": "顾风阳鼓动，脉显其形。", "16271": "严诊脉肝火有余，肾水不足以致，反并于阳明而益旺，右关之火，所由来也。治宜壮阴和阳。", "16272": "僧单腹胀有瘕作痛，脉小无力。", "16273": "谢囊肿足浮，溲少脉沉。", "16274": "陈湿阻络脉，为麻木，气血不行，痿痹所作。与宣通法。", "16275": "刘（35岁，洞庭）据证右半身时麻木，诊脉两手俱弦滑，是湿邪之留著处，麻木之所由来也。但治湿不可过燥，燥则伤阴，非所以利湿也。仿黑地黄丸治法。", "16276": "李脉来弦滑，手足麻木。", "16277": "刘（洞庭）右脉之滑较甚于左，酒湿动之也。", "16278": "周（42岁）两手脉伏而不扬，气机之滞也。宜助中宣达。", "16279": "钱诊脉小弱素有肝气，疝证时发。宜从下焦治。", "16280": "许（25岁）浊证起于正月，涓涓不绝，肾关开而精气大耗，筋脉无以濡养矣。填补固摄，势不容缓矣。现在咳嗽虽属风邪，但诊右寸大而不敛，非木火旺令所宜，不可视为小恙而忽诸。", "16281": "某脉小而急，月事先期，色紫黑，营热证也。", "16282": "赵经阻不行，肚腹连腰颇痛，从奇脉治。", "16283": "又：昨日气聚上冲，不惟冲脉之逆，而由两肋而升，肝亦觉冲为患矣。所喜者其势聚而不散，从其聚处击之，而使之并，竟归入脐中而刺痛不休矣。其故总因血虚而不能滋养肝冲，当脐即肝冲聚会之处也。精血空乏，宜抚不宜剿，使其日积月盛，府库充盈，无乘虚窃发之患矣。脐中痛一剂愈。", "16284": "吴奇经河津空乏，以致厥阴经脉不司约束，发为阴挺。治宜养阴清热，渐复其故。凡一切消克等味，宜戒勿进。", "16285": "杨（44岁）四肢麻痹，脉象软弱。总由营亏，血不养筋，恐属类中根萌，殊可虑也。至于脘中痛，则疏肝理胃为先。", "16286": "诸（70岁）麻木不仁，眩晕脉弦。风阳上旋，防其类中。", "16287": "毕（55岁）胆虚中正无权，疑惧交至，脉弦为减。风阳易动，防其类中。", "16288": "又脉左弦右滑、痰火生风，故左额胀痛。仍以和阳熄风，化痰去湿。", "16289": "又：言謇舌强久矣。渐至腰楚足酸，左股无力，转侧不舒，脉形小弱，右微数。此肝脾肾三阴并亏，日萌痱中之机。当究其本为要。", "16290": "杨（31岁）痿躄四月有余，脉濡小涩，语言不利，痱风之象。腹痛，大便或溏或结。姑从中治，宗《内经》独取阳明之义。", "16291": "又：痿躄不减，脉仍微细。前议三阴亏损，痱中最难取效。", "16292": "邓（38岁）昔贤云：口眼常动，故风生，风摇则血液衰耗，无以营筋，故筋脉拘急，有歪僻之象。", "16293": "荣（56岁）阴亏肝郁，化风化火，耳鸣，舌干起刺，不得寐，胁胀，见象一斑。脉弦、沉滞带数。议体用两顾。", "16294": "朱脉弦不寐，心中嘈杂。总由肝阳亢逆，化风内动。议以静药和阳之治。", "16295": "周阴虚火升咽燥，筋脉抽引，眩晕悸动，大便不爽，总由水亏木火少藏，游行变幻莫制，非易治也。宜与滋养。", "16296": "迟眩晕跌仆，心悸蠕动，筋脉抽掣，肝风振荡。与养阴熄风。", "16297": "华高年阴液向衰，素患痔痛，春夏之交，风阳上冒，陡发经脉抽胀，几至晕厥。身热面赤，汗出淋漓，逾时爽然若失。脉弦数，舌苔黄厚尖紫，初用养阴熄风，和络平胃，时作时止，几无措手矣。用羚羊角、夏枯草、丝瓜络、钩钩浓煎雪羹汤冲服，总未全瘳。转用方诸水冲入，日进几碗，热渐平而苔浊黄厚不退，食粽又剧。再与枳壳、建曲、麦芽、橘白、郁金，和胃宽中，得大便，又得小安。脉渐和，苔色减，然仍寐不安，筋仍掣，黎明汗泄。用黑枣仁四钱、炒木瓜七分，冲雪羹汤，日进二三碗。如是调理计及匝月，诸恙始有愈机。", "16298": "廉（63岁）向衰年岁，肝气挟湿，化风头晕，耳失其聪，食后少运，脉濡而弱，际此湿土司令，当扶中为法，熄风佐之。", "16299": "孙操劳郁勃，木乘土位为胀，脉形窒滞，大便不爽，皆是咎征。", "16300": "赵奇脉暗伤，阳浮作眩。", "16301": "胡厥阳眩晕跌仆，下部渐肿，腰楚带下，八脉暗损，风阳鼓动使然。", "16302": "华风阳未熄，巅顶痛仍不休，脉弦为减，长沙之旨也。下虚上实，素嗜酒，舌苔滑腻，挟湿生痰，今厥暂止，发亦甚易。预防之道，须推介类静药和阳，佐以扶正利痰，冀其应桴。", "16303": "又：前议滋填潜降，治其本也。考之古训，癫痫病发于阴，情志内伤，痰气阻遏，机窍郁勃阳升，此致病之由也。诊脉弦大而迟，舌苔浊腻，胃少纳谷，见象一斑。上午稍得清朗，下午善欠多寐，头风未熄，复厥奈何？拟方备商。", "16304": "又：症象稍减，然当壮盛年岁，春夏之脉濡细，形神消瘦，殊为可虑。仍前法参以扶正，体用两调。", "16305": "顾补剂颇适，所兼脉象细弱，难期骤复也。", "16306": "朱脉软弱，不寐目涩。责在营不足。", "16307": "陈今年火运，少阳司天，消渴一年，形神渐瘦，溲多腻浊。此阴精少奉，少亏阳亢，亢则害也。大便燥，脉涩。壮水之主，保本之道也。", "16308": "冯口干咳呛，脉虚数，恐延为肺痿。拟用清金宁肺。", "16309": "蔡（21岁）热久伤阴，脉弦数，本宜滋养，但嗽甚则呕，胃气受戕，金失所养，渐延肺痿。议以培土生金法。", "16310": "薛久咳涎沫，胃少纳，脉短，恐延肺痿。与益胃生金。", "16311": "阙（85岁）平素郁勃，向衰之年，厥阳司升，耳鸣咳呛，上脘窒滞不舒。近则寤不成寐，诊脉短涩虚数，阴液内亏，将交秋燥，预进清金益胃，迎其生生之气来复。恐延肺痿。", "16312": "岳（34岁）经言：热在上焦，脉虚数者为肺痿。汗易泄，时恶风，肺主皮毛故也。唇口腐碎少纳，兼理阳明。", "16313": "朱积劳伤阳，阴失其守，以致去年骤然失血。经曰：阳络伤则血外溢也。然血既去，阴必伤，时值盛夏，阴不配阳，故身觉热而不耐劳动，势所必然。诊脉颇有力，非有余也，仲景谓之为减。胃纳甚少，亦宜柔药养之。又曰：胃为阳土，得阴自安。拙见备商。", "16314": "周气口脉大，身微热，恶寒不知味。治从劳倦门。", "16315": "朱水亏火炎，水火未得既济之功。脉弦数，舌绛，小便艰涩。姑参造化之理，黄河之水天上来，人身则金能生水，水生则肝有制，胃有资矣。丹溪隔一治法，同一义也。若以通利之剂，当无是理。", "16316": "又：诛伐过多，胃气太伤，不容谷食，大便溏泄，中宫乏砥柱之权。舌绛无苔，柔土少津液之布。脉来数大，非有余也。仲圣脉法为减耳。拟《金匮》麦门冬汤益胃生津，望其安谷。", "16317": "宋（45岁）脉弦数大，阴损阳浮，大便艰涩。法宜滋养。", "16318": "陈交大节，阴虚阳升，血症复发，每于戌亥为多。龙相少藏，血随气上也。诊脉芤弦，填下摄纳为主。", "16319": "丁（27岁）漏疡暗耗久矣，封藏不固，正涉地气司升之候，络血沸腾，咳呛不已，兼之滑泄，或为盗汗，脉芤细数，皆是咎征。", "16320": "陆（27岁）脉濡细，阴虚及阳，身热消瘦，汗出已多，卫不固，虑其损怯。", "16321": "吴（31岁）鼻衄不止。宗仲景当从冲脉治。", "16322": "翁恙久阴阳偏胜，正值经行，水愈亏而阳越亢，热势转甚，腰楚怯弱，良有以也。年逾五旬，冲任不固，八脉交损，以致见象非一。脉形虚芤带数。总以和阳育阴为要。", "16323": "顾热不止，起于涌泉，下午入夜则剧，经断，脘痛时呕，脉来虚数，劳损见端，草木难期速功。", "16324": "陈（29岁）脉左搏大，阴虚阳浮，以致鼻衄走阳，上下耗损，势非轻浅。", "16325": "毕失血损症，滋养是矣。胃少纳谷，频欲呕吐，子病及母为难治。经伤咳呛，骨蒸微热盗汗，脉数，见象甚著。", "16326": "钱封藏不固，滑泄频频，肾脉上循喉咙，呛咳失音，良有以也。", "16327": "过肝肾阴亏，封藏失职，脉象微弦，风阳易亢。治从乙癸同源之治。", "16328": "张肝脾之气不和，少腹攻触作楚，又经梦泄，肾真不固，尤为吃紧处矣。大便稍干，胃气略开，此为休征。脉濡小，尺部微弦。协和肝脾，兼摄下焦。", "16329": "徐（53岁）交节龙相少藏，又经梦泄。脉象濡弦。填阴摄固奚疑。", "16330": "徐（34岁）症因惊恐而作，惊则伤心，恐则伤肾，心肾失交，故多梦悸动，精关淋沥，脉虚弦涩。治宜摄固。", "16331": "徐（26岁）经云：肾者主水，受五脏六腑之精而藏之。今则封藏失职，水渐亏而火渐亢，斯百病生矣。诊脉颇弦，长沙脉法为之减也。甚至遗滑无度，将有淋浊之虑，最难图治。拙见以壮水为主，俾得水火无偏胜之忧，斯阴平阳秘，始克有济耳。静养维持，尤宜加意于药石之先。", "16332": "薛先曾血淋，继则溲浊，肾阴固亏，脾元亦弱，故食后不运而疮痍，此可征也。正值湿土司令，入夜微热盗汗，脉虚，最易延入损门。仿立斋先生治意。", "16333": "徐（35岁）脉弦为减，长沙之旨也。火升口干，阴精少奉，总由淋沥暗耗，故未能骤期速动。", "16334": "周（23岁）右髀股筋挛作痛，几及三月，渐延白浊，溲便不利，此肝肾内伤，湿热下注，脉形虚数，口干怯弱，殊非轻浅。", "16335": "金素患淋浊，肾阴亏乏久矣。湿邪下注，海底结痈之象。舌苔滑腻，脉形弦数，见象一斑。经云：阴虚者，阳必凑之。至阴之地，龙相所居，泻南补北，莫如丹溪探本之道也。", "16336": "冯（42岁）痿躄软麻，脘闷气壅，大便不爽，脉象中阳不运。仿胸痹法，亦独取阳明之义也。", "16337": "朱（61岁）口苦舌黄黑，脉濡数，嗜酒中虚，湿胜化热，渐延痿躄，非轻象也。", "16338": "顾脉仍革，右为甚。肠痹症也。", "16339": "又：六日不更衣，胃腑失司下行，脉象短涩，液亏之象。法宜温润。", "16340": "又：得大便不爽，形气衰弱，尺脉尤虚，殊为可虑。拟方商正。", "16341": "钱服润燥宽畅，得大便而少腹之胀满不减，痰多纳少，脘痞脉短，色夺消瘦，与胃实腑病有间矣。仿济川煎合肠痹例。", "16342": "华延症一月，脉象小数，非实火也。宗经旨泻南补北。", "16343": "张经云：膀胱不利为癃，气化则能出矣。少腹满，溲色赤，湿热蕴结奚疑。苔腻作渴，脉形小数，正气渐亏，恐多变幻，不可轻视。", "16344": "前进血脱益气法。兼清营分。虚火崩决之阵顿止。胸脘乃觉舒和。略思纳谷。可知从前谬执黄耆闭气之误。然肝肾空乏。八脉交虚。最虑腹膨漏带。干呛寒热。此四者崩后极易见之。不可不为预防。", "16345": "崩止三日。神脉皆振。头晕轰热。时仍有之。必得营阴恢复。风阳游行之象。方可全熄耳。", "16346": "脾肾阳衰。早食暮吐。完谷不化。是无火也。并非火热暴迫之完谷下趋耳。舌质淡而苔白。脉细带弦。温中以理气分。", "16347": "思虑伤脾。郁怒伤肝。血崩之下。气营大虚。彻夜不寐。神不自持。触事惊疑。此乃怔忡疑虑之症。并非癫痫类也。脉症合参。脾藏气血大伤。脾为营之源。虽云心主生血。然血不自生。须得脾气运液。中焦取汁。变化而成。心虚而不知补脾。绝其生血之源矣。且大便亦溏。胆怯异常。显属不足之症。切勿执定痰火有余也。", "16348": "脉象细而带弦。微见虚数。血崩本属气虚下陷。血去阴液亦亏。心中悸惕。惊疑无主。寻源求本之计。宜补立中气为先。倘专清痰火。必有延成痼疾者也。", "16349": "日来脉象。颇形起色。元气渐振。故恐惧忧疑之象。已可支持。肝郁日畅。寡有恼怒。诚佳机也。心脾血液未充。尚须怡养为佳。", "16350": "新产两朝。瘀不下行。发热神蒙。肢麻汗多。脉芤舌红。酷暑外迫。阴气郁冒。血随气逆。时有昏晕。变险可危。急扶产母端坐椅中。敞轩牕以湘帘护风。切勿听信妪辈。胶执吃热苦草汤也。急嘱。急嘱。", "16351": "郁火越冒。冲心为厥。厥后心悸不寐。惊恐疑惧。劫肺而为痰血。不时形凛轰热。经行如崩。月行二次。盛暑而厚衣。稀粥不敢下咽。以脉症参之。非真寒。实由疑虑过深所致也。金先生指为劳损不起之症。窃恐未确。当放胆啖饭。不必避风。以怡畅襟怀。佐以药力。可许向痊者。", "16352": "冬温乍发。月事适行。阴气先虚。邪从内传。一候之前。失于开泄肺经。今病交十三日。曾服小柴胡汤微微得汗。惟邪转充斥肺胃。兼入营分矣。昼夜烦躁。神魂飞越。脉涩弦数。舌绛苔厚。痰滞并阻。大便溏泄。深恐痉厥。必多风波变险。", "16353": "病交两候。癸水淋漓未净。色带紫黑。营热炽甚。通宵不寐。寅卯时肝风内动。指痉发厥。目窜痰涌。遍体汗泄而定。顷诊右脉洪数。舌苔根厚。色转灰黄。大便连泄。自觉火热下注。温邪欲陷。昏闭可虑。但营分渗泄于下。肺邪壅遏于上。断不能执煞热入血室之古法也。", "16354": "温邪自口鼻吸入。肺先受之。逆传心包。入暮病剧。脉较晨间数甚。再与清解。勿致昏闭为妙。", "16355": "昨诊脉后。狂躁厥逆。即以至宝丹服下。神志渐定。吐咳浓痰颇畅。黎明时得寐。寐醒尚觉气逆。便泄已止。口苦咽关疳点密布。冬温化毒。乃外泄之机。", "16356": "胸膈肌肤热势大减。额上解而不了了。脉息左含静意。右寸关尚见滑数。舌绛苔少。疳点起腐痛甚。心中烦扰。月水将净。清化上焦痰热为主。", "16357": "舌苔焦黄已化。脉数颇缓。汗多如注。疳势蔓延亦定。白腐渐退。音闪渴饮。痰多黄厚。口中腻涎若涌。外邪将净。脾虚血热。湿火内生以玉女煎合甘露饮加减。", "16358": "疳痛大缓。谷食可进。寐醒之后。溲急欲遗。数而且多。是余热宿垢蕴结阳明。迫其膀胱津液下行也。汗泄又多胃津更伤。大肠愈燥。燥火更易伤阴。纳谷未多。能勿虑其液涸乎。伤寒论有可下不可下。并急下存阴等法。两者俱是回生要关。但须用之的当。今见口竭引饮。舌苔老黄干裂。根尤厚浊。脉象数实。按腹微痛。如斯确据。诚乃急下存阴时候矣。每见邪未归府。误下致逆。不可胜数。", "16359": "昨晚大便后。夜卧极安。胃思纳谷。神脉安静。小便合度。肠胃宿垢已彻。余邪下注肛侧。结有小瘰。且痉厥时擦伤皮肤。滋水频滋。两相蔓延。颇形痛楚。虽属微末。犹恐妨碍眠食。亦属节外生枝之累也。", "16360": "舌苔渐化。纳谷较增。痢畅而稀。其痛势虽在胃脘。观食下时并不作痛。关脉弦数。属血分之邪发越。肝木并逆也。", "16361": "肝火湿热下注阳明之络。外束风寒。两腿痛甚。艰于步履。脉细舌白。姑先疏解外风。但症系内伤虚痹。最属淹缠者也。", "16362": "环跳痛缓。移于内臁。左脉转数。外风已渐化火。盖阳明主一身之络。气血亏。不能灌溉络脉。郁火湿热。乘隙内踞。而焉脾痛。去秋曾患流注。病虽异而其源则一也。拟补血汤兼理湿热。", "16363": "肝风湿热。逗留经络。痹痛夜甚。脉软带弦。舌红苔黄。此内因之病。不宜峻剂。攻风劫痰。再伤血液。须防血枯筋挛而肢废。或痹乘中土而变腹胀。当养肝阴。佐以化瘀定痛。", "16364": "昨宵痛缓得寐。脉数和而舌苔稍化。病由气血两亏。用药慎其偏胜。为要。拟萎蕤加味。", "16365": "痰阻胃阳恶心。暑邪乘虚内陷。大疟发经四次。神疲纳少。脉弦濡。舌白腻。邪在太阴。达之非易。拟东垣法为主。", "16366": "病交一候。痢已全止。高年气阴两亏之体。邪达迅速。诚大幸也。纳谷未旺。神脉尚弱。拟益气生津以恢复之", "16367": "脉症合参。始由气不摄血。血崩阴伤。自患大疟而产。产后旋即腹胀如臌。服过斗门方。戒盐半载。病已磨久。而腹大依然。半月或旬日一发。肝脾伤而阳气式微也。脉细如丝。当从症治之。仿仲景法。", "16368": "阳回脉起。舌强渐平。肿胀亦减。诸恙皆轻。自觉神情颇振。此亦气旺之明征。拟宗血脱益气法。冀其便血勿崩。病之扼要也。", "16369": "交节前后。便血未行。神脉皆段。", "16370": "癸水甫净。养心脾佐调奇脉。", "16371": "日来脉情和缓。营卫气血流通。拟培养奇经八脉。佐理肝脾。", "16372": "乳房结疬。大小不一。起经四载。屡发酸𪽪。痛楚则更坚大。胸膈梗痛如束。脉弦舌红。一派肝郁。结于阳明部分也。有关格之根柢。怡养为佳。", "16373": "乳疬痛缓胀松。胸脘亦舒。脉症合参。究系营虚肝郁也。", "16374": "暑风暑热。蕴伏于经。病交四日。昨午壮热无汗。烦躁昏谵。热逼肝胆。气火直升犯胃。呕吐痰少。频频嗳气。夜半得汗极畅。表热退净。脉尚濡数。舌红苔黄。伏邪未必即化。转疟可虑。", "16375": "经居三月之余。骤然腹痛。酸坠不已。曾经小产。手厥阴经络受伤。脉胎巳至脱根。气从下陷。深恐血崩之虑。仿东垣法。", "16376": "血崩止之后。自觉胎元跃跃如常而动。肝升烦热。寅卯更衣。感冒寒邪。形冷发搐。郁木内扰。悲从中来。骤然哭泣。面色泛㿠。神志模糊。脉细无神。此属血去胎伤。又失于调养。胎殒腹中。浊向上蒙。至危至险候也。", "16377": "瘀露下而黑色。停瘀留顿未化。胃纳渐安。寐亦稳贴。神脉皆涉和平。但恐有胎元未化。仍宜留意也。", "16378": "益阴通瘀之下。夜寐得安。脉息稍静。正气渐醒。今晨瘀中虽下茄蒂之象。此即胞胎之根柢也。前日或指停经。或指崩漏。定可剖析分明而无惑矣。仍守昨法。", "16379": "小产后。肝肾阴虚。虚阳易升。逆胃焉汗泄气急。脉见芤数。阳衰已复。阴血尚难速长。眠食向安。自可日臻佳境。百日内务宜慎养。", "16380": "日来色㿠已转。脉维右寸关尚弦数。由乎盗汗自汗互伤营液。故易于心悸也。今瘀已净。可以补中。寓以收摄法矣。", "16381": "产虚未复。郁怒动肝。肝火上薰肺胃。寅卯时咳呛缠绵。半载未能全止。纳谷勉强。五心烦热。脉细。左部虚细。右寸关弦数。虑涉损途。急挽可许向吉。", "16382": "五更咳呛得缓。癸水先期而至。舌心露质。诊脉左见数象。胁中刺痛。产后营虚肝郁也。", "16383": "前进平肝养阴。寅卯时咳呛渐稀。脉息左部弦数。右尺虚软。经事乍过。毓阴平肝为主。", "16384": "肝阳化火生风。从冲脉逆行乘胃。巅顶胀痛。不能转侧。面部肌肉跳跃。屡发屡止。今春烦劳之下。阳气越胃凌心。而致煎厥。每进滋纳肾肝得平。自后萌发颇稀。宗内经治肝第三法镇守中州以靖逆气。", "16385": "肝火逆上触心络伤血从口溢。竟有盈碗之多。近增便泄。暑湿亦兼内袭也。左脉细弦。胃气衰谷气自少旋晕。益气清暑为治。", "16386": "心脾两亏。经行先期。心悸寐少。舌心光剥。脉息细数。气分亦怯。养血毋庸重滋。", "16387": "前进养血平肝法。哮发减轻过半。脉息左数右弦。心中似乎烦扰。寐不安贴。癸水将至。营虚血热。再防反复。当加意养金水为妙。", "16388": "肝脾气陷。便后下血。患经数载。近则脱肛。血下无度。小溲淋痛。寒热时作。舌光起刺。脉形芤数虚弦。情志内伤药力断难奏效者也。所虑秋令肃降。有血从下脱之变。", "16389": "郁火湿热。内伤肝脾。痰火化风。升扰阳明。脉弦舌红。有类中之机。防眩晕倾跌。", "16390": "己丑年，京畿道胡贷青病剧，延余诊视，舌黑，谵语，不省人事，诸医均以为实热实结，拟用大承气汤。余诊脉，洪而无力，不渴，复以姜片擦舌即淡，症若伤寒，化为虚热，拟用人参竹叶石膏汤。一服便行见效，加减数剂而愈。后月余，舌退一壳，如枳壳，即书中所谓六十样舌中之銕甲舌，阴亏也。设症不辨虚实，则死生反掌矣。", "16391": "己丑，工部员外杨味春夫人吴勤惠公小姐产时搐搦，不省人事，集医治，以肝风不效。适夫人嫡堂兄吴纯甫太守进京，引见与余，父子世交，延余诊视。脉虚，知为血晕非肝风也。先用韭菜根置两壶中加醋煮开，以壶两嘴对两鼻孔热气熏之，立时生男，苏醒，拟以当归参耆千金汤服之安。然继而胞衣不下者一日，合家惊惶，余著寻鸡头、菱叶，撕破，加炒皂刺三钱，同煎，服之。时许，胞衣随恶血分碎而下，安然无恙矣。", "16392": "己丑，候选通判缪仲勉少君伤寒，他医误为瘟疫，重用凉药，以致病剧，卧床两月，痰喘欲绝。延余诊视，脉沉濡而滑相等，尚可挽回，拟以生脉散加半夏杭芍服之，见效。数服即能饮食，治理数月，两腿不能伸屈站立，其母只此一子，不胜情急，询余曰废否？余曰：以脉缓和无力，不至残疾。即用十全大补汤加杜、牛膝，下注三阴，并令捶打以舒筋血，又两月全愈矣。", "16393": "庚寅年，户部员外宝源局监督胡吕瑞少君瀹生鹾尹壶相小产，胎不下者十余日，诸医均以攻代之药，胎更不下，而疼如绞，命在旦夕。延余诊视，脉濡，以体素弱，加以小产误服攻伐，重伤气血，以致血竭而胎不下。以十全大补汤加重以助气血，加朴硝一钱以化死胎。即下，去硝，用生化汤加参耆以扶气血，数服而愈。", "16394": "壬辰，胡吕瑞部郎痢疾，昼夜百余次，汗出如流，年逾五旬，诸医均以年老气血就衰，将脱之象，重用参耆等药，而痢反剧。延余诊视，脉急有力，寒化为邪，照《内经》初痢用清，久痢用固之法，拟以黄芩汤加减，以扶正清热。胡不敢服，强而后可，一服见效，数服减轻。满月后用，真人养脏汤加减，滋阴固摄之剂，数服遂愈。辛卯，刘仲良太史夫人比部段少沦之胞妹，因观剧夜深，衣单卒中痰迷，齿脉均闭，便溺俱遗，心窝微存一息，针不出血，诸医束手。延余诊视，曰：症有七不论脉，此其痰闭之一也。系受风寒痰闭，便溺俱遗，亦非五脏绝也。手未撒，发未指，面未如妆，汗未如珠，尚可挽回。幸假至契，深信不疑，拟以小续命汤，三生饮，再造丸合参加全蝎等药，以扶正气，逐风化痰，行气和血。以口闭药不下咽，用乌梅擦牙，竹箸启齿，小壶呷药，时许即呼妈矣。医治三日方苏，月余遂愈。", "16395": "胡公度待御之仆，某年弱冠，在京出痘，色紫周身无缝，登屋狂叫。延余诊视，脉洪实有力，舌苔黑知为热邪。拟归宗汤加减，以去热邪燥粪遂安。复拟犀角地黄加减，清热透发，数贯脓结痂而愈，变为麻脸，非旧日面目矣。又有厨夫某，中风不语，他医误以瘟治病剧。延余诊视，脉细，知系卒中。拟以小续命加参耆一服，即大呼曰：何不早服此药也？又大同居东沈智泉中风，亦用此药加减而愈。又水部正郎杨紫沧中风，亦用此药加减而愈。又内务府科房王寿龄母中风，亦用此方加减，而愈。又给谏洪良品中风亦用此方加减，寿延二年。故后哲嗣鸿卿明府向云误信，人言以年老气衰，将余初拟方内羌活、独活、防风未用，以致病未除根也。其余贫民无名之人，不可胜道也。", "16396": "刘次方于庚寅年为巡街御史时，相召宴饮，余赴道谢，言未曾面，何见爱之深也？刘云：见余脉案，拟方真有道理，愿为疾病扶持之交。余以小道偶中，逊谢无何。刘患牙疼面肿，太阳筋跳如锥痛，诸药罔效，寝食俱废，延余诊视，脉数无力，知为虚热，气血相搏，邪火上蒸，内服玉女煎加减，外以开水熏洗痛处，以和气血，又以热手巾𤆡之，再用烧酒以小指蘸滴耳内，如火外发，倾刻痛止，气血和矣。再用唾膏贴之。消肿，再用硼砂、冰片、细辛、蒲黄、黄柏、青盐共研细末，频擦牙龈，消肿止疼。内服滋阴以退虚热即愈。又水部张蔚如夫人，牙疼异常，饮食俱废，亦如法加减，治之遂愈。此虚火疼十之八九，若实火疼，宜用连翘、银花、绿豆皮、芦根等清凉之药。若虫牙疼用明雄黄，松香等药擦之即死。以上诸疼，七十方中，无此妙也。萨嘉乐太史夫人患牙疳，肿疼异常，已落一齿几于穿鼻透腮。延余诊视，脉洪有力，知为热毒。内服金银花散加减，外用硼砂、冰片、红枣烧灰、儿茶、人中白、陀僧、青盐、枯矾研细末敷，继用犀黄散加轻粉麝敷之。旬日，遂愈。庚寅张季端殿撰夫人体虚难眠，延余诊视，脉沉细，用温补药数服而愈。嗣后感冒风寒，渠以为旧症，用参耆等药服之以致沉重，复延诊视，脉紧无力，知为虚人外感，治以再造散加减，解邪和中之剂，服之寒战，似药不合，渠言奈何？余复诊之脉动，言时发汗以姜白糖水饮之助气。夫人胞叔杨子琛明府知医，信余力言不错，药邪相争，故寒战耳。张留余俟之至十点钟时，果汗而愈矣。又张次子二岁时，素患腿疼，不能行走，教人捶打，以重物厌之方眠。余诊视脉弱极，两尺几无，知为先后天不足之故，拟用十全大补汤加杜仲、牛膝，下注三阴，数服遂愈。", "16397": "甲午秋，戎部李星若夫人腹疼如绞，日久欲死。延余诊视，脉沉细，知系虚寒气结，他医误用凉药，以致病剧。余始拟以附子理中汤加减，一服而愈。旋因食抄绞痛如故，九日不便，诊脉虚细，系九结中之秘结。不可攻下，拟以前方加润导之品便而愈。旋又风抄，九月初一日痛绝，齿脉俱闭，仅存一息，其胞兄内阁中书虹若言女初三日吉期，设无救奈何？余为情急，恐药饵不及，嘱星若亲灸章门、虎口、三里等穴，并将前方加山甲、牛膝、桂枝，木香、乌药等擦牙，以箸启齿，呷药，一时而苏，脉复。余出曰：包辨喜事无虞。数服而愈。丙申年，来请，言夫人血崩晕绝。往诊脉扰急，知系小产，非血崩也。治以生化汤加参耆，去旧生新之品遂愈。马积生太史夫人亦患腹痛，如绞，数月病剧。延余诊视脉息腹痛相同，因体因症加减。拟方不敢服，以为与他医用寒药相反也。适曾任广州府冯端本太守寿日与马姻亲李星若亦姻娅同往，称礼，即马遍询同乡，可否服余之药？佥云：可归即试服。次早请余，言病减半矣。深信不疑，连服数剂而愈。农部张馨庵屠逊庵亦河南人，两夫人亦患此症欲死，均为如法治愈。", "16398": "徐颂阁侍郎三公子，于甲午岁淋症，他医误以血淋，苦寒之药，数月病剧，卧床不起，身不能动，将一年矣。延余诊视，仅存一息，脉沉细知为阴亏变色，非血淋也。诘其故，言无外务，以妻归宁浙省病年不归，思想而得。余曰：欲心一动，精却离舍成淋，久则阴亏变色，误为热淋，治以寒药，至于此极。拟以人参菟丝丸加减，大补之剂，以固心肾。一服见效，复诊加减数服，能食月余，全愈。", "16399": "李实之太史放甘肃主考时，夫人住京，系朱相国之孙女，湖北廉访之女，内阁章京伯平之妹，产后病剧。延余诊视，脉沉细，四肢拘挛，瘫痿溺黑，知受风寒化热为痹。拟以独活寄生汤加减见效，继为加减数服而愈。朱即请以夫人小产数胎为忧，余诊视，脉沉无力，气血两虚。拟以泰山磐石散、千金保胎丸合参，令有孕时服三十剂，果胎安矣。连举二子。甲午农部李有荣之夫人，临产三日未落草，咸谓胎死腹中，夫人自期亦死。情急许稔婆百金下死胎，以保夫人之命。稔婆无策，延余诊视，脉缓舌苔面色均无青赤，知胎无恙。询之稔婆，向言尚未顺胎，知经人早浆破血竭，犹鱼在盆，无水不行，数日不生者多也。安熨夫人不要慌乱，静心安卧，包管无恙。即重用达生散加重参耆归芎各一两，外加葱头七个，黄杨脑七个。熊亦奇太史知医，斟酌意药太重，余言：非此重剂，不能壮气生血，毋疑。幸李素信余医，留坐茶点少待，服药时许，家人报喜生一少爷，母子均安然矣。", "16400": "癸巳孙来山尚书小姐，因寒癃闭二日，腹胀如鼓。李山农方伯知医曾治尚书湿病而愈，兹治小姐不效，素信余医，代为荐诊。少阳脉弦，知为虚痞，拟以柴胡半夏茯苓汤加减，汗解溺畅遂愈。", "16401": "京畿道徐叔鸿夫人胸胀大痛世医误以经闭三月症瘕，治之几危。延余诊视，六脉相等，阳搏阴别，孕兆也。徐公曰：生过三胎，知无孕。余曰：十样胎十样生。年近四旬，气血渐衰，正气不敌，胎气引动，素有肝气，故胀痛。拟以安胎养血调和肝气之品请姑服之。以手试腹，如伏杂状，即知是胎非病。徐公如约，次早来请言，真医也，果胎跳矣。再拟数服全愈。至秋举一子，即六少爷也。", "16402": "乙未，比部正郎欧阳伯春病伤寒，世医误以为瘟，治以苦寒之药，不眠者三日，谵语揭被，狂叫大热，舌苔黑刺。延余诊视，脉洪无力，知为虚热。以姜擦舌即白，的为伤寒，非瘟疫也。虚火上炎，内无实热，拟以人参竹叶汤加减，引火归原之品，伊诸亲多不敢主，幸伊姑丈比部郭斡臣力主服之，遂安。四服全愈。", "16403": "甲午、王子捷太史令缓感冒风寒，理宜解表和中，汗澈即愈，而世医误以犀角羚羊角等药，引邪入内，不能言语，病剧。延余诊视，脉沉紧，用羌活汤加附子肉桂去黄芩、生地，一服能言发，出疹子而愈。", "16404": "甲午冬，黄慎之殿撰伤寒，时医以为冬瘟治，以元参论两等寒药二十余日，烦躁不省人事，三日不能合眼。延余诊视，脉数不及，知为胃气欲绝之象。拟以人参汤加减引火归原之剂，一服遂眠，至次午方醒。清余道谢，复诊脉，复依方加减月余，全愈。", "16405": "甲午，刘伯崇殿撰弟归感寒谵语，暴病惊人。延余诊视，脉浮数，知为风寒化热无汗，拟以羌活汤加减，一服汗解而愈。", "16406": "甲午冬，程从周军门少君绍周太守患喉痹，时医误以温补治之，遂致喉肿水不下咽三日矣。延余诊视，脉沉细。余曰：此症肺胃肾虚，火上冲喉咙成痹。单者重而双者轻，最忌刀针，刺破喉咙，引毒入内不治，并忌温药助邪，散药发邪，凉药伏邪。误服温补助邪项肿，以致于此。余为先刺少商、商阳二穴，出黑血，以浅毒，贴金刚匙以拔毒，吹吴氏丹药以消毒拟以滋阴清肺汤加减，以和解之。服药时许饮水，晚间食粥，次日加托里透脓之品数服，外溃内消而愈。", "16407": "福建陆路提督程魁齐军门年六旬伤寒，时医以年老气衰，重用参耆补药，固邪于内，痰喘不眠，病剧。延余诊视，脉紧数，知系闭塞寒邪，化热痰喘。拟以小青龙汤加减，解寒邪，疏通肺气化痰之品。佥曰：年老气衰，不可服。余曰：有症无损，开门逐盗之法，姑试少服。其弟从周军门天姿过，人以为然，嘱先服半，咳喘顿减，终服大好，依方加减十日而愈。", "16408": "京畿道胡岱青小姐年及笄时，腹痛如绞，时医均以受寒，重用姜附肉桂，其疼逾甚。延余诊视，脉涩无寒症，因言人腹中有蛔蚘、长、寸、线白等虫九种，长虫长一尺，不治。胡公言：曾便过尺长白虫。余嘱即买花榻饼一个，令服。再买榧子二斤，炒如粟子，令吃数日，便出长白虫数尺，长无算，遂愈。", "16409": "王小岑洗马患目昏花不能视物，时医以为肝热，清风退火之药，病逾甚。延余视，诊脉沉细，知为气亏内障，拟以八味还睛散，去风药，重加参耆服三十余剂，遂能视书写字。适考试京察一等召见，简放襄阳知府。", "16410": "陈紫蓬太守在京投供五年，与余契交，患脱肛肿痛，时医均为痔疮治之，肿疼逾甚。延余诊视，脉沉虚年逾六旬，知为脱肛便血，急则治标。先以螺汁合梅片敷之，减疼，内服滋阴清提补药，顿缩；外用椅垫，日晒大热，轮换坐之；又以开水频洗，数日而愈。", "16411": "李虹若小军机瘅疟误服他医凉药，病剧延余诊视脉紧间日一发，先冷后热，谵语，四时方退，已二十余日，自谓五脏皆空，病将不治。余言包治，拟以清脾饮加减。渠云：最忌柴胡。余云：此症必用柴胡和解少阳，姑试服之，过日又发。伊云：柴胡不效，定不服矣。余诊脉，见缓，知邪将解，复强令服，疟止。再以加减数服而愈，从此不信许济东大名医矣。", "16412": "户部万锡珩夫妇咳嗽昼夜不止，痰吐成盆，时医用人参鹿茸等药，痰咳逾甚。延余诊视，脉洪数，知系风寒闭于肺中，拟以二陈导痰汤加麻黄一服而愈。伊子书城黄疸秘结十数日不便，时医治以承气汤，余诊脉沉细，知系虚黄秘结，拟以茵陈润导滋养气血，使下焦气化而能出矣。饮以猪蹄汤，十四日便通黄退，遂愈。", "16413": "冯霖汝明府夫人胎中漏血，合家惊慌。延余诊，脉和缓和，系胎漏而胎未动。拟以安胎养血之品，每月行血如经，十月而生，母子安然。", "16414": "潘辉庭正郎令亲杨姓病狂上屋，他医均以犀角三黄汤。力主延余诊视，脉洪无力，知系风寒未解，虚火上炎，拟参苓甘露饮加柴胡和解等品。伊同乡多不为然，惟潘半信半疑，焚香拈阄，得余药方，嘱一剂，作三服，初服，次服，安眠，终服愈矣。", "16415": "张书城侍御夫人病，每厥不省人事，诸医均以肝风治之不效。延余诊视，脉沉涩，知系郁结气厥，非肝风也。询夫人生育否？答以无。年几何？答以不惑。余曰：夫贵妻荣，何以气郁至此？夫人言理该如此，而事有不然者，余复询张公纳侧室否？张曰今春买一妾。余曰：后妃能逮下而小星抱衿与裯乐，只君子有何郁处？及至书房，余诘张公，具以告实，寝妾处时多。余曰：谁家郎能被汝呼也？无怪气厥耳。遂拟以调气和血之方，劝张公常宿夫人房为引，数服而愈。后遇张公笑余，医外医耳。", "16416": "唐炳霖侍御小姐，年已及笄，病剧。延余诊视，脉涩，知为气郁。询以母氏，唐曰：故。余曰：俗语能从讨饭之母，不跟做官之父，小姐笑。复问兄嫂？唐曰：不和因得病。余曰：小组自有家耳，诸事忍让，何气为询，婿谁家？唐曰：待字。余曰：有高绍祥者，年弱冠宦家公子，才貌均佳，今科备中，堪为良偶。唐颔之，因拟以调气之品数服而愈。余与柳太守为媒，高允请命于兄津江县知系查核病故事寝旋说与某主政偕老矣。", "16417": "祁子和尚书之孙君司马段少沧军机之婿夫人产后伤寒，谵语病重。延余诊视，脉紧有力，拟以葛根汤生化汤合参和解，一服汗澈而愈。", "16418": "李有槻明府在京投供患疟数月，病势沉重，诸医罔效。延余诊视，脉沉紧，知邪伏于太阴少阳之间，拟清脾饮加减，略重草果以解两经之邪，外用胡椒末合蒜捣烂，置两钱于两关脉上，置椒蒜泥，用布条札紧，一伏时拔出白泡，泄邪遂愈。", "16419": "兵部王銕珊夫人，胎中漏血，向言无孕，余以诊脉流利不绝，认定为孕，以安胎养血之品治之，迨四个月后胎动，夫人犹曰无孕，王怒曰：私子也，何讳为？夫人亦恚其言秽。余劝曰：夫妇均年不惑，无子，设他医误以病治，奈何？此情急之言，毋足怪。夫妇转怒为喜，后举一子，亲朋贺筵。余曰：私子也。众询颠末，具以告，咸大笑。", "16420": "张文和公孙联恩正郎夫人病剧，延余诊视，脉细，知为气虚中满，非实胀也。拟以补中益气汤，数服遂愈。", "16421": "冯杰观察子茂才进京乡试，病痢，日厕无数，他医重用桂附论斤，病剧。延余诊视，脉数，知系热邪，拟黄芩汤加减，一服见效。月余，痢仍一日数次，改真人养脏汤数服，全愈。", "16422": "吴燮臣司业父刑部毓春公咳喘呕逆，延余诊视脉，七八至将绝之候，服殿撰陈冠生方石膏、黄连多日，以至此剧。余拟肾气汤加减，以救垂绝之阴阳，服之见效。次早来请，以为得手，至则见喘。已轻，呃逆已止，精神大好，原可挽回复。依原方加以滋阴扶阳之品，适陈冠生至，持方连曰：火上添油也。余请示姓名，知为殿撰。曰：何知为热？陈曰：脉数曰浮数为风热，沉数为寒热，洪数为大热，数而有力为实热，数而无力为虚热。今数而无力，不及之象，犹灯油将尽，拍拍欲绝之候，添油犹恐不燃，若加滴水即灭矣。陈曰：脉之理微曰：诚然，然优人胡琴二弦三指挑拨五音合调，君能之乎？陈曰：未习也。曰：以此即知脉理，未习故不知也。遂辞。燮臣司业送出，询以病势，余曰：若听陈君主政，预备后事，不出三日也。旋陈病自用苦寒之药亦亡。", "16423": "王惠棠员外，四旬无子，不能寓内，为之拟方滋补之剂服数十帖。一日请诊视姨太太，脉阴搏阳别，左大右小，余曰：喜脉。弄璋之兆，按月请诊，果举一男，后连生子。", "16424": "侍郎许筠庵胸脘绞痛，他医均为热症。延余诊视，脉沉知为新受寒邪滞气，胃脘作痛非心疼也，拟排气饮加减。公子樨筠内阁言素服肉桂，恐系受热，余以脉论，的寒非热，出诣李山农方伯，具以告，渠与许公郎舅至亲兼知医，急往请服余方，遂愈。", "16425": "（案1）肝阳上亢之势已平，肺气下降，呛咳、鼻塞、痰多、口干皆退，肢节作痛较前大减，尚未全止。湿痰入络，荣卫交阻。脉来沉滑。宜宗前法进治。", "16426": "（案2）肝阳升腾无制，挟素蕴之湿痰流窜节络，荣卫不能通行。右手无名、小指麻木作胀，脉来沉弦而滑。治宜清肝化湿，消痰通络。", "16427": "（案3）经谓「肝主筋」，肝阳升腾无制，挟湿痰热流窜节络，筋络缩短，手足肩臂作痛、浮肿，内热烦躁，齿痛苔黄，胸脘不舒，饮食少进，腹胀且硬。湿火痰热充塞三焦，流行之气皆阻。脉来沉弦而滑。脉症皆实，可用下夺之法，诚恐年高，气虚难支，拟养阴清火，化湿豁痰。", "16428": "（案4）湿痰流窜节络，荣卫不能通行。左肩臂酸痛，手指麻木，纳谷无多，动则气疾。湿痰阻胃，宣布无权。脉来沉弦而滑。治宜化痰通络，兼以和胃。", "16429": "（案5）阴血久虚，肝阳上亢，挟湿痰阻塞包络，胃气宣布无权。脘闷气郁，目泪时下，肢节麻木阴酸，胸腹作胀，头眩欲跌，脉来沉弦而滑。治宜化湿消痰，清肝和胃。", "16430": "（案6）胸脘痞闷、气短头眩、手指麻木已退，肝阳渐平，胃气宣布。惟肾阴久亏，摄纳无权，遗精眼花，见色流精，小溲甚多，不能静坐，脉弦之象稍减，沉细如常。宜宗前法进治。", "16431": "（案7）肝阳上升，挟素蕴之湿痰，阻塞胃气，宣布无权，脘闷作恶，呕吐黄水，饮食少进，肢节麻木作痛，湿痰渐化，荣卫交阻。脉来沉弦而滑。治宜清肝化痰，调和卫气。", "16432": "（案8）《经》谓「肝主筋」，肝阳升腾之势渐平。筋络酸痛、内热口干较前已减，尚未尽退，呛咳日久，头眩眼花，肺阴久虚，清肃无权，脉来弦细。治宜清肃肺气，兼治肝阳。", "16433": "（案9）阴血久虚，肝阳升腾无制，上灼胃阴，胃失降令。脘闷腹痛，内热口干，头眩且疼，肢节酸痛，腰酸带下，脉来弦细而数。治宜养血清肝，兼和胃气。", "16434": "（案10）脾肾久虚，中无砥柱之权，下少生发之气，肝阳上升，挟湿痰流窜节络，荣卫不能通行。左手臂麻木，上及头面，呛咳气喘，痰阻肺气已著，脉来细弦。治宜益肾清肝，运脾化痰。", "16435": "（案11）肝阳升腾之势已缓，肺金清肃之令下行。呛咳鼻塞、痰多口干、肢节作痛较前已减，尚未尽退，湿痰入络，荣卫不能通行。脉弦略退，沉滑仍然。宜宗前法进治。", "16436": "（案12）《经》谓「脾主四肢」，脾胃久虚，湿热下注。腿足暮肿朝消，右手臂麻木，大便溏泄，甚则呛咳、口干，湿热痰上阻肺气，脉来细弦。宜健脾化湿，消痰肃肺。", "16437": "（案1）湿热无从宣泄，上阻清道，肺金清肃之令不能下行。呛咳喉痛，牵引胸腹，有如带束，头面、颈项起颗结块，脉来细弦而数。清化湿热，兼肃肺气颇合，宜宗前法进治。", "16438": "（案2）湿热生虫。常有寸白虫随大便而下，或不大便，从肛门而出，脉来细缓。阴液已虚，湿热内蕴，已可概见。治宜清化湿热，并益阴清肝法。", "16439": "（案3）《经》谓「肺合皮毛」，肺有湿热，散布分肉之间。体热咳嗽，肌肤起颗作痒，破碎，略有脂水，即易结痂。湿热里达表，最是佳征，必须令湿热尽透于外，肺气清肃下行。脉来浮滑。治宜清化湿热，兼肃肺气。", "16440": "（案4）脾土久虚，运化无权，湿热淆乱清浊，升降失常。胸腹胀痛，大便泄泻带红，内热口干，小溲不利，纳谷无多，脉来沉细而弦。治宜健脾化湿，兼和胃气。", "16441": "（案5）湿热下注，膀胱气化无权，小溲茎中作痛，甚则白浊时下。湿热必须清化，投补太早，禁锢湿热，无从宣泄，蕴结于中。脉来沉细。治宜清化湿热，兼养阴调气法。", "16442": "（案6）肝阳升腾之势渐平，肺金肃清之令下行。呛咳、内热、口干、自汗较前已减，惟遗精便血，小溲浑浊。肾阴久虚，封藏不固，湿热下注，销铄荣阴，脉来沉细。治宜益肾化湿清肝。", "16443": "（案1）脾胃久虚，中无砥柱之权，下少生发之气，肝阳上升，挟素蕴之湿痰，耗气灼阴，流灌失职。内热口干，头眩神倦，脉来细弦。治宜脾肾并补，清肝化痰。", "16444": "（案3）胸腹作痛已止，大便亦调，湿痰渐化，胃气通降。惟脾土未健，运化失职。腹胀贲响，夜寐不酣，脉来沉细。治宜健脾渗湿，兼和胃气。", "16445": "（案5）大便通畅，湿热下泄，胃气宣布，胸腹较舒，呕吐亦止。惟纳谷运化不速，腿足软弱无力，脾失运化之权，肾少生发之气，脉弦已减，沉细如常。宜宗前法进治。", "16446": "（案6）湿痰上阻肺络，肺气不降，肾气不纳。呛咳气疾，举发无常，甚则喉际痰声漉漉，寝食俱废，抱恙多年，根深蒂固。脉来弦滑。治宜渗湿消痰，兼肃肺气。", "16447": "（案8）脾土不运，积湿生痰，阻塞胃气，不能下降。胸脘痞闷不舒，饮食少进，不易消化，苔黄，神倦，四肢无力，脉来沉细而滑。治宜健脾化食，消痰和胃。", "16448": "（案9）湿痰渐化，胃气流行，胸脘皆舒，呕吐已止，大便通畅。惟精神萎顿，腿足软弱无力，脾肾久虚，中无砥柱之权，下少生发之气，脉来沉细。宜宗前法，更进一筹。", "16449": "（案11）湿痰渐化，气机宣布，胸腹渐舒，尚未通畅，内热口干，头眩目赤，纳谷运化不速，脾肾久虚，肝阳上亢，耗气灼阴，流灌失职，脉来沉弦。宜宗前法进治。", "16450": "（案12）肝气上升，克脾犯胃，土受木制，运化无权，积湿生痰，阻塞气机。胸胁作痛，受寒咳嗽，湿痰凝结已著，脉来细弦，居经不行，已经四载。治宜养血润肝，扶土化痰。", "16451": "（案13）脾肾久虚，中失运化之权，下少生发之气，积湿生痰，阻塞气机。胸腹胀痛贲响，大便或溏或结，便后带血，脉来细弦。治宜化湿消痰，宣通气机。", "16452": "（案14）脾肾久虚，中失运化之权，下少生发之气，积湿生痰，阻塞胃气，不能下降。胸腹胁肋胀痛，纳谷无多，脉来细弦。治宜渗湿化痰，兼和胃气。", "16453": "（案15）纳谷无多，不易消化，口干破碎，腿足怯冷，大便溏薄，每日二三行。肾气久虚，肝阳上升，湿痰阻塞，胃气宣布无权，脉来沉细而弦。益肾清肝，化痰和胃颇合，宗前法进治。", "16454": "（案16）湿痰渐化，胃气下降，胸脘较舒，大便亦调。惟腹内结块，咯痰，觉冷，纳谷无多。脾土久虚，运化无权，脉弦已减，沉细仍然。宜宗前法进治。", "16455": "（案17）脾土久虚，运化无权，积湿生痰，阻塞肺气，清肃之气不能下行。呛咳气喘，脘闷鼻塞，甚则喉际痰声漉漉，寝食俱废，脉来沉弦而滑。治宜健脾渗湿，化痰肃肺。", "16456": "（案18）脾土久虚，运化无权，积湿无从宣泄，蕴结于中，阻塞胃气，宣布失职。胸腹不舒，纳谷无多，大便溏薄，脉来沉细而弦。治宜健脾化湿，兼和胃气。", "16457": "（案19）（痰热）内热口干，头眩作痛，眼花痰多，饮食少进，脾失运化之权，肾少生发之气，肝阳上升，挟痰热销铄津液，脉来细弦而数。治宜益肾清肝，运脾化痰。", "16458": "（案3）（咳兼湿疮）湿热无从宣泄，肺金清肃之令不能下行。呛咳喉痛，牵引胸腹，有如带束，头面、颈项、手臂起颗结块，脉来细弦而数。清化湿热，兼肃肺气颇合，宜宗前法进治。", "16459": "（案4）（外感）饮食不节，兼受风邪，肺不清肃，胃不宣通。呛咳又作，鼻塞头痛，胸腹贲响，食入疼胀，脉来浮弦而滑。治宜泄邪肃肺，导滞和胃。", "16460": "（案7）（咳兼血）肺金清肃之令下行，呛咳口干、咯血内热、苔黄耳鸣皆退。惟神昏发厥，肢节抽掣，肾阴久虚，水不涵木，肝阳化火，挟痰热上阻包络，神明无主，脉来弦滑。治宜益肾清肝，兼化痰热。", "16461": "（案8）（咳兼脘痛）肝阳升腾之势渐平，肺气肃降，脘痛已止，呛咳、内热、口干、腰酸渐退，惟头眩心悸，小溲频数。肾阴久虚，下失封藏之固。脉弦略迟，沉细如常。宜宗前法进治。", "16462": "（案9）（咳兼疝）肝阳上升，挟湿痰阻塞肺胃，宣布无权。呛咳，脘闷，饮食少进，疝气偏坠于右，睪丸胀大作痛，肺郁不舒已可概见，脉来弦滑。治宜清肝化痰，肃肺和胃。", "16463": "（案10）（外感）肺肾阴虚，湿热下注，膀胱气化无权。屡次遗精，溲前带浊，感冒逡，清肃无权，间或呛咳，脉弦已退，风邪外解。治宜益肾化湿，兼清肺气。", "16464": "（案12）（干血咳）居经不行已三阅月，呛咳内热，口渴引饮，饮食少进。肝郁化火，销铄肺胃阴液，肺失清肃之权，胃少冲和之气。脉来弦细软，入夜神迷谵语，干血痨症已成。姑拟育阴制阳。", "16465": "（案13）（初诊，干血劳咳）阴血久虚，肝阳升腾无制，销铄肺阴，金受火刑，清肃无权。呛咳，内热，口干，头眩，卧难著右。居经不行已三阅月，脉来弦细而数。势已入损，治宜养血清肝，兼肃肺气。", "16466": "（案14）（复诊，干血劳咳）肝阳升腾之势渐平，胃气下降，内热、口干较前已减。惟呛咳，头眩，卧难著右，居经不行已三月，肺阴久虚，清肃无权，脉弦略退，细数如常。宜宗前法进治。", "16467": "（案15）（咳兼血）肝阳上亢之势渐平，脾有复振之权。痰带血丝已止，内热、气急、大便溏薄均减，尚未尽退，呛咳作恶。肺肾阴虚已极，胃气宣布无权，脉弦略退，沉细如常。宜宗前法进治。", "16468": "（案16）（咳兼衄）肝阳升腾之势已缓，肺金清肃之令下行，内热、口干、衄血已止，纳谷不易消化、呛咳、气急皆减，尚未尽退。肺肾阴虚，摄纳无权，脉来沉细。宜宗前法进治。", "16469": "（案19）（咳牵胸背）肝阳升腾之势渐平，津液宣布，内热、苔黄腻皆退。惟呛咳气急，牵引胸背不舒，肢节酸痛，夜寐不酣。肺阴久虚，清肃无权，脉弦略退，沉细如常。宜宗前法进治。", "16470": "（案20）（外感）风邪外解，气机流行，发热较前大减，尚未尽退。咳嗽气急，甚则鼻扇。余邪未清，挟痰热销铄津液，肺气肃降无权。脉来弦滑。治宜生金肃肺，兼泄余邪。", "16471": "（案21）（外感）风热留恋气分，肺失清肃之权。发热咳嗽，不思饮食，大便不畅。肺与大肠相表里，脏气不和则府气不宣，脉来浮弦。治宜生津泄邪，兼肃肺气。", "16472": "（案22）（咳兼血）《经》谓「形寒饮冷则伤肺」。前月初著寒，咳嗽延今月余，咳嗽虽减，肺阴受伤，络血上溢，内热口干，脉来弦细而数。势已入损，治宜清养肺阴，兼化痰热。", "16473": "（案23）（咳兼鼻血）呛咳气急、鼻塞有血较前已减，肺金清肃之令下行。惟乍寒乍热，脘闷咯血，大便不畅。痰热销铄胃阴，胃气宣布无权，脉来沉滑。治宜清化痰热，肃肺和胃。", "16474": "（案24）（咳兼血）血分之热已清，早起咯血已止，饮食加增，胃气流行。惟肺阴尚虚，清肃无权，呛咳气急虽减，而未尽退，脉来缓滑。治宜清养肺阴，兼化痰热。", "16475": "（案25）（咳兼痔）阴血久虚，肝阳上升，消灼肺胃阴液，气机肃降无权。呛咳，内热，口干，脘闷，喉际作梗，头眩神倦，痰味热腥，痔疮下血。湿热内蕴已著，脉来细数。治宜清肝和胃，肃肺化湿。", "16476": "（案27）（咳兼喘）湿痰渐化，肺金清肃之令下行，呛咳气喘未发。惟饮食过多不易消化，胸脘气觉不舒。脾土未健，运化无权，脉来沉细。治宜甘温运脾，化痰肃肺。", "16477": "（案2）外感风邪，化热灼津，肺失清肃，发热已经三候未解，日轻夜重，每逢子时其热更炽，交寅方觉轻减。近日大便泄泻，肺邪下迫大肠，传道失职，津液愈伤，气失所养，中无砥柱，肌肉消瘦，面浮肢肿，苔白不渴，脉来细弱。邪少虚多，脱象已著，姑拟生津，兼泄邪法以望转机。", "16478": "（案3）外感风邪，挟食滞淆乱清浊，升降失常。大便泄泻，少腹作痛，头眩且胀，口干苔白，脉来弦细。虚体受邪，必以祛邪为先，外解风寒，内消食滞，清浊自分，邪退正安，河间治法不外乎此。治宜泄邪消食，升清降浊。", "16479": "（案4）进泄邪消食、升清降浊法，发热已退，邪从外泄。惟内陷肠胃之邪，因体虚气弱，难以外透，挟食滞耗气灼营，泄泻转为痢疾，红白俱下，少腹作痛，舌苔白腻，口不作干，脉来弦细。脉症细参，正虚邪陷，非养正透邪，下痢安有止期？症势非可轻视。治宜补散兼行，佐以消导。", "16480": "（案5）湿热已化，清升浊降，下痢已止，大便虽溏颇畅。前日恶寒发热，风邪乘虚而入，遏抑营卫，内热口干，余邪未清，胃失降令，脉来弦滑。治宜清余邪，甘润和胃。", "16481": "（案6）感受风寒，挟素蕴之湿痰，阻塞气机，肺不清肃，胃不宣通。脘闷腹痛，二便不甚通利，呕吐痰水，肢节阴酸，神倦力乏，脉来浮弦。治宜泄邪化痰，肃肺和胃。", "16482": "（案8）风邪外解，荣卫流行，恶寒发热已退。惟知饥少纳，头昏神倦。胃气未和，宣布无权，调和胃气，不外甘平。脉来细弱。治宜甘平养胃。", "16483": "（案9）外感风寒，肺失清肃之权。恶寒咳嗽，小溲色黄，胸脘不舒，纳谷无多。湿痰阻胃，气不通降，脉来浮弦。治宜泄邪肃肺，化痰和胃。", "16484": "（案2）脾肾久虚，肝阳上升，挟痰耗气灼荣，流灌失职。内热口干，苔腻头眩，胸腹结块作痛。气聚则凝，气散则平，病在无形之气，不在有形之血。脉来弦细。治宜益肾清肝，运脾化痰。", "16485": "（案3）《经》谓「诸风掉眩，皆属于肝」，又谓「肝开窍于目」。头眩作痛偏左，时常眼花，肝阳上升，挟痰灼阴，痰热蕴结已著，劳动口干，阴虚阳盛，脉来沉弦而滑。治宜益肾清肝，兼化痰热。", "16486": "（案7）肝当冲脉，冲任隶于阳明，荣血久虚，肝阳上灼胃阴，冲任失司。月事愆期，胸腹胀痛，纳谷不易消化，呕吐头眩，脉来弦细。养血清肝，颇为合度，宜宗前法更进一筹。", "16487": "（案8）荣血久虚，肝阳上亢，销灼胃阴，胃失降令。胸脘不舒，内热口干，甚则头眩，居经不行已三阅月，脉来沉弦而滑。治宜养血清肝，兼和胃气。", "16488": "（案10）阴血久虚，肝阳升腾无制，胃失降令。胸腹胀痛，纳谷无多，内热口干，苔腻头眩，月事不调，脉来沉细而弦。治宜养血清肝，兼和胃气。", "16489": "（案12）阴血内损，不能濡润诸经，头眩目燥，脘闷腹胀，神疲力乏，腿足阴酸，肝阳升腾无制，销灼胃阴，胃失降令，脉来沉细而弦。治宜培补阴血，兼潜肝阳。", "16490": "（案13）荣血久虚，肝阳上亢，销铄胃阴，胃失降令。胸腹作痛，内热口干，甚则头眩。调胃必先平肝，木火不升，胃气自降。脉来沉弦而滑。治宜养血平肝，兼和胃气。", "16491": "（案14）阴血内损，肝阳升腾无制，挟痰热上阻清道。头眩欲跌，内热口干。《经》谓「诸风掉眩，皆属于肝」，肝为刚藏，非柔不和。脉来细弦而滑。治宜养阴清肝，兼化痰热。", "16492": "（案15）脾肾久虚，中无砥柱之权，下少生发之气，积湿生痰，积痰生热，销铄肺阴。鼻塞头痛，内热口干，脉来虚弦。治宜益肾运脾，化痰肃肺。", "16493": "（案16）荣血久虚，肝阳上升，销铄胃阴，胃气宣布无权。胸脘不舒，纳谷不易消化，大便溏泄，心悸内热，头眩，苔腻，发际起块结痂，脉来细弦。治宜养血清肝，兼和胃气。", "16494": "（案17）肝当冲脉，冲任隶于阳明，肝阳上灼胃阴，冲任失司，带脉约束无权，月事淋漓，白带时下，乳胀，内热口干，头眩，腹痛作恶，纳谷无多，屡发喉痹，红肿痛，脉来细弦而数。治宜养血清肝，兼益胃阴。", "16495": "（案1）肺有蕴热，耗气灼荣，络血上溢。今早咯血，口干不欲多饮。痰为热遏，无从宣泄，清肃无权，已可概见。脉来弦细。治宜化痰清热，兼肃肺气。", "16496": "（案2）胸腹作痛，牵引腰背，纳谷无多，吐血而痛不减。病不在血而在气，肝阳上升，挟湿痰阻塞胃气，宣布无权。脉来弦细。治宜养血清肝，化痰和胃颇合，宜宗前法进治。", "16497": "（案3）肝阳升腾之势渐平，津液宣布。日晡凛寒肌热已退，每早痰内带血虽减未止。脾肾久虚，痰热灼阴耗气。脉来沉细。治宜脾肾并培，清化痰热。", "16498": "（案1）《经》谓「肾藏精」，又谓「肺开窍于鼻」，肾阴久虚，封藏不固。屡次遗精，鼻塞且衄。气逆痰多，肝阳上灼肺阴，清肃无权。脉来沉弦而滑。治宜益肾清肝，化痰肃肺。", "16499": "（案2）内热、鼻衄皆退，肺金清肃之令下行。惟脾土未健，积湿阻胃，宣布无权。肚腹作痛，即欲大便，纳谷无多，脉来细弦。治宜健脾化湿，兼和胃气。", "16500": "（案3）风邪外解，荣卫流行。恶寒发热已止，胸胁作痛、呕吐清水虽减，未尽退，痰阻喉际，咯不易出，居经不行已三阅月。湿痰阻胃，宣布无权。脉弦略退，沉滑如常。宜宗前法进治。", "16501": "（案5）肝郁气逆，胃失降令。胸脘胀痛。举发无常，甚则口多涎沫。调胃必先平肝，木能条达，胃自宣通。脉来沉弦。治宜养血柔肝，兼和胃。", "16502": "（案7）肝气上升，挟素蕴之湿痰，阻塞胃气，宣布无权。胸腹胀痛，腰腿阴酸，头眩口干，腿足破皮，时有脂水，月事愆期，脉来弦细。治宜调肝化湿，消痰和胃。", "16503": "（案14）木火升腾无制，挟素蕴之湿痰，阻塞气机，宣布无权。胸腹作痛，心悸，内热口干，头眩，赤白带下，甚则腰酸，脉来细弦而数。治宜养阴清火，兼化湿热。", "16504": "（案19）荣血久虚，肝气上升犯胃，阳明宣布无权。胸腹作痛，牵引腰背，纳谷无多，脉来沉弦而滑。久延有噎膈之虞，治宜养血调肝，兼和胃气。", "16505": "（案21）恙由伤风咳嗽而起，久咳伤肺，清肃无权，湿热无从宣泄，上蒸清道。呛咳牵引胸腹作痛，头面、颈项、手臂起颗结块，湿热为病已著，脉来弦细而数。治宜清化湿热，兼肃肺气。", "16506": "（案22）阴血久虚，肝阳上升，销铄胃阴，胃失降令。胸腹胀痛，结块甚多，懊𢙐呕吐，内热口干，头眩惊惕，脉来沉细而弦。治宜养血清肝，调和胃气。", "16507": "（案1）抑郁伤肝，火升无制，挟痰销铄心营，神魂飞越，入夜尤甚。夜不成寐，喜笑呓语，坐立偏倚。《经》谓：神伤则恐惧自失，魂伤则不正当人。脉来沉细而弦。治宜清火化痰，镇魂安神。", "16508": "（案2）肝阳上亢，挟湿痰蒙蔽包络，神明无主，如浮云蔽日，虽照无光。神识乍清乍昧，时常喜笑，夜不成寐，包络受病已无疑义。大便燥结，必须五六日一行，或肌热，或手足心内热，无非痰火灼阴见症，辛凉清热未免耗气伤津。脉来弦滑。清通神明，降火消痰颇为合度，宜宗前法，更进一筹。", "16509": "（案3）外邪不从外泄，自肺内陷包络，神明出入之窍皆闭。牙关紧强，神昏不语，戴眼肢掣，肝风鼓动，脉象模糊，危在旦夕。昨夜呕吐，便通，邪仍不解，交阴更甚平日，阴虚火旺，已可概见。姑拟芳香宣窍，豁痰生津法，聊尽人事，以待天眷。", "16510": "（案6）水不涵木，肝阳升腾无制，挟素蕴之痰热，上阻包络，心不自主。神思恍惚，疑虑惊恐，时常健忘，脉来沉弦而滑。抱恙日久，根蒂已深。治宜清通神明，调肝化痰。", "16511": "（案8）肝火上升，挟胃中痰热蒙蔽包络，神明无主，如浮云蔽日，虽照无光。神识迷昧，语言无次，时带喜笑，脉来沉细而弦。抱恙多年，根深蒂固。治宜清通神明，降火化痰。", "16512": "（案1）阴血久虚，肝阳上升，挟素蕴之湿热，销铄胃阴心营，心肾不交。夜寐不酣，喉痛目燥，牙关流血，作恶欲吐，腰酸带下，下体起颗作痒，脉来细弦而数。治宜养阴清肝，化湿和胃。", "16513": "（案2）湿痰渐化，胃气下降，胸腹胀痛较前已减。惟大便溏泄，每日五六次，纳谷无多，夜寐不酣，脾土未健，运化失职，脉弦略退，沉细仍然。治宜健脾化湿，兼和胃气。", "16514": "（案1）湿痰渐化，肺气下降，喘哮较前已减，而举发无定。喉际痰声漉漉，寝食俱废。脾肾久虚，摄纳无权。脉弦略退，沉滑仍然。宜宗前法进治。", "16515": "（案1）《经》谓「肺属金，主声音」，水不涵木，肝阳上烁肺阴，清肃无权，失音已经半载。向来遗精，耳鸣气急。肾阴久虚，封藏不固。脉来沉细而弦。势已入损，治宜益肾清肝，化痰养肺。", "16516": "（案2）《经》谓「肺属金，主声音」，肝火上升，销铄肺阴，清肃无权。呛咳音喑，咽喉红痛，入夜内热，脉来弦数。势已成损，姑拟益肾清肝，养肺消痰。", "16517": "（案1）肝阳上升之势已平，津液宣布，咽喉白腐、齿浮且痛、手足心内热皆退，痰热虽化而未尽净，脉弦已减，沉滑如常。治宜清化痰热，兼育阴制阳法。", "16518": "（案3）阴血久虚，肝阳升腾无制，挟痰热销铄胃阴，津液宣布无权。蒂丁色红作痛，喉起红颗，头眩且疼，内热口干，脉来细弦而数。治宜养阴清肝，化痰和胃。", "16519": "（案4）恙由下痢而起，迄今三月，大便仍带红，气觉下坠，口干苔腻。脾虚弱，湿热蕴结，脉弦细。治宜益气培脾，兼化湿热。", "16520": "（案1）脱肛作痛，时常带血。脾土久虚，中无砥柱，湿热下注，销铄营阴，肾阴更亏，肝阳上升，挟湿痰阻气。胸脘不舒，内热口干，脉来沉细而弦。治宜益肾清肝。", "16521": "（案6）《经》谓「肾藏精」，屡次遗精，肾阴久虚，封藏不固，已可概见。劳力伤脾，中无砥柱，精神萎顿，四肢无力，脉来沉细而弦。治宜脾肾并补，兼固精气。", "16522": "（案7）肝阳疏泄之势渐平，下元封藏已固，遗精已止，内热、盗汗均退。惟间或口干，劳动气急，肾阴尚虚，气不收纳。《经》谓「损其肾者益其精」，脉来细缓。治宜补肾益气，兼清肝阳。", "16523": "（案8）脾肾久虚，中无砥柱之权，下失封藏之固，屡次遗精，胸腹作胀，呛咳气急。积湿生痰，阻塞肺胃，气不通降，脉来弦滑。治宜脾肾并培，兼化湿痰。", "16524": "（案1）餐饭已加，入夜能寐，尚未酣畅，流浊已经匝月，茎中作痒，牵引后阴，觉热，小溲短数，间或咳嗽。肾阴久虚，湿热内蕴，气化无权。脉来弦细。宜宗前法进治。", "16525": "腰为肾府，肾虚腰痛，头痛眼花，内热口干，腿足阴酸，木少水涵，肝阳上亢，挟痰销铄肺阴，清肃无权，间或呛咳，脉来沉弦而滑。治宜益肾清肝，兼化湿痰（服廿帖，四月廿九日）。", "16526": "肝阳升腾之势渐平，内热口干较前已减，腰痛、咳呛、腿足阴酸虽减未止，大小便时懔寒，甚则头痛。肺肾阴虚，痰热蕴结。脉弦略退，细滑仍然。宜宗前法进治（五月廿七，服三十帖）。", "16527": "肝阳升腾之势已缓，肺金清肃之令下行，呛咳已止。惟内热口干，头眩目痛，遗精腰酸，胸腹不舒。脾肾久虚，痰热耗气灼阴，流灌失职，脉来缓滑。宜宗前法，更进一筹（九月十八日）。", "16528": "女子之病与男子同，所异者，经带以及胎前、产后耳。先哲谓：「经血超前属热，落后属寒。」此是定论，然亦有属血虚者，不可不知。每逢经行而少腹作痛，是血欲行，为气所阻，治必养血兼调气。如经后腹痛，血虚无疑，补血为主。凡崩漏症，前人皆指暴崩非热，久崩非寒。暴崩必兼益气摄血，久崩必养阴清火。带下症不外阴虚火旺而兼湿热，然亦有肝郁脾虚者。带有五色，须分别治之。脉左寸动滑，有摇摆之状者，怀孕也。月事当行不行，而有仍行者，荫胎之血有余，惟身体结实者如此，行之二三月，渐少而止。初受孕而呕者，气血初凝，胃失宣布；或妊娠已七八月而呕吐者，此胃气虚也，宜用参麦汤，补之即愈。每逢三月小产者，心阳搏肾，治必壮阳制水，兼固胎元。凡胎前外感，古用四物汤保胎，最为误事，外感必开泄，而反以滋腻血药，引邪入血，致肝风内动，母亡而子安能保乎？胎气强弱，全在母气安危，开泄邪热，令母气安和，正所保胎，舍此别无良法。产后以去瘀为第一义，倘瘀血不去，停积于中，少腹作痛，甚则有「三冲」之患，冲肺则气喘，冲胃则呕吐，冲心则神昏发厥，速以醋炭熏之，气从鼻入，其人即苏。叶天士谓：产后百脉皆虚，最多空窦，况身体素虚者，行血不宜太过，恐损真元。阴液虚者，养血行血；阳气虚者，益气去瘀。产后宜温之，谬说！断不可！可从临症斟酌，丝丝入扣，则从应各当矣。", "16529": "白带时下，肝阳挟湿热灼阴，带脉不固。治宜清肝化湿。", "16530": "黄带时下，任脉有火，挟湿热灼阴，带脉不固。治宜清火化湿。", "16531": "青带时下，如绿豆汁，腥秽异常，肝郁化火灼阴，带脉约束无权。治宜清肝。", "16532": "怀孕月余，内热呕吐，胎初结成，胃失宣布，左寸脉动滑，有摇摆之状。治宜苦降辛通。", "16533": "（案1）先天肾虚，后天脾弱，中失运化之权，下少生发之气，湿痰阻气，凝结成块，脉来沉弦。治宜益肾健脾，化痰理气。", "16534": "（案2）脾肾久虚，肝阳太旺，挟湿热耗气灼荣，肾囊时流脂水、血水，少腹恶寒，湿热生痰，阻塞气机已著，脉来沉细而弦。治宜益肾清肝，健脾化湿。", "16535": "（案1）目为肝窍，瞳神属肾，得血而后能视，肾阴肝血俱亏，精华不能上注，左目散光，右目作痛，阳升无制，挟热痰销铄营阴，脉来沉弦。治宜清肝益肾，兼化痰热。", "16536": "（案2）目为肝窍，瞳神属肾，得血而能视，营血久虚，木火升腾无制，销铄营阴，左目散光，视物不甚清楚，咯血鼻衄，内热口干，脉来沉弦。治宜清肝明目发光。", "16537": "（案4）肌肤起颗成片，破碎时流脂水，腿足内热，暮肿朝消，湿热外发，下行自寻出路，脉来弦滑。抱恙多年，根深蒂固。治宜气血两清，缓缓图功。", "16538": "（案1）肝阳升腾之势渐平，津液宣布，内热口干较前已减。惟颈生瘰疬，偏右腋下又结痰核，脾肾久虚，痰热蕴结，耗气灼阴，脉弦略退，沉滑如常。宜宗前法进治。", "16539": "（案1）肝阳上亢之势渐平，肺气肃降，内热口干、脘闷腹胀均已轻减，腿足暮肿朝消，月事愆期，白带时下，甚则怯冷手震。阴血久虚，湿痰阻胃，脉来弦细。宜宗前法进治。", "16540": "（案3）阴血久虚，肝阳上灼胃阴，冲任失司，带脉约束无权，血崩成块，带下甚多，心悸内热，头眩眼花，肢节酸痛，腿足浮肿，脉来沉细而弦。治宜养血清肝，兼和胃气。", "16541": "（案5）气血皆虚，中无砥柱，肝阳升腾无制，销铄肺胃阴液，知饥少纳，心悸，内热口干，头眩，带下腰痛，带脉约束无权，脉来细弦。治宜益气补阴，兼清肝阳。", "16542": "（案6）脾土久虚，湿热阻胃，气失降令，脘痛腹胀，内热口干，头痛眼花，腰酸带下。阴血内损，木火升腾无制，销铄津液，脉来细弦而数。治宜健脾化湿，兼益阴制阳法。", "16543": "（案1）徐，三十岁，春元钱庄。风邪自口鼻吸入，肺先受之。肺主皮毛，发为风疹，目赤，面如渥丹，发热，咳呛，多痰，头胀，脘闷，咽痛，小便短涩，大便不行，脉浮数。风已化热，弥漫上焦，急宜清肃肺卫，俾疹点透达，不致烦躁气喘为吉。", "16544": "复诊：风疹遍体透发，胸闷、头胀均愈，大便亦行，惟寐觉咽干，喉痛，咳痰不爽，痰中映红，据述素有咯血遗泄病，阴亏体质，易感风热，脉左弦数，右细数，舌心色紫。以微苦微辛清肺胃之热，以甘寒存肺胃之阴。", "16545": "（案2）孙，洞庭山人，裕康南货。去夏咯血，至今复发，时患遗泄，胸脘不舒，夜不成寐，脉双弦，素有痰湿，肺胃留热，且有心火。治以清泄。", "16546": "复诊：投清泄心火之剂，咯血、遗泄均愈，脉亦较和，惟胸脘气分尚觉未舒，（李辛坨师曰：当舒肺气，如旋覆、苏梗之类。）时作太息之声，素有痰湿，以调理脾胃为治。", "16547": "（案4）徐霭翁郎，二十岁，太平弄纸行。咳呛多痰不爽，咯血色紫，舌起红点。此肺胃郁热不能宣通之故。面色㿠白，脉细数，阴分素亏也。先以宣通肺气，佐以泄热存阴。", "16548": "复诊：咯血已止，咳呛多痰，浓厚，青绿色，夜间时觉轰热，舌红点已退，脉仍细数。以降火滋阴涤痰为治。", "16549": "二复：咳呛渐缓，轰热亦平，今晨咯出紫黑色一口，脉数而浮。阴亏火旺之体，再交春令，又值少阳相火司天之运，惟冀水能涵木，火不刑金，方为妥善。仍守前法，兼泄木火。", "16550": "三复：咳嗽虽缓，而夜分仍作，喉间微闻痰声，今晨鼻中吸出紫红色涕，多梦纷纭，时汗出，脉数如故。上焦之热尚未清肃，明日即交春令，天暖如暮春，深恐咯血复发，与以甘寒凉润。", "16551": "四复：昨交春令，夜间咯血三口，阴亏之体，阳不潜藏，脉数仍未稍减。拟清养肺胃，复以介类潜阳。", "16552": "五复：据述昨宵咳嗽十减五六，惟黎明时有盗汗，脉数较前略平。治法总以清肺养胃滋肾三者为要领。", "16553": "（案5）秦，右，五十一岁，洞庭山人。连年患吐血、血崩，及三阴虚，舌脱液，中心猪肝色，脉两手软弱无力，腰痛，头晕，手麻，耳鸣，小溲频数不禁，种种虚象叠现。今因新感咳呛，痰中映红，音嘶。久病难以骤复，先治其标，后治其本。", "16554": "（案6）苏仰翁，宁波人，万顺祥北货行。风邪袭于肺络，咳呛多痰，夜间发热，脉数，右颐作痛。以清肃肺胃。", "16555": "（案7）陆云翁。素有咯血症，时患喉痒，痒则呛嗽，吐薄痰，脉两寸皆数，左关弦。肺虚有热也。治以清肃肺气。", "16556": "复诊：投清肺之剂，喉痒、咳呛渐愈，惟咳呛时左右胁微痛，脉左弦右数。前法佐以通络。", "16557": "（案8）郭，右，二十余岁，苏州人，广东郭安庭之妾。方书以未产流乳为乳泣。今据述病起两年，初起左侧肿痛流脓，现左右时作胀痛，揾之皆有乳汁，而天癸仍如期而至，似与乳泣一证有间。夫乳属肝胃二经，乳汁系胃液所化。又述病初发时曾因懊恼而起，显系肝火胃热郁蒸所致。脉形细数而滑。以缪仲醇疏肝清胃法缓调，俟肝胃气和，再议滋补。", "16558": "（案9）储，右，苏州人。经事愆期，此次先期而至，腹痛，骨节、腰脊皆酸，色鲜不多，阵痛则下，胸脘闷，得嗳则舒，口腻，脉数，舌黄。此气血交滞也。", "16559": "（案11）屠，右，二十余岁，松江人，北㘮屠仰山之妾。据述经事先期而至，至时胃中泛泛欲呕，脘下气耕作痛，头亦微痛。夫经事先期为血热，阴虚则生热；胃中欲呕，脘下作痛，皆木乘土之明征；头痛不甚，阴虚，非外感也。脉细数。治宜凉肝清胃。", "16560": "（案12）张，左，六十八岁，上海人。据述少时曾有咯血症，已不复发。前年偶有忧虑之事，适从高坠下，旧疾复发，发时喉间介介然，遇天阴则血多痰少，晴则否。此素体有湿，络中有瘀也。脉弦数，舌腻。拟通肺肝之络，宗《金匮》旋覆花汤合《千金》苇茎汤法。", "16561": "（案13）卫，右。据述腹胀如臌，已见脐凸，纳食少许，即腹胀难忍，腰痛，小便不利，晨起肿至足跗，曾针过两次，脉左细数，右沉数，舌白。此单腹重症，本系气虚作胀，加以治不如法，脾胃伤残极矣。痼疾未易调治，勉以温补通阳。", "16562": "（案14）苏，宁波人。嗜酒豪饮。酒客多湿，湿中伏火结于阳明，食入即饥，所谓胃中热则消谷善饥，脘间时觉不舒，恐成中消之症，脉涩，舌根黄腻。以苦辛通湿中之火。", "16563": "（李师云：脉涩者，难治，将来恐成嗝。此时火盛，后来津液枯矣。）", "16564": "（案15）冯，宁波人。感受时令风邪，头痛甚于额，咳呛甚于夜，耳痒，时出脓水，入暮神倦，脉左弦右数。此风邪挟少阳之火上升也。治以清泄。", "16565": "（案16）孙，右，二十余岁。月前感冒，咳嗽，发热，现患头痛，上至颠顶，痛从左太阳起，延及石太阳、右颐及耳并脑后，右鼻不通（李师云：可用辛夷、荆芥），胃中泛泛欲呕，口苦吐酸（又云：可用左金），月事四月不至，脉细弦数，舌苔黄腻。此系少阳木火上升，犯胃及肺也。拟抑木和中法。", "16566": "复诊：头痛稍缓，胃中泛恶较平，据述头痛甚于午前，夜分不甚，此非阴虚头痛，乃少阳木火上升也。怀麟四月，正手少阳相火养胎之候，春令木火用事，又值少阳相火司天之运，「火曰炎上」，故犯胃则作恶，犯肺则鼻塞且衄也，脉仍细弦数，舌仍黄腻。拟清泄少阳之火。", "16567": "再复：头痛已愈，胃逆亦平，惟皮肤时痒，搔之微觉燥而板木，此血分素亏，而少阳风火余焰未熄也。右鼻仍塞，恶闻厨房煎熬气，此肺气不宣，想前此感冒、咳呛时清泄未净也。舌腻已退，脉弦滑。拟以轻剂宣上焦余热，再议滋养。", "16568": "（案17）张韶九，山东青口人。心肾不交，夜不成寐，寐则遍体为之不适，时患溃泄，脉两手皆弦。以心脾肾兼治。", "16569": "（案18）王，右。寒热，胸闷，腹痛，齿焦，舌白腻而厚，不食不便，脉右数左伏。此湿温重证，故以辛凉开泄。", "16570": "复诊：左脉伏略起，右数，齿焦亦退，舌白腻转淡黄，中有裂纹，而胸闷腹痛稍舒，不食不便依然。湿温重证，郁热未泄。仍以前法出入。", "16571": "（案19）黄楚翁，乌镇人。自前月感冒后，屡咳不已，致失血，音嘶，鼻时流涕，咽痛，咳甚于夜，脉两手皆数，右寸尤甚。此肺有留热，久咳伤阴。拟以清润肺经。", "16572": "复诊：投清润肺经之剂，血止，夜咳不甚，咽痛稍减，脉数渐和，惟音不响亮，流涕如故。由服辛温开泄太过，肺阴受伤，不能还复。以滋养肺金。", "16573": "（案20）金鸿翁，本城人。朝食暮吐，完谷不腐，二便俱秘，脉软，右关尤甚，舌淡。此关格之渐也。", "16574": "复诊：投温补辛通之剂，胃反已止，大小便亦通，脉迟而软，右关略起，畏寒，胸脘时痛。仍以前法出入。", "16575": "（案21）王先生，本地人。痰湿郁滞，现交夏令，正湿热郁蒸之时，口苦，纳减，神倦，头晕，耳聋，鼻塞，大便艰，脉涩，舌黄。治以辛开。", "16576": "（案22）徐，右，菊堂夫人，公义码头芝麻作，川沙人。素体阴亏，兼以情怀抑郁，五志之火燔灼于内，证见寐中盗汗，汗出指麻肌冷，掌心灼热，日晡发热，肌肤亦灼，头晕，口苦，胃减，便艰，舌根黄腻，脉两手细数。种种皆阴液亏损之征。拟以毓阴清热、养营固卫为治，宗仲圣黄连阿胶汤法加味。", "16577": "（案23）席，洞庭山人。热郁湿中，不能外达，口渴不引饮，泛泛欲呕，头痛，发热，气急，脉数而濡，舌白而润。急宜宣泄上焦气分。", "16578": "复诊：体虚感邪，湿热蕴结于心肺之分，壮热气急，渴不引饮，胃中泛恶，懊𢙐，大便不行，小便短赤，舌转微黄而不润，脉来数甚。急以辛凉开泄中上二焦。", "16579": "（案24）李干臣，宁波人，抛球场汇安洋庄。暑热客邪迫血妄行，倾盆盈碗，色紫而厚，咳呛，血即随之上溢，如火燎原，不可向迩，胸闷，胁痛，肌肤灼热，目闭，气急，脉弦数大。势来凶暴，急以竹叶石膏、桃仁承气合犀角地黄复方以救之。", "16580": "复诊：昨投大剂清热通瘀，呕血已止，胸闷亦开，惟咳呛时作，唇口干燥，余焰尚未熄也，脉弦数较昨稍敛，舌黄腻，边紫绛。仍以甘寒清热，佐以消瘀之品。", "16581": "（案25）沈。抑郁停食致病，胸满，左侧有块，今块虽隐伏，而胸次板实满闷，胃纳顿减，病经三月，脉弦而涩。此木郁土中，失调达之性，致肝脾胃交困。木郁达之，遵经旨也。", "16582": "（案26）叶，右，池亭上人。情怀抑郁，经水不至，胸闷，气急，大病之后，元气不复，脉细数。拟解郁参以育阴。", "16583": "（案27）顾，邓村人。酒客湿蕴中焦，寒热得汗不解，渴而引饮，胸闷，小便短赤，脉濡数，舌垢腻堆积。湿温重证也。", "16584": "复诊：寒热已退，目黄，爪甲微黄，足跗起泡累累，脉濡数，舌黄腻。湿热充斥三焦，发越未透，宗仲圣法。", "16585": "（案28）郑，右，广东人，洽记土行。晨起登高受风，虚邪中之，即觉懊𢙐，午后陡然眩晕欲厥，现两颧色赤，愁眉不展，时欲哭泣，脉沉按弦数，素有肝疾，常患头痛。外风引动肝阳上升无制，惟怀麟六月，芳香开泄之品皆在禁例。治拟直折厥阴，毋使风火相煽，致动胎元。", "16586": "（案29）王，十六岁。痫证病经半载，月必一发，发则卒仆，角弓反张，手足扬掷，口吐涎沫。此必有痰凝聚于肝胆胞络，久则化热，热则生风。脉细紧弦数。治以熄风除痰清热。", "16587": "（案30）沈，南长兴。久嗽痰出不爽，咽中如有炙脔，喉管狭窄而时痒，头晕如在舟车中。阅前所服方，辛散燥烈已十余剂矣。肺为娇脏，岂堪受此摧残？阴液已涸，肝阳随之而上。脉细弦数，舌绛无苔。故以滋润肺阴为补救之法，如花木枯萎频频灌溉之。", "16588": "光绪丙申，伯章研究医学已十年矣，恒兢业不敢为人举方。秋杪，舍弟璋如患白喉，又兼泄泻，猝难延医。适章自馆归，诊之，身无寒热，口不渴，舌胎淡白而薄，底面微露鲜红色，小便时清时浊，脉浮涩满指。审由燥气所发，因兼泄泻，始尚犹豫，继乃恍然大悟曰：此肺移热于大肠，病邪自寻去路也。即疏喻氏清燥救肺汤，一剂知，再剂已。嗣表兄彭君厚生暨李朂丞姻丈以他病同至，章举以相告，彭君拍案大叫曰：非名手莫辨！李公亦深相嘉许。因此踵门求方者，络绎不绝，章亦不能深闭固拒矣。", "16589": "李君楚枬女，年方十岁，患燥症，红喉转白，服发散药，米饮不入口已数日矣。延余往诊：口渴，身大热，无汗，心烦，夜不安枕，舌无苔，鲜红多刺，幸有浮液，不甚干燥，脉浮大而芤。余曰：此乃燥症误表，挽回甚难。为疏养阴清肺汤，大剂频服，勉尽人事。次日遍身露红斑，几无完肤。余曰：内邪外出，此生机也。仍守原方大剂加味，每日夜尽三剂，三日而平复，续以养阴方善后。闻愈后半月，发肤爪甲尽脱，燥症误表之为害，有如此者。", "16590": "李氏子，年十余岁，患干脚气，两足缓纵不能行。医者作风寒治，用五积散，益剧；或作痹症治，亦不效。病在床褥已三月矣。挽余治疗，审视：足不寒热、不红肿，亦不疼痛，舌苔如常人，口不渴，脉沉迟而涩，即照陈修园四物汤加味法，服二十余剂而愈。", "16591": "李君思澄之侄女懿娟，年甫十二岁，夏历正月初间，得春温症，先是进服表散、温燥等方，大热、大渴、大汗。延诊时，见其热渴异常，脉浮大而芤，身无汗，舌无苔，鲜红多芒刺，心烦不寐，米饮不入，症殊险恶。幸小便尚利，与《伤寒论》所云「小便利者，可治」相合，断为阴未全绝，犹存一线生机。渠家有一老人，尝涉猎医书，亦或为人举方，向余言曰：此症前此服药，不过败毒散等方，皆系普通发散之品，药未必误，而病势如此沉重，殊不可解。余应之曰：后世通行表剂，皆为寒而设，不知此乃春温，仲圣原有忌表明训，奈医者不知，每以通套表药误人，遂至轻者变重，重者即死，毫无觉悟，殊堪痛恨！此症先因误表而大热、大渴，大汗，若当时即进白虎汤大剂救之，尚易痊愈。今唯热渴，犹是白虎汤见症，然如身无汗，则是阳明津液被灼告竭，不能濡润皮肤之症；脉芤心烦，舌无苔而鲜红多芒刺，则病邪已由卫而累及营矣。寇深矣！若之何？反复思量，绝无可以磋商之人。因病者系余女弟子，东家向来深信不疑，即略不辞让，为疏白虎汤去黏米，加西洋参、蕤参、沙参、花粉、生地、天冬、麦冬大剂，少佐栀、连，频服，方内生石膏一两，一日夜尽三剂。次日，患者反增出时时恶风症，初疑或兼新感，继审脉息如故，热渴略减，舌色微润，心烦亦少瘥，知其仍是《伤寒论》白虎汤中原有兼症，仲师断不余欺，促其恪守原方，日夜进服。再二日，各症始十愈七八，举家相庆；余亦私幸此药幸胜病，免遭妄议，否则是非黑白，伊谁辨别！又窃喜病家坚信，不摇旁议，故得尽挽回手段，克奏肤功，否则虽有圣智，无能为役。嗣后减轻分量，再进甘寒养阴药饵，不犯一毫温燥，计三十余剂，各恙悉捐。唯如云之鬓发，手一抹而盈握，浅者纷纷堕地，皮肤飞屑，如蛇脱然，驯至手足爪甲，亦次第脱尽，久而复生。可见温病误表，真杀人不用刀矣，而世乃竟有行医至老，不知温病为何症者，谓之何哉？", "16592": "从母邓孺人，年五十时，因嫁女积劳，忽患类中风症，满面青黯，痰涎如潮，从口奔流，顷刻盈盆，手足不仁，精神恍惚，遍体津津汗出，医者用参、耆、归、地等药，病日剧。余闻，自馆归，诊之，脉浮大而缓，按之无神，即告其家人曰：病系阴寒大症，非大剂干姜、乌、附辛热之品，不克挽救。因所现各症，显系阴霾滔天、阳光将熄之候，若服归、地等药，是以水济水也；即参、耆亦不可用，因其柔润多液，难免不助桀为虐，故仲师回阳方中，每屏除不用，是其明证。即疏真武汤，嘱其不避晨夜，频频多服，或有转机。奈其家人以与前药大异，又非世俗所谓补药，狐疑不决；余再三逼令进服，始勉强煎服少许。次晨病如故，余即改用黑锡丹。至夜分，两次吞服计百粒，分量约三钱，其明日晨后询知痰涎已不上涌，汗不出，脉亦略平，足见黑锡丹之功效，神而且速，余正拟用通脉四逆汤再送服若干，必可转危为安。适延先此主方老人至，谓痰涎任其涌出为善，不宜引之内返，致留邪为患，疏方仍主参、耆、归，地。病家因其年老，阅历既多，方必不错，敬谨信服，且谓黑锡丹多系峻药，断难再服。余以年辈不敌，虽具热肠，奈孤掌难鸣，只得忍俊而去。嗣闻痰涎复如潮涌，神思日益昏愦，不旬日而没，惜哉！后以方质之彭君厚生，即奋立大言曰：冤哉，黑锡丹！使当日我能赴诊，必保无虞。随又转告余曰：勉之毋怠，从古名医之被冤者何限，此特其一端耳！为医者但当尽其在我而已。余唯唯称善而退。", "16593": "从伯母周孺人，躯干硕伟而肥，年七十时，患类中风症，四肢不仁，潮热，身微汗，面色青滞，时时震动，咳嗽多痰，语言艰阻，脉浮大而缓。适余自馆归，趋候起居。其子鲁卿兄，素业医，年逾五十，欢迎就诊，诸从姊五人，先后归宁，咸聚一室，叩余病势能否挽救，请为立方，医药各费，均由我姊妹担任，不以何问。余应之曰：可治。但此当由鲁兄作主，余虽有妙方，恐未必信任，即信亦断不坚，恐中道变更，功败垂成，事终无济，谁任其咎？鲁兄闻言，即从外跃而入曰：老弟谓此等大病，可以治愈，岂非神仙下凡。吾为人治病已三十年，即某老者年将七十，生平阅历极多，都未见有痊愈者，如本家某前辈、某女前辈，皆老弟所目击，虽不即死，恒痿废数年或十余年而死。况吾母年已七十，较各前辈之年五十或六十岁而遘疾者，尤当重视，老弟乃轻易言之，岂非欺人！吾因鲁兄盛气相加，乃徐徐答复曰：老兄所言，丝毫不爽，但是古今以来，方书所载疾病，若者死，若者可治，除南阳圣训成为铁案外，其余多未可据为定论。老兄习而不察，唯执所亲历所目睹者断之，则失之远矣。弟近来博考医书，间或为人主方，窃恐为晋唐以来方书所欺，弃短取长，非无一二心得处。现在伯母所患各症，弟谓可以望愈者，心中确有几分把握，非一味卤莽，但不得老兄真诚认可，又不为旁人所摇惑，弟亦不敢著手。言次，适七十老者从伯父放亭公入，询知各情，即命鲁兄曰：凡人疾病，总以能治愈为贵，况于父母。尔母之恙，尔自问不能救治，正当博访高明，勉图万一，今琢侄毅然任治，医药费又不尔问，即当专诚请其定方，徐希后效，尚何争执之有！于是举家欢悦，鲁兄亦欣然命纸笔属余主方，自矢不参异议。余以馆事未便久延，立疏两方：第一方系黄耆五物汤加二陈降痰等药，先服三剂；第二方即六君子汤加姜、附等味大剂。因告鲁兄曰：方内凡温补品，可以择宜加入，唯熟地切不可沾唇。并嘱其家人晨夜煎服尽三剂，少必两剂，许以守服两旬必愈。果如期而平复。愈后十年，算逾八秩，以他疾终。嗣后此症经鲁兄治愈者极多，辄一一告余，自鸣得意，亦殊悔觉悟之不早。今录此案，恨不起鲁兄而质证之。", "16594": "余在李芹芳别墅教授时，其戚彭君禄德，年六十矣，素有哮症，日甚一日，平日俭啬，不肯服药，后益剧。挽余诊之：脉三五不调，知其不治，姑以平剂予之。阅数日，晨后延他医诊治，谓脉甚善，断无他误，并告余，促复诊，余却之。奈主人守候甚殷，强应之。见其病症如故，毫无善状，切脉果三部调和，大异前日，心念六脉相会，死在即日。诊毕，旁人究问若何？余答曰：脉固佳，然而余不能立方。主人曰：脉既佳，当可不死，何却之坚也？余曰：此中妙理，一言难尽，且俟明日再商，若必服药，可暂用独参汤。主人以余之坚决，即用他医药方，至其晚二更而殁。甚矣，脉之欺人也！然在高明，则无虑此。", "16595": "余戚李君寿彭之内政萧氏，素孱弱善病，甚至日夜咳嗽，潮热自汗，夜不安枕，脉微数不可按指。延余治疗，知其不治，再三辞却不可。一日脉露雀啄形，遂直告之曰：疾万无瘳理，且命在数日，速备肩舆送余回。主人犹不许。乃嘱其赶用关东鹿茸三钱、丽参三钱，蒸服。次早，脉略平，不见雀啄形，但无神耳。晨后余辞去。李家离余家仅十数里，嗣闻延医满座，谓脉非死象，反以余言雀啄为非，许以可治。岂知余去未二日而殁。窃谓脉即雀啄，以服参、茸而暂平，即上案所云会脉之类，如灯光回焰，顷刻即熄，医者不知而为所欺，亦不考究之甚也！", "16596": "从叔多昌，当四十余岁时，初患大便不利，医者每以滋润药服之。久之小便亦不利，肚腹饱胀渐上，胸膈亦痞满不舒，饮食不入，时时欲呕，前后服药已数月，疾益剧。最后有一医谓当重用硝、黄大下，连进三剂，大小便亦闭塞不通，身体益困疲不支。余适自馆归，两家距离半里许，促往诊。见其面色惨晦、骨瘦，起居甚艰，舌苔厚而灰白，切脉沉迟而紧。呼余告曰：自得疾以来，医药屡更，而势转殆，吾其不起矣！即命家人将先后服方逐一送阅。余曰：药均大错，幸而最后所服硝、黄，未至腹痛泄泻，否则必无今日，然而危矣！多叔骇问曰：药乃如此错乎！当疾初起时，非但医以为火，余心中亦自以为火，有火服硝、黄，正是对病下药，未泄泻者，窃疑药力未到耳。余笑曰：否否，此症药与病反，诸医无一知者，何怪老叔。迄今图之，病虽危险，尚有方救，但恐老叔不能坚信，摇于旁议，中道变更，反使余代他人受过，则不敢举方，以于事无济也。多叔曰：吾自分死矣，他医之方，试之殆遍，今尔为吾立方，不论何药，死亦甘休，断不致听他人异议，在他人亦从何置议？遂疏方：乌附一两五钱，北姜一两五钱，老生姜一两，粉甘草一两五钱。写方未毕，多叔曰：如此猛烈热药，分量又极重，入口岂能下咽？余曰：入口不甚辣，后当自知，可无赘言，嘱其煎成冷服，每日当尽三剂，少必两剂，切勿疑畏自误。窃窥多叔犹有难色，即促速购药，余当在此守服，保无他虞。顷之药至，即嘱其子用大罐多汲清水，一次煎好，去渣，俟冷，分三次进服。究以疑畏不敢频进，至夜仅服完一剂，次早呕少止，膈略舒，可进糜粥，是日服药始敢频进，尽两剂。其明日，呕已止，胸膈顿宽，索糜粥，食如常人。余因语之曰：今日当不复疑余药矣。即应声曰：甚善甚善！当频服求速愈。余因馆事未便久旷，病根深锢，恐难克日收效，又于原方外加半硫丸二两，每日清晨用淡姜汤送下三钱，分三日服完而归。归后第四日，天甫明，即遣人召，入门，握余手曰：得毋骇乎？余乃示尔喜信耳！自相别之次日，见先日服药三剂，吞丸三钱，毫无热状，腹胀亦稍宽舒，食量加，体愈畅，除服汤三剂外，遂将丸药之半分三次吞服，功效益著，其明日又如前汤丸并进，丸药完矣。今天未明而腹中作响，似欲更衣者，即命小儿扶如厕，小便先至，大便随出，先硬后溏，稠黏不断，顷刻约半桶，病如失矣。所以急于告者，使尔放心。即留晨餐。多叔早废书，性聪明，通达事理，席间问余：此症究何缘致之，前此许多医药，何以日剧？贤侄方为向来所未经见，何以如此神效？愿闻其详。余曰：兹理深奥，即粗知医者，尚难语此。即承下问，请浅浅取譬，即得大要。人身肠胃，犹人家之阴沟，胸膈犹堂室然，疾系内脏阳气式微，犹之天寒地冻也。试观冬月，人家阴沟冰结，水道不通，求通之法，必俟赤日当空，自然冰释，此理妇孺咸知，医者反茫然罔觉。初以润药，是益之霜露，则阴沟冰结愈固，无怪二便不通，肚腹满胀也；继进硝、黄，是重以霰雪，阴沟即不通，层累而上，势必漫延堂室，是即阴霾上逼，由肚腹而累及胸膈，遂至咽喉亦形闭塞，时而作呕也。今余以辛温大剂频服，使锢阴中复睹阳光，坚冰立泮，获效所以神速。多叔掀髯抚掌曰：然哉然哉！遂为立通脉四逆加人参汤善后。别后一月复见，迎笑曰：前此大病几死，微贤侄必无幸矣，可称神技。然而当日谤书，何啻三箧。余曰：侄固知之，幸吉人天佑，不辨自明矣。", "16597": "族侄孀媳某，年近四十，先患大便不利，医者与玉竹、麻仁、牛膝等药，驯至小便艰涩，久之月事亦不通，身微热，已五阅月，腹满胀，胸膈时痞时宽，饮食减少，困倦嗜卧，更数医，率用滋润破气及行血之品。一日肩舆至余馆所迎诊，察脉沉迟而涩，舌苔湿滑而暗。心念疾本阴寒，今因误药，由气分而累及血分，气血交并，药当气血并治，才能有济；继悟气为血率，气行则血行，毋庸多惹葛藤；倘气治而血不和，转方调血，正自易易，遂断定单从气分斩关夺隘。疏方用大剂通脉四逆汤冷服，嘱其每日必服二剂；并用半硫丸二两，分作七日，每早食前淡姜汤送下，许以服完即愈而去。嗣后不十日，遣丁来云：药完而疾愈，请善后方。即授通脉四逆汤加人参，令其守服十余剂；后余以他事至其家，云后方仅服十剂，即平复如常云。", "16598": "脉理之奥窍，甚难言之，吾自究心医理以来，不敢以脉自炫，人有问者，辄虚心谢之，而其中妙处，要有不可思议者。友人彭某延余治疾，偶谈及妇女娠脉及分别男女，中有一人喜诙谐，谓医者未拈脉时，必先问其夫若何？次问前此是否生育？或先有儿而岁月若干？月事按期否？种种考察，则心中便有几分把握，谓其得之脉，毋乃欺人？余曰：君言虽属笑谈，确是题中应有之文，深合医理，至谓脉尽欺人，则殊不然，勿论其他，请就目前事实论之。乃低声告曰：今晨令戚本是寡妇，脉有疑义，幸余先已问明，若不知而妄言，岂不自招唾骂？其人笑曰：君得毋认作孕脉乎？余急摇手曰：否否，毋妄言。令戚外感最轻，与脉不合，医者即当知通变，不可固执，君前言本系嘲医，弟则引为训医妙论，故能自得师者，在在可取益也。后数月，以公务复聚，私相告曰：君脉学可谓精矣，敝戚某寡妇，近日果产一儿，尚记忆否？余曰：微君言，几忘之矣，亦增长知识之一助也。", "16599": "余在李家教授时，有一医士曾君过访，谓昨诊某妇人脉，似代非代，不解何故，不敢举方，已嘱其夫延诊。阅日其夫果至，云拙荆现无大病，但饮食不善，身体倦困贪睡，医者以脉歇至，多不敢用方，或有以生脉散脱责者，请驾示方，以释疑案。即往视之：脉果流利中时一跌，沉吟久之，主人具纸笔促疏方。余曰：勿药善。其夫亦惊疑，再三请方，余仍曰勿药善，后当自知。其夫即曰：月事不来虽已两月，此乃前此惯弊，未可以为孕也，况脉歇至，前后医者同然一辞，世岂有孕而歇至者乎？余曰：孕脉歇至，古有明训，况人身脏腑经络，一遇痰饮瘀血结毒及饮食停积，脉多歇至。妇人胞中，本来空洞，一旦胎结，气血阻滞，即形此象。《金匮·妇人妊娠篇》亦有胞阻之文，特医者不察，大惊小怪，殊为可哂！即如令政经断两月，前非孕而今孕，亦理之常，无足怪者。嘱以美膳调养，切勿乱药。后又两月，其夫走告曰：孕果验矣。乃知医术固非粗心人所能领悟也。", "16600": "邵阳周某，年三十，一日肩舆就余求方，云患风症，发作无时，屡医不效，出方阅之，皆普通去风药，令人喷饭。据述风作时，手足瘛疭，面皮震动，头晕眼花，猛不可当，风息则但觉口苦头晕、手足顽麻而已。审其面色如醉，舌苔黄厚，不甚燥，尖露红点，切脉弦数。即授《金匮》风引汤，以便泄风止为度。阅半月，以书来云：服药二剂，即便泄风止，后屡发暂轻，药比有效，惟病根深锢，不时发作，恐非佳象，恳再赐方善后。余乃疏黄连阿胶汤予之，服十剂，不复作矣。", "16601": "刘某之子，年五六岁，随母寓舅氏李家，先患泄泻，李戚曾医士诊之，继转慢惊风。李嘱曾挽余同诊，下利清谷，口不渴，身热微汗，舌苔灰白厚滑，目上视，气喘，手足躁扰而厥，切脉沉弦而劲，余难之，谢不主方。李家以其甥也，恳请再四。乃主附子理中汤加吴茱萸大剂冷服，嘱其不避晨夜进服，勉希万一。次日其母舅以既进温补大剂，即取关东鹿茸入药并服。又明日，疾大瘳。其父某自家至，云：尝见医士治风，必用勾藤、蝉蜕、僵蚕等味，兹独屏绝不取；数岁小儿，以温补大剂投之，将来必患别症。曾医闻而愤甚，踵门以告。余曰：恩将仇报，古今同慨，非独医也。相与大笑而罢。", "16602": "余与从兄念农，当光绪末年，同在李家教授，距离半里许，其室朱满妹，时年三十，一日肩舆至馆，云患气痛已数年，医治益剧，时值冬月，怯风异常人。询知胸及背胁牵痛，头重不举，手足酸软不温，面色黧黯，舌苔湿滑而厚，时时欲呕，脉沉迟而弦紧。予瓜蒌薤白半夏汤不应，进人参汤亦不应。乃用乌头赤石脂丸并入蜜作汤冷服，痛稍减，即嘱其相机递加分量，连服不断，以疾愈为度。后两月为夏历新正，余时家居，复肩舆抵念兄家就诊，云乌头、附子已增至每剂二两，服药时毫无痛苦；但停药三四日或五六日，疾又作，根未拔，故再请方。余为改用生乌头二个，计重二两，入前汤内，以清水七大碗，煎至四大碗，俟冷，分七次或八次，渐次增加进服。奈从妹以病苦贪速效，又以曾服附子近二十斤，有益无害，心信坚，胆亦壮，遂取进三分之一，约至二句钟，不见变异，续进三分之一。时天已晚，乡人傩，尽室观灯，独从妹在室，忽面如火烘，手足顽痹，口中麻，知药力发作，强忍之，不令人知，拥被而卧，约一句钟，身渐渐汗出。迨观灯者返，则笑语曰：吾病今其瘳矣。次日促诊，告以先夕各情，并述今早诸病如失，后当不复作矣，请疏善后方，为疏理中汤加附子，并令以温补美膳调养而痊。后念兄以症奇方奇，询余曰：阅历多矣，从未见此等方并大剂者，岂他医皆不知耶？抑知之而不敢用耶？余曰：唐宋以来医家，多以模棱两可之方试病，又或创为古方不可今用之说，故《内经》之理，仲景之方，几成绝学，间有一二卓荦者，恒倡而无和，道阨不行，亦如孔孟身当周末，终于穷老以死也。医者治病，必先炼识，一识真病，一识真方。仲师之方（经方），即真方也，识既真则胆自壮，一遇大病，特患病家不坚信耳，信苟坚，除不治症外，未有不愈者。念兄唯唯称善，并勉将来。念兄生平孝友好施与，长余八岁，共笔砚最久，常师事之。死之日，乡人谥之文惠，曾嘱余叙为谥议。今录此案，何禁池塘春草之感也！", "16603": "外科必识阴阳，方能为人治病，否则药与证反，或杂乱无纪律，势必轻者变重，重者即死，害与内科同等，不可不慎。从兄念农之长子莘耕，素羸弱，年十岁时，得项疽。外科用药内服外敷，溃久脓尽，流清汁，更以凉药服之，身冷汗出，困顿不支，脉微弱，不可按指，为疏四逆加人参汤，大剂冷服。三日，诸症悉平，疮口清汁转脓，改用阳和汤加附子而瘳。", "16604": "族侄某，父早世，素不率教，亲属皆厌弃之。一日腹旁生疽，从未用药，久而溃烂，脓尽，清汁泫流不断。适余自馆归，匍匐求医药，审视面色黧黯，舌苔湿滑，脉弱无神，心念余虽识病，望瘳殊难，姑以阳和汤令小儿辈给药三帖，命其分三日服完。嗣后旬日，忽来报曰疮口已敛，遂不药而愈。可见药症相对，其神效洵匪夷所思矣。", "16605": "先世父封臣公，少年患吐血疾，以善保养，不药而愈。生平常以节欲食淡教人，体虽清羸，卒少疾苦。年七十时，患五更洞泄，章尝劝服补肾温剂，不听，日益居。属家人煎送补剂，坚却之不顾，曰：死生有命，药物何功？并荤腥亦不御。一日昏迷不醒，手足痿废，溲便不禁，日更中衣六、七次，面目黑气弥漫，脉浮大濡缓无神，时而歇止。诊毕叹曰：症已不治！姑以参汤徐徐灌之，尽二盏。次日，口中喃喃郑声，语无伦次，问之不省。亲眷戚友问候者，皆计日候凶耗。章见药饵可入，胃气未绝，即以温固脾肾、扶养气血大剂，并辅以鸡肉汁和糜粥，渐次增加。后竟每日服药二大剂，糜粥尽三大碗，以为常，逾一月，诸症悉退。略省人事，以药饵进，即坚拒之，遂止不复沾唇。久之，平复如初，年逾八秩而终。当疾剧时，戚友距离较远者，咸谓死在旦夕，以久不得耗，疑为秘不发丧，岂知转机殊出意外。窃思药饵为治疾之需，有疾时资之治疗，则疾去而元气复固也，而世之贪生畏死者，每倚为日用之常膳，一遇疾病，必至无药可医。先世父之所以获瘳者，妙在平日不进丝毫补品，且素食日多，故得疾虽异寻常，而药物灵验亦异寻常。愿以谂世之留心养生者，并语医士，如遇斯人斯疾，勿拘常例而轻弃之也。", "16606": "周子某，年约三十，患水肿已半年，医药遍试，日剧。延诊时，头面、四肢、腰腹、胸背皆肿如瓜形，僵卧床席，不能转侧，皮肤胀痛异常，即被褥亦不能胜受，气喘，小便不利，脉沉而微。诊毕，就室，呼主人曰：古人言水肿死证，见一即危，如缺盆平、掌无纹、脐突、足底平皆是，今皆兼之，况皮肤痛不可支，有立刻破裂之势，须防外溃，喘满又恐内脱，虽有妙方，必无幸矣。即辞不举方。主人及病者皆曰：疾不可疗，命也，但愿得尊方入口，死亦甘休。余闻而怜之，即疏济生肾气丸而去。越数日，来告曰：药完二剂，小溲如泉，肿消大半矣。可否再服？嘱其更进二剂，病如失。嗣以六君、八味丸汤并进而瘥。甚矣，病机之难以常理测也。", "16607": "人身阴阳，互为其根，一有偏胜，百疾生焉，故《内经》曰「阴平阳秘，精神乃治」。然亦有素禀偏盛者，难以一概论也。先从伯父放亭公，素禀偏阳，少年患脱肛，必进硝、黄乃效。自后或数年一发，或十数年一发，无不皆然。迨七、八十时亦然，平时无他疾，脉沉潜不露。临终时，忽头晕难堪，即牙关紧闭，舌喑不言，唤之不省，手足痿废，滴水难入，脉细欲绝。其子鲁卿从兄问曰：有方治否？答曰：阴竭矣，虽有方，必无及，况滴水不入，其奈何！鲁兄曰：何所据而断为阴竭？余曰：证大类中风，然细察口无涎，鼻无涕，目无泪，身微热而无汗，即此以推，便知头晕等症，皆由阴竭使然。且面露红光，足厥冷，亦是孤阳上泛见症。《伤寒论》曰「小便利者可治」，谓阴未竭也，医者当活泼看去，推类以尽其余，斯为能自得师者。即试探下身，果无溲便，阅日而没，并易箦时亦无溲便痕迹。医为人之司命，对于阴阳偏盛之体，先事补救，或可延寿算于无形，然而有命存焉，盖未可强也。", "16608": "刘氏，妊已及月，一日腹胀痛，下血水甚多，胎寂不动。延诊时，见其精神困顿异常，自汗不止，舌苔灰白，脉浮大而迟。主人请催生方，余曰：未也，切勿乱。为疏气血补品大剂。阅日，人平复如初，胎始动。服药又两旬，产一儿，才半日而殇。此症先因母体孱弱，以致胎元不固而崩漏，胎既受伤，母命亦危，使误认为正产，而以催生药强迫之，势必两败俱伤，惟补养以培母气，则胎自然受益，听其安可也，产可也。医者可不知所从事哉。", "16609": "李某，年二十余，先患外感，诸医杂治，证屡变，医者却走，其父不远数十里踵门求诊。审视面色微黄，少腹满胀，身无寒热，坐片刻，即怒目注人，手拳紧握伸张，如欲击人状，有顷即止，嗣复如初，脉沉涩，舌苔黄暗，底面露鲜红色。诊毕，主人促疏方，并询病因。答曰：病已入血分，前医但知用气分药，宜其不效。《内经》云「血在上善忘，血在下如狂」，此症即《伤寒论》热结膀胱，其人如狂也，当用桃核承气汤。即疏方授之，一剂知，二剂已。嗣以逍遥散加丹、栀、生地调理而安。", "16610": "周某，年三十许，患伤寒，医药遍试不痊。适余以戚病往视，遮道挽诊，云刻已外症毫无，但精神恍惚，不甚省人事，时欲就卧房溲桶，以面向之，禁之即大叫，伸拳击人，疑为祟凭，僧巫祈祷，几无虚日，脉沉结，溲便如常，舌苔微黄而晦。余以症疑未审，约以明日至余戚家取方。戚怪余至之晏，具以告，戚又疑要厚礼方肯给方。余曰：非也，症未审，故不予方。次日，其家遣人索方，授桃核承气汤，二剂而愈。戚以症奇方灵就质，余曰：《内经》云「血在下如狂」，仲景亦曰「热结膀胱，其人如狂」，是即伤寒蓄血症也。此症恍惚不省人事，及大叫伸拳击人，即如狂之见症。人身小便，为通瘀妙品，妇科产后，常用以治瘀血，病者时欲面向便桶，意其内既有瘀血，其脏腑必有窒碍难言之隐，故借吸入溲气以宣其郁。医者读古人书，以参考病人见症，岂必一一吻合，当如作八股文，从旁面对面反面著想，则题理、题神，昭然若揭，毫无遁情，所谓读书不可死于句下也。余本《内经》之理以探病原，即用仲景之方以铲病根，获效所以神速，无他巧妙也。", "16611": "黄氏妇，适月事来，因感寒中断，往来寒热，少腹及胁下疼痛如被杖，手不可近。舁数十里至余馆求诊，舌苔白而暗，脉弦数。审即《伤寒论》热入血室，其血必结，故使如疟状也，与小柴胡汤加归、芍、桃仁、红花、荆芥炭两剂，大便下黑粪而瘥。", "16612": "快溪毛生，年十余岁，一日，肩舆至余馆，形色瘦暗，须扶掖乃能行。问之，则曰：每晚发热，汗出，左乳下痛，夜不能寐，卧病学舍，已三月矣，医者皆谓虚痨，治愈剧，未审有方救济否？脉之弦结，舌苔淡白。即令解衣视乳下，皮色如常，又不觉冷热，以手按之则愈痛。余曰：痛处是否受伤？曰：未也，惟三年前与同学戏，为其推压案角，正著乳下，比觉痛，以药敷治而愈。至今年则未受何伤。余曰：病根在此，瘀血内伏，不发痈，即成痨，迄今图之，保无他虞，但余方不可令他医见，致生阻挠。授小柴胡汤加归、芍、桃仁、红花、荆芥炭、元胡，青皮，嘱其服药后，以大便下尽黑粪为度。逾一月，以书来谢曰：药完三剂，下黑粪甚多，病如失矣。", "16613": "聂君诗伯，与余共事久，素耳吾医名，每思延诊其母，不果。后以公务同住县城，适以事回家，挽余迂远过诊。据述年已周甲，生平善病，药饵未曾稍离，但多系耆、术、桂、附温补品，克伐则不敢尝试。审视肌肉大退，面色惨白，身弱，行动不能自持，咽喉干至胸臆，舌色淡红而干晦，语声不扬，大便艰阻，小便短涩，饮食锐减，夜不成寐，脉弱而散。诊毕，退却客室直告曰：疾不可为，乃五液俱竭之症，毋庸服药，无已，当以吉林清水野参，或辅以西洋参熬膏，不时咽下，日间饮食，可以海参、燕窝、炖老鸭淡清汁吃之，庶几多延时日。至耆、术等药，虽属补品，与症不对，徒然助桀为虐，亟宜屏绝。聂君深以为然，后闻不数月而没。窃思聂母之疾，难免不因温补过当所致，余以既往不咎，前方又皆毁弃不存，只得即事论事。世之溺于温补，不择而施者，当知所反矣。", "16614": "医药不当，虽参、耆、术、草，皆能害人；医药苟当，即麻、桂、硝，黄，亦为上品；知其病，得其方，而又无太过不及之弊，斯为上乘。余戚刘君叔岘，年几五十，素有烟癖，误信医者言，肆进姜、附毒烈之品，不知节制，遂至两目俱盲。肩舆延诊，见其神思亦不爽慧，当就床吸烟时，凡接枪斢边向背坐卧之类，概不省记，必旁人呼唤挟持，方能如法；舌无苔而干晦，脉微细无神。余曰：他人但盲于目，君则并盲于心矣。病者亦不能言其所以，但请示方。余乃告其家人曰：目盲乃肾精为热药所劫，以致水阴不能上济也，至神思昏乱，则心阴亦并受伤，虽有良方，亦难救济，自后当屏绝药饵，但以海参、燕窝入老鸭内，炖取清淡汁饮之，庶于目光心神，有益无损。去后数月，闻其不远一、二百里，以重金延眼科专家匡某者主方，用五积散，云服百剂，保一目复明。余即寓书亟止之，已无及矣。继而其家人以告，疾革时，已服五积散八十剂。窃疑病者他脏尚固，故能久支，否则数帖间，必危状百出，奚待八十剂而后死。上症一误再误，卒以至死，病家无识，毋足责也。独怪冒称医士者，敢于妄言欺人，敢于杀人不用刀，殊堪痛恨！故著之以为医戒，并儆病家毋轻信瞽说也。", "16615": "自西洋牛痘之法行，至灵至稳，真小儿慈航宝筏，较之痘苗纳入鼻孔者，奚啻霄壤，即前此痘科方论，都可废而不存。惟是时行水痘挟疫者，不论其人已否种痘，沿门阖境，皆能传染，轻者清解即已，重者幸而不死，迄其久而愈也，满面瘢痕，殊不雅观。夫痘疮结粒，不论身体何处，皆能散布无遗，至其结靥脱痂，遍身如常，而面上独留瘢痕，其中所以然，尝遍考古今方书，并未言及。若以询之时俗医生及痘科专家，则更无从问津。盖疫痘多由淫毒传染，其见症轻重，每随其人阳气强弱及已否出痘、内毒微甚为转移，阳气强而未出痘者，热毒重；阳气弱而已出痘者，热毒轻，自然之理。人身先天之毒藏于肾脏，如无外邪引导，尚伏而不动，一遇疫气侵入，则肾中伏毒，乃由肾系而腠理，而肌肉，以达皮肤，内外合邪，毒愈澎涨，故善治毒痘者，必宣泄使之外达，不可内陷。又凡起胀、灌浆、结靥、脱痂等候，皆津液之作用也，津液足则自无干结倒靥之弊，面上瘢痕，从何发生？《内经》云「阳明之脉荣于面」，燥又阳明本气，一旦重以淫毒，津液消灼，不能充润面部肌肤，瘢痕所由来也。仲师一部《伤寒论》，总以存津液为主体，医者诚能扼要以图，当于痘粒起胀、灌浆之时，相机施以白虎汤加入甘寒大剂，少佐苦寒等品频服，使淫毒锐减，继专以甘寒濡养，则阳明之津液灌溉有余，不致受伤，迄夫结靥、脱痂，自然肌肤充盈，毫无瘢痕矣。余尝持此以语同道，率未能实行，多由学识不能贯彻，以致疑畏误事。嗣后亲治数人，信而有征。一得之愚，不敢自秘，故表而出之。或谓大剂凉药，难保痘症必无虚寒。则应之曰：医必审症用方，岂可混施。若果系淫毒疫痘，断未有骤变虚寒者，高明家自能识别，可毋赘云。", "16616": "内子年五十时，患舌裂作痛，无苔，色紫暗不润，口渴喜饮，脉缓，略带弦象。余因其体羸，素偏血虚，又以舌乃心苗，如心、肝、脾补血、活血，兼清血热等方，进服殆遍，又试服他医数十百方，前后三年，毫无效验。幸饮食尚可，惟咸辣不能进口，因医药无灵，已置之不理矣。值余以公务久驻县城，一日因臂痛，请鲁卿从兄举方，用当归三钱，川芎三钱，酒芍三钱，片姜黄二钱，桂尖四钱，独活三钱，北辛一钱，台乌三钱，秦艽三钱，续断三钱，广皮二钱，甘草一钱，香加皮一钱。服三剂，臂痛愈，舌裂痛亦如失。他日以方告，怪之，莫名所以，询之鲁兄，亦曰开方时，但注意臂为风寒所伤，故尔作痛，他非所知也。窃思舌为心之外候，而脾络系舌旁，肝脉亦络舌本。大抵内子平日，或因月事及生产，偶有瘀血留滞各经脉络，以致邪气循经上行，见于舌端，邪气进则正气退，裂痛所由来也。又舌色紫暗，口渴喜饮，亦属瘀血之见症。方中片姜黄，时医但云能入手臂，治风寒湿痹，不知为逐瘀妙品，合之桂尖、当归、川芎及艽、辛各品，更有辅正去邪之功。妇人臂痛，多由瘀血阻滞经络，或兼风寒使然，故上药双方并治，皆能奏效。兹酌定药品分量，命名消瘀蠲痛汤，并注症治，愿以质之高明者。", "16617": "九弟妇梁氏，产后瘀血未净，得外感，往来寒热，舌苔白滑，脉弦，以小柴胡去参加桂尖，一剂寒热止。后数日，腹痛，值余应戚友请外出，他医以四物汤加行气等药服之，痛益剧。余归时，询知痛处有形，手不可按，乃以四物汤去地黄，加桃仁、肉桂、大黄（醋炒）二剂，下黑粪极多而瘳。", "16618": "古人谓产前责实，产后责虚，殊未尽然。王氏妇年二十，产后四五日，患外感，寒热往来，余以小柴胡汤二剂愈之。厥后七八日，疾复作，他医进四物汤加味，益剧。复求示方，脉之沉实，日晡发热，烦躁，谵语，大便难，腹痛拒按，疏方用大承气汤。病家疑之，仍请前医就商，入门寒暄数语，即曰：产后大抵多虚，先生所示大承气汤，毋乃太峻？余曰：有此症则用此方，试取仲景《金匮》阅之便知。其人曰：古方难以今用，如《本草医方合编》，读之熟矣，他非所知。余曰：若此，则君应早治愈矣，奚待今日？其人语塞，逡巡退去。余亦向主人告辞，主人不可，余曰：既疑余方，留之何益？主人曰：即去购药，请留驾少待何如？余应之曰：可。顷之，购药者返，时正午，即嘱煎好，计一时服一茶碗，至二时又服一茶碗，迄三时，大便行，甚黑而臭，腹痛减，日晡时但微热，不复谵语矣。余欲告辞，不可，又以善后方是否再用大黄，殊难预定，乃强留一宿。次晨，见脉症已十愈八九，乃用大柴胡去大黄，加当归、生地、桃仁，二剂，平复如初。窃谓汪氏自言非知医者，合编之作，开后人简便之门途，实酿成医学浅陋之陷饼，读书未成之辈，喜其浅近，奉为圭臬，致反矜云妠之貌似，竟忘却高曾炬鸡，吁可慨矣！", "16619": "清宣统间，吾以筹备自治所长久驻县城，人以医治请者，辄却不应，故医案绝少。杨氏妇，产后两足痛如锥刺，跬步不能行。友人为挽余诊，询知痛处微热，手不可按，自产后十日得疾，已一月矣，遍治不效。脉之弦数，舌苔黄，疏方用桃核承气汤，以肉桂易桂枝，三剂，大便下黑粪而瘥。友人见余方之异人而奇验，亟思表扬。余曰：偶中耳，以后万勿说项，徒增一番应酬，致妨公务。乃止。", "16620": "安化谭君笃余，患腹脐畏寒而痛，时值夏历五月，常以火炉贴熨脐间，不可刻离。托敝本家挽余过诊：舌色红，苔黄而厚，饮食不美，精神疲倦，脉弦数，自谓曾服温补无效。余曰：此湿热而兼木郁，温补诸品，切不可沾唇，火炉急宜去之，毋助桀为虐。奈以畏冷故，不愿即去，为疏平胃散合左金丸作汤，三服，冷痛大减，始肯撤去火炉。嗣以越鞠、平胃、左金等方出入加减，二十余剂，平复如初。", "16621": "同邑罗某，与余同寓省垣，一日邀余过诊，云面上及四肢，近露痘形，想必时行水痘，未知是否？余笑应之曰：若据愚见，似属广疮。罗曰：近数年来，花柳场中，绝迹不涉，从何发生？余因其讳疾不情，权辞答之曰：此毒亦间有因厕便传染者。罗即应声：既然，且请示方，徐观后效。余曰非旦夕所能收效，即疏龙胆泻肝汤加味而去。后三月，复延诊，云前此痘疮，自服先生药数剂后，遍访省中中西名医，言人人同，因就某西医用德国六。六药针，针后遍身热胀麻木，坐卧行动，极其难堪；三日，人始苏，检视痘形，则已结靥或脱去矣。突近数日，日夜咳嗽，痰中带血，向无此弊，今若斯，当是药针所致，必非西医所能疗，故详陈缘因，请示方，免堕入肺痨一途。余曰：西药六。六吾不能知，然即其见症如此猛悍，化毒如此神速，则可推知其必合有砒石等品，大抵大辛大毒药饵，其性恒栗悍不驯，获效速而难免无弊，咳嗽吐血，必肺金为毒烈所伤。古人虽无成方，幸不才见病知源，保无他虞，切脉浮而带数，舌无苔而色红。为疏清燥救肺汤，方中人参改用西洋参，并加入丹皮、栀子、生地，三服而瘳。", "16622": "民国二年，余僦居长沙宗圣庙左侧枣园，适平江杨君鼎元患瘅疟，嘱其弟叔元君邀诊。审视舌苔黄，口大渴，脉弦数。检阅前所服方，皆杂乱无章。余曰：此疟与寻常异，非重用清凉不可。疏方用白虎汤，方中生石膏八钱，约以每日必服二剂。病者疑之，不敢频服，记两日间仅完二剂，疾不减。另用他医方，治反剧。复延诊，乃用白虎汤合黄连阿胶汤加减，进服数剂，热始退。嗣以甘寒养阴法，又十余剂，始平复如初。", "16623": "同时又有杨某，长沙人，患病数日，延余过诊，口渴，身大热，汗如注，脉洪数无伦。即正告病者曰：此系瘟热重症，非用大剂清凉不克收效，并宜速用药，不可迟延误事。病者狐疑，请为立案。即援笔草案百数十字，并疏清瘟败毒散大剂，约以日服三帖，少必两帖。去后，闻服药一帖，究疑药饵过凉，治装回家，卒以桂、附等药戕命。犹忆吾立案时，因恐人不识病源，词气何等直切分明，医家病家，都不醒悟，良可慨矣！余在医药联合会时，有工人某，患热症，势殊险恶，四肢麻痹不仁，大渴大汗，舌色鲜红，苔如积粉，耳重听，脉洪促，同事三数人，均推诿不敢举方。余曰：症虽暴，尚非败症，断不可轻弃，而任其授命他医。即用余师愚清瘟败毒散加减大剂，方中生石膏每剂二两，令其日进三剂，并以西瓜汁代茶肆饮。同事俱咋舌，噤不作声。阅三日，各症始减，知饥，脉亦略平，因减轻苦寒，加入甘寒，又十余剂而瘳。此等大症，苟一延误，变端不堪设想，然而医者虽识病用药，病家每以稀见疑畏，终为庸俗瞽说所误者，往往而然，谓之何哉！", "16624": "彭某，患下疳，溃烂不堪，跬步难移，值外科以丸药予之，保三日即愈，比索谢金而去。迨次日药发，咳嗽吐血，口破流血，牙龈唇舌皆肿，臭涎如泉涌出，米饮不入，自分死矣。延余过诊，脉之洪数，授大黄黄连泻心汤，以大便亦结，令其煎服，三剂，平复如初。甚矣！方土之惯以丹药害人，又不知讲求救误方法，仲尼曰「始作俑者，其无后乎」，正当移以持赠。", "16625": "江右黄某，营业长沙，初患外感，诸医杂治十余日，疾益剧。延余治疗，至则医士三人已先在座，正彼此通姓名间，主人即请入内。病者自云肚腹硬痛，手不可按，傍晚身微热，汗出，手足较甚，小便黄，大便不利，粒米不入口，已三日矣。审视舌色鲜红，苔黄不甚燥，脉沉实搏指，取阅前所服方，多杂乱无章。已而主人启他室引入，命纸笔请为立案疏方，并告以外间三医，皆已照办。余以病者之兄曾有一日之雅，笑问曰：主人今日实系考试医生，否则何必如此，余为人治疾，非畏考试者，但试卷甲、乙，凭谁评定？主人曰：我非知医者，拟俟各方案成立后，比较有相同者用之，暗取占三从二之义，否则质之神明，未识先生以为然否？余曰：前说揆之理想则是，按之事实则非。盖时下医士程度卑陋，率以搔不著痒无关责任之套方，自欺欺人，即有同者，难免不滔此弊；若后说则索之冥冥，殊为无谓。不如将所定三方及案交余一阅，可立为评定。有反唇相稽者，请为代表面论。主人称善，暂请先生拟定方案，照行未晚。余即取纸笔立案，并疏大承气汤方授之。主人果出三医方案请评。阅之，义各有取，然率系通套俗方，与症无涉，遂另纸逐一评判，交主人传示三医，皆无一言，相继辞去。余亦告辞。阅日，复延诊，余意其服方有效也，继乃知余去后，主人究疑药峻，另用他医方，益剧。病者亦深怨家人之不用余方，具以告。乃就大承气原方增加分量，约以连进两服，大便当行，万一不行，则宜再进，切勿疑畏而去。阅二日，仍延诊，则云昨晚药完二剂，下黑粪甚多，今晨进稀粥少许，各症十愈七八。为改用大柴胡减轻大黄，又两剂，黑粪始尽，病如失。最后仍请疏调养方。其家有西席，尝阅医书，暱就之，谓大承气证，当见谵语，此症何以无之？大承气系腹有燥屎，先生乃断为食积，敢问所以？余曰：《伤寒论》云「六七日不大便，烦不解，腹满痛者，此有燥矢」，其下又申之曰「所以然者，本有宿食故也，宜大承气汤」；又于阳明少阳合病条下云：「脉滑而数者，有宿食也，宜大承气汤」；若《金匮·宿食篇》主用大承气者甚详，不必赘述。盖宿食与燥矢，一而二，二而一，相去一间；至谵语有无，可不必拘，盖仲景原有阳明病，潮热，大便微硬者，可与大承气之文，亦不执定谵语也。此症若再延一二日，必发生谵语见鬼之症；幸而病家及时觉悟，故病者犹存一线生机；否则必至循衣摸床，微喘直视，陷于阴绝之死症，虽仲景复生，无如之何。西席至此又问曰：前三医方，似尚平稳，服之是否妨碍？答曰：药不对症，无论何方，皆能误人；况病已抵沉重，生死关头，稍纵即逝，故庸医耽搁时日，亦是杀人。西席乃拱手称曰：闻先生言，昭若发蒙。余即应声曰：微足下亦无以发余之狂言。遂相与大笑而别。", "16626": "刘某之子，年五六岁，时值夏历八月，先患寒热，医者杂治未愈，已而身热咳嗽，兼以下利清谷，口渴。邀余过诊，见其舌色红而苔白，脉浮大。曰：此正喻嘉言所谓肺热无从宣泄，急奔大肠也。即与泻白散加味，以清肺热而兼润大肠，数服而瘥。", "16627": "黄某，年三十许，患秋燥泄泻，日数十度，身热微咳。以粗阅医书，初服消散药不应，继进疏利亦不应，易以温补升提，愈剧。延诊时，形容惨晦，焦急不堪，舌苔淡白而薄，杂露红点，脉浮而虚。余曰：此等症候，从前名家，惟喻嘉言知之，有案可稽。若时医则无从问津，服药不对，宜其愈治愈乖也。病者犹疑信参半，乃命家人就邻舍取喻氏书请为指示。余为检出授阅，并告以屡试屡验，切勿疑阻自误，即照方连服六七剂，始平复如初。", "16628": "邑人周某，年近六十，以讼事寓居长沙，患咳嗽一月有奇，昼夜不能安枕，杂治不效。肩舆就诊，喘急涌痰，无片刻停，舌苔白而黯，脉之浮缓，余先后计授三方，亦不应。沉吟久之，意其阴虚而兼冲逆，姑以张景岳金水六君煎与之，已而一剂知，二剂愈。乃知其方亦有可采者，非尽如陈修园氏所论云。", "16629": "长沙陈某，年五十，患泄泻，医治益剧，已两月矣，仅余皮骨。延余过诊，肚腹不作胀痛，舌色淡红，苔白而薄，时以开水漱口而不欲咽，脉微缓。阅前方如温燥、固涩、升补，关于脾肾两家成方，服之殆遍。意其下多亡阴，以八味丸少合四神丸为汤服之，不应。改用景岳胃关煎：熟地五钱，山药、扁豆各三钱（均不炒），炙草一钱，炮姜一钱，吴茱萸五分，白术二钱（不炒）。煎水二杯，初服一杯，即十愈七八；再一杯，即全愈。考景岳方下自注：治脾肾虚寒作泻，或甚至久泻腹痛不止、冷痢等症。陈氏修园谓于苦燥辛温剂中，君以熟地，不顾冰炭之反，便注云治脾肾虚寒作泻，陋甚。然如上症百方不应，服之竟若此神效者，其故安在？窃思方中地黄，《神农本经》云：气味甘寒，填骨髓，长肌肉。叶天士注云：气寒入足少阴肾经，味甘入足太阴脾经。肾主骨，益肾则水足而骨髓充，脾主肌肉，润脾则土滋而肌肉丰。洵属确论。后人取以蒸晒，名曰熟地，则甘寒变为甘平，以之濡养脾阴，尤为相宜，次辅以山药、扁豆、甘草之甘平，则滋生脾阴之力量，更为雄厚。而又合以吴茱萸、干姜、白术之温燥，不嫌其与滋养脾阴之品相妨碍者，盖以人身阴阳，互为其根。故《内经》云：「阴平阳秘，精神乃治」。上症脾阴不足以配阳，故温燥药百无一效；如但见脾阴不足，注意填补，而不知兼顾脾阳，亦背岐轩平秘之旨，病必不服。但其中分量，最宜斟酌，不可颠倒。尝谓仲景桂附八味，为维系肾经阳阴方。景岳兹方，于维系脾经阴阳，不期而暗合，奈见不及此。故方下所注，不知分别，名以胃关，盖取肾为胃关之义，亦未吻合。陈氏虽斥为陋，亦知其有可用处，故《医学从众录》中尝采其方，亦无发明。兹故不揣固陋，聊摅一得，并更易方名，订正药品分量，附载于后，阅者谅之。", "16630": "刘某，湖北人，一日至余寓求诊。云患呕吐清汁，兼以头痛不能举，医者率以风寒发散药服之，益剧，已逾月矣。舌苔白而湿滑，口中和，脉之沉紧。与吴茱萸汤，一剂知，三剂疾如失。", "16631": "黄某，宁乡人，先患外感，医药杂投，方厚一寸。后更腹痛而呕，脉弦数，舌色红而苔黄，口苦。余曰：此甚易事，服药一剂可愈，多则两剂，何延久乃尔。与黄连汤。某人疑余之轻易也，请第二方。余曰：不必更方，后当自知。去后三日，复晤于洋货店，曰疾果瘳矣，相与大笑而别。", "16632": "浏阳李某之母，年六十，先因感冒风寒，杂治不愈，已而大便泄泻，日十余行，腹胀痛。医者不察，概以行气消胀之品图治，益剧。延余过诊，脉之微缓，舌苔白，口中和，饮食不美，困顿不能行。其子甚忧其不起。余曰：此中气下陷，可保无虞。为疏补中益气汤，方中当归用土炒，外加固脂、益智，三剂而瘥。", "16633": "长沙王某，以年少新进，喜为狎邪之游。一日肩舆就诊，云两胯俱起横痃，胀痛红肿，跬步不能行，医以败毒等方服之，益剧。口中苦，舌苔黄，脉弦数。与山甲内消散，三剂而瘳。陈氏有女工，年二十许，姿颇妖冶，患横痃，意其必因守身不洁所致。他医先用连翘败毒散，嗣进仙方活命饮，均不应。后更胀痛，热如火燎，时以冷湿布覆之，僵卧椅上，叫号不已。脉之洪大弦数，舌苔黄。与山甲内消散，不应；乃用桃核承气汤去甘草合控涎丹加木鳖、甲珠，三服，始大便下黑臭水极多而消。甚矣，淫毒之坚凝，非峻利药不能胜也。", "16634": "宁乡学生某，肄业长群中学，得外感数月，屡变不愈。延诊时，自云胸满，上身热而汗出，腰以下恶风，时夏历六月，以被围绕。取视前所服方，皆时俗清利搔不著痒之品。舌苔淡黄，脉弦。与附子泻心汤。旁有教员某骇问曰：附子与大黄同用，出自先生心裁，抑仍古方乎？余曰：此乃上热下寒症，时医不能知之，余遵张仲景古方治之，不必疑阻，保无他虞，如不信，试取《伤寒论》读之便知。旁又有人果取以来，请为指示，余即检出授阅，遂再三道歉而退。阅二日复诊，云药完二剂，疾如失矣，为疏善后方而归。", "16635": "温病误表，医者十而七八；至温病而兼泄泻，则率以温补、升提杀人者，比比皆然，何者？不知病源，一见下利，遂即认为虚寒，此庸医之惯技也。长沙易某之子，年十余岁，患冬温，发热，口微渴。延余过诊，舌无苔，脉浮数。余以辛凉平剂与之，嘱其频频进服，以愈为度，不拘剂数。阅数日，复延诊，大渴大汗，脉洪大，询知主人疑药凉，三日仅用一剂。改方用白虎汤，方内生石膏八钱。主人曰：小孩子能受此种凉药乎？余曰：有此疾则用此药，切勿延误。日前之方，因未照法多服，致有今日，病既增重，则药方亦宜加重，若再迟延，必变生他症，恐贻后悔。奈主人若明若暗，犹豫不决，遂兴辞而去。阅日又延诊，余以其服白虎有效也，入门则见座上客满。主人云：日昨先生去后，药未备而病者大泻，他医皆谓前药过凉，石膏则尤不可沾唇，不已将昨所授方及以后三医方，决之于卜及乩仙，皆主先生方，故今再请屈驾指示，但症已变，原方是否可用？余曰：温病泄泻，乃内邪自寻去路，正是生机，切勿止塞，方不须改，以多备频服为要。即援笔就原方加西洋参二钱，主人唯唯。检视他医三方，或主利水，或主和脾，或主升补，不觉失声大笑。主人询所以。余曰：无他，笑三医之太无识解也，可无赘说，约以是日及晚必服完三剂，明晨当有转机。至次晨诊视，泻利止，各症减大半，乃嘱用原方再服三剂，疾大瘳；改用甘寒养阴数服，平复如初。", "16636": "漆工黄某，胸满头痛喜呕，医与发散药不愈。过余寓求诊，脉紧，舌苔白滑，授吴茱萸汤两服而瘥。", "16637": "木工王某之子，年十余岁，初因外感，医治屡变不痊。一日肩舆就诊，云现无他症，但苦两脚跟肿痛，热如火燎，不可履地。舌苔白滑，脉沉缓，与附桂八味加独活、豆黄卷，一剂热减肿退，三剂即步履如常。", "16638": "同时又有缝工李某，患症与王同，但脉沉数为异，与六味加苍术、黄柏而瘳。", "16639": "笔工邓某，当夏历五月，因外感误治，遂下痢红白，医者用痢门套方，增剧，日数十行。延诊时，言小便时黄时清，腹不痛胀，但觉满而多气，口中淡，不饮食，傍晚身微热，头重而晕，脉之弦缓。余曰：此症原系风湿，未从外解，久而化热，故见症如此，医者不究病源，一误再误，竟成似痢非痢之状。乃以胃苓汤加减，先后三易方，计十余帖而瘥。", "16640": "邑子邓某，年三十许，喜狎邪游，得淋疾，赤白交下，痛不可支，踵门求诊。脉弦滑。与八正散六剂，痛止，红白断，惟黄浊不时泫流；改用二陈加萆薢、苍术、黄柏、滑石等味而瘥。后因犯淫屡发，仍用上方加减辄效，最后以六味加萆薢、黄柏调理，不复发矣。", "16641": "曾氏妇，年三十许，患两手关节疼痛，猛不可当，日夜叫呼，闻者酸鼻。延诊时，不可按脉，舌苔淡白。阅前所服方，如祛风、散寒、疏理气血之品，服之殆遍。比以当归四逆加片姜黄，服至四剂，痛如故。继审痛处适当骨节，正所谓历节风也。人身骨节，皆筋脉交纽之处，肝主筋而藏血，断为风寒湿干于血分，阻遏气道，故尔剧痛。乃取黄耆、当归、川芎、白芍为君，辅以桑枝、杉枝、松枝、桂枝、紫苏、竹枝，皆用节，即甘草亦用节，取其以节入节。虽古无成法，然医者意也，但能愈病，明者断不余訾。方成，授主人照办，连服十剂，痛如失。窃思黄耆、当归、桂枝、白芍、川芎、甘草，具黄耆五物、当归四逆两方之功用，紫苏节则尤能行气中血滞，辅以桑、杉、松各枝节，能使关节中停蓄之风湿一扫而空，至竹枝节气味甘寒，恐其拒而不纳，以之为反佐，故于上症功效颇巨，爰命之曰七节汤。附录于后，用者审之。", "16642": "钟某，以营业自河南得疾旋返，适余住县，其友周某挽余诊治。据云两月前患疟疾，友人劝服金鸡纳霜即止；逾三日复发，旋服旋止，如此四五次，每服加多，最后左胁下及少腹内一条如臂扛起，痛不可按，延医疗治，至今不愈。审视面色惨晦，舌色紫无苔，咳嗽气喘，昼夜不眠，寒热往来，骨瘦如柴，僵卧不能起坐，饮食不入，脉细数，按之散。余即告其友曰：此症已成疟母，早治可望痊愈；今若此，虽有妙药，奈元气就绝，不能胜受，治亦无功；且宜速备肩舆送归，否恐无及。即于次日送归，抵家一日而没。按：金鸡纳霜，味苦无比，不知何药所制，每见久疟不愈者，服之辄有奇验，若初起之疟，必多反复，余常以此戒人，勿遽轻服，多不见信，如钟某者，可为殷鉴矣。", "16643": "曾君履初，患头痛，医者以疏散风寒方与之，不应。易医作风热治，益剧。延诊时，口味淡，舌苔白滑，脉浮大而缓，与补中益气汤加川芎、蔓荆、细辛，一服知，三服已。", "16644": "安徽金某，体颇肥而短。一日肩舆踵门告曰：得奇疾，医者皆不之识，百方不效，据述两胁下间微闻蛙声，或作鼠叫，咳则乳下作痛，或胸中如有热水一缕上下，顷之即散，大便不时泻水，不治自止，或呕吐清水，头或晕痛，患病至今，已一年已奇，方厚一寸，无偶中者，人皆奇之。余笑应之曰：疾非奇，但医者少见多怪，宜其见骆驼言马肿背也。脉之沉弦。即告曰：此乃痰饮作祟，惟善读仲景书者知之，非鬼非神，不必惊疑，吾有妙药，不费多金；但不可令他医见，致召阻挠。约以来日取药而去，余乃以控涎丹方向药店购细末丸之，俟其来，令如法服之。阅三日，复来云：服丸药，大便下水极多，各症悉愈，请善后方。为疏六君子汤加白芥子，连服十剂，平复如初。曾君书斋之女，才三岁，得疳疾，众医杂治不应。延诊时，发热口渴，能食，皮黄肌瘦，腹大，便溏泻。初以消积清热平肝药，服数帖，病减大半，嗣以四君加柴、芍、黄连、胡黄连、五谷虫、鳖甲、鸡内金等品加减，十余剂而瘥。", "16645": "宁乡刘某之父，年六十，先患痰嗽，医药屡更，已逾一月。一日忽手足麻痹，喘急痰涌，口不能言，身微热，汗如泉溢，星夜延诊。脉之沉微，舌苔白而湿滑，即令以姜汁兑开水送下黑锡丹三钱，奈入口不能下咽，乃设法扶令半坐，分三次徐徐灌下；并以吴茱萸研末，醋调炒热，敷两足心，拖住元气。逾一时，始稍苏醒，再灌三钱，痰不涌，喘汗顿减。次晨乃以通脉四逆重加茯苓，阅三日，疾大瘳。继进六君加姜、附调理十余剂，平复如初。", "16646": "书店徒某，因冒风远行，患寒疾，医治少瘥，一日变脐腹绞痛，呼号震屋瓦，手摩米熨，不为少减，冷汗不止，手足痹软，大小便俱不通畅。临诊，舌苔厚白而暗，脉之沉紧，即呼主人告之曰：此寒积也，非寻常药饵所能治，今虽有妙方，恐不见信，若令他医见之，必妄加罪名，奈何！主人曰：但求先生主一方，无论何药，即当照服，亦断不令他医阅也。余曰：吾非如走江湖一流人，无端张大其辞以骇病家，且或借以希图重谢，不过以药方为世俗所罕见，庸陋医士，必诧为杂乱无章，病家不察，疑信参半，必不敢如法守服，或减轻分量，仅与少许，则药不敌病，自然无效，届时群疑众谤，因之峰起，肺腑非能言之物，谁与辨白？今主人既表示决心，可命纸笔立方，即疏《本事》温脾汤与之，令其连服二帖。阅二日，病者踵门道谢，并求善后方，与理中加附子而痊。", "16647": "何某，患咳嗽，胸中痛，痰涎臭不可近。踵门求诊，脉之浮滑。曰：此肺痈也，与《千金》苇茎汤数服而瘥。", "16648": "谷某之子，年十余岁，其父携之求诊。据云咳嗽、发热、口渴，小便不甚利，服发散药不愈，已数日矣。同道二人先后拈脉毕，皆主小青龙汤，正写方未毕，余适自外归，询知其状，即持脉，浮而微数，心知方错，未便明言。写方者询方是否？即慢应曰是。病者去，乃谓之曰：顷间方症不对，试再细思。一人曰：先生必别有妙方，请明示之。余曰：小青龙症，仲师虽未言脉，然即表不解三字推之，则可知其脉必浮紧也。今脉浮而微数，乃是猪苓汤症，试取《伤寒》、《金匮》细阅便知。吾意病者明日必来，当照方更正。次日，其人果来，谓方无效，乃为疏猪苓汤，一剂知，三剂疾如失。", "16649": "首饰店主胡某，因携其子求诊，并谈及其妻近三、四年来，每至霜降节，必发生痢疾，甚以为苦，不知所以。刻下时值七月，若至九月，难免不再患痢，届时当请屈驾诊洽，铲除病根。余应之曰：可。至霜降时，胡某延诊，审视腹痛里急，赤白杂下，日夜二十余行，舌色鲜红，苔白而薄，身微恶寒，脉浮紧。自云先日食面受凉，遂尔疾作，已两日矣，尚未服药。即与平胃散加羌活、防风、神曲、麦芽等味，以剪除新邪，二剂，外感已；继用大承气汤两剂，最后腹痛甚，下黑污臭粪极多，症减七八。恐其久蓄之积，根株未尽，复进大柴胡两剂，各恙皆平，乃以柴芍六君调理而愈。次年霜降时，疾不复作。仲景尝云下痢已瘥，至其年月日时复发者，以未尽故也，不诚然哉。", "16650": "江西黄君在中，初患外感，诸医杂治，屡变不痊。延诊时，言刻下最苦者头晕痛，猛不可当，心烦、口苦，手足不时热而麻木，已半月矣，大便时硬时溏，小便黄而涩，舌色红而苔黄，脉弦数。与风引汤两帖，疾如失，后以误用他医方，疾复发，但比前较为轻减，复延诊，仍用风引汤愈之，改进甘寒养阴，十余剂而瘥。", "16651": "潘某，初患头痛，往来寒热，余以小柴胡汤愈之，已逾旬矣。后复得疾，诸医杂治，益剧。延诊时，云胸中痞满，欲呕不呕，大便溏泄，腹中水奔作响，脉之紧而数，正疏生姜泻心汤，旁有少年谓黄连、黄芩凉药，干姜、生姜热药，人参补药，何一方混杂乃尔？余曰：方出《伤寒》，仲景明言「胃中不和」，心下痞硬，干噫食臭，腹中雷鸣下利者，生姜泻心汤主之」，吾乃照录原方，毫无加减，既患寒热错杂之症，必用寒热错杂之药。其人语塞而退。已而一剂知，二剂愈。阅日复延诊，其人从旁笑谢曰：日前轻慢乞恕！乃今知古方之不可思议也。余笑颔之而去。", "16652": "湖北张某，一日延诊，云近得异疾，时有气痛，自脐下小腹起，暂冲痛至心，顷之止，已而复作，夜间尤甚，诸医不能治，已一月有奇。吾家有老医，寄居此间，请为指示病源，并赐妙方，当执以授阅，借增识解。审视舌苔白滑，脉沉迟。即与桂枝加桂汤，并于方后注云：《伤寒论》一则曰「发汗后，其人脐下悸者，欲作奔豚，茯苓桂枝甘草大枣汤主之」；一则曰「烧针令其汗，针处被寒，必发奔豚，气从少腹上冲心者，与桂枝加桂汤」。此乃奔豚症，与仲师方案恰合，可以一剂知，二剂愈。已而果验。", "16653": "肾水上逆之奔豚，见之最多，以桂枝加桂与之，百发百中。惟肝火上逆之奔豚，患者极少。一日偶从友人闲谈，其同居有妇人前来，云其媳患气痛，口苦咽干，寒热往来。余曰：可取方往，不必临诊，意谓必小柴胡症也。其妇要求过诊，友人亦从旁敦劝。询之痛从少腹上冲胸及咽喉，顷之即止，已而复发如初，脉之弦数，舌苔白。即谓友人曰：此症幸临视，否则方虽无妨碍，病必不服。此乃肝火上逆之奔豚，为生平所罕见，当用《金匮》奔豚汤，即疏方与之，一剂知，三剂已。", "16654": "杨氏妇，年三十许，得一疾，医莫之识，人皆传为笑柄，在病者亦莫能言其所以。一日，其夫来云：拙荆现无他症，但云胸中窒塞无聊，短气，难于语言，有时呼吸亦殊艰阻，予偶以手按摩之，稍舒，后因卧以足抵其胸，觉甚快，后遂日夜不可刻离，甚以为苦，至今三月，医药罔效。临诊，舌无苔而色暗，脉涩。沉吟久之，偶忆《金匮》有肝著症，与之相合，即以旋覆花汤与之，方中新绛易以茜草，进三服，症不甚减。因念原方新绛，不知究系何物；药店茜草，是否真假，猝难辨别。乃用《医林改错》中通窍活血汤，三服，症减大半，又三服而瘳。", "16655": "同道晤谈间，云曾诊一妇人，时时欲哭，不可忍，状如鬼祟使然，莫名所以。但见其人瘦弱异常，年三十，无子女，亦无他疾，脉之微涩，比时搜索枯肠，无方对付，姑以逍遥散塞责，愿质之先生以为何如？余乃莞尔曰：此即脏躁也。《金匮·妇人杂病》云：「妇人脏躁，悲伤欲哭，状如神灵所作，数欠伸，甘麦大枣汤主之」，试取而读之便知，他日当为易方。已而果验。", "16656": "洋货店曾某，患伤寒，一月未愈，后变呕吐，食入顷刻，倾吐无余。诸医技穷而却走。延诊时，见其满面红光，舌色红而有刺，脉洪数，大便硬，与大黄甘草汤而瘥。反胃症之可畏，人皆知之，而试询其所用之方，动辄汇集滋润之品，以多为贵，及至屡服不应，徒太息于疾不可为，而不知其操术之不工。一医然，从医皆然，故一患反胃，鲜有愈者。胡某，江西人，世居长沙营业，一日因外感屡变，患反胃，延诊，舌苔白，脉微缓，与大半夏汤十余剂，平复如初。以此方获愈者多，足见经方之神妙，洵非后世所能及也。", "16657": "世医固守胎妊禁忌，往往遇病而不敢用药，遂至孕妇之疾迁延不愈，卒至母子俱伤，皆由食古不化之过也。《内经》「黄帝问曰：妇人重身，毒之何如？岐伯曰：有故无殒，亦无殒也」，旨哉言乎！有何姓妇，娠已七月，发热腹痛，脐以下如泼冷水，舌苔白滑，脉弦。他医概以四物汤加味，久之不愈。余曰：此乃附子汤症，何不照服？一医谓附子为孕妇禁药，谁敢用之。余曰：《金匮》怀妊六、七月，脉弦发热，其胎如胀，腹痛恶寒，少腹如扇，所以然者，子脏开故也。以附子汤温其脏。岂仲师而不知禁忌者？遂疏附子汤与之，一服而愈。", "16658": "按：治妊妇，不宜拘守禁忌，亦不可毫无顾忌，总以适可为止，斯为妙手。《内经》曰「大积大聚，其可犯也，衰其大半而止」，示医者以斟酌审慎，何等周到。尝记曾治一孕妇，胎结已三月，呕恶不止，米饮不能入口，已数日矣。腹中饥，大汗，脉两寸浮，两尺如无，气息奄奄，势甚危急，医皆束手。余以六君加旋覆花代赭石与之。同道皆咋舌，不敢赞辞。乃告其夫曰：舍此万无治法。即令从速备药，徐徐灌之，始得吐少咽多，药完一帖，约咽下十之七八；再一帖，即不呕吐矣。遂令止药，待观后效。阅二日又呕，又进药两帖而止。如此者先后三次，平复如初。夫有其病而不敢用其药，是谓无识；病已止而过剂，是谓畔道，二者皆不足以言医。有志者当知所从事焉。", "16659": "一男子曹姓，腹中隐隐作痛，胀满不堪，乍寒乍热，口渴，脉沉滑，医者每以发散药图治，益剧。肩舆求诊，按其腹濡而痛，间露紫筋。余曰：此系肠痈，宜及其未溃而下之，否恐溃烂难治。乃以大黄牡丹汤两帖，下黑粪甚多，各症悉减。改用赤豆薏苡汤加味，五帖而愈。", "16660": "按：肠痈生于腹中，隐而难见，非特外科不知，即内科率多无从问津，甚至溃而且死，脓血或从便下，则群目为痢；或从脐出，则益挢舌不能作声。尝见一八岁小孩，肠痈溃后，脓血从大便出，皆作痢治而死。又见一儿脓血从脐间出，医以为病即在脐，用末药掺之，三日而死。又见一儿先此数月，食指商阳穴现一小疮，溃烂不休，后因肠痈内溃，指疮始结痂而愈，其父颇谙医，以治久不愈，具以告，邀余临视。腹热肿胀，筋露青紫，满面青暗，不可逼视，气息奄奄。余曰：此大肠痈也。其父惊问：何以一望而知？余曰：食指商阳穴，是大肠经脉所起，即是确证；腹筋青紫，面色青暗，皆是痈毒溃烂之现状。症已无救，不须服药。次日即死。嗣闻其父深自愧悔，每恨挽治之不早也。", "16661": "周姓妇，年三十许，产后已逾两月，忽心中烦热、气短，不能安枕，欲小便不得，腹胀满，杂治半月，益剧。幸饮食如常，脉之弦缓。一医欲与五苓散。余曰：当用肾气丸。《金匮》曰：「妇人烦热不得卧，反倚息，此名转胞，不得溺也，肾气丸主之。」主人正检前方中有五苓散。即疏肾气丸与之，一服知，二服愈。", "16662": "傅某之子，才五岁，咳嗽久而不愈。延诊时，见其喘急，目突泪流，莫名其苦，舌苔白而薄，脉浮数。时值夏至，诸医但以通套疏散药与之，无一应者。余曰：此症必用麻黄方效，不可拘泥时禁。即疏越婢加半夏汤。其父犹疑之，余引《金匮》「咳而上气，此为肺胀」详细告之，因取药少少进服，不一杯而疾如失。可见经方之通神，匪夷所思矣。", "16663": "林君振华，患疟，每日申时发热，不恶寒，交亥止，身疼痛，欲呕不呕，舌苔白薄，脉平不弦。余念《金匮》「温疟者，其脉如平，身无寒，但热，骨节烦疼，时呕，白虎加桂枝汤主之」，正谓此也，即照方授之，一服知，三服已。", "16664": "丁巳夏，患疟者率不可与柴胡。章姓妇，热多，微恶寒，医者与小柴胡汤，不应。嗣以补中益气及温燥，益烦躁不宁。延诊时，舌苔黑而少液，口干，但欲漱水，脉不弦而沉数。余以为乃肾阴虚而挟相火也，以六味加黄柏、知母，二剂而愈。后遇多人，脉皆不弦，症每相类，俱以六味加减治之。书此以见疟症之变。", "16665": "劝工场贾某，患寒热，骨节烦疼，无汗，口渴，大小便俱不通，已两日矣。脉之紧数，舌色红而苔白，与刘河间防风通圣散两服而瘥。", "16666": "四川商徐某，患两脚骨节疼痛，昼夜叫号，跬步不能移，杂治不愈，已十日矣。脉沉缓，舌苔淡白，欲食，大小便如常，与自制七节汤，方中黄耆减半，加牛膝二钱，一剂知，连服十剂，平复如初。", "16667": "南货店黄某，患手足迟重，口中淡，不饮食，懒言语，终日危坐，不可名状，医药杂投无效，脉缓。余曰：此寒湿也。《金匮》云：「湿家身烦疼，可与麻黄加术汤。」照方与之而愈。", "16668": "《金匮》百合病，言之详矣，余曾为人医病，未之见及。一日有工厂织工踵门请曰：前此大病一月，几死。据述近状，竟是百合症，脉之浮救。又曰：病久囊空，难于购药。乃以百合一两、玉竹参六钱、麦冬六钱，令其煎水代茶，数日而愈。", "16669": "苏州易某，以贩卖寄寓长沙，一日负货踵门，价售毕。请曰：患病已一年，人莫之识，医药屡更，讫无一效。袒而示之背，云内有肉约一拳大，觉冷如冰，视之略无异形，按之不痛。余沉吟久之，意其必系寒痰凝结所致。《金匮》云「心下有留饮，其人背冷如掌大」是也。脉之弦，舌苔白滑。脉症相合，即以控涎丹与之，下痰涎极多而瘳。", "16670": "高士宗谓：连嗽不已，谓之顿呛。顿呛者，一气连呛二三十声，或十数声，呛则头倾胸曲，甚则手足痉挛，痰从口出，涕泣相随，皆由毛窍受寒，致胞血凝涩，其血不能淡渗于皮毛络脉之间，气不煦而血不濡，则患顿呛。用药当以治血理肝为主。蓄之于心，未曾经验。一日有傅姓小儿，患症与高氏所论适合，他医用疏散药不应，脉之细涩，乃以当归四逆汤与之，一剂知，三剂已。", "16671": "江西林某，营业长沙，身肥嗜酒，善啖，忽患胸中痞满，郁结不舒，医治三月不效。嗣后胸膈益胀满不堪，每以手重捶少止，已而复作，一日夜必数次或十余次，如是者又一月有奇，医皆莫识，惟饮食尚可，舌苔白，脉弦滑。余偶忆十余岁时，闻诸戚友，云有人曾得怪症，状与林同，医无治法，后因患他症大呕，痰涎中杂若黑虱者甚多，疾竟如失。因思林体肥而善饮啖，湿热素盛，乃生痰生虫之根据，所患之症，非痰即虫，惟有引吐一法可以治之。乃以莱服子捣碎，以沸汤搅和，少凉，令其徐徐饮之，初次所呕皆痰涎，最后痰水中果有如黑虱者，顷之盈盆，蠕蠕而动，疾遂不作矣。可见人之疾痛，非耳目所能尽也。", "16672": "邓某患疝，疼痛肿胀异常，恶寒，舌苔白，脉沉紧，与当归四逆加吴茱萸汤与之不应，乃加附子、干姜，三剂平复如初。", "16673": "谢姓妇，前阴热痒，爪搔至皮破血流，无片刻停，医者用方内服外敷不效。舌苔白，脉之左手沉数，以龙胆泻肝与之而瘳。又一妇人前阴热痒，且有虫蠕蠕，亦以上方服之，并研杀虫末药，设法纳入，遂瘥。", "16674": "汪氏女，年十余岁，忽恶食，自云秽臭不可闻，驯至月事亦不行，医治罔效，已两月矣。诊之：脉濡缓，舌色红，苔白。细询症因，据云清明节，母命在山中守笋，坐卧湿地得之。因悟此乃湿热侵入血室所致，以小柴胡汤合二妙散加萆薢、桃仁、归、芍，三剂而月事行，渐次进食而愈。", "16675": "木工李，体肥嗜酒，患肤痒，搔之虫蠕蠕盈指甲，医治数月无效。诊之：脉弦缓，舌苔白。皆由酒食侵淫，遂致肺失治节，肝木郁而生虫。乃以补中益气汤倍柴胡加白芍、蒺藜、杉枝、桑枝、枳椇子，并令戒酒，旬日而愈。", "16676": "吴君迪光，江西人，营业长沙。患往来寒热，胸中痞塞，医以败毒及各种发散药与之，不效。易医以柴芍六君进，益剧。诊之，脉弦滑，舌苔白。曰：此痰热阻于膈膜也，少阳之气通于膈，故往来寒热。乃以小柴胡合小陷胸与之，一剂知，二剂已。", "16677": "丁已秋，余息影常宁水口山矿物局。适张君惠畴之女工，肚腹膨胀，饮食锐减，骨瘦，身微热，贪眠，行动维艰，脉之沉微，舌苔白暗而黑。曰：此阴寒重症，幸未误药，及今图之，尚可救济。即疏理中汤加附子，嘱其连服数剂，即平复如初。", "16678": "黔城向君之内政，娠已及期，一日腹痛甚。延诊，舌苔白，脉之沉缓无力。曰：尚非正产，切勿误认，与十全大补汤去桂，加鹿胶、艾叶，一服平复，后又十余日而娩，母子俱安。上案甚多，不能备载，书此以为先事慌张者戒。", "16679": "嘉禾李君玉堂，当夏历六月忽患左足疼痛，卧床不可转侧，呻吟之声，达于户外。诊之，脉沉紧，舌苔白，口中和。曰：此风寒直中少阴，法当用仲景麻黄附子细辛汤。旁有人咋舌言曰：天气暑热若此，麻黄与细辛同用，得毋大汗不止乎？余曰：此方并不发汗，非阅历有得者不能知，毋庸疑阻。即疏与之，三药各一钱，共仅三钱，煎水两杯，分二次服，一服知，二服即步履如常而愈。经方之神效，洵有令人不可思议者。", "16680": "敲砂工人某，年十余岁，一日其母携来求诊，据云头晕已三日矣。问之，不知对答，但作哭形，双泪交流，面色惨晦，状如痴人，舌苔白，脉浮大而滑。余曰：此痰饮上逆，故现此症。与温胆汤去甘草，加旋覆、赭石、南星等药，一剂知，二剂愈。因无力服善后药，阅数月又发，仍与前方，效如桴鼓。", "16681": "工人李某，患感冒，医药屡更，益剧。诊之，恶寒发热，无汗，口渴，四肢顽麻，大小便俱不通利，已三日矣。舌色红而苔白如霜，脉之浮洪而数，此表症未除，里症复急，法当表里两治，与防风通圣散两剂而瘳。", "16682": "河南商城马君诚斋之内政，素体弱，孕才二、三月，忽患昏迷，不省人事，四肢冷，面色惨白，顷之苏。嗣后或一日一发，或数日一发。时周公铭山，颇谙医学，与马有姻，尝为主方，以其症之稀见也，骇而辞却，嘱其专请余治。诊之，脉涩弱，舌苔淡白而薄，就叩所以。余曰：此即子痫也，凡气血虚弱之妇女，一遇胎结，则正气难免阻滞，不能周流，遂现此症，以补养之品调之，可无虞也。即疏归脾汤加味，一剂知，数剂愈。", "16683": "语云：百病易治，咳嗽难医。盖以症之缘起纷繁，非明眼人，动辄舛错，每有愈治愈坏，致戕生命者，指不胜屈。龙王山工人某，云先年秋患咳嗽，屡医无效，已置之不理矣。今春，每逢寅卯时，喉间如烟火上冲，即连咳不止，晨餐后渐止，以为常，已三阅月，未少间。询之口中微苦，气粗，不渴，舌色红而苔白，脉浮大而满指，按之紧数。曰：此寒包热也，脉紧为寒，数则伏有热邪，彼粗工乌能知之。即与小青龙汤加石膏，一服知，再服已。", "16684": "陈某，当夏历五月，患大小便俱不通利，腹胀不堪，已旬日矣。据云数年前，尝患此症，以服温药获愈，照方服之，不应。他医以通利药进，亦无效，改从暑热治，益剧。诊之，舌苔白，口中淡，脉弦缓。曰：此系风湿阻滞，肺失治节，脾失转输，故形此症。与麻黄加术汤益入紫菀，一剂知，再剂已。", "16685": "安徽桐城马君铁珊之女工，年方十二岁，患温热症，大热大渴，汗出，双目红肿，口舌亦肿裂流血，头痛如劈，腹痛泄泻，臭不可闻，脉洪大而数。与大剂清瘟败毒散加减，二剂，各症稍轻，忽遍体发现红斑，仍用原方日夜进服，又四剂，十愈七八，乃去苦寒，加入甘寒等品，又数剂而始瘳，愈后半月，发肤手足爪甲俱脱，久而复生。甚矣！瘟热之毒焰，洵非轻剂所能侥幸也。", "16686": "妇女似娠非娠之疾，或成症瘕血蛊，或感异气而结为有形之物类，或由气结而渐变为水，古有之矣，从未见有始终纯由气积，酷肖真胎，而于脏腑身体毫无窒碍者。扬州方君禹金之继室，体素羸弱，月事愆期，余为治愈矣。一日延诊，云经断已及三月，未审是停是娠，脉之涩弱。曰：娠殊未确，但无他恙，可以美膳调之，不必用药。至五月又延诊，曰：脉如前，未必娠。自云腹内动，与娠无异。余答云：徐观后效，毋庸服药。嗣后期已九月，复诊，脉不少异，腹已高大，但较常娠差小，动时酷似真胎，两乳亦略起而有清汁，余念如果胎娠而靓此脉，后必难保危险。延至十一月未产，方君云：常娠不过九、十月而产；今若此，殊难索解。余曰：娠十余月而产者，古尝有之，但其脉究有疑义，且徐俟之。后又数月，方君笑而告曰：内子之疾诚怪，自月事断及今十三月，昨今两日，腹响泄气不止，至晚腹消大半，今日仍然，腹已全消如常，又无他恙，岂非怪事？余曰：诚然，我未之前闻也。书此以谂世之究心胎产者。", "16687": "福建闽侯陈君洁如之内政，每月事将行时，必腹中痛，大便下白脓。诊之，脉弦迟。曰：此内有积寒，当以温药下之，疏方用《本事方》温脾汤。后陈君云：时期已过即愈，前方尚未进服，余心知其疑畏也，笑而颔之。嗣于数月后又延诊，云旧病曾请某医举方，屡治未效，余曰：方犹前也，毋庸疑阻。嘱以一剂不应，必连二剂或三剂。不料其内政仍心怀疑畏，每日止进一杯。越二日，又延诊。余曰：药虽对症，日服一杯，药不敌病，乌能有效，自后务必连服数杯，药乃接续有力，以大便下尽黑粪或白脓为度。始照法服之，下黑粪甚多而愈。以后月事如常，旧恙不复作矣。", "16688": "袁君友松，宁乡人，性谨愿，生平笃于自信，尝以体素羸弱，非补品不敢沾唇。仲秋时节，陡患泄泻，日数十行，继以红白，腹胀痛不可忍。适余偶过访，即挽之主方。脉之弦紧，舌苔白而湿滑。即疏胃苓汤加味。嘱其连服两剂，如疾不减，当另易方，势虽剧，幸勿乱。袁君疑药之克伐，仅煎进一杯，即谋另医。值友人问候，为其谙医道，示以方，劝其当照服两剂，徐观后效，始再进一杯，见疾未减，即用他医方，药愈乱，疾益剧；乃延谷某治之，用大剂滋补品，三日势转危急，粒米不入，体亦疲困，卧床不起，谷辞不治，云已无脉。举家惊慌绝望，为具后事，病者亦自分死矣，遂不服药。又三日，疾如故，同事皆云病虽十分危急，不可坐视，日已晏，其侄祝候君至，云家叔病曾承费心，今若此，未审可以挽救？请往视之。余曰：令叔之恙，前此开方时，已剀切言之，若听余言，必不至此。今孱弱之躯，药误几遍，阅时又久，恐无及矣。袁君曰：奉叔母命而来，不论如何，当请枉顾。余以袁氏叔侄间交情素厚，不忍卒却。诊之，脉仍露弦紧状，舌苔湿暗，自言腹中胀痛，并述前药屡误，此后请用何药，但语言间不相接续。余一一佯诺，就榻前立方示之。退就他室谓其侄曰：脉有生气，前医谓无脉者，当系误用补药而伏也，但疾呈可治，奈令叔本不知医，而性颇执，榻前之方，乃一时权宜，不欲逆病者意耳。人心为君主之官，心之所至，药气每随之而行，一逆其意，药虽对症，必缘思想而弊端丛生，此事主权全在君身，余另有真方授服，但不可令病者知耳。袁君唯唯称善。即疏《本事方》温脾汤以祛积寒，三服，痛胀顿减，稍进糜粥。嗣后或用胃苓合左金加党参，或用补中益气合左金，渐次向愈，其中权宜迁就者又五方，最后以十全大补加味进，始告示以真方，时则已能于室内自由行动矣。计自病剧以至痊愈，又历半月之久，举家感激，至登报鸣谢。人或谓余何不惮烦？答曰：枉道徇利则不可，至枉道救人，即嫂溺援手之道，圣者不之非也，又何尤焉。", "16689": "黄海廷之儿，年七岁，发热口渴，腹痛，口不欲食，已半月矣。诊之，脉数而促，舌苔黄燥而色鲜红，痛处不可手按，人疲倦而烦躁，大便不畅，小溲黄浊。审知食积久而化热，本宜用大承气，因虑其体羸不胜，乃以三一承气汤加党参服之，一剂便行，二剂下黑粪甚多，热退渴止、痛减，脉亦不促矣。改进柴芍六君一帖，腹痛又作，而身微热，知积未尽，再以大柴胡汤两剂而瘳。", "16690": "周某之妻，年二十余，患后阴热痛而肿，继连前阴亦然，小溲短热，行动维艰。其夫请方，余疑其为淫毒也，却之。他医以发散及寒凉清利进，益剧，驯至咽喉亦肿痛，水谷难入，复再三恳求。诊之，脉沉微，舌苔白而滑。曰：经言「肾开窍于二阴」，肾阳不潜，浮游之火蔓延上下，故见此症。以《济生》肾气丸与之，一剂咽痛止，二剂肿痛减半，三剂顿愈。", "16691": "漆工余某，郴县人，患胸背作痛，或因感受寒热，痛即加剧，又每至晚间辄噎食臭，腹饱胀或微痛，不能进食，医治不痊，已十年矣。近一二年内，夜及晨必泻利一二次。脉之，沉紧而弦，舌苔灰白。与瓜蒌薤白桂枝汤不应，本拟用乌头赤石脂丸，适合有神保丸，即以七粒与之，令其用温开水送服。间二日复来，据云日前心疑药少力薄，恐难获效，因将所授丸药嚼碎，用开水送下，顷之泄泻，至傍晚已十次，饮冷茶一钟即止。今则胸背不复痛矣，但晚间腹胀、干噎及晨泄，尚未痊愈。为疏理中加附子、吴茱萸、固脂等药，令其多服而痊。", "16692": "长沙刘君鑫森之母，年近七旬，体气素旺，不亲药饵。一日感冒，发热恶寒，身体疼痛，无汗，心烦恼不堪。诊之，脉浮紧，舌苔白而薄。余曰：此与《伤寒·太阳篇》大青龙症正相吻合。即疏大青龙汤授服。次日复延诊，刘君云：日昨之方，见者咸宜阻之，多以高年宜用温补为言，议论纷歧，莫衷一是，幸尊方为向所深信，即一概谢绝，照方煎服，今疾势已减大半，则方之获效，不辨自明。余笑应之曰：仲景真方，非特门外汉不能知，即个中人多不能领会，每有方甚平常，施之大症，辄获奇验；亦有方似奇险，用之得法，效如影响者。故古圣之方，非精思不能窥其奥窍，非屡试不能识其神奇，若大青龙汤，乃百试百验之方，所患者症不确耳。吾临症拟方时，曾再三审慎，若旁人异议，不足深怪。今若此，当将原方再进一服，即照方服之。至其明日，寒热身痛悉瘥，惟心烦未愈，舌苔转黄色，脉弦数，与栀子豉汤两剂不应，改授黄连阿胶汤两帖而痊。若不凭脉症，而但怵于高年，即不施补养，而或以搔不著痒之方塞责，万无愈理，庸医杀人，此其一端。精于斯道者，自能辨之，断不嫌言之过激也。", "16693": "工人谷某，先得外感，继转疟，热多寒少，大渴多汗，以金鸡纳霜服之，不愈，即加倍进服之，疟止；阅日复作，又加倍吞服，旋止旋作，已而面目手足俱浮肿，踵门乞方。脉之弦数，舌色红而苔白，与小柴胡加花粉、知母、常山、青皮，于疟未发先一时进服一帖，疟止，嗣与调理，各恙遂痊。", "16694": "火车站工人某，年五十余，遍身肿胀，色黄而暗，饮食锐减，医治益剧，自分死矣。踵门乞诊，脉之，紧而缓，舌苔灰白而厚滑。与五皮饮加荆芥、防风，紫苏，三帖，身微汗出，肿消大半。改用真武汤加防已、木通、椒目，数服而瘳。矿工扬州黄某妻，患咳嗽，久而不愈。据云毫无余症，惟五更时，喉间如烟火上冲，即痒而咳嗽，目泪交下，约一时许渐息，发散、清凉、温补，备尝之矣，率无寸效。脉之弦数，舌色红而苔白。曰：此有宿食停积胃中，久而化热，至天明时，食气上乘肺金，故咳逆不止。医者不究病源，徒以通常止咳之药施之，焉能获效。为授二陈汤加姜汁炒黄连、麦芽、莱菔子，一帖知，二帖已。上症验案甚多，聊举其一，不复赘云。", "16695": "机械工某之父，年近六旬，初患外感夹积，医以发散消食之品与之，寻愈矣，已而腹胀痛，泄泻不止，更数医，率用破气消耗进，疾益剧。肌冷汗出，呼吸急促，不能接续，时时登厕而无便，饮食不入，已数日矣，自分不起。其子踵门求诊，脉之，浮大而虚，舌苔灰暗湿滑，检方盈寸，殊堪喷饭。曰：此虚寒而中气下陷，再投前方，命其休矣！即授补中益气汤加乌附、干姜大剂，嘱其不避晨夜，陆续进服，四剂而瘳。", "16696": "《伤寒论》云：「太阳病不解，热结膀胱，其人如狂，血自下，下者愈。」按：热结膀胱，即热入血室之变文，以血室与膀胱相连也；其曰「其人如狂」者，即包括小柴胡症谵语见鬼在内；又曰「外解已，但少腹急结者，桃核承气汤主之」，所谓急结，即兼有抵当汤症之硬满在内。病变不一，古文简略，读者当扼定病源，即其常以通其变，断不可死于句下，所谓知其要者，一言而终，不知其要，流散无穷也。吾临症凡三十年，所见热入血室，在男子因伤寒而传变者绝少，而以妇人关于月经者为最多，兹述一二，以例其余。赵公惺予之家妇，因经水适至，患往来寒热，身体疼痛，无汗，脉浮紧，与小柴胡汤加麻、桂等药两剂微汗之，寒热身痛已，嗣复经水中止，腹剧痛如被杖伤，不可手按，伛偻不能行动，按脉弦数。审系热入血室，以年少体强，即授桃核承气汤一服，下黑粪，痛减，二服霍然。同时陈君洁如之内政，症与上同，但身不痛而汗出为异，与小柴胡加桂尖二服，外症已，旋患少腹疼痛，如杖伤然，以体素弱，恐其不能胂受桃核承气，借用四物去地黄，加桃仁、红花、桂尖、醋炒大黄，两帖，下黑粪甚多而愈。上二症皆无谵语见鬼症，而少腹痛如杖伤，又仲师引而未发之旨，学古者所以贵得言外意也。", "16697": "李某，当夏暑时，初患外感，医治不如法，十余日后，忽大汗大渴，身大热，时作谵语，群医以症属罕见，却辞不治。踵门求诊。询知身虽恶热，而足下却畏风而冷，切脉洪大而缓，舌色红而苔白且厚。曰：大渴、大汗、身大热而谵语者，三阳合病，为白虎汤之的症，仲景《伤寒论》已明言之；足下畏风而冷者，兼有湿也。即与白虎汤加苍术，一剂知，二剂已。", "16698": "邓某之妻，小产后，患感冒，杂治不痊，已而身大热，多汗，少腹硬痛，势已濒危。其夫仓皇乞诊。脉之弦数，舌色红而苔白。询知痛处手不可近，溲便皆不通利。检阅前方，皆与症反，殊为可哂！审系瘀血停蓄为患，本宜桃核承气汤，以病久人困，虑其难于胜受，乃变通用四物汤去地黄，加桃仁、红花、肉桂、醋炒大黄，一剂下黑粪，痛减七八，再剂而愈。", "16699": "窿工石某，因在窿内供役十余年，蓄积寒湿，两足及腰酸痛。医者概以搔不著痒之方施治，遂日以剧，肿痛难行，面目暗黄，亦露肿痕，舌苔白而湿滑，脉沉弦而缓。与麻黄五积散加附子六剂，肿消痛减，继受真武汤加木通、黄耆、椒目，又五剂而瘳。同时又一窿工邓，患与石大同而小异、亦以前方加减而获效。上症最多，不能备举，惟症变异同之处，在医者善于变通也。", "16700": "机械工某之妻，患前阴热肿痛庠，最不能堪，医治逾月，毫无寸效。其夫踵门乞为一诊。脉沉弦而滑数，舌色鲜红而苔白，口苦咽干，不喜饮，溲数而短热，知系厥阴风湿，久而化热生虫所致。即以龙胆泻肝汤加黄柏、知母，服五六剂，并外用杀虫清热去湿之药敷洗而愈。", "16701": "工人黄某，素嗜酒而多湿，初患感冒，屡治转剧，因迭进温补，痰咳神昏，头晕耳聋，胸痞而呕不止，脉混淆不清，舌红而苔垢，口臭逼人，不可向迩，医皆却走，哗以不治。余曰：此湿郁化热，为温补所锢闭，胸中大气，失其升降；邪热痰涎，无从宣泄，故现以上险恶之症。法当清利湿热，涤除痰垢，使胸膈宽舒，肺胃清肃，则乾坤自有一番新景象。疏方用小陷胸合温胆汤，加黑栀、槟榔、木通、滑石、竹茹等药，三帖而诸症顿减大半，脉显滑数，小溲热赤，大便通利。复就原方稍为增减，又数帖，各恙递蠲，舌露鲜红，改授养阴清热而瘥。", "16702": "窿工某之妻，年四十余，正月经将断未断之候，患前阴热肿痛痒，赤白淋漓不止，极难忍耐，已逾一年，医治毫无一效。诊其脉沉微，舌色暗淡，微露湿白苔，口中干而不渴，头时眩晕，行动时两脚软弱，不能任身。审系肾家虚风所致。经云「肾开窍于二阴」，虚则内风煽扰，发生似热非热之症，故屡服清热祛风利湿之药，疾必益剧，乃以八味丸作汤，加蒺藜、牛角䚡，进服二帖，症愈大半，五帖痊愈。", "16703": "中国地气，高处多寒，低处多热，土著平民，恒感受而成为偏胂之疾，故医者为人诊治，必参究天地人而为调剂，方能有济，微论其他。即湖南一省言之，宝、永高燥而多山，麻、桂、姜、附，人多能受；岳、常卑湿而多水，腠理疏脆，上药即不可概施。余曾治先从兄念农之满妹，用乌附至二十余斤，已属罕见之事，案已载上卷。近水口山矿局漆工余某之妻，年近四十，得阴寒大症，已一年矣，初起时尚微，不甚介意，迨后每发益剧，踵门求诊。据病者云：左边少腹内有块，常结不散，痛时则块膨胀如拳，手足痹软，遍身冷汗，不醒人事，或二三日一发，或五六日一发，医药讫无寸效。阅所服方，厚积数寸，令人捧腹。脉之沉紧，舌苔白厚而湿滑，面色暗晦，即与通脉四逆汤，乌附用八钱，连进三剂，痛止。令其守方多服，免致再发。嗣因止药又发，另延他医治之，逾二旬，痛如故。仍来求诊。余曰：症本不易治，岂可付毫无学识之辈，而以搔不著痒之药图治乎？阅方果皆庸俗不经，复以通脉四逆加吴茱萸、乌附每剂一两，续加至二两，服十余剂，痛已不作，而内块未散，因念《金匮》「寒疝腹中痛、逆冷、手足不仁，若身疼痛，灸刺诸药不能治，抵当乌头桂枝汤主之」，惟乌头不可得，即用生附片一两，照方煎服。至四帖，脉紧稍减，内快渐小，食量增，精神益振。但药方为俗所未见，莫不惊骇，群疑众谤，时闻耳鼓。幸病者性颇慧，谓药业与症对，当多服图效，不肯更易，并求增加附片至二两，余允之，又服数剂，内块递减。嗣复陆续增加附片至四两，已服两帖，其夫虑其病久且死也，时值冬杪，谋舁归，求另方。余曰：方无以易，惟途中仍不宜缺药，当预购以备服，即携药四帖而行。记旅行三日，尽三帖，至第四日抵家，病者体气日健，喜出望外，即取余药一帖，浓煎大碗，一饮而尽，顷之，面热如醉，手足拘挛，舌尖麻，已而呕吐汗出，即平复如初，忻然向其夫而言曰：吾病其瘳矣！萧先生先见之明，果然不爽，自后毋庸服药，竟不药而诸症如失。次年春，其夫复至矿局，备述如此。尝谓大病必须大药，非特医生必有确定之见，又必病家信用之坚，两者相须为用，方能奏回天手段。如上症苟非病者信服不疑，必为旁议挠惑，功败垂成，反使门外汉得以借口，而真见病源者，不免代人受谤，无从辨白，自古名医之身遭其厄者，何可胜道！吾于斯症，何幸而获免也。", "16704": "胡某，初患头晕心悸，余以清热祛风涤痰之剂服之而愈。阅数日复发，医用疏利不效，继以温补，愈治愈乖，仍来乞诊。询知胸中窒塞，口苦，时时呕恶，大小便亦滞塞不通，粒米不能下咽。气喘，夜不安枕，时有谵妄，脉之沉极而滑，舌绛苔浊，秽气逼人。盖为误服温补，阻塞肺胃升降之机，以致痰热无从宣泄，故增出以上恶症。即用黄连、瓜蒌皮、枳实、法夏、栀子、旋覆、赭石、石膏、胆星、贝母、海蛤、花粉、黄芩、菖蒲等味出入为大剂，调入竹沥、姜汁，服五帖，诸症递减，乃去苦寒，参入甘寒清润等药，又十余帖，始获痊愈。", "16705": "敲砂工某，先患伤寒，杂治不痊，乞诊。脉之紧数，询证恶寒发热，无汗，口渴，骨节烦疼，腹胀，两腿麻痹，大小便俱不通利，与刘河间防风通圣散两帖，诸症顿减。已而转疟，热多寒少，口苦，时呕，胸痞，舌绛苔垢，脉滑数，与小陷胸合温胆汤加黑栀、黄芩、知母，三帖，疟已。改用清利小剂而瘳。", "16706": "窿工某，因外感转疟，单热无寒，大渴大汗，舌绛而苔白，厚如积粉，口苦，秽气逼人，胸满而喘，头晕痛，食入则吐。疟发时，人事不醒，时作谵语，已旬日矣。阅前方，或表散，或清凉，皆用柴胡，医治益剧。诊之脉洪大而滑数。曰：此乃湿热挟痰，故显以上各症。柴胡具升发之性，本少阳要药，而脉不弦者，则与少阳无涉，误用柴胡，则少阳之气有升无降，诸经之气亦随而上逆，况兼各种病邪，助桀为虐，遂致肺胃二者皆失其作用，欲却病而反以增病，皆由医者固执不通之过。救误方法，当以荡涤痰饮、清利湿热为主，使肺胃二气得遂其通降之枢机，则病邪无所依据，自然退避矣。疏方小陷胸合温胆汤，加黑栀、石膏、胆星、建菖蒲、竹茹等药，为大剂，一帖，呕吐止，能进食；二帖，诸症十愈六七；三帖，疟止。乃减去苦寒，加入甘寒清润之品，又数帖而瘳。", "16707": "张某，年才二十余，平日强健，略无病苦。一日晚间二鼓时，陡患狂妄，不省人事，数人捉之就床横卧，手足躁扰不宁。据旁人及其弟云：先此毫无他症，莫知所以。脉之浮大而虚，断为虚狂，大抵必受意外惊骇，或他事刺激，及忧思过度，遂心神飞越，出现似狂非狂之症。疏方用大剂归脾汤，嘱其从速购服一帖，比晚熟睡，至次晨，病即如失。询知先日因过船失足受惊故尔，继思上症幸未汗出，又不曾误药，故能回元气于无何有之乡，否则生死难以逆料也。", "16708": "长沙刘君鑫森之少君，年甫五岁，平日喜食糖点，久而成积，初不之觉，已而间作腹痛，所下之粪，杂有白脓，犹谓偶然小恙，未遑医治。继乃渐剧，日常数次。诊之，脉弦缓，舌苔淡白。因其赋禀薄弱，不敢迳施下剂，乃变通用理中汤加大黄服之，不应，遂以理中合小承气二帖，下黑粪甚多而愈。", "16709": "工人蔡某之妻，每日自午至子，手足心热，心中烦热，不得卧，短气懒言，饮食递减，身弱，艰于步履，不时咳嗽，已数月矣。脉之弦缓，舌苔淡白，口中干，喜漱水而不欲咽，以黄耆建中汤与之，守服三十剂而安。", "16710": "窿工某，先因感冒，杂治不效，已而转疟，又十余日，危殆已极。延诊时，卧床昏睡，不能起坐，问之不知答对，气息仅属，粒米不入，已三日矣。脉浮缓而虚，舌苔灰暗，面色惨晦，询之旁人，但云午后微热，不知其他。阅所服方，皆庸俗搔不著痒之药。即以大剂六君加香、砂、草果、乌梅与之，二帖，神颇清爽，略进糜粥，再三帖，疟已，眠食稍可，更方用大剂六君加姜、附，数帖而瘳。", "16711": "机械工某，先患外感，医用表散，寒热退，已而痰嗽呕吐，左胁下痛不可耐，舌绛苔白而厚，脉弦滑。断为肝邪挟痰饮上逆，以致肺胃之气不能通降。检所服方，皆温燥升提之品，愈服愈乖。治当涤降痰饮，肃清肺胃，兼以清热平肝，则病可愈。为疏温胆汤加旋覆、赭石、川楝、白芍、青皮、竹茹、栀子、黄芩等药，二帖，呕平，胁痛、咳痰减，再两帖而疾去八九，改投清润疏降而安。", "16712": "工人之父某，年近五十，患心气痛，杂治不瘥，已逾年矣，每有劳动，或用心稍过，即痛甚。诊之，诸脉如常，惟左寸略微细，舌苔淡白，面㿠白而神不敛。即疏六君加归、芍、薤白，服四帖，不应，改用归脾加建菖，一剂知，二剂疾如失。继思上二方，无大差别，而效不效若此，医药之微妙，诚未可掉以轻心也。", "16713": "窿工某之妻，年约三十，产后患感，杂治不痊，已两阅月。延诊，身微热，口渴，但欲漱水而不喜多饮，面若火烘，头晕目眩，脉浮大，按之虚散，与当归补血汤。记用黄耆一两、当归三钱。其夫以药味少而价昂，疑不购服，改用他药方，愈剧。逾旬复乞诊，以实告，询之症尚如前，令速照方煎服，毋得再延贻误，果三帖而安。", "16714": "工人某，患泄泻，日数十行，医以表散温燥药进，泻略减，而咽喉痛，杂见白点，咳嗽，痰中带鲜血，身大热，汗出，遍体红斑，口干，不甚喜饮，年未三十，两人掖而求诊。脉浮数而促，舌鲜红多刺，苔微黄，小溲短赤而数。余曰：此乃秋燥症，泄泻者，肺热移于大肠，脏邪传腑，自寻出路，正是佳兆，乃反其道以行之，幸泻未全止，治节之权，尚存一线，而喉关见白而痛，咳嗽带血，则肺金受伤，已非浅鲜，及今图治，或可挽救。与大剂养阴清肺汤加石膏、知母，三帖，症减大半，嗣就原方加减，又十余帖，始获全愈。", "16715": "机械工某，患伤寒，杂治逾月，各恙渐次向愈，惟口渴时呕，小溲不禁，有时而遗。踵门乞诊。舌绛而苔淡白，脉浮大而数。曰：此阳明余热未净，故口渴而呕，热气上灼肺金，治节无权，不能收摄津液，小溲所以不禁而遗也。与竹叶石膏汤三帖，遂霍然已。", "16716": "敲砂工某，先患感冒，继转疟，旬余不痊，询知单热无寒，发时两足冷如水浇，大渴大汗，舌色红而苔白，脉洪大而缓。审系阳明湿热，不关少阳，故脉无弦象，与白虎汤加苍术，一帖知，三帖已。同时又有工人，亦患单热疟，惟身疼痛、喜呕、脉浮大而缓为异，与白虎加桂枝汤而廖。", "16717": "工人陈某妻，患病旬日，自以单方疗之，不应，更数医亦无效。一日两手拳曲而振掉，身大热，面赤口渴，无汗，大小便不通，举家惊扰。诊之，脉浮洪而弦数，舌红苔黄燥，即为刺少商穴，两手即伸，审系表有风寒而里有实热，法当表里两解，与河间防风通圣散，两帖，汗下兼行，诸症悉愈。继转疟疾，热多寒少，改用小柴胡去法夏、人参，加桂枝、花粉、知母、常山、青皮，三帖而安。", "16718": "窿工某，患冬温，初微恶风，四肢串痛，头痛而晕，口渴，发热微汗，医者与表散药，益剧。延诊，身大热，大渴，心烦，口苦，汗出如浴，头痛如劈，咳嗽欲呕，舌鲜红有刺，苔薄而白，脉洪大而促。即与大剂白虎加黄连、黄芩，三帖，诸症悉退，改用清润养阴而瘳。", "16719": "醴陵郭君小纯，一日忽头痛而晕，不能起床。自云如被酒醉，神思不甚清爽，身如寒无寒，如热无热，两足间形顽麻，干咳欲呕，身无汗，舌无苔，尖微露红点，夜不成寐，口中涎沫多，间露苦及甜味，小舌曲而偏右，时觉梗塞，脉模糊不清。细察病情，知系冬温，而脉症不甚明了，皆由温邪侵袭经络，游行肌腠，尚未内犯，故口不甚渴，舌亦无苔，兼之脉象模糊，犹是云遮雾隐时也。为疏辛凉平剂，加入轻清宣泄之品，每日两帖。至三日，身微汗，头痛顿减，诸症亦退，苔微现黄白色，舌尖仍露红点，脉转滑数，旋覆胸膈痞满不舒，欲呕不呕，为温邪由腠理侵入膈膜，兼挟热痰使然，乃用旋覆代赭石合小陷胸并加薤白、栀子等药。三帖，胸膈宽，正拟进善后方，讵意余焰循肺系上熏而喉痛，沿胃经逆行而上下牙龈亦肿胀且痛，用玉女煎，以元参易熟地，一帖而喉恙除，龈肿亦消大半。阅日又忽胸痞，因取前旋覆赭石汤再加石膏、知母，连进七、八帖，始获全愈。上症缘病者体气素蓄湿热，故温邪袭入，以类相从，不免助桀为虐，变症所以驳杂，相机用药，未可以寻常温病例视也。", "16720": "朱君云轩，汝城人，其内政素患白带，外科以丹丸服之，大泻而口流涎沫，遍身发现疹疮，寻痊愈，已旬日矣。一日左胁及少腹痛连尾脊骨，如有物横梗，寒热往来，日夜呻吟，至不能堪。诊之，脉弦数，舌苔白而尖露红点，与小柴胡去参、枣，加木通、青皮、桔叶，二帖而痛平。因性不喜药，延至六七日后，痛复作，大便不利，知丹药留毒所致，乃以大柴胡汤下尽黑粪，并嘱以绿豆煎汤兑地浆冷服数日，即可除根，嗣即平复如初。逾旬，陡患大热大渴，微汗，头晕痛，疑为旧疾复发，促诊，脉浮洪而促，舌色鲜红。余曰：此与前症无关，乃新感冬温也。即与葱豉汤加青木香、石膏、白薇、沙参，一帖而瘳。", "16721": "窿工某，患冬温，头痛，初微恶风，时发热，微汗，医者以消风、败毒等方进，遂大热大渴，汗出如浴，头痛如劈，眩晕不能举，咽喉亦肿痛，水谷不入，时露谵语，舌鲜红有刺，无苔，脉浮数而洪，即与大剂白虎去粳米加生地、花粉、栀子，两剂，大便泄泻如沸汤下奔，诸症减十之五六。病者以腹泻疑药过凉所致，请更方。余以其愚昧无知，不与置辨，因权辞曰：症既变，方自当改易，乃疏白头翁汤加入石膏、知母、蕤参、生地、花粉等品，三帖泻止，各恙悉退，以清润养阴善后而瘳。", "16722": "窿工某，先因下窿失足，手足毁伤疼痛，伤科家已为治愈。嗣复咳嗽，往来寒热，两胁及胸膈作痛，舌苔淡白，脉弦数。审系内部蓄瘀未尽，兼感外寒所致，为疏小柴胡汤去参加桃仁、红花、荆芥炭、桂尖、赤芍、归尾、鲜桔叶等品，告以服药后，大便当下黑粪，以尽为度。服三帖，黑粪始下。踵门乞更方。询知粪色正黑，痛减大半，仍嘱将原方再进，又四帖，黑粪尽而各症皆瘳。", "16723": "木工某，患遍身重痛，头晕，身微热，冷汗不止，脉沉缓而迟，舌苔湿白，咳嗽多涎。医以败毒、香砂、二陈等方与之，不应。为疏五积散去麻黄，服二帖，冷汗、头晕、身热痛等症均愈，惟腰脊间有重痛，牵引小腹，因于方中加附片、盐水炒杜仲，又二帖而瘥。", "16724": "窿工朱某，每大便则下血如注，已一月矣。杂治不效。脉弦缓，舌苔湿白，与黄土汤加当归、白芍，以赤石脂易黄土，服三帖血止，再两帖而安。", "16725": "王某，患下血稠黏，间露里急后重，发散升补，备尝之矣，踵门乞诊。脉弦数而沉，舌鲜红而苔黄燥，与白头翁汤加僵虫、乌梅，五帖，遂霍然已。", "16726": "工人妻，年三十许，娩后十余日，恶露已尽，偶因感冒夹食，腹及胁痛。医者疑瘀血为患，以破血、降气药与之，不效，继更数医，率用桃仁、红花、三棱、莪术等品，愈治愈剧。一日医用桃仁承气煎好，进服一杯，即昏愦妄语。延诊，脉如蛛丝不绝，气息奄奄，手足如冰，汗出，面上黑气满布，口唇惨白，舌苔黑滑，即用大剂通脉四逆冷服，一帖，苏醒，厥回汗止，改用大剂附子理中汤，三帖，遂霍然已。", "16727": "清光绪癸未甲申间，吾乡数十百里内，多患阴寒白喉，或现白点，或白块满喉，饭粒可进，惟饮水及咽津则痛甚，身微热，舌苔或灰白，或浅黄而厚，如结痂状，脉多沉紧而弦，或沉缓无神。他医率用表散及寒凉，十治十死。先考独得其秘，每用通脉四逆汤奏效，甚者方中用生乌附八钱至一两，连服五六剂或七八剂而愈者，起死回生。同道中莫不骇为奇异，一遇上症，咸逊谢推荐，尝谆谆教伯章兄弟，故知之最悉。又如邵阳周某、黄某，白喉治验，皆所目见，计当时经手治愈者，不下数十百人。伯章自行医以来，经验他种白喉极多，独于以上阴寒剧症，未曾一见，不审当日何以若此之多，而先考独能于仲景《伤寒》方中探骊得珠，宜为同辈所叹服也。", "16728": "先世母梁孺人，外感夹食，泄泻日数十行，用平胃加味，泻止，已而腹胀，时欲登厕而无便，了而不了，更数医，辄进行气疏降之品，旬日不愈。适先考远适，急促归，审证究脉已，检阅前方，即怒形于色，曰：此中气下陷，胡前后医者不省乃尔。即进补中益气汤，两帖而安。", "16729": "渔庄沈迩夹风邪，咳嗽尤甚，脉形浮弦，舌滑腻，形寒，左腋刺痛。宜清肺、和络、疏风。（十一月望）", "16730": "介按：凡治风寒咳嗽，必先辛散轻开，宣肺豁痰，俾病从表入者，仍从表出，则肺气自复清肃之常，而咳嗽自除。此案是风邪于肺，肺气阻痹而肝络不和，以致左腋刺痛，脉形浮弦而咳嗽尤甚。治以清肺疏风，兼用旋覆花、丝瓜络以和络，恰是咳嗽而患腋痛之对症良剂。", "16731": "遗风郁风邪伏肺，咳嗽久累，已曾失血。脉寸浮滑，音嘶。宜清肺、疏风、化痰。防损。（四月五号癸卯十八日）", "16732": "遗风庞咳嗽日久。咽干音嘶，脉弦，舌微白，头疼。姑宜清肺、疏风。", "16733": "衙前施风邪未清，左脉浮滑，咳逆，舌薄白，头疼较差。宜止嗽、化痰、疏风。", "16734": "安昌沈风邪未尽，脉弦，舌薄白，迎风头疼，呛咳不已。宜清肺疏风为主。", "16735": "安昌叶风热头胀，脉数，气轮红，外寒内热，心悸。宜清疏为稳。（九月十二日）", "16736": "又风热未清，脉小数，不时汗出，厥阳上越则热，仍遵前法加减为妥。（九月十七日）", "16737": "又舌微黄，脉弦细数，午后寒热不清，姑宜清少阳为主。（九月二十二日）", "16738": "某带下腰疼不减，脉浮虚，夹风邪，呛咳，癸涩，牙缝出血。宜清肺疏风为主。（二月二十九日）", "16739": "介按：带脉不固，肾液未充，是以带下腰疼，兹以更感风热之邪，犯及肺胃，以致咳呛而牙缝出血。此方既清肺胃之热，复补肾液之虚，乃是欲要调经先须去病之意。", "16740": "遗风王暑风湿热，寒热交作，脉濡，舌滑微黄，脘闷欲呕。宜和中祛邪。", "16741": "阪里汪暑邪寒热，脉弦数，头疼脘闷，溲数。宜和中清邪。（七月三号丙午二十九日）", "16742": "又清解已效，脉虚细，寒热交作，午后稍瘥，舌滑白根微黄，便利。宜清暑和中。（七月六号丙午初二日）", "16743": "遗风庞暑风夹湿，寒热如疟，渴饮，溲数，脉濡右大，舌白，中心嫩黄。宜清解，防重。（八月十一号丁未二十九日）", "16744": "又寒热未除，脉弦濡，舌黄滑，腹中濯濯。姑宜清暑和中。（八月十五号戊申初三日）", "16745": "阪里汪暑风伤肺，头疼发热，汗微不出，脉右浮濡，身痛，溲数，舌微黄。宜清解，防变重。（五月十九日）", "16746": "蜀阜马，暑湿伤气，脘闷发热，脉濡，右弦细，舌滑白，溺数，恶心。宜开气分为治。（八月初四日）", "16747": "马安赵暑湿伤气，舌灰黄，汗出发热，脉虚，右濡，头目不爽，溲数。宜清热利湿为治，防重。（七月二十五号丁未十二日）", "16748": "介按：肺主皮毛，今以肺气被郁，则自汗发热而头目不爽，脉虚右濡，尤为伤暑挟湿之征。治以辛凉轻剂清解上焦，兼以渗湿，方法极是", "16749": "安昌姚暑湿伤气，呕渴身热，大便自利，脉弦濡数，舌黄滑，腹痛，症非轻藐。宜清热和中。候正。（七月十八号丁未初五日）", "16750": "又清热和中，自利呕渴悉瘥，脉濡，右弦数，舌黄滑。身热已缓，头晕耳鸣，仍遵前法加减为稳。（七月二十二号丁未初九日）", "16751": "西池余暑湿伤气，潮热，溺赤，大便如酱，脉濡细数，舌心焦黄，口甜。宜清利，防变。", "16752": "次诊潮热已退，脉左濡，右细，舌黄燥，口甜，溲溺赤，大便闭。宜泻心汤加减，防变。", "16753": "三诊舌转嫩黄尚腻，脉两手弦细，口尚甜。系脾瘅，胃钝。宜泻心汤加减。", "16754": "四诊舌色犹黄，胃气不振，脉濡，左弦细，便结，心泛。宜养胃清利，最怕变端。", "16755": "五诊舌色未清，大便稍下，饥不欲食，顷六脉虚细，胃逆恶心。湿热犹存，仍遵前法加减，不致变端无虑。", "16756": "蜀阜马冒暑受风，头疼发热，肢战，脉浮数，右关劲，脘闷气冲，咽喉如有物阻，舌微黄，根厚，症属棘手。宜防痉厥，候正。（六月初二日）", "16757": "大义汪稚孩暑风夹湿，脉浮大，舌滑白，汗多发热，渴饮。恐变惊风，姑宜清热祛邪。（又月二十四日）", "16758": "遗风庞右耳下肿，夹杂暑湿，便泻，腹痛，脉弦濡，舌根微黄。姑宜清暑和中。（六月二十四日）", "16759": "杭垣施素患痰饮，新受暑气夹湿，潮热，咳嗽气急，脉濡滑数，舌白，根微黄。姑宜清气消痰。", "16760": "遗风徐暑风热湿，呛咳，耳木，脉濡数，舌白，根微黄。神识乍愦，症势重险。宜防厥闭，候正。（七月二十四日）", "16761": "安昌李暑风夹湿，咳嗽吐血，脉寸大，舌白，根微黄，潮热。宜防瘵。（六月十二日）", "16762": "某妇伏暑呕渴发热，脉寸滑数，冲气撞脘，溲数。癸水趱迟，慎恐变端。宜泻心汤加减，候正。（十月十一号九月初二日）", "16763": "安昌余伏暑秋发，始起寒热，脉濡细，舌微白，底红，潮热，头胀，肢楚，大便不爽。姑宜清利。", "16764": "安昌顾（建记）阳明伏暑，舌焦腻，脘闷呕恶，脉弦细，暮夜烦热。症属棘手，宜防外脱内闭，候正。（八月二十四日）", "16765": "安昌高秋暑未清，脉涩滞，气机不和，神识乍愦，溺后精关不固，舌微白，腹痛，仍遵前法加减治之。（七月二十九日）", "16766": "茅蓬陈湿著经络，寒热交作，脉弦濡，舌黄滑，口渴，足跗冷彻骨中。宜宣明桂苓甘露饮加减。（三月二十九日）", "16767": "某寒热不清，脉濡数，舌滑白，咳嗽稍减，湿热阻隔气分。宜治手太阴，佐淡渗。（四月十八日）", "16768": "某咳逆已除，脉弦，舌白，根微黄，大便溏，溺赤涩。湿热蕴结。", "16769": "马安赵湿热伤气，寒热交作，肢冷，呕逆，便利，脉沉弱，舌黄滑，两边微白，脘闷。宜宣明桂苓甘露饮加减，尤防昏厥之变，候正。（六月十六日）", "16770": "遗风庞湿热寒热。脉弦濡，中痞气滞，腹痛便滑。姑宜和中利湿。", "16771": "盛陵徐中焦未和，气冲脘闷，脉滞涩，湿热蕴蓄。宜顺气和中。", "16772": "盛陵徐胃气稍振，湿犹未净，舌滑嫩黄，脉濡。腰坠。宜渗利为妥。", "16773": "安昌叶湿热未清，脉濡细，舌薄滑，午后背寒乍热。宜宣明桂苓甘露饮加减治之。", "16774": "漓渚吴舌微黄，脉细数，背寒肢木，脘中窒痹。此属湿邪。宜温胆祛邪。", "16775": "遗风李舌色黄滑，根厚，脉濡细，头晕肢楚，恶寒微热，溲数便结。宜甘露饮加减治之。（五月二十三日）", "16776": "安昌顾湿阻肺卫，脉弦，舌微黄，呃逆频频，溲溺赤。症属重险。宜宣化肺气，候正。（七月十八日）", "16777": "遗风金舌滑微黄，头胀肢懈，脉濡细，咳逆。此属湿热。宜保和丸加减治之。（六月二十二号丙午初八日）", "16778": "渔庄沈疟邪已除，脉弦濡，湿热犹存，舌滑白，屡次衄血。宜清利为稳。（五月十七日）", "16779": "安昌徐舌黄滑罩灰，脉弦濡，胃钝，跗肿溺赤。此属湿热。宜越鞠丸法加减治之。（七月十二号丙午二十七日）", "16780": "遗风胡湿热内著，脘闷便结，骨热，脉涩滞，舌厚嫩黄，足肿冷。宜清利。（六月十五日）", "16781": "遗风徐舌黄罩灰，身潮热，脉弦濡，湿热蕴于经络，便溏溺赤。姑宜清热利湿，慎恐变幻。（八月九号丁未二十七日）", "16782": "某湿热未罢，脉涩滞，舌厚微黄，足跗酸楚，脘闷。姑宜和中清利。（五月十八日）", "16783": "湿热发黄，脉涩滞，舌滑，面跗浮。症属重极。宜清利，候正。（八月初三日）朱墅田绵茵陈（三钱）大豆卷（三钱）鸡内金（三钱）冬瓜皮（三钱）赤苓（四钱）白蔻仁（八分）新会皮（钱半）生米仁（四钱）防己（钱半）滑石（四钱）光杏仁（三钱）", "16784": "西庄黄跌仆伤筋，环跳肿痹作痛，脉濡左劲，舌黄滑，湿热作泻。姑宜和络、清热、利湿。（八月十九号戊申初七日）", "16785": "介按：因跌仆伤筋而湿郁肿痹，气窒络瘀，壅闭不宣，不通而痛，故用地龙、豨莶、桑枝，以宣通脉络。又因湿胜便泄，而用健脾渗湿之剂，以清热止泻。且米仁、木瓜二味，为治湿热阻滞，以致足筋酸痛之妙品。", "16786": "遗风庞舌滑白，脉濡细，脘闷，溲溺赤，汗出津津。宜和中清利。", "16787": "盛陵徐闺女秋燥发热，脉浮数，咳嗽气急，舌微黄，渴不多饮，症非轻貌。宜防昏变，候正（九月初四日。）", "16788": "蜀阜张闺女秋燥发热，脉滑数，呛咳痰阻。症非轻貌，姑宜清燥消痰（九月十五日。）", "16789": "义桥徐秋感燥化，头晕而疼，咳逆发热，脉右浮滑，左微劲，舌黄尖红。姑宜辛凉清解（七月初四日。）", "16790": "大西庄杨童年咳嗽，已曾失血，脉细右大，舌微黄，身热火胀，此燥气内逼。宜防成损（八月十七日）", "16791": "又童年血后咳嗽较减，顷脉两手皆弦，舌尖红，头晕。宜清燥以育阴（八月二十二日。）", "16792": "介按：时令燥气，挟肝经之燥火，互相上蒸，冲肺则咳呛失血，冲脑则头晕目眩。初诊脉细右大，治在气分，所以咳嗽较减。次则治以清肝肃肺，和胃止血，俾肺气复肃降之权，则咳晕自止。此后如能再进顾松园之八仙玉液，更为稳妥。又据叶氏《幼科要略》自注云：秋燥一证。气分先受，治肺为急。若延绵数十日之久，病必入血分，又非轻浮肺药可治。须审体质证端，古谓治病当活泼泼地，如盘走珠耳。", "16793": "遗风漏风温发热咳嗽，气急不耐，脉弦数，舌厚腻。症势非轻，宜治防变（元月二十九日。）", "16794": "介按：风温先伤肺分，肺气不舒，以致咳嗽气急，脉数舌腻。治法大忌辛温汗散，宜与辛凉轻剂，肃降肺气，清解表邪。姜半夏虽能消痰止咳，尚宜慎用。", "16795": "安昌徐温邪未净，脉尚大，午后肌热，舌白滑，呛咳面浮，大便溏薄。宜养胃、清肺熄邪。", "16796": "白马山李温邪上郁，头目不爽，脉数，舌微黄，身热肢楚。宜清解为主（二月二十七日。）", "16797": "遗风庞温邪发热，神识乍清乍愦，脉滑数，口燥，咳逆，便闭。宜防变端，候正（四月十七号三月初二日。）", "16798": "又大便稍下，热犹不解，脉滑数，咳逆。宜清上焦为主，不致变端无虑（三月初四日。）", "16799": "渔庄沈（妇）癸水色尚紫，正夹温邪，咳嗽尤甚，脉浮大，舌红，头疼身热。邪热已极营络，宜清解消痰（杏月十一日。）", "16800": "介按：阴虚内热则癸水色紫，更感温邪，上犯于肺，致咳嗽身热头疼，而脉象浮大，足气分热炽，已属显然。但两热相并，易入营分，故此方于清肺止咳之中，兼顾营热为治。", "16801": "安昌顾温热言谵，脉促数，舌微黄，疹点隐约，咳逆，发热，肢战。症属棘手。宜防痉厥，候正（四月二十四号甲辰初八日。）", "16802": "盛陵龙湿温杂受，中焦格拒，脉涩滞，舌厚嫩黄，便溺不利。藉小陷胸汤，防变，候正。（五月三号甲辰十七日。）", "16803": "盛陵徐湿热温邪杂受，寒热交作，脉濡数，大便自利，舌心灰黄。宜防昏蒙之变。候正。（五月十号甲辰二十四日。）", "16804": "道墟陶湿温杂受，烦热口燥，身发疹斑，神识乍清乍愦，脉数舌黄。清窍失聪，症属棘手。宜防厥闭，候正。（五月二十三号乙巳初七日。）", "16805": "又血舍已清，泻痢较差，脉濡数，舌黄，呛咳，微热不清，胸前发斑白㾦。宜清解为主。（六月念四号丙午初十日）。", "16806": "又泻痢已瘥，身热亦退，脉濡细，脘腹胀闷，咳逆宜治，防变（七月四号丙午二十日。）", "16807": "西庄易血舍已清，脉数，气口滑，呛咳头晕，身热未退，舌黄尖红，腰疼肢楚。还防变幻，候正。（五月二十号乙巳初四日。）", "16808": "遗风徐冬温汗出发热，脉数右劲，舌心黄厚。咳逆吸短，右胁刺痛，神识乍愦。症势重险，宜防厥闭，候正（十月十二日。）", "16809": "又右胁犹痛，脉滑数，舌黄，吸粗，咳逆痰阻，神色乍愦，还防变幻。", "16810": "白马山李温热寒热，脉弦寸口芤，呛咳咽痛，舌白尖赤。症属阴虚，宜防喉燥。", "16811": "又咽痛稍瘥，脉弦右寸大，舌黄红，呛咳，寒热不清，宜防喉燥（二月十二日。）", "16812": "又咳逆稍减，自利未除，脉濡数，舌滑根焦，尚润形光，最怕变幻。（四月二十一号甲辰初五日。）", "16813": "安昌王风热目涩，头疼胃馁，脉浮弦，呛咳，便结，舌微黄。宜清疏为妥。", "16814": "又风热未净，脉弦濡，头疼已减。目涩胃馁。仍遵前法为妥（十二月十二日。）", "16815": "又胃气尚馁，脉虚细，舌微黄，夜寐少安。姑宜养胃凝神。", "16816": "盛陵徐温邪上郁，齿浮口臭，牙缝出血，脉细数，肢木。宜防牙疳。", "16817": "介按：胃脉络于上龈，大肠脉络于下龈，而胃又为五脏六腑之海，最善容纳，邪热入胃，逼动肝阳，血溢而上结于龈，转成牙疳。此方清肝凉胃，为治牙疳之良剂。", "16818": "安昌徐咳呛不已，脉弦细，口甜，舌色嫩黄。宜清肺胃以化痰。", "16819": "某咳痰不爽，脉弦，舌微白，脐下气机不运。姑宜清气消痰为主（四月念三日。）", "16820": "安昌高舌白滑，脉细数，咳嗽痰迷，咯不易出，气逆，周身骨骱痛。宜防损。（五月念三日。）", "16821": "又咳不减，喉中贮痰不爽，咳不易出，脉濡细，舌滑，头晕肢楚。宜清气熄风，利湿化痰（六月初五日）。", "16822": "某湿热酿痰，脉濡细，舌微白，咳逆，右胁刺痛，溲溺赤，腹痛。宜清气、和络、化痰。", "16823": "大西庄宋呛咳喉痒，脉弦细，舌转微白，潮热较差，食入恶心。宜清肺胃化痰。（四月十六号癸卯二十九日。）", "16824": "又潮热不清，脉弦细数，咳嗽如前，溲溺赤。宜清热、通肺、化痰，防血溢。（四月念三号甲辰初七日。）", "16825": "遗风庞咳嗽不已，脉尚虚数，胃纳已和。宜润肺以清降。（四月十二日。）", "16826": "安昌施咳嗽未除，脉小数，仍属汗出，微热已退，姑宜清肺敛液（五月一号甲辰十五日。）", "16827": "安昌王（年五十余岁）酒湿伤肺，咳嗽气急，痰稠，脉滑数，舌赤，苔薄腻。尤防变幻，候正。（八月六日丁未念四日）", "16828": "安昌李（妇）呕减热缓，呛咳渴饮，脉滑数，经停月余，小溲稍利，偶有呃逆，脘痛。宜宣肺、和中、化痰。（九月补五日。）", "16829": "又呕逆已瘥，脉小滑，经停月余，呛咳脘闷，气冲欲呕。宜清养肺胃化痰。（九月初九日。）", "16830": "又呛咳未除，舌红，潮热，脉滑数，经停，胸闷心惕。宜清养肺胃为主。（九月十三日。）", "16831": "大西庄沈（妇）气喘呛咳，右脉小数，左关弦细，舌灰黄底红，癸水不调，外寒内热，胃钝便闭。宜防血溢。（十月初九日。）", "16832": "柯桥王咳嗽较减，脉虚，左弦细，腰疼，癸涩早期，还宜前法加减为妥。", "16833": "介按：经水趱早，血热之征，脉虚腰疼，肾虚之候。咳嗽略减，是肺气略见清肃。脉虚而细，是胃液尚未恢复。故其方法，既以清养肺胃，又佐滋液补肾。", "16834": "遗风庞（妇）呛咳头晕，左脉弦细，气口搏大，形寒，钝胃，经停二月余。宜清肺胃熄风。（三月念号癸卯初二日。）", "16835": "介按：冲脉为病，气逆里急，在男子则为内疝，女子则为瘕聚。今冲脉之气上逆，犯胃则呕吐涎沫，冲肺则咳呛不止。且冲脉即是血海，隶于阳明，细揣病情，治宜镇冲养胃。兹因腹瘕呕恶，治以清肺平肝，方法极佳。如能酌用镇冲养胃之品，则奏效尤捷矣。", "16836": "渔庄沈大便已通，胃气稍振，脉虚细，舌滑白。宜养胃凝心神。（九月十二日。）", "16837": "陡舋王（妇）肝气作痛，脉弦，经闭，咳痰带红，损怯已成，非轻藐之症（六月初九日）", "16838": "安昌庞肝阳烁肺，咳痰带红，脉弦数，舌色透明，便血，防损。（二月初十日。）", "16839": "又痰红较差，脉弦劲，呛咳不已，咽痛已减。宜清肺化痰。（二月二十日。）", "16840": "又咳嗽仍属带红，脉劲数，肝阳上升。宜清降为主。（三月初七日。）", "16841": "安昌胡咳血气促，脉弦数，舌微黄，寒热交作，此木火刑肺。宜清少阳为主。", "16842": "又血已除，咳嗽气促不已，脉数，舌黄，肝火犹炽。宜清降为妥（十二月初二日。）", "16843": "介按：阳明脉络日衰则发冷，阴亏而阳不潜藏则发热，总之，肝阳横逆而血上溢，故初方以柔肝肃肺，降气凉血而获效。次方于清降之中，参用养胃，立法秩序井然。", "16844": "张溇俞咳血未除，脉数，右关弦，胸闷，舌微黄。宜清降消痰。", "16845": "安昌徐遭忿动肝，气冲咳血，脉弦细，舌微黄。姑宜清降消痰。（三月初七日。）", "16846": "安昌王阴虚内热，便结，脉细数，精关不固，咳痰带红。宜存阴为主（六月念七日）", "16847": "安昌黄肝阳烁肺，咳嗽带红，脉弦，迎风头疼，舌心光，耳鸣作痛。宜清少阳为主。", "16848": "安昌徐痰血已除，脉虚数，咳嗽不已，气逆。宜清降为主。（四月初七日。）", "16849": "安昌娄阴火上升，咳嗽气喘，著枕不耐，脉滑数，舌黄燥底赤。宜防变幻，候正。（二月七号壬寅十九日。）", "16850": "安昌叶脘痹气冲，得嗳稍舒，脉弦细，腹中有瘕，咳逆。姑宜栝蒌薤白汤主治。（三月二号壬寅十四日。）", "16851": "安昌杨肺气不宣，胸脘仍属窒痹，右脉涩，左沉弦，舌厚腻，仍遵前法加减（三月二十一号癸卯初五日。）", "16852": "长巷宋呛咳痰阻，脉濡细数，胸冷窒痹，舌微黄。宜清气化痰。", "16853": "西庄易血后咳痰不爽，脉弦，肝逆上冲，脘闷，肺气窒痹。仍遵前法加减为妥（八月念七日。）", "16854": "某肺痹气逆，呛咳稠痰，脉浮滑，耳木。姑宜清降消痰为治（八月念一日。）", "16855": "介按：肝性上升，胆脉贯耳，兹以厥阳与少阳挟稠痰而上腾，阻遏清阳，方以苦降辛通，柔肝肃肺，治法极好。", "16856": "大西庄马，病损成劳，呛咳，形寒盗汗，曾经失血，脉小数，舌黄。肺气受戕，非轻藐之症。", "16857": "又案列于前，顷脉仍属小数，咳痰脓厚带红。总之，肺气受戕，形寒，属虚劳重症。", "16858": "下方桥王症由暑湿伤气，咳嗽潮热，清窍已蒙，右脉小数，左劲，舌光红，中有白屑，津液重伤，已成虚劳，势在棘手。宜清降养胃消痰。（九月三十日。）", "16859": "蜀阜马（妇）劳嗽潮热，脉涩，左细数，舌白，中心红。经阻形怯，非轻藐之症。", "16860": "又咳嗽未除，形怯潮热，脉虚细右弦，舌微黄，脘闷便泻。究属重险之症，宜清气和中，候正（六月初九日。）", "16861": "安昌范盗汗未除，六脉虚细，舌白少津，咳嗽气促，脘痛。宜防血溢。（二月十九日。）", "16862": "又咳嗽已减，脉左虚细，右较缓，舌滑白，盗汗较差，仍遵前法加减损益。（三月十二日。）", "16863": "又前药已效，咳嗽盗汗悉减，脉虚细，舌滑白，力怯，腰跗不健，还宜前法损益为妥。（三月十九日。）", "16864": "安昌娄阳不交阴，寤不成寐，脉数右劲，舌尖赤，咳嗽气逆，胃馁。姑宜清肺、安神、化痰。（三月七号壬寅十九日。）", "16865": "渔庄沈肝阳未静，夜寐少安，脉右尚弦，左细数，呛咳，舌色如前。还宜柔肝肾以和阳为妥（杏月初四日。）", "16866": "黄公溇某呛咳心悸，夜不安寐，脉虚细，胃钝恶心。宜温胆和胃，清肺安神。", "16867": "安昌相心惕如悬，夜寐不安，脉虚细，左关细劲。舌红，偶然语蹙，姑宜补心丹加减治之。（辛亥十二月念九日。）", "16868": "安昌王晕眩并作，心悸少寐，脉劲，舌色透明，力怯跗肿。宜柔肝肾以安神。（四月四号癸卯十七日。）", "16869": "又晕眩已减，夜寐稍安，睡中汗出，脉虚，力怯，仍遵前法加减为妥。（二月念三日）", "16870": "西庄沈胃气仍钝，夜不安寐，脉濡细，舌黄滑，湿犹未罢，宜温胆汤加减。（元月十二日。）", "16871": "安昌徐湿热较减，胃纳略增，脉右弦濡，左虚细。夜寐少安，大便艰涩。宜和胃安神为妥。（六月六号乙巳二十日。）", "16872": "遗风徐血后阴耗，脉濡数，舌黄滑，湿火未清，心悸健忘，仍遵前法再进。", "16873": "某咳嗽盗汗悉瘥，左脉虚细，右劲，舌滑白，心虚悸惕。宜补心丹加减治之（三月念九日。）", "16874": "白马山李肝逆乘中，脘痛气冲，脉弦，语蹙心悸，姑宜泄降化痰。（四月二号癸卯望日。）", "16875": "又冲气未平，脉弦细，舌白，心无所主，语蹙。宜镇肝逆，凝心神。（四月六号癸卯十九日。）", "16876": "安昌徐水亏木旺，脉细劲，音低，心悸，寝寐恍惚，舌心微黄。姑宜滋水涵木，佐以凝神。（三月十四日。）", "16877": "介按：少阴之脉，循喉咙，挟舌本。今以肾液未能上承，而致音低心悸，此方宗阿胶鸡子黄汤加减，俾心肾交合，阳和阴充，则少阴之火各归其部，而诸恙自除。", "16878": "渔庄沈（妇）肝风烁肺，呛咳久累不已，右脉寸关虚细，左弦，舌心红，癸水始淡继紫。姑宜柔肝以清肺为主。（十月十三号九月初四日。）", "16879": "华川赵（妇）癸水先后不一，脉左涩右弦，舌心光，头晕音哑，此肝风烁肺。宜阿胶鸡子黄汤治之。（十一月一日。）", "16880": "安昌庞（妇）冲任内怯，带下癸涩，腰酸腹痛，脉涩细，右细数，肝风浮越，头疼牙痛。姑宜柔肝熄风为主。（六月初三日。）", "16881": "又带下未除，腹中疼痛，脉涩数，头疼牙痛悉瘥。宜柔肝、调经、涩下。（六月十四日。）", "16882": "某肝风内震，心惕，头晕，肢战，脉弦右虚，癸来夹杂腰疼。姑宜柔肝熄风，仍镇摄心神。", "16883": "安昌余大便稍润，舌根微黄，脉濡，头角筋惕作痛，此由内风浮越。姑宜清肝、熄风、渗利。（九月二十四日）", "16884": "安昌杨（妇）血虚气滞，湿热盘踞，肝逆犯胃，每癸来心泛，脉濡，腹满带下。故宜和肝调经。", "16885": "介按：此即秦越人所谓带脉为病，腰溶溶如坐水中之候也。今以带脉不固，更兼湿热盘踞，厥阴逆乘而犯胃心泛。治以和肝除湿为首要。", "16886": "大西庄黄肝逆犯胃，脘格呕恶，脉右细滞，左弦，舌色还和。宜苦辛通降为妥。（八月十四日。）", "16887": "又呕恶已除，脉弦细，舌微白，著根淡黄，湿热未净，气机不利。宜和中利湿为妥。（八月二十八日）", "16888": "渔庄沈（女）闺女便泻未除，脉弱细，呕恶已瘥，胃馁，脘闷少寐。宜养胃、和肝、凝神。", "16889": "安昌徐（妇）带下未除，脉沉弦，呕恶，舌微黄，此肝胃不和，癸水不调。宜防隔症。（杏月二十日。）", "16890": "安昌徐（妇）隔气作吐，脉左沉弦，右弦滑，经停五月，舌薄白，根稍厚。此肝逆犯胃，宜厥阴阳明同治。（五月十七日。）", "16891": "又隔气较差，脘中稍和，脉两手切来弦滑，经停五月，舌根微黄，仍遵前法加减为妥。（六月二十日。）", "16892": "介按：肝郁气逆，胃液被劫，势成隔症，故以厥阴阳明同治。但脉滑经停而兼呕吐，虽属肝胃不和，似乎妊娠之象。且治法并未通经活血。惟用和胃理气。但案中未曾叙明孕育，鄙见难以臆断。然蔻壳劫津，究宜慎用。", "16893": "梅陵钱舌滑白，脉弦紧，食入脘中窒格，此肝逆乘中，脾气失运。故宜和中疏肝。（六月二十一号丙午初八日。）", "16894": "白马山李舌滑灰黄，脘痛窒格，呕恶，汤水难入，脉弦濡，食后潮热，便闭。症属重险，宜苦辛通降。候正。", "16895": "安昌徐（妇）血虚气冲，腰腹痛，带下，背板，脉沉弦，脘中偶痛。宜养血、和胃、平肝。", "16896": "又带下未除，脉细，舌厚黄，腹痛恶心，仍遵前法加减为妥。", "16897": "介按：肾虚而带脉失于固束，则背板腰痛而带下，肝阳逆行而阻气，则脘腹作痛。总因血虚肝滞所致。故以和胃平肝，补肾养血为主，次以腹痛恶心，又参用理气之品。", "16898": "安昌李（文彬）脘痛窒极，口涌清水欲呕，脉弦，舌白，中心微黄，肢稍乍冷，宜厥阴阳明同治。（七月二十四日。）", "16899": "（又）脘痛未除，呕恶已瘥，脉弦，肝横，舌厚嫩黄。宜疏泄厥阴为治。（七月二十七日）", "16900": "又脘痛较减，脉弦，嗳气上逆，肝木未和。姑宜镇逆和胃为妥。（八月初四日）", "16901": "头蓬何脘腹联痛有瘕，脉弦细，舌白，便溺涩。症属重险，宜治防厥，候政之。（六月二十三日。）", "16902": "又脘痛未除，大便已通，脉弦细，舌腻，还宜防厥。呕逆，宜和肝胃为主，候正（六月二十五日。）", "16903": "安昌黄嗜酒湿胜，脉弦，肝横，脘腹痛，宜解酒，分消利气为主（三月初三日。）", "16904": "安昌俞脘腹联痛较减，脉弦细，腰胯坠，湿热犹存，还宜前法加减再进。（元月初七日。）", "16905": "又腹痛已缓，腰胯犹坠，背掣，脉濡细，口甜。宜和肝胃为主。（元月二十九日）", "16906": "渔庄沈脘痛较减，脉弦，舌黄根厚，寒热交作，仍遵前法加减为妥。（四月二十九日）", "16907": "大义汪脘痛已瘥，大便不快，脉弦，舌根黄厚，溲溺赤。宜启膈、和中、疏肝。（十一月三号九月二十日）", "16908": "介按：湿热阻遏清阳，而肝阳上逆，胃不下行，致大肠失于传导，小肠失于变化，而二便不爽。然脉象仍弦，故治以泄肝和胃而启膈通阳。", "16909": "某水亏木旺，脉形两手皆弦，食入脘格，脐下胀闷，暮夜手足心发热。姑宜养胃、和中清肝。（三月十二日。）", "16910": "蜀阜孙腹痛联脘，脉弦，肝横，嗳气上逆。姑宜疏肝和中。", "16911": "遗风庞营虚胃痛，脉虚，心悸，宜辛甘治之。（又月初三日。）", "16912": "又胃痛未除，脉虚左弦，心悸如悬，仍宜养血平肝（六月初八日。）", "16913": "渔庄沈秋暑内逼，腹痛如绞，大便赤不爽，脉弦濡，舌赤，呕恶，防痢。（七月二十四日。）", "16914": "渔庄沈腹痛已除，胃气较振，脉两手皆弦，肝横气滞，阴火不敛。姑宜养胃泄肝。（八月初三日。）", "16915": "安昌沈闺女腹痛欲呕，脉寸弦滑，此由寒温失调，夹食为患，咳逆。宜开提和中，防变。（九月二十二日。）", "16916": "某便泻已止，脉弦，腹痛肠鸣。姑宜清肝和中。", "16917": "安昌陈腹痛已瘥，脉弦，脘闷气冲，舌微黄，故宜顺气和中。（五月十七日）", "16918": "某腹痛较瘥，脉沉弦，头晕，仍遵前法加减为妥。（五月十三日）", "16919": "遗风王舌厚黄滑，便泻不化，脉弦濡，小便不利，此属湿热。脘闷，宜和中清利。（六月初八日。）", "16920": "安昌夏舌滑白，脉弦细，便溏，患小便不多，脘闷，气冲欲呕，藉猪苓汤加减。（三月十三日。）", "16921": "又湿热未清，腹中胀闷，脉涩滞，便泻，仍宜猪苓汤加减。", "16922": "渔庄沈（妇）便泻腹痛，右脉涩，左弦细，经停四月，腰酸带下。心泛，舌微白，咳呛。姑宜清气和中。（十月二十日。）", "16923": "介按：肝肾阴亏，带脉不固，则腰酸带下，肝阳横逆，则腹痛便泻，上乘于肺则咳嗽心泛。先以清肺扶脾，兼用理气之品，是急则治标之意。", "16924": "大西庄沈木克土便泻，气滞经阻，脉右涩左弦，舌心光，胃钝脘闷，腹中有瘕。姑宜泄木和中。（七月二十九日。）", "16925": "介按：肝阳侮胃，气聚成瘕，阳明隶于冲脉，冲脉即是血海。兹以胃被肝乘，血海亦同时为病，以致经阻。治以泄肝救胃，方极稳健可法。", "16926": "遗风庞舌黄滑，脉弦濡，便利腹痛，此属湿热。宜治防痢。（六月初九日。）", "16927": "某便泻较减，脉虚，气机不和，舌滑，宜固肾止泻，理气和中。（三月十七日。）", "16928": "渔庄沈中虚气馁，水谷酿湿，成痰作泻，左脉虚细，右弦濡，舌微黄，心肾不交，寝不成寐。宜治脾肾为主。（五月十三日。）", "16929": "朱墅杨（妇）木克土便泻腹满，脉沉涩，舌黄，心泛欲呕，癸涩，宜防腹胀。（六月二十日。）", "16930": "介按：冲隶阳明，厥阴对峙，今因肝病犯胃，则心泛欲呕，乘脾则便泻腹满，冲脉既被肝逆犯胃而受影响，则癸水难以应期而至。故治以苦辛泄降，俾肝逆稍平，胃气渐和，则诸恙自退。", "16931": "安昌马（妇）上咳下泻，形肉日削，脉弱细，经闭脘格，属棘手重症。宜法候政之。（又六月初五日。）", "16932": "某（稚孩）呕渴已瘥，脉涩滞，舌心厚，腹尚大，胃钝便滑，仍遵前法加减。（二月十一日）", "16933": "某（稚孩）腹形不减，气逆便溏，脉弦细，舌薄滑，身微热，口渴，仍宜和中分消，防疳。（六月二十四日）", "16934": "渔庄沈女孩虫气内著，腹痛乍作乍止，脉弦濡，便溏。姑宜安胃和中。（二月十五日。）", "16935": "遗风庞女孩瘄后受暑，夹食化泻，脉弦，舌黄，口渴，宜清热和中。", "16936": "又时瘄后，便泻腹痛，右脉弦，潮热似疟。宜和中清利。（七月十三号五月二十九日。）", "16937": "遗风庞便痢未除，脉弦急，气不和，舌厚黄滑，潮热。姑宜清暑和中。（八月十四号戊申初三日。）", "16938": "后马周肠澼久累，脉弦，舌滑，头晕而疼。宜黄连阿胶汤治之。（二月十二日。）", "16939": "某休息下痢，脉弦濡，跗浮脘闷，此湿热蕴蓄，宜和中清利。（三月十七日。）", "16940": "又休息下痢，圊而不爽，脉涩滞，胃钝，湿热犹存，舌微白。宜和中清利（三月二十日。）", "16941": "瓜沥杨太阴湿疟，脉弦濡细，面跗浮，食人脘中胀闷。姑宜渗湿和中（十月十七日。）", "16942": "又疟邪犹来，脉弦濡，舌滑，湿热未清，仍遵前法加减为妥。", "16943": "安昌陈气虚邪留，寒热久羁。脉虚左弦。夜寐少安。姑宜补中益气汤加减。（四月三十号甲辰十四日。）", "16944": "又益气升阳。寒热较差，脉虚，按之弦细，邪犹未净，仍遵前法加减为妥（五月九号甲辰二十三日。）", "16945": "遗风庞暑热内著，口腹不慎，化胀，脉濡左弦，舌白罩灰，呛咳脘闷，最重之症。宜分消，候正。（八月十一号丁未二十九日。）", "16946": "复诊浮肿消减，脉浮濡，舌滑白，呛咳音嘶，脘中略和。仍宜分消为稳。（八月十四号戊申初二日。）", "16947": "三诊浮肿已退，脉弦劲，呛咳音嘶，舌滑。宜清肺利湿为妥。（八月二十号戊申初八日。）", "16948": "柯桥李高年痰湿胶固，腹满，跗浮，溺少，脉濡细，舌厚腻，微灰两边白，呛咳。最重之症。（八月九号丁未二十七日。）", "16949": "盛陵徐腹中仍属胀闷，食入尤甚，脉涩滞，舌滑尖红，大便溏，跗浮，究属重极之症。（六月初五日。）", "16950": "安昌沈（厚记）湿久化肿，脉涩滞，舌滑，溲数，脾阳受伤，非轻藐之症。（八月二十九日。）", "16951": "又浮肿稍减，脉尚涩滞，舌滑，溲数，脾阳伤残，究非轻藐之症。（九月初四日。）", "16952": "后马金室女食积化肿，脉濡右大，舌滑，便溺涩。宜消食消肿。", "16953": "后马金闺女舌微黄，脉弦濡，便利稀水，浮肿已退。宜分消为稳。（八月二十九日。）", "16954": "遗风包痢后浮肿腹大，脉涩滞，舌滑白，溺少。宜和中分消。（七分十四日。）", "16955": "渔庄王伏暑湿热，脉濡，舌滑微黄，跗肿溲赤，尤宜防胀。（八月二十九日。）", "16956": "遗风金痰湿化肿，左脉濡细，右寸关弦滑，呛咳气急，胸满溺少。症非轻藐，宜治防变。", "16957": "渔庄沈（霖记）木克土化胀，两跗皆肿，脉沉弦，便泻不爽，气逆溺少，非轻藐之症。（七月初三日）", "16958": "又浮肿已退，脉虚细，腰痛，胃纳尚和。宜《金匮》肾气丸加减治之。", "16959": "又诸款悉减，脉虚，夜不安寐，临晚跗浮，嘈杂已瘥，仍遵前法加减为妥。（九月二十二日。）", "16960": "又诸款悉瘥，脉虚细，临晚跗浮酸楚。宜分消为妥。（九月二十七日。）", "16961": "又两跗犹肿，脉涩滞，面浮。宜分消，防化胀。（十月初三日。）", "16962": "上灶屠屡有遗滑，脉弦细，气滞，腹中不和，呛咳，舌微灰。宜清肺胃为主。", "16963": "某咳嗽较减，脉虚细，心肾并亏，湿未净，屡次滑精。宜清养肝肾，佐清肺渗湿。（四月十八日。）", "16964": "安昌高痰红已除，脉形小数，溺白，精关不固，溺后有淫。宜固补心肾为妥。（七月十八日。）", "16965": "渔庄沈（湘记）阴火已敛，脉虚细，心肾不交则精滑，舌白稍润。宜补心丹加减。（五月十九日）", "16966": "又精滑未除，脉细劲，舌微白，大便难，有血。宜补益润肠。（五月二十八日。）", "16967": "老埠头寿泻犹未除，左脉虚细，右濡，小便不禁。姑宜分清养阴。", "16968": "东浦陈湿热下注，溲溺赤流，脉濡右弦，舌滑跗肿。姑宜分清养阴为主。", "16969": "渔庄沈身热已退，脉弱，舌滑，小溲仍属淋漓。宜清利太阳。（八月初三日。）", "16970": "安昌茹湿热下注，小便涩痛带血，脉濡，肢冷背寒，舌黄。宜分清利湿为主。（二月十八日。）", "16971": "又湿热未清，溺后仍属有血，惟涩痛较差，脉濡，舌滑，借四物汤加减治之。（四月九号癸卯二十三日。）", "16972": "又尿血遇劳即发，脉濡细，舌黄滑，湿热蕴蓄。姑宜凉血、清热、分利。（五月十五号甲辰二十九日。）", "16973": "又尿血屡发屡瘥，脉涩数，肺气窒痹，胸次痰阻。姑宜瓜蒌薤白汤主之。（元月初八日。）", "16974": "茅蓬陈湿火下注，茎肿作痛已溃，脉弦濡，舌白厚。宜龙胆泻肝汤治之。（四月十七日。）", "16975": "长巷沈浊流未除，小便仍属涩痛，脉濡，气口滑，舌根黄，咳逆，仍遵前法加减为妥。（元月二十九日）", "16976": "东关金心肾不交，阴分尚亏，脉细数，手心热，精竭形怯，小溲乍赤。宜养阴清热为主。（七月一号五月十七日。）", "16977": "复诊养阴清热，精浊较差，脉尚细数，耳鸣，寝寐恍惚，仍遵前法加减为主。（五月二十四日。）", "16978": "安昌陈湿热郁遏，脐下胀闷，睪丸偏坠，脉涩滞，舌黄腻。宜疏利为主。（二月二十四日。）", "16979": "介按：此系七疝中之气疝，其脉涩滞，而舌黄腻，是夹湿热之候。方从《济生》橘核丸加减，确治睪丸偏大，痛引脐腹之专剂。兹又加以萆薢、赤苓、泽泻等味以利湿，用两头尖以浊导浊，治法极是。若再参用荔枝核、山楂核等味，尤为灵效，此鄙人所历验不爽者。", "16980": "某小便流浊涩痛，右脉弦细，睪丸偏坠。宜金铃子散为主。（四月初四日。）", "16981": "清水闸陈湿热下注为痔，始起下疳，脉滑数，九月身发疹痘，系是结毒。宜清解，仰希外科政之。", "16982": "渔庄沈（湘记）结喉旁及右手臂肿，溃而不敛，左脉细数，右寸关弦，不时汗出，形体怯弱。宜防疮劳。（五月初十日。）", "16983": "又疮毒未敛，脉弦细数，阴火上升，齿痛，舌白少津。宜养阴清降，防疮劳。（五月十三日。）", "16984": "又疮劳胃钝，脉虚濡，舌滑白，迩由湿热伤气，清窍不利。宜清利为妥。（又月初四日。）", "16985": "又疮劳形怯，胃气稍振，脉虚细，舌滑白，湿热犹存，仍遵前法损益。（又月初七日。）", "16986": "又诸款悉减，脉虚细，疮口未敛。宜补虚扶元为妥。（六月初九日。）", "16987": "某便泻已除，六脉涩细，癸来涩少，脘中胀闷，皆缘肝横气滞，仍遵前法损益。（八月初三日）", "16988": "介按：秦天一曰：血气之化，由于水谷，水谷盛则血气亦盛，水谷衰则血气亦衰。是水谷之海，即是阳明胃气，又是冲脉之本。故月经之本，所重在冲脉，所重在胃气，所重在心脾生化之源耳。今以胃被肝乘，失其生化之源，是癸来涩少。脘中胀闷，此方清肝和胃以养血，庶几肝逆稍平，太冲脉盛，则月事以时下矣。", "16989": "瓜沥王头晕心泛已瘥，六脉细涩。癸来腰腹联痛如刺，宜和营卫为主。（五月四号甲辰十八日。）", "16990": "西庄俞潮热不清，右脉涩，左关沉弦，大便忽泻，经停，腹中有瘕，脐下痛较缓，气转至咽，舌微黄。宜清热、养胃、和肝。", "16991": "又寒热较差，胃纳已和，右脉虚，左弦细，经停，腹中有瘕，脐下偶痛，肝木抑郁。仍宜逍遥散加减。（十一月初四日。）", "16992": "某冲任内损，腰疼背掣，脉涩细，头疼心悸，癸涩。宜柔肝、补心、调经。", "16993": "某脘闷气滞，癸涩，脉涩细，右弦，带下腰酸。宜养血和中。（又月初三日。）", "16994": "安昌包闺女月事仍闭，脉沉涩，腹痛脘闷，肢体浮肿，顷经少安。", "16995": "介按：此因血液被湿热逼出，旁流膈膜，以致肢体浮肿，经来之时，湿热乘虚而入，阻碍血脉之周流，血既凝滞，自然经闭腹痛，利水活血以行气。方法面面顾到。", "16996": "某带下腰疼，脉虚细，癸涩，腹左有瘕，病在冲任。宜柔肝调经。", "16997": "安昌顾气郁成痹，脉涩，右寸关弦，音嘶，腹痛有瘕，癸水早期。宜泄降清肝。（三月二十七日。）", "16998": "某便泻未除，舌色左边厚，癸水早期，脘闷气滞，右脉虚细，左关沉弦，肝木偏横。宜养胃、平肝、调经。（六月七号。）", "16999": "介按：便泻未除，是挟时令之湿热，癸水早期，是属肝热而不藏血之症。肝阳横逆，则脘闷气滞，而左脉沉弦，胃被肝乘，未能与冲脉生化血液，则右脉虚细，治宜双方顾到，故以养胃和血，平肝渗湿之剂。", "17000": "安昌寿血虚木旺，脉弦，右虚细，项背掣痛，癸水先后不一，脘中偶痛，夜寐少安。宜补心平肝为主。", "17001": "瓜沥王癸涩后期，脉虚左涩，腰酸带下，胃纳不旺。姑宜养胃、调经、涩下。", "17002": "介按：月经之本，所重在冲脉，而冲脉隶于阳明。今以胃纳不旺而血海渐涸，是以癸涩后期，肾虚而带脉不固，则腰酸带下。治以养胃补肾，庶几经调带止。", "17003": "瓜沥王癸涩迟滞，气冲脘闷，脉左涩，右弦滑，痰湿下注为滞。宜养血理气为主。（四月二十三号。）", "17004": "介按：湿痰下注于带脉，带脉不能约束而下浊液。但带脉又能于冲任，冲任并亏，则气冲癸涩，治以补脾肾之气。又佐舒肝之品，俾血旺气和，则诸恙自愈。", "17005": "安昌顾心悸带下，癸涩过滞，腰酸，脐下痛，脉濡涩细，迩有头疼，龈起胀泡。宜胜金丹加减。（五月二十日。）", "17006": "介按：傅青主曰：带脉横生，通于任脉，任脉直上，走于唇齿，唇齿之间，原有不断之泉，下贯任脉以化精，使任脉无热气之绕，则口中之津液，尽化为精，以入于肾矣。惟有热邪存下焦之间，则津液不能化精而反化湿也。今此案系是带任两脉，液虚热炽之象，故用胜金丹加减，借以养血清热，柔肝安神。", "17007": "遗风庞血虚嘈杂，知饥少纳，脉虚细，腰酸带下，舌色灰厚。姑宜养血、和中、平肝。", "17008": "介按：冲脉之血，系是阳明水谷所化，兹以胃液已虚，未能容纳水谷，而致知饥嘈杂。且肝肾并亏，而致腰酸带下，故以柔肝、和胃、养血为治。", "17009": "遗风庞带下腰酸，脉关尺涩细，经停七月，腹中有形，病在冲任。宜柔肝、涩下。（三月二十三日。）", "17010": "介按：任脉通，太冲脉盛，则月事以时下。兹以冲任并亏，而经停七月，肝郁不畅，则腹中有形，肾虚而带脉不固，则酸下腰带。治以柔肝涩下，即是摄冲任之意。", "17011": "黄公溇徐小腹仍属滞痛，脉尚涩，白带未除，冲任腰胯酸痛。宜和肝涩下为稳（六月七号乙巳二十二日。）", "17012": "介按：王叔和曰：带脉为病，左右绕脐，腰脊痛，冲阴股也。据是以观，则此症系是带脉失司，肝逆未平之候。", "17013": "盛陵徐冲任内怯，腰疼背掣，带下，脉涩细，癸涩不调，头疼。姑宜养血、调经、涩下。（八月二十二号戊申十四日。）", "17014": "安昌马带下如注，小腹滞痛，脉涩左弦细，癸涩不调，舌厚腻，汗出濈濈。宜疏泄厥阴为主。（四月二十八日。）", "17015": "瓜沥谢经停二月余，右脉滑数，脘格呕恶，食入即吐。宜防妊育。", "17016": "头蓬胡肝风犯胃，头疼晕眩，呕恶，脉左虚细，右稍滑，经停厌食。宜防孕育，未知然否，候正。", "17017": "渔庄沈妊育头胀，腹中气机不和，脉弦濡滑，溲弱短数，呕恶涎沫，胃钝。宜和中、理气、护胎。（五月初四日。）", "17018": "黄公溇徐小产后带下如注，脉弦细涩，脘中有形，攻触而痛，癸水不调。姑宜涩下平肝。（六月七号乙巳二十二日。）", "17019": "介按：刘宗厚曰：带下多本于阴虚阳竭，营气不升，经脉凝涩，冲气下陷，精气积滞于下焦而成。今此案系是肝经抑郁，耗及营液，以致带脉失固，冲气下陷。故小产之后，而带下如注，冲任虚气挟肝阳上逆，则脘腹作痛，治宜平肝补肾为先。", "17020": "华舍施产后湿臌，溲黄，腹满，足肿，脉滞，舌黄，症势棘手。（民国十年七月十九日。）", "17021": "又产后臌胀，舌仍黄，溲较长，脘未展，脉尚滞，症尚棘手。", "17022": "又产后臌胀，脉尚滞，溲长，舌黄，症尚棘手。（八月初五日。）", "17023": "癸涩趱迟，带注腹痛有症，左脉涩右沉弦，中脘胀闷，背掣，姑宜顺气利中平肝。", "17024": "稚孩虫气内著，腹痛作泻，脉滞滑，苔白，口渴呕恶，姑宜安胃利中。", "17025": "便泻较减，面跗浮肿不退，脉弦滑，经停，仍遵前法加减为稳。", "17026": "崩漏后，腹满气滞作痛，脉清数，腿跗浮肿，宜和营卫为主。", "17027": "宿恙夹新邪，痰壅气塞，咳嗽暮夜尤剧，脉弦苔滑，姑宜清降化痰。", "17028": "癸涩迟滞，腹中㽲痛，脉两手沉弦，苔白根微黄，带下为注，宜四物汤主治。", "17029": "咳逆痰阻，午后恶寒，脉清气口浮滑，左沉弦，癸水适至，脘闷便利，苔根黄滑，宜清解为主。", "17030": "苔根黄厚，右脉沉涩，左关弦，腹痛心涎，胃钝大便忽泻，产后载余，癸水未至，姑宜理气平肝为主。", "17031": "中焦未和，气机失利，脉两手混滞，大便稍下不畅，仍遵前法加减为妥。", "17032": "虫气作痛，腹泻肢肿面浮，脉沉细，苔白口渴，症属重极，宜利中分消。", "17033": "体虚受邪，寒热久羁，脉弦两尺虚细，苔白腰痛，宜补中益气汤加减。", "17034": "咳嗽日久，其脉象两手细数，癸水不调，周身脉络不舒，症势防入损途。", "17035": "邪客肺卫，呛咳气促，脉寸浮滑，苔白形寒，姑宜清肺疏风化痰。", "17036": "痛气滞，脉左涩，右关沉弦，苔白里半截微黄，带下如注，治在奇经。", "17037": "呛咳声重，音犹哑不扬，脉右小数，左细，苔黄络血上溢，究非轻藐之症。", "17038": "温邪未清，身热口燥，痰壅气塞，脉弦数，苔黄腻。呛咳便利，症尚重险，宜防变幻。", "17039": "呛咳稍差，胃纳略增，脉虚细，左弦已缓，苔腻肢楚，宜清肺胃化痰。", "17040": "咳痰未除，阴火不敛，脉小数，苔黄中心红，彻夜不寐，形肉日削，究属肺劳重症。", "17041": "痢下赤白，脉弦细，苔滑白尖红，小腹下坠，湿热蕴蓄，仍遵前法加减为妥。", "17042": "闺女虫气作泻，脉弦细，苔滑白，两足浮肿，势恐增剧。", "17043": "风邪袭肺，呛咳形寒，脉寸浮滑，苔微黄，胃钝肢楚，姑宜清肺化痰。", "17044": "产后瘕泻，腹中隐隐作痛，脉涩左弦，舌光，呛咳形怯，非轻藐之症。", "17045": "屡受风邪，咳嗽多痰，脉浮弦数，苔滑，宜止嗽散加减治之。", "17046": "便泻未除，经停脘闷，脉滞滑，肢体浮肿，仍遵前法加减为妥。", "17047": "小孩肝泻化肿，脉细数，唇舌均红，阴火不敛，溺少，属棘手凶危之症，勉为立法候正。", "17048": "癸来涩少，左脉涩细，右寸关弦滑，气冲脘闷心涎，苔滑腹痛，气滞作泻，姑宜和肝调经为主。", "17049": "便泻稍减，腹满有瘕，脉两手皆弦，苔薄白，经停九月，气滞如痛，仍遵前法加减为妥。", "17050": "产后冲任不固，带注腰酸，脉右涩，左关弦，腹痛有瘕，宜治奇经。", "17051": "脾泄腹痛脘闷，脉弦细，左沉涩，胃钝足跗浮，癸水趱迟，宜防肿胀。", "17052": "风湿条热，下寒身疼，肢楚气冲，脘闷欲呕，脉寸浮滑，苔黄咳逆，咽中不爽，尤宜防剧。", "17053": "肝风未静，头晕惊怖，六脉涩细，带注腰疼，子后鸣鸣便利，仍遵前法加减再进。", "17054": "心惕如悬，胸闷胃馁少谷，脉两寸关弦，舌色透明，偶觉晕眩，姑宜泄降平肝。", "17055": "脱力腰跗酸，咳痰曾患失血，脉虚细，左弦数，苔黄有小红星，搜溺赤，宜清上益下。", "17056": "气阻经隧，腹痛有瘕，脉两手弦细，脘闷便泻，带注腰疼，宜青娥丸法加减治之。", "17057": "湿热盘踞，脘闷腹痛，脉濡右弦，苔黄滑，肢体浮肿，姑宜分消利中。", "17058": "产后四月，便泻未除，腹痛已缓，脉涩弱苔滑，跗浮，嘈杂少谷，宜猪苓汤加减治之。", "17059": "苔白根微黄，脉弦细气口滑，寒热交作，肢稍不暖，形怯体虚，曾患失血，此由湿邪夹杂使然，宜治标为先。", "17060": "案列于前，咳嗽气急，脉弦细，苔白滑，胃纳不旺，姑宜泄降利胃化痰。", "17061": "脱身受邪，湿著阻气，脉弦，苔滑白，呛咳气逆，跗酸溲溺赤，姑宜清肺利湿化痰。", "17062": "湿热化疟，寒热互作，脉弦濡，食入脘中胀闷，小溲乍赤，姑宜利中祛邪。", "17063": "肝火上郁，右耳失聪，脉涩数，带注腹满，癸水不调，苔滑，宜清少阳为主。", "17064": "癸涩迟滞，腹痛胀闷，脉细滞，便泻恶心，姑宜利中。", "17065": "风湿外乘，身热恶寒，脉两寸关浮滑，呛咳身酸楚，姑宜辛凉轻解，防剧。", "17066": "虫痛尿白悉差，脉混滞，大便仍滑，脾土失运，宜防疳患。", "17067": "肺劳咳血，脉细数，苔黄，腹痛便结，胃钝背寒，究非轻藐之症。", "17068": "肝块作痛，脘中嘈杂，脉左弦右涩，癸涩带注，腰酸背制，姑宜养血平肝。", "17069": "大疟未除，呕恶脘闷，脉弦右滑，咳逆痰阻，腿跗酸楚，宜利胃化痰祛邪。", "17070": "脾泄较差，食入脘闷，脉细左关弦，癸水未至，口渴跗浮，仍遵前法加减为主。", "17071": "便泻稍减，脉两手皆细，食入脘腹胀闷，经停，防成肿胀。", "17072": "阴虚呛咳，已曾失血，咽痛音低，左脉小数右弦，苔滑白，便溏，肝横气滞，不易图治之症。", "17073": "营虚嘈杂，癸水先后不一，脉右涩左弦，带注腰坠，膻左有瘕，不明晕眩，舌心空，治在奇经。", "17074": "小孩便泻未除，脉濡滑苔腻，虫积尚存，还宜前法加减为妥。", "17075": "风湿外乘，头疼发热乍寒，脉浮数，呛咳不寐，身疼肢楚，姑宜轻解化痰。", "17076": "呛咳未除，头晕目暗，脉虚右弦滑，苔滑微灰，便结，宜清肺安神为主。", "17077": "前药已效，寒热较轻，脉弦细，苔滑白，呛咳不已，腿跗酸楚，宜建中汤加减治之。", "17078": "大腹已润，头晕呛咳未除，脉小数，右寸关弦，苔白根微黄，子后寐不安，仍遵前法，加减为妥。", "17079": "血舍未清，呛咳较减，舌心灰黄，脉小数，腹痛便下滞，仍遵前法加减为妥。", "17080": "闺女腹满气逆，脉濡左弦细，苔黄滑，尖边红，便弱不爽，颜红汗出口渴，属棘手重症。", "17081": "大疟犹来，脉虚盗汗，苔黄咳痰，四肢酸楚，宜何人饮治之。", "17082": "叠进建中汤已效，脉较有神，气口滑，溺热形寒，汗出稍饮，还宜前法加减为妥。", "17083": "苔微白，脘闷大便忽泻，脉细左弦，寒热交作，呛咳肢楚，胃钝小溲乍赤，宜活人败毒散加减治之。", "17084": "盗汗较差，呛咳已减，痰红未除，左脉虚细，右寸滑数，苔心微黄，便滑形怯，不易之症。", "17085": "苔转微白，尖边尚红，脉象两手小数，呛咳较减，音犹嘶，虑防涸阴。", "17086": "风湿发热口燥，脉浮滑数，苔黄厚，咳痰吸短，右胁刺痛，症中重险，宜防变端。", "17087": "呛咳未阴，痰不易出，脉弦细，苔滑气逆，仍遵前法加减为妥。", "17088": "湿邪侵肺，咳痰带红，脉滑数苔黄，咽痛音嘶，倏热乍寒头疼，姑宜清解化痰。", "17089": "头晕且疼，心惕肢楚，左脉沉弦，右寸转坚，苔微黄，腹满左偏有瘕，姑宜柔肝理气和中。", "17090": "清窍未和，睡即呛咳，胃气稍振，脉小数，音犹嘶，还防变幻。", "17091": "风湿发热口燥，脉数左浮滑，呛咳痰阻，左胁痛，癸水适至淋漓，大便黏滞不爽，尤防痉厥之变。", "17092": "痢已带粪，脉细数，苔红稍淡，小溲略利，咽干音嘶，宜清热解毒，不致变幻，无虑。", "17093": "肝火刑肺，咳痰带红，脉右弦滑，左逾转坚，苔黄头晕，寝寐恍惚，宜清降为主。", "17094": "呛咳稍减，经阻脐下胀闷，脉涩右弦细，舌心空，寒热交作，究属损怯之症。", "17095": "呛咳未除，音出犹嘶，脉数左弦，恶寒潮热，子后汗出则退，苔黄，尤宜防损。", "17096": "心惕较差，六脉涩细，气滞脘闷，腰胯胀，苔滑白，头晕而疼，仍遵前法加减为妥。", "17097": "足跗犹浮，脉沉弦左细，苔白口渴，虫气作痛，大便仍滑，宜安胃利中。", "17098": "泻痢未除，胃气已振，脉细右弦，每大便，肛坠作痛，舌红较和，仍遵前法加减为妥。", "17099": "心惕如悬，脉虚数，经停腰腹痛，法宜养胃柔肝。", "17100": "风湿内并，脉滞寸口浮大，苔微黄，腹痛脘闷，头疼晕眩，癸水适至，宜疏利为稳，恐变痉病。", "17101": "呕恶腹痛悉差，潮热汗微，脉弦经阻嘈杂，仍照前法加减为稳。", "17102": "寒热间日而作，已发三期，脉弦苔白，头疼咳逆，胃钝胸闷，藉清脾饮加减截之。", "17103": "经停两月，脉沉涩，咳血气促，脘中空闷，此属倒经，宜清降为主。", "17104": "心惕夜寐不安，脉细涩，中脘胀闷，腹痛已缓，癸水趱迟，五心烦热，宜养胃清热，佐以宁神。", "17105": "腹满气滞，脉弦右涩，癸水不调，宜顺气利中。", "17106": "血虚气滞，腹痛便艰，脉弦细而涩，经水有数月不至，周身脉络板掣，宜活任脉为妥。", "17107": "癸涩面带黄色，脉虚腹痛，便血脉络抽掣，宜柔肝熄风。", "17108": "腰疼带下如注，脉虚癸水趱迟，宜补血涩下为主。", "17109": "瘰疬已溃，脉弦左数，舌心空，倏热乍寒，经闭，症属重极，逍遥散加减治之。", "17110": "癸不及期，腹痛有瘕，脉弦细，带下督背掣，宜胜金丹加减。", "17111": "先腹痛而后经至，气滞为多，脉涩右沉弦，头晕腰酸，姑活血理气调经。", "17112": "呛咳不减，音出不扬，脉数左弦，寒热犹来，仍遵前法加减为妥。", "17113": "咳血较瘥，肺气不降，脉右涩数，左弦细，苔滑，脏腹痛，便清，离络之血未净，宜降气化痰利便，防剧。", "17114": "湿邪上受，始犯喉痹，脉弦数，苔灰腻，便闭外寒内热，痰黏，非轻藐之症。", "17115": "风湿外乘，头胀而痛，恶寒发热，脉寸浮滑，咳逆，姑宜开达以轻解。", "17116": "风热侵窍，两耳失聪，左脉细，右弦滑，呛咳苔白，宜清少阳为主。", "17117": "闺女腹痛，便滑脉弦，癸水不调，头疼，宜和中调经。", "17118": "闺女痛经中满，脉细涩苔白，头疼，宜活血疏风。", "17119": "产后载余，冲任内损，腹痛有瘕，脉弦细，大便忽泻，形肉日削，非轻藐之症。", "17120": "湿热阻于肺卫，脉滞细苔黄，咳逆跗酸，小溲乍赤，姑宜清肺利湿。", "17121": "癸水不调，脉虚手足酸楚，步履不耐，宜四物汤主治。", "17122": "心惕如悬，脉涩脘闷，癸来腰腹聊痛，苔厚腻，倏寒汗彻，防遂厥。", "17123": "闺女经闭，腰痛脉弦细，气滞中痞，宜活血调经为主。", "17124": "闺女晕眩心涎，脉涩寸口大，每经来腹中胀闷而痛，宜安胃熄风为主。", "17125": "癸水腹痛肢酸，按脉两手皆涩，此气阻经隧，当养血理气为主。", "17126": "癸涩迟滞而痛，脉弦右涩，带下如注，宜养血平肝调经。", "17127": "经阻腹痛，脉弦细，倏寒忽热，腹中有瘕，宜加减逍遥散治之。", "17128": "冲任内隙，脉细微，腰腹痛，带下心惕，癸涩迟滞，气滞中满，治在奇经。", "17129": "阴伤液耗成消，脉细数，舌红根薄白，渴饮善饥，溺多形肉日削，系属大症，宜存阴增液为主。", "17130": "经停数月，脉弦数，呛咳气促，已曾失血，腰腹痛，宜防损怯之虑。", "17131": "病延日久，脉小数形怯，呛咳气冲，腹中有瘕，癸涩不调，宜防损怯之虑。", "17132": "久咳经闭，脉弦细，腹痛脘闷，症属重极，宜清肺胃利中。", "17133": "久嗽苔黄少液，脉小数，背掣癸涩，宜防损怯之虑。", "17134": "咳呕较减，癸来涩少，脉虚脘闷形怯，究属重极之症，仍遵前法加减为妥。", "17135": "气逆稍缓，浮肿不减，脉涩经闭，究属棘手重症，仍照前法加减，候正。", "17136": "晕眩肢酸，脉弦滑，经停数月，呛嗽气促，睡中汗彻，宜清肺敛液为主。", "17137": "带下腰疼，脉涩气口滑，潮热气冲呛咳，癸涩，少寐，宜清肺凝神为主。", "17138": "冲任内隙，脉细微，带下腰痛，心惕呛咳，癸涩迟滞，宜六味地黄丸法加减治之。", "17139": "营虚胃痛，脉虚肢稍冷，癸水不调，宜当归桂枝汤加减。", "17140": "暑风夹湿，寒热交作，汗彻不出，脉浮弦咳逆，腰疼肢酸，法当和解，防变痉病。", "17141": "癸来腹痛联腰，脉弦虚体气滞，宜活血疏肝为主。", "17142": "肝逆犯胃，呕酸作吐，乘脾作泻，脉两关皆弦，苔白根微黄，脐下滞痛，宜治厥阴阳明。", "17143": "咳嗽未除，气冲脘闷，脉虚数，癸来涩少，宜润肺止嗽化痰。", "17144": "久嗽不已，喉有血腥，脉小数潮热，癸水不调，宜防损怯之虑。", "17145": "湿热不退，苔滑呛咳，神倦脉濡，肢酸溺赤胃钝，宜清气利湿化痰。", "17146": "肝逆稍平，脉来细涩，足跗犹酸，宜养血调经为妥。", "17147": "头晕心悸，脉虚右弦，此肝风犯胃，癸水不调，姑宜安胃熄风，佐理气调经。", "17148": "血虚生风，脉虚癸涩，身发肿块瘙痒，宜四物汤加减。", "17149": "咳嗽多痰，脉弦数，潮热胸次痛，癸水适至，宜清肺利络化痰。", "17150": "咳嗽未除，脉虚细右弦，腰疼肌体麻木，心惕，癸水月余不至，宜六味地黄丸加减治之。", "17151": "呛咳音嘶，脉虚数便泻，形怯经闭，究非轻藐之症，宜清气和中，候正。", "17152": "疾疟久累，脉弦数，呛咳癸来涩少，苔微黄盗汗，宜扶羸汤，加减治之。", "17153": "胃纳稍振，呛咳便泻不已，脉弦细，苔滑经闭，究属重险之症。", "17154": "腹痛较缓，脉弦细，经闭呛咳，宜防损怯之虑。", "17155": "上咳嗽，下便泻，癸水不调，脉弦细，最重之症。", "17156": "头疼咳逆，右脉浮滑，心涎脘闷，苔黄厚，颊车紧，经停月余，手足麻木，寒热不清，宜清肺疏风。", "17157": "癸水先后不一，脉沉涩，腹满气冲呛咳，宜清肺降气和中。", "17158": "清气和络，胸胁刺痛已减，脉寸弦滑，舌厚胃馁呛咳，仍遵前法。", "17159": "暑风夹湿，微热畏风，脉虚手尖冷，汗出不休，咳逆舌厚嫩黄，姑宜瓜蒌桂枝汤加减治之。", "17160": "苔白厚，脉两手浮弦，寒热间日而作，邪在少阳，头胀而痛，咳逆胸闷，姑宜和解为主。", "17161": "咳动肺，脉弦细，胸胁刺痛，苔色微黄，尤防血溢。", "17162": "咳嗽不已，舌红口干渴饮，脉左细右微，动溺犹多，大便始结继溏，湿热尚存，阴液耗，仍遵前法，加减再进。", "17163": "心惕已减，脉细涩，癸不及期，苔微白，仍照前法加减为妥。", "17164": "腰酸带下，脉虚细，苔白便滑，癸水不调，宜青娥丸法加减治之。", "17165": "头痛较瘥，脘中稍和，腹痛心惕，脉虚癸水不调，宜补心和中。", "17166": "内伤夹外感，脉滞寸口短，头痛心涎脘闷，癸水不调，宜治标为先。", "17167": "癸水趱迟，气冲脘闷欲呕，脉沉涩，苔白如粉，宜顺气和中。", "17168": "咳逆痰壅，寸脉滑数，癸水适至不多，苔根厚，宜清热消痰。", "17169": "前药己效，脘中胀闷已减，左脉弦，癸不及期，仍照前法加减为妥。", "17170": "肝逆乘中，当脘胀闷，脉弦气逆，癸不及期，宜防肿胀。", "17171": "血后心惕，苔白而干，脉滑数，经停三月，脘闷，宜养胃和中。", "17172": "经停吐血，脉数右寸特大，苔微黄，心惕脘闷，宜降气凉血为治。", "17173": "癸水涩少不调，脉虚细带下，便泻不已，中痞气滞，宜和中止泻为主。", "17174": "癸涩迟滞，脉涩腰疼，带下便泻中痞，宜理气和中。", "17175": "便泻腹痛悉减，脉沉涩，癸涩带下，宜和中调经为妥。", "17176": "血虚气滞，每癸来腹痛作泻，脉细涩心惕，宜五苓散主治。", "17177": "腹痛便利不减，苔黄呕恶，右脉弦滑，月事过期不至，仍照前法加减，防痢。", "17178": "癸来涩滞，脉虚细便滑，脘闷脐下不爽，宜养胃和中，佐理气下。", "17179": "癸涩迟滞，脉沉清便泻，中痞肠鸣，宜胃苓汤加减。", "17180": "便泻腹痛稍减，苔色仍属黄厚，癸涩已有二月不至，脉涩右沉弦，中痞气滞，还宜前法加减为妥。", "17181": "大便仍属不爽，脉弦左涩，癸水已至不多，头晕脘闷，仍照前法加减为妥。", "17182": "癸水先后下一，脉细涩，腹痛气滞，大便滑泻，胃钝带下，宜和中为妥。", "17183": "潮热不清，苔黄口渴，大便自利，瘄疹已现，癸水适至，脉小数，神识恍惚，宜清热祛邪。", "17184": "寒热日作，脉来弦数，心涎便利，癸水适至，宜柴平汤加减治之。", "17185": "湿郁气阻，遍体浮肿，脉沉弦右涩滞，癸涩迟滞，中痞防胀。", "17186": "湿热发黄，脉弦肝木偏横，腹臌跗浮，癸趱迟，属重极，宜鸡金散加减。", "17187": "风湿化疟，脉濡细，苔心灰，经阻腹满，头面跗浮，宜防化胀。", "17188": "脾泄化肿，脉细滞，经阻跗浮，宜利中分消为妥。", "17189": "夹气夹食化肿，脉弦中满，癸水沥，症属重险，当和营卫为主。", "17190": "肝阳犯胃，脘痛彻背，呕酸作吐，右脉细左弦，苔白痰气交阻，肢尖不煦，恐厥，宜厥阴阳明同治，佐祛瘀化痰。", "17191": "苔白脉两手皆弦，肝块作痛，癸涩已闭，大便忽泻，倏热忽寒，宜疏肝和中。", "17192": "肝逆射肺，脉弦呛咳潮热，经阻喉有血腥，宜清少阳为主。", "17193": "癸涩迟滞，脉涩左弦细，腰酸腹胀，心惕带下。此血虚木旺，姑宜养血理气平肝。", "17194": "肝逆上冲，脘痛背掣，脉沉弦癸涩，宜疏泄厥阴为主。", "17195": "肝虚晕眩目暗，脉虚癸涩，食入欲呕，宜柔肝养血。", "17196": "腹痛有形联腰，脉细涩，肢冷呕渴，癸水适来，苔厚微黄，宜治防厥，候正。", "17197": "木克土，便泻心涎，脉弦舌尖红，腹中有瘕，经闭，宜猪苓汤加减治之。", "17198": "肝逆攻冲作痛，呕恶欲厥，脉弦滞经阻，症属重极，宜厥阴阳明同治，候正。", "17199": "肝逆犯胃，腹痛作吐，脉弦微热，癸水趱迟，宜厥阴阳明同治。", "17200": "木克土化泻，脉弦细，中焦窒格，经停防胀，宜利中分消为治。", "17201": "木克土化泻，脉涩脘格，心涎欲呕，癸涩不调，宜泻心汤加减治之。", "17202": "苔白呛咳气逆，左脉弦细，头疼倏热乍寒，腹左有瘕，经停四月，胃钝防肿胀。", "17203": "木克土化泻，脉弦而涩，舌滑脘闷，带下癸涩，姑宜顺气和中。", "17204": "任脉为病，腹痛有瘕，癸水涩少，脉细涩，苔心黄，肢木心烦，宜治防厥，候正。", "17205": "肝块作痛，脉沉弦，气滞为满，癸水先后不一，大便忽泻，宜疏肝和中。", "17206": "肝逆中脘闷窒，脉弦苔厚腻，癸水不调，心惕胃钝欲呕，当和肝胃为主。", "17207": "苔黄脉涩左弦，脘腹联痛呕恶，此厥阴顺乘阳明，癸水趱迟，宜泻心汤加减治之。", "17208": "肝逆未平，中满气滞，脉细涩，腹痛经停，防肿胀。", "17209": "木克土，便泻中痞，脉沉涩，面跗浮，经阻，宜治防胀。", "17210": "木克土化泻，脉右弦，中痞气滞腹痛，舌红经阻，宜养胃和中平肝。", "17211": "头疼不已，脉浮弦，呛咳多痰，苔色微黄，恶风微寒，宜解表消痰。", "17212": "感邪未解，身热乍寒，脉浮数，苔黄滑，宜清解防剧。", "17213": "秋感化燥，呕恶发热，脉浮滑，苔黄燥呛咳，症势非轻，宜防昏蒙之变幻，候正。", "17214": "案列于前，热犹不解，脉动苔黄口燥，便痢赤色，还防痉厥，候正。", "17215": "湿阻肺卫，脉弦濡咳逆，寒热交作，脉弦濡，苔白根微黄，腹中气机不和，宜桂苓甘露饮加减治之。", "17216": "脚气犹然酸痛，脉弦濡，苔滑白心灰，姑宜祛风利湿为主。", "17217": "秋感发热乍寒，脉浮数苔黄，头胀而疼，姑宜辛凉轻解。", "17218": "暑湿伤气，苔滑白，脉濡细，腹痛泻痢溺少，宜清阳明经为主。", "17219": "稚孩湿热内著，脉弦濡身微热，腹痛坚满，大便忽泻，宜太安丸法加减治之。", "17220": "感冒发热，脉浮数，头胀痛，苔滑微黄，脘闷肢楚，宜达表为主，防剧。", "17221": "头晕目暗，夹杂痧秽，腹痛吐利，脉濡细苔黄，胃钝带下，宜治标为先。", "17222": "痰疟二期，寒多热少，脉弦苔白，邪在少阳，宜小柴胡汤加减治之。", "17223": "闺女腹痛气滞，两脉皆弦，苔白，癸水不调，宜疏肝和中。", "17224": "女孩脾疳化肿，苔白便泻，口渴，脉濡滑左弦，腹大溺少，非轻藐之症。", "17225": "苔微黄，左脉涩，右弦数，脘腹胀闷，癸水早期，咳痰，宜和中调经。", "17226": "风湿相搏，寒热如疟，左脉濡，苔白根微黄，腰痛身痛，头目皆疼，神识皆愦，宜防柔痉。", "17227": "咳痰稠白，脉沉弦，苔厚微黄，胃钝食入脘闷，姑宜清肺胃和中。", "17228": "苔黄厚，呕渴发热，脉弦数，脘格腹痛不便。此属伏暑，宜陷胸承气汤加减，防厥。", "17229": "郭鹤轩名昌年，医士也，货药于乡。甲辰夏，忽患目痛，因自知医，用黄连、山栀、菊花、薄荷之类清之，转益增剧。不得已，延余视之。观其不红至少肿，又无翳障，惟黑珠起红一点。诊其脉搏，沉数细弱，知为阴虚血热，郁于肝脏，无怪寒凉之不应也。因以杞菊地黄汤易生地而投之。一服而疼减，三服而红点除，疼全止矣。遂设席请教，乃告之曰：凡眼疾有内外之分，前人虽谓眼无火不病，然火有虚实，病有内外。如暑天酷热，天行暴肿，羞涩难开，此外症也，但用黄连、蝉蜕等洗之即可。如湿热内淫，脾胃郁火，因而攻目，必兼头晕口渴、上下眶暴肿，此内实热也。可下之。若夫不红不肿，又无翳障，断为阴热无疑。君用寒凉，截其发生之源，能无增剧乎。经云：「阴虚生内热」。又云：「乙癸同源」。又云：「壮水之主，以制阳光」。合此数者观之，其用丹溪之法必矣。若夫阴虚而寒必生翳障，转成大症，又不可同日而语矣。鹤翁乃谢不敏。", "17230": "刑部主政杨星臣，宁乡人，与余为前后同年，喘咳廿余年。每咳甚，或至晕绝不醒。医药不啻百数，而终罔获效。在星槎侍御处谈及其病，喟然长叹，忧形于色。余问君服何药？星翁云：「医家皆谓余好内阴亏，所服药皆滋补剂。年近五旬，不敢强辩，然心窃非之。」余问：「君发嗽时，面赤气急否？」曰：「实有之，不自知也。」次早星翁即来求予诊视，因诊其右寸关脉坚凝而滑，几乎搏指，余则平平。乃曰：滑者痰象也，坚凝者，痰结也，见于部寸关之间，盖顽痰结于肺胃之管。肺为清道，胃为浊道，两道为痰所壅，故甚则晕绝也。此病非汤剂可疗，非礞石滚痰丸下之不可。星翁曰：歧黄家畏礞石如砒毒，何可入口？余曰：然则先贤留此方，为毒人耶？君试服之，如误，当甘庸医杀人之罪。星翁见余言确有定见，乃市三钱服之，卧后觉胸膈烦扰，欲吐不吐，不移时，中脘漉漉，解下黑秽数碗，倦而归寝，爽适异常，至晓而若失矣。急驱车揖余，谢曰：「奇哉！奇哉！君有胆有识，三钱药去数十年之病，孙思邈之神奇，不是过也。诸医谓余阴亏，抱此不白之冤久矣，得君并雪是耻，感铭何既？」至今函劄往来，犹时时道谢也。", "17231": "星槎侍御之女，年十三，能读葩经、四子书，唐诗古文，略皆上口。写画亦颇有法度。星槎爱如拱璧。乙卯夏，偶患发热，身面皆赤。延医视之，或曰瘟疫也，用藿香正气散；或曰过食生冷，阳郁于脾也，用散火汤；或曰中暑，用香薷饮；或曰实火，用承气汤、天水散，而皆不效。急遣纪纲迎余。问曰：头痛乎？曰否，然则非瘟疫也。问腹痛吐泻乎？曰否，然则非中暑也。问扪之炙手乎？曰否。然则非脾郁也；问烦渴出汗乎？曰否，然则非实火也。余曰：既无此数者，必午后转甚也。曰然。且眼黑耳鸣也。曰然。且口干咽痛也。曰然。星槎惊曰：尚未诊脉，何了若指掌如是。余曰：此为阴虚内热，既非彼，则在此。症如是，脉必沉数，不必诊也。投以大剂归芍地黄汤，加生地、蝉蜕。二服而愈。星槎谢曰：他人诊脉，移时不放，立方之际，不胜迟疑，君寥寥数语，所见如是其捷，奏效如是其速，非绝顼聪明曷有此哉！余谢过奖。", "17232": "寅春，同乡寻管香太史，在文昌馆作团拜，申未之交忽患身疼，众以为坐久而倦也。嘱之少息，晚餐初上，竟命驾归矣，次早张太常炳堂，专车迎余，问何为？曰：管香病笃危在倾刻。其纪纲乃多年旧人，涕泣长跪，求余救主人之命，余曰：昨在会中尚同席，何至如是？因系心腹交，不暇栉沐，而往视之。四肢椎床，昏不知人，提腕诊脉，无一丝可见；按太奚，则沸如涌泉，心头突突乱动。余曰：此红痧也，症虽危，却无碍。乃刺其委中、尺泽，出黑血半盏，神气稍定。急进柴葛解肌汤灌之，因嘱众人勿动，后半日当有红紫点发于肢体，晚再进一剂，明早当再来也。越日往视，炳堂太常迎门云，君言果验，此时紫斑夹痧而发，遍身如涂，而心地清明，约无害也，已进粥矣。余惊曰，谁使食粥！痧最恶粥，恐增剧也。炳堂又惶恐自怨。逮余入，又手足乱动，烦闷颠倒矣。急取麦芽汤灌之，始少安。晚以犀角地黄汤解其热，又以小陷胸汤解其烦，越五日而病安。惟余热未清，身如束缚。余曰：血热伤阴，固应尔尔。命服滋补之剂，半月而后，安然如常矣。", "17233": "薛鹤亭侍御名呜皋，陵川人，古道照人。在吏部时掌选事，胥吏不敢欺以隐。后作御使，数条奏忤上旨，而公正无阿识者服焉。甲寅夏，其夫人患大便不通，医士或以为实热，投承气汤不效；或以为肠燥，投火麻仁亦不效；或以为食滞，投平胃散，通而旋塞。延余治之。诊其六脉微弱，右关尤甚，右尺脉细如丝。乃曰：此脾虚不能转运故也。遂立四君平胃汤，重用潞参至一两。鹤翁曰：病苦不通，塞之不转剧乎？余曰：君不识此。内经云：「塞因寒用」。盖人大小二便，全凭中气转运中气不摄，则泄泻；中气太虚，则不能下送。夫人之病，非不欲不便，盖欲便而不下也。今以四君提其中气，平胃散调其胃气，再不通者事不复为此矣。晚即照方服之，次早即便数下，肚腹空虚，精神爽健，早餐已进三碗矣。午后来信云：同内之病，已十去八九，何神若是，昨日之言，思之不得其解，愿暇时一请教也。次日即来拜谢。余曰：君未读医书，诚难下也。人之脾胃，何独不然。鹤翁曰：闻所未闻，今乃知大便不通之不无虚证也。遂与余为至交焉。", "17234": "商人穆栖桐，吾介东乡人也。在京为号中司事。体素肥胖，又兼不节饮食。夏有友人招饮，洒后出饭肆，卒然错噤，口不能言，四肢不能运动，胸腹满闭，命在旦夕，车载而归。其契友南方人，颇知医，以为瘫也，用续命汤治之，数日无效。乃转托其同事延余视之，余诊其六脉缓大，惟右关坚欲搏指，问其症，则不食、不便、不言数日矣。时指其腹，作反侧之状。余曰：瘫则瘫矣，然邪风中府，非续命汤所能疗，必先用三化汤下之，然后可疗，盖有余症也。南医意不谓然，曰：下之亦恐不动。余曰：下之不动，当不业此。因立进三化汤，留南医共守之。一饭之际，病者欲起，肠中漉漉，大解秽物数次，腹小而气定，声亦出矣。惟舌根蹇涩，语不甚可辨，伏枕视余，叩头求命。因问南医曰：何如？南医面赤如丹，转瞬间鼠窜而去。因命再服二剂，神气益清。用龟尿点其舌，言亦渐出。不十日铺东逼之归家。余在京供职，今不知其如何也。", "17235": "又有银商，忘其名，夏得痢疾，医家以为火，用承气汤下之，逐日下数十次，又一医以为虚，补之，痢下止而胸满腹胀，委顿不起。司事者惧其死，邀伊表兄某引之出铺，在寺中凭一屋居之，又十余日医药罔效。其表兄已为市殓具矣。一日午饭后其表兄来请曰：舍亲病重，恐吓不能起，闻阁下脉理清真，欲往驾，以决生死，如可敬延半月。拟即遣之还家，较胜殁于旅舍也。余随而往视，屋中臭不可近，急命舁置他处，见其合眼朦胧，转侧之，并不知矣。提腕而诊之，俱微弱沉细，然至数匀称，惟右关独大，按之搏指。乃曰：此病因食积致痢，初医下其火，未去其食也。此时必肚腹膨胀，醒时见食作呕，病虽危，不惟不即死，并可生也。其表兄曰：果尔，请治之。乃以平胃散加神曲、麦芽等类进之，至夜解下秽物极多，腹平而知人矣。越日视之，脉小而气虚。因以真人养脏汤固其痢，三剂而痢止，略进食矣。因继以人参养荣丸半月而健。余当其病时曾见二次，不识其人，越两月，有以靴帽等踵门而谢者，不知何人，入门自称乃前病痢者也。叩头不起谢曰：蒙先生再生之恩，不惟病愈，且健壮胜于往日，衔环结草所不惜也。余却其物而善遣之。", "17236": "祁寿阳相国，予告京居，素有头晕疾，每发则呕逆旋转欲跌。延医数辈，皆以为虚，参耆之类，久不离口，而病终不去。风天阴则转甚。一日雨后无事，邀余闲谈，并求一诊，见其左寸独虚，右三部俱滑而缓，并见弦象。乃曰：老师劳心过度，脾湿停痰，且时泻时止，身体重困，非燥湿祛痰不可，而古人云治痰不理脾胃，非其治也，非健脾不可。脾健则痰消，痰消则晕止，相因之势也。乃进以香砂六君子加益智、泽泻之类。五服而晕全除矣。继相国邀晚餐，席间告同乡云，头晕属痰，此语未经人道。润园为此语，吾始不信，服其药，竟去宿恙，非深明脉理，何能见及于此。余谢不敏。", "17237": "仲秋又苦臂痛，使部曹某治之，乃为部曹述前病，并道余治之之法。部曹乃因而附会曰：王某之言诚然，今之臂痛，仍系痰之为害，不早除之成瘫痪。乃以大秦艽汤进。药甫入口，痛益增，不可屈伸，次早而寝食俱废。仍使其子子禾部郎延余，急往视之，脉浮而弱，而津津有汗出，而神气清明，语言便利。乃告相国曰：此肩臂中风而痛，病极微末，部曹小题大做，用秦艽汤，岂知秦艽汤以十全大补为主，风在皮肤，以疏发腠理为要，兹用参耆固之，岂非益之痛乎。老师勿为所惑，药三进必无苦矣。因进东垣羌活胜湿汤，加威灵仙、苍术、各二钱，一进而痛减，三进而若失。越日谈及，曰：中风之言不谬，余以书名，持纸素索书者颇多，因循堆积未暇搦管，尔日无事，开窗作字，窗外多竹，适风起觉冷，晚而痛作。子言之，余忆之矣。然何以所用皆汗药？余曰：老师营心经济，医道小技，究未深考，羌活、藁本，乃太阳皮肤疏散之药，非发汗也。汗症用之者，以其能开腠理，非能动汗也。相国惊曰：此言更觉入微，医家多不识此，可谓才大于身，心细如发矣。君少年乃造诣如此，将来必歧黄中自树一帜，勉之哉！具此才思，早缀高科，老夫当避三舍。余惶愧而退。在陕需次时，相国来书，尚称之不已。", "17238": "商友王定安庵，幼在京，权子母，工于心计而贪诈猬锁，兼嗜面食，年四十后，得脾劳病，遇冬更甚，医药数年矣。余常劝其节食节劳，而以经营生息，刻无暇晷。每食过饱，则痰嗽喘满，终夜不寝。壬子冬，疾增剧，乃俯余治。余进以健脾诸品，痰嗽少止，而狂啖如故，因之时发时愈。病甚则服药，稍痊则不肯，余以其不能调摄，置之不问。年终，风事匆匆，劳扰更甚，一日早起，则面目四肢俱浮肿，而烦满益不堪，余告其同事曰：脾绝矣。尚未立春，虽交木令，尚可到家，立春后则不能矣。盖肝木克脾土，促春必难过也。同事者不为意，延之。继请一同乡医视之，则曰：此水病，下之则愈矣。问用何药？则曰：舟车丸。余力陈不可，而病者误信之，急服三钱，肿未减，而卧不能兴。诊其脉若有若无。同事惟恐其殁于铺，急觅车傅人送还，出京甫数日，殁于松林店。计其时，立春后五日也。吁！人生固有命，而始则不知爱养，继则不信良言，迨疾不可为，又信庸医，以速成其烈属，亦愚之甚至矣。故录之，以为不知调摄者戒。", "17239": "茶商某，忘其名，在都中，夏得疟病。医药数进，而午后必寒战经时许。沉绵者数月，渐至体肤削减，饮食少进，出入随人扶掖，又年过五旬，获利不丰，家无子嗣，言必长叹，已不作生活计矣。适秋间，余到其铺，有契友田时甫扶之来求余治。见其面若败灰，气息仅属，诊其脉，则六部皆沉细迟微，右关更不三至。乃曰：此固疟疾，然疟系外感，初发时，解之清之，无不愈者。君病时所服，必草果，常山等劫药，中气本属虚寒，再克伐之，必无痊日。此时满腹虚寒，中气大馁，仍作疟疾治，是速其毙也。时甫曰：尚可治否？乃云：六脉虽虚，毫无坏象，何至不治。因进以附子理中汤，越日而寒战去。再进以补中益气汤加白芍、白蔻、肉桂数种。五日而饮食进，半月后如常矣。", "17240": "裕州刺史李莲舫，幼与余为文字交，以辛亥孝廉由议叙得州牧，在京候选，与余同住襄陵会馆，寝馈共之，每日与各相好宴乐，暮出夜归，风寒外感，且数中煤烟毒最可畏。一日余卧中夜尚来起，其弟小园促之曰：家兄病甚，速请一视。余急披衣视之，浑身颤汗，转侧不安。问之，则胸中烦闷特甚，欲吐不吐，且心头突突动。急提左手诊之，则平平无病状，余曰：病不在此也。易而诊右，脉寸关滑而泉涌。乃曰：此酒肉内薰，风寒外搏，且晚间煤火，渐而生痰。乃以二陈汤加麦芽、山楂、神曲，并芩、连、枳实等立进之，刻许安卧，至巳刻急起如厕，洞下红黄色秽物数次，午后胸平气定，进粥一盂。又欲趋车外出与友人作消寒之会，余急止之曰，朝来颠倒之苦竟忘之耶。一笑而罢。", "17241": "后腊月莲舫西归，余移与小园同榻，一日天未明，闻小呻吟甚急，起而视之，病症脉象与莲舫无少区别。乃曰：君家昆玉，真是不愧，乃以治莲舫之药治之，所下与莲舫同，其愈之速亦同。晚间其仆乘间言曰，家主兄弟之病，幸老爷一人治之，若再易一医，必别生枝节，支曼不清矣。其言近阅历者，乃首颔之。", "17242": "伶人某，忘其名，四喜部名旦也，六月初，演泗州城剧，众称善。有某官爱其艺，又出钱命演卖武一折，身体束缚，刀矛剑戟之类，旋舞越二时许，卸妆入后台，则大吐不已，腹中绞痛，急载归家，吐止而昏不知人，推之不醒。其师怒，遣人寻某官，某官知余名，又转同乡请余诊视，乃偕之往，则剩粉残脂，犹晕面颊，汗出如油，气息促迫，呼之不应。提其腕，则六脉浮濡，按之反不见。余曰：此中署阳邪也，命守者以热鞋熨其脐，刻许，稍醒。逐以大剂香薷饮进之，二日而安。后三日，有投小片者，不知其人，问阍人，乃知其伶来谢也，余却而避之。", "17243": "商友梁某，素有痔，兼好鸦片，发则痛不能起，且有隐疾，未尝告人。一日痔发，不可忍，延一南医治之。梁素弱，面目削瘦，饮食不思，南医以为虚也。用桂附补之，二日而腹膨如鼓，烦闷不安，因而痔益增痛。急延余往视之，脉细数而有力。余曰：阴亏血热，且增烦躁，故痔作。鸦片最燥肺，肺主气，气燥而血亦不润矣。再以桂附火之，无怪其增痛也。", "17244": "穆某之副伙，忘其姓名。素有呕血疾。因见穆某病危，铺事纷集，以急躁故，呕血转甚，亦求余冶。余问曾服药否？曰，药不离口者数年矣。而作发无时,见逆事则益甚。为诊其脉，并不甚虚，左关弦滑如涌，且有坚象。余曰，此肝郁也。君初得病时，必因暴怒，此后必胁间时时刺痛，甚则呕，色必紫黯。曰诚然，先生何如见也？乃以左金丸合颠倒木金散（郁金木香）解其郁，继用逍遥散舒其肝，命常服养血平肝之剂，戒其忿怒。一月而后酒肉来谢，余却而问其病，曰：服逍遥散后，已胸胁宽舒，血归乌有，先生命长服之药，不欲服也。余听之。", "17245": "马景波孝廉，与余为文字交，又同出龙兰簃先生门下，故称莫逆。乙卯谋纳粟作宰，都中有女校书才色超群，马昵之。一日余赴同乡之饮，在前门酒市，席未半，景波遣其仆，趋车迎余曰：家主得暴疾，危在顷刻，亟请视之。余颇惊骇，乃投箸登车而去，曲折经数处，见非景波所栖止。因问其车夫，车夫扬鞭掉臂曰：老爷至则自知。到陕西巷则景波依闾已久，捐余曰：校书病甚，惟恐君不来，故托于余以速之，急请入一施汤剂。余乃知为校书病。入其室，数媪环守之。启衾看，则校书篷首赤体，昏不识人。扪其肌，热可烙手，面赤气粗，颠倒烦乱．提腕诊之，六脉浮数，几乎七至。乃曰：此外感风热也，一发可愈。乃开防风通圣散易麻黄以桂枝。景波争曰；硝黄劫药，校书娇姿恐不堪。余曰：君情深如此，宜校书之倾倒，然君解怜香，我岂好碎玉耶，有病则病当之，保无恐。急遣下走货药，煎而进之。属曰：三更后，当大汗，渴，勿多与饮，明早必愈，我去矣。", "17246": "庚戌春，余以选拔赴廷试，有同年张君，久雨之后，兼嗜茶饮，六月初患小便不通，数日而手足渐肿，渐至喘咳不能卧。有其同县人商于京，颇知医，告之曰：此阳虚水肿病也。少年酒色过度，精气内虚，非金匮肾气丸不可。张信之，服未一两，肿愈甚，喘亦增，转侧需人，自以为不可救药矣。有同乡荐余往视，六脉俱伏，目睁睁不得合，乃曰：此谓水肿信不谬，而阳则不虚，盖由湿热相搏，水不由小便去，泛于皮肤，故作肿耳．实证而补之，焉有好处！且病即虚，而古人云，急则治其标。先消水泻肿，后补其虚，乃为正路。今以补虚为泻水，非通之，乃塞之也。命市舟车神佑丸（方：二丑大黄甘遂大戟芫花青皮桔红槟榔）服之，四钱而小便泉涌，越两日而肿消喘定，又命服桔半枳术丸（方：桔皮半夏炒枳实白术）半斤，而全愈矣。", "17247": "常少张炳堂同乡，甲寅得疝病，肾囊重坠，膀胱时作痛楚，适入值圆明园，出城门路砌以石，长数十里，行者车倾侧，车中人四肢竭力支持，多以为苦。炳翁一往返，疝痛甚，肾囊欲肿。延医视之，仓卒不暇细诘病状。因曰：肾囊肿多是湿热下陷，利水清火痛自除。炳翁于歧黄素愦愦，急服其药，痛增甚，腰胁不可屈伸。乃命余视，诊其脉象沉迟，季肋丸丸，直上直下。乃曰，此寒疝也，病由肝气凝结，胁下如柱，非温血养胁不可，利水清火，不增甚何为。乃为合茴香丸一料送之，服未一两而痛减。适有盛京视学之命，炳翁即束装出关。冬季来函，则曰，药已服完，疝不再发，余犹以温养告之云。", "17248": "同年娄丙卿，壬子捷南宫（礼部考试告捷），得庶常（官名），亦寓于三忠祠。素有唾血疾，人不知也。一日宵坐，其仆携汤药来饮之。因问君何病，所服何药。丙卿曰：弟有血疾，经数年矣，医药不啻百辈，竟无效。昨遇医士，以为肺金受火伤，赐一方服之。虽不甚效，然尚平平无大误，弟觉病非旦夕病，故药亦无旦夕效也。余请一诊视，丙卿曰，润翁解此乎？相处不知，几交臂失之。乃伸其腕，觉六脉沉细而数，脾部尤甚，而肺部却浮短而涩，非病脉也。乃告曰：君所患为阴亏生内热，兼思虑伤脾，脾不统血，故午后有时发热，水泛为痰，或梦遗失精，怔忡惊悸，然否？丙卿曰，所言之证，无毫发差，当作何治？乃视其所服之方，则救肺饮也。告曰，君病在脾肾两经，与肺并无干预，果肺病，当喘咳。君不喘咳，而以紫苑、兜铃凉之，是诛伐无过也。久而肺寒气馁，则成瘵矣。此时夏令，宜常服麦味地黄丸。令金水相生，水升火降，血亦当少止。秋后以人参归脾丸摄之，不过二斤，保无病矣。丙卿乃买麦味丸服之。五日后，热退神清，唾少止，继以归脾丸。至仲秋后分手时，则血全止而无病矣。次年散馆作武邑宰，秋寄函问余，有曰：自服君药，顿去沉屙，怀念良朋，时形梦寐，每公余独坐，犹忆握腕清谈时也。余复谢焉。", "17249": "少司成马介樵所狎伶人（戏子）名阿二，秋后发疟疾，寒多热少，精神困惫。介翁亦知医，云是虚寒，施桂附补之，疟不少减，而转寒为热，发则烦渴汗出。一日有友人在吟秀堂招饮，介翁命呼阿二车载以来，则坐立不能自主。介翁云：今日招尔非为侑酒，王老精于医，拟令去尔病也。阿二请安将叩头，余日：病体如此，何必拘拘。诊其脉，则浮而缓，沉取之，内甚实。乃告介翁曰，疟疾是外感病，阿二内有积热，外伤于风，须先解其表，后清其热。用桂附似未当，乃命服五积散（方：白芷川芎甘草当归肉桂芍药半夏陈皮桔梗麻黄苍术干姜厚朴枳壳生姜）。以桂枝易麻黄。二日疟少止，而烦渴依然，又进以桂枝白虎汤，十日而全清矣。后在文昌馆文宴，阿二在三庆部，晚饭后，专为余演桂花亭一折。情深文明，的是佳剧。后余呼之必来，虽极忙促时，必勿勿一至也。", "17250": "里中段某之妻，年廿余，忽患昏乱，浑身颤汗，口蹇不能言，腹中满闷，颠倒欲绝。其家以为祟，招女巫驱之。女巫多索粟帛，用香褚祈禳之，病不减。三日后，求余视之，诊其六脉乱动，沸如泉涌，且手足乍屈乍伸，不可把握。乃告之曰，此风痰也。少年气盛，下之则愈。乃命服祛风至宝丹（滑石川芎当归甘草白芍防风白术石膏黄芩桔梗熟地天麻人参羌活独活栀子连翘薄荷麻黄大黄芒硝川连黄柏细辛全蝎）。至晚则大便出红黄秽物数筒，次早而安。又请往视，六脉俱平，神气清爽。告曰，病已去，不必服药，但避风寒，节饮食，不久痊愈。半月后酒肉来谢，余知其贫，却之。", "17251": "友人盂嘻之妻，年四十余，新产后，患腹中块痛。延余诊视，按其两脉实大而坚，知非吉象，而以至好，不便明言。乃聊以人参泽兰汤进，服之未效。又请余冶，余曰，痛不减，则药不效，请延他医视之。盂不肯，至余门者日三四次。不得已，实告曰，产后之脉，宜缓宜小，今见坚大，恐难愈也。盂曰：试再进一方，万一不愈，亦不敢怨。余曰：岂在怨不怨，但竭力经营，徒费钱无益耳。盂忧疑而去。凡更十数医，无毫发效，五十余日而殁。", "17252": "内人之妹适武举张某之长子，产后患心胃痛。发则饮食俱绝，气促口干。其翁延人视之，皆曰虚，况产妇尤无实症，当培其气血，气血流通，则痛止。始服八珍汤，继服十全大补汤，月余不止。乃来外家求余治。诊其左寸关脉，坚凝而涩，知为瘀血停于胸膈。乃曰，胸膈痛，非心胃痛也。发则内如针刺，口渴气喘，宜散瘀以定痛，不宜补气以益瘀也。前服多补药，何能有效。乃命服失笑散二剂，而痛若失。三日后视之，则其儿始岁余，手足发热，神痴气粗，乳食不进，喉中时时如锯声，众以为惊风，延一邻媪针灸之。余曰：此痰也，针灸则益甚，必平日多置暧处，其母卧而乳之所致也。瞩服白玉饼（方：滑石半夏巴霜朱砂苦矾各一钱神曲糊为丸，滑石为衣）数粒，至晚则下绿色粪如许，乳食进热退而安。后返其家未逾月，乃婿忽来，下车入门，面目黑腻，胸高气喘。问系吐血疾，自言心中时时作呕，两胁刺痛发咳。来求治之。诊其脉弦而滑，乃曰：此气秘也，必有大遂事，暴怒伤肝，乃致是疾。张曰：然。余曰：曾施治否？张曰：有村医以余为阴亏，命服地黄汤，转增腹张，乃辞，而求阁下。余为开苏子降气汤，又开逍遥散方，付之曰：路远病劳，归先服降气汤，气当舒，再服逍遥散，血当止，十数日保无恙，无烦再来也。张谢而去，如言服之，月余，遣人来言，主人病痊愈，恐在念，令小人先告知，有暇必衣冠来谢也，余固止之。", "17253": "肝郁气逆脉不应病", "17254": "同谱王丹文茂才之父，余执子侄礼，少游江湖，权子母，工于心计，故握算持筹资无少缺。晚年出资在永宁州生息，忽为典商负千金，州郡控诉，未获归赵，忧郁而病，兼家务多舛，遂得气逆症。腹满身痛，转侧不安。他医投补剂，转增剧。丹文邀余诊视，其脉多伏，惟肝部沉坚而涩，且三二至辄一息。知力肝郁，因以苏子降气汤合左金丸进，三服而气稍舒。又视之，肝部有长象，又益颠倒木金散进之，十剂后，腹减而气舒，饮食进，精神作矣。一日留晚餐，座中仍令诊之，脉息如故，余未便明言，归语家人云：三伯肝脏已绝，病恐不起。家人曰，已愈矣，何害？余曰，此脉不关此病，此病易愈，此脉不可转也。况见肝脏，必死于立春前后。家人以余故神其说，置不信，余遂北上。至冬病作，竟医药无效，于腊月廿四日终于家。余由京归，家人语其事，咸诧异焉。", "17255": "丙辰春，余需次入秦，西安守沈小梅，余内阁前辈也。时税骖，即召余入谳局，昕夕相从，蒙其奖拔，信足感也。是年至四月不雨，至于六月旱甚，大吏忧之，谋所以祈雨者，星甫年伯以八卦坛进。遂延僧道数十人讽经设醮。派余及州县数人监其事。小梅素壮，自是夙兴夜寐，奔走不惶，兼旱天酷暑，事务增烦，遂得热病，烦躁不安，精神昏瞀。余在雨坛未知其事，越日，小梅不来，问两首县则曰：太尊病两日矣。问何病，两县不能悉言。次候补府何保如仆从而来曰：小梅之病甚危，外似实症，内实虚寒，已进桂附理中汤，不知可获效否？因问其脉，保如以微对。余心窃以为不然。而未知形症，不敢辨也。盖小梅浙人，保如亦苏产，恐俗医误事，故延保如治之。次日，星甫惶恐而来曰，小梅病危在旦夕，昨服药后，益僵不能动，仅存余息而已。余告同人恐不至此，小梅病当是药误，急登舆而视之。至署，则阁家环泣，幕僚咸啧啧耳语。余急止之曰：病才数日，未必不可治，请一视之。其子似竹，急揖余曰：老伯既解此，宜施拯救，前实不知。随入视之，小梅横卧，呼之不知，面汗出如油腻，气息粗急，视其腹，浑身如赤，按之鼓甚，且鼻有血涕，两目白珠全红，口吻肿破，舌强不可卷伸。问饮食乎？曰，不食三日矣，惟饮水而嫌热。问二便乎？曰，点滴全无。诊其脉则丝毫不见，而血络棱起带紫色。乃告其家人，此实热内郁，外伤于暑。保翁误认为虚寒，投以桂附，若再服，则九窍出血，遍体紫黑而毙矣！幸气息尚盛，虽危尚可治，勿忧也。为立一方，以大承气汤，白虎汤，六一散合之。其幕孙桂珊曰：南人畏大黄石膏如鸠毒，今用至数两之多，恐虎狼之性戕人命也？余曰，病势至重，轻剂断不能达。孙曰，南人脾胃虚弱，不比北人强壮，宜少减之。余不得已请之曰：古人留石膏大黄专为北人耶？抑为天下后世耶？君如此多疑，以为可，则进，不可，则否，余不能误人性命，急拂衣而起。其家见余言激切，急煎服之。而其子留余不使出署，越二刻许，小梅呻吟求凉水，目开而语出。家人禁其饮凉，余曰，尽饮之无伤也，乃饮凉水两碗。刻许，而呼小便，下如血。余曰：何如？至晚，则胸腹雷鸣，下黑粪数十粒，精神渐爽。家人共喜，急告以故，次早肩舆迎余，握余手曰，蒙君再生，感激无既，前药尚可服否？余曰，一服始通，病尚未清，连服三四乃可，君何怯焉。凡五服，而病全除。数日后，小梅问余曰，大黄素实不敢沾口，今借此得愈，深为南人卖。余曰，前辈固南人，而京居十数年，脾胃亦与北人等。况医之一道，认病为先，不必存南北之见。小梅又欲服参补虚。余曰，本不虚，何容补。如参茸能壮人，则神农，后稷，何不教人食参茸而食五谷乎？小梅拍案曰，痛快之论，得未曾有闻者，咸首肯焉。", "17256": "小梅之次媳，初秋忽患项脖肿痛，延一医视之曰：此厥阴瘰疠也。外贴羔药，内服疏肝解郁之剂，五六日来并无功效。其夫似竹延余视之，见其高肿焮红，按之坚凝，知非瘰疠。问初发时寒热否？曰，不但寒热，并带头疼，且头目眩掉，时时有汗出。按其脉，两寸浮数。乃曰，此发颐病，并非瘰疠。盖内蕴积热，外伤于风，以致火郁经络，四体不舒，骨节烦痛，若作瘰疠治，失之万里矣。且贴膏敷药，势将破溃，遂至缠绵，愈且无日，急命去其膏，用通草汤洗净，投以连翘败毒饮，越日而痛止，再服而肿消，五日后全清矣。", "17257": "泾阳令周备三之岳母，并其内嫂，两代孀居，食息仰给于周。一日谳局公退，备三邀余曰，舍亲病甚，乞往视之。余随至其家，问何病？备三曰，家岳浑身发热，烦渴汗出，胸满便闭，腹中增痛。内嫂患肚腹闷胀，有时而痛，不热不渴，四肢无力，精神困倦，饮食不思。余两诊其脉，其岳母则沉而数，右关坚大，其内嫂则六部迟缓，右关尤甚。乃告之曰，二症老少悬殊，老者胃热；少者脾寒。热者宜下；寒者宜温。遂令其岳母服调胃承气汤，其内嫂服桂附理中汤。备三曰，下则用芒硝大黄，补则用肉桂附子，二症虽殊，不该迳庭若此，少缓之何如？余曰，泰水病若实火内攻，缓之恐发狂疾。内嫂脾上弱极，缓之必成泄泻。急救之尚恐不及，况敢犹预。备三曰，唯唯，余辞而出。过数日，问两病何如？备三曰，二病俱有小效，然未全愈。余骇曰，服硝黄而不下，服桂附而不振，难道热者怀铁石？寒者成痨瘵耶？备三笑曰，前日之方，实恐太峻，君去后承气汤去硝黄，理中汤去附子。谚云：「当迟不当错，非药不效也。」余曰，令亲何拘之深，药病相投，如机缄之对发，过则为害少则不及，此间分隙不容毫发，何得私意抽添。请照方服之，错则我当之，必无害也，备三乃可原方进。次日其岳母下燥粪，火退而身清矣。其内嫂腹痛递减，饮食少思。又延余往视，余曰，令岳母病已去，不必服药，唯令调摄保无虞。令内嫂则此药非十数剂不可，且须常服温中理脾诸药，方无反复，非旦夕可望也，余辞去。一月后，以宫绢酒点八物来谢，余与备三为莫逆，乃封还之。", "17258": "备三之夫人，工诗善画，刺绣尤冠一时，人亦风流自喜，词辩滔滔。余在备三处闲谈，诸寅作斗叶之戏，余不喜此事作壁上观，晚餐甫设，有媪自内出，启备三日，太太不知何故，忽患心烦发呕，坐卧不安，闻王大老善医，急请入视。余偕备三入，则二婢扶坐，粉汗淫淫，作捧心状。急诊其脉，脾部细弱，左寸滑数特甚。乃曰，夫人所患是脾虚停痰症也。盖由思虑伤脾，饮食不化，平日必有健忘惊悸之疾。此时痰涎绕心包络，故烦呕交作。须先清其痰，后理其脾。清痰须用莲子清心饮（黄芩麦冬地骨皮车前子甘草石莲子人参黄耆茯苓），理脾须用人参归脾丸。病以渐来，亦以渐去，旦夕难全愈也。乃先以清心饮投之，二日而烦呕止。再进归脾汤，十日而四视之，病若失矣。", "17259": "典史宋晓岚，同乡也。丙辰春，与余同携眷入秦。将至临潼，其孙女甫周岁，坐车为雨泥所滑，女失手坠车下，轮辗其腹，顷刻而毙，亦气数也。其媳以恸女故，日切悲哀，兼介入，安土重迁，乡思颇切，晓岚尤吝于财，虽宦游而饮食衣服，不遂妇愿。至夏忽患胸胁大痛，喘嗽不宁，饮食俱减。晓岚来求治余，诊其左脉弦而牢，右寸坚而滑，知为气郁，乃以左金丸合颠倒木金散进。二服后，吐痰涎数碗，再视之，则左少软，而右亦渐乎矣。因以逍遥散加木香青皮等叠进之，半月后始就平复。因劝晓岚曰，儿女情怀，须少宽假。前日之病，久则成癫，若不去其痰，遥遥千里，携带而来，竞成废人，不悔之甚乎。晓岚遵之，辞色稍温，三月后，如居故土矣。", "17260": "劳倦失眠脉坏难治", "17261": "商州牧赵笏山同乡，崞县人。以进士宰秦中，所至有政声，丙辰夏，以天旱祈雨，夜作早兴，又商地皆山，每祷出入崎岖甚苦。秋末忽病，商僻地少医，遣干仆入省，求余往治。余以需次人，不敢私出省，同乡武芝田观察，言于抚军吴仲容先生，乃治任随之，越秦岭而视焉。至其署，笏山尚危坐，议论风生。问何病？曰，夜不瞑目者廿日矣。问何所苦？则曰，胸满气急，饮食不思。茶后诊之，六脉俱形沉数，而右关毫无神气，乍沉乍浮，乍缓乍急，且二至而一息。余以脉非吉象，不便明言，乃曰，君所患为心火上炎，心肾不交故也。急滋阴以壮水，则得寐、笏山急索一方，乃以地黄汤加生地、桔梗进之。药下二刻，倦而就枕，沉沉酣睡，晨钟动方起。请余入曰，真仙丹也。前屡服天王补心丹，以为睡觉良药，而竟不寐。今服君药，彻夜常眠，披衣而起，如释重负，弟病虽危，有阁下神手当无恐也。再诊之，脉似稍起，而右关依然。乃进七味都气汤，又开香砂六君汤敷衍之。亟欲归省，而笏山再三款留，不得已为延三日。临行笏山食亦少进，起坐颇自如，嘱余笔论其病，余乃书曰；金水不生，脾胃枯竭，室欲惜精，少思淡食，一阳始生，病将自绝。笏山铭之。余归途无事，戏作挽联云：「越秦岭而视君，愧余寡术。牧商山而怀古，想尔同仙。」入省后，芝田问笏山之病何如？余曰：必不起！曰；何故？曰：脉已败坏，焉得不死。因告以已作挽联，同人皆笑，芝田阴为料理身后，至十一月二十四日殁于署。其弟来省交代，余即书前联挽之，并道及论病数语。其弟憬然曰：阁下何神哉！叩头而去，扶柩归焉。", "17262": "同乡张文泉司马，于余为同谱弟，丙辰春，先后入秦需次，公余则酒宴过从，其戚乔其亦介人，为楚郧阳府经，以提饷来秦，馆于文泉之室，文泉厚遇之。而乔鄙甚，饮食之外索洋烟，洋烟之外索衣服。又索小费。文泉稍拂之，则裂眦负气。久而不堪其扰，拟遣之去，又以军饷未齐，迟迟两月，临行诟谇百端，几乎握拳相向。文泉素讷于言，不能发泄，心甚恚之。一日由咸宁过余，余留晚餐，言次文泉含泪欲滴，余劝以不仁之人无可计较，既去矣，置之可也。文泉归馆，则气急腹痛，呕吐大作。急遣车邀余，至则痰涎溢地，犹张口作吐状，汗出如流，面带青色。诊之，则六脉俱伏。乃日，此气郁而逆也，甚则发厥，急命捣生姜汁半碗灌之，刻许而吐定，然胸腹闷乱，转侧难安。乃以越鞠丸合顺气汤进之，至天明而腹舒，仍命服顺气汤，三日而愈。", "17263": "邻人刘锡庆，商于楚，年三十余无子，父母共忧之。娶妻数年，百方调补终莫效。一日刘忽患腹痛，邀余往视。众以为霍乱，服霍香正气散不效。诊其六脉沉弱，知为阴虚。因曰，君腹痛必喜按，且时作时止，非常病也，且痛发必在脐下。刘曰，然。乃投以七味都气汤(方：熟地山芋山药丹皮泽泻茯苓五味子)加肉桂二钱，两服而痛止。归后家人问其病，余曰，此阴虚血弱，腹痛易治，惟两尺细仅如丝，毫无胃气，恐命之不久也。越年许，余白京师归，已于数月前，以瘵终矣。刘本孤子，家极贫，以刘贾少裕，刘殁后双亲衰独，抚养无人，兼两餐不继。见者皆恻恻云。", "17264": "介之罗王庄张冠英，家称小有，继娶吾里中李姓女。得腿病，骨节痛楚，不可屈伸，且时作肿，卧床已半年矣延医视之，或以为下痿，用虎潜丸（方：炒黄柏炒知母熟地龟板陈皮白芍锁阳虎骨干姜牛膝当归羊肉）补之；或以为瘫痪，用续命汤散之。皆不效。其内弟请余往治。余诊六脉缓大。告之曰，既非下痿，亦非瘫痪。所患乃寒湿下注，关节不灵，肿痛必在关节。病虽久，可治也。乃先进羌活胜湿汤加牛膝防己以疏利之。三服后，杖而能起。又往视之，投以五苓理中汤（五苓散与理中汤合剂），四服后，肿痛全消。意不愿服药。余曰：湿气未清，恐将复作，不如多服，以免后患。张听之，服药二十余剂，乃以酒肉来谢。余告以谨避风寒湿气。相隔十余年，余见于其戚家席上，称健步焉。", "17265": "里中田大授，家少裕，而年老无子，妻悍不敢置妾，后以失业窘于财，郁而为病。城中有老医名荣同者，田素信之，请其诊视。荣曰：风寒外感也，散之不效。又视之曰年老气虚也，补之益甚。荣穷于术，乃邀余治。诊其肝脉滑数，脾部见弦急，且三至一息。乃曰，君所患为肝气郁结，木来侮土，土已败矣。病可小愈，命不可保也。田似嫌其唐突，请示一方，余以逍遥散合左金丸进之。数服而病减，进饮食矣。又请视之，诊其肝脉稍长，而脾脉如故。知不能愈，乃以逍遥散敷衍之。半月，精神爽健，出入游行。值村中演优戏，相见于庙庑，告余曰，病已全除，当无恐。余曰，脉至不息方可，后半年，余赴都，及来春归，询之，已欹殁数月矣。", "17266": "邻人郝某之次女，产后经数月，饮食不思。精神减少，时兼胸满，面黄肌瘦．延医视之，以为痨瘵。投以八珍汤，获小效，而病复如故。或又以为产后血虚，用大剂四物汤合生化汤，转增腹痛。继有庸手，作伤寒阴症冶，去益远而病增剧。法无可施，来求余治。诊其六脉浮弱，右关尤甚。乃曰，此气虚，非血虚也。当补气以生血。他人多用血药，品多清降，不转馁其气乎．因处以补中益气汤。其父素明针灸，颇知医，难之曰，病苦胸满，益以补中，不增甚乎。余曰，令嫒胃气下陷，清阳不升，故浊阴不降，以致饮食留滞，故胸苦满。若清阳既升则浊阴下降，胸中自当痛快。命如方服之。三剂而精神作，饮食进。更命易汤以丸，一斤而全愈矣。", "17267": "介之田村乔某，忘其名，年老得痹疾，或手或足，痛发左右无定。医药数辈皆以瘫痪治之，药不啻千百剂，竟罔效。委顿经年，已为治丧具矣，而痛则饮食二便尚无大害。其里中有商于都者，知余名，因嘱请治。余至其家，未见病人，先问其子曰：遵大人是何病？其子以瘫痪告。余曰：老年人得此病十无二三愈者，恐治之亦无益也。然既来不得不一视之。入其室，则病者拱手称谢，问答数语，口舌便利，视其口眼无歪斜状，神气亦清。乃问手足麻木乎？曰，并不麻木，惟有时作痛，不可忍耳。因诊其脉，六部俱缓而沉，兼带弱象。告之曰，君所患乃湿痹，既非瘫痪，又非痿症。盖寒湿著于皮肤，四肢重滞，每转侧则重不可举，如移山挪石，非人不行。病者曰，不错，不错，先生所认既真，急请施方必可愈也。余曰，愈则可愈，然无速效，须服药数十付，起居调摄，乃杖而起，早亦在三月外，迟则半年。病者曰，但求病愈，何必急急。乃先以五苓理中汤加附子苍术进之。五服而痛少止，肚腹宽，饮食进。又易羌活胜湿汤加牛膝，肉桂等类，命多服之，半月痛全止。惟举动艰滞，步履尚难。更以白木附子汤，加松节、萆薢等。命十服后，丸服之。更命每早晚遣入扶掖，往返数十步不必再视也。病者遵之，越三月，趋车备物衣冠而来，见其行走如常，而履阶遇限，尚多不利，急遣还而养之。冬十一月遇于城中酒市，则指挥如意，毫无痛苦矣。此事相隔十余年，辛酉其子来求治眼，谈次具陈本末，乃始忆而录之。", "17268": "乔某之子名夏清，忽踵门，先以函入，拆视之，词极文雅谦抑，延之入。问之，已入县庠。据云一别十余年，家道零落，又以嫂氏妒悍，避其虐，舌耕于祁县。春来乍得眼疾，两珠痛楚，夜则尤甚。易数医，无少效。因忆前治家君之病，甚有确见，故特来请治。余拨其眶视之，则黑珠周围起白膜，带二三红血点。诊其脉，则左关弦滑，尺微细。乃曰，此阴亏肝郁也。幸未久，尚无害。若再迟数月，则生外障，翳膜遮睛，则揭去匪易。乃先开一疏肝散，又继以杞菊地黄汤，二方并付之。告之曰：先服疏肝散三四剂，痛当止；继服地黄汤不十剂，当无事矣。每晚临卧，以火酒洗之，避风寒辛热，遥遥数十里可勿再来省往返也。夏清揖而去。半月后，忽自称谢，渭目疾痊愈，专申感悃，并偕邻村郭某来云，亦有病求治，余适在城中宴会，未及见，后不果来。", "17269": "邻人刘锡庆之姊，三醮而仍寡，年近五旬，忽患血崩，村医以为蹉跌，用发灰地榆类涩之而不效。经月余，来邀余治，见其面白如灰，气息仅属，甚不堪。视其脉则沉细迟弱，凡虚象无所不有。乃曰，此病危如朝露，过半月，恐不救也。又贫寒难事药饵，急欲辞归，其婿忽止之曰：岳母病如可愈，药钱我任之，万一不救，则不必矣。余感其义，乃告之曰：君热肠如是，余当竭力，虽无旦夕效，然性命或无碍也。投以大剂六味回阳饮（方：附子炮姜甘草当归党参肉桂），二日而精神起，然崩则如故。其婿来曰，命似可救，而血崩不止。余曰，君无虑，止血崩实易事，但岳母阳阴两虚，不固其气，血崩难止。今有回阳饮以作其气，再用提补，靡不效矣。又投人参养荣丸，加柴胡，升麻以提之，又加芡实、龙骨以涩之，凡五进而血止，因命专服人参养荣丸，两月后，偕其婿来敛衽拜谢。就内人取针线数事而去。越数日精心密缕，封而呈焉。并云贫无可酬，聊以手指答救命之恩云耳。", "17270": "业师庞芸圃夫子，秋间抱丧弟之戚，忽患水泻，自辰至申酉如厕者三十余次，如桶泻水。继之以吐，困顿不堪。且时时作转筋，急遣人呼余至，问其形证，按其脉俱弦直，知为霍乱。以藿香正气散进，泻少止，而二刻许，复吐，所服药点滴无存，前病发作。至天明，转筋将近腹，两腿不可曲伸污便床褥。及余视之，神气仅属，濒于危矣，举家惶恐，余急命刺尺泽，委中二穴，出紫黑血半盏，刻许而吐定，可服药矣，仍煎前方与之，逾时安卧，至午后则腿舒而泻少止。至晚又进一剂，三日而安。而先生知无害，便不服药。余视之见其皮黏于骨，面色青黯，乃以老亲在堂之说，竭力劝之方许焉，告以香砂六君子汤。半月始得如常，而出入动作矣。", "17271": "先生之母，余太师女也，年过八旬，颇壮健。夏秋，忽得疟疾，发则如火烧身，狂叫反侧，他医用药截之不效。招余治之，见其目如赤珠，口干唇破，时时呼冷水。问二便，则小便如血，大便闭数日矣。按其脉，则六部弦数尤甚。乃告日，此热疟也。单热不寒，须内清其热则火退而疟自止。若徒用截法，万无效理。因投以大剂白虎汤，重用石膏至两许，二服而热退，四服而疟已．", "17272": "先生之弟妇，患头痛发呕，饮食不思．时瘟疫盛行，疑为时症，余偶到塾，其侄兰芬兄言其状，并邀之治。问身觉憎寒壮热乎？曰，否。问身痛鼻塞乎？曰，否。然则非时症。诊其脉，则左关弦滑，余俱细弱。告兰芬曰：此脾虚肝郁也，作时证治，必散之，虚而散，则大误矣。兰芬请一方，因以逍遥散进。余过而忘之，越数日，见兰芬，告余曰，药才二服，病全除矣。", "17273": "丁未岁，余读于乡之僧寺。是年太阴司天，五月后阴雨经旬，里中地极下湿，而农家露宿于野，外感风寒，必病疟利。因先配常山酒一坛施之。六月半疟果大作，凡十人而五六，取酒者接踵至，保全颇多。至七月中，疟少息而酒亦罄矣，寺僧名昌裕，素无赖，以佘在寺稍敛迹。旋亦病疟，向余求酒，余以酒已完，欲再制之非浸渍十数日不可，仓卒不能办。昌裕似嫌余吝，乃招而来曰：子怒我错矣，疟虽一病，而人之虚实禀赋不同，余所施之酒，未必人人尽效。我为若治之何如？僧始转怒为喜，乃诊其脉，则弦而迟。告曰：弦是疟正脉，而迟则寒象。子患寒疟，发必多寒少热，且先寒后热，身痛无汗。僧曰：良是。乃以越婢汤发之，二日疟少止，令五服则全愈矣。", "17274": "里中钮某之妻，体素壮，忽患月事不至。始以为胎。久而腹痛，又以为虚，补之益甚。留连数月，腹大如鼓，饮食不思。迎余治之。诊其脉，两关坚劲。问发渴乎？曰，前半日多渴，后半日方可。余曰，此胃热血结也。寻常必患胃热，发则胸膈如烧，甚则发咳，痰必稠。病者曰，良是。先以三黄四物汤破之，二服后下紫块十余，腹少减。又以两地地黄汤加山栀、连翘、通草，叠进之。逾月而潮至，然前后尚不齐也。命常服归芍地黄汤，数月后，如期血至，久而受孕矣。", "17275": "邻人郭某之女，再醮于邻村，归宁恒数月不返。一日忽患咳嗽，初略不为意，久而增盛，延人治之，则曰，此虚劳也。始而补气，继而行瘀，又转而理脾疏肝。药屡易而病不减。一日其母偕之来，俯余治。因问曰，嗽时作时止乎？抑咳则面赤气急声声接续乎？曰急甚。观其面色红润，知非虚证。乃诊其脉，则右寸浮滑而数，余则平平。告曰，此痰火郁在肺经，常苦胸膈满闷，发则痰嗽俱出，不但非虚劳，且大实热证也，进以芩连二陈丸加桑皮，木通以疏之，三日而嗽减。再请余治，则数象减而滑则依然。余曰，热退而痰仍在，不去之，恐复作，因用平陈汤加枳实大黄下之。凡二进，下顽痰数碗胸膈顿宽，而嗽亦止矣。", "17276": "病之奇，有不可解者，徒执方药论之，辄不效。同谱弟王丹文之母，春仲忽患热，口渴神昏，发晕出汗，热如火，几发狂。其母家弟以茂才业医，视之知为热。曰，此阳明正病也。投白虎汤用石膏至一两，而热如故。又有邻人李茂才亦业医，用承气汤下之，二便少利，而热如故。丹文邀余往视，按其脉极沉数，知阴火大炽，而肠胃燥甚。告丹文曰，中无实物，火热熏心，下之无可下，宜清降之。急用地黄汤加山栀，三黄进。药服而心颇清，热如故。是夜忽大雪，天甫明，病者知之，要食雪。丹文以其年老，靳不与。逾时，丹文外出，匍匐出户，就阶取雪，卧啖之，凡三碗许，觉心境顿清；又啖之，归而卧于床。至夕则热退身凉，越日而起。三日后，病若失矣。噫！药则罔效而天降雪以除其病。盖雪阴寒，不假烟火，较药之清降胜万倍矣。医家无此法，亦不敢用也。", "17277": "谚云：「老医少卜」殊未必然。盖此事全关天资学力，资质清者，读书多，则虽少亦佳，资质浊者，胸中无物，老而亦愦愦也。辛酉春正月，家君体素壮健而年过七旬。以新年酬应劳攘，且多食厚味，又年前偶感风寒，痰咳流连。上元后，口下暴肿，渐而两足增胀，渐而两手亦胀矣。堉屡欲施治，而家君素不服药，自以体壮，俟其病之自已也。越三日更甚，以长媳有小恙，前曾经杨医治之，乃托治媳病，遣人招杨治家君病。下车视之，则须发苍然，步履迟重，戴眼镜矣轮扶杖而入，毫无谦抑态，扬扬睨一切，余唯唯听命，窃意必斫轮手也。茶后以家君病请教，杨曰，脉后再谈，诊之越时许，乃释手曰：年老气虚，宜有此疾。此时宜先补虚，不必治肿。气不虚，肿自已也。余以其统混无头绪。辨曰，经云：「水肿初起，目下如卧蚕形。」今家父病适合，似宜先导水，杨怫然曰，治病拘定书本，焉有是处。请服余药，方信余之不谬也。余未便非之，而心窃不谓然，因请一方。乃八珍汤加桂附也，又加陈皮五分，木通三分。云可利水，掉臂而去。知必不效，而家君以其年老，当有确见。药初进而胸腹增满，肿愈甚。不得已，私以杏苏饮加木通牛膝防己各三钱，煎成请家君服，至半夜，则小便五六次，天明腹宽，而肿处作绉形，嗽亦少止矣。家君见药效，连进四服。肿俱消，惟肾囊尚胀，停三日，又以原方加葶苈，二丑进。凡一服，小便洞下十余碗，肾囊如常，而病全息矣。谚之重老医者，以其阅历深，而见闻广，如杨某者，虽松鹤之寿，此事安得梦见乎！", "17278": "长媳初入门十余日，得温病。呻吟叫号，反侧不安。因新妇，急告其父。其父延一医来，则吾里中丙午茂才也。幼尝同考试，其人玩世不恭，乡党薄之，颇落拓。虽通医理，而所读不知何书，每治病，药寥寥三四味，皆以分计，故获效甚少。请视长媳，出告余曰，痧也。宜服犀角解毒汤。尚觉近理，急服之，痧未出而热如故。又易一医，乃河南武安药侩也，初解药性，立方字常误，胸无墨水，而治病颇有一二效者。适为邻治病，延之来。诊脉不一刻，即出曰，此是痧症，又兼胃寒，故胸烦作呕耳，须用温散。请其方，则平胃散也。余不欲令服，而家中人皆曰，时医常以误效，请一试之。药入口则热几如狂，昼夜不安。实无可处。余乃入诊之，脉极沉极数，而外症甚险。告其父曰，以弟愚见，当是阴虚血热。此热症，非痧症也。如是痧，流连将十日，何无一点发耶。此虽新来，乃弟儿妇，当以私意治之，倘有误，亲家亦相谅也。其父诺。乃以大剂地黄汤易生地，合三黄汤满饮之。二更许沉沉睡矣。又恐余热未清，加蝉蜕、灯芯，四服而热止，病始安。令常服麦味地黄丸，半月痊愈。", "17279": "余甥名映昌，以服贾奔走，兼不节饮食，四月忽得斑疾。初斑未清，请董医视之，董以时症兼食，用五积散，病益重，浑身如丹，目睛皆赤。有老女医为人按摩，延视之，知为斑，乃以针刺其舌，又刺其阴而吮之。心稍清，气稍定，而热则如故。余知而省之。见面汗如流，口唇焦破，以为阳明胃热。诊其脉则沉而数。问二便，则小便赤，大便如常。腹亦绵软。知为阴热无可下，宜清之。乃以知柏地黄汤进之。初服而热减，三服而热清。困卧不起，面目黄瘦矣。惟急索食。告之曰，病已去，不必服药，惟饮食宜清淡减少，否则恐复发也，调养一月而安。此亦阴热症也。", "17280": "同谱王丹文之母，夏月染疫症，留连数月。屡易医，病渐去，而苦发热头痛，胸中烦扰。而性情反复，忽而不服药，亲邻力劝之而不肯也。一日头痛甚，丹文专车迎余，因视其病，以同谱故侄呼余，余亦伯母呼之。再三开导，乃许服药。诊脉则沉数，而肝部涩，左寸微。告丹文曰，此血虚肝郁也。专滋阴以润血，热当已，且「乙癸同源」，血润则肝亦舒，头痛亦当止，乃开归芍地黄汤，加薄荷、山栀以清之。二日后，丹文来，问之，则身凉而头痛止矣。又不服药，余以其病无碍听之。", "17281": "同乡张七兄名守秩，其夫人患痢疾，屡治不效。托其戚梁某转邀余视之，则年五十余，人甚枯瘦。诊其脉，浮数特甚。问发热否？曰，热甚。问，渴否？曰，渴甚。余曰，若然，则腹必胀痛也。曰，然。乃告张曰，外似虚，却是实证，非下之不可。张不然其说，曰，体素虚，况痢则愈虚，再下之恐不相宜，万一病不可补，微利之可乎？余告以利之无益，若再迟数日，恐内蕴攻胃，成噤口也。张不得已，嘱余开方。余以大承气汤进。归经数日，又请往视，余曰，此病当大效，何迟迟至是。问来人，则前方恐过峻，减去芒硝故也。乃告其来人曰：归语张某，不服芒硝，勿望余治也。来人归以实告，张勉强加芒硝服之，越半时腹中如坠，暴下如血块数次，病者气乏而卧，痢亦止矣。越日遣人又问，告曰：病已去，不必再下，但病实伤阴，以芍药汤和之，数剂则无误矣。归遂服芍药汤，半月而安。中秋备物作谢，言之始知其详。", "17282": "越二年，张七兄之女，适吾乡大郎神村宋，数年不孕，月事不以时至，饮食亦少。春间忽患咽痛，人以为感冒瘟疫，凡解毒散风、销火凉血诸药，无所不施，而喉痛如故。张求余治，诊其脉沉而滑，恐喉中肿烂，以箸按其舌而视之，则痰核累累如贯珠。白喉连及上腭，且复如此。乃笑曰，如此不著紧病，乃累赘至是乎。头不痛，鼻不塞，非感冒也；项不肿，喉不闭，非瘟疫也，不渴不热，非火也；不汗不昏，非风也。此乃痰热上潮，结而成疮形，按之软而滑，其痛若口疮。况病者体素肥，痰膜凝结，故数年不孕，月事不至。但去其痰，则血络通，不惟止喉痛，即月事亦当至也。其父喜，急索方，余以芩连二陈汤示之，告曰，二服喉痛自止，再合加味二陈丸一料，时常服之，不半年必更壮矣。病者听之，余亦不问．迨戊午春，于宗人处，见张至，急揖谢曰，小女病，诚如君言，今抱子矣，鄙亲家亦极感谢。为之一笑。", "17283": "戊午秋，张七兄亲家之夫人，继室也。即前病喉痛者之姑，年未四旬，得血崩疾。其家富甲一乡，因距城颇远，恐有仓猝病，医药不便，乃设药肆于家。而乡中贫苦者，辄造而请视疾。故亦时时观医书。以夫人病崩，自用血余散止之小效。更一医，又以为热，用寒凉清之，转益甚。乃嘱张俯求余治，余以路远辞，而张哀恳至再，不得已，随之去。入而视之，见病者面如石灰，唇指皆白，知为血虚之极。乃诊其脉，则微弱特甚。乃曰，此中气下陷，脾虚不能摄血，故崩不止。再服寒凉恐血脱也。此时不宜峻补，但提其中气。气能统血，则崩自止。涩之，截之皆非法。因为开补中益气汤，宋似嫌其平平无奇。乃告之曰，君曾读医书，不闻士材先生之言乎，其云：「补气有行血之功，补血无行气之理。」二语极为明确。可见血随气行，气升则血升，气降则血降。若不摄其气而徒止其血，所谓扬汤止沸也。今升其气，使摄血而不下降，然后再用圣愈、养荣之类补其虚，气血相调，并可受孕，治病犹余事耳。宋豁然悟，首肯者数四。更为开大剂圣愈汤，告曰，服补中汤不四帖血当止，后以圣愈汤继之，如恐其烦，可易汤以丸。余去矣，不必再视也。归不数日，时将春夏之交，宋遣人担过牡丹二本。并道病已痊愈。再三申谢。余受而栽于盆，培植灌溉，以吾乡水土杂盐卤，其性极恶。除石榴。葡萄而外，凡花果皆不宜此水，宋所送之牡丹，来时正含苞欲吐，余遣人灌溉，不数日，苞痿而枝渐枯，拔而弃之，增惜焉尔。", "17284": "友人王福友之妻，少以贫寒致痞疾，适王数年，面黄肌瘦，月事不至，至或淡少，久而腹痛增胀。延医视之，见其形症，皆以为虚，补之不应，而王固粗质，亦任之。半年腹大如鼓，见食辄吐，渐至不起，乃邀余治，诊其六脉坚大而迟，知为寒凝食积。问曰：胃中按之有坚块否？病者曰然。告曰，此自幼生冷风寒伤胃气，故甚则增痛，且四肢发厥，盖虚人实症也。不温胃以散其结，则气凝而血必闭，无怪补之增剧。乃以五积散投之，两服而腹稍舒。又以香砂平胃散合乌药散并用之。有邻人素看医书，见方诧曰，病属经闭，治当行血，乃用销食之剂，无乃非法。余曰，君自不信，看药后效验何如。王命其妻服之，越两日而下秽物，腹膈顿舒。又命常服香砂养胃丸，廿日余而月事至矣。", "17285": "又邻人李寿昌之妻，年四十余，忽患经闭，其夫素务农，日用颇窘，兼无酒德，醉后辄加诟厉，妻久而郁结，遂成病。适夏间阴雨，李忽踏泥而至。问何为？曰，家人病甚，拟请诊视，余问何病？则曰：经闭数月矣，此时腹中胀痛，饮食不下，人皆以为蛊。请一视之，果不可治，亦听之矣。问身体肿否？曰，不肿。乃曰，不肿则非蛊也。问痛多乎？胀多乎？对曰：痛有止时，胀则时时如此，几乎大便不利。余曰，此气滞碍血也，无须诊脉，但服药三四付，则病愈。李曰：不如一诊，较为稳当。余曰：此病显而易见，何在诊脉，尔无非愿病愈，但能病愈，何必诊也。乃处以本事琥珀散（方：三棱、赤芍、刘寄奴、丹皮、熟地、蒲黄、当归、官桂、菊花、莪术等），命服四付。李持而去，余亦忘之。至中秋晚餐无事，余巡行田垄间，李忽携镰自禾黍中出而叩首，余惊问何故？对曰，内人服君药一服，即胸膈雷鸣下气而胀减，再服之，病全失矣。余以其病已愈，不必再服，至今月事不愆，饮食壮健，真仙方也。以农忙未得叩谢，兹遇君敢申意也。余笑而扶之起。说麻问稷，日瞑而归。", "17286": "医士郭梦槐之妻，以家道式微，抱郁而病，发则胸隔满闷，胃气增痛，转侧不食。郭以茂才设童蒙馆，而赀不给馔粥，见其妻病，以为虚而补之。病益甚。乃来求余，诊其六脉坚实，人迎脉尤弹指，因告之曰，此气郁而成痰也，则发头晕，且增呕逆，久而胃连脾病，恐成蛊。郭求一方，乃以香砂平陈汤加大黄、枳实以疏之，二服而大解，病若失矣。", "17287": "里中相周庞兄之母，年五十余，得吐食症。始以为霍乱，吃塘西痧药数粒，吐如故。又请一医以为气郁，用四七散开之，仍如故。庞求余治，余细问形症，即非霍乱，亦非气郁。按其脉，则右关弦甚，余各平平，乃顿悟曰，此水积也。病必小便不利，好饮水，胸膈闷滞，时兼头晕，病者点头称是。因以五苓散加苍术、木通利之，越日吐止。庞又请视，告曰，不必再视，但常服香砂六君子丸，不但不能停水，且大益于脾胃，于老人甚相宜也。庞遵之，其母遂健。", "17288": "治病之道，如钥之启锁，无论显然相反，即相近者，辨之不明，治之不当而亦无效验。其间毫厘之差，千里之谬，如痰之与饮，皆水也，而有阴阳之分。温之与热，皆火也，而有微甚之别。其间或虚、或实、在腑、在脏，尤须详审。审之奈何？形、气、脉、证是也。合而参之，断无背谬。俗医知有心肝脾肺肾。而置六腑于不问，不知人生全以胃气为主，胃气盛，则脏腑皆盈，胃气衰则脏腑皆败。不但饮食谷气，全凭胃经生发，即病者服药，亦先入胃腑，而后达于它脏，故曰：「得胃者生。」又诊脉以胃气为验。然则胃者生死之关也，不明乎此，而能达精妙者，未有也。且一病只有一法，故余治病未尝私自立方，所开皆古人成方，又不敢妄为增减。每见病者粗识字，则厌故喜新、求日易方药，不知药之为物，非五谷平和之气，利此则害彼，医士用之不当，必有诛伐无过之虑。久之，胸中混淆。病者非病病，乃药病也，富贵之家，尤易犯此，曾屡屡言之，以为以药饵调养者成。", "17289": "余读书于城东之三道河，有友人李君香泉年四十许，未博一衿。素嗜茶，自早至晚，约饮茶数十碗。见炉鼎热沸，则喜形于色。久之面乏血色，食量减少。每至秋初，则彻夜不寐，天明益渴。一日由家至塾，携丸药来，朝夕服之。又常蓄熟枣仁一囊，不时咀嚼。余问何故？则谓医家云，枣仁能安神，苦不寐，故常嚼之。问服何药？则因不寐请医士习天主教者，名王凝泰，令服人参归脾丸，谓是读书劳心，心血亏损所致。余曰，药效否？香泉曰，并不见效，然尚无害。余请一诊，则脉多弦急。告香泉曰，此水停不寐，非血虚不寐也。就枕则心头颤动胸胁闷胀，小便不利，时时发渴，乃有余证，宜逐水则寐自安。若以归脾丸补之，久而水气上蒸，恐增头昏呕吐，年老恐成水肿。香泉曰，是是。急请一治。余以茯苓导水汤付之，二更许，小便五六次，启衾而卧，则沉沉作梦语曰，好爽快。须臾转侧至明始觉，则遗尿满席，被襆如泥，而饮自此少，食自此进。命常服六君丸以健睥胃。香泉逢人说项焉。", "17290": "里中庞守愚茂才之子，年四岁，忽患痛，浑身发热，见食作吐，汗出不止，已昏昏不知人。庞以训蒙在外，其家乏人经纪，听之，病增甚，乃转人求余治。往而问之，则以未出天花，邻媪以西河柳、胡荽等发之。提其腕，则脉颇弦大。问饮食乎？曰；不食数日，且见食则吐，即粥不进矣。问二便乎？曰，小便赤如血，大便绝无。按其腹胀甚，按胸则张口作痛状。乃告曰，此停食也，不下之，何能愈。乃以平胃散加芩连大黄以进，服后时许，下黑粪数粒，又下赤色粪数次，腹减而醒。又视之，则脉已小，惟胃气尚滞，又用保和丸加槟榔末而进之，晚即呼食，其母以蒸馒头付之，狂啖数口，三更后，病复发矣。次早又请治，得其状，乃责其母曰，小儿何知，食积甫去，顿令食面，恐新积较旧积难去也。仍令服平胃散，重用莱菔籽投之，嘱曰，不必再看，一月内谨忌食面，只可以米粥调之，若再发，则不治矣。其母惭而听之。多方调摄，适值中秋，共父酒肉致谢，余以文字交固却之。", "17291": "风寒暑热，饮食劳倦，内因外因，病各有一定之征，一定之脉。惟痰之为病，奇奇怪怪，实有千变万化之势。凡不可名状，无从考核者，大抵皆痰为之也。", "17292": "又司徒芝邻方伯藩秦时，体素肥。时各省提拔军饷，员弁充集会垣，而库款支绌，芝翁忧形于色。至夏，得痴呆病。坐卧不安，时而独言独语，时而浑身痒搔。又合眼则睡，睡则梦二鬼在前：一自缢者，索挂于项；一无首者，以手提头，发蓬蓬，血模糊。以是，不能独卧，不接属员者十余日。延医治之，皆曰冤业，恐不起。又易一医，则曰心血亏损，用天王补心丹，饮食顿减，及饬门者请余，余入见，则曰：病至此，恐不能治，但请君决之，果何经受病，须详悉言之，勿隐护也。按其脉，则六部弦缓而滑，寸部浮取尤甚，知是痰证，乃启芝翁曰，大人乃脾湿停痰，又加以劳倦伤脾，心火浮动，以致痰涎绕心包络，故时迷时悟，平时必喜唾痰，唾则胸腹宽舒。此时痰涎停结，必不能唾。且时而发烦，时而动躁，时而口渴，时而心颤并手足，时而二便不利，皆痰为之。芝翁曰：二鬼何物？余曰：二鬼亦神魂烦乱所致，其实无之，大人不必多虑。病虽多端，卑职保能愈也。芝翁喜，问服何药？余曰：大人病非汤药可疗，须先以矾郁丸吐之，次以控涎丹通之，再多服去痰健脾诸药则无虑矣。芝翁急索矾郁丸，余以此药市中多无，乃制而送之。服数粒，则刻许而吐痰絮胶黏，色兼青黑，自谓心境顿开，欲再服，余曰：痰已吐，再服恐伤胃气。继以控涎丹投之。两日后，设便饭邀余，扶杖告余曰，两夜二鬼不见，神气亦清，君之高名实所佩服，敢问不治成何症？余曰，若不治，不癫则痫，甚则成痰厥。其幕友皆来周旋，饭后面归。不数日，余以内艰、闻讣回籍辞丧。至八月，芝翁以官钱案发，奉旨革职。案定，其阍人黄五绞死，就刑之际，芝翁闻之，痰厥而殁于馆。后小梅来书，犹道芝翁之死如君言焉。", "17293": "观察蹶然起曰：闻君讲解，无不确当晓畅，心为之开，然则我之遗精绝非虚症，请一视之。乃诊其脉，缓而坚，右关尤甚。告之曰，大人之病，所谓湿热内淫是也。胸膈常患闷滞，大便颇形后重，当消导之。进以震亨渗湿汤。观察阅方内有黄连恐不宜，且厚朴、苍术恐伤胃气。告曰，胃苓汤是湿热要药。平胃散者，培卑监而使之平，非削平之谓也，前辈言之甚明，此方用黄连川芎素亦疑之，细思其理，苦能燥湿用黄连而焦炒之，用其苦非用其凉也。湿热能瘀血，用川芎以行之，震亨此方，具有深意。大人成见在胸，一误岂容再误，他人必谓此方，非治遗之药，岂知治病必求其本，本治而末不治者，未之有也。请放心照服四付，常服香砂六君丸以调之，不但精不遗，即饮食亦当倍也。观察如言服之，五日后，约晚饭，至则告曰，前闻君言甚有理，而心窃疑之，今服君药，遗已止，果觉精神增健，食量亦佳，并阳事亦壮。非君妙达精微，几乎冤我，可见医道无方，在究其理而变通之耳。后余诸蒙奖许，即内艰而归，犹寄函问讯者数四。", "17294": "诊脉如审案", "17295": "昔人谓用药如用兵，余尝谓诊脉如审案。其微言妙旨，前辈论之详矣。惟仕才先生四言要诀，简明切当。其云：四时之脉，胃气为本，尤为诊家要著。盖胃气者，脉之神也。所谓神者，极力形容而总归之曰有力。窃谓有力二字，尚不足尽神字之义。盖有力而兼活动，不疾不徐，不软不硬，方是如春风弱柳气象。本此参之，百不失一。审时，有正凶，有佐证，有致事之由，有受害之所，有连坐，有挂诬。审之既确，而刑罚之轻重随之。姑就一端言之，如脾湿停痰一证，脉必沉滑。则沉滑者，正凶也。而脾湿必便难，停痰必减食，此佐证也。湿或饮水过多则兼弦，劳倦思虑则兼弱，此致事之由也。或因湿而泄泻，或因痰而咳嗽，则泄泻者，右尺必虚；咳嗽者，右寸亦滑，此连坐也。且脾湿者，饮食不能健运，精液必致不充，则左尺必涩，此挂诬也。但识定正凶，健脾销痰，病皆自己。若治泄泻而止之，治咳嗽而清之，则抛却正凶，诛伐无过，必至不能治病，而反增他病也。故用药不过古人成方数十，传之于世，而用之或效或不效者，非笔下之愦愦，实指下之未了了也。", "17296": "吾尝谓诊脉，须合三部十二脏腑，参考而斟酌之，方有定见。若诊寸而忘尺，诊右而忘左；滑则治其痰，数则去其火，虽有小效，亦难去病，况审之不清，而未必效乎。俟高明斟酌之。", "17297": "武芝田先生，崞县人，以名进士出宰陕西，后升榆林观察，以榆林地瘠，故在省遥领之。观察素豪于饮，以酒积得吐血疾。余在省候补，一日招余往视其病，谈及其病，观察曰：吐血数年矣，遇郁益甚。已更十数医。或曰思虑伤脾；或曰暴怒伤肝；或曰血热妄行。或效或否，而终未拔其根，可为吾一治也。余见其气体魁伟，面色红润，食饮兼人，知非虚证。为一诊之，则左部沉实，非病脉，右关沉弦而数。乃告曰，大人乃有余病，非不足病也。如思虑伤脾，则当忡怔健忘惊悸；如血热妄行，则当身热发渴，头晕目眩；如暴怒伤肝，则当两胁膨胀，胸膈不开，兼发呕逆。今无此诸证，则前医皆误也。以愚见参之，必是湿热内淫。热能瘀血，故所吐必血色紫黯，且时而成块。胃口多患刺痛，小便常赤，大便艰涩，时亦带血。观察曰，语语不谬，当作何治？余曰：先以葛花解酲汤清其胃，继用枳术胃苓丸行其瘀。再饮食淡泊以调之，不过一月，保不再犯矣。观察如言调摄。廿日而安。后观察内艰归里，以清风两袖，主讲吾汾之西河书院。余亦以内艰归籍。相隔六十里，文字往还甚密。", "17298": "谈及共如君云，癸水不调，脐腹常疼，精神委顿，饮食不思，偶受孕，三四月辄坠。前在崞，曾服药无数，兹又请教授齐老师治之，又请府幕钱老夫子治之，病仍不愈。皆以为痨矣，请一决之。如君出则荆钗裙布、寒素依然，向余展拜，余答之。诊其脉则六脉俱虚，而无数象，右关尤甚。告观察曰，此乃脾虚土衰之证，故精神少，饮食滞。至月事不调，怀孕辄坠，则中气不能健固之故。极可治。但须积日累月，非旦夕可愈之病也。若迟延不治，则久而泄泻，或久而咳嗽发热，面赤恶寒，真痨症矣。余先进以六君子汤加益智、干姜、芡实，命服八剂后，服资生健脾丸。观察问，丸药服几斤？余曰，多多益善。", "17299": "里中布贾姓安名溶者，虽作商，人极推重。辛酉夏，其次子岁余而殇；其三女亦以痨症亡于家；未越月，其次女之婿与其甥男，一日间相继亡。其次女年幼，婿之族人恐席卷而他适，置死人于不问，互争产业。安知之，急与愤争，族人乃散，前丧子女，已抱忧郁，后次女事，又增其愤，故归而得胸满腹泻之疾。求余治之，诊其脉，弦而滞。告曰，此气滞水积也。用香砂胃苓丸消之，病早愈，安啬于财，不复服药，余亦忘之。越十余日，急遣人招余视其病，余以为泻之未愈也。急视之，则气格格作逆，口唾不能下咽。问膈与胸中作满否？曰否。提其腕，则两手如冰，六部伏不见，惟有寸带滑数。乃曰，此痰壅肺窍也。肺窍为气所出入，今为痰壅，故气不能入。如在胃，则卒然昏噤，三生饮吐之可也。今在肺管恐吐之不出，无可措手，急辞而出。安固请一方，乃以木香顺气饮敷衍之，出而告其伙曰：安某之病，必不起，可急为料理。其伙尚不信，因循至次早，乃来省视，安已口张气促而不能言矣。其堂兄见其危，又邀余治，余固辞。乃请邻人扶乩，服一方颇能言，遍召家人以身后属之，转侧而殁。", "17300": "李赓堂先生以武进土为温州都司，后升江西参将，缺甚瘠，告而归里。其长子号东樵，以北元作户郎，次子号莲峰，屡荐未售，博极群书，在里中与余往来甚契，赓堂先生虽林下，而性情伉爽，排难解纷，里党中多赖之，庚申春，东樵以都中官钱铺案发，下刑部狱，越年许，案未结，赓翁在家忧之。辛酉夏，忽患胸膈满闷，饮食不进，遂致手足肿胀。延医视之，疑为水肿，用利水药不效。继更一医以为虚，用肾气丸仍不效，而肿益甚。适余以其族人丧葬遇莲峰，即请余治。诊其六脉坚实，右关硬欲搏指。乃告日，此饮食伤胃，有余病也。平日多食厚味，积滞胃中，胃主四肢，胃气和，则四肢安；胃气滞，则四肢胀。必至之势也。况胃气既滞，杯勺茶汤皆能停积，虽见小便不利，其实非水能泛滥发为水肿，徒利水，必不效。且此病由湿热内蕴，再用熟地以涩之，跗子以塞之，不增胀何待乎！惟年老阳虚，脾胃素弱，治无速效，但欲消肿，则易易耳。用渗湿汤加枳实、木通、牛膝销导之。莲峰似嫌其峻，余曰：此急则治标之法，但令胃气通，则积自销，肿自愈，不必专治小便，小便必无不利。后再用健脾养胃药治之，须三五月乃成功也。乃服之，一剂而肿皱，三服而十去其六。莲峰来书云：不意君久持文誉，出其余技，竟使顿失沉屙。昔人云：事亲者不可不知医，弟真赭颜无地矣。明日更烦一视，敬当执帚一待。余往视之，脉稍和，而右关如故。告曰，胃气已行，尚未通也。问小便利否？曰，未利，乃加葶苈，二丑疏之，即小便十余碗，肚腹宽舒，饮食亦进。继以资生健脾丸方，汤服之。告曰：必厌汤药，服丸可也。莲峰以秋试在即，欲赴省，恐再发肿。余曰：但令勿服附子、东参、熟地之类，渐而培养之，必无恐，惟老人气虚，多需时日耳。莲峰见无碍，遂束装赴试。赓翁之长女亦知医识字，又有旧仆亦业医，莲峰走后见其羸瘠不堪，力劝其服熟地、麦冬并燕窝、东参等，大补气血；又见其能食，以鸡鸭鱼肉日日调养之。未半月，肿虽不作，而胸腹仍滞，小便仍不利矣。", "17301": "里人张兄清之妹，归宁数日，忽患胸满饮食不进，兼发呕作嗽，其母疑为胎。邀余治之。诊其六脉平，左关带滑象。因告之曰，病乃肝气不舒，郁而生火，且肝冲犯胃土，食必不思，乃以逍遥散加丹皮、山栀清之，二服而瘥。", "17302": "吾乡张公景夷之弟，素短于才，在湖南作贾。年余而归，益无聊赖，兼嗜洋药，一切衣物日用，仰给于兄。性近侈，私累丛集，又不恭厥兄，终日愦愦抱闷气，食不沾荤，而糖饴瓜果之类，时不离口。辛酉夏因而成疾，其兄延余诊之，六脉平和，惟左关滑，右关弱，乃气不伸而脾馁候也。因投以逍遥散。其兄以为颇效，而病者不任也，乃入城投荣医者治之。荣素迂滞，问其形症，且恐货药无钱，遂以病不可为辞焉。张归则涕零如雨，其母素溺爱，亦以为不复生矣，举家惊啼。日诟谇，景翁不得已，又请余治，情辞急迫，乃曰：荣某以舍弟病为不起，请决之，如真不可为，身后一切好预备也。见其景象，本不欲诊，以景翁诚恳相求。又诊之，则脉象如故。乃告其家人曰，此病此脉，万无不好之理，如别生他证，余不敢保，若单有此病，勿药可愈，如有错误，当抵偿也。荣某以庸术吓人，勿为所惑。景翁颇喜。而其弟则大拂意，奋袂而出。景翁嗟悼再三，问何以处？余曰：此虽弱冠，其心反不如聪明童子，但日给钱数十，令其游行自在，无拘无束，三两月必无虑矣。景翁如言听之，病者日日入城，颓然自放，不两月病痊而更胖矣。景翁始信余言之不谬。即其弟亦自云悔不听余言，致多费也。余笑而鄙之。", "17303": "直隶藩库厅张一端，介人也，以名家子，赴直候补。内艰归里，与余时时作觞豆之会，人亦潇洒不群。以其犹子张文泉司马与余为同谱，故叔呼之。庚申夏，忽患耳聋，人与言者，必大声疾呼方可。适余约作销夏之会，入门与语，貌甚痴。怪问之，方知其聋。谈次便请一诊。问其得自何时？曰：四月中旬。延医数四，皆以为肝气，用平肝药数十付竟不效。乃诊之，觉其六脉沉而数，兼带弱象。因告之曰，此阴火上冲也。耳主肾，肾气壮则耳通；肾气虚则耳闷；肾气寒则耳枯；肾气热则耳塞。君所患乃肾热，绝非肝气，吾乡小儿多患此，甚则流黄汁，一予散肝，不益悖乎。一翁问服何药，乃以知柏地黄汤进。一翁似赚过凉。余曰，长夏气冲，兼胃中有湿热，必无碍。但耳不聋，则勿服也。否则须服麦味地黄丸，其功稍缓。一斋归而服之。余略不记忆，越年许，与其兄张立翁茂才谈及，方知四付耳即通。因忆其事，申谢再再。", "17304": "里中武庠杨乐斋之二嫂，廿余而寡，抚一子，人颇精强，一切家政，皆经其手，诸妯娌不及也。然郁郁独居，肝气时作，发则喘咳交臻，呻吟不食，如此者经年矣，延医数辈皆以痨瘵论。壬戌春，病复发。卧床月余，阁家无可措手。杨邀余视之，诊其左关滑数，右寸关俱甚。乃告之曰，此气郁停痰，并非痨症。前必多服补药，因而增剧，万勿为虑，药不十剂，保无恐矣。乃以平胃、二陈、四七汤合进之，药入口才刻许、膈间漉漉作声，顿觉宽展，二帖后，喘咳息，而食少进。家人皆惊其神，以为全愈，遂停药。余亦忘之，未过三日病又作。又延余视，诊之，脉少衰，而滑数未改。因问服几帖？以二对。告曰：二帖路已开，病未愈，少亦须四服，但得大解胶黏秽物，则全去矣。不必易方，宜照前服之，三日后再见也。病者听之，越日晨起，暴下恶物数次，食大进，喘咳皆归乌有。更告以香砂六君子丸调摄之，尤当稳固，而其家皆淡漠，不知听之否也。倘调养不善，恐明春再作也。", "17305": "同谱王丹文，续弦至四而仍病。始以为不礼于姑，郁症也。清阴雨苍茂才治之，用逍遥散或效或否。月余又请李笛仙茂才治之，问其癸水不至者两月矣，始疑为孕，继觉其非，以瘵治之，用十全大补汤加桂附，初服则可，继服而热增矣。迁延之久，无计可施，专车迎余。诊之脉细数，而肺部尤兼滑象。告曰，此热入血室症也。初因少阳感冒而起，宜小柴胡汤加生地、丹皮等，以凉其血，则病当愈。阴之逍遥尚近理，李之桂附，则直阴本虚，又加热药以熬煎之，是油沃火也。此时必喘咳并作，午后发热，头目昏晕，精神倦怠。解外感，则外感已散；清内热，则真金久为销烁，恐无效也。丹文急请一方，乃以东垣拯阴理痨汤进。告曰，服后当有效，然此病总以癸水为主，癸水至则可治，若癸水不至，虽效亦无益也。越两日，丹文来喜曰：服兄药凡两剂，病已减半，再服可乎？余曰：可再服两剂，再看可也。又两日，迎余去，诊之，数象稍变，而虚弱特甚。惟肺部火不退，乃易以人参救肺汤。三服后，丹文又迎余，问其癸水仍不至，乃辞焉。……午月末，余由定回介，问之，则四月中已殁矣。", "17306": "里中王云集夫妇，习天主教，精于技艺，大而土木之工，小而钟表之细，以致裁衣治膳，骑射技击之术无不通，亦无不精也。而清贫如冼，夫妇诵经奉佛，意气淡泊，乡党皆敬之。壬戊春，得脑后疼，起卧不敢转侧，动则如针刺。请王槐堂茂才治之，以为风也，散之不效，乃邀余治。诊其六脉浮滑，两寸俱出鱼际者半寸。告曰，此痰厥头痛，非外感也。甚则为刚痉，必至角弓反张，身体强直；缓则半身不遂，口眼歪斜，实大症也。止头痛，极易事，但此病须服药数十付，乃除根。不然疼虽止，将复发。王以贫辞，乃曰：但能止头痛则举动自如，余听之可也。乃示以东垣通气太阳汤（柴胡、升麻、黄耆各一钱，防风、羌活、陈皮、人参、甘草各五分，槁木、青皮各三分，黄柏一分，白豆蔻仁二分）二服，痛果减，遣人告余，拟余易方，余曰，方无可易，但服至五六付，痛全止矣。王遵之，痛遂已。其妻劝其再治，其夫苦无药资，遂止。余近闻其手足迟重，饮食不思，且皮肤疼痛不自觉。噫！贫人获此大病，若跌扑而痰壅以死，犹为了当，不然恐沉绵床褥，累月经年，其罪状有不可以言语者，伤哉贫也。", "17307": "赵梅村先生，崞县人，工书，兼精笔劄。见者辄赏之。以廪生博广文尚在需次，为榆林观察芝田先生记室，后芝翁以内艰归里，梅翁亦家居，近为定襄令同谱弟戴幼安翁司笔劄。壬戌夏，定襄县试，幼翁邀余阅卷，与梅翁朝夕聚谈。一日梅翁曰：弟素颇健，近不知何故，两腿连脚作肿，午后益盛，闷滞不能屈伸。余问皮皱乎？曰然。光亮乎？曰然。小便不利乎？曰然。胸膈发闷乎？曰然。告曰，此必饮水太多，水气下注，不治则成水肿，渐而至腰，至腹，则无救矣。梅翁请一诊，余曰，不必诊脉，但疏泻其水，小便利则肿自已。至于茶水，渴而后饮，不渴时则绝之，勿过贪也。因进以五苓散加木通、牛膝、防己、瞿麦，至夜则小便五六次，觉肚腹宽舒。天明视之，肿消其半，连服三剂。则肿迹全无，步履矫健。梅翁为书对联、横幅，称神者再再。", "17308": "定襄西厅程裕堂，都中人，春初到任，而定缺苦甚，岁入不足二百金，而定俗尤鄙陋不堪，一切起居日用多不遂意。又以老母在京，迎养则不给，不迎又不可，忧思抑郁，手生一疔，延本处牛医治之，牛屡施针灸，半月而后愈。然程素有积滞，兼日来忧郁，遂胸膈张满，饮食不思，精神馁惰，面目瘦削，牛以为病后大虚，用桂附补之，二服而满益甚。知余在县署，急衣冠来拜，幼安问其病，即指余告之曰，润翁医道如神，山陕诸相好，无不服者，宜请治之。余诊其脉，六部沉数，右关坚欲搏指。笑曰，君腹中如塞井而下之石，积滞无隙，宜乎饮食之减少也。此有余之症，急下之，则舒畅。误认为虚，则相悖矣。程曰：精神馁困，肌肉消瘦，非虚而何？余曰，俗医但知书上病，不如身上病，焉有是处。精神不足者，气血不流通之故；肌肉消瘦，饮食不生发之故也。盖脾胃为容受转输之官，积则无所容受，滞则不能转输，胃气一停，百脉皆败，无怪其然也。程请一方，以对金饮合保和汤合进之。两服而胸腹作声。洞下秽物数次，顷刻间，饥不可忍，神气亦清。晚笼灯而来，伏地作叩曰：此方真灵丹妙药，前尚未深信，今乃知俗医之多误也。余曰，人腹中如常平仓，最须年年出陈易新方好，但旧积既去，胃气尚弱，新物入口，停滞尤易，须节俭也。程首颔之。即折柬相邀，余怜其苦力辞之。越日余束装归里，程乃饬差送数里外。时雨后多泥，凡难行处，即转轮负毂，余遣之去，则曰，家主之命不敢违。过十里而后返。", "17309": "杨清礼之女，年六七岁亦得热症，请江湖士常治之，常以为温，用荆防败毒汤不效。又请朱医治之，朱素作贾，粗知药性，又以为风，用通圣散而热仍不退。杨不得已，邀余治之，见其脉象沉数，身热如火，告曰，此与余舅母同病，并非风，亦非温，但清其血，热自止。若用荆防等发之，要知春冬腠理为风寒所闭，故用散药解之。此时皮肤皆开，长夏酷热，散之不益耗其气乎。杨曰，医者意在发汗。余曰，无汗，汗之可也。有汗，何容发也。杨又谓，医以为此汗是热天之汗，非应出之汗也，故发之。乃晓之曰，汗无非人身精液，容有二乎。此时之汗从令爱身上流出，难道以药发出之汗，从他人身上出乎！必以为此时之汗为非汗，以药发出之汗为真汗，必使用麻黄柴葛，使汗出不已，真气耗竭而后已。医道不通至此，几何不误人性命耶。杨语塞。请一方，乃仍用三黄解毒汤。杨痴物，久不见，未知应效否，余不愿问之，然亦难保也。", "17310": "邻人杨本檀之岳母，贫不能自存，衣食悉仰给其婿，而杨亦失业家居，日用颇窘，面目相觑，日抱忧郁，以爱女故，遂增咳喘，肚腹胀满，饮食不思，杨不忍坐视，邀余治之。至则面目黄瘦，气息仅属。告余曰，不食数日，喉中如有物塞者，咽之不下，唾之不出，他人以为时气，请一决之。诊之则六脉沉弱，两尺如丝。告曰，此大虚证也，须大剂峻补之方可，且药必得数十付，再能节思忍气，可保万全。若喉中之物，即所谓梅核气，并非时气，药不三服可去之。杨曰，但使喉中通利，饮食能进，其余缓缓保养。至精神大虚，用药调补，弟近况实艰，药资无从出也。余曰：亦是，乃开四七汤加桔皮，香附以疏之，药入口至夜觉喉中之物如坠于腹者，呼吸通利，药两进则思食，而精神作矣。杨疾告余曰：家岳病似全愈。余曰：不然，四七汤只能疏通道路，与其本病毫无干涉。盖病日久，故觉爽快，若再迟数日，恐饮食仍不进也。且脉象甚不佳，不如听之，徒费银钱无益也。杨然之。", "17311": "同谱弟张月谭之姊，所适非人，贪而好气，以故时增烦闷，久而生痰，又久而积食，因之精神萎顿，饮食不思，膈满肚胀，自以为痨。一日同入城，月谭邀余诊之，则脉象沉伏，按之至骨而后见。告曰，此气郁痰也。胃气力痰气所壅，则清阳不升，浊阴不降，而头晕目眩，项粗口干，腹满便秘，诸症交作矣。病者称是。乃进以胃苓承气汤，二服后，下秽物十数次。又往视之，病者再三称快。命再一服，即继以香砂六君丸，不及半斤，当健壮倍于昔日矣。", "17312": "裕州牧莲舫兄之夫人，号杏云，灵石漪泉翁女也。工书画，善音律，一切博奕棋酒，无所不通。适李时，莲舫尚诸生，劝之读书，不数年得乡举，后以誉录议叙牧裕州。杏云随之往，日行事件，多经其手。而莲舫多萎靡，且好狎邪游，并取二妓。以防撚不力失官，后虽开复，而空坐省城，益不自释，日与夫人反目。辛酉秋，夫人不得已回介，家道式微，翁姑俱老，诸事赖之保全。余曾一次，即为余画桃花春燕扇幅，至足感也。壬戌夏，忽遣人邀余，问之，则杏云病矣。急随之往，则衣饰楚楚，诊其脉，则六部沉伏。余曰：此郁滞也，宜逍遥散。夫人亦知医，点头称是。二服而全。又隔月，余赴捕厅之饮，先见晓圃，晓圃曰，兄来正好，五嫂又病矣，何不一视。入而问之，杏云曰，以为感冒，但觉憎寒发热，肢体沉困，用柴胡四物汤，一服而腹作痛，昨夕犹缓，朝来无止时矣。时疫气流行，恐其为疫，故请大哥一视。诊之则余脉俱平，惟右关颇实而滞。告曰，此非外感，亦非瘟疫，仍是食为气滞，故中脘不通。不惟增痛，且多胀也。况胸间作闷，时时作嗳气，以霍香正气散疏之则无病矣。杏是之，称不谬。乃处一方。越二日，遇晓圃于酒市，问之，则日二服全愈，家五嫂命致谢焉。", "17313": "盖闻万变而不可拘者，命曰病机；一定而不可易者，命曰方药。若夫胶一定之方以应无穷之变，未有见其或可者也。故曰：用古方治今病，譬犹拆旧料改新房，不再经匠氏之手，其可用乎？余以方药起沉疴，盖比比也，而不至于阴阳逆用，虚实倒施者，诚有见于病状万殊，刹那生死，不敢不穷源而治也。而源于何穷，不过以色合脉，以脉合症，以症合问，谨持四者，互而求之。病机虽人人殊，而方药且符节合矣。以是受知于当世，四十余年，吹枯振槁，固非褚墨所胜纪，兹摘其朱紫易淆者，聊录一二，以传后世。非敢妄自矜诩，良欲偕天下为穷源之学，勿得草草以欺世而自欺也。仲景云：观今之医，务在口给，相对须臾，便定汤剂。按寸不及尺，握手不及足，人迎趺阳，三部不参，动数发息，不满五十，明堂阀庭，概不见察，夫欲定死决生，实为难矣！余也三复斯言，肌肤粟起，遂沉湎于三坟，惟鱼蠹是师，故可幸无罪耳。倘天下后世，因予之案以尚友三世，弗令南阳捧腹则几矣。", "17314": "文学顾六吉，胸中有奇痛，不吐则不安者，已历两载。偶为怒触，四十日不进粥浆，三十日不下溲便，面赤如绯，神昏如醉。终事毕备，以为旦夕死矣。余视其脉，举之则濡，按之则滑，是胃中有火，膈上有痰，浸淫不已，侵犯膻中，壅遏心窍，故迷昧乃尔。以沉香、海石、胆星、瓦楞子、牛黄、雄黄、天竺黄、朱砂、冰、麝为细末，姜汁、竹沥和沸汤调送。初进犹吐其半，继进乃全纳矣。随服六君子加星、香、姜、沥，两日而溲便通，三日而糜饮进。调摄百余日，遂复正常。", "17315": "隐士陈眉公，患三日疟，浃气未瘥。素畏药饵，尤不喜人参。余诊其脉，浮之则濡，沉之则弱，营卫俱穷，故绵延不已。因固请曰：夫素不服参者，天畀之丰也。今不可缺者，病魔之久也。正气虚惫，脉如悬丝，而可拘以常乎？变通趋时，不得失也。先服人参钱许，口有津生，腹无烦满。乃色喜云：素所胶而不化者，今日发吾覆矣。敢以性命委重，惟兄所命耳。遂以人参一两，何首乌一两，煎成膏，加姜汁一钟。甫一剂而势减七八，再进而疟遂绝。", "17316": "文学沈子凡之内，忽然晕绝，周身如冰，自寅至申，竟不得苏。咸曰不可救矣。余曰：脉虽潜伏，而气口则隐隐见也。但真微之脉，粗浮者不能察耳。东垣以卒倒为气虚，正谓是症也。以人参一两，生姜汁一钟，冰片一分，和匀灌之，下咽便醒。", "17317": "盟友张萃甫之妾，产后蒸热昏困，不进食者半月有奇，口不能言，身不能动，业已瞑目而治凶具。余闻而往，诊之寸关已不可见，左尺犹瞥瞥如𤸒上肥珠。余曰：症虽万无一生，脉可百中救一。以人参五钱，煨姜五钱煎汤，磨琥珀丸抉口灌之。一服目开，再服能言，三服而进浆粥遂愈。", "17318": "别驾施笠泽，两足肿重，痛若虎啮，叫号彻于户外。医以四物汤加槟榔、木通、牛膝、苡仁，数剂病不少减。余曰：阴脉细矣，按之至骨则坚，未可竟以虚责也。况两膝如绯，拊之烙手，当以黄柏五钱为君，木通四钱为佐，槟榔一钱为使，日进两剂，可使遄已。笠泽服之。十余剂而愈。", "17319": "文学朱文哉，遍体如虫螫，口舌糜烂，寅卯时必见二鬼执盘餐以献，时年尚未满三十。余诊之寸脉，乍大乍小，亦知其为鬼祟矣。细察两关弦滑且大，定为痰饮之疴。投滚痰丸，一服微有所下。更以小胃丹下痰及积，身痛减半，至明旦而鬼亦不见矣。更以参、术煎汤送小胃丹，复下数行而愈。", "17320": "内侄陆文蔚之内，自上脘抵少腹奇痛欲绝，服山栀、枳、朴，弥甚。余曰：脉诚数矣，独不察其沉则软乎？不第土惫，抑且火衰。六君子加姜、桂，大剂饮之而痛减，原医犹谓之火症。文蔚信余言，调一月愈。", "17321": "医者杜仲畹子，伤寒八日而大热不休，胸腹满痛，脉细且软，为阳症得阴脉，法在不治。余曰：欲攻之，则形体已虚；欲补之，则邪气犹在。无已，用杏仁五钱，苏子、枳实、厚朴、当归各三钱服之，外用姜、楂、葱白炒热熨之，又令两人更互揉摩，时时以浓𡵚茶加生蜜饮之。至夜分腹中大响，下结粪殊多，更以前汤服，仍令揉摩，复下宿物，而后热退神已，困倦虚热蒸蒸不已，令食糜菜，继食人乳一钟，日进数次，两日而神清热止。更以生地、麦冬、茯苓、知母、陈皮、甘草、大枣服二日，更以四君子加陈皮、麦冬，服数日而元神复。夫阳症阴脉，十发九死，况大积未消，犹难措手，乃知法不可以尽拘也。", "17322": "邑宁夏彝仲太夫人，年届八十，因彝仲远仕闽中，忧思成疾，忽发热头疼，医以伤寒发散禁食，一剂而汗如洗，气喘促，神昏倦。业已治凶具矣。余谓其脉大无力，即令食而投参、耆，犹恐或失之，禁其食而攻之，未遽绝者幸耳。用人参、黄耆各五钱，白术三钱，橘、半各一钱五分，甘草六分，煨姜三钱。诸医鼎沸。用一剂而喘汗差减，倍用参、术至一两，症愈七八，惟食未强耳。此火衰不能生土耳，加熟附二钱，干姜一钱，服二月而始全愈。", "17323": "工部主政王汉梁，郁怒成痞，形坚痛甚，攻下之剂太过，遂若洞泄，一日一夜计下一百余次，肌肉尽消，神气愦乱，舌不能言。余曰：在症已无活理，在脉犹有生机，以真藏脉未见也。此甚虚之症，法当甚补。以枯矾、龙骨、粟壳、肉果以固其肠，人参二两，熟附五钱以救其气。三日之内用参半斤，用附二两，泻减大半，舌遂能言。更以补中益气加生附、炮姜、肉果，大补百日而食进神强，然昼夜下四五行，两手痿废，以仙茅、巴戟、桂、附等为丸，参附汤送下。□五日余而痞消、泻止、能步。向使畏多参、附，或掣肘于投剂之时，或懈弛于将愈之际，安望其在生哉。信医不专者，戒诸。", "17324": "门人薛昙孚之内，十五岁，腹痛甚，面黄体瘦。服清热药，通经药，疏气药，补血养气等药，无效。余察其皮肤甲错，左尺独数，是小肠有痈。脉数知脓已成，当以药溃之。以葵根一两，皂角刺二钱，陈皮三钱，两剂而脓血大下。更以太乙膏为丸，参、耆汤送下，一月而愈。", "17325": "光禄卿吴玄水夫人，腹满而痛，喘急不能食。或以中满治之，无效。余诊其脉，右尺偏大，皮肤甲错。余谓此大肠痈也。先用黄耆、白术、陈皮、当归、白芷托里，三日而脉始数，数则脓已熟矣。用黄耆、角刺、白芷、山甲，加葵根五钱，连投两剂而脓溃如注，昏晕不支。饮独参一两，更以八珍汤补养，一月而康宁。", "17326": "龙华张介甫之内，怀娠腹胀泄泻，肢体肿重。余谓六脉缓大而软，皆缘以泄伤脾，先止其泻，后补其中，参、术、茯苓、肉果、补骨脂，十剂而泄止。更以补中益气加茯苓、牛膝、车前、泽泻、木香、炮姜，二十剂而肿胀愈，未几生男无所苦，□日进参、术平复。", "17327": "儒者吴君明，伤寒六日，谵狂笑语，头痛有汗，大便不通，小便自利，众议承气下之。余谓其脉浮而大，察腹不硬不痛。因思仲景云：伤寒不大便六七日，头疼有热，小便清，知不在里，仍在表也。方今仲冬严寒，宜用桂枝汤。众皆咋舌云：谵狂为阳盛，用桂枝必死。余曰：汗多神昏故妄语。虽不大便，腹无所苦，和其营卫，必自愈耳。用之及夜而笑语止，明日大便通。夫既谵语而能察为表症者，百不得一也。向使误行下剂，则立毙可知。", "17328": "医者王月怀，伤寒五六日以来，下利日数十行，懊𢙐目胀，众谓泻将脱矣，必山药、苡仁补之。余谓其脉沉且数，按其腹便攒眉作楚，此协热自利，谓之旁流，非正粪也，当有燥屎。饮以承气汤，果得结粪数枚，利乃止，懊𢙐亦定。", "17329": "文学韩茂远，伤寒九日，体不能动，口不能言，目不能视，四肢俱冷，众认阴症欲温之。余诊六脉皆无，惟趺阳脉大而有力，以手柱其腹，则热且坚也。煎承气汤下之，得燥屎甚多，遂能言动矣。若按手不及足，察面不及腹者，何以拯此垂绝之症哉！", "17330": "郡守张三星，泄泻无度，自服燥湿分利达气药。余诊其脉滑而无力，此中虚下陷，而痰滞不化也。以六君子加升、柴、沉香、五倍子，十剂而安。", "17331": "明经俞元济，背心一点痛，久而渐大。用行气和血药，绝不取效。余问之曰：遇天阴觉痛增否？元济曰：天阴痛即甚。余曰：脉既滑而遇天阴痛辄甚，其为湿痰无疑。以胃苓汤加半夏三钱，数剂而痛消。", "17332": "刑部主政徐凌如，劳与怒并，遂汗出昏倦，语言错乱，危笃殆甚，迎余视之，脉滑而软，为气大虚而痰上涌。以补中益气汤加半夏、附子，四日而稍苏。更以六君子加姜汁、熟附将两月而愈。", "17333": "文学张方之，久忧暴惊，遂发颠妄，服补心神药，服逐痰涎药，均无俾也。余曰：六脉结而有力，非大下其痰，无由痊也。先服宁志膏三日，遂以小胃丹下之。三月之内，服小胃丹数次，去痰积始尽。更以归脾、妙香加牛黄，龙骨为丸，剂毕而康。向使下之不如是之屡屡，以尽其痰，将成痼疾矣。", "17334": "太学史明麟，经年咳嗽，医谓虚劳。余曰：脉无虚数之象，惟浮大而滑，是风痰胶固于至高之府，未得宣越耳。且多服酸收之剂，故久而日剧。乃用麻黄、杏仁、半夏、橘红、甘、桔、苏子，五剂而愈。", "17335": "邑侯张孟端夫人，忧愤交乘，食下辄噎，胸中隐隐痛。余曰：阳脉滑而阴脉搏，痰血互凝之象也。以二陈汤加归尾、桃仁、郁金、五灵脂，四剂未效。因思五灵脂与人参同剂，善于浚血，即前方入人参二钱，倍用五灵脂。再剂而血从大便出，十剂而噎止，一月而愈。", "17336": "金元之之内患噎，胸腹有奇痛而经阻，医认瘀血。余察其脉，细为气衰，沉为寒痼，若攻瘀血，加霜于雪也。况自下而上，处处皆痛，明非血矣。参、耆、术各二钱，木香、姜、桂各一钱，煎成，和醇酒饮之。甫入口便快，半月而痛止。因常服理中汤，数年弗辍。", "17337": "文学倪念岚，累劳积郁，胸与膈俱闷满，畏食如仇，服理气，改服行痰，改服清火而益病。余曰：脉大而软，两尺为尤，火衰不能生金，反以寒剂伤之，是下井而投石也。乃用六君子加姜、桂，十剂稍效，兼胁八味丸，半载而痊。", "17338": "大方伯张七泽夫人，谷食不安，小便不禁。余曰：六脉沉迟，两尺益甚，水泉不藏，转输违度，是衰火不能生弱土也。以理中汤、八味丸并进，再剂而验，十剂而瘥。", "17339": "顾淡之，劳神之后，燥热甚，头角掣痛，时作时止。医禁其食而解表，越四日而热不衰，议将攻内。余细视之，脉不浮紧，安得表耶？又不沉实，安得里耶？只有少阴大而无力，为劳神太过，乃虚烦类伤寒也。若禁饮食则病深矣，先饮糜粥，用大剂归脾汤，十日而痊。", "17340": "钱台石，年近六十，肢体不能转侧，昏倦不能言，鼻窍不利，二便俱秘。是心肺俱虚，为类中风也。医伐其气，攻其痰，几危矣。余诊之，六脉洪盛，按之搏指。此至虚有盛候，以形色验之灼然也。法当从症不从脉，补中为主，方可回生。不信余言两日，余发声曰：今日不进药，不治矣。以补中益气加秦艽、天麻、竹沥、姜汁，再剂而神清，十日而转侧利便，珍摄半载全愈。", "17341": "工部主政庸名必，心劳大过，又多食海鲜，吐血多痰，喉间如鲠，日哺发热，喜其六脉不数，惟右寸细且涩，右关大且软，思虑伤脾之象也。以归脾汤加生地、麦冬二十余剂，兼进六味丸三月，永不发。", "17342": "侍御冯五玉令爱，灼热咳嗽将一年矣，时仲冬吐血甚，饮食少，大肉消瘦，大便溏泻，脉来七至。余曰：在法不救，然脉尚有根，可以救十中之一二。每剂人参五钱，耆、术、附各一钱五分，陈皮、归身各一钱，日投三剂。约进十余剂，及壮水丸五斤而起床。", "17343": "王邃初，老于经商，患哮喘者二十年。舟次谈及，余谓年望六十难治，及诊脉尚有神，右寸浮滑，是风痰胶固于太阴之经。以杏仁、防风、甘、桔、白芥子、麻黄，三剂而病状减。因以丹溪治哮丸与之，仍日进六君子汤，连服无间，经年而愈。", "17344": "文学陈文阿，两足麻痹，初服和血，改服攻痰，更服导湿，并两手亦患矣。余曰：脉洪而软，阴阳并虚，虚风鼓动，良由攻治太深，真元日削耳。用神效黄耆汤加茯苓、白术、当归、生地，十剂而小效，更以十全大补加秦艽，六十余服而安。", "17345": "京卿叶震瀛夫人，痞闷而喘，肌肤如灼，汗出如洗，目不得瞑，六脉皆代，有医者请以十剂决效。余谓之曰：神气不甚衰者，灯将灭而复明也，汗如油，喘不休，明旦死矣。果夜分神□，初晓死。", "17346": "武科张宁之，纵饮违度，一□小便后滴□数点，谓有余之疾，不医。逾月时有精漏，头目眩晕，神气困倦，服固涩药益漏。余曰：六脉滑大，此曲药中湿热下干精道。以干葛、白豆蔻、白术、茯苓、陈皮、甘草、黄柏，大剂煎，日恣饮五六碗而精止，更以地黄丸料加黄柏，服十余日而愈。", "17347": "太学朱宁侯之子，年十六而精滑，闻女子声即下莫禁，其脉大而无力。此中气虚而下陷，以补中益气汤，倍用升、柴，以六味丸料多加芡实、金樱、五味、人参，服三月而精固。", "17348": "儒者钱用宾，色欲过度，梦遗精滑，服清火药，服固涩药弗效。余以玉华白丹浓煎，人参汤送五钱。两服稍固，兼服生脉散、连鸦散、六味丸，交互服之，一月愈。", "17349": "郡侯李易斋，患白浊，服五苓散、六一散、知柏散。余曰：寸与尺交数而滑，为心肾不交之症，以六味丸加杏仁、远志，麦冬、丹参为丸，朱砂为衣，生脉散送下，五服而霍然矣。", "17350": "文学罗忍庵，精滑经年，膀足肿痛，困顿床席两月余。忽被巨寇火灼之，误以黄柏、井泥傅之，遍身糜烂。医谓火毒入腹，拟用连翘、薄荷等药凉之，余曰：久虚之人脉如蜘丝，气将竭绝，非参、附恐无生理。其弟怒色不允，忍庵信余言，遂煎服而神稍复，肌肤痂脱，用温补二月始安。", "17351": "孝廉王征美，腰痛不得坐卧，服补肾药弗效。余曰：脉缓大而无力，为风湿交侵，用独活寄生汤四剂而痛止，但苦软弱。余曰：邪去则正虚。服八味丸数日而愈。", "17352": "上舍宋敬夫，心腹大痛，伛偻不能仰。日服行气和血药，无益也。余谓寸脉左手滑而急，其气不能以息，偶得一咳，攒眉欲绝。此为心疝无疑。以酱姜进粥，取小茴香、川楝子、青木香、广木香、茱萸、木通，玄胡索、归身、青皮，一服而痛减，五日而安。", "17353": "大博徐淡宁，病余膏粱不节，且伤于怒，腹胀气粗，其脉盛大而滑，按之不甚虚。余用疏肺达肝之剂稍愈，即旦暮更医，两月病增。余曰：今病仍用参、术、香、砂等药矣。用二十余剂而安。", "17354": "先兄念山，谪官浙江按察，郁怒之余，又当炎暑，小便不通，气高而喘，服胃苓汤不效。余曰：六脉大且结，乃气滞也。用盐炒枳壳八钱，木通三钱，生姜五大片，急火煎服。一剂遂通，四剂霍然矣。", "17355": "大史杨方壸，疟发间日，脉见弦紧，两发后苦不可支，且不能忌口，急欲截之。余曰：强截之必变他症，当令其自止。用升麻、柴胡各二钱，提阳气上升，使远于阴而寒可止；黄芩、知母一钱半，引阴气下降，使远于阳而热自已；生姜五钱，劫邪归正；以甘草五分，和其阴阳；以苍术、陈皮，正其胃气。两剂而寒热减，再剂进而止。", "17356": "文学顾伟男之内，痢下一月，脉大而无力，其虚可知。余禁痢药，第以十全大补汤兼补中益气汤加姜、桂，相间而服，二十余日而安。", "17357": "京卿吴伯玉少妾，颈间肿胀，喉间且痛且麻。余曰：此急喉痹也，亦名缠喉风。若不治，明日必死。今胀而喘，毒势方张，且恶寒者，病方在表，急以甘、桔、荆、防、牛蒡、枳壳、薄荷煎成，加生姜汁五匙服之，喘胀如故。急刺少商穴出血，再进前剂愈矣。此症一见恶寒便是表邪，是症若用寒冷药，食冷物，毒邪凝闭无救矣。又硼矾□敛□之剂，无表邪者可用。若见脉浮恶寒，亦在禁例。", "17358": "陈邃玄令郎，年十六岁，发尽脱落，脉数而大。余曰：肾之合骨也，其荣发也。多食甘则骨痛而发落，此《内经》之言也。及揣股髀间骨，果觉大痛。用还少丹加生地、当归作丸，日服一两。兼进清胃汤，半载而发出。", "17359": "孝廉俞彦直，肌肤灼热，神气昏闷，闻食即呕，强食即吐，困惫不支。或欲温补，余按其热处在骨间，脉沉而搏，此伏火也。用黄连一钱五分，山栀、黄柏各一钱，枳壳、陈皮各二钱，甘草五分，煎成入姜汁三匙，服四剂而痊。更以六味丸加生脉散，调摄次岁。", "17360": "张仲舆令爱，未出阁时，困于邪祟，终日谵妄。服安神化痰、祛邪辛香之剂。已无遗用，病不少间也。余曰：六脉忽大忽小、忽沉忽浮，确为祟凭。内服八毒赤丸，外以帛紧拴两臂，复以二拇指相并扎定，以小艾炷于两介甲侧肉处灼之。甫十壮而乞哀愿去，更与四壮，旦日复报七壮而祟绝。", "17361": "鞠上囡，抑郁蒸热如焚，引饮不休，卧床谵语，户外事如见。医认伤寒，又认鬼祟。余曰：肝脉浮濡，肺脉沉数。夫木性虽浮，肝则藏血藏魂，而隶于下焦，脉当沉长而弦。金性虽沉，肺则主气藏魄，而居乎至高，脉当浮短而涩。肺燥而失其相傅之权，则肝为将军之官，无所畏制，遂飞扬而上越，不能自藏其魂耳。魄强则魂安，今魄弱而魂不肯退藏，乃逐虚阳而放荡，此名离魂。魂既离矣，则出入无时，故户外事皆见皆闻也。当救肺金之燥，使金气足而肝木有制，则魂归矣。用清燥加减，人参、黄耆、麦冬、天冬、五味、当归以润肺养气；芍药、枣仁、栀子、甘草以摄肝归魂；橘红、沉香使九天之阳下降；升麻、柴胡使九天之阴上升。两剂而呓语止，十剂而烦渴皆除，一月而病魔退。", "17362": "新安吴文邃，眩晕者三载，战栗恶寒，五月而向火。数妾拥居帷帐，屡服姜、桂，千里延余。予谓脉浮之细小，沉而坚搏，是郁火内伏，不得宣越也。用山栀三钱，黄连二钱，黄柏一钱五分，柴胡一钱，甘草五分，生姜五片，乘热亟饮之。移时而恶寒稍减，再剂而辍去火炉，逾月而起。更以六味丸、知、柏，用人参汤送下，两月全安。余知此病者，虽恶寒而喜饮热汤，虽脉细而按之搏指，灼然为内真热而外假寒，热极反兼胜己之化。以凉药热饮者，内真寒而外假热之剂也。", "17363": "苏淞道万玄圃，神气不充，两足酸软。服安神壮骨，服补肾养阴，服清热去湿，卒不效也。余曰：六脉冲和，独有中州涩而无力，是土虚不能制水，湿气注于下焦。以补中益气汤加苍术，旬日愈。夫脉虚下陷之症，用牛膝、苡仁、黄柏等下行之剂则愈陷，故前药所以无功也。", "17364": "车驾郎赵昌期，两臂痛甚，两手灼热。用清胃健脾，三日溺色如泔。余曰：六脉俱涩，喉有喘呼。《内经》曰：肺所生病者，上气喘满，臂痛，掌中热，溺色变。今病是也。用枳壳、桔梗各三钱，茯苓、知母各二钱，甘草一钱，一剂而痛减，再剂而溺清，三剂而安。", "17365": "太常卿胡慕东，形神俱劳，十昼夜目不得瞑，服归脾汤数剂，中夜见鬼。更服苏时丸，无功。余曰：脉大而滑，痰气胶固也。二陈汤加枳实、苏子，两日进四剂，未效。以人参汤送滚痰丸，下痰积甚多，因而瞑眩。大剂六君子汤，服一月愈。", "17366": "沔阳州学宪钱长玉夫人，腹痛肠鸣，或谓怒伤肝气，又谓虫积血积。余见其身伛偻而气喘呼，脉弦而细。此女子之疝也，用青木香、广木香各一钱五分，川楝子、木通、肉桂，茴香各一钱，当归、甘草各八分。一剂痛止，四剂已。", "17367": "丹阳邑侯王维凝，伤寒汗下后时时灼热，医谓汗后不为汗衰，邪气深重，禁其食，服清剂。困倦已极，求治于余。余曰：脉小腹濡，此邪气已尽，正气未复，谷气不加，阳明失养，非病也，饥也。病者不能言，但首肯不已。徐进糜粥日五六次，居五日，不药愈。", "17368": "吴门佥宪郭履台，年高入房，昏倦不食。医知其虚，服补中益气汤加姜、桂，不效。遣使迎余，兼夜而往视之，目不能瞬，口不能言，肌体如烙。余曰：脉大而鼓，按之如无，真气欲绝，正嫌病重而药轻耳。以人参三两，熟附三钱，煎液，半日饮尽，目开。再剂能言笑，数日神气渐复。用大剂补中，兼服八味丸，五十日而起。", "17369": "吴门孝廉王征明，喘咳吐血十余年，余曰：脉浮而濡，是金脏既薄而飞风客之，为处薄荷二钱五分，人参、麦冬各三钱，桔梗、苏子、甘草各一钱，橘红、茯苓各八分，二剂效，三月而除根。", "17370": "相国方禹修，足疮浸淫三载。服解毒药、燥湿药、清热祛风药。余曰：脉大无力，气虚之候也。气虚则下陷，服疏利药，则愈下矣。以补中益气加萆薢、苍术服之，外用当归白术膏和二妙散涂之，脓水渐干，更以六味丸加苍术、黄柏，间服一年而愈。", "17371": "新安吴修宇令侄，烦躁发热，肌体骨立，三年在床，目不得瞑。余诊其肝脉沉而坚，此怒火久伏，木郁宜达也。以柴胡五钱，白芍、丹皮、栀子各三钱，甘草、桂枝各五分。日晡方进剂，未抵暮而熟寐，至明午未觉，举家惊疑。余曰；卧则魂归于肝。三岁不归，疲劳已极，譬如久热得凉，乐而忘返，无庸虑也。直夜分方醒，喜不自禁，愈。", "17372": "楚中中翰秦五梅，发热困倦头痛，以风治转剧。余曰：六脉虚软，中气下陷，阳气不充而头痛，阴气衰少而内热。补中益气加葛根一剂而减，数剂而愈。", "17373": "相国方禹修夫人，触于惊恐，身霭霭如在车船，开目则眩，起立欲仆。医补虚化痰，屡投弗效。余为察脉，左独沉牢。是惊气入心，畜血为祟。用大黄、川山甲、归尾、桃仁、降真、苏木、郁金，一剂而血下，再剂而复下数升而愈。", "17374": "延平郡唐东瀛，多思善郁，昏冒痰涌，口㖞语涩，四肢不随，时时悲泣，脉大而软，为脾肺气虚，风乘经遂。余以补中益气加羌活、防风、秦艽、天麻、半夏、钩藤，十剂而症减。又以前方去风药，倍用人参、黄耆，兼八味丸，两月乃安。", "17375": "吴门太史姚现闻，中风昏愦，面赤发笑，难饮食月余。余于孟秋诊之得石脉，即语门生唐名璧曰：石者，冬脉也。新秋见之非其时，果殁于冬。", "17376": "江右学宪□□之父，肠风下血，面色枯黄，腹高不快。余诊脉右关浮缓，此脾土□足风湿交浸也。白术一钱，人参、茯苓、黄耆、陈皮、甘草各一钱，升麻、柴胡各八分，数十剂而色润。", "17377": "邵武邑宰何金阳令郎，久困虚劳，已濒于危，数千里招余。其脉大而数，按之极软，此中气积虚，反为凉剂所苦耳。乃以归脾汤入桂一钱，人参五钱，当晚得熟寐。二十日而汗敛精藏。更以还少丹与补中益气间服，数月而康。", "17378": "青溪陈县尊名鏕夫人，蒸热干咳，肌体骨立，服滋阴降火而食减泄泻。余曰：脉状如丝，阳气虚也，以补中益气加肉果、诃子、干姜，月余而泻止减咳矣。", "17379": "南都许轮所孙女，十八岁，患痰喘羸弱。于四月初诊之，手太阴脉搏指，足少阴脉如烂绵，水衰而火乘金也。余曰：金以火为仇，今不浮涩而反洪大，贼脉见矣。肾水不能救，秋令可忧。至八月初五日复诊之，脉之洪大者变为细，肾之软者变而为大。岁在戊午，君火司天，法当两尺不应。今尺当不应而反大，寸当浮大而反细。经曰：尺寸反者死。况肺脉如丝，悬悬欲绝。经云：肺至悬绝，十二日死。此病短期，当在十六日。然安谷者逾期，不安谷者不及期，今食不断，于十六、十六二日皆金，助其一线之气，安得遽绝！十八日交寒露节，又值火日。经云：手太阴气绝，丙日笃，丁日死。寅时乃气血注肺之时，不能注则绝，轮所以能食，不信。于十八日寅时死。", "17380": "新安上□方太和，怒后大醉，肢体肿胀，烦满欲绝，六脉大且坚，当逐其水。用疏凿饮子一剂，而小便大行，再服而四肢宽，以五皮饮加木香、沉香，服数日而瘥。", "17381": "两广都宪李来吴，积劳善郁，肢体胀满，服胃苓汤加木香、白豆蔻，转增痞闷。余曰：脉沉涩而软，色黄而枯，宜大温大补。不从，仅用人参二钱，稍觉宽舒，欲投姜、附不肯。余曰：症坐虚寒，喜行攻伐。弗听，果两月殁。", "17382": "闽中周东志，形羸善饭，忽胀满。医认食多不化，服槟榔、枳、楂、麦芽、神曲、厚朴，胀势转增。余曰：右手脉滑，知为胃火。用石膏、黄连、山栀、木香、陈皮、酒蒸大黄，二剂而胀止。", "17383": "闽中太学张仲辉，纵饮无度，兼嗜瓜果，忽患泄泻，日一十余次。先服分利，不应；继服燥药，转见沉剧。余曰：六脉俱浮，因思经云春伤于风，夏生飧泄。非大汗之，不能解也。用麻黄、升麻、干葛、甘草、生姜煎服。或曰麻黄为重剂，虽伤寒不敢轻用者。仲辉叹曰：吾命将尽，姑服此剂，以冀万一。遂服而取汗，泄泻顿止。", "17384": "白下姚越甫，乙卯秋二子俱痨瘵死，悲痛不已。蒸热咳嗽，两目不明，腰肢无力，口吐清涎，唇有白点。服滋阴药，开郁药，补中药，清火药。余曰：左脉数大无伦，右脉沉缓无力。此为传尸，有虫蚀藏，不去虫，无生理。用加芎归血余散，加甘遂、天灵盖，共为末。以东引桃枝煎汤，于八月初二天未明时空心调服，至辰、巳时，下虫如小鼠者三枚，两头尖者数枚。以病者困顿，亟于人参一两煎服。薄暮又服参一两。明日四鼓，更以末药减半服之，下两头尖虫数枚。另以十全大补汤料丸服半载平复。其虫以烈火煅过，雄黄末研匀，入瓶封固，埋于僻地绝人行处。", "17385": "大司丞孟文时，□□□痛甚，服理气药。余曰：脉缓而涩，法当峻补。医曰：诸痛属实，痛无补法。余强用参、耆、术各三钱，陈皮钱半，甘草四分服之。是夕痛定，明日进食。", "17386": "江右给谏晏怀泉如夫人，盛暑腹痛，自汗淋漓。服清火行气药，俱无当也。余曰：左脉涩，右脉濡。此气弱不能运行，血因以阻耳。用参、耆、姜、桂、桃仁、归尾、苏木、玄胡索、郁金，二剂而痊。当暑而用姜、桂，舍时从症也。", "17387": "抚台周洱如，伤于拂郁，胀满喘嗽，多药愈肿，卧床不起，粥饮一杯。余曰：左寸大而滑，右关弱而沉，法当参、附。门人柳子青曰：曾服参喘急，服附烦焦矣。余以秋石制人参，黄连制附子，白蔻制白术，薄荷制橘红，沉香末佐之，另以通草、茯苓各一两，煎液二碗。投药煎成，加姜汁半酒钟，和匀热服，更以红铅、煅鼠粪，乌、附、冰、麝，蒸其脐，小便如泉涌。治五日而肿胀减十之七，进饭一碗。又十日而肉食，精神焕发矣。会部院索钱谷舟楫，乃昼夜草文，忧劳靡宁，三日而前疴复作。脉数大无伦，按之则了不可见，是根本败坏，虚阳上亢之象也，且春杪如得夏脉，因辞不治，果于午月殁。", "17388": "常镇道张大𤸒子，舍有腹疾。余曰：六脉俱濡，气口独牢，乃中气太虚而有坚积也。困惫不食者，以攻积太过也。虽用补中汤，只可延时日耳，果月余毙。", "17389": "给谏章鲁斋，肌痒且麻，三日发黑块如博棋子，大便痛楚，呕恶，一岁四五发，服热毒药。余诊其脉，举之则大，按之则缓，湿与风俱也。以荆、防、羌、独，二术、芎、归、甘、桔、黄耆、茯苓、木通，十剂而旋效。更以前料为末，酒糊为丸，参汤送下，以杜其根蒂。", "17390": "屯院孙潇湘夫人，久痢发热不食，犹服香、连、芩、芍。余曰：脉大而数，按之如蜘丝，腹痛喜按，此火衰不能生土，内真寒而外假热也。煎附子理中汤，待水冷服之，一剂而减，再加肉果、五味子，二十余剂而起。", "17391": "郡侯傅世烈，疟发而汗如雨，此风伤卫耳。医认气虚，用参、术致病。余以青皮饮加卜子、麦芽而愈。因不节饮食，腹痛下痢。余曰：既经下后，愈而复发，一月之疟，两月之痢，脉如悬丝，其虚已极，正须大补，第杯水不救车薪火矣。用二剂少安，逾旬不起。", "17392": "山右何宗鲁，夏令好饮凉水，因宗师发放，晨起候至未申，为炎威蒸逼，饮水过多，胀满不食，腹如抱瓮，气高而喘。余曰：皮薄而光泽，土伤不化也，且病暴成，六脉坚实，法当峻剂攻之，以舟车丸三钱，香薷汤送下，再剂而二便下水，腹减如故。", "17393": "青浦邑尊韩原善，遍体发黄，服茯苓渗湿汤。余曰：脉细如丝，身冷如冰，口中不渴，此阴黄也。以姜汁同茵陈遍身擦之，服六君子加干姜、熟附、茵陈，应手而效。", "17394": "苏淞道张綗庵，秋初下痢，服香、连、归、芍、枳、朴、槟榔、陈皮。用之两月而病不衰。余曰：脉滑而有力，失下故也。于前剂中加大黄一钱，两剂下积秽甚多，更以香砂六君子调摄而神旺。", "17395": "抚台毛孺初，痢如鱼脑，肠鸣切痛，闻食即呕。余曰：脉虽洪大，按之濡软，右尺倍甚，此命门火衰，不能生土。若非参、附，无益于病。今脾土太虚，虚则补母，复何疑乎？用人参五钱，熟附一钱五分，炮姜二钱，白术、陈皮各二钱。三剂呕吐止，更服补中汤加姜、附，十四剂即理事。", "17396": "襄阳邑侯于鉴如，酒后腹痛，痛处渐坚。余曰：脉大而长，且搏指矣，必有坚积。然两尺濡软，不敢峻攻。先以四君子汤补完胃气，然后以攻积丸，下十数行黑而韧者，腹犹痛也。经曰：大积大聚，其可犯也，衰其半而止。但以补中益气加蓬术为丸，服两月而霍然。", "17397": "相国沈明缜，丙辰仲秋疟发呕吐，出蛔虫五枚，昏闷不能食，六脉沉细。余曰：疟邪干犯太阴，中寒而蛔动也，以理中汤加乌梅、黄连，数剂吐止，去乌梅、黄连，加熟附子五剂愈。（此病素有寒中之患者。）", "17398": "新安程武修，患疟一日一发，自巳午时起至次日寅时退，月余困顿。余曰：脉沉而大，头痛，恶寒，寒势甚于热势，此非失汗，必误截耳。武修云：曾服家中截疟丹，百发百中。弟服之病势增剧，何也？余曰：邪方炽而止之，邪不能伏，愈猖獗矣。以石膏、黄芩各三钱，抑阳明之热，使其退就大阴；豆蔻三钱，生姜五钱，救太阴之寒，使其退就阳明；脾胃为夫妻，使之和合，则无乖乱之愆。半夏、槟榔各钱半，祛胸中之痰；苏叶三钱，发越太阳之邪；干葛一钱，断其入阳明之路。服三剂而势减半，改用小柴胡汤四剂，而疟不复发矣。四日服八剂效。", "17399": "休邑吴文哉，伤寒发躁，面赤足冷，时时索水不能饮，且手扬足掷，难以候脉。五六人制之就诊，则脉大而无伦，按之如无。余曰：浮大沉小，阴证似阳，谓之阴躁，非附子理中汤不可。伊弟日休曰：不用柴胡、承气、不用三黄、石膏，反用热剂耶。余曰：内真寒而外假热，服温补犹救十中之七。日休卜之吉，乃用人参四钱，熟附一钱，白术二钱，干姜一钱，甘草八分，煎成冷服之。甫一时许，而狂躁少定，数剂而神清气爽。", "17400": "吴门周复庵，年五旬，荒于酒色。忽头痛发热，服羌活汤以散邪，汗出不止，晕昏不苏，余灸关元十余壮而醒，用四君子加姜、桂服之而愈。因分析家产，劳而且怒，复晕而厥，用参、附大剂煎服稍醒。但一言语一展动便昏，一日昏绝者数四。服参三两，以人参煮羊肉、大米羹服之，至五日昏止。余曰：元气虽虚，幸脉有根蒂，非三年调摄不可。乃遵余言，两月服人参四斤，投剂六百，丸药三十斤愈。", "17401": "湖州王文麓，吐血干咳五年。余曰：察君之脉，望君之色，俱合补气，却闻服参必喘而见血，肺素有热也。然疾已危，非人参不能振其衰者，乃以秋石制之，便可大进而无虞也。何则？人参入肺补气，金家有火，故不胜也，然人参畏溲及卤，咸润下可以制其上升之性耳。先服一钱，明日服二钱，嗽减少，用四君子加麦冬、五味、陈皮，以秋石汤泛为丸，同地黄丸兼进，服至两年竟愈。", "17402": "吴门张饮光，发热干咳，呼吸喘促，服苏子降气，改服八味、理中。余曰：两颊俱赤，六脉数而有力，金木两家蕴热不得越也。用逍遥散济以秋石，地黄丸济以龟胶，历岁不怠，乃克全功。", "17403": "京师须日华，暴怒伤阴，吐血甚多。余思《内经》云：大怒则血菀于上，令人薄厥。今血厥而呕数升，金气大虚，而木寡于畏也。以人参一两，培养金宫，且木欲实，金当平之。又况血脱益气，治其母也。以沉香三钱制肝木，更以炮姜少许为向导之兵，再进而血始定，然脉法则已违度矣。经云：至如颓土，按之不得，是肌气予不足，白蔂发而死。言木克土也。及期果验。", "17404": "郡侯陈莲石，易于感冒，得风剂乃安。频发频服，四五年矣。余曰：脉大如波涌，软若𤸒肥，表虚而玄府不密也。日散其邪，是开门延寇矣。制玉屏风散三斤，剂毕而永不再发。", "17405": "苏淞道程九屏，嘈杂不宁五月矣，服痰剂、凉剂。余曰：脉阳强而阴弱，病得之酒且内，用连理汤同加减八味丸并服，三月而胸中之楚尽释。", "17406": "青田县令杨龙交少妾，发热头疼，遍身有细点。医认癍也，治以升麻、犀角，转加烦闷懊𢙐。余曰：脉浮而大，皆有头粒，此太阴之疹，非阳明之癍。癍为热毒，蕴于阳明，病在肌肉。疹为风邪客于太阴，病在皮毛，乃用荆、防、甘、桔、蝉退、陈皮、生姜，二剂而疹透。", "17407": "太史李集，虚劳而无度，醉而使内，汗发知雨，痰涌如泉，脉沉而涩，两尺为□，余语伊修杨玄润曰：涩脉见于痰家，实艰于治，况尺涩更甚，伤精之象也，在法不治。勉用六君子合补中数剂小效，众皆喜。余曰：涩象不减，按重无根，有日无月矣，果越十六日而殁。", "17408": "檇李给谏黄健庵，中风大虚，喘急自汗，得食即吐，脉大且疾，沉之豁然，内有真寒，外有假热，当用理中汤冷饮之。不从，反服清火剂而死。", "17409": "朱修之脉痿", "17410": "金陵朱修之，八年痿废。余曰：六脉有力，按之搏指，犹是强饭。此心阳独亢，壮火炎蒸，故称脉痿者是也。以承气下数行，右足展舒。再下之，手中可以持物。更用芩、连、山栀、酒蒸大黄蜜丸，以参汤送。一月之内，积滞尽去，四肢皆能屈伸。余曰：积滞虽祛，真元虚惫矣。用三才膏十斤，尽剂而康。", "17411": "崇明文学倪君俦，痿废著床，春秋四易。余曰：脉浮之则大，沉之则濡，荣卫交损也。用十全大补汤加附子、鹿茸、虎骨、龟板、黄柏为丸，日进一两。百日而机关利，半载而康。", "17412": "给练侯启东，腹中嘈杂，左肋异痛，呕吐涎沫，每饮食到口，咽嗌间若有一物接之者。余曰：脉大而数，按之辄减，此虚而挟湿，湿热相兼，虫乃生焉。中气素虚，当以参汤送槟榔丸以涤虫，种虫不祛而服补汤无益。不从，竟至不起。", "17413": "江右方春和，年近五旬，多欲善怒，患噎三月，日粥一钟犹吐其半，六脉弱薄，神情困倦，喜饮热汤，小便清白。用理中汤加人乳、姜汁、白蜜，二剂便减，十剂而多粥，加减至四十剂，而噎与吐咸绝迹矣。", "17414": "练川钱远之，以鼓盆之戚太过，胸痛不能饭，数日粥不下咽，随食随吐，涎如卵白，溲便坚涩。余曰：脉有根本，其畜血可下也，用酒蒸大黄加桃仁、归尾、郁金、延胡索、降真香、山甲，蜜丸酒送四钱，再剂而黑皆下，补养数月，病苦减去。", "17415": "上海邑尊高肖泉，大醉大劳，吐血二十余碗。服滋阴止血药，两颊俱赤，六脉洪大，按之有力，时仲春重裘登火炕。余曰：此因形体过暖，为有余之症，法当凉之。用生地、芍药、栀、连、白蔻、橘红、甘草，十剂而止，更以清胸汤料为丸，服之而安。", "17416": "浙江邑宰严知非，淋沥大痛，阴脉疾而鼓，为龙火虚炎，医泥痛无补法，转通转虚。余以六味丸料加车前、牛膝、沉香、通草，八剂痛减。医曰：实火妄行而淋痛反补耶。余仍用补中汤、六味加减互进，五月而愈。", "17417": "锡山张鸣之，吐血两年，面色痿黄，潮热咳嗽，膈有微痛，服滋肾，服补中。时仲冬，余曰：脉数而沉且搏，其痛而不可按，而甚于夜分，是坚血畜积，非大下不可，又以久痛，不敢峻攻，用郁金、降真香、当归、生地、山甲、蓬术、人参，下血如漆者数次而痛减，月余复痛。余曰：病重而药轻也，乃以大黄、干漆、蓬术、郁金、山甲、肉桂、归尾、桃仁、虹虫为丸。每日服参耆之剂，午后服丸钱许。十日而血积大下，数次痛止神旺，吐血烦热咸已。", "17418": "此书系我曾祖于磐公手录，至今有五十余年矣。其残编犹存于古架之上，览其前后，凋落不堪，已成半废。吾父见之曰：此士材李公家藏之脉案，因吾祖与李公旧交，故得此抄录以秘藏之，当须珍重。噫！我曾祖手录之时，不知四世孙之续其全矣。吾续之后，不知复有何人重较耶！", "17419": "医，生死关头最重事也。张长沙云，居世之士，曾不留心医述，上疗君亲，下救贪贱，中以保身，但逐荣利，企睡权豪，卒遇非常，身居死地，百年寿命委付凡流，岂不危哉！由此观之则医之一道殆与六经并重，而非可以艺术名也。久矣，仆人非司马，病似休文，庚寅一病，坐困八年，日与名医谢鹿圆先生讲论，复聚集古今名家方书，床头痤右，无地不有，寝食其中者数年，始知孰为大家，孰为小家，孰为过正，孰为当宗，孰为当辟，一一批点，得所指归，于是人定胜天，霍然出户，然后悟今此诸症坌集，皆从前庸医金石妄投所致，甚悔学医之不早也。医之不明，其害至此，然而此道更未易言也，余虽潜心有年，究不过窥其藩篱，而于古人得心应手之妙，终不敢望其肩背。独怪夫世之业此者，门户未窥，脉理不晓，家无数卷之书，室鲜名师之授，独记此一二汤头歌诀，以应万变无定之病，侥幸病之合方，未必方之能合病也，其不草营人命也几希！庚子应试都门，一日与张子菊如雨窗对酌，偶道及此，不禁畅谈，张子闻之津津有味，忙促余书纸，以为后学指南，余遂录其当看书目与医中关键最紧要者，简括数篇，以告知已，而於单方绝口不言，俾入门者有所适从，得明其理与法，不致徒记一二汤头，祸世殃民，亦一已消灾禳疾之道，也敢言医哉！是为序。", "17420": "朱丹溪，元朱震亨，号丹溪，著有《脉因症治》一书，先论脉，次因，次症，后乃论治。此无方之书也，人多未睹。又著有《丹溪心法》，专以知柏寒凉之药治阴虚等证，此有方之书也，人多宗之，然唯阴虚有实火者宜之，否则断不可胶柱也，慎之。", "17421": "李时珍《本草纲目》，时珍，号濒湖，湖北人，父子名医。著《本草纲目》，大部药性至此备矣，诚博物君子也。内有《濒湖脉学》一册，辨释精详，以二十七脉编为七编，最令人便记，不可不知，后人又以纲目中一切古方，分门集成一册，名曰《普门医品》，亦可便览，但古方用于今日多无验，此又不可胶柱也。", "17422": "李士材，公讳中梓，字士材，江苏松江人，副车。医道为本朝开宗第一家，无偏无弊，寒热适中，诚吾辈之良师也。著《颐生微论》、《医宗必读》（内有《四言脉诀》，《脉法心参》亦佳）。《士材三书》：一《诊家正眼》，一《本草通玄》，一《病机沙篆》。而《诊家正眼》一书，专论脉理，极其精详，诚千古脉法之大成也，学脉者，当宗之，然此书系公晚年工夫，医通禅矣，末附《寿世青编》一卷最妙，此养生修炼之法也，不可不知。", "17423": "《医学入门》，其中徒采取四大家书，挂一漏万，毫无折衷定论，且脉诀又宗叔和，正不知其为高阳生伪诀，何医学入门之有，不可为训。", "17424": "《东医宝鉴》，杂辑成书，不论美恶，于己毫无论断，令人无所适从，内治阴虚宗丹溪，脉诀宗叔和，不可为训。", "17425": "论脉", "17426": "脉不可看坊间所售叔和脉诀。晋王叔和撰脉经十卷，为医家一经，最妙书也。其实并无脉诀歌括之式，后因真书丧亡，五代时高阳生伪造歌诀，假冒叔和之名，鱼目混珠，遂使其书不可为训，历代诸名家辨之详矣，而士材辨之尤力。今人所见不广，不知真假，群以此书奉为典型，家弦户诵，以致脉理不明，大为所误，良可呗也，然而脉书惟李士材《诊家正眼》议论精详，皆本《内经》，实千古脉家之大成。次之《濒湖脉学》、张景岳《脉神章》，皆有道之言，而景岳十六脉尤为简老概括。然必平日先看《士材三书》二十八脉，与濒湖二十七脉，然后方看景岳十六脉，始知议论简老，概括之妙，此余阅历之言，亦凡事由博入约自然之理，不可不知所先后也，会心人自领之。", "17427": "脉有三部九侯，寸关尺三部也，浮中沉九侯也。每部各有浮中沉三侯故曰九。每侯五十至，每一部脉看一百五十至，三部共四百五十至，左右六部共九百至。今人胡乱看之，可谓粗之至矣。左寸属心，关属肝，尺属肾，谓之心肝肾。右寸属肺，关属脾，尺属命门，谓之肺脾命门。然而左尺右尺皆肾也，左肾属水，右肾属火，命门居两肾之中，士材辨之详矣，而亦谓之肺脾命者，不过分别令人便记耳。然右尺肾火，即命门相火亦通。", "17428": "人迎系阳明胃脉，气口系太阴肺脉，所谓寸口即气口也，非指左右而言也。李士材《医宗必读》与张景岳书辨之甚详，不可胶柱而鼓瑟也。", "17429": "寸关尺三部歌诀，实照依《内经》新编，此图悉载《士材三书·诊家正眼》中，并《医宗必读·四言脉诀》，一见自明（按大小肠系下焦部位，高阳生伪诀竟列之心肺上部，谬也）。今照《内经》改正：左心膻中肝膈肾，内与小肠膀胱并。右肺胸中连胃脾，命门大肠皆一定。", "17430": "二十八脉名目歌诀：（濒湖二十七脉无疾脉）浮沉迟数动牢革，长短洪微疾滑涩：紧缓细濡代促弦，散芤结伏弱虚实。此余所新编便记者，以浮沉迟数四字作起，提纲也，以虚实二字作结，点睛也。极有深意，明乎此，可与言脉矣。", "17431": "浮沉迟数四字提纲诀：（亦新编）洪虚散芤濡微革，七脉俱在浮分得。若夫伏牢细弱实，五脉又于沉中别。缓涩结代迟之形，滑紧促动数之列。惟有弦脉与长短，三脉不在四部设。", "17432": "景岳十六脉，有论在前。", "17433": "死脉六部歌诀，此即无胃气之脉，内经所谓真藏脉见是也。雀啄连来三两啄，屋漏半日一点落，鱼翔似有又如无，虾游静中忽一跃，弹石硬来寻即去，搭指散乱如解索，寄语医人仔细看，六脉一见休下药。", "17434": "奇经八脉，此二十八脉之外，另有此奇经八脉也。督、任、冲、带、阳𫏋、阴𫏋、阳维、阴维。", "17435": "诊脉法", "17436": "滑伯仁曰，诊脉之道，先调自己气息，男左女右，先以中指取定关位，去下前后二指，初轻候消息之，次中候消息之，自寸关至尺逐部寻究。一呼一吸之间脉行四至为率，闰以太息五至，为平脉也。其有太过不及，则为病脉。各以其部断之。", "17437": "又曰，臂长则疏下指，臂短则密下指。三部之内大小浮沉迟数同等，尺寸阴阳高下相符，男女左右强弱相应，四时之脉不相戾，命曰平人。其或一部之内独大、独小、独疾、独迟，左右强弱之相反，四时男女之相背，皆病脉也。左手不和为病在表，为阳、主四肢。右手不和为病在里，为阴、主腹藏。", "17438": "又曰，察脉须识上下、来去、至止六字，不明此则阴阳虚实不别也。上者为阳，下者为阴，来者为阳，去者为阴，至者为阳，止者为阴也。上者自尺部上干寸口，阳生于阴也。下者自寸口下于尺部，阴生于阳也。来者自骨肉之分而出于皮肤之际，气之升也。去者自皮肤之际而还于骨肉之分，气之降也。应曰至，息曰止也。", "17439": "扁鹊曰，初持脉如三菽之重，与皮毛相得者，肺部也。如六菽之重，与血脉相得者，心部也。如九菽之重，与肌肉相得者，脾部也。如十二菽之重，与筋平者，肝部也。按之至骨，举指来疾者，肾部也。", "17440": "脉分四时六气", "17441": "十二月大寒至二月春分，为初之气，厥阴风木主令。经曰，厥阴之至其脉弦。", "17442": "春分至小满，为二之气，少阴君火主令，经曰，少阴之至其脉钩。", "17443": "大暑至八月秋分，为四之气，大阴湿土主令，经曰，太阴之至其脉沉。", "17444": "脉分五脏", "17445": "肝脉弦，心脉钩，脾脉代，肺脉毛，肾脉石。", "17446": "五藏平脉", "17447": "肝脉来耎弱，招招如揭长竿木稍，曰肝平。招招犹迢迢。揭高举也。高揭长竿，稍必和缓，乃弦长而兼和缓柔软之象也。", "17448": "心脉来累累如贯珠，如循琅玕，曰心平。连珠、琅玕，皆状其盛满流行，而无太过不及之弊也。", "17449": "脾脉来和柔，相离如鸡践地，曰脾平。和柔者悠悠扬扬也。相离者不模糊也。如鸡践地，取其缓而不迫胃气之妙也。", "17450": "肺脉来厌厌聂聂，如落榆荚，曰肺平。厌厌、聂聂涩之象也。如落榆荚毛之象也。轻浮和缓为和平之象。", "17451": "肾脉来喘喘累累，如钩按之而坚，曰肾平。喘喘、累累、如钩，此三者皆心脉之阳也，而济之以沉石，则阴阳和平也。", "17452": "反关脉", "17453": "脉不行于寸口，由列缺络入臂后，手阳明大肠经也，以其不正行于关上，故曰反关，必反其手而诊之，乃可见也。左手得之主贵，右手行之主富，左右俱反富贵两全，男女皆然。", "17454": "冲阳者，胃脉也。一曰趺阳，在足面大指间五寸骨间动脉是也。凡病势危笃，当侯冲阳，以验其胃气之有无，盖土为万物之母，资生之本也。故经曰冲阳绝死不治。", "17455": "太谿者，肾脉也。在足内踝后跟骨上陷中动脉是也。凡病势危笃，当侯太谿，以验其肾气之有无，盖水为天一之元，资始之本也。故经曰太谿绝死不治。", "17456": "太冲者，肝脉也。在足大指本节后二寸。经曰诊病人太冲有无可以决生死。《难经》曰：上部有脉下部无脉，是人当吐，不吐者死。", "17457": "脉有不可言传之说", "17458": "脉之理微，自古记之，昔在黄帝，生而神灵，犹曰若窥深渊，而迎浮云。许叔微曰，脉之理幽而难明，吾意所解，口莫能宣也。凡可以笔墨载，可以口舌言者，皆迹象也。至于神圣，非心领神会，乌能尽其元微，如古人形容胃气之脉，而曰不浮不沉，此迹象也，可以中候求也。不疾不徐，此迹象也，可以至数求也。独所谓意思欣欣、悠悠，扬扬，难以名状，非古人秘而不言，欲名状之而不可得，故「引而不发，跃如。」于言词之表，以待能者之自认耳。东垣至此亦穷于词说，而但言脉贵有神，惟其神也，故不可以迹象求、言语告也。又如形容滑脉而曰替替然如珠之圆转。形容涩脉而曰如雨沾沙。形容紧脉而曰如切绳转索。形容散脉而曰如杨花散漫。形容任脉而曰寸口丸丸。此皆迹象之外别有神理，就其所言之状，正惟穷于言语，故借形似以揣摹之耳，盖悟理虽入微之事，然迹象未明，从何处悟入，思境未苦，从何处悟出。必于四言之诀，二十七字之法诵之极其熟，思之极其苦，夫然后灵明自动，神鬼来通。启玄子曰：「欲登泰岱，非径奚从？诣扶桑，无舟莫适。」其是之谓乎。", "17459": "逐脉审察者，一成之矩也，随人变通者圆机之士也。肥盛之人，气居于表，六脉常带浮洪。瘦小之人气敛于中，六脉常带沉数。性急之人五至方为平脉。性缓之人四至便作热。看身长之人，下指宜疏，身短之人，下指宜密。北方之人每见实强，南方之人恒多软弱。少壮之脉多大，老年之脉多虚。酒后之脉常数，饭后之脉常洪。远行之脉必疾，久饥之脉必空。室女、尼姑多濡弱，婴儿之脉常七至。经曰：「形气相得者生，三五不调者死。」其可不察于此乎！", "17460": "脉者气血之先，阴阳之兆，贵得其纲领而提挚之也。左手为阳，右手为阴。关前为阳，关后为阴。浮取为阳，沉取为阴。长大为阳，短小为阴。明乎此，而脉之大端已在是矣。故曰约而言之，只浮沉迟数已见其梗概，博而考之，虽二十四字未尽其精详。经曰：「知其要者一言而终，不知其要流散无穷。」此之谓也。", "17461": "脉有相似宜辨", "17462": "洪与虚皆浮也，浮而有力为洪，浮而无力为虚。沉与伏皆沉也，沉脉行筋间，重按即见；伏脉行于骨间，重按不见，必推筋至骨乃可见也。数与紧皆急也，数脉以六至得名，而紧则不必六至，惟弦急而左右弹状，如切紧绳也。迟与缓皆慢也，迟则三至，极其迟慢，缓则四至，徐而不迫。实与牢皆兼弦大实长之四脉也，实则浮中沉三取皆然；牢则但于沉侯取也。洪与实皆有力也，洪则重按少衰，实则按之亦强也。革与牢皆大而弦也，革则浮取而得，牢则沉取而见也，濡与弱皆细小也，濡在浮分，重按即不见也；弱主沉分，轻取不可见也。细与微皆无力也，细则指下分明，微则似有若无模糊难见矣。促结涩代皆有止者也，数时一止为促，缓时一止为结，往来迟滞似止非止为涩，动而中止不能自还止有定数为代。", "17463": "脉有相反宜参", "17464": "浮沉者脉之升降也，迟数者脉之急慢也，滑涩者脉之通滞也，虚实者脉之刚柔也，长短者脉之盈缩也，洪微者脉之盛衰也，紧缓者脉之张驰也，牢革者脉之内外也。动伏者脉之出处也，促结者脉之阴阳也，濡弱者脉之穷于进退者也，芤弦者脉之见于盛衰者也。经曰前大后小，前小后大，来疾去徐，来徐去疾，去不盛，来反盛，去盛来不盛，乍大乍小，乍长乍短，乍数乍疏，是又二脉之偶见者也。", "17465": "脉无根有两说", "17466": "女人脉法", "17467": "阴博阳别谓之有子。（谓尺中之阴脉搏大，与寸部之阳部迥别者，乃有子也。）阴虚阳搏谓之崩。（阴虚血衰于下，则阳火上亢矣，血为火迫不得安其位，乃为崩漏之疾。）手少阴脉动甚者妊子也。（手少阴者心脉也，动甚者形如豆粒，急数有力也。心主血，血旺乃能成胎，心脉动甚而旺之象，故当妊子）", "17468": "何以知怀子之且生也，身有病而无邪脉也。（有病，如腹痛拘急之类。无邪脉，谓无病脉也。）妇人欲生，其脉离经，夜半觉，日中则生也。（离经者谓离于常经之脉，如昨小今大，昨涩今滑，昨浮今沉之类。夜半觉，日中生子者，子午相冲也。）", "17469": "小儿脉法", "17470": "小儿五岁以下，未可诊寸关尺，惟看男左女右虎口食指第一节寅位，为风关，脉见易治。第二节卯位，为气关，脉见为病深。第三节辰位，为命关，脉见为命危。紫脉为热，红脉伤寒，青脉惊风，白脉疳疾，黄脉隐隐为常侯也，黑脉者多危，脉纹入掌为内钩，纹弯里为风寒，纹湾外为食积。", "17471": "岐伯曰：察九侯七诊（九候注见前）。独小者病，独大者病，独疾者病，独迟者病，独热者病，独寒者病，独陷下者病。（些言九候之中有独见之脉，而与他部不同，即按其部而知其病之所在也。七者之中，「即言独疾，则主热矣，即言独迟，则主寒矣，而又言独寒独热者何也？必于阴部得沉微迟涩之脉，故又言独寒也；必于阴部得洪实滑数之脉，故又言独热也；独陷下者沉伏而不起者也。）形肉已脱，九候虽调犹死。（形肉脱去，大肉尽运也，脾主肌肉，为五脏之本，未有脾气脱而能生者，虽九候之中无独见之七诊，然终不免于死之矣。）", "17472": "七诊虽见，九候皆从者不死。（从顺也，谓脉顺四时之令，合五脏之常，故与病症为顺也。既得顺候，虽有独大独小等脉，不至于死也。）", "17473": "必先问明然后诊脉", "17474": "《素问·征四失篇》曰：「诊病不问其始，忧患饮食之失节，起居之过度，或伤于毒，不先言此，而卒持寸口，妄言作名，为粗所穷，何病能中。」此言不问其症之所由起，先与切脉，未免模糊揣度，必不能切中病情者矣。", "17475": "李士材曰，古之神圣，未尝不以望闻问切四者互相参者审察病情，然必先望其气色，次则闻其音声，次则问其病源，次则诊其脉状，此先后之次第也。近世医者既自附于知脉，而病家亦欲试其本领，遂绝口不言，惟伸手就诊，而医者即强为揣摩，若揣摩偶合，则信为神奇。揣摩不合则薄为愚脉。噫！嘻！此《内经》所谓「妄言作名，为粗所穷。」如是而欲拯危起殆，何异欲入其室而反闭门也！王海藏云：「病人拱默，惟令切脉，试其知否。夫热则脉数，寒则脉迟，实则有力，虚则无力，此可以脉知也。然一脉管数十症，得病之由不可以脉知也，如伤食可以脉知也，而所伤何物，岂能以脉知哉？故医者不可不问其由，病者不可不说其故。」苏东坡云：「我有病状必尽告医者，使其胸中了然，然后诊脉，则疑似不能惑也，我求愈疾而已，岂以困医为事哉？」若二公之言，可以发愚蒙之聋聩矣。", "17476": "持脉有道", "17477": "《素问·脉要精微论》曰：「持脉有道，虚静为保。」此言切脉之道，贵于精诚，嫌其扰乱，故必心虚而无他想，身静而不言动，然后可以察脉之微，而不失病情也。保者不失也，若躁动不安，瞻视不定，轻言谈笑，乱说是非，不惟不能得脉中之巧，适足为旁观者，鄙且笑也。今世诊者，大类如此，可发一笑！", "17478": "脉以胃气为主", "17479": "脉以胃气为主，有胃则生，无胃则死。脉经所谓不大不小，不长不短，不滑不涩，不浮不沉，不疾不徐，应手中和，悠悠扬扬，难以名状者，此胃脉也。二十八脉中缓脉即胃脉也，六脉皆有胃气，不可以脾胃一部为胃脉，盖从容和缓乃谷气，即人之元气是也。人之谷气，贯乎一身，无地不有，故不论何症何脉，但得从容和缓即为有胃气，此生脉也。此详《脉经》缓脉中，为诊家第一大关键，不可不知，故特表而出之。", "17480": "又东垣脉贵有神之说，不论病之轻重与脉之大小，但得脉有力即为无害，有力即有神也，此亦为医中要领。此即《内经》所谓有胃气也，故亦表之。", "17481": "此论脉之大要也，若夫议论精详，则唯于李士材《诊家正眼》、李濒湖《脉学》、张景岳《脉神章》诸书潜心求之，则自得矣，不赘。余纂有《脉法大成》一部，嗣当续刻。", "17482": "医要明白阴阳表里寒热虚实八字，病虽万变百出，而其实总不离此八字，以人不病阴即病阳，不病表即病里，不病寒即病热，不病实即病虚也，然表与热皆属阳，里与寒皆属阴。八字之中又只阴阳虚实四字足以尽之。然阳有阳实亦有阳虚，阴有阴实亦有阴虚，而虚实二字又为百病之会归，八字之纲领也。诸书辨之甚明，无不随症言之。惟张景岳《传忠录》以此八字分篇立论，最为详细。学医者尤当细看，俾方寸先有定见，庶临时认症不错耳。然虚实二字尤为要紧，比惟精于脉理者可与言也。", "17483": "张景岳曰：凡诊病施治必须先审阴阳，乃为医道之纲领，阴阳无谬，治焉有差？医道虽繁，而可以一言蔽之，曰阴阳而已。故证有阴阳，脉有阴阳，药有阴阳。以症而言则表为阳，里为阴。热为阳，寒为阴。上为阳，下为阴。气为阳，血为阴。动为阳，静为阴。多言者阳，无声者为阴。喜明者为阳，欲暗者为阴。阳微者不能呼，阴微者不能吸。阳病者不能俯，阴病者不能仰。以脉而言则浮大滑数之类皆阳也，沉微细涩之类皆阴也。以药而言则升散者为阳，敛降者为阴。辛热者为阳，苦寒者为阴。行气分者为阳，行血分者为阴。性动而走者为阳，性静而守者为阴。此皆医中之大法。至于阴中复有阳，阳中复有阴。疑似之间辨须的确，此而不识，极易差讹，是又最为紧要，然总不离乎前之数者。但两气相兼，则此少彼多，其中便有变化，一皆以理测之，自有显然可见者，若阳有余，而更施阳治，则阳愈炽，阴愈消。阳不足，而更用阴方，则阴愈盛，而阳斯灭矣。设能征明阴阳，则医理虽玄，思过半矣。", "17484": "凡人之病非寒即热，然寒热之真者易知，假者难辩。最重在假寒假热。所谓大实有羸状，至虚有盛侯是也。然真热假寒之症少，而真寒假热之症多耳。此「类白虎症」、「假白虎症」所当辨也。白虎汤石膏、知母，必有实热方可用，或有血虚心寒，脾虚发热及阴盛格阳、面赤烦躁，类白虎等证，误投之不可救也。盖血实则身凉，血虚则身热，此以饥饱劳役伤其阴，血虚阳独盛，故肌热烦渴与白虎证无异，但真白虎证得之外感，实热内盛，故脉洪大而长，按之有力。类白虎证得之内伤，血虚发热脉洪大而无力。内经所谓脉虚血虚是也，以脉之有力无力为辩，庶不贻误。若不知脉，误服白虎汤必毙，故用当归补血汤自愈，此理最微，宜细心体察。", "17485": "又按阴盛格阳，阳盛格阴，二症至为难辨。盖阴盛极而格阳于外，外热而内寒。阳盛极而格阴于外，外冷而内热。经所谓重阴必阳，重阳必阴，重寒必热，重热则寒是也。固以脉之有力无力为辨。又当于小便分之，便清者外虽燥热而中心寒，便赤者外虽厥冷而内必热，再看口中燥润及舌苔浅深，盖舌为心苗，应南方火邪，在表则未生苔，邪入里津液搏结则生苔而滑。苔白者丹田有热、胸中有寒，邪在半表半里也。热入渐深则燥而涩，热聚于胃则黄，宜承气及白虎。若热病口干舌黑乃肾水刑于心火，热益深而病笃矣，然亦有苔黑属寒者，舌无芒刺，口有津液也，又当用温补之剂。尤宜细辨。张景岳《传忠录》有寒热真假辨，李士材《医宗必读》有《疑似之间须辨论》，并《伤寒有阴症似阳阳症似阴辨》，皆当参看。又有上热下寒，用八味冷饮以治之法，此即《内经》热因寒用，不可不知者也。", "17486": "舌苔舌黑虽云火症，然实火虚火皆能为之，凡治此者当察脉症，以虚实为主，而再以辨色之法参之，庶可无误。盖实热之黑必兼红紫，干渴或多芒刺。若沉黑少红而带润滑者，本非实热症也。若其六脉细弱而形困气倦，则又最为虚候，是必寒水乘心，火不归源之病，此不救本，而但知治标，则万无一生矣。若阴虚火盛而兼有表邪未解者，宜补阴益气煎之类，兼表里而治之。若形气俱不足，寒水乘心而虚阳不敛者，必用理阴煎、理中汤或大补元煎之类，以单救其里，自可保其无虞，此治虚火之法也。《薛氏医案·金镜录》有三十六舌，李士材《诊家正眼》有舌诊一条，所当参看。", "17487": "李士材曰：「古称五劳，七伤、六极、二十二蒸，症状繁多，令人眩感，但能明先天后天根本之治，无不痊安。」此简而不繁，约而无漏者也。夫人之虚非气即血、五藏，六府莫能外焉。然血之源头在乎肾水，为天一之元，而人资之以为始者，故曰先天。气之源头在乎脾土，为万物之母，而人资之以为生者，故曰后天。二藏安和则百脉受调，二藏虚伪则千疴并起。至哉斯言！可谓后学司命之指南也。", "17488": "李士材曰，虚痨之症扶脾保肺两不可缺，然脾之性喜温喜燥，而温燥之剂不利于肺，肺之为性喜凉喜润，而凉润之剂不利于扶脾。两者并列而论脾有生肺之能，肺无扶脾之力，故曰土旺而金生，勿拘拘乎保肺，泻火之亢以全阴气，壮水之主以镇阳光，法当并行。然泻火之品多寒而损阳气，壮水之剂多平而养阴血，两者并列而论，苦寒过投，将有败胃之忧，甘平恒用却无伤中之患，故曰水壮而火自熄，勿亟亟于寒凉。症如烦渴喘呼，脉则数大有力，当润肺为主，而扶脾佐之。症如食少善泄，脉则细数无力，当扶脾为主而保肺佐之。甚则保肺之剂不和于脾，当尽去之，却宜补土之母，庶可冀其回春，全在明辨其症之何如，变通以治之可也。张景岳曰，朋虚一症邪火偏胜，缘真水之不足也，故其为病或为烦渴，或为骨蒸，或为咳血吐血，或为淋浊遗泄，此虽明是火症，而非邪热实热之比。盖实热之火其来暴，必有感触之故，虚热之火其来徐，必有积损之因，此虚火实火之大有不同也。凡治火者，实热之火可以寒胜，可以水折，所谓热者寒之也；虚热之火不可以寒胜，所谓劳者温之也。何也？盖虚火因其无水，只当补水以配火，则阴阳得平，而病自可愈。若欲去火以覆水，则既亏之水未必可复，而并火去之，岂不阴阳两败乎！且苦寒之物绝无升腾之生气，而欲补其虚无是理也。故余之治此，必以甘平之剂专补真阴，此未必即愈，自可无害，然后察其可乘，或暂一清解，或渐加温润，必使生气渐来，庶乎脾可健则热可退，肺可润则嗽渐宁，方是渐复之佳兆，多有得生者。若但知知、柏为补阴，则愈败其肾，而致泄泻食减，必速其殆矣！", "17489": "李士材曰，或问血虚自应补血，专以气药为主，得无左乎？答曰：血虚应投血药本为正法，但专用多用中州有碍，至于以气药为主似乎相左，不知《素问》云，无阳则阴无以为生。仲景曰，身热亡血，身凉脉凝，血虚，并加人参，盖血脱者须益气，为血不自生，须得阳和之药乃生，阳生而阴长也，若只用血药，则血无由而生矣。东垣云，人参甘温补脾，脾气旺则四藏之气皆旺，精自生而形自盛也。白飞霞云，人参多服，回元气于无何有之乡。凡病后气虚及肺虚喘嗽者，并宜用之，若气虚有火宜与麦冬同服。杨起云，人参功载本草，人所共知，古方治肺寒以温肺汤，肺热以清肺汤，中满分消汤，血虚养营汤皆用人参。庸医每谓人参不可轻用，诚哉庸也，自本经以至诸家谆谆言之，以气药有生血之功，血药无益气之理，可谓详切著明，奈何人不悟耶！", "17490": "张景岳曰，万事皆有本，而治病之法，尤惟求本为首务，所谓本者惟一而无两也。盖或因外感者，本于表也，或因内伤者本于里也，或病热者本于火也，或病冷者本于寒也，邪有余者本于实也，正不足者本于虚也。但察其因何而起，起病之因便是病根，万病之本只此表里寒热虚实六者而已，知此六者则表有表症，里有里症，寒热虚实无不皆然，六者相为对待，原冰炭不同，辨之亦异。凡初病不即治，及有误治不愈者，必致病变日多，无不皆从病本生出，最不可逐件猜摸，短觑目前，头痛治头，脚痛治脚。经曰：「众脉不见，众凶不闻，外内相得，无以形先。」是诚求本之至要也。苟不知此，必庸流耳。故明者独知所因，直取其本，则所生诸病无不随本皆退矣。至若六者之中，多有兼见而病者，则其中亦自有源有流，无弗可察，然惟于虚实二字总贯乎前之四者，尤为紧要而当辨也。盖虚者本平，元气实者由乎邪气，元气若虚，则虽有邪气不可攻，而邪不能解则又不可不攻者，此处最难下手，但当察其能胜攻与不能胜攻，或宜以攻为补，或宜以补为攻，而得其补泻于微甚可否之间，斯尽善矣。且常见有偶感微疾者，病原不甚，斯时也，但知拔本，则一药可愈，而庸者值之非痰曰痰，非火曰火。四路兜拿茫无真见，而反遗其本，多致轻者日重，重者日危，而殃人祸人，总在不知本末耳。甚矣！医之贵神，神奚远哉？此提纲挈领医之最上乘法也，读者当三复焉。", "17491": "凡大寒大热之药，必要有凭有据而后可用，切不可以意度之。药所以补偏而救弊也。寒药所以治热，热药所以治寒，中病即止，勿过用也。若夫大苦大寒与大燥大热之药、尤宜斟酌慎用。如热病必要有热症热脉，寒病必要有寒症，寒脉，内外相符，确凿可据，而后始可用以治之，自无不瘳。若无确凭确据，而但以意揣度之，则害人不浅。以大寒大热之药，其力最悍极易坏事，苟非脉与症对，皆有确凭确据，则断不可轻用，此医中之最要紧语也。独怪夫世之不读书者，每执一已偏见，私心自用，或好寒凉，知柏硝黄任用；或好燥热，桂附硫黄妄投，造次孟浪，欲其不杀人也难矣，故再三致戒焉。", "17492": "凡药下咽必有气味，气味与人相投，服之安然即对症药也。否即参茸至贵之药，一不相投，即知中止，切不可强然。亦有初服不相安及至三四帖后如水融乳者，此又在认证之真确耳。余昔在兴安治一肾气上逆症人，多误认为怔忡，十三年疗治不愈。余诊脉后，开以八仙长寿方，加砂仁、沉香纳气归肾，服一帖不相安，余限以连服四十贴自愈，后果然。此在认症之确耳。", "17493": "治外感暴病不难，而治内伤则最难也，以外感暴病得之旦夕，即可旦夕去之，如时文中之单句题，人人可以为之者也。若内伤虚劳，积之有素，非一朝一夕而来，亦非可以一朝一夕而去。如时文中之性理题，最精最细，非平日博极群书，细意体察及精于脉理者，断不能也。彼时医庸医乌足以知之，然又非信任得专，从容调治，不能为之力也。古人医案中有服至一二百帖而后愈者，又有治至三五年而后愈者，此类是也。今人好称手到病除，不知一二贴即愈者，此惟轻病暴病则可耳，若内伤与重病岂可以此言哉，故一概欲图速效者，不可与言医。", "17494": "伤寒阳经与阳症不同，阳经者邪在表也，阳症者热在里也，若内无实热脉候，而以阳经作阳症，妄用寒凉治其火，因致外内合邪而不可解者必死。", "17495": "小儿痘疹发热，此其正候，盖不发热，则毒不能透，凡其蒸热之力，即元气之力，故自起至化，自收至靥，无不赖此热力为之主，是诚痘疹之用神，必不可少，亦不必疑者也。惟是热甚而毒甚者，则不得不清火以解其毒，然必有内热真火脉症，方可治以清凉。此不过数十中之一二耳，如无内热而但有外热，此是痘家正候，必不可攻热，以拔元气之力，以伤脾肾之源。奈近代痘科，全不知此，但见发热，则无论虚实，开口止知解毒，动手止知寒凉，多致伤脾而饮食日减，及靥时泄泻而毙者，皆其类也。此误最多，不可不察。", "17496": "妇人经脉滞逆，或过期不至，总由冲任不足而然，若不培养血气，而止知通经逐瘀，则血以日涸，而崩漏血枯等症无所不至矣。", "17497": "脉虚证热，本非真火，若作热治而肆用寒凉，则轻者必重，重者必死。", "17498": "（案1）钱，左，三十一。三疟后风邪入络，口眼歪斜，现在已得平复。风势走窜经络，肢麻筋掣，脘痛腹鸣，头蒙发眩，燔灼艰寐，脉见细弦。防成风瘫。治以和养。", "17499": "（案2）孙，左，廿六。寒热后风湿入络，肢骱酸痛甚于腰膝，当脘亦似寒似痛，脉见沉弦。治以疏和。"});